create table #lt_DisputedClass
(
	IcCode      	numeric (5,  0) NOT NULL,
	Name		varchar (40) 	NOT NULL

)

Insert #lt_DisputedClass
	Select ICCode, Name from SheerazDBV1.Dbo.ItemClass
	where name in (SElect name from SheerazDBV1.Dbo.ItemClass
			group by name having count(name) > 1)
	order by name

INSERT INTO TraderDBV3.Dbo.ItemClass (ICCode, Name)
	SELECT CONVERT(SmallInt, ICCode) as ICCode, Name 
	FROM SheerazDBV1.Dbo.ItemClass
	WHERE ICCode NOT IN (Select ICCODE from #lt_DisputedClass)

INSERT INTO TraderDBV3.Dbo.ItemClass (ICCode, Name)
