-- PostServiceOrder_Service_Sale (last defined by script catalog)
CREATE   PROCEDURE DBO.PostServiceOrder_Service_Sale @ServiceOCode INT, @UserCode SMALLINT
AS

DECLARE @errcode INT, @ServiceInvCode INT , @SaleInvCode INT, @RaiseProfSale CHAR(1)

SET @RaiseProfSale = DBO.Fn_GetPreference('RaiseProformaSaleOnServiceOrderPosting')
IF @RaiseProfSale IS NULL
	SET @RaiseProfSale = 'N'

IF @ServiceOCode <> 0
BEGIN
	SET @errcode = 0
	EXECUTE @errcode = DBO.SP_Generate_Svc_For_ServiceOrder @ServiceOCode, @UserCode, @ServiceInvCode OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Generating Service Invoice', 16, 1)
		RETURN -1
	END

	IF @RaiseProfSale='Y'	
	BEGIN
		SET @errcode = 0
		EXECUTE @errcode = DBO.SP_Generate_Proforamsales_For_ServiceOrder @ServiceOCode, @UserCode, @SaleInvCode OUTPUT
		IF @@ERROR <> 0 OR @errcode <> 0
		BEGIN
			RaisError('Problem while Generating Proforma Sale Invoice', 16, 1)
			RETURN -1
		END
	END

	UPDATE IssueReqHeader 
	SET Posted='Y', PostedBy=@UserCode, PostDate=GETDATE()
	WHERE ServiceOCode=@ServiceOCode

	UPDATE ServiceOHeader 
	SET Posted='Y', PostDate=GetDate(), PostedBy=@UserCode, SaleInvCode=@SaleInvCode, ServiceInvCode=@ServiceInvCode
	WHERE ServiceOCode=@ServiceOCode AND Posted='N'
END
IF @@ERROR = 0 
BEGIN
	RETURN 0
END
ELSE
BEGIN
	RETURN -1
END
GO

