	Select 1, acccode, case when Currbalance > 0 then Abs(currbalance) else 0 end,
			   case when Currbalance < 0 then Abs(Currbalance) else 0 end 
		From SheerazDBV1.Dbo.Accounts
		Where Currbalance <> 0 and AccCode >= 100

Declare @bal Numeric(15, 5)

Select @bal = (Select Sum(Debit - Credit) from TraderDBV3.Dbo.gldetail)

