-- SP_AbsoluteOpeningBalance (last defined by script catalog)
CREATE PROCEDURE SP_AbsoluteOpeningBalance @AccCode INT, @Bal NUMERIC(15, 5) OUTPUT
AS
/*
Author: 
	M.Azhar
Purpose:
	This procedure is used to compute absolute balance of an individual account 
	if it is not included in any summary account and if account is included in
	any summary account then return combined balance of all accounts included
	in taht summary account

PreProcessing:
	First of all it executes SP_VirtualGL (Accounting repository) to accomodate 
	all uptodate posted transactions
*/
BEGIN
	EXECUTE SP_VirtualGL 'A'
	
	SET @BAL = 0

	SET @BAL = 
		ISNULL(
			(SELECT ISNULL(SUM(DEBIT - CREDIT), 0) 
			FROM VIRTUALGL 
			WHERE AccCode IN 
				(SELECT AccCode FROM udf_GetSummaryAccountList(@AccCode)))
		, 0)
END
GO

-- sp_AccountOpeningBalance (last defined by script catalog)
CREATE  PROCEDURE sp_AccountOpeningBalance @al_AccCode INT, @ad_edate datetime, @af_openbalance NUMERIC(15,5) out AS 
/*
	Two Parameters:-
		1)	ad_edate datetime 	(date upto which the balance is required)
		2)	af_openbalance float 	(output variable returns the balance to caller)
*/
/******** Collecting the result and assigning to the relevent reference variable *********/
select @af_openbalance = isnull( ( select sum(debit) - sum(credit)
		 	  from   VirtualGL WHERE AccCode = @al_AccCode AND Date < @ad_edate 
			), 0)
GO

-- sp_AccountsBalance (last defined by script catalog)

/****** Object:  Stored Procedure dbo.sp_AccountsBalance    Script Date: 4/23/02 4:29:59 PM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsBalance    Script Date: 4/8/02 6:26:06 PM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsBalance    Script Date: 3/6/02 3:39:36 PM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsBalance    Script Date: 7/20/01 6:52:01 PM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsBalance    Script Date: 6/28/00 5:23:52 PM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsBalance    Script Date: 5/19/00 9:47:28 AM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsBalance    Script Date: 4/19/00 1:21:26 PM ******/
CREATE PROCEDURE sp_AccountsBalance @ad_Date DateTime AS

/* Declaration of local Variables to be used in the script later */

DECLARE @ln_purchaseacc NUMERIC(5, 0)
DECLARE @ln_cashacc NUMERIC(5, 0)
DECLARE @ln_equityacc NUMERIC(5, 0)
DECLARE @ln_salesacc NUMERIC(5, 0)
DECLARE @ln_salesretacc NUMERIC(5, 0)
DECLARE @ln_purchaseretacc NUMERIC(5, 0)
DECLARE @ln_revfromservice NUMERIC(5, 0)
DECLARE @ln_salestaxacc NUMERIC(5, 0)

/* Fetching local Variables values to be used in the script later */

SELECT @ln_purchaseacc     = (SELECT code FROM global WHERE name = 'GT_PurchaseAccount')
SELECT @ln_cashacc         = (SELECT code FROM global WHERE name = 'GT_CashACC')
SELECT @ln_equityacc	   = (SELECT code FROM global WHERE name = 'GT_EquityACC')
SELECT @ln_salesacc        = (SELECT code FROM global WHERE name = 'GT_SalesACC')
SELECT @ln_salesretacc     = (SELECT code FROM global WHERE name = 'GT_SalesReturnACC')
SELECT @ln_purchaseretacc  = (SELECT code FROM global WHERE name = 'GT_PurchaseReturnsAccount')
SELECT @ln_revfromservice  = (SELECT code FROM global WHERE name = 'GT_RevenueFromServices')
SELECT @ln_salestaxacc	   = (SELECT code FROM global WHERE name = 'GT_AdvanceSalesTaxACC')

/* Declaration of Temporary Table to be used for records to be returned by this script */

CREATE TABLE #lt_Accounts
(
	acccode      NUMERIC(5,  0) NOT NULL,
	currbalance  NUMERIC(15, 2) NOT NULL 
)

INSERT #lt_Accounts
SELECT acccode, 0
FROM   accounts

/**********************************************************************/
/******************* Purchase Module's effects ************************/
/**********************************************************************/

CREATE TABLE #lt_AccEntries
(
	acccode      	NUMERIC(5,  0) NOT NULL,
	SaleTax		NUMERIC(15, 2) NOT NULL,
	Gross		NUMERIC(15, 2) NOT NULL
)

insert  #lt_AccEntries
select  Case purledger.PurCatCode
		when 3 THEN @ln_equityacc      /* Opening Purchase  */
		else   purledger.suppcode
	end,
	SaleTax=ROUND(
		SUM((purdetail.looseqty + purdetail.packqty + purdetail.bonusqty) *
			purdetail.unitsalestax) +
		SUM(ROUND((purdetail.looseqty + purdetail.packqty) * purdetail.purprice * 
			(1 - (.01 * purdetail.discperc)) * purdetail.gstperc * .01, 2)) +
		ROUND((SUM(((purdetail.looseqty + purdetail.packqty) * purdetail.purprice) * 
			(1 - (.01 * purdetail.discperc))) * 
			(1- (.01 * purledger.discperc)) - purledger.flatdisc) * 
			(purledger.invgstperc1 * .01), 2), 0),
	Gross=  ROUND(SUM((purdetail.looseqty + purdetail.packqty) * purdetail.purprice * 
			(1 - (.01 * purdetail.discperc))) * (1- (.01 * purledger.discperc)) + 
			purledger.misccharges + purledger.salestax - purledger.flatdisc, 0)

from     purledger,	 
	 purdetail 

where    purledger.date <= @ad_Date and
	 purledger.posted = 'Y' and
	 purledger.purinvcode = purdetail.purinvcode 

group by purledger.purinvcode,
	 purledger.purcatcode,
	 purledger.date,
	 purledger.discperc,
	 purledger.misccharges,
	 purledger.salestax,
	 purledger.flatdisc,	
	 purledger.invgstperc1,
	 purledger.suppcode 

/********************** Debit SalesTax Receiveable Account A/c) ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
		(Select IsNull(sum(saletax), 0) from #lt_AccEntries)
where  #lt_accounts.acccode = @ln_salestaxacc

/********************** Debit PurchaseAccount (Expense A/c) ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
		(Select IsNull(sum(Gross), 0) from #lt_AccEntries)
where  #lt_accounts.acccode = @ln_purchaseacc

/******************Credit supplier/equity account********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - 
		(Select sum(ISNULL(#lt_AccEntries.Gross+#lt_AccEntries.SaleTax, 0))
		from #lt_AccEntries 
		where #lt_AccEntries.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_AccEntries
where  #lt_accounts.acccode = #lt_AccEntries.acccode 

Delete #lt_AccEntries

/**********************************************************************/
/**************** Purchase Return Module's Effects*********************/
/**********************************************************************/

insert  #lt_AccEntries
select  Case prledger.PRCatCode
		when 6 THEN @ln_equityacc   /* Opening Purchase Return */
		else   prledger.suppcode    /* Credit Purhase Return */
	end,
	SaleTax=ROUND(
		SUM((prdetail.looseqty + prdetail.bonusqty) * prdetail.unitsalestax) +
		SUM(ROUND(prdetail.looseqty * prdetail.prprice * 
			(1 - (.01 * prdetail.discperc)) * prdetail.gstperc * .01, 2)) +
		ROUND((SUM((prdetail.looseqty * prdetail.prprice) * 
			(1 - (.01 * prdetail.discperc))) * (1- (.01 * prledger.discperc)) -
			prledger.flatdisc) * (prledger.invgstperc1 * .01), 2), 0),
	Gross  =ROUND(SUM((prdetail.looseqty * prdetail.prprice) * 
			(1 - (.01 * prdetail.discperc))) * (1- (.01 * prledger.discperc)) + 
			prledger.misccharges + prledger.salestax - prledger.flatdisc, 0)

from     prledger,	 
	 prdetail		

where    prledger.date <= @ad_Date and
	 prledger.posted = 'Y' and
	 prledger.prinvcode = prdetail.prinvcode

group by prledger.prinvcode,
	 prledger.suppcode, 
	 prledger.prcatcode,
	 prledger.date,
	 prledger.discperc,
	 prledger.misccharges,
	 prledger.salestax,
	 prledger.invgstperc1,
	 prledger.flatdisc		

/**********************Credit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - 
		(Select IsNull(sum(saletax), 0) from #lt_AccEntries)
where  #lt_accounts.acccode = @ln_salestaxacc

/***************************Credit Purchase Return Account****************************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - 
		(Select IsNull(sum(Gross), 0) from #lt_AccEntries)
where  #lt_accounts.acccode = @ln_purchaseretacc

/******************Debit supplier/equity account********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
		(Select sum(ISNULL(#lt_AccEntries.Gross+#lt_AccEntries.SaleTax, 0))
		from #lt_AccEntries where #lt_AccEntries.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_AccEntries
where  #lt_accounts.acccode = #lt_AccEntries.acccode 

Delete #lt_AccEntries

/**********************************************************************/
/***************************** Sale ***********************************/
/**********************************************************************/

insert  #lt_AccEntries
select  Case saleledger.saleCatCode
		when 1 THEN @ln_cashacc     /* Cash Sale */
		when 3 THEN @ln_cashacc     /* Cash Sale */
		else   saleledger.custcode  /* Credit Sale */
	end,
	SaleTax=Round(
		SUM(saledetail.looseqty * saledetail.unitsalestax) + 
		SUM(ROUND( (saledetail.looseqty * 
			(saledetail.saleprice - saledetail.itemflatdisc)) *
			(1 - (.01 * saledetail.discperc)) * saledetail.gstperc * .01, 2)) +
		ROUND( (SUM((saledetail.looseqty * 
			(saledetail.saleprice - saledetail.itemflatdisc)) *
			(1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) -
			saleledger.flatdisc) * (saleledger.invgstperc1 * .01), 2), 0),
	Gross=Round(
		SUM((saledetail.looseqty*(saledetail.saleprice - saledetail.itemflatdisc)) *
			(1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + 
			saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0)

from     saleledger,	 
	 saledetail		

where    saleledger.date <= @ad_Date and
	 saleledger.posted = 'Y' and
	 saleledger.saleinvcode = saledetail.saleinvcode 

group by saleledger.saleinvcode,
	 saleledger.custcode, 
	 saleledger.salecatcode,
	 saleledger.date,
	 saleledger.discperc,
	 saleledger.misccharges,
	 saleledger.salestax,
	 saleledger.invgstperc1,
	 saleledger.flatdisc		

/**********************Credit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - 
		(Select IsNull(sum(saletax), 0) from #lt_AccEntries)
where  #lt_accounts.acccode = @ln_salestaxacc

/**********************Credit Sales Account***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - 
		(Select IsNull(sum(Gross), 0) from #lt_AccEntries)
where  #lt_accounts.acccode = @ln_salesacc

/******************Debit customer/cash/equity account********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
		(Select sum(ISNULL(#lt_AccEntries.Gross+#lt_AccEntries.SaleTax, 0))
		from #lt_AccEntries 
		where #lt_AccEntries.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_AccEntries
where  #lt_accounts.acccode = #lt_AccEntries.acccode 

DELETE #lt_AccEntries

/**********************************************************************/
/**************************** Sale Return ********************************/
/**********************************************************************/

insert  #lt_AccEntries
select  Case srledger.srCatCode
		when 6 THEN @ln_cashacc     /* Cash Sale Return*/
		when 8 THEN @ln_cashacc     /* Cash Sale Return*/
		else   srledger.custcode    /* Credit Sale Return*/
	end,
	SaleTax=ROUND(
		SUM(srdetail.looseqty * srdetail.unitsalestax) + 
		SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
		    (1 - (.01 * srdetail.discperc)) * srdetail.gstperc * .01, 2)) +
		ROUND( (sum( (srdetail.looseqty * srdetail.srprice) *
		    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) - 
		srledger.flatdisc) * (srledger.invgstperc1 * .01), 2), 0),
	 Gross= Round( sum( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) + srledger.misccharges + srledger.salestax - srledger.flatdisc, 0)


from     srledger,	 
	 srdetail		

where    srledger.date <= @ad_Date and
	 srledger.posted = 'Y' and
	 srledger.srinvcode = srdetail.srinvcode 

group by srledger.srinvcode,
	 srledger.custcode, 
	 srledger.srcatcode,
	 srledger.date,
	 srledger.discperc,
	 srledger.misccharges,
	 srledger.salestax,
	 srledger.invgstperc1,
	 srledger.flatdisc

/**********************Debit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
		(Select IsNull(sum(saletax), 0) from #lt_AccEntries)
where  #lt_accounts.acccode = @ln_salestaxacc

/**********************Debit Sales Return ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
		(Select IsNull(sum(Gross), 0) from #lt_AccEntries) 
where  #lt_accounts.acccode = @ln_salesretacc

/******************credit customer/cash/equity account********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - 
		(Select sum(ISNULL(#lt_AccEntries.Gross+#lt_AccEntries.SaleTax, 0)) 
		from #lt_AccEntries where #lt_AccEntries.acccode = #lt_accounts.acccode)
from   #lt_accounts, #lt_AccEntries
where  #lt_accounts.acccode = #lt_AccEntries.acccode 

DELETE #lt_AccEntries

/**********************************************************************/
/**************************** Accounting Vouchers ************************/
/**********************************************************************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(gldetail.debit - gldetail.credit), 0) from glheader, gldetail where glheader.date <= @ad_Date and glheader.posted = 'Y' and glheader.glvochcode =  gldetail.glvochcode and gldetail.acccode = #lt_accounts.acccode  ) 
from   #lt_accounts
where  #lt_accounts.acccode IN (Select distinct acccode from gldetail) 


/**********************************************************************/
/********************* Bills Receivables/Payables **********************/
/**********************************************************************/

/* Credit the Customer A/c for B/R and Debit the Supplier A/c for B/P */
/* that is decrease the balance for Customer or Supplier */

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
	(Select IsNull(sum(Case NoteCatCode When 1 Then Amount * -1 Else Notes.Amount      End), 0)
		from Notes 
		where Notes.postdate <= @ad_Date and Notes.posted = 'Y' and 
		Notes.acccode = #lt_accounts.acccode )
from   #lt_accounts
where  #lt_accounts.acccode IN (Select distinct acccode from Notes ) 

/* Credit the Bank A/c for B/P and Debit the Bank A/c for B/R */
/* that is Increase the balance for Customer and Decrease for Supplier */

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
	(Select IsNull(sum(Case NoteCatCode When 1 Then Amount    Else Notes.Amount * -1   End), 0)
		from Notes 
		where Notes.postdate <= @ad_Date and Notes.posted = 'Y' and 
		Notes.bankacccode = #lt_accounts.acccode ) 
from   #lt_accounts
where  #lt_accounts.acccode IN (Select distinct bankacccode from Notes ) 


/**********************************************************************/
/************************** Sale of Services **************************/
/**********************************************************************/

insert  #lt_AccEntriesselect  Case h.serviceCatCode
	    When 10 THEN @ln_cashacc   /* Retail Service Sale (Cash) */
	    When 12 THEN @ln_cashacc   /* Whole Cash Service Sale (Immediate Cash) */
	    Else   	 h.custcode    /* Credit Service Sale */
	End,
	SaleTax=0.00,
	Gross=IsNull(Round(sum( (isnull(d.price, 0) * 
		(1 - (.01 * isnull(d.discperc, 0)))) * 
		(1- (.01 * h.discperc)) + isnull(h.misccharges,0) - 
		isnull(h.flatdisc, 0)), 0), 0)

from     serviceheader h,	 
	 servicedetail d

where    h.date <= @ad_Date and
	 h.posted = 'Y' and
	 h.serviceinvcode = d.serviceinvcode 

group by h.serviceinvcode,
	 h.custcode, 
	 h.servicecatcode,
	 h.date,
	 h.discperc,
	 h.misccharges,
	 h.flatdisc

/*******************Credit Revenue From Services A/c ********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - 
		(Select IsNull(sum(Gross), 0) from #lt_AccEntries)
where  #lt_accounts.acccode = @ln_revfromservice

/******************Debit customer/cash account********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
	(Select IsNull(sum(#lt_AccEntries.Gross), 0) 
	from #lt_AccEntries 
	where #lt_AccEntries.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_AccEntries
where  #lt_accounts.acccode = #lt_AccEntries.acccode 

Delete #lt_AccEntries

/**********************************************************************/
/******************* Sale Return of Services **************************/
/**********************************************************************/

insert  #lt_AccEntriesselect  Case h.serviceRCatCode
	    When 13 THEN @ln_cashacc   /* Retail Service Sale Return (Cash) */
	    When 15 THEN @ln_cashacc   /* Whole Cash Service Sale Return (Immediate Cash) */
	    Else   	 h.custcode    /* Credit Service Sale Return */
	End,
	SaleTax=0.00,
	Gross=IsNull(Round(sum( (isnull(d.serviceprice, 0) * 
		(1 - (.01 * isnull(d.discperc, 0)))) * 
		(1- (.01 * h.discperc)) + isnull(h.misccharges,0) - 
		isnull(h.flatdisc, 0)), 0), 0)

from     serviceRheader h,	 
	 serviceRdetail d

where    h.date <= @ad_Date and
	 h.posted = 'Y' and
	 h.serviceRinvcode = d.serviceRinvcode 

group by h.serviceRinvcode,
	 h.custcode, 
	 h.serviceRcatcode,
	 h.date,
	 h.discperc,
	 h.misccharges,
	 h.flatdisc

/************* Debit Revenue From Services A/c (Reverse of Services Sales) ********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
		(Select IsNull(sum(Gross), 0) from #lt_AccEntries)
where  #lt_accounts.acccode = @ln_revfromservice

/**************** Credit customer/cash account (Reverse of Services Sales) *******************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance -
		(Select IsNull(sum(#lt_AccEntries.Gross), 0) 
		from #lt_AccEntries where #lt_AccEntries.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_AccEntries
where  #lt_accounts.acccode = #lt_AccEntries.acccode 

DROP TABLE #lt_AccEntries

/**************************Final Housing Keeping *********************/

Delete ReportData

Insert ReportData (name1, name2, value1, code1)
	Select accounts.name, subaccounts.name, #lt_Accounts.currbalance, accounts.acccode
	From   	accounts, #lt_Accounts, subaccounts
	Where  	accounts.acccode = #lt_Accounts.acccode and
		accounts.subcode = subaccounts.subacccode
	
Drop table #lt_Accounts
GO

-- sp_AccountsLedger (last defined by script catalog)

/****** Object:  Stored Procedure dbo.sp_AccountsLedger    Script Date: 4/23/02 4:29:59 PM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsLedger    Script Date: 4/8/02 6:26:06 PM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsLedger    Script Date: 3/6/02 3:39:36 PM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsLedger    Script Date: 7/20/01 6:52:01 PM ******/
/****** Object:  Stored Procedure dbo.sp_AccountsLedger    Script Date: 4/19/00 1:21:26 PM ******/
CREATE PROCEDURE sp_AccountsLedger @ad_StartDate datetime,
				   @ad_EndDate   datetime AS

/* Declaration of local Variables to be used in the script later */

DECLARE @ln_purchaseacc NUMERIC(5, 0)
DECLARE @ln_cashacc NUMERIC(5, 0)
DECLARE @ln_equityacc NUMERIC(5, 0)
DECLARE @ln_salesacc NUMERIC(5, 0)
DECLARE @ln_salesretacc NUMERIC(5, 0)
DECLARE @ln_purchaseretacc NUMERIC(5, 0)
DECLARE @ln_revfromservice NUMERIC(5, 0)
DECLARE @ln_salestaxacc NUMERIC(5, 0)

/* Fetching local Variables values to be used in the script later */

SELECT @ln_purchaseacc     = (SELECT code FROM global WHERE name = 'GT_PurchaseAccount')
SELECT @ln_cashacc         = (SELECT code FROM global WHERE name = 'GT_CashACC')
SELECT @ln_equityacc	   = (SELECT code FROM global WHERE name = 'GT_EquityACC')
SELECT @ln_salesacc        = (SELECT code FROM global WHERE name = 'GT_SalesACC')
SELECT @ln_salesretacc     = (SELECT code FROM global WHERE name = 'GT_SalesReturnACC')
SELECT @ln_purchaseretacc  = (SELECT code FROM global WHERE name = 'GT_PurchaseReturnsAccount')
SELECT @ln_revfromservice  = (SELECT code FROM global WHERE name = 'GT_RevenueFromServices')
SELECT @ln_salestaxacc	   = (SELECT code FROM global WHERE name = 'GT_AdvanceSalesTaxACC')


/**********************Computation of Opening Balance***************************/

exec sp_accountsBalance @ad_StartDate

/**********************Initial HouseKeeping ***************************/
/* Declaration of Temporary Table to be used for records to be returned by this script */

create table #lt_Accounts
(
	acccode      numeric (5,  0) NOT NULL,
	accname      varchar (100)       NULL,
	subaccname   varchar (100)       NULL,
	openbalance  numeric (15, 2) NOT NULL 
)

create table #lt_accountsledger
(
	acccode      numeric (5,  0) NOT NULL,
	Type         varchar (100)   NOT NULL,
	Date         DateTime        NOT NULL,
	debit        numeric (12, 2) NOT NULL, 
	credit       numeric (12, 2) NOT NULL,
	Remarks      varchar (100)   	 NULL, 
)


Insert #lt_Accounts
Select code1, name1, name2, value1
from   ReportData

/**********************************************************************/
/**************************** Accounting Vouchers ************************/
/**********************************************************************/

insert #lt_accountsledger
Select  acccode = gldetail.acccode, 
	type    = Case VochCatCode When 1 Then 'CP-'
				   When 2 Then 'CR-'
				   When 3 Then 'BP-'
				   When 4 Then 'BR-'
				   When 5 Then 'JV-'
				   Else        'OV-'
		  End + Ltrim(str(glheader.glvochcode)),
	date    = glheader.Date, 
	debit   = gldetail.debit, 
	credit  = gldetail.credit,
	remarks = glheader.remarks


from    glheader,
	gldetail 

where    glheader.date between @ad_StartDate and @ad_EndDate and
	 glheader.posted = 'Y'	 and 
	 glheader.glvochcode = gldetail.glvochcode

/**********************************************************************/
/********************* Bills Receivables/Payables **********************/
/**********************************************************************/

/************************* Receivables/Payables **********************/

insert #lt_accountsledger
Select  acccode= Notes.acccode, 
	Type   = Case Notes.NoteCatCode  
			When 1 Then 'NR-'
			Else        'NP-'
		 End + Ltrim(str(Notes.NoteCode)), 
	Date   = Notes.PostDate, 
	debit  = Case Notes.NoteCatCode  
			When 2 Then Notes.Amount
			Else        0
		 End,
	credit = Case Notes.NoteCatCode  
			When 1 Then Notes.Amount
			Else        0
		 End,
	remarks= notes.remarks

from    Notes

where   Notes.Postdate between @ad_StartDate and @ad_EndDate and
	Notes.posted = 'Y'	

/*********************   Bank **********************/

insert #lt_accountsledger
Select  acccode= Notes.Bankacccode, 
	Type   = Case Notes.NoteCatCode  
			When 1 Then 'NR-'
			Else        'NP-'
		 End + Ltrim(str(Notes.NoteCode)), 
	Date   = Notes.PostDate, 
	debit  = Case Notes.NoteCatCode  
			When 1 Then Notes.Amount
			Else        0
		 End,
	credit = Case Notes.NoteCatCode  
			When 2 Then Notes.Amount
			Else        0
		 End,
	remarks= notes.remarks

from    Notes

where    Notes.Postdate between @ad_StartDate and @ad_EndDate and
	 Notes.posted = 'Y'	 

/**************************Final Housing Keeping *********************/
delete  reportdata

insert  reportdata(name1, name4, value3, name2, date1, value1, value2, name3)
select 	RTrim(#lt_accounts.accname), 
	RTrim(#lt_accounts.subaccname), 
	#lt_accounts.openbalance, 
	#lt_accountsledger.type,
	#lt_accountsledger.date,
	#lt_accountsledger.debit,
	#lt_accountsledger.credit,
	#lt_accountsledger.remarks
from   	#lt_accounts, 
	#lt_accountsledger
where   #lt_accounts.acccode = #lt_accountsledger.acccode 
order  by accname

/*-------------by shahzad-----------*/

update reportdata
set reportdata.code1=accounts.acccode
from accounts,reportdata
where reportdata.name1=accounts.name

/*-------------end-----------*/
Drop Table #lt_accounts
Drop Table #lt_accountsledger
GO

-- sp_AccountsLedger1 (last defined by script catalog)
CREATE PROCEDURE sp_AccountsLedger1 @ai_AccCode int,@ad_Sdate datetime,@ad_Ldate datetime AS
/*****************************************************************/
/* Declaration of local Variables to be used in the script later */
/*****************************************************************/

DECLARE @ln_purchaseacc NUMERIC(5, 0)
DECLARE @ln_cashacc NUMERIC(5, 0)
DECLARE @ln_equityacc NUMERIC(5, 0)
DECLARE @ln_salesacc NUMERIC(5, 0)
DECLARE @ln_salesretacc NUMERIC(5, 0)
DECLARE @ln_purchaseretacc NUMERIC(5, 0)
DECLARE @ln_revfromservice NUMERIC(5, 0)
DECLARE @ln_salestaxacc NUMERIC(5, 0)

DECLARE @ln_OpeningBalance NUMERIC(15,2)

/*****************************************************************/
/* Fetching local Variables values to be used in the script later*/
/*****************************************************************/

SELECT @ln_purchaseacc     = (SELECT code FROM global WHERE name = 'GT_PurchaseAccount')
SELECT @ln_cashacc         = (SELECT code FROM global WHERE name = 'GT_CashACC')
SELECT @ln_equityacc	   = (SELECT code FROM global WHERE name = 'GT_EquityACC')
SELECT @ln_salesacc        = (SELECT code FROM global WHERE name = 'GT_SalesACC')
SELECT @ln_salesretacc     = (SELECT code FROM global WHERE name = 'GT_SalesReturnACC')
SELECT @ln_purchaseretacc  = (SELECT code FROM global WHERE name = 'GT_PurchaseReturnsAccount')
SELECT @ln_revfromservice  = (SELECT code FROM global WHERE name = 'GT_RevenueFromServices')
SELECT @ln_salestaxacc	   = (SELECT code FROM global WHERE name = 'GT_AdvanceSalesTaxACC')

/*****************************************************************/
/* Declaration of Temporary Table to be used for records to be returned by this script */
/*****************************************************************/
CREATE TABLE #lt_virtualgl
(
	documentcode int not null,
	documenttype varchar(5) not null,
	catcode      tinyint NOT NULL,
	dr_acccode      smallint NOT NULL,
	cr_acccode      smallint NOT NULL,
	AlternateAccCode smallint NULL,
	date datetime not null,
	amount numeric (15, 2) NOT NULL,
	remarks varchar (100) NULL,
	checkNo varchar (20) NULL,
	usercode smallint NULL
)

/*****************************************************************/
/*-------------------------- CASH ACCOUNT -----------------------*/
/*****************************************************************/

IF @ai_AccCode =@ln_cashacc
BEGIN

	/*******************************/
	/*OPENING BALANCE CALCULATIONS */
	/*******************************/

	SELECT  @ln_OpeningBalance=
	(SELECT ISNULL(SUM(S.amount),0) 
	FROM 	(SELECT Amount = Isnull(Round(SUM(saledetail.looseqty*saledetail.unitsalestax) +
			SUM(ROUND( (saledetail.looseqty * 
				(saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))*saledetail.gstperc * .01,2))+
			Round( (sum( (saledetail.looseqty * 
				(saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))) * 
				(1- (.01 * saleledger.discperc)) - saleledger.flatdisc) * 
				(saleledger.invgstperc1 * .01), 2), 0) +
			Round( sum( (saledetail.looseqty * 
				(saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))) * 
				(1- (.01 * saleledger.discperc)) + saleledger.misccharges + 
				saleledger.salestax - saleledger.flatdisc, 0), 0)
		FROM	saleledger, saledetail		
		WHERE	saleledger.salecatcode IN ( 1,3 )and 
	                SaleLedger.Date < @ad_Sdate and
			/*saleledger.posted = 'Y' and */
			saleledger.saleinvcode = saledetail.saleinvcode
		GROUP BY saleledger.saleinvcode,
			saleledger.custcode, 
			saleledger.salecatcode,
			saleledger.date,
			saleledger.discperc,
			saleledger.misccharges,
			saleledger.salestax,
			saleledger.invgstperc1,
			saleledger.flatdisc,
			saleledger.salesmancode) as S)
	-
	(SELECT ISNULL(SUM(SR.amount),0) 
	FROM	(SELECT Amount  = Isnull(Round(SUM(srdetail.looseqty * srdetail.unitsalestax)+ 
				  SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc)) * 
					srdetail.gstperc * .01, 2)) +
				  Round( (sum( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc))) * 
					(1- (.01 * srledger.discperc)) - srledger.flatdisc) * 
					(srledger.invgstperc1 * .01), 2), 0) +
				  Round( sum( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc))) * 
					(1- (.01 * srledger.discperc)) + srledger.misccharges +
					srledger.salestax - srledger.flatdisc, 0), 0)
		FROM    srledger, srdetail
		WHERE   srledger.srcatcode in (8,6) AND
			srledger.date  < @ad_Sdate and 
			srledger.posted = 'Y' and 
			srledger.srinvcode = srdetail.srinvcode 
		GROUP BY srledger.srinvcode,
			srledger.custcode, 
			srledger.srcatcode,
			srledger.date,
			srledger.discperc,
			srledger.misccharges,
			srledger.salestax,
			srledger.invgstperc1,
			srledger.flatdisc,
			srledger.salesmancode) as SR)
	+
	(SELECT ISNULL(SUM(SER.amount) ,0)
	FROM	(SELECT Amount	= IsNull(Round(sum( (isnull(d.price, 0) * 
				  (1 - (.01 * isnull(d.discperc, 0)))) * 
				  (1- (.01 * ISNULL(h.discperc, 0))) + isnull(h.misccharges,0)- 
				  isnull(h.flatdisc, 0)), 0), 0)
		FROM    serviceheader h,
			servicedetail d

		WHERE	h.serviceCatCode IN (10,12) AND
			h.date < @ad_Sdate  and
			/* h.posted = 'Y'	 and */
			h.serviceinvcode = d.serviceinvcode 
		GROUP BY h.serviceinvcode,
			 h.custcode, 
			 h.ServiceCatCode,
			 h.date,
			 h.discperc,
			 h.misccharges,
			 h.flatdisc,
			 h.salesmancode)as SER)
	- 
        (SELECT ISNULL(SUM(SERR.amount) ,0)
	FROM    (SELECT	Amount   = IsNull(Round(sum( (isnull(d.ServicePrice, 0) * 
				  (1 - (.01 * isnull(d.discperc, 0)))) * 
				  (1- (.01 * h.discperc)) + isnull(h.misccharges,0) - 
				  isnull(h.flatdisc, 0)), 0), 0)
		FROM    serviceRheader h,
			serviceRdetail d

		WHERE	h.servicercatcode IN (13,15) AND
			h.date < @ad_Sdate and 
			h.posted = 'Y'	 and 
			h.serviceRinvcode = d.serviceRinvcode 
		GROUP BY h.serviceRinvcode,
			 h.custcode, 
			 h.ServiceRCatCode,
			 h.date,
			 h.discperc,
			 h.misccharges,
			 h.flatdisc,
			 h.salesmancode  ) as SERR)
	+
	(SELECT ISNULL(SUM(GL.debit - GL.credit),0)
	FROM	(SELECT debit,credit,gldetail.glvochcode,glheader.postdate
		FROM  	gldetail, glheader
		WHERE 	glheader.postdate < @ad_Sdate and 
	      		glheader.posted='Y' and
	      		glheader.glvochcode=gldetail.glvochcode and
      			gldetail.acccode=@ai_AccCode ) AS GL)

	/*******************************/
	/*TRANSACTIONS DURING PERIOD */
	/*******************************/

	INSERT INTO #lt_VirtualGL
	SELECT  documentcode = saleledger.saleinvcode,
		documenttype    = 'SV',
		catcode = saleledger.SaleCatCode,
		dr_acccode = CASE saleledger.saleCatCode
				WHEN 1 THEN @ln_cashacc     /* Cash Sale */
				WHEN 3 THEN @ln_cashacc     /* Cash Sale */
				ELSE   saleledger.custcode  /* Credit Sale */
				END,
		cr_acccode = @ln_salesacc,
		AlternateAccCode = CASE saleledger.saleCatCode
				WHEN 1 THEN saleledger.custcode  /* Cash Sale */
				WHEN 3 THEN saleledger.custcode  /* Cash Sale */
				ELSE Null
				END,
		Date    = saleledger.date,
		Amount  = Isnull(Round(SUM(saledetail.looseqty * saledetail.unitsalestax) + 
			  SUM(ROUND( (saledetail.looseqty * 
				(saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))*saledetail.gstperc * .01,2)) +
			  Round( (sum( (saledetail.looseqty * 
				(saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))) * 
				(1- (.01 * saleledger.discperc)) - saleledger.flatdisc) * 
				(saleledger.invgstperc1 * .01), 2), 0) +
			  Round( sum( (saledetail.looseqty * 
				(saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))) * 
				(1- (.01 * saleledger.discperc)) + saleledger.misccharges + 
				saleledger.salestax - saleledger.flatdisc, 0), 0),
		remarks = MAX(saleledger.remarks),
		CheckNo = NULL, 
		UserCode=saleledger.salesmancode
	FROM    saleledger, saledetail
	WHERE   saleledger.salecatcode IN ( 1,3 )and 
                SaleLedger.Date between @ad_Sdate and @ad_ldate and
		/*saleledger.posted = 'Y'	 and */
		saleledger.saleinvcode = saledetail.saleinvcode  
	GROUP BY saleledger.saleinvcode,
		 saleledger.custcode, 
		 saleledger.salecatcode,
		 saleledger.date,
		 saleledger.discperc,
		 saleledger.misccharges,
		 saleledger.salestax,
		 saleledger.invgstperc1,
		 saleledger.flatdisc,
		 saleledger.salesmancode

	INSERT INTO #lt_VirtualGL
	SELECT  documentcode = srledger.srinvcode,
		documenttype = 'SRV',
		catcode = SRledger.SRCatCode,
		dr_acccode = @ln_salesretacc,
		cr_acccode = CASE srledger.srCatCode
			WHEN 6 THEN @ln_cashacc     /* Cash Sale Return*/
			WHEN 8 THEN @ln_cashacc     /* Cash Sale Return*/
			ELSE   srledger.custcode     /* Credit Sale Return*/
		END,
		AlternateAccCode = CASE srledger.srCatCode
			WHEN 6 THEN srledger.custcode     /* Cash Sale Return*/
			WHEN 8 THEN srledger.custcode     /* Cash Sale Return*/
			ELSE   NULL     /* Credit Sale Return*/
		END,
		Date    = srledger.date,
		Amount  = Isnull(Round(SUM(srdetail.looseqty * srdetail.unitsalestax)+ 
				  SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc)) * 
					srdetail.gstperc * .01, 2)) +
				  Round( (sum( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc))) * 
					(1- (.01 * srledger.discperc)) - srledger.flatdisc) * 
					(srledger.invgstperc1 * .01), 2), 0) +
				  Round( sum( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc))) * 
					(1- (.01 * srledger.discperc)) + srledger.misccharges +
					srledger.salestax - srledger.flatdisc, 0), 0),
		remarks = max(srledger.remarks),
		CheckNo = NULL, 
		UserCode= ISNULL(srledger.salesmancode, 0)
	FROM    srledger, srdetail		
	WHERE   srledger.srcatcode in (8,6) AND
		srledger.date between @ad_Sdate and @ad_ldate and
		srledger.posted = 'Y'	 and 
		srledger.srinvcode = srdetail.srinvcode 

	GROUP BY srledger.srinvcode,
		 srledger.custcode, 
		 srledger.srcatcode,
		 srledger.date,
		 srledger.discperc,
		 srledger.misccharges,
		 srledger.salestax,
		 srledger.invgstperc1,
		 srledger.flatdisc,
		 srledger.salesmancode

	INSERT INTO #lt_VirtualGL
	SELECT  DocumentCode = h.serviceinvcode, 
		DocumentType = Case h.ServiceCatCode
				when 10 THEN 'SERV'
				when 12 THEN 'SERV'
				else        'SERV'			       End,
		catcode = h.ServiceCatCode,
		dr_acccode      = Case h.ServiceCatCode
				when 10 THEN 	@ln_cashacc
				when 12 THEN 	@ln_cashacc
				else		h.custcode
			       End,
		cr_acccode = @ln_revfromservice,
		AlternateAccCode = CASE h.ServiceCatCode
			WHEN 10 THEN h.custcode     /* Cash Sale Service*/
			WHEN 12 THEN h.custcode     /* Cash Sale Service*/
			ELSE   NULL     /* Credit Sale Service*/
		END,
		Date         = h.date,
		Amount       = IsNull(Round(sum( (isnull(d.price, 0) * 
				  (1 - (.01 * isnull(d.discperc, 0)))) * 
				  (1- (.01 * ISNULL(h.discperc, 0))) + isnull(h.misccharges,0) - 
				  isnull(h.flatdisc, 0)), 0), 0),
		remarks = max(h.remarks),
		CheckNo = NULL, 
		UserCode=ISNULL(h.salesmancode, 0)

	FROM     serviceheader h,
		 servicedetail d

	WHERE	 h.serviceCatCode IN (10,12) AND
                 h.date between @ad_Sdate and @ad_ldate and
		 /*h.posted = 'Y'	 and */
		 h.serviceinvcode = d.serviceinvcode 
	GROUP BY h.serviceinvcode,
		 h.custcode, 
		 h.ServiceCatCode,
		 h.date,
		 h.discperc,
		 h.misccharges,
		 h.flatdisc,
		 h.salesmancode 

	INSERT INTO #lt_VirtualGL
	SELECT  DocumentCode = h.serviceRinvcode, 
		DocumentType = Case h.ServiceRCatCode
				when 13 THEN 'SERRV'
				when 15 THEN 'SERRV'
				else        'SERRV'
			       End,
		catcode = h.ServiceRCatCode,
		dr_acccode = @ln_revfromservice,
		cr_acccode = Case h.ServiceRCatCode
				when 13 THEN 	@ln_cashacc
				when 15 THEN 	@ln_cashacc
				else		h.custcode
			  End,
		AlternateAccCode = Case h.ServiceRCatCode
				when 13 THEN 	h.custcode
				when 15 THEN 	h.custcode
				else		NULL
			  End,
		Date    = h.date,
		Amount   = IsNull(Round(sum( (isnull(d.ServicePrice, 0) * 
			  (1 - (.01 * isnull(d.discperc, 0)))) * 
			  (1- (.01 * h.discperc)) + isnull(h.misccharges,0) - 
			  isnull(h.flatdisc, 0)), 0), 0),
		remarks = max(h.remarks),
		CheckNo = NULL, 
		UserCode=h.salesmancode

	FROM    serviceRheader h, serviceRdetail d

	WHERE    h.servicercatcode IN (13,15) AND
		 h.date between @ad_Sdate and @ad_ldate and
		 h.posted = 'Y'	 and 
		 h.serviceRinvcode = d.serviceRinvcode 

	GROUP BY h.serviceRinvcode,
		 h.custcode, 
		 h.ServiceRCatCode,
		 h.date,
		 h.discperc,
		 h.misccharges,
		 h.flatdisc,
		 h.salesmancode 


	DELETE FROM reportdata

	INSERT INTO reportdata(code1,value1,value2,date1,name2,name3)
	SELECT @ai_AccCode,amount,0,date,remarks,Convert(varchar(12),DocumentCode) + DocumentType
	FROM #lt_VirtualGL
	WHERE DocumentType IN ('SV','SERV')

	INSERT INTO reportdata (code1,value1,value2,date1,name2,name3)
	SELECT @ai_AccCode,0,amount,date,remarks,Convert(varchar(12),DocumentCode) + DocumentType
	FROM #lt_VirtualGL
	WHERE DocumentType IN ('SERRV','SRV')

END

/*****************************************************************/
/*-------------------------Revenue From Sale Acc-----------------*/
/*****************************************************************/

IF @ai_AccCode=@ln_salesacc
BEGIN

	/*******************************/
	/*OPENING BALANCE CALCULATIONS */
	/*******************************/

	SELECT 	@ln_OpeningBalance=
	(SELECT ISNULL(SUM(S.amount),0) * (- 1)
	FROM	(SELECT	Amount = Isnull(Round(SUM(saledetail.looseqty * saledetail.unitsalestax) + 
			SUM(ROUND( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))*saledetail.gstperc * .01,2))+
			Round( (sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc))*
				(1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) - saleledger.flatdisc) * (saleledger.invgstperc1 * .01), 2), 0) +
			Round( sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0), 0)
		FROM	saleledger, saledetail
		WHERE   saleledger.salecatcode IN ( 1,3,2 )and 
                	SaleLedger.Date < @ad_Sdate  and
			/*saleledger.posted = 'Y'	 and */
			saleledger.saleinvcode = saledetail.saleinvcode  
		GROUP BY saleledger.saleinvcode,
			 saleledger.custcode, 
			 saleledger.salecatcode,
			 saleledger.date,
			 saleledger.discperc,
			 saleledger.misccharges,
		 	 saleledger.salestax,
			 saleledger.invgstperc1,
			 saleledger.flatdisc,
			 saleledger.salesmancode ) as S)
	+
	(SELECT ISNULL(SUM(GL.debit - GL.credit),0)
	FROM    (SELECT debit,credit,gldetail.glvochcode,glheader.postdate
		FROM	gldetail, glheader
		WHERE	glheader.postdate < @ad_Sdate and 
      			glheader.posted='Y' and
      			glheader.glvochcode=gldetail.glvochcode and
      			gldetail.acccode=@ai_AccCode) AS GL)

	/*******************************/
	/*TRANSACTIONS DURING PERIOD */
	/*******************************/

	INSERT INTO #lt_VirtualGL
	SELECT  documentcode = saleledger.saleinvcode,
		documenttype    = 'SV',
		catcode = saleledger.SaleCatCode,
		dr_acccode =  saleledger.custcode,    
		cr_acccode = saleledger.custcode,
		AlternateAccCode = saleledger.custcode,
		Date    = saleledger.date,
		Amount  = Isnull(Round(SUM(saledetail.looseqty * saledetail.unitsalestax) + 
			SUM(ROUND( (saledetail.looseqty * 
				(saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))*saledetail.gstperc * .01,2))+
			Round( (sum( (saledetail.looseqty * 
				(saledetail.saleprice - saledetail.itemflatdisc))*
				(1 - (.01 * saledetail.discperc))) * 
				(1- (.01 * saleledger.discperc)) - saleledger.flatdisc) * 
				(saleledger.invgstperc1 * .01), 2), 0) +
			Round( sum( (saledetail.looseqty * 
				(saledetail.saleprice - saledetail.itemflatdisc)) *
				(1 - (.01 * saledetail.discperc))) * 
				(1- (.01 * saleledger.discperc)) + saleledger.misccharges + 
				saleledger.salestax - saleledger.flatdisc, 0), 0),
		remarks = MAX(saleledger.remarks),
		CheckNo = NULL, 
		UserCode=saleledger.salesmancode

	FROM    saleledger,	 
		saledetail		

	WHERE   saleledger.salecatcode IN ( 1,3,2 )and 
                SaleLedger.Date between @ad_Sdate and @ad_ldate and
		/*saleledger.posted = 'Y'	 and */
		saleledger.saleinvcode = saledetail.saleinvcode  
		
	GROUP BY saleledger.saleinvcode,
		 saleledger.custcode, 
		 saleledger.salecatcode,
		 saleledger.date,
		 saleledger.discperc,
		 saleledger.misccharges,
		 saleledger.salestax,
		 saleledger.invgstperc1,
		 saleledger.flatdisc,
		 saleledger.salesmancode 
	
	DELETE FROM reportdata

	INSERT INTO reportdata(code1,value1,value2,code2,date1)
	SELECT  @ai_AccCode, 0,amount,DocumentCode,date
	FROM #lt_VirtualGL
	WHERE DocumentType IN ('SV')
END

/*****************************************************************/
/*----------------------SALE RETURN ACCOUNT ---------------------*/
/*****************************************************************/

IF @ai_AccCode =@ln_salesretacc
BEGIN

	/*******************************/
	/*OPENING BALANCE CALCULATIONS */
	/*******************************/

	SELECT  @ln_OpeningBalance=
	(SELECT ISNULL(SUM(SR.amount),0) 
	FROM	(SELECT Amount  = Isnull(Round(SUM(srdetail.looseqty * srdetail.unitsalestax)+ 
				  SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc)) * 
					srdetail.gstperc * .01, 2)) +
				  Round( (sum( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc))) * 
					(1- (.01 * srledger.discperc)) - srledger.flatdisc) * 
					(srledger.invgstperc1 * .01), 2), 0) +
				  Round( sum( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc))) * 
					(1- (.01 * srledger.discperc)) + srledger.misccharges +
					srledger.salestax - srledger.flatdisc, 0), 0)
		FROM	srledger, srdetail		
		WHERE    srledger.srcatcode in (8,6,7) AND
			 srledger.date  < @ad_Sdate and 
			 srledger.posted = 'Y'	 and 
			 srledger.srinvcode = srdetail.srinvcode 
		GROUP BY srledger.srinvcode,
			 srledger.custcode, 
			 srledger.srcatcode,
			 srledger.date,
			 srledger.discperc,
			 srledger.misccharges,
			 srledger.salestax,
			 srledger.invgstperc1,
			 srledger.flatdisc,
			 srledger.salesmancode) as SR)
	+
	(SELECT ISNULL(SUM(GL.debit - GL.credit),0)
	FROM    (SELECT debit,credit,gldetail.glvochcode,glheader.postdate
		FROM  	gldetail, glheader
		WHERE 	glheader.postdate < @ad_Sdate and 
      			glheader.posted='Y' and
      			glheader.glvochcode=gldetail.glvochcode and
      			gldetail.acccode=@ai_AccCode) AS GL)

	/*******************************/
	/*TRANSACTIONS DURING PERIOD */
	/*******************************/
	
	INSERT INTO #lt_VirtualGL
	SELECT  documentcode = srledger.srinvcode,
		documenttype = 'SRV',
		catcode = SRledger.SRCatCode,
		dr_acccode = @ln_salesretacc,
		cr_acccode = CASE srledger.srCatCode
			WHEN 6 THEN @ln_cashacc     /* Cash Sale Return*/
			WHEN 8 THEN @ln_cashacc     /* Cash Sale Return*/
			ELSE   srledger.custcode     /* Credit Sale Return*/
		END,
		AlternateAccCode = CASE srledger.srCatCode
			WHEN 6 THEN srledger.custcode     /* Cash Sale Return*/
			WHEN 8 THEN srledger.custcode     /* Cash Sale Return*/
			ELSE   NULL     /* Credit Sale Return*/
		END,
		Date    = srledger.date,
		Amount  = Isnull(Round(SUM(srdetail.looseqty * srdetail.unitsalestax)+ 
				SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc)) * 
					srdetail.gstperc * .01, 2)) +
				Round( (sum( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc))) * 
					(1- (.01 * srledger.discperc)) - srledger.flatdisc) * 
					(srledger.invgstperc1 * .01), 2), 0) +
				Round( sum( (srdetail.looseqty * srdetail.srprice) *
					(1 - (.01 * srdetail.discperc))) * 
					(1- (.01 * srledger.discperc)) + srledger.misccharges +
					srledger.salestax - srledger.flatdisc, 0), 0),
		remarks = max(srledger.remarks),
		CheckNo = NULL, 
		UserCode= ISNULL(srledger.salesmancode, 0)

	FROM     srledger,	 
		 srdetail		

	WHERE    srledger.srcatcode in (8,6,7) AND
		 srledger.date between @ad_Sdate and @ad_ldate and
		 srledger.posted = 'Y'	 and 
		 srledger.srinvcode = srdetail.srinvcode 

	GROUP BY srledger.srinvcode,
		 srledger.custcode, 
		 srledger.srcatcode,
		 srledger.date,
		 srledger.discperc,
		 srledger.misccharges,
		 srledger.salestax,
		 srledger.invgstperc1,
		 srledger.flatdisc,
		 srledger.salesmancode

	DELETE FROM reportdata

	INSERT INTO reportdata (code1,value1,value2,date1,name2,name3)
	SELECT @ai_AccCode,amount,0,date,remarks,Convert(varchar(12),DocumentCode) + DocumentType
	FROM #lt_VirtualGL
	WHERE DocumentType IN ('SRV')

END

/*****************************************************************/
/*----------------REVENUE FROM SERVICE ACCOUNT ------------------*/
/*****************************************************************/

IF @ai_AccCode =@ln_revfromservice
BEGIN

	/*******************************/
	/*OPENING BALANCE CALCULATIONS */
	/*******************************/

	SELECT  @ln_OpeningBalance=
	(SELECT ISNUll(SUM(SER.amount) ,0) * (- 1)
	FROM   	(SELECT DocumentCode = h.serviceinvcode, 
			DocumentType = Case h.ServiceCatCode
				when 10 THEN 'SERV'
				when 12 THEN 'SERV'
				else        'SERV'		       		End,
			catcode = h.ServiceCatCode,
			dr_acccode      = Case h.ServiceCatCode
				when 10 THEN 	@ln_cashacc
				when 12 THEN 	@ln_cashacc
				else		h.custcode
			        End,
			cr_acccode = @ln_revfromservice,
			AlternateAccCode = CASE h.ServiceCatCode
				WHEN 10 THEN h.custcode     /* Cash Sale Service*/				WHEN 12 THEN h.custcode     /* Cash Sale Service*/
				ELSE   NULL     /* Credit Sale Service*/
				END,
			Date   = h.date,
			Amount = IsNull(Round(sum( (isnull(d.price, 0) * 
				 (1 - (.01 * isnull(d.discperc, 0)))) * 
			  	 (1- (.01 * ISNULL(h.discperc, 0))) + isnull(h.misccharges,0) - 
				 isnull(h.flatdisc, 0)), 0), 0),
				 remarks = max(h.remarks),
				 CheckNo = NULL, 
				 UserCode=ISNULL(h.salesmancode, 0)
		FROM serviceheader h, servicedetail d
		WHERE 	h.serviceCatCode IN (10,12) AND
                	h.date < @ad_Sdate  and
			/* h.posted = 'Y'	 and */
			h.serviceinvcode = d.serviceinvcode 
		GROUP BY h.serviceinvcode,
			 h.custcode, 
			 h.ServiceCatCode,
			 h.date,
			 h.discperc,
			 h.misccharges,
			 h.flatdisc,
			 h.salesmancode)as SER)
	- 
        (SELECT ISNULL(SUM(SERR.amount) ,0)
	FROM    (SELECT DocumentCode = h.serviceRinvcode, 
			DocumentType = Case h.ServiceRCatCode
				when 13 THEN 'SERRV'
				when 15 THEN 'SERRV'
				else        'SERRV'
			        End,
			catcode = h.ServiceRCatCode,
			dr_acccode = @ln_revfromservice,
			cr_acccode = Case h.ServiceRCatCode
				when 13 THEN 	@ln_cashacc
				when 15 THEN 	@ln_cashacc				else		h.custcode
				End,
			AlternateAccCode = Case h.ServiceRCatCode
				when 13 THEN 	h.custcode
				when 15 THEN 	h.custcode
				else		NULL
			  	End,
			Date    = h.date,
			Amount   = IsNull(Round(sum( (isnull(d.ServicePrice, 0) * 
				   (1 - (.01 * isnull(d.discperc, 0)))) * 
				   (1- (.01 * h.discperc)) + isnull(h.misccharges,0) - 
			  	   isnull(h.flatdisc, 0)), 0), 0),
			remarks = max(h.remarks),
			CheckNo = NULL, 
			UserCode=h.salesmancode
	FROM     serviceRheader h, serviceRdetail d
	WHERE    h.servicercatcode IN (13,15) AND
		 h.date < @ad_Sdate and 
		 h.posted = 'Y'	 and 
		 h.serviceRinvcode = d.serviceRinvcode 
	GROUP BY h.serviceRinvcode,
		 h.custcode, 
		 h.ServiceRCatCode,
		 h.date,
		 h.discperc,
		 h.misccharges,
		 h.flatdisc,
		 h.salesmancode  ) as SERR)
	+
	(SELECT ISNULL(SUM(GL.debit - GL.credit),0)
	FROM    (SELECT debit,credit,gldetail.glvochcode,glheader.postdate
		FROM gldetail, glheader
		WHERE   glheader.postdate < @ad_Sdate and 
      			glheader.posted='Y' and
      			glheader.glvochcode=gldetail.glvochcode and
      			gldetail.acccode=@ai_AccCode) AS GL)
		
	/*******************************/
	/*TRANSACTIONS DURING PERIOD */
	/*******************************/

	INSERT INTO #lt_VirtualGL
		
	SELECT  DocumentCode = h.serviceinvcode, 
		DocumentType = Case h.ServiceCatCode
				when 10 THEN 'SERV'
				when 12 THEN 'SERV'
				else        'SERV'			       End,
		catcode = h.ServiceCatCode,
		dr_acccode      = Case h.ServiceCatCode
				when 10 THEN 	@ln_cashacc
				when 12 THEN 	@ln_cashacc
				else		h.custcode
			       End,
		cr_acccode = @ln_revfromservice,
		AlternateAccCode = CASE h.ServiceCatCode
			WHEN 10 THEN h.custcode     /* Cash Sale Service*/
			WHEN 12 THEN h.custcode     /* Cash Sale Service*/
			ELSE   NULL     /* Credit Sale Service*/
		END,
		Date         = h.date,
		Amount       = IsNull(Round(sum( (isnull(d.price, 0) * 
				  (1 - (.01 * isnull(d.discperc, 0)))) * 
				  (1- (.01 * ISNULL(h.discperc, 0))) + isnull(h.misccharges,0) - 
				  isnull(h.flatdisc, 0)), 0), 0),
		remarks = max(h.remarks),
		CheckNo = NULL, 
		UserCode=ISNULL(h.salesmancode, 0)

	FROM     serviceheader h, servicedetail d

	WHERE	 h.serviceCatCode IN (10,12) AND
                 h.date between @ad_Sdate and @ad_ldate and
		 /*h.posted = 'Y'	 and */
		 h.serviceinvcode = d.serviceinvcode 
	GROUP BY h.serviceinvcode,
		 h.custcode, 
		 h.ServiceCatCode,
		 h.date,
		 h.discperc,
		 h.misccharges,
		 h.flatdisc,
		 h.salesmancode 

	INSERT INTO #lt_VirtualGL
	SELECT  DocumentCode = h.serviceRinvcode, 
		DocumentType = Case h.ServiceRCatCode
				when 13 THEN 'SERRV'
				when 15 THEN 'SERRV'
				else        'SERRV'
			       End,
		catcode = h.ServiceRCatCode,
		dr_acccode = @ln_revfromservice,
		cr_acccode = Case h.ServiceRCatCode
				when 13 THEN 	@ln_cashacc
				when 15 THEN 	@ln_cashacc
				else		h.custcode
			  End,
		AlternateAccCode = Case h.ServiceRCatCode
				when 13 THEN 	h.custcode
				when 15 THEN 	h.custcode
				else		NULL
			  End,
		Date    = h.date,
		Amount   = IsNull(Round(sum( (isnull(d.ServicePrice, 0) * 
			  (1 - (.01 * isnull(d.discperc, 0)))) * 
			  (1- (.01 * h.discperc)) + isnull(h.misccharges,0) - 
			  isnull(h.flatdisc, 0)), 0), 0),
		remarks = max(h.remarks),
		CheckNo = NULL, 
		UserCode=h.salesmancode

	FROM     serviceRheader h,
		 serviceRdetail d

	WHERE    h.servicercatcode IN (13,15) AND
		 h.date between @ad_Sdate and @ad_ldate and
		 h.posted = 'Y'	 and 
		 h.serviceRinvcode = d.serviceRinvcode 

	GROUP BY h.serviceRinvcode,
		 h.custcode, 
		 h.ServiceRCatCode,
		 h.date,
		 h.discperc,
		 h.misccharges,
		 h.flatdisc,
		 h.salesmancode 


	DELETE FROM reportdata

	INSERT INTO reportdata(code1,value1,value2,date1,name2,name3)
	SELECT @ai_AccCode,0,AMOUNT,date,remarks,Convert(varchar(12),DocumentCode) + DocumentType
	FROM #lt_VirtualGL
	WHERE DocumentType IN ('SERV')

	INSERT INTO reportdata (code1,value1,value2,date1,name2,name3)
	SELECT @ai_AccCode,0,amount,date,remarks,Convert(varchar(12),DocumentCode) + DocumentType
	FROM #lt_VirtualGL
	WHERE DocumentType IN ('SERRV')
END

/*****************************************************************/
/*------------------------PURCHASE ACCOUNT ----------------------*/
/*****************************************************************/

IF @ai_AccCode = @ln_purchaseacc
BEGIN

	/*******************************/
	/*OPENING BALANCE CALCULATIONS */
	/*******************************/
  
	SELECT  @ln_OpeningBalance= 
	(SELECT ISNULL(SUM(PL.AMOUNT),0)  
	FROM 	(SELECT  Amount=ISNULL(
			 	ROUND(SUM((purdetail.looseqty + purdetail.packqty) *
					purdetail.purprice * (1 - (.01 * purdetail.discperc)))* 
					(1- (.01 * purledger.discperc)) + purledger.misccharges+ 
					purledger.salestax - purledger.flatdisc, 0) +
				ROUND(SUM(((purdetail.looseqty + purdetail.packqty) + 
					purdetail.bonusqty) * purdetail.unitsalestax) + 
				SUM(ROUND((purdetail.looseqty + purdetail.packqty) * 
					purdetail.purprice * (1 - (.01 * purdetail.discperc)) *
					purdetail.gstperc * .01, 2)) +
				ROUND((SUM(((purdetail.looseqty + purdetail.packqty) * 
					purdetail.purprice) * (1 - (.01 * purdetail.discperc)))* 
					(1- (.01 * purledger.discperc)) - purledger.flatdisc)* 
					(purledger.invgstperc1 * .01), 2), 0), 0)
		FROM     purledger, purdetail
		WHERE    purledger.postdate<@ad_Sdate and
			 purledger.purcatcode IN (1,2,3,7,8)AND 
			 purledger.posted = 'Y'	 AND	 
			 purledger.purinvcode = purdetail.purinvcode 		GROUP BY purledger.purinvcode,
			 purledger.suppcode, 
			 purledger.purcatcode,
			 purledger.postdate,
			 purledger.discperc,
			 purledger.misccharges,
			 purledger.salestax,
			 purledger.invgstperc1,
			 purledger.flatdisc,
			 purledger.salesmancode) AS PL)
	+
	(SELECT ISNULL(SUM(GL.debit - GL.credit),0)
	FROM    (SELECT debit,credit,gldetail.glvochcode,glheader.postdate
		FROM  	gldetail, glheader
		WHERE 	glheader.postdate < @ad_Sdate and 
      			glheader.posted='Y' and
      			glheader.glvochcode=gldetail.glvochcode and
      			gldetail.acccode=@ai_AccCode) AS GL)

	/*******************************/
	/*TRANSACTIONS DURING PERIOD */
	/*******************************/

	INSERT INTO #lt_VirtualGL
	SELECT  documentcode = purledger.purinvcode,
		documenttype='PV',
		catcode = purledger.PurCatCode,
		dr_acccode = purledger.suppcode,
		cr_acccode = purledger.suppcode,
		AlternateAccCode =purledger.suppcode,
		date    = purledger.postdate,
		Amount 	= ISNULL(
			 	ROUND(SUM((purdetail.looseqty + purdetail.packqty) *
					purdetail.purprice * (1 - (.01 * purdetail.discperc)))* 
					(1- (.01 * purledger.discperc)) + purledger.misccharges+ 
					purledger.salestax - purledger.flatdisc, 0) +
				ROUND(SUM(((purdetail.looseqty + purdetail.packqty) + 
					purdetail.bonusqty) * purdetail.unitsalestax) + 
				SUM(ROUND((purdetail.looseqty + purdetail.packqty) * 
					purdetail.purprice * (1 - (.01 * purdetail.discperc)) *
					purdetail.gstperc * .01, 2)) +
				ROUND((SUM(((purdetail.looseqty + purdetail.packqty) * 
					purdetail.purprice) * (1 - (.01 * purdetail.discperc)))* 
					(1- (.01 * purledger.discperc)) - purledger.flatdisc)* 
					(purledger.invgstperc1 * .01), 2), 0), 0),
		remarks = MAX(purledger.remarks),
		CheckNo = NULL,
		usercode= purledger.salesmancode
	FROM    purledger, purdetail
	WHERE   purledger.postdate between @ad_Sdate and @ad_ldate and
		purledger.purcatcode IN (1,2,3,7,8) AND 
		purledger.posted = 'Y'	 AND	 
		purledger.purinvcode = purdetail.purinvcode 
	GROUP BY purledger.purinvcode,
		 purledger.suppcode, 
		 purledger.purcatcode,
		 purledger.postdate,
		 purledger.discperc,
		 purledger.misccharges,
		 purledger.salestax,
		 purledger.invgstperc1,
		 purledger.flatdisc,
		 purledger.salesmancode

	DELETE FROM reportdata

	INSERT INTO reportdata(code1,value1,value2,date1,name2,name3)
	SELECT @ai_AccCode,amount,0,date,remarks,Convert(varchar(12),DocumentCode) + DocumentType
	FROM #lt_VirtualGL
	WHERE DocumentType IN ('PV')

END

/*****************************************************************/
/*------------------------CAPITAL ACCOUNT -----------------------*/
/*****************************************************************/

IF @ai_AccCode = @ln_equityacc
BEGIN

	/*******************************/
	/*OPENING BALANCE CALCULATIONS */
	/*******************************/
  
	SELECT  @ln_OpeningBalance= 
	(SELECT ISNULL(SUM(PL.AMOUNT),0)  * (- 1)
	FROM	(SELECT Amount= ISNULL(
			 	ROUND(SUM((purdetail.looseqty + purdetail.packqty) *
					purdetail.purprice * (1 - (.01 * purdetail.discperc)))* 
					(1- (.01 * purledger.discperc)) + purledger.misccharges+ 
					purledger.salestax - purledger.flatdisc, 0) +
				ROUND(SUM(((purdetail.looseqty + purdetail.packqty) + 
					purdetail.bonusqty) * purdetail.unitsalestax) + 
				SUM(ROUND((purdetail.looseqty + purdetail.packqty) * 
					purdetail.purprice * (1 - (.01 * purdetail.discperc)) *
					purdetail.gstperc * .01, 2)) +
				ROUND((SUM(((purdetail.looseqty + purdetail.packqty) * 
					purdetail.purprice) * (1 - (.01 * purdetail.discperc)))* 
					(1- (.01 * purledger.discperc)) - purledger.flatdisc)* 
					(purledger.invgstperc1 * .01), 2), 0), 0)
		FROM     purledger, purdetail
		WHERE    purledger.postdate<@ad_Sdate and
			 purledger.purcatcode IN (3)AND 
			 purledger.posted = 'Y'	 AND	 
			 purledger.purinvcode = purdetail.purinvcode 
		GROUP BY purledger.purinvcode,
			 purledger.suppcode, 
			 purledger.purcatcode,
			 purledger.postdate,
			 purledger.discperc,
			 purledger.misccharges,
			 purledger.salestax,
			 purledger.invgstperc1,
			 purledger.flatdisc,
			 purledger.salesmancode) AS PL)
	+
	(SELECT ISNULL(SUM(GL.debit - GL.credit),0)
	FROM    (SELECT debit,credit,gldetail.glvochcode,glheader.postdate
		FROM 	gldetail, glheader
		WHERE 	glheader.postdate < @ad_Sdate and 
      			glheader.posted='Y' and
      			glheader.glvochcode=gldetail.glvochcode and
      			gldetail.acccode=@ai_AccCode) AS GL)

	/*******************************/
	/*TRANSACTIONS DURING PERIOD */
	/*******************************/

	INSERT INTO #lt_VirtualGL
	SELECT  documentcode = purledger.purinvcode,
		documenttype='PV',
		catcode = purledger.PurCatCode,
		dr_acccode = purledger.suppcode,
		cr_acccode = purledger.suppcode,
		AlternateAccCode =purledger.suppcode,
		date    = purledger.postdate,
		Amount 	= ISNULL( ROUND(SUM(( (purdetail.looseqty + purdetail.packqty ) * purdetail.purprice) * (1 - (.01 * purdetail.discperc))) * (1- (.01 * purledger.discperc)) + purledger.misccharges + purledger.salestax - purledger.flatdisc, 0), 0),
		remarks = MAX(purledger.remarks),
		CheckNo = NULL,
		usercode= purledger.salesmancode

	FROM     purledger,	 
		 purdetail

	WHERE    purledger.postdate between @ad_Sdate and @ad_ldate and
		 purledger.purcatcode IN (3) AND 
		 purledger.posted = 'Y'	 AND	 
		 purledger.purinvcode = purdetail.purinvcode 
	GROUP BY purledger.purinvcode,
		 purledger.suppcode, 
		 purledger.purcatcode,
		 purledger.postdate,
		 purledger.discperc,
		 purledger.misccharges,
		 purledger.salestax,
		 purledger.invgstperc1,
		 purledger.flatdisc,
		 purledger.salesmancode

	DELETE	FROM reportdata

	INSERT INTO reportdata(code1,value1,value2,date1,name2,name3)
	SELECT @ai_AccCode,0,amount,date,remarks,Convert(varchar(12),DocumentCode) + DocumentType
	FROM #lt_VirtualGL
	WHERE DocumentType IN ('PV')

END


/*****************************************************************/
/*------------------ PURCHASE RETURN ACCOUNT --------------------*/
/*****************************************************************/

IF @ai_AccCode=@ln_purchaseretacc
BEGIN

	/*******************************/
	/*OPENING BALANCE CALCULATIONS */
	/*******************************/
	
	SELECT  @ln_OpeningBalance=
	(SELECT ISNULL(SUM(PR.amount),0) * (- 1)
	FROM	(SELECT	Amount = ISNULL(ROUND(SUM((( prdetail.looseqty + prdetail.packqty * prdetail.packunits) * prdetail.prprice) * (1 - (.01 * prdetail.discperc))) * (1- (.01 * prledger.discperc)) + prledger.misccharges + prledger.salestax - prledger.flatdisc, 0), 0)
		FROM prledger, prdetail
	WHERE   prledger.date < @ad_Sdate and
 		prledger.posted = 'Y'	 and 
		prledger.prcatcode IN (4,5) AND
	 	prledger.prinvcode = prdetail.prinvcode

	GROUP BY prledger.prinvcode,
	 	 prledger.suppcode, 
 		 prledger.prcatcode,
	 	 prledger.date,
 		 prledger.discperc,
	 	 prledger.misccharges,
	 	 prledger.salestax,
	 	 prledger.flatdisc,
 		 prledger.salesmancode) AS PR)
	+
	(SELECT  ISNULL(SUM(GL.debit - GL.credit),0)
	FROM    (SELECT debit,credit,gldetail.glvochcode,glheader.postdate
		FROM  	gldetail, glheader
		WHERE	glheader.postdate < @ad_Sdate and 
      			glheader.posted='Y' and
      			glheader.glvochcode=gldetail.glvochcode and
      			gldetail.acccode=@ai_AccCode) AS GL)

	/*******************************/
	/* TRANSACTIONS DURING PERIOD  */
	/*******************************/

	INSERT INTO #lt_VirtualGL
	SELECT  documentcode = prledger.prinvcode,
	 	documenttype    = 'PRV',
		catcode = prledger.PRCatCode,
 		dr_acccode = prledger.suppcode,
	 	cr_acccode = prledger.suppcode, 
		AlternateAccCode = prledger.suppcode,
	 	date    = prledger.date,
 		Amount = ISNULL(ROUND(SUM((( prdetail.looseqty + prdetail.packqty * prdetail.packunits) * prdetail.prprice) * (1 - (.01 * prdetail.discperc))) * (1- (.01 * prledger.discperc)) + prledger.misccharges + prledger.salestax - prledger.flatdisc, 0), 0),
	 	remarks = MAX(prledger.remarks),
		CheckNo = NULL,
	 	UserCode = prledger.salesmancode

	FROM     prledger,	 
	 	 prdetail		
 	WHERE	 prledger.date between @ad_Sdate and @ad_ldate AND
 		 prledger.posted = 'Y'	 and 
		 prledger.prcatcode IN(4,5) and
	 	 prledger.prinvcode = prdetail.prinvcode

	GROUP BY prledger.prinvcode,
	 	 prledger.suppcode, 
 		 prledger.prcatcode,
	 	 prledger.date,
 		 prledger.discperc,
	 	 prledger.misccharges,
	 	 prledger.salestax,
	 	 prledger.flatdisc,
 		 prledger.salesmancode


	DELETE FROM reportdata

	INSERT INTO reportdata(code1,value1,value2,date1,name2,name3)
	SELECT @ai_AccCode,0,amount,date,remarks,Convert(varchar(12),DocumentCode) + DocumentType
	FROM #lt_VirtualGL
	WHERE DocumentType IN ('PRV')

END

/*****************************************************************/
/*--------------------- ANY OTHER ACCOUNT -----------------------*/
/*****************************************************************/

IF  @ai_AccCode > 100

BEGIN

	/*******************************/
	/*OPENING BALANCE CALCULATIONS */
	/*******************************/

	SELECT	@ln_OpeningBalance=
	 	(select ISNULL(sum(gldetail.debit - gldetail.credit),0)
			from  	gldetail, glheader
			where 	glheader.postdate <@ad_Sdate and 
      				glheader.posted='Y' and
      				glheader.glvochcode=gldetail.glvochcode and
		      		gldetail.acccode=@ai_AccCode)
	DELETE FROM reportdata
END

INSERT INTO reportdata (code1,name1,value1,value2,date1,name2,name3)
SELECT  gldetail.acccode,'cash',debit,credit,glheader.postdate,gldetail.remarks,
	CASE glheader.vochcatcode
		When 1 Then convert(varchar(14),glheader.glvochcode) + 'CPV'
		When 2 Then convert(varchar(14),glheader.glvochcode) + 'CRV'
		When 3 Then convert(varchar(14),glheader.glvochcode) + 'BPV'
		When 4 Then convert(varchar(14),glheader.glvochcode) + 'BRV'
		When 5 Then convert(varchar(14),glheader.glvochcode) + 'JV'
	ELSE
		 convert(varchar(14),glheader.glvochcode) + 'OPEN'
	END											
FROM  gldetail, glheader
WHERE glheader.postdate between @ad_Sdate and @ad_Ldate and
      glheader.posted='Y' and
      glheader.glvochcode=gldetail.glvochcode and
      gldetail.acccode=@ai_AccCode


UPDATE reportdata 
SET value3=(SELECT @ln_OpeningBalance)
DROP TABLE #lt_VirtualGL
GO

-- SP_Activate_DeActivate_Quotation (last defined by script 7836)
CREATE PROCEDURE DBO.SP_Activate_DeActivate_Quotation
	@List VARCHAR(8000),
	@NewValue CHAR(1),
	@OldValue CHAR(1)
AS
/*
Author :
	M. Azhar Inayat
Purpose:
	To Activate/DeActivate a range of quotations

PARAMETER DESCRIPTION :
	@List = A comma separated list of quotation codes to be processed
	@NewValue = Y OR N activate Y/N
	@OldValue = Y OR N activate Y/N
*/

DELETE ReportData

DECLARE @Tab_List TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_List SELECT CODE FROM udf_StringToTabl(@List, ',')

UPDATE QuotationHeader 
SET Active = @NewValue
WHERE Active = @OldValue AND QuotationCode IN (SELECT Code FROM @Tab_List) 

RETURN 0
GO

