IF @type = 'C'
BEGIN
	INSERT INTO #lt_amt
	SELECT AccCode, Date, Amount=Debit, Paid=0, DaysOld=DATEDIFF(day, date, @l_date)
	FROM VirtualGL 
	WHERE	Date <= @l_Date AND 
		Debit > 0 AND 
		AccCode IN (SELECT CUSTCODE FROM CUSTOMER)
	ORDER BY AccCode, Date, Debit

	INSERT INTO #lt_pmt
	SELECT AccCode, Amount=SUM(Credit)
	FROM VirtualGL 
	WHERE	Date <= @l_Date AND 
		Credit > 0 AND 
		AccCode IN (SELECT CUSTCODE FROM CUSTOMER)
	GROUP BY AccCode
	ORDER BY AccCode
END
IF @type = 'S'
BEGIN
	INSERT INTO #lt_amt
	SELECT AccCode, Date, Amount=Credit, Paid=0, DaysOld=DATEDIFF(day, date, @l_date)
	FROM VirtualGL 
	WHERE 	Date <= @l_Date AND 
		Credit > 0 AND AccCode IN (SELECT SUPPCODE FROM SUPPLIER)
	ORDER BY AccCode, Date, Credit

	INSERT INTO #lt_pmt
	SELECT AccCode, Amount=SUM(Debit)
	FROM VirtualGL 
	WHERE 	Date <= @l_Date AND 
		Debit > 0 AND AccCode IN (SELECT SUPPCODE FROM SUPPLIER)
	GROUP BY AccCode
	ORDER BY AccCode
END

DECLARE C1 CURSOR FOR SELECT * FROM #lt_amt ORDER BY AccCode, Date, Amount
OPEN C1

FETCH NEXT FROM C1 INTO @AccCode, @TDate, @Amt, @Paid, @RowID, @DaysOld
WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @Pmt=ISNULL((SELECT ISNULL(Amount, 0) FROM #lt_pmt WHERE AccCode = @AccCode), 0)

	IF @Pmt <> 0
	BEGIN
		UPDATE #lt_amt
		SET Paid = Paid + CASE WHEN @Amt >= @Pmt THEN @Pmt ELSE @Amt END
		WHERE RowID = @RowID
	
		SELECT @Pmt = @Pmt - (SELECT CASE WHEN @Amt >= @Pmt THEN @Pmt ELSE @Amt END)
	
		UPDATE #lt_Pmt
		SET Amount = @Pmt 
		WHERE AccCode = @AccCode
	END

	FETCH NEXT FROM C1 INTO @AccCode, @TDate, @Amt, @Paid, @RowID, @DaysOld

END
CLOSE C1
DEALLOCATE C1

DELETE #lt_amt WHERE Amount - Paid = 0

IF @type = 'C'
BEGIN
	INSERT INTO ReportData (Code1, Name1, Name2, Name3, Name4, Name5, Value1, Code2)
	SELECT  
		Code1, Name1, Name2, Name3, Name4, Name5, Value1 = SUM(Value1), Code2
	FROM 
		(SELECT  
			Code1=Ar.AreaCode,
			Name1=Ar.Name,
			Name2=Ac.AliasName,
			Name3=Ac.Name,
			Name4=LEFT(LTRIM(RTRIM(C.Address1)) + ' ' + LTRIM(RTRIM(C.Address2)), 60),
			Name5=C.Phone,
			Value1 = 0.00,
			Code2 = T.Lowerlimit
		FROM Accounts Ac, Area Ar, Customer C, #lt_interval T
		WHERE 	Ac.AccCode = C.CustCode AND
			C.AreaCode = Ar.AreaCode
		UNION ALL
		SELECT  
			Code1=Ar.AreaCode,
			Name1=Ar.Name,
			Name2=Ac.AliasName,
			Name3=Ac.Name,
			Name4=LEFT(LTRIM(RTRIM(C.Address1)) + ' ' + LTRIM(RTRIM(C.Address2)), 60),
			Name5=C.Phone,
			Value1 = SUM(Amount-Paid),
			Code2 = (SELECT MAX(LowerLimit) FROM #lt_interval 
				WHERE	l.daysold >= lowerlimit AND
					l.daysold <= upperlimit)
		FROM #lt_amt l, Accounts Ac, Area Ar, Customer C
		WHERE 	l.AccCode = Ac.AccCode AND 
			Ac.AccCode = C.CustCode AND
			C.AreaCode = Ar.AreaCode
		GROUP BY
			Ar.AreaCode,
			Ar.Name,
			Ac.AccCode,
			Ac.Name,
			Ac.AliasName,
			C.Address1,
			C.Address2,
			C.Phone,
			l.DaysOld) T
	GROUP BY Code1, Name1, Name2, Name3, Name4, Name5, Code2
END

IF @type = 'S'
BEGIN
	INSERT INTO ReportData (Code1, Name1, Name2, Name3, Name4, Name5, Value1, Code2)
	SELECT  
		Code1,
		Name1,
		Name2,
		Name3,
		Name4,
		Name5,
		Value1=SUM(Value1),
		Code2
	FROM 
		(SELECT  
			Code1=0,
			Name1='All Supplier(s)',
			Name2=Ac.AliasName,
			Name3=Ac.Name,
			Name4=LEFT(LTRIM(RTRIM(S.Address1)) + ' ' + LTRIM(RTRIM(S.Address2)), 60),
			Name5=S.Phone,
			Value1 = 0.00,
			Code2 = T.Lowerlimit
		FROM Accounts Ac, Supplier S, #lt_interval T
		WHERE 	Ac.AccCode = S.SuppCode
		UNION ALL
		SELECT  
			Code1=0,
			Name1='All Supplier(s)',
			Name2=Ac.AliasName,
			Name3=Ac.Name,
			Name4=LEFT(LTRIM(RTRIM(S.Address1)) + ' ' + LTRIM(RTRIM(S.Address2)), 60),
			Name5=S.Phone,
			Value1 = SUM(Amount-Paid),
			Code2 = (SELECT MAX(LowerLimit) FROM #lt_interval 
				WHERE	l.daysold >= lowerlimit AND
					l.daysold <= upperlimit)
		FROM #lt_amt l, Accounts Ac, Supplier S
		WHERE 	l.AccCode = Ac.AccCode AND 
			Ac.AccCode = S.SuppCode
		GROUP BY
			Ac.AccCode,
			Ac.Name,
			Ac.AliasName,
			S.Address1,
			S.Address2,
			S.Phone,
			l.DaysOld) T
	GROUP BY Code1, Name1, Name2, Name3, Name4, Name5, Code2
END

UPDATE ReportData 
SET Value1 = ISNULL(
	(SELECT SUM(ISNULL(T.Value1,0)) 
	FROM ReportData T 
	WHERE T.Code2 >= R.Code2 AND T.Code1 = R.Code1 AND 
		T.Name2 = R.Name2 AND
		T.Name3 = R.Name3),0)
FROM ReportData R

DELETE ReportData WHERE Value1 = 0

DROP TABLE #lt_amt
DROP TABLE #lt_pmt
DROP TABLE #lt_interval
GO

-- sp_Aging_CustomerWise (last defined by script catalog)
CREATE PROCEDURE sp_Aging_CustomerWise @Type Char(1), @l_date DATETIME, @interval INT, @limit INT, @AccountList VARCHAR(8000)
AS

DECLARE @OldAccCode INT
DECLARE @AccCode INT
DECLARE @TDate DateTime
DECLARE @Amt Numeric(15,5)
DECLARE @Paid Numeric(15,5)
DECLARE @RowID INT
DECLARE @Pmt Numeric(15,5)
DECLARE @DaysOld INT
DECLARE @StartLimit INT
DECLARE @EndLimit INT

DECLARE @Tab_AccList TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_AccList SELECT CODE FROM udf_StringToTabl(@AccountList, ',')

DELETE REPORTDATA

CREATE TABLE #lt_amt (
	AccCode INT NOT NULL,
	Date DateTime Not Null,
	Amount Numeric(15,5) Not Null Default 0,
	Paid Numeric(15,5) Not Null Default 0,
	RowID INT IDENTITY(1,1) NOT NULL,
	DaysOld INT Not Null Default 0
)

CREATE TABLE #lt_pmt (
	AccCode INT NOT NULL,
	Amount Numeric(15,5) Not Null Default 0
)

CREATE TABLE #lt_interval (
	IntervalID INT IDENTITY (0,1) NOT NULL,
	LowerLimit INT Not Null Default 0,
	UpperLimit INT Not Null Default 0
)

SELECT @StartLimit = 0
WHILE @StartLimit <= @limit
BEGIN
	SELECT @EndLimit = @StartLimit + CASE @StartLimit WHEN 0 THEN 0 ELSE @interval - 1 END
	SELECT @EndLimit = CASE WHEN @EndLimit > @limit THEN @limit ELSE @EndLimit END

	INSERT INTO #lt_interval (LowerLimit, UpperLimit) 
	VALUES (@StartLimit, @EndLimit)

	SELECT @StartLimit = @EndLimit + 1
END

INSERT INTO #lt_interval (LowerLimit, UpperLimit) 
VALUES (@StartLimit, 99999999)

IF @type = 'C'
BEGIN
	INSERT INTO #lt_amt
	SELECT AccCode, Date, Amount=Debit, Paid=0, DaysOld=DATEDIFF(day, date, @l_date)
	FROM VirtualGL 
	WHERE	Date <= @l_Date AND 
		Debit > 0 AND 
		AccCode IN (SELECT CODE FROM @Tab_AccList)
	ORDER BY AccCode, Date, Debit

	INSERT INTO #lt_pmt
	SELECT AccCode, Amount=SUM(Credit)
	FROM VirtualGL 
	WHERE	Date <= @l_Date AND 
		Credit > 0 AND 
		AccCode IN (SELECT CODE FROM @Tab_AccList)
	GROUP BY AccCode
	ORDER BY AccCode
END
IF @type = 'S'
BEGIN
	INSERT INTO #lt_amt
	SELECT AccCode, Date, Amount=Credit, Paid=0, DaysOld=DATEDIFF(day, date, @l_date)
	FROM VirtualGL 
	WHERE 	Date <= @l_Date AND 
		Credit > 0 AND AccCode IN (SELECT CODE FROM @Tab_AccList)
	ORDER BY AccCode, Date, Credit

	INSERT INTO #lt_pmt
	SELECT AccCode, Amount=SUM(Debit)
	FROM VirtualGL 
	WHERE 	Date <= @l_Date AND 
		Debit > 0 AND AccCode IN (SELECT CODE FROM @Tab_AccList)
	GROUP BY AccCode
	ORDER BY AccCode
END

DECLARE C1 CURSOR FOR SELECT * FROM #lt_amt ORDER BY AccCode, Date, Amount
OPEN C1

FETCH NEXT FROM C1 INTO @AccCode, @TDate, @Amt, @Paid, @RowID, @DaysOld
WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @Pmt=ISNULL((SELECT ISNULL(Amount, 0) FROM #lt_pmt WHERE AccCode = @AccCode), 0)

	IF @Pmt <> 0
	BEGIN
		UPDATE #lt_amt
		SET Paid = Paid + CASE WHEN @Amt >= @Pmt THEN @Pmt ELSE @Amt END
		WHERE RowID = @RowID
	
		SELECT @Pmt = @Pmt - (SELECT CASE WHEN @Amt >= @Pmt THEN @Pmt ELSE @Amt END)
	
		UPDATE #lt_Pmt
		SET Amount = @Pmt 
		WHERE AccCode = @AccCode
	END

	FETCH NEXT FROM C1 INTO @AccCode, @TDate, @Amt, @Paid, @RowID, @DaysOld

END
CLOSE C1
DEALLOCATE C1

DELETE #lt_amt WHERE Amount - Paid = 0

IF @type = 'C'
BEGIN
	INSERT INTO ReportData (Code1, Name1, Name2, Name3, Name4, Name5, Value1, Code2, Code3)
	SELECT  
		Code1=Ar.AreaCode,
		Name1=Ar.Name,
		Name2=Ac.AliasName,
		Name3=Ac.Name,
		Name4=LEFT(LTRIM(RTRIM(C.Address1)) + ' ' + LTRIM(RTRIM(C.Address2)), 60),
		Name5=C.Phone,
		Value1 = SUM(Amount-Paid),
		Code2 = (SELECT MAX(LowerLimit) FROM #lt_interval 
			WHERE	l.daysold >= lowerlimit AND
				l.daysold <= upperlimit),
		Code3 = Ac.AccCode
	FROM #lt_amt l, Accounts Ac, Area Ar, Customer C
	WHERE 	l.AccCode = Ac.AccCode AND 
		Ac.AccCode = C.CustCode AND
		C.AreaCode = Ar.AreaCode
	GROUP BY
		Ar.AreaCode,
		Ar.Name,
		Ac.AccCode,
		Ac.Name,
		Ac.AliasName,
		C.Address1,
		C.Address2,
		C.Phone,
		l.DaysOld
END

IF @type = 'S'
BEGIN
	INSERT INTO ReportData (Code1, Name1, Name2, Name3, Name4, Name5, Value1, Code2, Code3)
	SELECT  
		Code1=0,
		Name1='All Supplier(s)',
		Name2=Ac.AliasName,
		Name3=Ac.Name,
		Name4=LEFT(LTRIM(RTRIM(S.Address1)) + ' ' + LTRIM(RTRIM(S.Address2)), 60),
		Name5=S.Phone,
		Value1 = SUM(Amount-Paid),
		Code2 = (SELECT MAX(LowerLimit) FROM #lt_interval 
			WHERE	l.daysold >= lowerlimit AND
				l.daysold <= upperlimit),
		Code3 = Ac.AccCode
	FROM #lt_amt l, Accounts Ac, Supplier S
	WHERE 	l.AccCode = Ac.AccCode AND 
		Ac.AccCode = S.SuppCode
	GROUP BY
		Ac.AccCode,
		Ac.Name,
		Ac.AliasName,
		S.Address1,
		S.Address2,
		S.Phone,
		l.DaysOld
END

DROP TABLE #lt_amt
DROP TABLE #lt_pmt
DROP TABLE #lt_interval
GO

