-- SP_BatchWiseSaleReturn_IssueBased (last defined by script catalog)
CREATE PROCEDURE SP_BatchWiseSaleReturn_IssueBased
	@ICode INT, @Batch VARCHAR(100), @Expiry DATETIME, @RetAbleQty NUMERIC(15, 4) OUTPUT
AS

SET @RetAbleQty =
	(SELECT Qty=SUM(ISNULL(Qty, 0))
	FROM
		(SELECT Qty=SUM(Qty) FROM IssueDetail
		WHERE ICode = @ICode AND Batch = @Batch AND Expiry = @Expiry
		UNION ALL
		SELECT Qty= - SUM(LooseQty) FROM SRDetail
		WHERE ICode = @ICode AND Batch = @Batch AND Expiry = @Expiry) A
	)
GO

