-- sp_changeitemdisc (last defined by script catalog)
CREATE Procedure [dbo].[sp_changeitemdisc] @changeOption Int, @code Int, @discpercno Int, @discperc Numeric(5,2), @usercode Int, @serverdatetime DateTime
As 
Declare @query VarChar(300) , @str_wherecondition VarChar(50), @str_discquery VarChar(50)
Declare @str_UserCode VarChar(10), @str_serverdatetime VarChar(20), @str_discperc VarChar(10), @str_Code VarChar(20)
Set @str_UserCode = Cast( @usercode As VarChar(10) )
Set @str_discperc = Cast( @discperc As VarChar(10) )
Set @str_serverdatetime = Convert ( VarChar(20) , @serverdatetime , 100 )
Set @str_code = Cast( @code As VarChar(20) )

IF ( ( @discpercno < 1 ) OR ( @discpercno > 5 )   )
	Return -1
IF ( ( @changeOption < 1 ) OR ( @changeOption > 4  )   )
	Return -1

IF @discpercno = 1
	Set @str_discquery = ' SaleDiscPerc = '  + @str_discperc
IF @discpercno = 2
	Set @str_discquery = ' SaleDiscPerc2 = '  + @str_discperc
IF @discpercno = 3
	Set @str_discquery = ' SaleDiscPerc3 = '  + @str_discperc
IF @discpercno = 4
	Set @str_discquery = ' SaleDiscPerc4 = '  + @str_discperc
IF @discpercno = 5
	Set @str_discquery = ' SaleDiscPerc5 = '  + @str_discperc

IF @changeOption = 1 
	Set @str_wherecondition = '  Where item.manfcode = ' + @str_code 
IF @changeOption = 2 
	Set @str_wherecondition = '  Where item.icatcode = ' + @str_code
IF @changeOption = 3 
	Set @str_wherecondition = '  Where item.iccode = ' + @str_code
IF @changeOption = 4
	Set @str_wherecondition = '  Where item.packcode = ' + @str_code

Set @str_wherecondition = @str_wherecondition + '  AND Item.Active=1' 

Set @query = ' Update  Item Set ChangeReason=''Change Discounts Cat Wise'', Module=''Change Discounts'', UserCode  = ' + @str_usercode + ' , LastUpdate = ''' + @str_serverdatetime + ''' , ' + @str_discquery + @str_wherecondition

Execute ( @query )

IF @@Error <> 0 
Begin
	RaisError('Unable to update item Salediscperc' , 16, 1)
	Return -1 
End

Return 0
GO

