CREATE PROCEDURE SP_Check_UserAttendance
	@UserCode SMALLINT, 
	@RowID INT OUTPUT
AS
/*
Author:M. Azhar Inayat
Purpose:
	The Purpose of this code is to return the latest Timein
	For the required user.
*/
