				GLDetail.GLVochCode <> 
				CASE @callermodule WHEN 'V' THEN 
						CASE WHEN @code IS NULL THEN -1 ELSE @code END ELSE -1 END  
			UNION ALL  
			SELECT M = 'Module: Bill Summary ' + char(13) + char(10) + 'Code: ' + RTRIM(LTRIM(STR(B.BillSummaryCode, 10)))
			FROM BillSummaryDetail BD, BillSummary B
			Where B.Posted = 'N' AND 
