-- SP_CopyInvoicesToSBuffer (last defined by script catalog)
CREATE PROCEDURE DBO.SP_CopyInvoicesToSBuffer
As    
DECLARE @errorno int, @rowsaffected int, @inv_posted_age INT

SET @inv_posted_age = DBO.Fn_Get_INT_Preference('AutoPurgePostedSaleTime')
IF @inv_posted_age IS NULL 
	SET @inv_posted_age = 30

BEGIN TRANSACTION MyTrans

Insert Into SBuffer
With (TabLockX) 
	(SaleInvCode, SaleCatCode, CustCode, SalesmanCode, Date, DiscPerc, FlatDisc, MiscCHARges,
	SalesTax, Posted, PostDate, Remarks, CustRefNo, headerno, headerinvno, OriginalDate, ModifiedBy,
	PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, RePrINTingCounter, CashReceived, InvGSTPerc1,
	PrINTWaranty, PrINTBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3, CustRefno4,
	GSTNO, InvTotal, MachineName, ModifyCounter, ItemDiscPercNo, RelationCode, DiseaseCode, WardCode,
	AdmissionCode, ReturnCounter, Paid, BillingDate, UnReceivedBalance, TotalOfSaleReturns, ListOfSrInvoices,
	prINTbalance, AccountFor, PaymentMode, PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt,
	Marked, Transferable, Transfered, TransferedOn, TransferedBy, Imported, ImportedBy, deliveredby, SaleTypeCode,
	Balance, PptCustCode, DELETED, PresCode, ImpactInventory,  SaleOrderCode, SaleComments1, SaleComments2,
	AlterSaleInvCode, RecurringInvoice, RecurringPeriod, LastRecurringInvCode, RecurringAgainst, ConsiderInPO,
	VisitCode, DueDate, SRBufferInvCode, CustRefNo5, GCCode, GRN, SuppInvCode, Vehicle, ShipTo, GuaranteePersonCode,
	CashTendered, CashCHARged, CashBack, CashAccCode, CustLicNo, CustLicExpiry, ModuleId, DocCode, SaleTypeInvNo,
	CRS_Transfered, CRS_TransferedOn, GuestCode, GuestCheckInCode, StudentCode, CustSiteCode, Transmit, Transmited,
	CurrencyCode, ConversionRate, ShipToCustomer,
	PreviousReading, CurrentReading, NextChange, Synced, SyncedOn, SyncedBy,
	MiscCharges1, MiscCharges2, MiscCharges3, MiscCharges4, MiscCharges5) 
Select  
	SaleInvCode, SaleCatCode, CustCode, SalesmanCode, Date, DiscPerc, FlatDisc, MiscCHARges,
	SalesTax, Posted, PostDate, Remarks, CustRefNo, headerno, headerinvno, OriginalDate, ModifiedBy,
	PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, RePrINTingCounter, CashReceived, InvGSTPerc1,
	PrINTWaranty, PrINTBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3, CustRefno4,
	GSTNO, InvTotal, MachineName, ModifyCounter, ItemDiscPercNo, RelationCode, DiseaseCode, WardCode,
	AdmissionCode, ReturnCounter, Paid, BillingDate, UnReceivedBalance, TotalOfSaleReturns, ListOfSrInvoices,
	prINTbalance, AccountFor, PaymentMode, PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt,
	Marked, Transferable, Transfered, TransferedOn, TransferedBy, Imported, ImportedBy, deliveredby, SaleTypeCode,
	Balance, PptCustCode, DELETED, PresCode, ImpactInventory,  SaleOrderCode, SaleComments1, SaleComments2,
	AlterSaleInvCode, RecurringInvoice, RecurringPeriod, LastRecurringInvCode, RecurringAgainst, ConsiderInPO,
	VisitCode, DueDate, SRBufferInvCode, CustRefNo5, GCCode, GRN, SuppInvCode, Vehicle, ShipTo, GuaranteePersonCode,
	CashTendered, CashCHARged, CashBack, CashAccCode, CustLicNo, CustLicExpiry, ModuleId, DocCode, SaleTypeInvNo,
	CRS_Transfered, CRS_TransferedOn, GuestCode, GuestCheckInCode, StudentCode, CustSiteCode, Transmit, Transmited,
	CurrencyCode, ConversionRate, ShipToCustomer,
	PreviousReading, CurrentReading, NextChange, Synced, SyncedOn, SyncedBy,
	MiscCharges1, MiscCharges2, MiscCharges3, MiscCharges4, MiscCharges5
From SaleLedger
Where SaleLedger.Posted = 'Y' AND 
	DateDiff ( Minute , PostDate , GetDate() ) >= @inv_posted_age AND
	SaleLedger.SaleInvCode Not In (Select SaleInvCode From SBuffer)

Select @errorno = @@error,  @rowsaffected = @@rowcount      
IF @errorno <> 0
BEGIN   
	ROLLBACK TRANSACTION MyTrans
	Return @errorno    
END
INSERT INTO SBufferDetail WITH (TABLOCKX) 
	(SaleInvcode, ICode, GCode, Batch, Expiry, PackQty, LooseQty,  PackUnits, SalePrice, AvgPrice, Rate,
	DiscPerc, SalesTax, RowID, Due, SatisfiedDate, itemflatdisc, SaleItemDescription, PackPrice, UnitSalesTax,
	GSTPerc, SaleUtn, bonusqty, claimable, balancestock, RowGroup, ClaimableDiscPerc, ManfDate, PackQtyForSale,
	BonusPackQtyForSale, SaleOrderRowID, DescICode, SourceSaleInvCode, SaleRowID, IssueRowID, PurUnitRate, 
	RPPUnitRate, TotalPieces, PiecesInHand, PackSalePrice, RefusalSaleRowID, AlternatePurPrice, CommissionPerUnit,
	CommissionPerc, AlternateCustomICode, BatchCost, ItemMeterCode, MeterReading, InsCode)
Select   
	SaleInvcode, ICode, GCode, Batch, Expiry, PackQty, LooseQty,  PackUnits, SalePrice, AvgPrice, Rate,
	DiscPerc, SalesTax, RowID, Due, SatisfiedDate, itemflatdisc, SaleItemDescription, PackPrice, UnitSalesTax,
	GSTPerc, SaleUtn, bonusqty, claimable, balancestock, RowGroup, ClaimableDiscPerc, ManfDate, PackQtyForSale,
	BonusPackQtyForSale, SaleOrderRowID, DescICode, SourceSaleInvCode, SaleRowID, IssueRowID, PurUnitRate, 
	RPPUnitRate, TotalPieces, PiecesInHand, PackSalePrice, RefusalSaleRowID, AlternatePurPrice, CommissionPerUnit,
	CommissionPerc, AlternateCustomICode, BatchCost, ItemMeterCode, MeterReading, InsCode
From SaleDetail
Where SaleDetail.SaleInvCode In 
		(Select DISTINCT SaleInvcode From SBuffer)
UNION ALL
Select   
	SaleInvcode, ICode, GCode, Batch, Expiry, PackQty=0, LooseQty,  PackUnits, SalePrice, AvgPrice, Rate,
	DiscPerc, SalesTax=0, RowID, Due='D', SatisfiedDate=GETDATE(), itemflatdisc, SaleItemDescription, PackPrice, UnitSalesTax,
	GSTPerc, SaleUtn, bonusqty, claimable, balancestock=0, RowGroup, ClaimableDiscPerc, ManfDate=GETDATE(), PackQtyForSale,
	BonusPackQtyForSale, SaleOrderRowID=NULL, DescICode, SourceSaleInvCode, SaleRowID, IssueRowID=NULL, PurUnitRate=0, 
	RPPUnitRate=0, TotalPieces=0, PiecesInHand=0, PackSalePrice=SalePrice, RefusalSaleRowID=NULL, AlternatePurPrice, CommissionPerUnit=0,
	CommissionPerc=0, AlternateCustomICode=NULL, BatchCost=0, ItemMeterCode=NULL, MeterReading=0, InsCode=NULL
From SaleInvDetail
Where SaleInvCode In 
		(Select DISTINCT SaleInvcode From SBuffer)

Select @errorno = @@error    
IF @errorno <> 0     
BEGIN
	ROLLBACK TRANSACTION MyTrans
	Return @errorno
END

UPDATE SRLedger SET SaleInvCode=NULL WHERE SaleInvCode IN (Select DISTINCT SaleInvcode From SBuffer)
Select @errorno = @@error    
IF @errorno <> 0     
BEGIN
	ROLLBACK TRANSACTION MyTrans
	Return @errorno
END

