	ROLLBACK TRANSACTION MyTrans
	Return @errorno
END

DELETE SaleDetailLog WHERE SaleInvCode IN (Select DISTINCT SaleInvcode From SBuffer)
Select @errorno = @@error,  @rowsaffected = @@rowcount      
IF @errorno <> 0     
BEGIN
	ROLLBACK TRANSACTION MyTrans
	Return @errorno
END

DELETE SaleSetsDetail WHERE SetCode IN (Select DISTINCT SetCode From SaleSetsHeader WHERE SaleInvCode IN (Select DISTINCT SaleInvcode From SBuffer))
