IF @errorno <> 0     
BEGIN
	ROLLBACK TRANSACTION MyTrans
	Return @errorno
END

DELETE SaleSetsHeader WHERE SaleInvCode IN (Select DISTINCT SaleInvcode From SBuffer)
Select @errorno = @@error,  @rowsaffected = @@rowcount      
IF @errorno <> 0     
BEGIN
	ROLLBACK TRANSACTION MyTrans
	Return @errorno
END

DELETE SaleDetail WHERE SaleInvCode IN (SELECT SaleInvCode FROM SBuffer)
Select @errorno = @@error,  @rowsaffected = @@rowcount      
IF @errorno <> 0     
