declare @an_outstandingamt numeric(15,2), @an_balance numeric(15,2)
declare @as_posted char(1)
Declare @Err As Int , @RowCount As Int, @TABMAXKEY As Int, @ai_vouchercode AS Int

EXECUTE @err = SP_GetTabMaxkey 'GLHeader', @TABMAXKEY Output
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RaisError('GL Voucher Code generation problem' ,16, 1)	
	RETURN -1			
END

SET @ai_vochcatcode = 5

EXECUTE @err = SP_GetVoucherCode @ai_vochcatcode, @ai_vouchercode Output
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RaisError('Voucher Code Generation Problem' ,16, 1)
	RETURN -1			
END

SET @ai_acccode = 2
SET @ad_date = GETDATE()
SET @as_posted = 'Y'
SET @ad_postdate = GETDATE()
SET @as_remarks = (SELECT ReceiptRemarks FROM SOReceipt WHERE SOReceiptCode=@ai_SOReceiptCode)
SET @ad_originaldate=GETDATE()
SET @ai_modifiedby=NULL
SET @ai_postedby=@ai_usercode
SET @as_chkno= (SELECT ReceiptRefNo FROM SOReceipt WHERE SOReceiptCode=@ai_SOReceiptCode)

EXECUTE @err = SP_SetGLHeader @TABMAXKEY, @ai_vochcatcode, @ai_acccode, @ad_date, @ai_usercode, @as_posted, @ad_postdate, @as_remarks, @ad_originaldate, @ai_modifiedby, @ai_postedby, @as_chkno, @ai_vouchercode
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RaisError('Problem Inserting Voucher (Table:GLHeader)' ,16, 1)
	RETURN -1			
END

INSERT INTO GLDetail (GLVochCode, AccCode, Debit, Credit, ChkNo, Remarks, GLUTN, PatientCode, InvoiceCode, OutStandingAmt, Balance, GuestCode, StudentCode)
SELECT @TABMAXKEY, AccCode, Debit=0.00, Credit=ISNULL(ReceiptAmt, 0), @as_chkno, @as_remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(ReceiptAmt, 0) <> 0
UNION ALL 
SELECT @TABMAXKEY, AccCode, Debit=0.00, Credit=ISNULL(WHTaxAmt,0), @as_chkno, @as_remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(WHTaxAmt,0) <> 0
UNION ALL /*Receipt Amt Debited*/
SELECT @TABMAXKEY, ReceiptAccCode, Debit=ISNULL(ReceiptAmt, 0), Credit=0.00, ReceiptRefNo, ReceiptRemarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(ReceiptAmt, 0) <> 0
UNION ALL /*Wholding Tax Amt credited*/
SELECT @TABMAXKEY, WHTaxAccCode, Debit=ISNULL(WHTaxAmt, 0), Credit=0.00, WHTaxRefNo, WHTaxRemarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(WHTaxAmt, 0) <> 0
/*Deduction 1 (if any)*/
UNION ALL 
SELECT @TABMAXKEY, Deduction1_Acccode, Debit=ISNULL(Deduction1, 0), Credit=0.00, Deduction1_Ref, Deduction1_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction1, 0) <> 0 AND Deduction1_Acccode IS NOT NULL
UNION ALL 
SELECT @TABMAXKEY, AccCode, Debit=0.00, Credit=ISNULL(Deduction1, 0), Deduction1_Ref, Deduction1_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction1, 0) <> 0 AND Deduction1_Acccode IS NOT NULL
/*Deduction 2 (if any)*/
UNION ALL 
SELECT @TABMAXKEY, Deduction2_Acccode, Debit=ISNULL(Deduction2, 0), Credit=0.00, Deduction2_Ref, Deduction2_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction2, 0) <> 0 AND Deduction2_Acccode IS NOT NULL
UNION ALL 
SELECT @TABMAXKEY, AccCode, Debit=0.00, Credit=ISNULL(Deduction2, 0), Deduction2_Ref, Deduction2_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction2, 0) <> 0 AND Deduction2_Acccode IS NOT NULL
/*Deduction 3 (if any)*/
UNION ALL 
SELECT @TABMAXKEY, Deduction3_Acccode, Debit=ISNULL(Deduction3, 0), Credit=0.00, Deduction3_Ref, Deduction3_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction3, 0) <> 0 AND Deduction3_Acccode IS NOT NULL
UNION ALL 
SELECT @TABMAXKEY, AccCode, Debit=0.00, Credit=ISNULL(Deduction3, 0), Deduction3_Ref, Deduction3_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction3, 0) <> 0 AND Deduction3_Acccode IS NOT NULL
/*Deduction 4 (if any)*/
UNION ALL 
SELECT @TABMAXKEY, Deduction4_Acccode, Debit=ISNULL(Deduction4, 0), Credit=0.00, Deduction4_Ref, Deduction4_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction4, 0) <> 0 AND Deduction4_Acccode IS NOT NULL
UNION ALL 
SELECT @TABMAXKEY, AccCode, Debit=0.00, Credit=ISNULL(Deduction4, 0), Deduction4_Ref, Deduction4_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction4, 0) <> 0 AND Deduction4_Acccode IS NOT NULL
/*Deduction 5 (if any)*/
UNION ALL 
SELECT @TABMAXKEY, Deduction5_Acccode, Debit=ISNULL(Deduction5, 0), Credit=0.00, Deduction5_Ref, Deduction5_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction5, 0) <> 0 AND Deduction5_Acccode IS NOT NULL
UNION ALL 
SELECT @TABMAXKEY, AccCode, Debit=0.00, Credit=ISNULL(Deduction5, 0), Deduction5_Ref, Deduction5_Remarks, GLUTN=NULL, PatientCode, InvoiceCode=NULL, OutStandingamt=0.00, Balance=0, GuestCode=Null, StudentCode=Null
FROM SOReceipt 
WHERE SOReceiptCode=@ai_SOReceiptCode AND ISNULL(Deduction5, 0) <> 0 AND Deduction5_Acccode IS NOT NULL

IF @@ERROR <> 0 OR @err <> 0 OR @@RowCount=0
BEGIN
	RaisError('Problem Inserting Voucher (Table:GLDetail)' ,16, 1)
	RETURN -1			
END

SET @GlVochCode = @TABMAXKEY
SET @VochCode   = @ai_vouchercode 
SET @ai_glvochcode=@TABMAXKEY

UPDATE SOReceipt 
SET GLVochCode=@GlVochCode, Posted='Y',PostedBy = @ai_usercode, PostDate=GETDATE()
WHERE SOReceiptCode=@ai_SOReceiptCode
IF @@ERROR <> 0 OR @err <> 0 OR @@RowCount=0
BEGIN
	RaisError('Problem Updating GL Voucher Code in (Table: SOReceipt)' ,16, 1)
	RETURN -1			
END

Return 0
GO

