-- SP_CRS_FetchFinalizedSaleOrders (last defined by script catalog)
CREATE PROCEDURE DBO.SP_CRS_FetchFinalizedSaleOrders
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20),
	@ClientInstanceID SMALLINT,
	@UserCode SMALLINT = NULL
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON
SET NOCOUNT ON
SET XACT_ABORT ON

DECLARE @err int, @LastSOCode INT, @RowID INT, @SOCount INT
DECLARE @Header_Qry VARCHAR(8000), @Detail_Qry VARCHAR(8000), @TablePrefix VARCHAR(255)
DECLARE @InstanceID_STR VARCHAR(100), @LogID_STR VARCHAR(100)

IF @UserCode IS NULL
	SET @UserCode=1

SET @TablePrefix = @SRV + '.' + @DB + '.' + @OWNER + '.'
SET @InstanceID_STR = LTRIM(RTRIM(CAST(@ClientInstanceID AS VARCHAR(100))))

Execute @err = sp_LockTabMaxkey 'SaleOrderHeader' , @LastSOCode Output
IF @@Error <> 0 OR @err <>  0
Begin
	RaisError('CRS Data Transfer Error: unable to fetch new sale order code', 16, 1)
	RETURN -1
End

CREATE TABLE #SOHeader (
	SaleOrderCode INT, CustCode SMALLINT, Date DATETIME, OriginalDate DATETIME, BillingDate DATETIME, 
	DiscPerc NUMERIC(6,2), FlatDisc NUMERIC(12,2), MiscCharges NUMERIC(12,2), InvGSTPerc1 NUMERIC(6,2), 
	InvTotal NUMERIC(12,2), SPrice SMALLINT, Remarks VARCHAR(100), 
	CustRefNo VARCHAR(100), CustRefNo2 VARCHAR(100), CustRefNo3 VARCHAR(100), CustRefNo4 VARCHAR(100), 
	DeliveryDeadLine DATETIME, NewSOCode INT NOT NULL DEFAULT (0),
	MyRowID INT IDENTITY(1,1)
)

CREATE TABLE #SODetail (
	SaleOrderCode INT, ICode INT, GCode SMALLINT, LooseQty NUMERIC(15,4), 
	PackUnits SMALLINT, SalePrice NUMERIC(12,2), DiscPerc NUMERIC(6,2), ItemFlatDisc NUMERIC(12,2), 
	SaleItemDescription VARCHAR(100), UnitSalesTax NUMERIC(12,2), GSTPerc NUMERIC(6,2), BonusQty NUMERIC(15,4),
	Remarks VARCHAR(100), Batch VARCHAR(100), Expiry DATETIME
)

SET @Header_Qry = 'SELECT SaleOrderCode, CustCode, Date, OriginalDate, BillingDate, DiscPerc, FlatDisc, MiscCharges, InvGSTPerc1, InvTotal, SPrice, Remarks, CustRefNo, CustRefNo2, CustRefNo3, CustRefNo4, DeliveryDeadLine FROM ' + @TablePrefix + 'SaleOrderHeader WHERE Finalized=''Y'' AND Posted=''N'' AND CRS_Sent=''N'' AND ClientInstanceID=' + @InstanceID_STR

INSERT INTO #SOHeader (SaleOrderCode, CustCode, Date, OriginalDate, BillingDate, DiscPerc, FlatDisc, MiscCharges, InvGSTPerc1, InvTotal, SPrice, Remarks, CustRefNo, CustRefNo2, CustRefNo3, CustRefNo4, DeliveryDeadLine) 
EXECUTE (@Header_Qry)
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RaisError('CRS Data Transfer Error: Fetching Sale Order Header Data From source', 16, 1)
	RETURN -1
END

SET @SOCount = ISNULL((SELECT COUNT(*) FROM #SOHeader), 0)
IF @SOCount <= 0
	RETURN 0

SET @Detail_Qry = 'SELECT SaleOrderCode, ICode, GCode=1, LooseQty, PackUnits, SalePrice, DiscPerc, ItemFlatDisc, SaleItemDescription, UnitSalesTax, GSTPerc, BonusQty, Remarks, Batch, Expiry FROM ' + @TablePrefix + 'SaleOrderDetail WHERE SaleOrderCode IN (SELECT SaleOrderCode FROM ' + @TablePrefix + 'SaleOrderHeader WHERE Finalized=''Y'' AND Posted=''N'' AND CRS_Sent=''N'' AND ClientInstanceID=' + @InstanceID_STR + ')'

INSERT INTO #SODetail (SaleOrderCode, ICode, GCode, LooseQty, PackUnits, SalePrice, DiscPerc, ItemFlatDisc, SaleItemDescription, UnitSalesTax, GSTPerc, BonusQty, Remarks, Batch, Expiry)
EXECUTE (@Detail_Qry)
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RaisError('CRS Data Transfer Error: Fetching Sale Order Detail Data From source', 16, 1)
	RETURN -1
END

UPDATE #SOHeader SET NewSOCode = @LastSOCode + MyRowID
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RaisError('CRS Data Transfer Error: Updating Identity Column in Temporary Sale Order Data', 16, 1)
	RETURN -1
END

UPDATE #SODetail SET SaleOrderCode = H.NewSOCode
FROM #SOHeader H, #SODetail D
WHERE H.SaleOrderCode = D.SaleOrderCode

INSERT INTO SaleOrderHeader (SaleOrderCode, CustCode, UserCode, Date, OriginalDate, BillingDate, DiscPerc, FlatDisc, MiscCharges, InvGSTPerc1, InvTotal, SPrice, Remarks, CustRefNo, CustRefNo2, CustRefNo3, CustRefNo4, DeliveryDeadLine, GRN)
SELECT NewSOCode, CustCode, @UserCode, Date, OriginalDate, BillingDate, DiscPerc, FlatDisc, MiscCharges, InvGSTPerc1, InvTotal, SPrice, Remarks, CustRefNo, CustRefNo2, CustRefNo3, CustRefNo4, DeliveryDeadLine, GRN=SaleOrderCode 
FROM #SOHeader
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RaisError('CRS Data Transfer Error: Error Inseting Sale Order Data', 16, 1)
	RETURN -1
END

INSERT INTO SaleOrderDetail (SaleOrderCode, ICode, GCode, LooseQty, PackUnits, SalePrice, DiscPerc, ItemFlatDisc, SaleItemDescription, UnitSalesTax, GSTPerc, BonusQty, Remarks, Batch, Expiry)
SELECT SaleOrderCode, ICode, GCode, LooseQty, PackUnits, SalePrice, DiscPerc, ItemFlatDisc, SaleItemDescription, UnitSalesTax, GSTPerc, BonusQty, Remarks, Batch, Expiry
FROM #SODetail
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RaisError('CRS Data Transfer Error: Error Inseting Sale Order Detail Data', 16, 1)
	RETURN -1
END

SET @LastSOCode = ISNULL((SELECT MAX(NewSOCode) FROM #SOHeader), 0)

Execute @err = sp_UpdateTabMaxkey 'SaleOrderHeader' , @LastSOCode
IF @@Error <> 0 OR @err <>  0
Begin
	RaisError('CRS Data Transfer Error: unable to update new sale order code', 16, 1)
	RETURN -1
End

SET @Header_Qry = 'Update ' + @TablePrefix + 'SaleOrderHeader SET CRS_Sent = ''Y'', CRS_SentOn = GETDATE(), Posted=''Y'', PostDate=GETDATE(), PostedBy=' + ltrim(rtrim(str(@userCode))) + ' WHERE Finalized=''Y'' AND Posted=''N'' AND CRS_Sent=''N'' AND ClientInstanceID=' + @InstanceID_STR
EXECUTE (@Header_Qry)
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RaisError('CRS Data Transfer Error: Error Marking Sale Order On source as Sent', 16, 1)
	RETURN -1
END

RETURN 0
GO

-- SP_CRS_GetClientInstanceInfo (last defined by script catalog)
CREATE PROCEDURE DBO.SP_CRS_GetClientInstanceInfo
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20),
	@InstanceName VARCHAR(100),
	@ClientID SMALLINT OUTPUT,
	@InstanceID SMALLINT OUTPUT
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DELETE REPORTDATA
DECLARE @qry VARCHAR(1000) 
SET @qry = 'INSERT INTO REPORTDATA (code1, code2, name1, name2) SELECT ClientInstanceID, ClientID, Name, Description FROM ' + @SRV + '.' + @DB + '.' + @OWNER + '.CRS_ClientInstance WHERE Name = ''' + @InstanceName + ''''
EXECUTE (@qry)
SET @InstanceID = (SELECT Code1 FROM REPORTDATA)
SET @ClientID = (SELECT Code2 FROM REPORTDATA)
GO

-- SP_CRS_GetLastCRSDataSendInfo (last defined by script catalog)
CREATE PROCEDURE DBO.SP_CRS_GetLastCRSDataSendInfo
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20),
	@ClientInstanceID SMALLINT OUTPUT,
	@StartDate DATETIME OUTPUT,
	@EndDate DATETIME OUTPUT,
	@UserCode SMALLINT OUTPUT
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON
DECLARE @InstanceName VARCHAR(100), @qry VARCHAR(1000), @ClientID SMALLINT, @InstanceID SMALLINT, @err INT

SET @InstanceName = ISNULL((SELECT Name FROM ClientInstance) ,'')

EXECUTE @err = DBO.SP_CRS_GetClientInstanceInfo @SRV, @DB, @OWNER, @InstanceName, @ClientID OUTPUT , @InstanceID OUTPUT
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RAISERROR('CRS Instance Verification: Unable to make CRS Instance Verification From CRS Server.', 16, 1)
	RETURN -1
END 

DELETE REPORTDATA
SET @qry = 'INSERT INTO REPORTDATA (code1, date1, date2, code2) SELECT ClientInstanceID, StartDate, EndDate, UserCode  FROM ' + @SRV + '.' + @DB + '.' + @OWNER + '.CRS_DataTransferLog WHERE ClientInstanceID = ' + LTRIM(RTRIM(STR(@InstanceID))) + ' AND LogID IN (SELECT LogID=MAX(LogID) FROM ' + @SRV + '.' + @DB + '.' + @OWNER + '.CRS_DataTransferLog WHERE ClientInstanceID = ' + LTRIM(RTRIM(STR(@InstanceID))) + ')'
EXECUTE (@qry)

SET @ClientInstanceID = (SELECT MAX(Code1) FROM REPORTDATA)
SET @StartDate = (SELECT MAX(Date1) FROM REPORTDATA)
SET @EndDate = (SELECT MAX(Date2) FROM REPORTDATA)
SET @UserCode = (SELECT MAX(Code2) FROM REPORTDATA)
GO

-- SP_CRS_GetTableKey (last defined by script catalog)
CREATE PROCEDURE DBO.SP_CRS_GetTableKey
	@table_id INT,
	@tablename NVARCHAR(255),
	@fulltablename NVARCHAR(255),
	@PKCOND VARCHAR(1000) OUTPUT, 
	@UPD_PKCOND VARCHAR(1000) OUTPUT, 
	@MAXCOL	VARCHAR(1000) OUTPUT
AS
DECLARE @ColName VARCHAR(255), @KeySeq SMALLINT, @CON NVARCHAR(50)
SET @CON = N'CONVERT(VarChar(10),'

DECLARE TmpCrs CURSOR FOR
SELECT
	COLNAME = CONVERT(sysname,c.name),
	KEYSEQ =
		CASE
			when c.name = index_col(@fulltablename, i.indid,  1) then convert (smallint,1)
			when c.name = index_col(@fulltablename, i.indid,  2) then convert (smallint,2)
			when c.name = index_col(@fulltablename, i.indid,  3) then convert (smallint,3)
			when c.name = index_col(@fulltablename, i.indid,  4) then convert (smallint,4)
			when c.name = index_col(@fulltablename, i.indid,  5) then convert (smallint,5)
			when c.name = index_col(@fulltablename, i.indid,  6) then convert (smallint,6)
			when c.name = index_col(@fulltablename, i.indid,  7) then convert (smallint,7)
			when c.name = index_col(@fulltablename, i.indid,  8) then convert (smallint,8)
			when c.name = index_col(@fulltablename, i.indid,  9) then convert (smallint,9)
			when c.name = index_col(@fulltablename, i.indid, 10) then convert (smallint,10)
			when c.name = index_col(@fulltablename, i.indid, 11) then convert (smallint,11)
			when c.name = index_col(@fulltablename, i.indid, 12) then convert (smallint,12)
			when c.name = index_col(@fulltablename, i.indid, 13) then convert (smallint,13)
			when c.name = index_col(@fulltablename, i.indid, 14) then convert (smallint,14)
			when c.name = index_col(@fulltablename, i.indid, 15) then convert (smallint,15)
			when c.name = index_col(@fulltablename, i.indid, 16) then convert (smallint,16)
		end
from
	sysindexes i, syscolumns c, sysobjects o
where
	o.id = @table_id
	and o.id = c.id
	and o.id = i.id
	and (i.status & 0x800) = 0x800
	and (c.name = index_col (@fulltablename, i.indid,  1) or
	     c.name = index_col (@fulltablename, i.indid,  2) or
	     c.name = index_col (@fulltablename, i.indid,  3) or
	     c.name = index_col (@fulltablename, i.indid,  4) or
	     c.name = index_col (@fulltablename, i.indid,  5) or
	     c.name = index_col (@fulltablename, i.indid,  6) or
	     c.name = index_col (@fulltablename, i.indid,  7) or
	     c.name = index_col (@fulltablename, i.indid,  8) or
	     c.name = index_col (@fulltablename, i.indid,  9) or
	     c.name = index_col (@fulltablename, i.indid, 10) or
	     c.name = index_col (@fulltablename, i.indid, 11) or
	     c.name = index_col (@fulltablename, i.indid, 12) or
	     c.name = index_col (@fulltablename, i.indid, 13) or
	     c.name = index_col (@fulltablename, i.indid, 14) or
	     c.name = index_col (@fulltablename, i.indid, 15) or
	     c.name = index_col (@fulltablename, i.indid, 16)
	    )
order by 2

OPEN TmpCrs

FETCH NEXT FROM TmpCrs INTO @ColName, @KeySeq
WHILE @@FETCH_STATUS = 0
BEGIN
	IF @KeySeq <> 1
	BEGIN
		SET @PKCOND = @PKCOND  + ' + '
		IF @KeySeq = 2
			SET @UPD_PKCOND = @UPD_PKCOND
		ELSE
			SET @UPD_PKCOND = @UPD_PKCOND + ' AND '
	END

	SET @PKCOND = @PKCOND + ' ' + @CON + LTRIM(RTRIM(@ColName)) + ')'
	IF @KeySeq <> 1
		SET @UPD_PKCOND = @UPD_PKCOND + ' S.' + LTRIM(RTRIM(@ColName)) + ' = ' + 'C.' + LTRIM(RTRIM(@ColName))
	SET @MAXCOL = 'MAX(' + RTRIM(LTRIM(@ColName)) + ')'	
	FETCH NEXT FROM TmpCrs INTO @ColName, @KeySeq
END
CLOSE TmpCrs
DEALLOCATE TmpCrs

RETURN 0
GO

-- SP_CRS_MONTHLYSALES (last defined by script catalog)
CREATE PROCEDURE DBO.SP_CRS_MONTHLYSALES @ar_startdate datetime, @ar_enddate datetime, @ai_pricetype INT , @ai_returns INT, @ai_bonus INT, @ai_allcust INT, @ai_custcode INT
AS

DELETE ReportData

INSERT INTO ReportData (date1, name1, code1, name2, name3, name4, code2, value1, value2, value3, name5, name6)
SELECT	
	st.Date,
	Name = ic.Name,
	Code = i.icatcode,
	Item = i.name,
	AliasName= i.customicode,
	PackingDesc= i.PackingDesc,
	St.Icode,
	Rate = Round(i.saleprice/case when i.packunits > 0 THEN i.packunits ELSE 1 END, 2),
	SaleQty	  =SUM(qty),
	SaleValue =SUM(CASE @ai_pricetype WHEN 1 THEN value ELSE Round(i.saleprice/case when i.packunits > 0 THEN i.packunits ELSE 1 END, 2) * qty END),
	Manfname=(SELECT M.Name FROM Manufacturer M WHERE M.ManfCode = I.ManfCode),
	Customer = CASE WHEN @ai_allcust = 0 THEN (SELECT A.Name FROM Accounts A WHERE A.AccCode = @ai_custcode) ELSE 'ALL CUSTOMERS' END
FROM
(SELECT	sd.icode,
	DATE= LTRIM(RTRIM(MONTH(SL.DATE))) + '-01-' + RTRIM(LTRIM(DATENAME(YEAR, SL.DATE))),
	qty = sum(sd.looseqty + CASE @ai_bonus WHEN 0 THEN 0 ELSE sd.bonusqty END + sd.packqty * sd.packunits),
	value = sum((sd.looseqty + sd.packqty * sd.packunits) *
		(sd.saleprice - sd.itemflatdisc) * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01))
FROM 
	CRS_ClientInstance CI, 
	CRS_ClientList CL,
	CRS_SaleLedger SL,
	CRS_SaleDetail SD,
	(select c.custcode from customer c WHERE @ai_allcust = 0 AND C.CustCode = @ai_custcode
	UNION 
	select c.custcode from customer c WHERE @ai_allcust = 1) CS
WHERE
	CL.ClientID = CI.ClientID AND 
	CI.ClientInstanceID = SL.ClientInstanceID AND
	CI.ClientInstanceID = SD.ClientInstanceID AND
	SL.ClientInstanceID = SD.ClientInstanceID AND
	SL.SaleInvCode = SD.SaleInvCode AND 
	sl.posted = 'Y' AND 
	sl.custcode = CS.CustCode AND
	sl.date BETWEEN @ar_startdate and @ar_enddate
Group By sd.icode, sl.date
UNION ALL
select	sd.icode,
	DATE=LTRIM(RTRIM(MONTH(DATE))) + '-01-' + RTRIM(LTRIM(DATENAME(YEAR, DATE))),
	qty = -sum(sd.looseqty + CASE @ai_bonus WHEN 0 THEN 0 ELSE sd.bonusqty END + sd.packqty * sd.packunits),
	value = -sum((sd.looseqty + sd.packqty * sd.packunits) *
		sd.srprice * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01))
FROM
	CRS_ClientInstance CI, 
	CRS_ClientList CL,
	CRS_SrLedger SL,
	CRS_SrDetail SD,
	(select c.custcode from customer c WHERE @ai_allcust = 0 AND C.CustCode = @ai_custcode
	UNION 
	select c.custcode from customer c WHERE @ai_allcust = 1) CS
WHERE
	CL.ClientID = CI.ClientID AND 
	CI.ClientInstanceID = SL.ClientInstanceID AND
	CI.ClientInstanceID = SD.ClientInstanceID AND
	SL.ClientInstanceID = SD.ClientInstanceID AND
	SL.SrInvCode = SD.SrInvCode AND 
	sl.posted = 'Y' AND 
	sl.custcode = CS.CustCode AND
	sl.date BETWEEN @ar_startdate and @ar_enddate AND
	@ai_returns = 1
Group By sd.icode, sl.date) St, 
	Item i, itemcategory ic
WHERE st.icode = i.icode and i.icatcode = ic.icatcode
GROUP BY St.icode, i.name, i.customicode, st.date, i.icatcode, ic.Name, i.manfcode, i.saleprice, i.packunits, i.PackingDesc
ORDER BY st.date, ic.name, i.icatcode, i.name, i.customicode, St.icode
GO

