DECLARE @ClientID INT, @ClientInstanceID INT, @Name VARCHAR(100), @LastSynced DATETIME

SELECT @Name = RTRIM(LTRIM(Name)), @ClientID = ClientID, @ClientInstanceID = ClientInstanceID  FROM ClientInstance
IF @Name IS NULL OR @Name = '' 
BEGIN
