-- SP_CRS_VirtualGL_Sales (last defined by script 7810)
CREATE PROCEDURE dbo.SP_CRS_VirtualGL_Sales
AS

SET NOCOUNT ON

DECLARE @ln_purchaseacc NUMERIC(5, 0), @ln_cashacc NUMERIC(5, 0), @ln_equityacc NUMERIC(5, 0), @ln_invacc NUMERIC(5, 0), @ln_cgs NUMERIC(5, 0),
	@ln_salesacc NUMERIC(5, 0), @ln_salesretacc NUMERIC(5, 0), @ln_purchaseretacc NUMERIC(5, 0),
	@ln_revfromservice NUMERIC(5, 0), @ln_salestaxacc NUMERIC(5, 0),
	@ln_AdvIncomeTaxSale NUMERIC(5, 0), @ln_fbrposfeeacc NUMERIC(5,0)
DECLARE @SRemks CHAR(1), @InvSys CHAR(1), @RoundUpYo TINYINT, @AdvIncomeTax CHAR(1)

SET @AdvIncomeTax = ISNULL((SELECT a=DBO.Fn_GetPreference('ApplyAdvanceIncomeTaxInSale')), 'N')
SET @RoundUpYo = (SELECT A=dbo.Fn_Get_Int_Preference('roundsaleinvon'))
SET @InvSys = ISNULL((SELECT a=DBO.Fn_GetPreference( 'InventorySystemUsed')), 'P')
SET @ln_invacc = (SELECT code FROM global WHERE name = 'GT_InventoryAcc')
SET @ln_cgs = (SELECT code FROM global WHERE name = 'GT_CostOfGoodsSoldAcc')
SET @ln_cashacc     = (SELECT code FROM global WHERE name = 'GT_CashACC')
SET @ln_salesacc    = (SELECT code FROM global WHERE name = 'GT_SalesACC')
SET @ln_salesretacc = (SELECT code FROM global WHERE name = 'GT_SalesReturnACC')
SET @ln_salestaxacc	= (SELECT code FROM global WHERE name = 'GT_AdvanceSalesTaxACC')
SET @ln_AdvIncomeTaxSale = (SELECT code FROM global WHERE name = 'GT_AdvIncomeTaxSale')
SET @ln_fbrposfeeacc = (SELECT code FROM global WHERE name = 'GT_FBRPOSFeeAcc')

SET @SRemks = (SELECT a=DBO.Fn_GetPreference( 'ShowSaleRemarksInLedger' ))

CREATE TABLE #lsl (clientinstanceid smallint not null, code INT NOT NULL)

INSERT INTO #lsl
SELECT  S.Clientinstanceid, S.SaleInvCode 
FROM CRS_SaleLedger S
WHERE S.Posted = 'Y' and S.AccountFor = 'Y' AND 
	NOT EXISTS (SELECT DISTINCT V.ClientInstanceid, V.DocumentCode FROM CRS_VirtualGL V WHERE V.DocumentType IN ('SV') AND V.ClientInstanceid = S.ClientInstanceid AND V.DocumentCode = S.SaleInvCode)

INSERT INTO CRS_VirtualGLTemp	/*accounting for sales*/
SELECT  S.Clientinstanceid, documentcode = S.saleinvcode, documenttype    = 'SV', catcode = S.SaleCatCode,
	dr_acccode = CASE S.saleCatCode	WHEN 1 THEN S.CashAccCode /* Cash Sale */
		WHEN 3 THEN S.CashAccCode /* Cash Sale */ ELSE S.custcode /* Credit Sale */ END,
	cr_acccode = @ln_salesacc,
	AlternateAccCode = CASE S.saleCatCode WHEN 1 THEN S.custcode  /* Cash Sale */
		WHEN 3 THEN S.custcode  /* Cash Sale */ ELSE Null END,
	Date    = S.date,
	SaleTax=Round(
	SUM( (D.looseqty + D.bonusqty) * D.unitsalestax) + 
	SUM(ROUND( (D.looseqty * (D.saleprice - D.itemflatdisc)) *
		(1 - (.01 * D.discperc)) * D.gstperc * .01, 2)) +
	ROUND( (SUM((D.looseqty * (D.saleprice - D.itemflatdisc)) *
		(1 - (.01 * D.discperc))) * (1- (.01 * S.discperc)) -
		S.flatdisc) * (S.invgstperc1 * .01), 2), @RoundUpYo),
	Gross=Round(
	SUM((D.looseqty * (D.saleprice - D.itemflatdisc)) *
		(1 - (.01 * D.discperc))) * (1- (.01 * S.discperc)) + 
		S.misccharges + S.salestax - S.flatdisc, @RoundUpYo),
	dr_remarks = CASE @SRemks WHEN 'Y' THEN S.Remarks
			ELSE CASE S.SaleCatCode WHEN 3 THEN 'Cash receipt on sale #: '
				WHEN 1 THEN 'Cash receipt on sale #: ' 
				ELSE 'Receivable on cr. sale #: ' END +
				RTRIM(LTRIM(CONVERT(VARCHAR(12), S.saleinvcode))) 
			END,
	cr_remarks = 'Revenue from ' + CASE S.SaleCatCode WHEN 3 THEN 'cash' 
			WHEN 1 THEN 'cash' ELSE 'cr.' END + ' sale #: ' + 
			RTRIM(LTRIM(CONVERT(VARCHAR(12), S.saleinvcode))),
	saletax_remarks= 'S.Tax ' + CASE S.SaleCatCode WHEN 3 THEN 'received' 
		WHEN 1 THEN 'received' ELSE 'receivable' END + ' on ' + 
		CASE S.SaleCatCode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash'
		ELSE 'cr.' END + ' sale #: ' + RTRIM(LTRIM(CONVERT(VARCHAR(12), S.saleinvcode))),
	CheckNo = NULL, 
	UserCode= S.salesmancode, vouchercode= S.saleinvcode, invoicecode= S.saleinvcode,
	invoicetype = 1 /*1 stands for sales*/,
	Amt = CASE S.SaleCatCode WHEN 2 THEN S.Amt ELSE 0 END,
	DrAmtAccCode = S.PaymentAccCode, CrAmtAccCode = S.Custcode, 
	AmtBy = S.AmtBy, AmtDate = S.AmtDate, AmtRef = S.AmtReference, 
	OutstandingAmt = S.OutstandingAmt, Balance = 0,
	PatientCode=CASE WHEN S.PatientCode IS NULL THEN 
					CASE WHEN S.AdmissionCode IS NULL THEN NULL
					ELSE (SELECT A.Patientcode FROM PatientAdmission A WHERE S.AdmissionCode = A.AdmissionCode)
					END
				ELSE S.PatientCode END,
	GRN = S.GRN, GCCode = S.GCCode, Vehicle = S.Vehicle, ShipTo = S.ShipTo, S.GuestCode, S.StudentCode, CGS=ISNULL(SUM((D.LooseQty + D.BonusQty) * D.AvgPrice), 0),
	S.CurrencyCode, S.ConversionRate,
	AdvIncomeTax = CASE WHEN @AdvIncomeTax = 'Y' THEN ISNULL(S.AdvanceTaxAmt,0) ELSE 0 END, S.FBRPosFee
FROM CRS_Saleledger S, CRS_Saledetail D
WHERE STR(S.Clientinstanceid, 10) + STR(S.saleinvcode, 10) IN (SELECT STR(#lsl.ClientInstanceid,10) + STR(#lsl.Code,10) FROM #lsl) AND
	S.Clientinstanceid = D.Clientinstanceid AND
	S.saleinvcode = D.saleinvcode 
GROUP BY S.Clientinstanceid, S.saleinvcode, S.custcode, S.salecatcode, S.date, S.discperc, S.misccharges, 
	S.salestax, S.flatdisc, S.invgstperc1, S.salesmancode, S.Amt, S.PaymentAccCode,
	S.AmtBy, S.AmtDate, S.AmtReference, S.OutstandingAmt, S.patientcode, S.admissioncode, S.Remarks,
	S.GRN, S.GCCode, S.Vehicle, S.ShipTo, S.CashAccCode, S.GuestCode, S.StudentCode, S.CurrencyCode, S.ConversionRate, S.AdvanceTaxAmt, S.FBRPosFee

INSERT INTO CRS_VirtualGLTemp	/*accounting for sales having impactinventory='Y' and account for ='Y'*/
SELECT  S.Clientinstanceid, documentcode = S.saleinvcode, documenttype    = 'SV', catcode = S.SaleCatCode,
	dr_acccode = CASE S.saleCatCode	WHEN 1 THEN S.CashAccCode /* Cash Sale */ 
		WHEN 3 THEN S.CashAccCode /* Cash Sale */ ELSE S.custcode /* Credit Sale */ END,
	cr_acccode = @ln_salesacc,
	AlternateAccCode = CASE S.saleCatCode WHEN 1 THEN S.custcode /* Cash Sale */
		WHEN 3 THEN S.custcode  /* Cash Sale */ ELSE Null END,
	Date    = S.date,
	SaleTax=Round(
	SUM( (D.looseqty + D.bonusqty) * D.unitsalestax) + 
	SUM(ROUND( (D.looseqty * (D.saleprice - D.itemflatdisc)) * (1 - (.01 * D.discperc)) * D.gstperc * .01, 2)) +
	ROUND( (SUM((D.looseqty * (D.saleprice - D.itemflatdisc)) *
		(1 - (.01 * D.discperc))) * (1- (.01 * S.discperc)) -
		S.flatdisc) * (S.invgstperc1 * .01), 2), @RoundUpYo),
	Gross=Round(
	SUM((D.looseqty * (D.saleprice - D.itemflatdisc)) *	(1 - (.01 * D.discperc))) * (1- (.01 * S.discperc)) + 
		S.misccharges + S.salestax - S.flatdisc, @RoundUpYo),
	dr_remarks = CASE @SRemks WHEN 'Y' THEN S.Remarks
		ELSE CASE S.SaleCatCode WHEN 3 THEN 'Cash receipt on sale #: '
			WHEN 1 THEN 'Cash receipt on sale #: ' ELSE 'Receivable on cr. sale #: ' END +
			RTRIM(LTRIM(CONVERT(VARCHAR(12), S.saleinvcode))) 
		END,
	cr_remarks = 'Revenue from ' + CASE S.SaleCatCode WHEN 3 THEN 'cash' 
		WHEN 1 THEN 'cash' ELSE 'cr.' END + ' sale #: ' + RTRIM(LTRIM(CONVERT(VARCHAR(12), S.saleinvcode))),
	saletax_remarks= 'S.Tax ' + CASE S.SaleCatCode WHEN 3 THEN 'received'
		WHEN 1 THEN 'received' ELSE 'receivable' END + ' on ' + 
		CASE S.SaleCatCode WHEN 3 THEN 'cash' WHEN 1 THEN 'cash' ELSE 'cr.' END + ' sale #: ' + 
		RTRIM(LTRIM(CONVERT(VARCHAR(12), S.saleinvcode))),
	CheckNo = NULL, 
	UserCode= S.salesmancode, vouchercode= S.saleinvcode, invoicecode= S.saleinvcode,
	invoicetype = 1 /*1 stands for sales*/,
	Amt = CASE S.SaleCatCode WHEN 2 THEN S.Amt ELSE 0 END,
	DrAmtAccCode = S.PaymentAccCode, CrAmtAccCode = S.Custcode,
	AmtBy = S.AmtBy, AmtDate = S.AmtDate, AmtRef = S.AmtReference,
	OutstandingAmt = S.OutstandingAmt, Balance = 0,
	PatientCode=CASE WHEN S.PatientCode IS NULL THEN 
					CASE WHEN S.AdmissionCode IS NULL THEN NULL
					ELSE (SELECT A.Patientcode FROM PatientAdmission A WHERE S.AdmissionCode = A.AdmissionCode)
					END
				ELSE S.PatientCode END,
	GRN = S.GRN, GCCode = S.GCCode, Vehicle = S.Vehicle, ShipTo = S.ShipTo, S.GuestCode, S.StudentCode, CGS=0,
	S.CurrencyCode, S.ConversionRate,
	AdvIncomeTax = CASE WHEN @AdvIncomeTax = 'Y' THEN ISNULL(S.AdvanceTaxAmt,0) ELSE 0 END, S.FBRPosFee
FROM CRS_Saleledger S, CRS_Saleinvdetail D
WHERE STR(S.Clientinstanceid, 10) + STR(S.saleinvcode, 10) IN (SELECT STR(#lsl.ClientInstanceid,10) + STR(#lsl.Code,10) FROM #lsl) AND
	S.Clientinstanceid = D.Clientinstanceid AND
	S.saleinvcode = D.saleinvcode 
GROUP BY S.Clientinstanceid, S.saleinvcode, S.custcode, S.salecatcode, S.date, S.discperc, S.misccharges,
	S.salestax, S.flatdisc, S.invgstperc1, S.salesmancode, S.Amt, S.PaymentAccCode,
	S.AmtBy, S.AmtDate, S.AmtReference, S.OutstandingAmt, S.patientcode, S.admissioncode, S.Remarks,
	S.GRN, S.GCCode, S.Vehicle, S.ShipTo, S.CashAccCode, S.GuestCode, S.StudentCode, S.CurrencyCode, S.ConversionRate, S.AdvanceTaxAmt, S.FBRPosFee

INSERT INTO CRS_VirtualGLTemp	/*accounting for cash received via master cash window during sales*/
SELECT  S.Clientinstanceid, documentcode = S.saleinvcode, documenttype    = 'SV', catcode = S.SaleCatCode,
	dr_acccode = S.CashAccCode,
	cr_acccode = S.CustCode,
	AlternateAccCode = Null, Date    = S.date, SaleTax= 0,
	Gross = S.CashCharged,
	dr_remarks = 'Cash Received on Sale Inv. No.' + LTRIM(RTRIM(STR(S.SaleInvCode, 10))), 
	cr_remarks = 'Cash Received on Sale Inv. No.' + LTRIM(RTRIM(STR(S.SaleInvCode, 10))),
	saletax_remarks= '', CheckNo = NULL, 
	UserCode= S.salesmancode, vouchercode= S.saleinvcode, invoicecode= S.saleinvcode,
	invoicetype = 1 /*1 stands for sales*/,
	Amt = 0, DrAmtAccCode = NULL, CrAmtAccCode = NULL, AmtBy = NULL, AmtDate = NULL,
	AmtRef = NULL, OutstandingAmt = S.OutstandingAmt, Balance = 0,
	PatientCode=CASE WHEN S.PatientCode IS NULL THEN 
					CASE WHEN S.AdmissionCode IS NULL THEN NULL
					ELSE (SELECT A.Patientcode FROM PatientAdmission A WHERE S.AdmissionCode = A.AdmissionCode)
					END
				ELSE S.PatientCode END,
	GRN = S.GRN, GCCode = S.GCCode, Vehicle = S.Vehicle, ShipTo = S.ShipTo, S.GuestCode, S.StudentCode, CGS=0, S.CurrencyCode, S.ConversionRate,
	AdvIncomeTax = 0.00, FBRPosFee=0.00
FROM CRS_saleledger S
WHERE S.SaleCatCode NOT IN (1, 3) AND S.CashCharged > 0 AND
	STR(S.Clientinstanceid, 10) + STR(S.saleinvcode, 10) IN (SELECT STR(#lsl.ClientInstanceid,10) + STR(#lsl.Code,10) FROM #lsl)
UNION ALL
SELECT  S.Clientinstanceid, documentcode = S.saleinvcode, documenttype    = 'SV', catcode = S.SaleCatCode,
	dr_acccode = D.AccCode,
	cr_acccode = S.CustCode,
	AlternateAccCode = Null, Date    = S.date, SaleTax= 0,
	Gross = Amount,
	dr_remarks = D.Remarks, cr_remarks = D.Remarks,
	saletax_remarks= '', CheckNo = NULL, 
	UserCode= S.salesmancode, vouchercode= S.saleinvcode, invoicecode= S.saleinvcode,
	invoicetype = 1 /*1 stands for sales*/,
	Amt = 0, DrAmtAccCode = NULL, CrAmtAccCode = NULL, AmtBy = NULL, AmtDate = NULL,
	AmtRef = NULL, OutstandingAmt = S.OutstandingAmt, Balance = 0,
	PatientCode=CASE WHEN S.PatientCode IS NULL THEN 
					CASE WHEN S.AdmissionCode IS NULL THEN NULL
					ELSE (SELECT A.Patientcode FROM PatientAdmission A WHERE S.AdmissionCode = A.AdmissionCode)
					END
				ELSE S.PatientCode END,
	GRN = S.GRN, GCCode = S.GCCode, Vehicle = S.Vehicle, ShipTo = S.ShipTo, S.GuestCode, S.StudentCode, CGS=0, S.CurrencyCode, S.ConversionRate,
	AdvIncomeTax = 0.00, FBRPosFee=0.00
FROM CRS_saleledger S, CRS_CashierWindow D
WHERE STR(S.Clientinstanceid, 10) + STR(S.saleinvcode, 10) IN (SELECT STR(#lsl.ClientInstanceid,10) + STR(#lsl.Code,10) FROM #lsl) AND 
	S.saleinvcode = D.saleinvcode 

TRUNCATE TABLE #lsl
GO

-- SP_CRS_VirtualGL_SalesReturn (last defined by script 7829)
CREATE PROCEDURE dbo.SP_CRS_VirtualGL_SalesReturn
AS

SET NOCOUNT ON

DECLARE @ln_purchaseacc NUMERIC(5, 0), @ln_cashacc NUMERIC(5, 0), @ln_equityacc NUMERIC(5, 0), @ln_invacc NUMERIC(5, 0), @ln_cgs NUMERIC(5, 0),
	@ln_salesacc NUMERIC(5, 0), @ln_salesretacc NUMERIC(5, 0), @ln_purchaseretacc NUMERIC(5, 0),
	@ln_revfromservice NUMERIC(5, 0), @ln_salestaxacc NUMERIC(5, 0)

DECLARE @SRRemks CHAR(1), @InvSys CHAR(1), @RoundUpYo TINYINT

SET @RoundUpYo = (SELECT A=dbo.Fn_Get_Int_Preference('roundsalereturninvon'))
SET @InvSys = ISNULL((SELECT a=DBO.Fn_GetPreference( 'InventorySystemUsed')), 'P')

SET @ln_invacc = (SELECT code FROM global WHERE name = 'GT_InventoryAcc')
SET @ln_cgs = (SELECT code FROM global WHERE name = 'GT_CostOfGoodsSoldAcc')
SET @ln_cashacc     = (SELECT code FROM global WHERE name = 'GT_CashACC')
SET @ln_salesacc    = (SELECT code FROM global WHERE name = 'GT_SalesACC')
SET @ln_salesretacc = (SELECT code FROM global WHERE name = 'GT_SalesReturnACC')
SET @ln_salestaxacc	= (SELECT code FROM global WHERE name = 'GT_AdvanceSalesTaxACC')

SET @SRRemks = (SELECT a=DBO.Fn_GetPreference( 'ShowSRetRemarksInLedger' ))

CREATE TABLE #lt_sret (clientinstanceid smallint not null, code INT NOT NULL)

INSERT INTO #lt_sret
SELECT  S.Clientinstanceid, S.SRInvCode 
FROM CRS_SRLedger S
WHERE S.posted = 'Y' and S.accountfor = 'Y' AND
	NOT EXISTS (SELECT DISTINCT V.ClientInstanceid, V.DocumentCode FROM CRS_VirtualGL V WHERE V.DocumentType IN ('SR') AND V.ClientInstanceid = S.ClientInstanceid AND V.DocumentCode = S.SRInvCode)

INSERT INTO CRS_VirtualGLTemp	/*accounting for sales return*/
SELECT  S.Clientinstanceid, documentcode = S.srinvcode, documenttype = 'SR', catcode = S.SRCatCode,
	dr_acccode = @ln_salesretacc,
	cr_acccode = CASE S.srCatCode WHEN 6 THEN S.CashAccCode /* Cash S/Return*/ 
		WHEN 8 THEN S.CashAccCode /* Cash S/Return*/ ELSE S.custcode /* Credit S/Return*/ END,
	AlternateAccCode = CASE S.srCatCode WHEN 6 THEN S.custcode /* Cash S/Return*/
		WHEN 8 THEN S.custcode /* Cash S/Return*/ ELSE NULL /* Credit S/Return*/ END,
	Date    = S.date,
	SaleTax=ROUND(
		SUM( (D.looseqty + D.bonusqty) * D.unitsalestax) + 
		SUM(ROUND( (D.looseqty * D.srprice) * (1 - (.01 * D.discperc)) * D.gstperc * .01, 2)) +
		ROUND( (sum( (D.looseqty * D.srprice) * (1 - (.01 * D.discperc))) * 
			(1- (.01 * S.discperc)) - S.flatdisc) * (S.invgstperc1 * .01), 2), @RoundUpYo),
	Gross= Round( sum( (D.looseqty * D.srprice) * (1 - (.01 * D.discperc))) * 
		    (1- (.01 * S.discperc)) + S.misccharges + S.salestax - S.flatdisc, @RoundUpYo),
	dr_remarks = 'Revenue (reversal) on ' + CASE S.SRCatCode WHEN 6 THEN 'cash'
		WHEN 8 THEN 'cash' ELSE 'cr.' END + ' sale ret. #: ' + 
		RTRIM(LTRIM(CONVERT(VARCHAR(12), S.srinvcode))) + 
		CASE WHEN S.saleinvcode is null Then '' 
		     ELSE ', Sale #:' + RTRIM(LTRIM(CONVERT(VARCHAR(12), S.saleinvcode))) END,
	cr_remarks = CASE @SRRemks WHEN 'Y' THEN S.Remarks
		ELSE CASE S.SRCatCode WHEN 6 THEN 'Cash paid on sale ret.#: '
			WHEN 8 THEN 'Cash paid on sale ret.#: ' ELSE 'Payable on cr. sale ret.#: ' END +
			RTRIM(LTRIM(CONVERT(VARCHAR(12), S.srinvcode))) + 
			CASE WHEN S.saleinvcode is null Then '' 
			     ELSE ', Sale #:' + RTRIM(LTRIM(CONVERT(VARCHAR(12), S.saleinvcode))) END
		END,
	saletax_remarks= 'S.Tax ' + 
		CASE S.SRCatCode WHEN 6 THEN 'Paid' WHEN 8 THEN 'Paid' ELSE 'Payable' END + 
		' on sale ret. #: ' +  RTRIM(LTRIM(CONVERT(VARCHAR(12), S.srinvcode)))+ 
		CASE WHEN S.saleinvcode is null Then '' 
		     ELSE ', sale #:' + RTRIM(LTRIM(CONVERT(VARCHAR(12), S.saleinvcode))) END,
	CheckNo = NULL, 
	UserCode= ISNULL(S.salesmancode, 0), vouchercode= S.srinvcode, invoicecode= S.srinvcode,
	invoicetype = 3 /*3 stands for sales return*/,
	Amt =  CASE S.SRCatCode WHEN 8 THEN 0 ELSE S.Amt END,
	DrAmtAccCode = S.Custcode, CrAmtAccCode = S.PaymentAccCode, AmtBy = S.AmtBy,
	AmtDate = S.AmtDate, AmtRef = S.AmtReference,
	OutstandingAmt = S.OutstandingAmt, Balance = 0,
	PatientCode=CASE WHEN S.PatientCode IS NULL THEN 
			CASE WHEN S.AdmissionCode IS NULL THEN NULL
			ELSE (SELECT A.Patientcode FROM PatientAdmission A WHERE S.AdmissionCode = A.AdmissionCode)
			END
		ELSE S.PatientCode END,
	GRN = NULL, GCCode = NULL, Vehicle = NULL, ShipTo = NULL, S.GuestCode, S.StudentCode,
	CGS=ISNULL(SUM((D.looseqty + D.bonusqty) * CASE WHEN S.SaleInvCode > 0 THEN D.AvgPrice ELSE (D.SRPrice * (1 - D.DiscPerc * 0.01) * (1 - S.DiscPerc * 0.01)) END),0),
	S.CurrencyCode, S.ConversionRate, AdvIncomeTax=ISNULL(S.AdvanceTaxAmt,0), FBRPosFee= ISNULL(S.FBRPosFee,0)
FROM CRS_SRledger S, CRS_SRdetail D
WHERE STR(S.Clientinstanceid, 10) + STR(S.srinvcode, 10) IN (SELECT STR(#lt_sret.ClientInstanceid,10) + STR(#lt_sret.Code,10) FROM #lt_sret) AND
	S.Clientinstanceid = D.Clientinstanceid AND
	S.srinvcode = D.srinvcode 
GROUP BY S.Clientinstanceid, S.srinvcode, S.custcode, S.srcatcode, S.CashAccCode, S.date, S.discperc, S.misccharges,
	 S.salestax, S.flatdisc, S.invgstperc1, S.salesmancode, S.saleinvcode, S.Amt,
	 S.PaymentAccCode, S.AmtBy, S.AmtDate, S.AmtReference, S.OutstandingAmt,
	 S.PatientCode, S.AdmissionCode, S.CashAccCode, S.Remarks,
	 S.GuestCode, S.StudentCode, S.CurrencyCode, S.ConversionRate, S.AdvanceTaxAmt, S.FBRPosFee

INSERT INTO CRS_VirtualGLTemp	/*accounting for cash received via master cash window during sales*/
SELECT  S.Clientinstanceid, documentcode = S.srinvcode, documenttype = 'SR', catcode = S.SRCatCode,
	dr_acccode = S.CustCode,
	cr_acccode = S.CashAccCode,
	AlternateAccCode = Null, Date    = S.date, SaleTax= 0,
	Gross = S.CashCharged,
	dr_remarks = 'Cash Paid on S/R No.' + LTRIM(RTRIM(STR(S.SRInvCode, 10))), 
	cr_remarks = 'Cash Paid on S/R No.' + LTRIM(RTRIM(STR(S.SRInvCode, 10))),
	saletax_remarks= '', CheckNo = NULL, 
	UserCode= S.salesmancode, vouchercode= S.srinvcode, invoicecode= S.srinvcode,
	invoicetype = 3 /*3 stands for sale return*/,
	Amt = 0, DrAmtAccCode = NULL, CrAmtAccCode = NULL, AmtBy = NULL, AmtDate = NULL,
	AmtRef = NULL, OutstandingAmt = S.OutstandingAmt, Balance = 0,
	PatientCode=CASE WHEN S.PatientCode IS NULL THEN 
					CASE WHEN S.AdmissionCode IS NULL THEN NULL
					ELSE (SELECT A.Patientcode FROM PatientAdmission A WHERE S.AdmissionCode = A.AdmissionCode)
					END
				ELSE S.PatientCode END,
	GRN = NULL, GCCode = NULL, Vehicle = NULL, ShipTo = NULL, S.GuestCode, S.StudentCode, CGS=0,
	S.CurrencyCode, S.ConversionRate, AdvIncomeTax=0.00, FBRPosFee=0.00
FROM CRS_SRledger S
WHERE S.SRCatCode NOT IN (6, 8) AND S.CashCharged > 0 AND
	STR(S.Clientinstanceid, 10) + STR(S.srinvcode, 10) IN (SELECT STR(#lt_sret.ClientInstanceid,10) + STR(#lt_sret.Code,10) FROM #lt_sret)
UNION ALL
SELECT  S.Clientinstanceid, documentcode = S.srinvcode, documenttype    = 'SR', catcode = S.SRCatCode,
	dr_acccode = S.CustCode,
	cr_acccode = D.AccCode,
	AlternateAccCode = Null, Date    = S.date, SaleTax= 0,
	Gross = Amount,
	dr_remarks = D.Remarks, cr_remarks = D.Remarks,
	saletax_remarks= '', CheckNo = NULL, 
	UserCode= S.salesmancode, vouchercode= S.srinvcode, invoicecode= S.srinvcode,
	invoicetype = 3 /*3 stands for sales Return*/,
	Amt = 0, DrAmtAccCode = NULL, CrAmtAccCode = NULL, AmtBy = NULL, AmtDate = NULL,
	AmtRef = NULL, OutstandingAmt = S.OutstandingAmt, Balance = 0,
	PatientCode=CASE WHEN S.PatientCode IS NULL THEN 
					CASE WHEN S.AdmissionCode IS NULL THEN NULL
					ELSE (SELECT A.Patientcode FROM PatientAdmission A WHERE S.AdmissionCode = A.AdmissionCode)
					END
				ELSE S.PatientCode END,
	GRN = NULL, GCCode = NULL, Vehicle = NULL, ShipTo = NULL, S.GuestCode, S.StudentCode, CGS=0,
	S.CurrencyCode, S.ConversionRate,AdvIncomeTax=0.00, FBRPosFee=0.00
FROM CRS_srledger S, CRS_MasterCashWin D
WHERE STR(S.Clientinstanceid, 10) + STR(S.srinvcode, 10) IN (SELECT STR(#lt_sret.ClientInstanceid,10) + STR(#lt_sret.Code,10) FROM #lt_sret) AND
	S.Clientinstanceid = D.Clientinstanceid AND
	S.srinvcode = D.DocumentCode AND D.DocumentType = 'SR'

TRUNCATE TABLE #lt_sret
GO

-- SP_CRS_VirtualGL_TransactionWindow (last defined by script 7812)
CREATE PROCEDURE DBO.SP_CRS_VirtualGL_TransactionWindow
AS

SET NOCOUNT ON

CREATE TABLE #lt_transaction (clientinstanceid smallint not null, code INT NOT NULL)
INSERT INTO #lt_transaction
SELECT T.Clientinstanceid, T.DocumentCode
FROM CRS_TransactionHeader T
WHERE NOT EXISTS 
	(SELECT DISTINCT V.ClientInstanceid, V.DocumentCode FROM CRS_VirtualGL V 
	WHERE V.DocumentType IN (SELECT ShortName FROM TransactionType) AND V.Clientinstanceid = T.Clientinstanceid AND V.DocumentCode = T.DocumentCode)

INSERT INTO CRS_VirtualGLTemp	/* accounting for cash received via transaction window */
SELECT  TH.Clientinstanceid, 
	documentcode = TH.documentcode, 
	documenttype    = TT.ShortName, 
	catcode = TH.TransactionTypeCode,
	dr_acccode = TH.CashAccCode,
	cr_acccode = TH.AccCode,
	AlternateAccCode = Null, Date    = TH.date, SaleTax= 0,
	Gross = TH.CashCharged,
	dr_remarks = 'Cash Recvd. Against Transaction Doc. Code: ' + LTRIM(RTRIM(STR(TH.DocumentCode, 10))), 
	cr_remarks = 'Cash Recvd. Against Transaction Doc. Code: ' + LTRIM(RTRIM(STR(TH.DocumentCode, 10))), 
	saletax_remarks= '', CheckNo = NULL, 
	UserCode= TH.usercode, vouchercode= TH.TransactionCode, invoicecode= TH.TransactionCode,
	invoicetype = NULL,
	Amt = 0, DrAmtAccCode = NULL, CrAmtAccCode = NULL, AmtBy = NULL, AmtDate = NULL,
	AmtRef = NULL, OutstandingAmt = 0, Balance = 0,
	PatientCode=TH.PatientCode,
	GRN = NULL, GCCode = NULL, Vehicle = NULL, ShipTo = NULL, GuestCode=NULL, StudentCode=NULL, CGS=0, CurrencyCode=NULL, ConversionRate=NULL,
	AdvIncomeTax=0.00, FBRPosFee=0.00
FROM CRS_TransactionHeader TH, TransactionType TT
WHERE TH.CashCharged > 0 AND TH.Posted = 'Y' AND
	STR(TH.Clientinstanceid, 10) + STR(TH.DocumentCode, 10) IN (SELECT STR(#lt_transaction.ClientInstanceid,10) + STR(#lt_transaction.Code,10) FROM #lt_transaction) AND
	TH.TransactionTypeCode = TT.TransactionTypeCode AND
	TT.TransactionCatCode = 1
UNION ALL
SELECT  TH.Clientinstanceid, 
	documentcode = TH.documentcode, 
	documenttype    = TT.ShortName, 
	catcode = TH.TransactionTypeCode,
	dr_acccode = TD.AccCode,
	cr_acccode = TH.AccCode,
	AlternateAccCode = Null, Date    = TH.date, SaleTax= 0,
	Gross = TD.Amount,
	dr_remarks = 'Amount Recvd. Against Transaction Doc. Code: ' + LTRIM(RTRIM(STR(TH.DocumentCode, 10))), 
	cr_remarks = 'Amount Recvd. Against Transaction Doc. Code: ' + LTRIM(RTRIM(STR(TH.DocumentCode, 10))), 
	saletax_remarks= '', CheckNo = NULL, 
	UserCode= TH.usercode, vouchercode= TH.TransactionCode, invoicecode= TH.TransactionCode,
	invoicetype = NULL,
	Amt = 0, DrAmtAccCode = NULL, CrAmtAccCode = NULL, AmtBy = NULL, AmtDate = NULL,
	AmtRef = NULL, OutstandingAmt = 0, Balance = 0,
	PatientCode=TH.PatientCode,
	GRN = NULL, GCCode = NULL, Vehicle = NULL, ShipTo = NULL, GuestCode=NULL, StudentCode=NULL, CGS=0, CurrencyCode=NULL, ConversionRate=NULL,
	AdvIncomeTax=0.00, FBRPosFee=0.00
FROM CRS_TransactionHeader TH, CRS_TransactionDetail TD, TransactionType TT
WHERE 
	TH.Posted = 'Y' AND
	TH.TransactionTypeCode = TT.TransactionTypeCode AND
	TT.TransactionCatCode = 1 AND
	TH.DocumentCode = TD.DocumentCode AND
	TD.Amount > 0 AND
	STR(TH.Clientinstanceid, 10) + STR(TH.DocumentCode, 10) IN (SELECT STR(#lt_transaction.ClientInstanceid,10) + STR(#lt_transaction.Code,10) FROM #lt_transaction)
UNION ALL
SELECT  TH.Clientinstanceid, 
	documentcode = TH.documentcode, 
	documenttype    = TT.ShortName, 
	catcode = TH.TransactionTypeCode,
	dr_acccode = TH.AccCode,
	cr_acccode = TH.CashAccCode,
	AlternateAccCode = Null, Date    = TH.date, SaleTax= 0,
	Gross = TH.CashCharged,
	dr_remarks = 'Cash Paid Against Transaction Doc. Code: ' + LTRIM(RTRIM(STR(TH.DocumentCode, 10))), 
	cr_remarks = 'Cash Paid Against Transaction Doc. Code: ' + LTRIM(RTRIM(STR(TH.DocumentCode, 10))), 
	saletax_remarks= '', CheckNo = NULL, 
	UserCode= TH.usercode, vouchercode= TH.TransactionCode, invoicecode= TH.TransactionCode,
	invoicetype = NULL,
	Amt = 0, DrAmtAccCode = NULL, CrAmtAccCode = NULL, AmtBy = NULL, AmtDate = NULL,
	AmtRef = NULL, OutstandingAmt = 0, Balance = 0,
	PatientCode=TH.PatientCode,
	GRN = NULL, GCCode = NULL, Vehicle = NULL, ShipTo = NULL, GuestCode=NULL, StudentCode=NULL, CGS=0, CurrencyCode=NULL, ConversionRate=NULL,
	AdvIncomeTax=0.00, FBRPosFee=0.00
FROM CRS_TransactionHeader TH, TransactionType TT
WHERE TH.CashCharged > 0 AND TH.Posted = 'Y' AND
	TH.TransactionTypeCode = TT.TransactionTypeCode AND
	TT.TransactionCatCode = 2 AND
	STR(TH.Clientinstanceid, 10) + STR(TH.DocumentCode, 10) IN (SELECT STR(#lt_transaction.ClientInstanceid,10) + STR(#lt_transaction.Code,10) FROM #lt_transaction)
UNION ALL
SELECT  TH.Clientinstanceid, 
	documentcode = TH.documentcode, 
	documenttype    = TT.ShortName, 
	catcode = TH.TransactionTypeCode,
	dr_acccode = TH.AccCode,
	cr_acccode = TD.AccCode,
	AlternateAccCode = Null, Date    = TH.date, SaleTax= 0,
	Gross = TD.Amount,
	dr_remarks = 'Amount Paid Against Transaction Doc. Code: ' + LTRIM(RTRIM(STR(TH.DocumentCode, 10))), 
	cr_remarks = 'Amount Paid Against Transaction Doc. Code: ' + LTRIM(RTRIM(STR(TH.DocumentCode, 10))), 
	saletax_remarks= '', CheckNo = NULL, 
	UserCode= TH.usercode, vouchercode= TH.TransactionCode, invoicecode= TH.TransactionCode,
	invoicetype = NULL,
	Amt = 0, DrAmtAccCode = NULL, CrAmtAccCode = NULL, AmtBy = NULL, AmtDate = NULL,
	AmtRef = NULL, OutstandingAmt = 0, Balance = 0,
	PatientCode=TH.PatientCode,
	GRN = NULL, GCCode = NULL, Vehicle = NULL, ShipTo = NULL, GuestCode=NULL, StudentCode=NULL, CGS=0, CurrencyCode=NULL, ConversionRate=NULL,
	AdvIncomeTax=0.00, FBRPosFee=0.00
FROM CRS_TransactionHeader TH, CRS_TransactionDetail TD, TransactionType TT
WHERE 
	TH.Posted = 'Y' AND
	TH.TransactionTypeCode = TT.TransactionTypeCode AND
	TT.TransactionCatCode = 2 AND
	TH.DocumentCode = TD.DocumentCode AND
	TD.Amount > 0 AND
	STR(TH.Clientinstanceid, 10) + STR(TH.DocumentCode, 10) IN (SELECT STR(#lt_transaction.ClientInstanceid,10) + STR(#lt_transaction.Code,10) FROM #lt_transaction)

TRUNCATE TABLE #lt_transaction
GO

-- SP_CRS_VirtualGL_Vouchers (last defined by script 7813)
CREATE  PROCEDURE DBO.SP_CRS_VirtualGL_Vouchers
AS

SET NOCOUNT ON

DECLARE @ln_purchaseacc NUMERIC(5, 0), @ln_cashacc NUMERIC(5, 0), @ln_equityacc NUMERIC(5, 0),
	@ln_salesacc NUMERIC(5, 0), @ln_salesretacc NUMERIC(5, 0), @ln_purchaseretacc NUMERIC(5, 0),
	@ln_revfromservice NUMERIC(5, 0), @ln_salestaxacc NUMERIC(5, 0)

SET @ln_purchaseacc = (SELECT code FROM global WHERE name = 'GT_PurchaseAccount')
SET @ln_cashacc     = (SELECT code FROM global WHERE name = 'GT_CashACC')
SET @ln_equityacc	= (SELECT code FROM global WHERE name = 'GT_EquityACC')
SET @ln_purchaseretacc  = (SELECT code FROM global WHERE name = 'GT_PurchaseReturnsAccount')
SET @ln_salestaxacc	= (SELECT code FROM global WHERE name = 'GT_AdvanceSalesTaxACC')

CREATE TABLE #lt_voucher (ClientInstanceID SMALLINT, code INT NOT NULL)

INSERT INTO #lt_voucher
SELECT  H.ClientInstanceID, H.GLVochCode 
FROM    CRS_GLHeader H
WHERE   NOT EXISTS 
	(SELECT DISTINCT V.ClientInstanceID, V.DocumentCode
	FROM CRS_VirtualGL V, CRS_VocherCategory VC 
	WHERE V.ClientInstanceID = VC.ClientInstanceID AND V.DocumentType = VC.ShortName AND
	H.ClientInstanceID = V.ClientInstanceID AND V.DocumentCode = H.GLVochCode) AND H.Posted = 'Y'

/*  Create Accounting Vouchers that are manullay entered by user but not accounted for yet (depending on VIRTUALGL Table). That is the posted Accounting Vouchers not entered in VIRTUALGL but exist in GLHeader */
INSERT INTO CRS_VirtualGL
	(ClientInstanceID, DocumentCode, DocumentType, CatCode, AccCode, AlternateAccCode, date, Debit, Credit, Remarks, CheckNo, UserCode, VoucherCode, InvoiceCode, InvoiceType, OutstandingAmt, Balance, VRow, PatientCode, GRN, GCCode, Vehicle, ShipTo, GuestCode, StudentCode, CurrencyCode, ConversionRate)
Select	H.ClientInstanceID, documentcode = H.glvochcode,
	documenttype    = VC.ShortName,
	catcode = H.VochCatCode,
	acccode = D.acccode, 
	AlternateAccCode = NULL, 
	date    = H.Date,
	debit   = D.debit, 
	credit  = D.credit,
	remarks = CASE WHEN h.acccode = d.acccode THEN H.Remarks ELSE D.remarks END,
	CheckNo = CASE WHEN h.acccode = d.acccode THEN H.ChkNo ELSE D.ChkNo END, 
	UserCode = H.salesmancode, H.VoucherCode, D.InvoiceCode, VC.InvoiceType, 
	OutstandingAmt= D.OutstandingAmt, Balance= D.Balance, 
	VRow = CASE D.DEBIT WHEN 0 THEN 1 ELSE 0 END, D.PatientCode,
	GRN=NULL, GCCode=NULL, Vehicle=NULL, ShipTo=NULL, GuestCode=D.GuestCode, StudentCode=D.StudentCode, H.CurrencyCode, H.ConversionRate
from CRS_GLHeader H, CRS_GLDetail D, CRS_VocherCategory VC
where STR(H.ClientInstanceID,10) + STR(H.GLVochCode,10) IN 
	(SELECT STR(#lt_voucher.ClientInstanceID,10) + STR(#lt_voucher.Code,10) Code FROM #lt_voucher) AND
	H.ClientInstanceID = D.ClientInstanceID AND 
	H.ClientInstanceID = VC.ClientInstanceID AND 
	H.glvochcode = D.glvochcode and H.vochcatcode = VC.vochcatcode

TRUNCATE TABLE #lt_voucher
GO

-- SP_CRS_ZONALAREASALES_CROSSTAB (last defined by script catalog)
CREATE   PROCEDURE SP_CRS_ZONALAREASALES_CROSSTAB 
@Zonecode INT, @startdate datetime, 
@enddate datetime, @ReportGrouping CHAR(1), 
@GroupList VARCHAR(8000), @Pricetype TinyInt, 
@TotCol Float, @ColCaption SMALLINT AS

/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'crosstab_reportdata' table to be used for cross tabulation of a
	zone's areas and items selected depending upon the grouping criteria selected.

PARAMETER DESCRIPTION :
	@zoneCode = Zone for which report is required
	@startdate, @ar_enddate = Determine the period of report
	@ReportGrouping = The criteria for grouping the items in report
	@GroupList = A comma separated list of values to be filtered while grouping the record set
	@Pricetype = 1 stands for Actual Price, 2 stands for Sale/Trade Price, 3 stands for Purchase price and 4 stands for Average price
	@TotCol = the number of cross tab clolumns for the report (area shortname columns)
*/

DELETE CrossTab_ReportData

SET NOCOUNT ON

DECLARE @coltable TABLE (code int, shortname varchar(100), rowid INT identity(1,1))
DECLARE @UPD VARCHAR(4000), @Col VARCHAR(10), @RowID INT, @colname VARCHAR(100), @colcode VARCHAR(100), @str_col VARCHAR(10)
DECLARE @totareas FLOAT, @curriter int, @iterations int, @i int, @tot int
DECLARE @ICODE INTEGER, @AREACODE INTEGER, @QTY INT, @VAL NUMERIC(15, 5), @err INT

SELECT @totareas = ISNULL((SELECT Count(Area.AreaCode) FROM ZONEAREAS Z,Area WHERE Z.ZONECODE=@zoneCode AND Z.AreaCode = Area.AreaCode), 0)

DECLARE @Tab_GroupList TABLE (CODE INT NOT NULL)
DECLARE @Tab_ItemList TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_GroupList SELECT CODE FROM udf_StringToTabl(@GroupList, ',')
INSERT INTO @Tab_ItemList SELECT CODE FROM udf_selectitems(@ReportGrouping, @GroupList)

IF @totareas > 0 and @TotCol > 0
BEGIN

	SELECT @tot = (SELECT MIN(A) FROM (SELECT A=@TotCol UNION SELECT A=@TotAreas) T)

	INSERT @coltable (Code, ShortName)
	SELECT Area.AreaCode, Name=CASE WHEN @ColCaption = 1 THEN Area.ShortName ELSE Area.Name END
	FROM ZONEAREAS Z,Area 
	WHERE Z.ZONECODE=@zoneCode AND Z.AreaCode = Area.AreaCode
	ORDER BY AREA.ShortName

	SET @iterations = CEILING(@totareas/@TotCol)
	SET @curriter = 1
	SET @RowID = 0
	WHILE @curriter <= @iterations
	BEGIN
		
		INSERT INTO CrossTab_ReportData (Code1, Code2, Code3)
		SELECT Code, @curriter, @zoneCode FROM @Tab_ItemList

		SET @i = 1
		WHILE @i <= @tot
		BEGIN
			SET @RowID = @RowID + 1
			SELECT @colname = RTRIM(LTRIM(ISNULL((SELECT shortname FROM @coltable WHERE ROWID = @RowID), '')))
			SELECT @colcode = RTRIM(LTRIM(STR((SELECT CODE FROM @coltable WHERE ROWID = @RowID), 7)))
			IF @colcode IS NULL
			BEGIN
				BREAK
			END
			ELSE
			BEGIN
				SET @str_col = LTRIM(RTRIM(STR(@i, 7)))
				SELECT @UPD = 	'UPDATE CrossTab_ReportData SET C_Name' + @str_col + 
								' = ''' + @colname + ''', C_Code' + @str_col + ' = ' + @colcode +
								' WHERE CODE2 = ' + LTRIM(RTRIM(STR(@curriter, 7)))
				EXECUTE (@UPD)
				SET @err = @@ERROR
				IF @err <> 0
				BEGIN
					SET @UPD = 'UPDATION ERROR, DETAILS: ' + @UPD
					RAISERROR(@UPD, 16, 1, @UPD)
					RETURN -1
				END 
				SET @i = @i + 1
			END
		END
		SET @curriter = @curriter + 1
	END

	DECLARE C1 CURSOR FOR
	SELECT S.ICODE, QTY = ISNULL(Sum(S.QTY), 0),
		VAL= ROUND(SUM(
			CASE @Pricetype WHEN 1 THEN S.NETAMT 
			WHEN 2 THEN S.QTY * ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			WHEN 3 THEN S.QTY * ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			ELSE S.QTY * ROUND(I.AVGPRICE, 2) END), 0), 
		S.AREACODE
	FROM
		(SELECT SD.ICODE,
			C.AREACODE,
			CUSTCODE=SL.CUSTCODE,
			QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
			NETAMT=Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
					(1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
		FROM
			CRS_SALELEDGER SL,
			CRS_SALEDETAIL SD,
			CUSTOMER C,
			(SELECT AREACODE, ZONECODE FROM ZONEAREAS WHERE ZONECODE = @zonecode) A
		WHERE
			SD.ClientInstanceID = SL.ClientInstanceID AND
			SL.SALEINVCODE = SD.SALEINVCODE AND
			SL.POSTED='Y' AND 
			A.AREACODE = C.AREACODE AND
			C.CUSTCODE = SL.CUSTCODE AND
			SL.DATE BETWEEN @StartDate AND @EndDate
		GROUP BY
			SD.ICODE,
			SL.CustCode,
			C.AREACODE
		UNION ALL
		SELECT 	SD.ICODE,
			C.AREACODE,
			CUSTCODE=SL.CUSTCODE,
			QTY = - ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
			NETAMT= - Round(ISNULL(SUM((SD.looseqty * SD.SRPrice) *
					(1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
		FROM
			CRS_SRLEDGER SL,
			CRS_SRDETAIL SD,
			CUSTOMER C,
			(SELECT AREACODE, ZONECODE FROM ZONEAREAS WHERE ZONECODE = @zonecode) A
		WHERE
			SD.ClientInstanceID = SL.ClientInstanceID AND
			SL.SRINVCODE = SD.SRINVCODE AND
			SL.POSTED='Y' AND 
			A.AREACODE = C.AREACODE AND
			C.CUSTCODE = SL.CUSTCODE AND
			SL.DATE BETWEEN @StartDate AND @EndDate
		GROUP BY
			SD.ICODE,
			SL.CustCode,
			C.AREACODE) S, ITEM I
	WHERE I.ICODE = S.ICODE AND I.ICODE IN (SELECT CODE FROM @Tab_ItemList)
	GROUP BY 
		S.AREACODE,
		S.ICODE
	ORDER BY S.AREACODE, S.ICODE

	OPEN C1
	FETCH NEXT FROM C1 INTO @ICODE, @QTY, @VAL, @AREACODE
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @i = 1
		WHILE @i <= @tot
		BEGIN
			SELECT @colcode = LTRIM(RTRIM(STR(@ICODE, 7)))
			SELECT @colname = LTRIM(RTRIM(STR(@AREACODE, 7)))
			SET @str_col = LTRIM(RTRIM(STR(@i, 7)))

			SELECT @UPD = 	'UPDATE CrossTab_ReportData SET ' + 
							'QTY' + @str_col + ' = ' + LTRIM(RTRIM(STR(@QTY, 7))) + 
							', VAL' + @str_col + ' = ' + LTRIM(RTRIM(STR(@VAL, 15, 5))) + 
							', C_Code' + @str_col + ' = ' + @colname +
							' WHERE CODE1 = ' + @colcode + ' AND ' + 
							' C_Code' + @str_col + ' = ' + @colname
			EXECUTE (@UPD)
			SET @err = @@ERROR
			IF @err <> 0
			BEGIN
				SET @UPD = 'CROSSTAB PLOTING ERROR, DETAILS: ' + @UPD
				RAISERROR(@UPD, 16, 1, @UPD)
				CLOSE C1
				DEALLOCATE C1
				RETURN -1
			END 
			SET @i = @i + 1
		END

		FETCH NEXT FROM C1 INTO @ICODE, @QTY, @VAL, @AREACODE
	END
	CLOSE C1
	DEALLOCATE C1

	UPDATE CrossTab_ReportData 
	SET NAME1 = I.NAME,
		NAME2 = I.CustomICode,
		Name3 = I.PackingDesc,
		Name4 = (SELECT NAME FROM ZONE WHERE ZONECODE = @ZONECODE),   
		Code5=CASE @ReportGrouping 
			WHEN 'M' THEN I.MANFCODE
			WHEN 'C' THEN I.ICatCode
			WHEN 'L' THEN I.ICCode
			ELSE I.PACKCODE END,
		Name5 = CASE @ReportGrouping 
			WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE  = I.ManfCode)
			WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE  = I.ICatCode)
			WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE  = I.ICCode)
			ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE  = I.PACKCODE) END,
		Value1= CASE @Pricetype WHEN 1 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			ELSE ROUND(I.AVGPRICE, 2) END
	FROM ITEM I, CrossTab_ReportData C
	WHERE I.ICODE = C.CODE1

	EXECUTE SP_UPDATE_TOTAL_CrossTab_ReportData
END
RETURN 0
GO

-- SP_CUSTCATWISESALES (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_CUSTCATWISESALES @ar_startdate datetime, @ar_enddate datetime, @ReportGrouping CHAR(1), @GroupList VARCHAR(8000), @CustCatList VARCHAR(8000), @AreaList VARCHAR(8000), @ZeroRows tinyint AS 
/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'reportdata' table to be used for cross tabulation of a
	customer categories specified in parameter @custCatList and items selected 
	depending upon the grouping criteria selected.

PARAMETER DESCRIPTION :
	@ar_startdate, @ar_enddate = Determine the period of report
	@ReportGrouping = The criteria for grouping the items in report
	@GroupList = A comma separated list of values to be filtered while grouping the record set
	@CustCatList = A comma separated list of customercategory
	@AreaList	 = A comma separated list of areas
	@ZeroRows = 1 include rows with zero net sales and 0 for otherwise
*/

DELETE ReportData

DECLARE @Tab_GroupList TABLE (CODE INT NOT NULL)
DECLARE @Tab_CustCatList TABLE (CODE INT NOT NULL)
DECLARE @Tab_AreaList TABLE (CODE INT NOT NULL)
DECLARE @Tab_ItemList TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_GroupList SELECT CODE FROM udf_StringToTabl(@GroupList, ',')
INSERT INTO @Tab_CustCatList SELECT CODE FROM udf_StringToTabl(@CustCatList, ',')
INSERT INTO @Tab_AreaList SELECT CODE FROM udf_StringToTabl(@AreaList, ',')
INSERT INTO @Tab_ItemList SELECT CODE FROM udf_selectitems(@ReportGrouping, @GroupList)

INSERT INTO ReportData (code1, code2, code3, name1, name2, name3, name4, name5, value1, value2)
SELECT  Code1=S.ICODE,   
	Code2=S.CUSTCATCODE,    
	Code3=CASE @ReportGrouping 
		WHEN 'M' THEN I.MANFCODE
		WHEN 'C' THEN I.ICatCode
		WHEN 'L' THEN I.ICCode
		ELSE I.PACKCODE END,
	Name1=I.NAME,
	Name2=(SELECT NAME FROM CUSTOMERCATEGORY WHERE CUSTCATCODE = S.CUSTCATCODE),
	Name3=CASE @ReportGrouping 
		WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE  = I.ManfCode)
		WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE  = I.ICatCode)
		WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE  = I.ICCode)
		ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE  = I.PACKCODE) END,   
	Name4=I.CUSTOMICODE,   
	Name5=I.PackingDesc,
	Value1= ISNULL(SUM(QTY), 0),   
	Value2 = ROUND(SUM(NETAMT), 0)
FROM    
	(SELECT INVNO=-1,
		ICODE=I.ICODE,
		C.CUSTCATCODE,
		QTY = 0,
		NETAMT=0
	FROM
		(SELECT C.CustCatCode 
		FROM CUSTOMER C 
		WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
			C.CustCatCode IN (SELECT CODE FROM @Tab_CustCatList)) C,
		(SELECT ICODE=MIN(Code) FROM @Tab_ItemList) I
	WHERE CASE @ZeroRows WHEN 0 THEN 0 ELSE 1 END = 1
	UNION ALL
	SELECT INVNO=-1,
		ICODE=I.ICODE,
		C.CUSTCATCODE,
		QTY = 0,
		NETAMT=0
	FROM
		(SELECT CUSTCATCODE=MIN(C.CustCatCode)
		FROM CUSTOMER C 
		WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
			C.CustCatCode IN (SELECT CODE FROM @Tab_CustCatList)) C,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE CASE @ZeroRows WHEN 0 THEN 0 ELSE 1 END = 1
	UNION ALL
	SELECT INVNO=SL.SALEINVCODE,
		SD.ICODE,
		C.CUSTCATCODE,
		QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		NETAMT=Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
				(1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
	FROM
		SALELEDGER SL,
		SALEDETAIL SD,
		(SELECT C.CustCode, C.AreaCode, C.CustCatCode 
		FROM CUSTOMER C 
		WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
			C.CustCatCode IN (SELECT CODE FROM @Tab_CustCatList)) C,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
		SD.ICode = I.ICode AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
	GROUP BY
		SL.SaleInvCode,
		SD.ICODE,
		C.CUSTCATCODE
	UNION ALL
	SELECT INVNO=SL.SALEINVCODE,
		SD.ICODE,
		C.CUSTCATCODE,
		QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		NETAMT=Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
				(1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
	FROM
		SALELEDGER SL,
		SALEINVDETAIL SD,
		(SELECT C.CustCode, C.AreaCode, C.CustCatCode 
		FROM CUSTOMER C 
		WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
			C.CustCatCode IN (SELECT CODE FROM @Tab_CustCatList)) C,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE
		SL.IMPACTINVENTORY = 'N' AND
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
		SD.ICode = I.ICode AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
	GROUP BY
		SL.SaleInvCode,
		SD.ICODE,
		C.CUSTCATCODE
	UNION ALL
	SELECT INVNO=SL.SRINVCODE,
		SD.ICODE,
		C.CUSTCATCODE,
		QTY = - ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		NETAMT= - Round(ISNULL(SUM(SD.looseqty * SD.SRPrice *
				(1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
	FROM
		SRLEDGER SL,
		SRDETAIL SD,
		(SELECT C.CustCode, C.AreaCode, C.CustCatCode 
		FROM CUSTOMER C 
		WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
			C.CustCatCode IN (SELECT CODE FROM @Tab_CustCatList)) C,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SRINVCODE = SD.SRINVCODE AND
		SD.ICode = I.ICode AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
	GROUP BY
		SL.SRInvCode,
		SD.ICODE,
		C.CUSTCATCODE) S,
	(SELECT * FROM ITEM WHERE ICODE IN (SELECT Code FROM @Tab_ItemList)) I
WHERE
	S.ICode = I.ICode
GROUP BY
	S.CUSTCATCODE,
	S.ICODE,
	I.Name,
	I.CustomICode,
	I.PackingDesc,
	I.ICatCode,
	I.ICCode,
	I.ManfCode,
	I.PackCode
GO

-- SP_CUSTCATWISESALESDETAIL (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_CUSTCATWISESALESDETAIL @ar_startdate datetime, @ar_enddate datetime, @ReportGrouping CHAR(1), @GroupList VARCHAR(8000), @CustCatList VARCHAR(8000), @AreaList VARCHAR(8000), @ZeroRows tinyint AS 
/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'reportdata' table to be used for cross tabulation of a
	customers (specified by a subset of customer category using parameter @custCatList) 
	and items selected depending upon the grouping criteria selected.

PARAMETER DESCRIPTION :
	@ar_startdate, @ar_enddate = Determine the period of report
	@ReportGrouping = The criteria for grouping the items in report
	@GroupList = A comma separated list of values to be filtered while grouping the record set
	@CustCatList = A comma separated list of customercategory
	@AreaList	 = A comma separated list of areas
	@ZeroRows = 1 include rows with zero net sales and 0 for otherwise
*/

DELETE ReportData

DECLARE @Tab_GroupList TABLE (CODE INT NOT NULL)
DECLARE @Tab_CustCatList TABLE (CODE INT NOT NULL)
DECLARE @Tab_AreaList TABLE (CODE INT NOT NULL)
DECLARE @Tab_ItemList TABLE (CODE INT NOT NULL)
DECLARE @MIN_CUSTCODE INT, @MIN_ICODE INT

INSERT INTO @Tab_GroupList SELECT CODE FROM udf_StringToTabl(@GroupList, ',')
INSERT INTO @Tab_CustCatList SELECT CODE FROM udf_StringToTabl(@CustCatList, ',')
INSERT INTO @Tab_AreaList SELECT CODE FROM udf_StringToTabl(@AreaList, ',')
INSERT INTO @Tab_ItemList SELECT CODE FROM udf_selectitems(@ReportGrouping, @GroupList)

SET @MIN_CUSTCODE = ISNULL((SELECT MIN(C.CustCode) FROM CUSTOMER C 
						WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
						C.CustCatCode IN (SELECT CODE FROM @Tab_CustCatList)), 0)

INSERT INTO ReportData (code1, code2, code3, name1, name2, name3, name4, name5, value1, value2, Value3, value4, value5, Value6, Value7, Value8, Value9, Value10, Value11, Value12, Value13)
SELECT
	Code1=I.ICODE,   
	Code2=ISNULL(S.CUSTCODE, @MIN_CUSTCODE),    
	Code3=CASE @ReportGrouping 
		WHEN 'M' THEN I.MANFCODE
		WHEN 'C' THEN I.ICatCode
		WHEN 'L' THEN I.ICCode
		ELSE I.PACKCODE END,
	Name1=I.NAME,
	Name2=(SELECT NAME FROM ACCOUNTS WHERE ACCCODE = ISNULL(S.CUSTCODE, @MIN_CUSTCODE)),
	Name3=CASE @ReportGrouping 
		WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE  = I.ManfCode)
		WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE  = I.ICatCode)
		WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE  = I.ICCode)
		ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE  = I.PACKCODE) END,   
	Name4=I.CUSTOMICODE,   
	Name5=I.PackingDesc,
	Value1 = ROUND(I.SalePrice / CASE I.PackUnits WHEN 0 THEN 1 ELSE I.PackUnits END, 2),
	Value2 = ISNULL(O.QTY, 0),
	Value3 = ISNULL(O.VAL, 0),
	Value4 = ISNULL(P.QTY, 0),
	Value5 = ISNULL(P.VAL, 0),
	Value6 = ISNULL(PR.QTY, 0),
	Value7 = ISNULL(PR.VAL, 0),
	Value8= ISNULL(S.QTY, 0),
	Value9 = ISNULL(S.VAL, 0),
	Value10 = ISNULL(SR.QTY, 0),
	Value11 = ISNULL(SR.VAL, 0),
	Value12 = ISNULL(OT.QTY, 0),
	Value13 = ISNULL(OT.VAL, 0)	
	
FROM
	(SELECT * FROM ITEM WHERE ITEM.ICODE IN 
		(SELECT Code FROM @Tab_ItemList)) I
	LEFT OUTER JOIN 
	(SELECT
		ICODE=CODE,
		QTY=ISNULL(Qty, 0),
		VAL=ISNULL(Value, 0)
	FROM udf_openingstock (@ar_startdate, @ReportGrouping, @GroupList, 1)) AS O ON (I.ICode = O.ICode)
	LEFT OUTER JOIN
	(SELECT
		PD.ICODE,
		QTY=ISNULL(Sum( (PD.looseqty + PD.Packqty + PD.bonusqty) * CASE PL.PurCatCode WHEN 1 THEN PD.Packunits WHEN 2 THEN PD.Packunits ELSE 1 END), 0),
		VAL=Round(ISNULL(SUM((PD.looseqty + PD.PackQty) * PD.PurPrice *
				(1 - (.01 * PD.discperc)) * (1- (.01 * PL.discperc))), 0), 2)
	FROM
		PURLEDGER PL, PURDETAIL PD,	(SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE
		PL.POSTED='Y' AND PL.PURINVCODE = PD.PURINVCODE AND
		PD.ICode = I.ICode AND
		PL.DATE >= @ar_startdate AND PL.DATE <= @ar_enddate
	GROUP BY PD.ICODE) AS P ON (I.ICode = P.ICode)
	LEFT OUTER JOIN 
	(SELECT 
		PD.ICODE,
		QTY=ISNULL(Sum(PD.looseqty + PD.bonusqty), 0),
		VAL=Round(ISNULL(SUM(PD.looseqty * PD.PRPrice *
				(1 - (.01 * PD.discperc)) * (1- (.01 * PL.discperc))), 0), 2)
	FROM PRLEDGER PL, PRDETAIL PD, (SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE
		PL.POSTED='Y' AND PL.PRINVCODE = PD.PRINVCODE AND
		PD.ICode = I.ICode AND
		PL.DATE >= @ar_startdate AND PL.DATE <= @ar_enddate
	GROUP BY PD.ICODE) AS PR ON (I.ICode = PR.ICode)
	LEFT OUTER JOIN 
	(SELECT
		SD.ICODE,
		QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		VAL=  Round(ISNULL(SUM((SD.looseqty * SD.srprice) * (1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
	FROM
		SRLEDGER SL,
		SRDETAIL SD,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE
		SL.POSTED='Y' AND SL.SRINVCODE = SD.SRINVCODE AND
		SD.ICode = I.ICode AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
	GROUP BY
		SD.ICODE) AS SR ON (I.ICode = SR.ICode)
	LEFT OUTER JOIN
	(SELECT 
		T.ICode, Qty=SUM(T.Qty), Val=SUM(T.Val)
	FROM
		(SELECT
			SD.ICODE,
			QTY=-ISNULL(Sum(SD.qty), 0),
			VAL=-Round(ISNULL(SUM(SD.qty * (SD.SalePrice / CASE SD.Packunits WHEN 0 THEN 1 ELSE SD.Packunits END)), 0), 2)
		FROM
			IssueHeader SL,
			IssueDETAIL SD,
			(SELECT ICODE=Code FROM @Tab_ItemList) I
		WHERE
			SL.POSTED='Y' AND SL.ISSUEINVCODE = SD.ISSUEINVCODE AND
			SD.ICode = I.ICode AND
			SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
		GROUP BY
			SD.ICODE
		UNION ALL
		SELECT 
			SD.ICODE,
			QTY=ISNULL(Sum(SD.qty), 0),
			VAL=Round(ISNULL(SUM(SD.qty * (SD.SalePrice / CASE SD.Packunits WHEN 0 THEN 1 ELSE SD.Packunits END)), 0), 2)
		FROM
			RECEIPTHeader SL,
			RECEIPTDETAIL SD,
			(SELECT ICODE=Code FROM @Tab_ItemList) I
		WHERE
			SL.POSTED='Y' AND SL.RECEIPTINVCODE = SD.RECEIPTINVCODE AND
			SD.ICode = I.ICode AND
			SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
		GROUP BY
			SD.ICODE
		UNION ALL
		SELECT
			SD.ICODE,
			QTY=ISNULL(Sum(SD.Looseqty * CASE SL.AdjCatCode WHEN 1 THEN 1 ELSE -1 END), 0),
			VAL=Round(ISNULL(SUM(SD.Looseqty * (SD.SalePrice / CASE SD.Packunits WHEN 0 THEN 1 ELSE SD.Packunits END) * CASE SL.AdjCatCode WHEN 1 THEN 1 ELSE -1 END), 0), 2)
		FROM
			AdjHeader SL,
			AdjDETAIL SD,
			(SELECT ICODE=Code FROM @Tab_ItemList) I
		WHERE
			SL.POSTED='Y' AND SL.ADJCODE = SD.ADJCODE AND
			SD.ICode = I.ICode AND
			SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
		GROUP BY SD.ICODE) T
	GROUP BY T.ICODE) AS OT ON (I.ICode = OT.ICode)
	LEFT OUTER JOIN
	(SELECT
		SD.ICODE,
		C.CUSTCODE,
		QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		VAL=  Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
					(1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
	FROM
		SALELEDGER SL,
		SALEDETAIL SD,
		(SELECT C.CustCode
		FROM CUSTOMER C 
		WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
			C.CustCatCode IN (SELECT CODE FROM @Tab_CustCatList)) C,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
		SD.ICode = I.ICode AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
	GROUP BY
		C.CUSTCODE,
		SD.ICODE
	UNION ALL
	SELECT
		SD.ICODE,
		C.CUSTCODE,
		QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		VAL=  Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
					(1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
	FROM
		SALELEDGER SL,
		SALEINVDETAIL SD,
		(SELECT C.CustCode
		FROM CUSTOMER C 
		WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
			C.CustCatCode IN (SELECT CODE FROM @Tab_CustCatList)) C,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE
		SL.IMPACTINVENTORY = 'N' AND
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
		SD.ICode = I.ICode AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
	GROUP BY
		C.CUSTCODE,
		SD.ICODE) AS S ON (I.ICode = S.ICode)
GO

-- SP_CUSTCATWISESALESDETAIL_CROSSTAB (last defined by script catalog)
CREATE   PROCEDURE DBO.SP_CUSTCATWISESALESDETAIL_CROSSTAB 
	@ar_startdate datetime, 
	@ar_enddate datetime, 
	@ReportGrouping CHAR(1), 
	@GroupList VARCHAR(8000), 
	@CustCatCode INT, 
	@AreaList VARCHAR(8000), 
	@TotCol Float AS 
/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'reportdata' table to be used for cross tabulation of a
	customers (specified by a customer category using parameter @custCatCode)
	and items selected depending upon the grouping criteria selected.

PARAMETER DESCRIPTION :
	@ar_startdate, @ar_enddate = Determine the period of report
	@ReportGrouping = The criteria for grouping the items in report
	@GroupList = A comma separated list of values to be filtered while grouping the record set
	@CustCatCode = customercategory for which report is needed
	@AreaList	 = A comma separated list of areas
	@TotCol = the number of cross tab clolumns for the report (customer columns)
*/

DELETE CrossTab_ReportData

SET NOCOUNT ON

DECLARE @Tab_GroupList TABLE (CODE INT NOT NULL)
DECLARE @Tab_AreaList TABLE (CODE INT NOT NULL)
DECLARE @Tab_ItemList TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_GroupList SELECT CODE FROM udf_StringToTabl(@GroupList, ',')
INSERT INTO @Tab_AreaList SELECT CODE FROM udf_StringToTabl(@AreaList, ',')
INSERT INTO @Tab_ItemList SELECT CODE FROM udf_selectitems(@ReportGrouping, @GroupList)

DECLARE @coltable TABLE (code int, name varchar(100), rowid INT identity(1,1))
DECLARE @UPD VARCHAR(4000), @Col VARCHAR(10), @RowID INT, @colname VARCHAR(100), @colcode VARCHAR(100), @str_col VARCHAR(10)
DECLARE @totcols FLOAT, @curriter int, @iterations int, @i int, @tot int, @err INT
DECLARE @ICODE INTEGER, @AREACODE INTEGER, @ACCCODE INTEGER, @QTY INT, @VAL NUMERIC(15, 5)

SELECT @totcols = ISNULL((SELECT Count(A.AccCode) 
						FROM Accounts A, Customer C, @Tab_AreaList AR
						WHERE A.SubCode=3 AND A.AccCode = C.CustCode AND A.Active='Y' AND
							C.CustCatCode = @CustCatCode AND AR.CODE = C.AreaCode), 0)

IF @totcols > 0 and @TotCol > 0
BEGIN

	SELECT @tot = (SELECT MIN(A) FROM (SELECT A=@TotCol UNION SELECT A=@TotCols) T)

	INSERT @coltable
	SELECT A.AccCode, Name=A.Name
	FROM Accounts A, Customer C, @Tab_AreaList AR
	WHERE A.SubCode=3 AND A.AccCode = C.CustCode AND A.Active='Y' AND
		C.CustCatCode = @CustCatCode AND AR.CODE = C.AreaCode
	ORDER BY A.Name

	SET @iterations = CEILING(@totcols/@TotCol)
	SET @curriter = 1
	SET @RowID = 0

	INSERT INTO CrossTab_ReportData (Code1, Code2)
	SELECT Code, 0 FROM @Tab_ItemList

	WHILE @curriter <= @iterations
	BEGIN
		INSERT INTO CrossTab_ReportData (Code1, Code2)
		SELECT Code, @curriter FROM @Tab_ItemList

		SET @i = 1
		WHILE @i <= @tot
		BEGIN
			SET @RowID = @RowID + 1
			SELECT @colname = RTRIM(LTRIM(ISNULL((SELECT NAME FROM @coltable WHERE ROWID = @RowID), '')))
			SELECT @colcode = RTRIM(LTRIM(STR((SELECT CODE FROM @coltable WHERE ROWID = @RowID), 10)))
			IF @colcode IS NULL
			BEGIN
				BREAK
			END
			ELSE
			BEGIN
				SET @str_col = LTRIM(RTRIM(STR(@i, 7)))
				SELECT @UPD = 	'UPDATE CrossTab_ReportData SET C_Name' + @str_col + ' = ''' + @colname + 
								''', C_Code' + @str_col + ' = ' + @colcode +
								' WHERE CODE2 = ' + LTRIM(RTRIM(STR(@curriter, 7)))
				EXECUTE (@UPD)
				SET @err = @@ERROR
				IF @err <> 0
				BEGIN
					SET @UPD = 'CROSSTAB GENERATE ERROR, DETAILS: ' + @UPD
					RAISERROR(@UPD, 16, 1, @UPD)
					RETURN -1
				END 
				SET @i = @i + 1
			END
		END
		SET @curriter = @curriter + 1
	END

	UPDATE CrossTab_ReportData 
	SET Value2 = K.OQTY,  Value3 = K.OVAL, Value4 = K.PQTY, Value5 = K.PVAL,
		Value6 = K.PRQTY, Value7 = K.PRVAL, Value8= K.SQTY, Value9 = K.SVAL, 
		Value10= K.SRQTY, Value11 = K.SRVAL, Value12= K.OTQTY, Value13 = K.OTVAL
	FROM CrossTab_ReportData C,
		(SELECT
			ICODE=I.ICODE,   
			OQty = ISNULL(O.QTY, 0),
			OVal = ISNULL(O.VAL, 0),
			PQTY = ISNULL(P.QTY, 0),
			PVAL = ISNULL(P.VAL, 0),
			PRQTY = ISNULL(PR.QTY, 0),
			PRVAL = ISNULL(PR.VAL, 0),
			SQTY = ISNULL(S.QTY, 0),
			SVAL = ISNULL(S.VAL, 0),
			SRQTY = ISNULL(SR.QTY, 0),
			SRVAL = ISNULL(SR.VAL, 0),
			OTQTY = ISNULL(OT.QTY, 0),
			OTVAL = ISNULL(OT.VAL, 0)	
		FROM
			(SELECT * FROM ITEM WHERE ITEM.ICODE IN 
				(SELECT Code FROM @Tab_ItemList)) I
			LEFT OUTER JOIN 
			(SELECT
				ICODE=CODE,
				QTY=ISNULL(Qty, 0),
				VAL=ISNULL(Value, 0)
			FROM udf_openingstock (@ar_startdate, @ReportGrouping, @GroupList, 1)) AS O ON (I.ICode = O.ICode)
			LEFT OUTER JOIN
			(SELECT
				PD.ICODE,
				QTY=ISNULL(Sum( (PD.looseqty + PD.Packqty + PD.bonusqty) * CASE PL.PurCatCode WHEN 1 THEN PD.Packunits WHEN 2 THEN PD.Packunits ELSE 1 END), 0),
				VAL=Round(ISNULL(SUM((PD.looseqty + PD.PackQty) * PD.PurPrice *
						(1 - (.01 * PD.discperc)) * (1- (.01 * PL.discperc))), 0), 2)
			FROM
				PURLEDGER PL, PURDETAIL PD,	(SELECT ICODE=Code FROM @Tab_ItemList) I
			WHERE
				PL.POSTED='Y' AND PL.PURINVCODE = PD.PURINVCODE AND
				PD.ICode = I.ICode AND
				PL.DATE >= @ar_startdate AND PL.DATE <= @ar_enddate
			GROUP BY PD.ICODE) AS P ON (I.ICode = P.ICode)
			LEFT OUTER JOIN 
			(SELECT 
				PD.ICODE,
				QTY=ISNULL(Sum(PD.looseqty + PD.bonusqty), 0),
				VAL=Round(ISNULL(SUM(PD.looseqty * PD.PRPrice *
						(1 - (.01 * PD.discperc)) * (1- (.01 * PL.discperc))), 0), 2)
			FROM PRLEDGER PL, PRDETAIL PD, (SELECT ICODE=Code FROM @Tab_ItemList) I
			WHERE
				PL.POSTED='Y' AND PL.PRINVCODE = PD.PRINVCODE AND
				PD.ICode = I.ICode AND
				PL.DATE >= @ar_startdate AND PL.DATE <= @ar_enddate
			GROUP BY PD.ICODE) AS PR ON (I.ICode = PR.ICode)
			LEFT OUTER JOIN
			(SELECT 
				T.ICode, Qty=SUM(T.Qty), Val=SUM(T.Val)
			FROM
				(SELECT
					SD.ICODE,
					QTY=-ISNULL(Sum(SD.qty), 0),
					VAL=-Round(ISNULL(SUM(SD.qty * (SD.SalePrice / CASE SD.Packunits WHEN 0 THEN 1 ELSE SD.Packunits END)), 0), 2)
				FROM
					IssueHeader SL,
					IssueDETAIL SD,
					(SELECT ICODE=Code FROM @Tab_ItemList) I
				WHERE
					SL.POSTED='Y' AND SL.ISSUEINVCODE = SD.ISSUEINVCODE AND
					SD.ICode = I.ICode AND
					SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
				GROUP BY
					SD.ICODE
				UNION ALL
				SELECT 
					SD.ICODE,
					QTY=ISNULL(Sum(SD.qty), 0),
					VAL=Round(ISNULL(SUM(SD.qty * (SD.SalePrice / CASE SD.Packunits WHEN 0 THEN 1 ELSE SD.Packunits END)), 0), 2)
				FROM
					RECEIPTHeader SL,
					RECEIPTDETAIL SD,
					(SELECT ICODE=Code FROM @Tab_ItemList) I
				WHERE
					SL.POSTED='Y' AND SL.RECEIPTINVCODE = SD.RECEIPTINVCODE AND
					SD.ICode = I.ICode AND
					SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
				GROUP BY
					SD.ICODE
				UNION ALL
				SELECT
					SD.ICODE,
					QTY=ISNULL(Sum(SD.Looseqty * CASE SL.AdjCatCode WHEN 1 THEN 1 ELSE -1 END), 0),
					VAL=Round(ISNULL(SUM(SD.Looseqty * (SD.SalePrice / CASE SD.Packunits WHEN 0 THEN 1 ELSE SD.Packunits END) * CASE SL.AdjCatCode WHEN 1 THEN 1 ELSE -1 END), 0), 2)
				FROM
					AdjHeader SL,
					AdjDETAIL SD,
					(SELECT ICODE=Code FROM @Tab_ItemList) I
				WHERE
					SL.POSTED='Y' AND SL.ADJCODE = SD.ADJCODE AND
					SD.ICode = I.ICode AND
					SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
				GROUP BY SD.ICODE) T
			GROUP BY T.ICODE) AS OT ON (I.ICode = OT.ICode)
			LEFT OUTER JOIN 
			(SELECT
				ICODE=SD.ICODE,
				QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
				VAL=  Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
							(1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
			FROM
				SALELEDGER SL,
				SALEDETAIL SD,
				(SELECT C.CustCode
				FROM CUSTOMER C 
				WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
					C.CustCatCode = @CustCatCode) C,
				(SELECT ICODE=Code FROM @Tab_ItemList) I
			WHERE
				C.CUSTCODE = SL.CUSTCODE AND
				SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
				SD.ICode = I.ICode AND
				SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
			GROUP BY
				SD.ICODE) AS S ON (I.ICode = S.ICode)
			LEFT OUTER JOIN 
			(SELECT
				ICODE=SD.ICODE,
				QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
				VAL=  Round(ISNULL(SUM((SD.looseqty * SD.srprice) * (1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
			FROM
				SRLEDGER SL,
				SRDETAIL SD,
				(SELECT C.CustCode
				FROM CUSTOMER C 
				WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
					C.CustCatCode = @CustCatCode) C,
				(SELECT ICODE=Code FROM @Tab_ItemList) I
			WHERE
				C.CUSTCODE = SL.CUSTCODE AND
				SL.POSTED='Y' AND SL.SRINVCODE = SD.SRINVCODE AND
				SD.ICode = I.ICode AND
				SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
			GROUP BY SD.ICODE) AS SR ON (I.ICode = SR.ICode)) K
	WHERE C.CODE1 = K.ICODE

	DECLARE C1 CURSOR FOR
	SELECT
		ICODE=SD.ICODE,
		ACCCODE=C.CUSTCODE,
		QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		VAL=  Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
					(1 - (.01 * SD.discperc)) * (1- (.01 * SL.discperc))), 0), 2)
	FROM
		SALELEDGER SL,
		SALEDETAIL SD,
		(SELECT C.CustCode
		FROM CUSTOMER C 
		WHERE C.AreaCode IN (SELECT CODE FROM @Tab_AreaList) AND
			C.CustCatCode = @CustCatCode) C,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	WHERE
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
		SD.ICode = I.ICode AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
	GROUP BY
		C.CUSTCODE,
		SD.ICODE

	OPEN C1
	FETCH NEXT FROM C1 INTO @ICODE, @AccCode, @QTY, @VAL
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @i = 1
		WHILE @i <= @tot
		BEGIN
			SELECT @colcode = LTRIM(RTRIM(STR(@ICODE, 7)))
			SELECT @colname = LTRIM(RTRIM(STR(@AccCODE, 7)))
			SET @str_col = LTRIM(RTRIM(STR(@i, 7)))

			SELECT @UPD = 	'UPDATE CrossTab_ReportData SET ' + 
							'QTY' + @str_col + ' = ' + LTRIM(RTRIM(STR(@QTY, 10))) + 
							', VAL' + @str_col + ' = ' + LTRIM(RTRIM(STR(@VAL, 15, 5))) + 
							', C_Code' + @str_col + ' = ' + @colname +
							' WHERE CODE2 > 0 AND CODE1 = ' + @colcode + ' AND ' + 
							' C_Code' + @str_col + ' = ' + @colname
			EXECUTE (@UPD)
			SET @err = @@ERROR
			IF @err <> 0
			BEGIN
				SET @UPD = 'CROSSTAB PLOTING ERROR, DETAILS: ' + @UPD
				RAISERROR(@UPD, 16, 1, @UPD)
				CLOSE C1
				DEALLOCATE C1
				RETURN -1
			END 
			SET @i = @i + 1
		END

		FETCH NEXT FROM C1 INTO @ICODE, @AccCode, @QTY, @VAL
	END
	CLOSE C1
	DEALLOCATE C1

	UPDATE CrossTab_ReportData 
	SET NAME1 = I.NAME,
		NAME2 = I.CustomICode,
		Name3 = I.PackingDesc,
		Name4 = (SELECT NAME FROM CustomerCategory WHERE CUSTCATCODE = @CUSTCATCODE),   
		Code5=CASE @ReportGrouping 
			WHEN 'M' THEN I.MANFCODE
			WHEN 'C' THEN I.ICatCode
			WHEN 'L' THEN I.ICCode
			ELSE I.PACKCODE END,
		Name5 = CASE @ReportGrouping 
			WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE  = I.ManfCode)
			WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE  = I.ICatCode)
			WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE  = I.ICCode)
			ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE  = I.PACKCODE) END,
		Value1= ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
	FROM ITEM I, CrossTab_ReportData C
	WHERE I.ICODE = C.CODE1

	EXECUTE SP_UPDATE_TOTAL_CrossTab_ReportData
END
RETURN 0
GO

-- SP_CustGroup_ItemGroup_NetSale_CrossTab (last defined by script catalog)
CREATE PROCEDURE DBO.SP_CustGroup_ItemGroup_NetSale_CrossTab
@CustGroupCode INT, @ItemGroupCode INT, @startdate datetime, @enddate datetime AS

/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'crosstab_reportdata' table to be used for cross tabulation of a
	customer of a cusomer group and items of an item group 

PARAMETER DESCRIPTION :
	@CustGroupCode = Customer Group for which report is required
	@ItemGroupCode = Item Group for which report is required
	@startdate, @ar_enddate = Determine the period of report
*/

DELETE CrossTab_ReportData

SET NOCOUNT ON

DECLARE @coltable TABLE (code int, shortname varchar(100), rowid INT identity(1,1))
DECLARE @UPD VARCHAR(4000), @Col VARCHAR(10), @RowID INT, @colname VARCHAR(100), @colcode VARCHAR(100), @str_col VARCHAR(10)
DECLARE @totitems FLOAT, @curriter int, @iterations int, @i int, @tot int
DECLARE @ICODE INTEGER, @CustCODE INTEGER, @QTY INT, @VAL NUMERIC(15, 5), @err INT, @TotCol SMALLINT

SELECT @totitems = ISNULL((SELECT Count(ICode) FROM ItemGroupDetail WHERE ItemGroupCode = @CustGroupCode), 0)
SET @TotCol = 12
IF @totitems > 0
BEGIN
	SELECT @tot = (SELECT MIN(A) FROM (SELECT A=@TotCol UNION SELECT A=@totitems) T)

	INSERT @coltable (Code, ShortName)
	SELECT ICode , Name=ShortName
	FROM Item
	WHERE ICode IN (SELECT ICODE FROM ItemGroupDetail WHERE ItemGroupCode = @ItemGroupCode)
	ORDER BY ShortName

	SET @iterations = Ceiling(@totitems/@TotCol)
	SET @curriter = 1
	SET @RowID = 0
	WHILE @curriter <= @iterations
	BEGIN
		
		INSERT INTO CrossTab_ReportData (Code1, Code2, Code3, Code5)
		SELECT CustCODE, @curriter, @CustGroupCode, @ItemGroupCode FROM CustomerGroupDetail WHERE CustomerGroupCode = @CustGroupCode

		SET @i = 1
		WHILE @i <= @tot
		BEGIN
			SET @RowID = @RowID + 1
			SELECT @colname = RTRIM(LTRIM(ISNULL((SELECT shortname FROM @coltable WHERE ROWID = @RowID), '')))
			SELECT @colcode = RTRIM(LTRIM(STR((SELECT CODE FROM @coltable WHERE ROWID = @RowID), 7)))
			IF @colcode IS NULL
			BEGIN
				BREAK
			END
			ELSE
			BEGIN
				SET @str_col = LTRIM(RTRIM(STR(@i, 7)))
				SELECT @UPD = 	'UPDATE CrossTab_ReportData SET C_Name' + @str_col + 
								' = ''' + @colname + ''', C_Code' + @str_col + ' = ' + @colcode +
								' WHERE CODE2 = ' + LTRIM(RTRIM(STR(@curriter, 7)))
				EXECUTE (@UPD)
				SET @err = @@ERROR
				IF @err <> 0
				BEGIN
					SET @UPD = 'UPDATION ERROR, DETAILS: ' + @UPD
					RAISERROR(@UPD, 16, 1, @UPD)
					RETURN -1
				END 
				SET @i = @i + 1
			END
		END
		SET @curriter = @curriter + 1
	END

	DECLARE C1 CURSOR FOR
	SELECT S.ICODE, S.CustCode, QTY = ISNULL(Sum(S.QTY), 0), VAL= ISNULL(SUM(S.NETAMT), 0)
	FROM
		(SELECT INVNO=SL.SALEINVCODE,
			SD.ICODE,
			CUSTCODE=SL.CUSTCODE,
			QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
			NETAMT=Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
					(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2)
		FROM
			SALELEDGER SL,
			SALEDETAIL SD,
			CUSTOMER C
		WHERE
			C.CustCode IN (SELECT CustCODE FROM CustomerGroupDetail WHERE CustomerGroupCode = @CustGroupCode) AND
			C.CUSTCODE = SL.CUSTCODE AND SL.POSTED='Y' AND 
			SL.SALEINVCODE = SD.SALEINVCODE AND
			SL.DATE BETWEEN @StartDate AND @EndDate AND
			SD.ICOde IN (SELECT ICODE FROM ItemGroupDetail WHERE ItemGroupCode = @ItemGroupCode)
		GROUP BY
			SL.SaleInvCode,
			SD.ICODE,
			SL.CustCode,
			SL.DiscPerc
		UNION ALL
		SELECT INVNO=SL.SRINVCODE,
			SD.ICODE,
			CUSTCODE=SL.CUSTCODE,
			QTY = - ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
			NETAMT= - Round(ISNULL(SUM((SD.looseqty * SD.SRPrice) *
					(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2)
		FROM
			SRLEDGER SL,
			SRDETAIL SD,
			CUSTOMER C
		WHERE
			C.CustCode IN (SELECT CustCODE FROM CustomerGroupDetail WHERE CustomerGroupCode = @CustGroupCode) AND
			C.CUSTCODE = SL.CUSTCODE AND SL.POSTED='Y' AND 
			SL.SRINVCODE = SD.SRINVCODE AND
			SL.DATE BETWEEN @StartDate AND @EndDate AND
			SD.ICOde IN (SELECT ICODE FROM ItemGroupDetail WHERE ItemGroupCode = @ItemGroupCode)
		GROUP BY
			SL.SRInvCode,
			SD.ICODE,
			SL.CustCode,
			SL.DiscPerc) S, Accounts A
	WHERE S.CustCODE = A.AccCODE
	GROUP BY 
		S.CustCode,
		S.ICODE
	ORDER BY S.CustCODE, S.ICODE

	OPEN C1
	FETCH NEXT FROM C1 INTO @ICODE, @CustCODE, @QTY, @VAL
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @i = 1
		WHILE @i <= @tot
		BEGIN
			SELECT @colcode = LTRIM(RTRIM(STR(@CustCODE, 7)))
			SELECT @colname = LTRIM(RTRIM(STR(@ICODE, 7)))
			SET @str_col = LTRIM(RTRIM(STR(@i, 7)))

			SELECT @UPD = 	'UPDATE CrossTab_ReportData SET ' + 
							'QTY' + @str_col + ' = ' + LTRIM(RTRIM(STR(@QTY, 7))) + 
							', VAL' + @str_col + ' = ' + LTRIM(RTRIM(STR(@VAL, 15, 5))) + 
							', C_Code' + @str_col + ' = ' + @colname +
							' WHERE CODE1 = ' + @colcode + ' AND ' + 
							' C_Code' + @str_col + ' = ' + @colname
			EXECUTE (@UPD)
			SET @err = @@ERROR
			IF @err <> 0
			BEGIN
				SET @UPD = 'CROSSTAB PLOTING ERROR, DETAILS: ' + @UPD
				RAISERROR(@UPD, 16, 1, @UPD)
				CLOSE C1
				DEALLOCATE C1
				RETURN -1
			END 
			SET @i = @i + 1
		END

		FETCH NEXT FROM C1 INTO @ICODE, @CustCODE, @QTY, @VAL
	END
	CLOSE C1
	DEALLOCATE C1

	UPDATE CrossTab_ReportData 
	SET NAME1 = A.NAME,
		NAME2 = A.AliasName,
		Name3 = NULL,
		Name4 = (SELECT NAME FROM CustomerGroup WHERE CustomerGroupCODE = @CustGroupCODE),
		Name5 = (SELECT NAME FROM ItemGroup WHERE ItemGroupCODE = @ItemGroupCODE)
	FROM Accounts A, CrossTab_ReportData C
	WHERE A.AccCODE = C.CODE1

	EXECUTE SP_UPDATE_TOTAL_CrossTab_ReportData
END
RETURN 0
GO

-- sp_Customer_Sale_Accounts (last defined by script catalog)

/****** Object:  Stored Procedure dbo.sp_Customer_Sale_Accounts    Script Date: 4/23/02 4:29:59 PM ******/
/****** Object:  Stored Procedure dbo.sp_Customer_Sale_Accounts    Script Date: 4/8/02 6:26:06 PM ******/
/****** Object:  Stored Procedure dbo.sp_Customer_Sale_Accounts    Script Date: 3/6/02 3:39:36 PM ******/
CREATE PROCEDURE sp_Customer_Sale_Accounts @ad_date datetime ,@ad_ldate datetime AS



/*----------------------for opening balance-----------------------*/

create table #lt_pvamts 
(
	debit  numeric (15, 2) NOT NULL,
	credit numeric (15, 2) NOT NULL,
	code   numeric (5,0) NOT NULL,
	name varchar(50) NOT NULL
)

/***************************** Credit Sales Transactions **********************************/

insert #lt_pvamts
select
	 Debit = Isnull(Round(SUM(saledetail.looseqty * saledetail.unitsalestax) + 
	 SUM(ROUND( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc)) * saledetail.gstperc * .01, 2)) +
	 Round( (sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) - saleledger.flatdisc) * (saleledger.invgstperc1 * .01), 2), 0) +
	 Round( sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0), 0),
	 credit = 0.0,
	 custcode=saleledger.custcode	,
	 name=(select accounts.name from accounts where acccode=saleledger.custcode)
     
from     saleledger, saledetail  
where    saleledger.saleinvcode = saledetail.saleinvcode and
	 saleledger.salecatcode = 2   and 
 	 saleledger.date < @ad_date  and
	 saleledger.posted = 'Y' 

group by saleledger.saleinvcode,
	 salecatcode, 
         saleledger.custcode,
	 saleledger.date,
	 saleledger.discperc,
	 saleledger.misccharges,
	 saleledger.salestax,
	 saleledger.invgstperc1,
	 saleledger.flatdisc

/************************** Credit Sales Returns Transactions ******************************/

insert   #lt_pvamts
select   Debit = 0.0,
	 Credit = Isnull(Round(SUM(srdetail.looseqty * srdetail.unitsalestax) + 
			SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
			    (1 - (.01 * srdetail.discperc)) * srdetail.gstperc * .01, 2)) +
			Round( (sum( (srdetail.looseqty * srdetail.srprice) *
			    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) - 
			    srledger.flatdisc) * (srledger.invgstperc1 * .01), 2), 0) +
			Round( sum( (srdetail.looseqty * srdetail.srprice) *
			    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) + 
			    srledger.misccharges + srledger.salestax - srledger.flatdisc, 0), 0),
         custcode=srledger.custcode,
	 name=(select accounts.name from accounts where acccode=srledger.custcode)
from     srledger, srdetail
where    srledger.srinvcode = srdetail.srinvcode and
	 srledger.srcatcode = 7     and 
 	 srledger.date < @ad_date  and
	 srledger.posted = 'Y' 	 
group by srledger.srinvcode,
	 srledger.srcatcode,
         srledger.custcode,
	 srledger.date,
	 srledger.discperc,
	 srledger.misccharges,
	 srledger.salestax,
	 srledger.invgstperc1,
	 srledger.flatdisc

/***************************** Debit Services Transactions ********************************/

insert #lt_pvamts

select  debit = IsNull( sum(IsNull(servicedetail.price, 0) * 
	(1 - (.01 * servicedetail.discperc))) * (1- (.01 * serviceheader.discperc)) +
	serviceheader.misccharges - serviceheader.flatdisc,0),
	credit= 0.0,
        custcode=serviceheader.custcode	,
	name=(select accounts.name from accounts where acccode=serviceheader.custcode)
from     serviceheader, servicedetail
where    serviceheader.serviceinvcode = servicedetail.serviceinvcode and
	 serviceheader.servicecatcode = 11     and 
 	 serviceheader.date < @ad_date  and
	 serviceheader.posted = 'Y' 
	

group by serviceheader.serviceinvcode,
	 serviceheader.servicecatcode,
         serviceheader.custcode,
	 serviceheader.date,
	 serviceheader.discperc,
	 serviceheader.misccharges,
	 serviceheader.flatdisc

/************************* Credit Services Returns Transactions ***************************/

insert #lt_pvamts

select  debit = 0.0,
	credit= IsNull( sum(IsNull(serviceRdetail.ServicePrice, 0) * 
		(1 - (.01 * serviceRdetail.discperc))) * (1- (.01 * serviceRheader.discperc)) +
	serviceRheader.misccharges - serviceRheader.flatdisc,0),
        custcode=serviceRheader.custcode,
	name=(select accounts.name from accounts where acccode=serviceRheader.custcode)

from     serviceRheader, serviceRdetail

where    serviceRheader.serviceRinvcode = serviceRdetail.serviceRinvcode and
	 serviceRheader.serviceRcatcode = 14 and 
 	 serviceRheader.date < @ad_date  and
	 serviceRheader.posted = 'Y' 

group by serviceRheader.serviceRinvcode,
	 serviceRheader.serviceRcatcode,
         serviceRheader.custcode,
	 serviceRheader.date,
	 serviceRheader.discperc,
	 serviceRheader.misccharges,
	 serviceRheader.flatdisc
/**************************** Any Acccounting Transactions ********************************/

insert #lt_pvamts
select  IsNull( sum(gldetail.debit), 0),
        IsNull( sum(gldetail.credit), 0),
        custcode=gldetail.acccode	,
	name=(select accounts.name from accounts where accounts.acccode=gldetail.acccode)
	 
from     glheader, gldetail  
where    glheader.glvochcode = gldetail.glvochcode and 
 	 glheader.date < @ad_date  and
	 glheader.posted = 'Y' and
         gldetail.acccode IN (select custcode from customer) 
GROUP BY gldetail.acccode	 

/******************************* Any Bills Receivables ***********************************/

insert #lt_pvamts
select  0,
        IsNull( sum(notes.amount), 0),
        custcode=notes.acccode,
        name=(select accounts.name from accounts where accounts.acccode=notes.acccode)
    
	 
from     notes
where    notes.notecatcode = 1 and
	 notes.posted = 'Y' and
	 notes.postdate < @ad_date  and
	 notes.acccode IN (select custcode from customer) 
GROUP BY notes.acccode



/******** Collecting the result and assigning to the relevent reference variable *********/
delete from reportdata
insert into reportdata(code1,name1,value1,value2,value3,value4,value5,value6,value7,value8)
select code,name,IsNull(sum(debit) - sum(credit),0),0,0,0,0,0,0,0
	from   #lt_pvamts 
	group by name,
                 code 

insert into reportdata(code1,value1,value2,value3,value4,value5,value6,value7,value8)
select customer.custcode,0,0,0,0,0,0,0,0

from  customer

where 
	 customer.custcode Not IN (select code1 from reportdata) 


update 	reportdata
set 	name1=accounts.name
from 	accounts,reportdata
where	reportdata.name1=Null and
	reportdata.code1=accounts.acccode
/*----------inserting AreaCode--------------*/
update reportdata
set code2=customer.areacode
from customer
where reportdata.code1=customer.custcode
/*--------------end AreaCode--------------*/

/*---------------end---------------------------------------------*/





/*
insert into reportdata(code1,name1)
select custcode,accounts.name
from accounts,customer
where accounts.acccode=customer.custcode*/



/*--------------------for CreditSale-----------------------*/

update reportdata
set value7=SaleH.amount

from reportdata,(select amount=sum(sale.amount),customercode=sale.custcode
		
		from  
		(select custcode=customer.custcode , 
			amount= Isnull(
				Round(SUM(saledetail.looseqty * saledetail.unitsalestax) + 
				SUM(ROUND( (saledetail.looseqty * 
					(saledetail.saleprice - saledetail.itemflatdisc)) *
					(1 - (.01 * saledetail.discperc)) * 
					saledetail.gstperc * .01, 2)) +
				Round( (sum( (saledetail.looseqty * 
					(saledetail.saleprice - saledetail.itemflatdisc)) *
					(1 - (.01 * saledetail.discperc))) * 
					(1- (.01 * saleledger.discperc))-saleledger.flatdisc)*
					(saleledger.invgstperc1 * .01), 2), 0) +
				Round( sum( (saledetail.looseqty * 
					(saledetail.saleprice - saledetail.itemflatdisc)) *
					(1 - (.01 * saledetail.discperc))) * 
					(1- (.01 * saleledger.discperc)) + 
					saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0), 0)
		from	saleledger, saledetail ,customer
		where	saleledger.saleinvcode = saledetail.saleinvcode and
			saleledger.salecatcode = 2   and
			saleledger.Posted = 'Y'   and	
			saleledger.date >= @ad_date  and
			saleledger.date <= @ad_ldate  and
			saleledger.custcode =customer.custcode
		group by
			saleledger.saleinvcode,
			salecatcode, 
			saleledger.date,
			saleledger.discperc,
			saleledger.misccharges,
			saleledger.salestax,
			saleledger.flatdisc,
			saleledger.invgstperc1,
			customer.custcode) as Sale 

	 	group by sale.custcode	

		) saleH

where reportdata.code1=SaleH.customercode


/*-----------------------------end sale-------------------*/


/*-------------------for Credit Sale Return--------------------*/

update reportdata
set value2=SaleReturnH.amount

from reportdata,(select amount=sum(salereturn.amount),customercode=SaleReturn.custcode
		 
		 from (
			select  custcode=customer.custcode,
	
				Amount= Isnull(
					Round(SUM(srdetail.looseqty * srdetail.unitsalestax) + 
					SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
					    (1 - (.01 * srdetail.discperc)) * 
					    srdetail.gstperc * .01, 2)) +
					Round( (sum( (srdetail.looseqty * srdetail.srprice) *
					    (1 - (.01 * srdetail.discperc))) * 
					    (1- (.01 * srledger.discperc)) - 
					    srledger.flatdisc) * 
					    (srledger.invgstperc1 * .01), 2), 0) +
					Round( sum( (srdetail.looseqty * srdetail.srprice) *
					    (1 - (.01 * srdetail.discperc))) * 
					    (1- (.01 * srledger.discperc)) + 
					    srledger.misccharges + srledger.salestax - srledger.flatdisc, 0), 0)
			from     srledger, srdetail, customer  
			where    srledger.srinvcode = srdetail.srinvcode and
	        		 srledger.srcatcode = 7     and 
	 			 srledger.posted  = 'Y' and 	
				 srledger.date >= @ad_date  and
		        	 srledger.date <= @ad_ldate  and
 	 			 srledger.custcode = customer.custcode

			group by srledger.srinvcode,
				 srledger.srcatcode,
	 			 srledger.date,
	 			 srledger.discperc,
	 			 srledger.misccharges,
				 srledger.salestax,
				 srledger.invgstperc1,
	 			 srledger.flatdisc,
		 		 customer.custcode
	 		) as SaleReturn

	   	 group by salereturn.custcode	

		) as SaleReturnH

where reportdata.code1=SaleReturnH.customercode


/*----------------------end------------------------*/

/*-----------------------total recieved----------------------*/

update reportdata
set value3=Recieved.amount

from reportdata,(select   customercode=customer.custcode,
			
			amount=case sum(Round(gldetail.credit, 0))
				when NULL then 0.0
	 			else sum(Round(gldetail.credit, 0))
	 			end
		from     glheader, gldetail , customer
		Where	glheader.posted = 'Y' and
			glheader.vochcatcode in (2,4) and
			glheader.date >= @ad_date  and
	 		glheader.date <= @ad_ldate  and
			glheader.glvochcode = gldetail.glvochcode and	
			gldetail.acccode = customer.custcode  
		group by customer.custcode

	 		) as Recieved

where reportdata.code1=Recieved.customercode








/*--------------------------end recieved-------------------*/


/*--------------------------total adjustment----------*/


update reportdata
set value4=Adjustment.amount

from reportdata,(select   customercode=customer.custcode,
			
			amount= ISNULL( sum(Round(gldetail.debit, 0)),0) 
				
		from     glheader, gldetail , customer
		Where	glheader.posted = 'Y' and
			glheader.vochcatcode in (5,8,10,1,3) and
			glheader.date >= @ad_date  and
			glheader.date <= @ad_ldate  and
			glheader.glvochcode = gldetail.glvochcode and	
			gldetail.acccode = customer.custcode  
		group by customer.custcode

	 		) as Adjustment

where reportdata.code1=Adjustment.customercode




update reportdata
set value8=Adjustment.amount

from reportdata,(select   customercode=customer.custcode,
			
			amount=  ISNULL( sum(Round(gldetail.credit, 0)),0)
				
		from     glheader, gldetail , customer
		Where	glheader.posted = 'Y' and
			glheader.vochcatcode in (5,8,10) and
			glheader.date >= @ad_date  and
			glheader.date <= @ad_ldate  and
			glheader.glvochcode = gldetail.glvochcode and	
			gldetail.acccode = customer.custcode  
		group by customer.custcode

	 		) as Adjustment

where reportdata.code1=Adjustment.customercode

/*----------------end adjustment-----------------------*/




/*----------------------total CreditService---------*/
update reportdata
set value5=ServiceH.amount

from reportdata,(Select amount=sum(service.amount),customercode=service.custcode
		
		 from     (
				select  custcode=serviceheader.custcode,
			 		amount = IsNull( sum(IsNull(servicedetail.price, 0) * 	(1 - (.01 * servicedetail.discperc))) * (1- (.01 * serviceheader.discperc)) +	serviceheader.misccharges - serviceheader.flatdisc,0)
	
				from     serviceheader, servicedetail, customer
				where    serviceheader.serviceinvcode = servicedetail.serviceinvcode and
	 				serviceheader.servicecatcode = 11     and 
	 				serviceheader.posted = 'Y' and
					serviceheader.date >= @ad_date  and
					serviceheader.date <= @ad_ldate  and
	 				serviceheader.custcode = customer.custcode

				group by serviceheader.serviceinvcode,
					 serviceheader.servicecatcode,
	 				serviceheader.date,
	 				serviceheader.discperc,
	 				serviceheader.misccharges,
	 				serviceheader.flatdisc,
	 				serviceheader.custcode
			 )as Service
		group by service.custcode 
		
		) as ServiceH

where reportdata.code1=ServiceH.customercode
/*-----------------end service-------------------*/


/*----------------------total CreditServiceReturn---------*/
update reportdata
set value6=ServiceReturnH.amount

from reportdata,(select amount=sum(servicereturn.amount),customercode=servicereturn.custcode
		
		from    (select  custcode=serviceRheader.custcode,
		
				amount= IsNull( sum(IsNull(serviceRdetail.Serviceprice, 0) * (1 - (.01 * serviceRdetail.discperc))) * (1- (.01 * serviceRheader.discperc)) + serviceRheader.misccharges - serviceRheader.flatdisc,0)
			 from     serviceRheader, serviceRdetail, customer
			 where    serviceRheader.serviceRinvcode = serviceRdetail.serviceRinvcode and
			 	 serviceRheader.serviceRcatcode = 14 and 
	 			 serviceRheader.posted = 'Y' and
				 serviceRheader.date >= @ad_date  and
			 	 serviceRheader.date <= @ad_ldate  and
	 			 serviceRheader.custcode = customer.custcode

			group by serviceRheader.serviceRinvcode,
	 			serviceRheader.serviceRcatcode,
	 			serviceRheader.date,
	 			serviceRheader.discperc,
	 			serviceRheader.misccharges,
	 			serviceRheader.flatdisc,
	 			serviceRheader.custcode
			)as ServiceReturn

               group by servicereturn.custcode
		 
		) as ServiceReturnH


where reportdata.code1=ServiceReturnH.customercode
/*-----------------end serviceReturn-------------------*/


drop table #lt_pvamts

select * from reportdata
GO

-- SP_CustomerNetSaleMonthSummary (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_CustomerNetSaleMonthSummary 
	@ar_startdate datetime, 
	@ar_enddate datetime 
AS
/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'reportdata' table to be used for netsale of customers in
	cross tabulation of months
PARAMETER DESCRIPTION :
	@ar_startdate, @ar_enddate = Determine the period of report
*/

DELETE ReportData

INSERT INTO ReportData (Name1, Name2, Name3, Name4, Date1, Value1, Value2)
SELECT 
	CC.Name,
	A.AliasName,
	A.Name,
	SaleType = ISNULL((SELECT ST.Name FROM SaleType ST, SaleLedger SL WHERE SL.SaleInvCode=S.DocumentCode AND SL.SaleTypeCode=ST.SaleTypeCode), '.'),	
	Date = CAST(S.Date AS DateTime),
	NetSale = SUM(S.NetSale),
	Discount = 	
		(SELECT Discount=SUM(VG.Credit) FROM VirtualGL VG 
		WHERE VG.AccCode = A.AccCode AND
		VG.Date BETWEEN @ar_startdate AND @ar_enddate AND 
		VG.DocumentType IN ('JV') AND VG.Credit > 0)
FROM
	CustomerCategory CC,
	Customer C, 
	Accounts A,
	(SELECT 
		Date = LTRIM(RTRIM(STR(MONTH(VG.Date)))) + '/01/' + LTRIM(RTRIM(STR(YEAR(VG.Date)))),
		VG.AccCode, 
		VG.DocumentCode,
		NetSale = SUM(CASE VG.DocumentType WHEN 'SV' THEN VG.Debit WHEN 'SR' THEN  - (VG.Credit) ELSE 0 END)
	FROM VirtualGL VG 
	WHERE 
		VG.AccCode IN (SELECT AccCode FROM Accounts WHERE SubCode = 3 ) AND
		VG.Date BETWEEN @ar_startdate AND @ar_enddate AND 
		VG.DocumentType IN ('SV', 'SR') AND VG.CatCode IN (2,7)
	GROUP BY
		VG.DocumentCode, 
		VG.Date,
		VG.AccCode) S
WHERE 
	CC.CustCatCode = C.CustCatCode AND
	C.CustCode = A.AccCode AND
	A.AccCode = S.AccCode
GROUP BY
	CC.Name,
	A.AliasName,
	A.Name,
	A.AccCode,
	S.DocumentCode,
	CAST(S.Date AS DateTime)
ORDER BY
	CC.Name,
	A.Name,
	A.AliasName,
	Date
GO

-- sp_CustomersBalance (last defined by script catalog)

/****** Object:  Stored Procedure dbo.sp_CustomersBalance    Script Date: 4/23/02 4:29:59 PM ******/
/****** Object:  Stored Procedure dbo.sp_CustomersBalance    Script Date: 4/8/02 6:26:06 PM ******/
/****** Object:  Stored Procedure dbo.sp_CustomersBalance    Script Date: 3/6/02 3:39:36 PM ******/
/****** Object:  Stored Procedure dbo.sp_CustomersBalance    Script Date: 7/20/01 6:52:01 PM ******/
/****** Object:  Stored Procedure dbo.sp_CustomersBalance    Script Date: 4/19/00 1:21:26 PM ******/
CREATE PROCEDURE sp_CustomersBalance AS


create table #lt_pvamts 
(
	custcode numeric (5, 0) NOT NULL,
	debit  numeric (15, 2) NOT NULL,
	credit numeric (15, 2) NOT NULL
)

DELETE  ReportData	

/******************************* Any Credit Sales **********************************/

insert #lt_pvamts
select   customer.custcode,
	 Debit = Isnull(Round(SUM(saledetail.looseqty * saledetail.unitsalestax) + 
	 SUM(ROUND( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc)) * saledetail.gstperc * .01, 2)) +
	 Round( (sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) - saleledger.flatdisc) * (saleledger.invgstperc1 * .01), 2), 0) +
	 Round( sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0), 0),
	 Credit = 0
from     saleledger, saledetail, customer  
where    saleledger.saleinvcode = saledetail.saleinvcode and
	 saleledger.salecatcode = 2   and 
	 saleledger.Posted = 'Y'   and	
	 saleledger.custcode = customer.custcode
group by saleledger.saleinvcode,
	 salecatcode, 
	 saleledger.date,
	 saleledger.discperc,
	 saleledger.misccharges,
	 saleledger.salestax,
	 saleledger.flatdisc,
	 saleledger.invgstperc1,
	 customer.custcode

/******************************* Credit Sales Returns **********************************/

insert #lt_pvamts
select   customer.custcode,
	 Debit = 0,
	 Credit = Isnull(Round(SUM(srdetail.looseqty * srdetail.unitsalestax) + 
	 SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc)) * srdetail.gstperc * .01, 2)) +
	 Round( (sum( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) - srledger.flatdisc) * (srledger.invgstperc1 * .01), 2), 0) +
	 Round( sum( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) + srledger.misccharges + srledger.salestax - srledger.flatdisc, 0), 0)
from     srledger, srdetail, customer  
where    srledger.Srinvcode = srdetail.Srinvcode and
	 srledger.srcatcode = 7   and 
	 srledger.Posted = 'Y'   and	
	 srledger.custcode = customer.custcode
group by srledger.srinvcode,
	 srcatcode, 
	 srledger.date,
	 srledger.discperc,
	 srledger.misccharges,
	 srledger.salestax,
	 srledger.flatdisc,
	 srledger.invgstperc1,
	 customer.custcode

/******************************* Any Credit Services **********************************/

insert #lt_pvamts

select  serviceheader.custcode,
	debit = IsNull( sum(IsNull(servicedetail.price, 0) * 
	(1 - (.01 * servicedetail.discperc))) * (1- (.01 * serviceheader.discperc)) +
	serviceheader.misccharges - serviceheader.flatdisc,0),
	credit= 0.0
from     serviceheader, servicedetail, customer
where    serviceheader.serviceinvcode = servicedetail.serviceinvcode and
	 serviceheader.servicecatcode = 11     and 
	 serviceheader.posted = 'Y' and
	 serviceheader.custcode = customer.custcode

group by serviceheader.serviceinvcode,
	 serviceheader.servicecatcode,
	 serviceheader.date,
	 serviceheader.discperc,
	 serviceheader.misccharges,
	 serviceheader.flatdisc,
	 serviceheader.custcode

/******************************* Any Credit Services Returns ********************************/

insert #lt_pvamts

select  serviceRheader.custcode,
	debit = 0.0,
	credit= IsNull( sum(IsNull(serviceRdetail.Serviceprice, 0) * 
	(1 - (.01 * serviceRdetail.discperc))) * (1- (.01 * serviceRheader.discperc)) +
	serviceRheader.misccharges - serviceRheader.flatdisc,0)
from     serviceRheader, serviceRdetail, customer
where    serviceRheader.serviceRinvcode = serviceRdetail.serviceRinvcode and
	 serviceRheader.serviceRcatcode = 14 and 
	 serviceRheader.posted = 'Y' and
	 serviceRheader.custcode = customer.custcode

group by serviceRheader.serviceRinvcode,
	 serviceRheader.serviceRcatcode,
	 serviceRheader.date,
	 serviceRheader.discperc,
	 serviceRheader.misccharges,
	 serviceRheader.flatdisc,
	 serviceRheader.custcode


/********************************* Any A/c Vouchers *************************************/

insert #lt_pvamts
select   customer.custcode,
	 case sum(Round(gldetail.debit, 0))
	 when NULL then 0.0
	 else sum(Round(gldetail.debit, 0))
	 end, 
	 case sum(Round(gldetail.credit, 0))
	 when NULL then 0.0
	 else sum(Round(gldetail.credit, 0))
	 end
from     glheader, gldetail , customer
Where	glheader.posted = 'Y' and
	gldetail.acccode = customer.custcode and 
	glheader.glvochcode = gldetail.glvochcode 	
group by customer.custcode

/******************************* Any Bills Receivables **********************************/


insert #lt_pvamts
select  customer.custcode,
	0, 
	IsNull( sum(notes.amount), 0)
from    notes , customer
Where	notes.posted = 'Y' and
	notes.notecatcode = 1 and
	notes.acccode = customer.custcode

group by customer.custcode

/*********************************** Final Report *************************************/

INSERT ReportData(code1, name1, value1)

select   accounts.acccode,
	 accounts.name,
         sum(#lt_pvamts.debit) - sum(#lt_pvamts.credit) 
	
from     #lt_pvamts, accounts

where    #lt_pvamts.custcode = accounts.acccode

Group by accounts.acccode,
	 accounts.name

order by accounts.name


/***************************** Final House Keeping *********************************/

drop table #lt_pvamts

select * from reportdata
GO

-- sp_CustomerTransactionStatus (last defined by script catalog)

/****** Object:  Stored Procedure dbo.sp_CustomerTransactionStatus    Script Date: 4/23/02 4:29:59 PM ******/
/****** Object:  Stored Procedure dbo.sp_CustomerTransactionStatus    Script Date: 4/8/02 6:26:06 PM ******/
/****** Object:  Stored Procedure dbo.sp_CustomerTransactionStatus    Script Date: 3/6/02 3:39:36 PM ******/
/****** Object:  Stored Procedure dbo.sp_CustomerTransactionStatus    Script Date: 7/20/01 6:52:01 PM ******/
/****** Object:  Stored Procedure dbo.sp_CustomerTransactionStatus    Script Date: 7/12/01 10:16:17 AM ******/
/****** Object:  Stored Procedure dbo.sp_CustomerTransactionStatus    Script Date: 7/11/01 1:28:49 PM ******/
CREATE PROCEDURE sp_CustomerTransactionStatus @ad_date datetime ,@ad_ldate datetime AS

create table #lt_pvamts 
(
	debit  numeric (15, 2) NOT NULL,
	credit numeric (15, 2) NOT NULL,
	code   numeric (5,0) NOT NULL,
	name varchar(50) NOT NULL
)

/***************************** Credit Sales Transactions **********************************/

insert #lt_pvamts
select   Debit = Isnull(Round(SUM(saledetail.looseqty * saledetail.unitsalestax) + 
	 SUM(ROUND( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc)) * saledetail.gstperc * .01, 2)) +
	 Round( (sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) - saleledger.flatdisc) * (saleledger.invgstperc1 * .01), 2), 0) +
	 Round( sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0), 0),
	 credit = 0.0,
	 custcode=saleledger.custcode	,
	 name=(select accounts.name from accounts where acccode=saleledger.custcode)
     
from     saleledger, saledetail  
where    saleledger.saleinvcode = saledetail.saleinvcode and
	 saleledger.salecatcode = 2   and 
 	 saleledger.date < @ad_date  and
	 saleledger.posted = 'Y' 
	 
group by saleledger.saleinvcode,
	 salecatcode, 
         saleledger.custcode,
	 saleledger.date,
	 saleledger.discperc,
	 saleledger.misccharges,
	 saleledger.salestax,
	 saleledger.invgstperc1,
	 saleledger.flatdisc

/************************** Credit Sales Returns Transactions ******************************/

insert #lt_pvamts
select   Debit = 0.0,
	 Credit = Isnull(Round(SUM(srdetail.looseqty * srdetail.unitsalestax) + 
	 SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc)) * srdetail.gstperc * .01, 2)) +
	 Round( (sum( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) - srledger.flatdisc) * (srledger.invgstperc1 * .01), 2), 0) +
	 Round( sum( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) + srledger.misccharges + srledger.salestax - srledger.flatdisc, 0), 0),
         custcode=srledger.custcode,
	 name=(select accounts.name from accounts where acccode=srledger.custcode)
from     srledger, srdetail
where    srledger.srinvcode = srdetail.srinvcode and
	 srledger.srcatcode = 7     and 
 	 srledger.date < @ad_date  and
	 srledger.posted = 'Y' 	 
group by srledger.srinvcode,
	 srledger.srcatcode,
         srledger.custcode,
	 srledger.date,
	 srledger.discperc,
	 srledger.misccharges,
	 srledger.salestax,
	 srledger.invgstperc1,
	 srledger.flatdisc

/***************************** Credit Services Transactions ********************************/

insert #lt_pvamts

select  debit = IsNull( sum(IsNull(servicedetail.price, 0) * 
	(1 - (.01 * servicedetail.discperc))) * (1- (.01 * serviceheader.discperc)) +
	serviceheader.misccharges - serviceheader.flatdisc,0),
	credit= 0.0,
        custcode=serviceheader.custcode	,
	name=(select accounts.name from accounts where acccode=serviceheader.custcode)
from     serviceheader, servicedetail
where    serviceheader.serviceinvcode = servicedetail.serviceinvcode and
	 serviceheader.servicecatcode = 11     and 
 	 serviceheader.date < @ad_date  and
	 serviceheader.posted = 'Y' 
	

group by serviceheader.serviceinvcode,
	 serviceheader.servicecatcode,
         serviceheader.custcode,
	 serviceheader.date,
	 serviceheader.discperc,
	 serviceheader.misccharges,
	 serviceheader.flatdisc

/************************* Credit Services Returns Transactions ***************************/

insert #lt_pvamts

select  debit = 0.0,
	credit= IsNull( sum(IsNull(serviceRdetail.ServicePrice, 0) * 
		(1 - (.01 * serviceRdetail.discperc))) * (1- (.01 * serviceRheader.discperc)) +
	serviceRheader.misccharges - serviceRheader.flatdisc,0),
        custcode=serviceRheader.custcode,
	name=(select accounts.name from accounts where acccode=serviceRheader.custcode)

from     serviceRheader, serviceRdetail

where    serviceRheader.serviceRinvcode = serviceRdetail.serviceRinvcode and
	 serviceRheader.serviceRcatcode = 14 and 
 	 serviceRheader.date < @ad_date  and
	 serviceRheader.posted = 'Y' 

group by serviceRheader.serviceRinvcode,
	 serviceRheader.serviceRcatcode,
         serviceRheader.custcode,
	 serviceRheader.date,
	 serviceRheader.discperc,
	 serviceRheader.misccharges,
	 serviceRheader.flatdisc
/**************************** Any Acccounting Transactions ********************************/

insert #lt_pvamts
select  IsNull( sum(gldetail.debit), 0),
        IsNull( sum(gldetail.credit), 0),
        custcode=gldetail.acccode	,
	name=(select accounts.name from accounts where accounts.acccode=gldetail.acccode)
	 
from     glheader, gldetail  
where    glheader.glvochcode = gldetail.glvochcode and 
 	 glheader.date < @ad_date  and
	 glheader.posted = 'Y' and
         gldetail.acccode IN (select custcode from customer) 
GROUP BY gldetail.acccode	 

/******************************* Any Bills Receivables ***********************************/

insert #lt_pvamts
select  0,
        IsNull( sum(notes.amount), 0),
        custcode=notes.acccode,
        name=(select accounts.name from accounts where accounts.acccode=notes.acccode)
    
	 
from     notes
where    notes.notecatcode = 1 and
	 notes.posted = 'Y' and
	 notes.postdate < @ad_date  and
	 notes.acccode IN (select custcode from customer) 
GROUP BY notes.acccode



/******** Collecting the result and assigning to the relevent reference variable *********/
delete from reportdata
insert into reportdata(code1,name1,value1,value2,value3)
select code,name,IsNull(sum(debit) - sum(credit),0),0,0
	from   #lt_pvamts 
	group by name,
                 code 

insert into reportdata(code1,value1,value2,value3)
select customer.custcode,0,0,0

from  customer

where 
	 customer.custcode Not IN (select code1 from reportdata) 


update 	reportdata
set 	name1=accounts.name
from 	accounts,reportdata
where	reportdata.name1=Null and
	reportdata.code1=accounts.acccode



delete from #lt_pvamts





/*-----------------------------For Transactions Within The Period----------------*/
/*===============================================================================*/


/***************************** Credit Sales Transactions **********************************/

insert #lt_pvamts
select   Debit = Isnull(Round(SUM(saledetail.looseqty * saledetail.unitsalestax) + 
	 SUM(ROUND( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc)) * saledetail.gstperc * .01, 2)) +
	 Round( (sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) - saleledger.flatdisc) * (saleledger.invgstperc1 * .01), 2), 0) +
	 Round( sum( (saledetail.looseqty * (saledetail.saleprice - saledetail.itemflatdisc)) *
	    (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0), 0),
	 credit = 0.0,
	 custcode=saleledger.custcode,
	 name=(select accounts.name from accounts where acccode=saleledger.custcode)
from     saleledger, saledetail  
where    saleledger.saleinvcode = saledetail.saleinvcode and
	 saleledger.salecatcode = 2   and 
 	 saleledger.date >= @ad_date  and
	 saleledger.date <= @ad_ldate  and
	 saleledger.posted = 'Y' 
	 
group by saleledger.saleinvcode,
	 salecatcode, 
         saleledger.custcode,
	 saleledger.date,
	 saleledger.discperc,
	 saleledger.misccharges,
	 saleledger.salestax,
	 saleledger.invgstperc1,
	 saleledger.flatdisc

/************************** Credit Sales Returns Transactions ******************************/

insert #lt_pvamts
select   Debit = 0.0,
	 Credit = Isnull(Round(SUM(srdetail.looseqty * srdetail.unitsalestax) + 
	 SUM(ROUND( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc)) * srdetail.gstperc * .01, 2)) +
	 Round( (sum( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) - srledger.flatdisc) * (srledger.invgstperc1 * .01), 2), 0) +
	 Round( sum( (srdetail.looseqty * srdetail.srprice) *
	    (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) + srledger.misccharges + srledger.salestax - srledger.flatdisc, 0), 0),
         Custcode=srledger.custcode,
	 Name=(select accounts.name from accounts where acccode=srledger.custcode)
from     srledger, srdetail
where    srledger.srinvcode = srdetail.srinvcode and
	 srledger.srcatcode = 7     and 
 	 srledger.date >= @ad_date  and
	 srledger.date <= @ad_ldate  and
	 srledger.posted = 'Y' 	 

group by srledger.srinvcode,
	 srledger.srcatcode,
         srledger.custcode,
	 srledger.date,
	 srledger.discperc,
	 srledger.misccharges,
	 srledger.salestax,
	 srledger.invgstperc1,
	 srledger.flatdisc

/***************************** Credit Services Transactions ********************************/

insert #lt_pvamts

select  debit = IsNull( sum(IsNull(servicedetail.price, 0) * 
	(1 - (.01 * servicedetail.discperc))) * (1- (.01 * serviceheader.discperc)) +
	serviceheader.misccharges - serviceheader.flatdisc,0),
	credit= 0.0,
        custcode=serviceheader.custcode	,
	name=(select accounts.name from accounts where acccode=serviceheader.custcode)
from     serviceheader, servicedetail
where    serviceheader.serviceinvcode = servicedetail.serviceinvcode and
	 serviceheader.servicecatcode = 11     and 
 	 serviceheader.date >= @ad_date  and
   	 serviceheader.date <= @ad_ldate  and
	 serviceheader.posted = 'Y' 
	

group by serviceheader.serviceinvcode,
	 serviceheader.servicecatcode,
         serviceheader.custcode,
	 serviceheader.date,
	 serviceheader.discperc,
	 serviceheader.misccharges,
	 serviceheader.flatdisc

/************************* Credit Services Returns Transactions ***************************/

insert #lt_pvamts

select  debit = 0.0,
	credit= IsNull( sum(IsNull(serviceRdetail.ServicePrice, 0) * 
		(1 - (.01 * serviceRdetail.discperc))) * (1- (.01 * serviceRheader.discperc)) +
	serviceRheader.misccharges - serviceRheader.flatdisc,0),
        custcode=serviceRheader.custcode,
	name=(select accounts.name from accounts where acccode=serviceRheader.custcode)

from     serviceRheader, serviceRdetail

where    serviceRheader.serviceRinvcode = serviceRdetail.serviceRinvcode and
	 serviceRheader.serviceRcatcode = 14 and 
 	 serviceRheader.date >= @ad_date  and
	 serviceRheader.date <= @ad_ldate  and
	 serviceRheader.posted = 'Y' 

group by serviceRheader.serviceRinvcode,
	 serviceRheader.serviceRcatcode,
         serviceRheader.custcode,
	 serviceRheader.date,
	 serviceRheader.discperc,
	 serviceRheader.misccharges,
	 serviceRheader.flatdisc
/**************************** Any Acccounting Transactions ********************************/

insert #lt_pvamts
select  IsNull( sum(gldetail.debit), 0),
        IsNull( sum(gldetail.credit), 0),
        custcode=gldetail.acccode	,
	name=(select accounts.name from accounts where accounts.acccode=gldetail.acccode)
	 
from     glheader, gldetail  
where    glheader.glvochcode = gldetail.glvochcode and 
 	 glheader.date >= @ad_date  and
	 glheader.date <= @ad_ldate  and
	 glheader.posted = 'Y' and
         gldetail.acccode IN (select custcode from customer) 
GROUP BY gldetail.acccode	 

/******************************* Any Bills Receivables ***********************************/

insert #lt_pvamts
select  0,
        IsNull( sum(notes.amount), 0),
        custcode=notes.acccode,
        name=(select accounts.name from accounts where accounts.acccode=notes.acccode)
    
	 
from     notes
where    notes.notecatcode = 1 and
	 notes.posted = 'Y' and
	 notes.postdate >= @ad_date  and
         notes.postdate <= @ad_ldate  and
	 notes.acccode IN (select custcode from customer) 
GROUP BY notes.acccode



/******** Collecting the result and assigning to the relevent reference variable *********/


update reportdata

set value2=A.ddebit,value3=A.dcredit

from

(select code,name,ddebit=IsNull(sum(debit) ,0),dcredit=IsNull(sum(credit),0)
	from   #lt_pvamts 
	group by name,
                 code) as A

where reportdata.code1=A.code
 
drop table #lt_pvamts
GO

-- SP_DailyIncomeStatement_With_GP_Summary (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_DailyIncomeStatement_With_GP_Summary 
	@StartDate DATETIME, 
	@EndDate DATETIME,
	@ReportType CHAR(1),
	@Accounts VARCHAR(8000)
AS

TRUNCATE TABLE REPORTDATA 

/*
Author: M. Azhar Inayat
Purpose: Purpose of this Code is to compute the profit/loss of a period and describes
it in the form of sales/service category
Parameter Description:
	@StartDate Start DateTime
	@EndDate Ending DateTime
	@ReportType = 'M' Medical Store and 
	@ReportType = 'H' Hospital
	@ReportType = 'B' Both
	@Accounts  (Comma Separated List of Account Codes)
*/

CREATE TABLE #lt_CatAccounts (Code INT)

INSERT INTO #lt_CatAccounts
SELECT CODE FROM udf_StringToTabl(@Accounts, ',')

IF @ReportType='S' OR @ReportType='A'
BEGIN
	INSERT INTO REPORTDATA (Date1, Name1, Name2, Name3, Name4, Value1, Code1, Code2, Code3, Code4)
	SELECT	
		Date=CONVERT(DATETIME, CONVERT(VARCHAR(10), R.Date, 101)),
		FunctionalArea='S',
		Category='MED. G/P',
		Details = '',
		Type=' Revenue', 
		Amt=ROUND(SUM(R.Sales + R.Ret + R.CGS), 0),
		AccCode=-2,
		CatAccCode=-2,
		OrderBy=-1,
		Code=NULL
	FROM
		(SELECT	
			Date=CONVERT(VARCHAR(10), S.Date, 101),
			Sales=ROUND(SUM(
				CASE S.TYPE WHEN 'S' THEN 
					S.itemvalue - (S.flatdisc * (S.itemvalue/
						CASE S.grossamt WHEN 0 THEN 1 ELSE S.grossamt END))
				ELSE 0 END), 0),
			Ret=0,
			CGS=-SUM(S.Cost)
		FROM	
			(SELECT
				SL.saleinvcode,
				SL.Date,
				SD.icode,
				Cost = SUM((SD.LooseQty+SD.BonusQty) * SD.AvgPrice),
				GrossValue = SUM(SD.looseqty * SD.saleprice ) ,
				ItemDiscValue = SUM((SD.looseqty * (SD.saleprice - SD.itemflatdisc))*
									 (.01 * SD.discperc) + SD.itemflatdisc ),
				InvItemDiscValue = SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc))*
										(1 - (.01 * SD.discperc) ) *  (.01 * SL.discperc) ),
				ItemValue=SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc))*
					(1 - (.01 * SD.discperc))) * (1 - (.01 * SL.discperc)),
				GrossAmt=
					(SELECT SUM((SDD.looseqty*(SDD.saleprice - SDD.itemflatdisc)) *
						(1 - (.01 * SDD.discperc)) * (1- (.01 * SLL.discperc)))
					FROM	saledetail SDD, saleledger SLL
					WHERE SLL.saleinvcode=SL.saleinvcode and SLL.saleinvcode=SDD.saleinvcode
					GROUP BY SLL.saleinvcode),
				SL.flatdisc,
				catcode=SL.salecatcode,
				type='S'
			FROM
				saleledger SL,	 
				saledetail SD
			WHERE
				SL.SaleInvCode = SD.SaleInvCode AND
				SL.Date >= @StartDate AND SL.Date <= @EndDate
			GROUP BY 
				 SL.saleinvcode,
				 SL.Date,
				 SL.salesmancode,
				 SD.icode,
				 SL.salecatcode,
				 SL.discperc,
				 SL.flatdisc,
				 SL.invgstperc1,
				 SL.salecatcode) S
		GROUP BY 
			CONVERT(VARCHAR(10), S.Date, 101)
		UNION ALL
		SELECT	
			Date=CONVERT(VARCHAR(10), S.Date, 101),
			Sales=0,
			Ret=-ROUND(SUM(
			CASE S.TYPE WHEN 'R' THEN
				S.itemvalue - (S.flatdisc*(S.itemvalue/
					CASE S.grossamt WHEN 0 THEN 1 
					ELSE S.grossamt END)) 
			ELSE 0 END), 0),
			CGS=SUM(S.Cost)
		FROM	
			(SELECT
				SL.srinvcode,
				SL.Date,
				SD.icode,
				Cost = SUM((SD.LooseQty+SD.BonusQty) * SD.AvgPrice),
				GrossValue = SUM( SD.looseqty * SD.srprice ) ,
				ItemDiscValue = SUM((SD.looseqty * SD.srprice ) * (.01 * SD.discperc) ),
				InvItemDiscValue = SUM( ( (SD.looseqty * SD.srprice) *
											(1 - (.01 * SD.discperc) ) ) * (.01 * SL.discperc) ),
				ItemValue=SUM((SD.looseqty * SD.srprice *
					(1 - (.01 * SD.discperc))) * (1 - (.01 * SL.discperc))),
				GrossAmt=(SELECT SUM((SDD.looseqty * SDD.srprice *
						(1 - (.01 * SDD.discperc))) * (1- (.01 * SLL.discperc)))
					FROM	srdetail SDD, srledger SLL
					WHERE SLL.srinvcode=SL.srinvcode and SLL.srinvcode=SDD.srinvcode
					GROUP BY SLL.srinvcode),
				SL.flatdisc,
				catcode=SL.srcatcode,
				type='R'
			FROM
				srledger SL,	 
				srdetail SD
			WHERE
				SL.SRInvCode = SD.SRInvCode AND
				SL.Date >= @StartDate AND SL.Date <= @EndDate
			GROUP BY
				 SL.srinvcode,
				 SL.Date,
				 SL.salesmancode,
				 SD.icode,
				 SL.srcatcode,
				 SL.discperc,
				 SL.flatdisc,
				 SL.invgstperc1,
				 SL.srcatcode) S
		GROUP BY 
			CONVERT(VARCHAR(10), S.Date, 101)) R
	GROUP BY 
		R.Date
END

IF @ReportType='H' OR @ReportType='A'
BEGIN
	INSERT INTO REPORTDATA (Date1, Name1, Name2, Name3, Name4, Value1, Code1, Code2, Code3, Code4)
	SELECT	
		Date=CONVERT(DATETIME, CONVERT(VARCHAR(10), R.Date, 101)),
		FunctionalArea='H',
		Category=(SELECT SC.Name FROM ServiceCategory SC WHERE SC.ServiceCatCode = R.ServiceCatCode),
		Details = '',
		Type=' Revenue', 
		Amt=ROUND(SUM(R.Sales + R.Ret), 0),
		AccCode=-1,
		CatAccCode=-1,
		OrderBy=0,
		Code=NULL
	FROM
		(SELECT	
			Date=CONVERT(VARCHAR(10), S.Date, 101),
			SV.ServiceCatCode,
			Sales=ROUND(SUM(
				CASE S.TYPE WHEN 'S' THEN 
					S.itemvalue - (S.flatdisc * (S.itemvalue/
						CASE S.grossamt WHEN 0 THEN 1 ELSE S.grossamt END))
				ELSE 0 END), 0),
			Ret=0
		FROM	
			(SELECT
				SL.Serviceinvcode,
				SL.Date,
				SD.servicecode,
				GrossValue = SUM(SD.qty * SD.price ) ,
				ItemDiscValue = SUM((SD.qty * SD.price)*
									 (.01 * SD.discperc)),
				InvItemDiscValue = SUM((SD.qty * SD.price) *
										(1 - (.01 * SD.discperc) ) *  (.01 * SL.discperc) ),
				ItemValue=SUM((SD.qty * SD.price)*
					(1 - (.01 * SD.discperc))) * (1 - (.01 * SL.discperc)),
				GrossAmt=
					(SELECT SUM((SDD.qty * SDD.Price) *
						(1 - (.01 * SDD.discperc)) * (1- (.01 * SLL.discperc)))
					FROM	servicedetail SDD, serviceheader SLL
					WHERE SLL.serviceinvcode=SL.serviceinvcode and SLL.serviceinvcode=SDD.serviceinvcode
					GROUP BY SLL.serviceinvcode),
				SL.flatdisc,
				type='S'
			FROM
				serviceheader SL, servicedetail SD
			WHERE
				SL.serviceInvCode = SD.serviceInvCode AND
				SL.Date >= @StartDate AND SL.Date <= @EndDate
			GROUP BY 
				 SL.serviceinvcode,
				 SL.Date,
				 SL.salesmancode,
				 SD.servicecode,
				 SL.servicecatcode,
				 SL.discperc,
				 SL.flatdisc) S, Service SV
		WHERE 
			S.ServiceCode = SV.ServiceCode
		GROUP BY 
			CONVERT(VARCHAR(10), S.Date, 101), SV.ServiceCatCode
		UNION ALL
		SELECT	
			Date=CONVERT(VARCHAR(10), S.Date, 101),
			SV.ServiceCatCode,
			Sales=0,
			Ret=-ROUND(SUM(
			CASE S.TYPE WHEN 'R' THEN
				S.itemvalue - (S.flatdisc*(S.itemvalue/
					CASE S.grossamt WHEN 0 THEN 1 
					ELSE S.grossamt END)) 
			ELSE 0 END), 0)
		FROM	
			(SELECT
				SL.servicerinvcode,
				SL.Date,
				SD.servicecode,
				GrossValue = SUM( SD.qty * SD.serviceprice ) ,
				ItemDiscValue = SUM((SD.qty * SD.serviceprice ) * (.01 * SD.discperc) ),
				InvItemDiscValue = SUM( ( (SD.qty * SD.serviceprice) *
											(1 - (.01 * SD.discperc) ) ) * (.01 * SL.discperc) ),
				ItemValue=SUM((SD.qty * SD.serviceprice *
					(1 - (.01 * SD.discperc))) * (1 - (.01 * SL.discperc))),
				GrossAmt=(SELECT SUM((SDD.qty * SDD.serviceprice *
						(1 - (.01 * SDD.discperc))) * (1- (.01 * SLL.discperc)))
					FROM	servicerdetail SDD, servicerheader SLL
					WHERE SLL.servicerinvcode=SL.servicerinvcode and SLL.servicerinvcode=SDD.servicerinvcode
					GROUP BY SLL.servicerinvcode),
				SL.flatdisc,
				type='R'
			FROM
				servicerheader SL, servicerdetail SD
			WHERE
				SL.ServiceRInvCode = SD.ServiceRInvCode AND
				SL.Date >= @StartDate AND SL.Date <= @EndDate
			GROUP BY
				 SL.servicerinvcode,
				 SL.Date,
				 SL.salesmancode,
				 SD.servicecode,
				 SL.servicercatcode,
				 SL.discperc,
				 SL.flatdisc) S, Service SV
		WHERE S.ServiceCode = SV.ServiceCode
		GROUP BY 
			CONVERT(VARCHAR(10), S.Date, 101), SV.ServiceCatCode) R
	GROUP BY 
		R.Date, R.ServiceCatCode
END 

INSERT INTO REPORTDATA (Date1, Name1, Name2, Name3, Name4, Value1, Code1, Code2, Code3, Code4)
SELECT 
	Date=CONVERT(DATETIME, CONVERT(VARCHAR(10), @ENDDate, 101)),
	FunctionalArea='A',
	Category='z Expenses',
	Details = 'Expense',
	Type='Expenses', 
	Amt = SUM(Credit - DEBIT),
	AccCode= -1,
	CatAccCode= -2,
	OrderBy=1,
	Code=NULL
FROM Accounts A, GLHeader H, GLDetail GD, SubAccounts S, CategoryAccounts C
WHERE
	H.Date >= @StartDate AND H.Date <= @EndDate AND
	H.Posted = 'Y' AND 
	H.GLVochCode = GD.GLVochCode AND 
	GD.AccCode = A.AccCode AND
	A.SubCode = S.SubAccCode AND
	S.CatAccCode IN (SELECT CODE FROM #lt_CatAccounts) AND
	S.CatAccCode = C.CatAccCode AND
	C.MainAccCode IN (5)

INSERT INTO REPORTDATA (Date1, Name1, Name2, Name3, Name4, Value1, Code1, Code2, Code3, Code4)
SELECT 
	Date=CONVERT(DATETIME, CONVERT(VARCHAR(10), H.Date, 101)),
	FunctionalArea=GD.Remarks,
	Category=C.Name,
	Details = A.Name,
	GroupAccount=S.Name, 
	Amt = Credit - DEBIT,
	AccCode= A.AccCode,
	CatAccCode=C.CatAccCode,
	OrderBy=2,
	Code=H.GLVochCode
FROM Accounts A, GLHeader H, GLDetail GD, SubAccounts S, CategoryAccounts C
WHERE
	H.Date >= @StartDate AND H.Date <= @EndDate AND
	H.Posted = 'Y' AND 
	H.GLVochCode = GD.GLVochCode AND 
	GD.AccCode = A.AccCode AND
	A.SubCode = S.SubAccCode AND
	S.CatAccCode IN (SELECT CODE FROM #lt_CatAccounts) AND
	S.CatAccCode = C.CatAccCode AND
	C.MainAccCode IN (5)
GO

-- SP_DailyIncomeStatement_With_GP_Summary2 (last defined by script catalog)
CREATE PROCEDURE DBO.SP_DailyIncomeStatement_With_GP_Summary2
	@StartDate DATETIME, 
	@EndDate DATETIME,
	@Accounts VARCHAR(8000)
AS

TRUNCATE TABLE REPORTDATA 

/*
Author: M. Azhar Inayat
Purpose: Purpose of this Code is to compute the profit/loss of a period and describes
it in the form of sales/service category
Parameter Description:
	@StartDate Start DateTime
	@EndDate Ending DateTime
	@Accounts  (Comma Separated List of Account Codes)
*/

CREATE TABLE #lt_CatAccounts (Code INT)

INSERT INTO #lt_CatAccounts
SELECT CODE FROM udf_StringToTabl(@Accounts, ',')

INSERT INTO REPORTDATA (Name1, Name2, Name3, Value1, Value2, Code1)
SELECT	
	PatientName = (SELECT LTRIM(RTRIM(P.Name)) + ' (' + LTRIM(RTRIM(P.RegNo)) + ')' FROM Patient P WHERE P.PatientCode = R.PatientCode),
	Category=(SELECT SC.Name FROM ServiceCategory SC WHERE SC.ServiceCatCode = R.ServiceCatCode),
	Type=' Revenue', 
	Amt=ROUND(SUM(R.GrossSales - R.GrossRet), 0),
	Discount=ROUND(SUM(R.SaleDiscount - R.RetDiscount), 0),
	OrderBy=0
FROM
	(SELECT	
		S.PatientCode,
		SV.ServiceCatCode,
		GrossSales=ISNULL(SUM(S.GrossValue), 0),
		SaleDiscount= ISNULL(SUM(S.Discount), 0),
		GrossRet=0.00,
		RetDiscount=0.00
	FROM	
		(SELECT
			SL.PatientCode,
			SD.servicecode,
			GrossValue = SUM(SD.qty * SD.price ) ,
			Discount = 
			ISNULL(SUM(SD.qty * SD.ServiceFlatDisc), 0) + 
			ISNULL(SUM((SD.qty * (SD.price - SD.ServiceFlatDisc)) * (.01 * SD.discperc)), 0) + 
			ISNULL(SUM((SD.qty * (SD.price - SD.ServiceFlatDisc)) * (1 - (.01 * SD.discperc) ) *  (.01 * SL.discperc) ), 0) +
			ISNULL(SL.flatdisc, 0),
			type='S'
		FROM
			serviceheader SL, servicedetail SD
		WHERE
			SL.serviceInvCode = SD.serviceInvCode AND
			SL.Date >= @StartDate AND SL.Date <= @EndDate
		GROUP BY 
			 SL.serviceinvcode,
			 SL.Date,
			 SL.salesmancode,
			 SD.servicecode,
			 SL.servicecatcode,
			 SL.PatientCode,
			 SL.discperc,
			 SL.flatdisc) S, Service SV
	WHERE 
		S.ServiceCode = SV.ServiceCode
	GROUP BY 
		S.PatientCode, SV.ServiceCatCode
	UNION ALL
	SELECT	
		S.PatientCode,
		SV.ServiceCatCode,
		GrossSales=0.00,
		SaleDiscount= 0.00,
		GrossRet=ISNULL(SUM(S.GrossValue), 0),
		RetDiscount=ISNULL(SUM(S.Discount), 0)
	FROM	
		(SELECT
			SL.PatientCode,
			SD.servicecode,
			GrossValue = SUM(SD.qty * SD.serviceprice ) ,
			Discount = 
			ISNULL(SUM(SD.qty * SD.ServiceFlatDisc), 0) + 
			ISNULL(SUM((SD.qty * (SD.serviceprice - SD.ServiceFlatDisc)) * (.01 * SD.discperc)), 0) + 
			ISNULL(SUM((SD.qty * (SD.serviceprice - SD.ServiceFlatDisc)) * (1 - (.01 * SD.discperc) ) *  (.01 * SL.discperc) ), 0) +
			ISNULL(SL.flatdisc, 0),
			type='R'
		FROM
			serviceRheader SL, serviceRdetail SD
		WHERE
			SL.serviceRInvCode = SD.serviceRInvCode AND
			SL.Date >= @StartDate AND SL.Date <= @EndDate
		GROUP BY 
			 SL.serviceRinvcode,
			 SL.Date,
			 SL.salesmancode,
			 SD.servicecode,
			 SL.serviceRcatcode,
			 SL.PatientCode,
			 SL.discperc,
			 SL.flatdisc) S, Service SV
	WHERE 
		S.ServiceCode = SV.ServiceCode
	GROUP BY 
		S.PatientCode, SV.ServiceCatCode) R
GROUP BY 
	R.PatientCode, R.ServiceCatCode
UNION ALL
SELECT 
	PatientName = A.Name,
	Category='«Expenses»',
	Type='Expenses', 
	Amt = SUM(Credit - DEBIT),
	Discount = 0,
	OrderBy=1
FROM Accounts A, GLHeader H, GLDetail GD, SubAccounts S, CategoryAccounts C
WHERE
	H.Date >= @StartDate AND H.Date <= @EndDate AND
	H.Posted = 'Y' AND 
	H.GLVochCode = GD.GLVochCode AND 
	GD.AccCode = A.AccCode AND
	A.SubCode = S.SubAccCode AND
	S.CatAccCode IN (SELECT CODE FROM #lt_CatAccounts) AND
	S.CatAccCode = C.CatAccCode AND
	C.MainAccCode IN (5)
GROUP BY A.Name
GO

-- sp_DailyLedger_LPLedger (last defined by script catalog)
CREATE PROCEDURE sp_DailyLedger_LPLedger 
	@custcode INTEGER,
	@datetype VARCHAR(100),
	@start_date DATETIME, 
	@end_date DATETIME,
	@caption VARCHAR(100)
AS

DELETE ReportData

CREATE TABLE #sale (
	CustAliasName VARCHAR(20),
	Customer VARCHAR(100),
	ICode INT,
	ItemAliasName VARCHAR(100),
	ItemName VARCHAR(100),
	PackingDesc VARCHAR(100),
	Packing VARCHAR(100),
	SaleQty NUMERIC(15,4),
	FormNoAndQty VARCHAR(4000)
)

INSERT INTO #sale
SELECT 
	CustomerAliasName=A.AliasName,
	Customer = A.Name,
	ICode = SD.ICode,
	ItemAliasName=I.CustomICode,
	ItemName = I.Name,
	PackingDesc = I.PackingDesc,
	Packing = (SELECT IP.Name FROM ItemPacking IP WHERE IP.PackCode = I.PackCode),
	SaleQty = SUM(SD.LooseQty),
	FormNoAndQty = ''
FROM
	Item I, SaleLedger SL, SaleInvDetail SD, Accounts A
WHERE
	CASE 
	WHEN lower(@datetype) = 'originaldate' THEN SL.OriginalDate 
	WHEN lower(@datetype) = 'lastsavingdate' THEN SL.Date 
	WHEN lower(@datetype) = 'billingdate' THEN SL.BillingDate 
	ELSE SL.Date 
	End Between @start_date AND @end_date AND
	SL.CustCode = @custcode AND
	SL.CustCode = A.AccCode AND
	SL.Posted = 'Y' AND
	SL.SaleInvCode = SD.SaleInvCode AND
	SD.ICode = I.ICode
GROUP BY
	A.AliasName,
	A.Name,
	SD.ICode,
	I.CustomICode,
	I.Name,
	I.PackingDesc,
	I.PackCode

UPDATE #Sale SET FormNoAndQty = dbo.Fn_GetFormNoAndQty_DailyLedger(@custcode, ICode, @datetype, @start_date, @end_date)

SELECT 
	CustAliasName,
	Customer,
	ICode,
	ItemAliasName,
	ItemName,
	PackingDesc,
	Packing,
	SaleQty,
	FormNoAndQty
FROM #Sale
ORDER BY ItemName
GO

-- SP_DateWiseSaleBreakup (last defined by script catalog)
CREATE PROCEDURE SP_DateWiseSaleBreakup
	@ai_custcode int,
	@ad_startdate datetime,
	@ad_enddate datetime,
	@ai_days int,
	@ad_discperc numeric(6, 2)
AS 

/*
Author :
	M. Azhar Inayat
Purpose:
	This report displays the breakup of sales in specified sales period

PARAMETER DESCRIPTION :
	This function takes following parameters i.e. 
		1. @ai_custcode  = customer code whose sale is to required
		2. @ad_startdate = suggests the sale period start point
		3. @ad_enddate   = suggests the sale period end point
		4. @ai_days      = the chunk duraion in terms of days
		5. @ad_discperc  = discount %age to applied to sale
*/

DELETE ReportData

DECLARE @tmpdate datetime, @tmpdate2 datetime
DECLARE @counter int
DECLARE @date_str VARCHAR(100)
SET @tmpdate = @ad_startdate
SET @counter = 1

WHILE @tmpdate + @ai_days <= @ad_enddate
BEGIN
	SET @date_str = CONVERT(VARCHAR(100), @tmpdate + @ai_days - 1, 101) + ' 23:59:59'
	INSERT INTO ReportData (Date1, Date2, Code1, Code2)
	SELECT @tmpdate, CONVERT(DateTime, @date_str), @ai_custcode, @Counter

	SET @tmpdate = @tmpdate + @ai_days
	SET @counter = @counter + 1
END

INSERT INTO ReportData (Date1, Date2, Code1, Code2)
SELECT @tmpdate, @ad_enddate, @ai_custcode, @Counter

UPDATE ReportData
SET
	Name1 = (SELECT A.AliasName FROM Accounts A WHERE A.AccCode = @ai_custcode),
	Name2 = (SELECT A.Name FROM Accounts A WHERE A.AccCode = @ai_custcode),
	Code3 = 
		(SELECT MIN(S.SaleInvCode) FROM SaleLedger S
		WHERE S.CustCode = @ai_custcode AND S.Date BETWEEN ReportData.Date1 AND ReportData.Date2),
	Code4 = 
		(SELECT MAX(S.SaleInvCode) FROM SaleLedger S
		WHERE S.CustCode = @ai_custcode AND S.Date BETWEEN ReportData.Date1 AND ReportData.Date2),
	Code5  = @ad_discperc,
	Value1 = 
		(SELECT SUM(S.netamount) 
		FROM 
			(SELECT 
			netamount = 
					Round(
					SUM((saledetail.looseqty*(saledetail.saleprice - saledetail.itemflatdisc)) *
						(1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + 
							saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0)
					+
					Round(
					SUM( (saledetail.looseqty + saledetail.bonusqty) * saledetail.unitsalestax) + 
					SUM(ROUND( (saledetail.looseqty * 
								  (saledetail.saleprice - saledetail.itemflatdisc)) *
								  (1 - (.01 * saledetail.discperc)) * saledetail.gstperc * .01, 2)) +
						 ROUND( (SUM((saledetail.looseqty * 
								(saledetail.saleprice - saledetail.itemflatdisc)) *
								(1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) -
								saleledger.flatdisc) * (saleledger.invgstperc1 * .01), 2), 0)
			FROM SaleLedger, SaleDetail
			WHERE 
				SaleLedger.CustCode = @ai_custcode AND 
				SaleLedger.Date BETWEEN ReportData.Date1 AND ReportData.Date2 AND
				SaleLedger.SaleInvCode = SaleDetail.SaleInvCode
			GROUP BY
				SaleLedger.saleinvcode,   
				SaleLedger.date,
				SaleLedger.salecatcode, 
				SaleLedger.patientcode,
				SaleLedger.custrefno,	 
				SaleLedger.remarks,
				SaleLedger.relationcode,
				SaleLedger.DiscPerc,
				SaleLedger.MiscCharges,
				SaleLedger.SalesTax,
				SaleLedger.FlatDisc,
				SaleLedger.DiscPerc,
				SaleLedger.FlatDisc,
				SaleLedger.InvGSTPerc1
			UNION ALL
			SELECT 
			netamount = 
					Round(
					SUM((saledetail.looseqty*(saledetail.saleprice - saledetail.itemflatdisc)) *
						(1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + 
							saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0)
					+
					Round(
					SUM( (saledetail.looseqty + saledetail.bonusqty) * saledetail.unitsalestax) + 
					SUM(ROUND( (saledetail.looseqty * 
								  (saledetail.saleprice - saledetail.itemflatdisc)) *
								  (1 - (.01 * saledetail.discperc)) * saledetail.gstperc * .01, 2)) +
						 ROUND( (SUM((saledetail.looseqty * 
								(saledetail.saleprice - saledetail.itemflatdisc)) *
								(1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) -
								saleledger.flatdisc) * (saleledger.invgstperc1 * .01), 2), 0)
			FROM SaleLedger, SaleInvDetail SaleDetail
			WHERE 
				SaleLedger.CustCode = @ai_custcode AND 
				SaleLedger.ImpactInventory = 'N' AND
				SaleLedger.Date BETWEEN ReportData.Date1 AND ReportData.Date2 AND
				SaleLedger.SaleInvCode = SaleDetail.SaleInvCode
			GROUP BY
				SaleLedger.saleinvcode,   
				SaleLedger.date,
				SaleLedger.salecatcode, 
				SaleLedger.patientcode,
				SaleLedger.custrefno,	 
				SaleLedger.remarks,
				SaleLedger.relationcode,
				SaleLedger.DiscPerc,
				SaleLedger.MiscCharges,
				SaleLedger.SalesTax,
				SaleLedger.FlatDisc,
				SaleLedger.DiscPerc,
				SaleLedger.FlatDisc,
				SaleLedger.InvGSTPerc1) S)

RETURN 0
GO

-- SP_DB_MarkExpiryIntimationAsPulled (last defined by script 7918)
CREATE PROCEDURE dbo.SP_DB_MarkExpiryIntimationAsPulled
	@SiteCode SMALLINT,
	@SInvCode INT,
	@UserCode SMALLINT,
	@SRV VARCHAR(100),
	@DB VARCHAR(100),
	@OWNER VARCHAR(100)
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON
SET NOCOUNT ON
SET XACT_ABORT ON
DECLARE @Upd VARCHAR(4000), @Prefix VARCHAR(4000)
DECLARE @err INT

SET @Prefix=''
IF (LEN(LTRIM(RTRIM(@SRV))) = 0 OR @SRV IS NULL) 
	SET @Prefix = ''
ELSE
	SET @Prefix = @SRV + '.' 

IF (LEN(LTRIM(RTRIM(@DB))) = 0 OR @DB IS NULL)
	SET @Prefix = @Prefix
ELSE
	SET @Prefix = @Prefix + @DB + '.'

IF (LEN(LTRIM(RTRIM(@OWNER))) = 0 OR @OWNER IS NULL)
	SET @Prefix = @Prefix + 'DBO' + '.'
ELSE
	SET @Prefix = @Prefix + @OWNER + '.'

SET @UPD = 'UPDATE ' + @Prefix + 'DB_ExpiryIntimation Set Pulled=''Y'',PulledOn=GETDATE(),PulledBy=' + LTRIM(RTRIM(STR(@UserCode))) + ' WHERE SiteCode = ' + LTRIM(RTRIM(STR(@SiteCode))) + ' AND IntimationCode = ' + LTRIM(RTRIM(STR(@SInvCode)))

EXECUTE (@UPD)
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RAISERROR('Data Updation: Error Updating Expiry Intimation Header into Drop Box', 16, 1)
	RETURN -1
END 
RETURN 0
GO

