-- sp_DeleteItemStockBatch (last defined by script catalog)
CREATE  PROCEDURE SP_DeleteItemStockBatch 
	@GCode integer, 
	@ICode integer, 
	@Batch varchar (100), 
	@Expiry datetime , 
	@OldQty NUMERIC(15, 4)
AS

Declare @itemname VarChar(60)
Declare @string_expiry VarChar(25)

Delete GodownDetail
Where
	GodownDetail.GCode  = @GCode and
	GodownDetail.ICode  = @ICode and
	GodownDetail.Batch  = @Batch and
	GodownDetail.Expiry = @Expiry and
	GodownDetail.CurrQty = @OldQty

IF @@RowCount = 0 OR @@Error  <>  0
Begin
	Select @itemname = name
    From Item
	Where Icode = @icode

    Set @string_expiry = CONVERT ( VarChar(25) , @expiry , 103 )
    RAISERROR  ('Not enough stock available for the item (%s) in batch no. (%s) with expiry (%s)' , 16 , 1,  @itemname , @batch , @string_expiry  )    
	Return -1   
End
Return 0
GO

-- SP_DeletePostedTransactions (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_DeletePostedTransactions
AS
DECLARE @err INT, @RowID INT, @Script VARCHAR(1000), @Stmt VARCHAR(100), @tablename VARCHAR(255)
DECLARE @maxlogid int, @KeepBal CHAR(1)

SET @KeepBal = DBO.Fn_GetPreference('keep_accbal_on_archive')
SET @KeepBal = ISNULL(@KeepBal,'Y')

IF @KeepBal='Y'
BEGIN
-- Fill up the a/c repository for later use
	EXECUTE @err = DBO.SP_VirtualGL 'A'
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		RaisError('Problem in Executing Accounting Repository.', 16, 1)
		RETURN -1
	END
	
	SET @maxlogid = ISNULL((SELECT MAX(LogID) FROM AccountBalanceLog), 0) + 1
	IF @maxlogid <= 0
	BEGIN
		RaisError('Problem in fetching maximum log id.', 16, 1)
		RETURN -1
	END
	
	INSERT INTO AccountBalanceLog (LogID, Date, AccCode, Balance)
	SELECT 
		LogID = @maxlogid,
		Date = GETDATE(),
		A.AccCode, 
		Balance=Sum(ISNULL(V.Debit,0) - ISNULL(V.Credit, 0))
	FROM VirtualGL V, Accounts A
	WHERE V.AccCode = A.AccCode
	GROUP BY A.AccCode
	HAVING Sum(ISNULL(V.Debit,0) - ISNULL(V.Credit, 0)) <> 0
	
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		RaisError('Problem in Insert Account balance log.', 16, 1)
		RETURN -1
	END
END

