SELECT 770, 'ServicePurDetail', 'Y', 'ServicePurHeader', 'ServicePurInvCode', 'Y', 'Y'
UNION ALL
SELECT 780, 'ServicePrHeader', 'Y', NULL, 'ServicePrInvCode', 'N', 'Y'
UNION ALL
SELECT 790, 'ServicePrDetail', 'Y', 'ServicePrHeader', 'ServicePrInvCode', 'Y', 'Y'
UNION ALL
SELECT 800, 'ServicePrAllocationHeader', 'Y', NULL, 'ServicePrAllocationCode', 'N', 'Y'
UNION ALL
SELECT 810, 'ServicePrAllocationDetail', 'Y', 'ServicePrAllocationHeader', 'ServicePrAllocationCode', 'Y', 'Y'
--Accounting Tables
UNION ALL
SELECT 1010, 'GLHeader', @ArchAccData, NULL, 'GLVochCode', 'N', 'Y'
UNION ALL
SELECT 1020, 'GLDetail', @ArchAccData, 'GLHeader', 'GLVochCode', 'Y', 'Y'
UNION ALL
SELECT 1030, 'Notes', @ArchAccData, NULL, 'NoteCode', 'Y', 'Y'
UNION ALL
SELECT 1040, 'NotesDetail', @ArchAccData, 'Notes', 'NoteCode', 'Y', 'Y'
UNION ALL
SELECT 1050, 'TransactionHeader', @ArchAccData, NULL, 'DocumentCode', 'N', 'Y'
UNION ALL
SELECT 1060, 'TransactionDetail', @ArchAccData, 'TransactionHeader', 'DocumentCode', 'Y', 'Y'
UNION ALL
SELECT 1065, 'AvgPriceAdjHeader', @ArchAccData, NULL, 'DocumentCode', 'N', 'Y'
UNION ALL
SELECT 1070, 'AvgPriceAdjDetail', @ArchAccData, 'AvgPriceAdjHeader', 'DocumentCode', 'Y', 'Y'

DECLARE C1 CURSOR FOR
SELECT RowID, TableName, Synchronize, ParentTable, ParentPK, UpdateParent, Posted
FROM #ins_temp
ORDER BY ROWID DESC

OPEN C1

FETCH NEXT FROM C1
INTO @RowID, @TableName, @Synchronize, @ParentTable, @ParentPK, @UpdateParent, @Posted
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @QRY = N''

	IF @Synchronize='Y'
	BEGIN
		IF @ParentTable IS NULL
		BEGIN
			IF @TableName = 'SRBufferLedger'
			BEGIN
				UPDATE SaleLedger SET SRBufferInvCode = NULL WHERE SRBufferInvCode > 0
			END
			IF @TableName = 'SaleLedger'
			BEGIN
				UPDATE BillSummaryDetail SET SaleInvCode = NULL WHERE SaleInvCode > 0
				UPDATE BillSummaryDetail SET SaleInvCode = NULL WHERE SaleInvCode > 0
				UPDATE ServiceHeader SET SaleInvCode = NULL WHERE SaleInvCode > 0
			END
			SET @QRY = N'DELETE ' + @TableName + ' WHERE Synced = ''Y'''

		END
		ELSE
		BEGIN
			SET @QRY = N'DELETE ' + @TableName + ' WHERE ' + @ParentPK + ' IN (SELECT ' + @ParentPK + ' FROM ' + @ParentTable + ' WHERE Synced = ''Y'')' 
		END
		
		IF LEN(LTRIM(RTRIM(@Qry))) > 0
		BEGIN
			print @Qry
			EXECUTE (@Qry)
			SET @err = @@ERROR
			IF @@ERROR <> 0 OR @err <> 0
			BEGIN
				RAISERROR('Data Deletion: Error Transfering %s Data', 16, 1, @TableName)
				CLOSE C1
				DEALLOCATE C1
				RETURN -1
			END
		END
	END
	FETCH NEXT FROM C1
	INTO @RowID, @TableName, @Synchronize, @ParentTable, @ParentPK, @UpdateParent, @Posted
END
CLOSE C1
DEALLOCATE C1

RETURN 0
GO

-- SP_Drop_Constraint (last defined by script catalog)
CREATE PROCEDURE DBO.SP_Drop_Constraint @TableName VARCHAR(255), @ConstraintType VARCHAR(255)
AS
DECLARE @Stmt VARCHAR(8000), @Constraint VARCHAR(1000)

SET @Stmt = 'ALTER TABLE '

SET @Constraint = (SELECT so2.Name FROM SysObjects so, SysConstraints sc, sysobjects so2 WHERE so.Name=@TableName AND so.id = sc.id AND sc.ConstID = so2.id AND so2.xtype=@ConstraintType)

IF LEN(LTRIM(RTRIM(@Constraint))) <= 0 RETURN 0

SET @Stmt = 'ALTER TABLE DBO.' + LTRIM(RTRIM(@TableName)) + ' DROP CONSTRAINT ' + @Constraint

EXECUTE (@Stmt)

RETURN 0
GO

-- SP_DropColumnLevelConstraint (last defined by script catalog)
CREATE PROCEDURE SP_DropColumnLevelConstraint
AS

DECLARE @ConstCount INT, @LoopCount INT, @Priority NUMERIC(6,2)
DECLARE @Table VARCHAR(60), @Col VARCHAR(60), @Const VARCHAR(1000), @Stmt VARCHAR(8000)
DECLARE @OldTable VARCHAR(60)

DECLARE C1 CURSOR FOR
SELECT dd.tablename, dd.columnname, dd.priority, so.name
FROM
	(select so.id, so.name from sysobjects so) p, 
	sysobjects so, 
	sysconstraints sc,
	dropdata dd
WHERE
	dd.tablename = p.name and
	p.id = so.parent_obj and
	so.id = sc.constid and 
	so.parent_obj in (OBJECT_ID(p.name)) /* and 
	xtype ='D'*/ and 
	sc.colid > 0 AND 
	sc.colid in
	(SELECT sl.colid 
	FROM syscolumns sl 
	WHERE
		sl.id IN (OBJECT_ID(p.name)) and 
		sl.name IN (dd.columnname))
ORDER BY dd.priority

OPEN C1
FETCH NEXT FROM C1 INTO @Table, @Col, @Priority, @Const
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @Stmt = 'ALTER TABLE DBO.' + LTRIM(RTRIM(@Table)) + ' DROP CONSTRAINT ' + LTRIM(RTRIM(@Const))
	EXECUTE (@Stmt)
	FETCH NEXT FROM C1 INTO @Table, @Col, @Priority, @Const
END
CLOSE C1
DEALLOCATE C1

RETURN 0
GO

-- SP_DropImportTables (last defined by script catalog)
CREATE   PROCEDURE SP_DropImportTables
AS
/*
Author: Muhammad Azhar Inayat
Version:1.0
Comments:This stored procedure is build using iterative prototyping sofware process model so at this
	 stage some of the temporary basic data tables (acting as import buffer area) are used for storing data.
	 This SP must be execute before executing the following stored procedures.
	 1-SP_ImportData	
	 2-sp_SynchronizeData
*/
SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

/*Variables to be used in drop process*/
DECLARE @TableName NVARCHAR(255), @DropQuery NVARCHAR(1000)
DECLARE @err INT

DECLARE TmpCrs1 CURSOR FOR
SELECT TABLENAME = 'DBO.Import_' + LTRIM(RTRIM(TABLENAME))
FROM TransferableData 
WHERE Enable='Y' AND (AUTOINSERT = 'Y' OR AUTOUPDATE = 'Y' OR AUTODELETE = 'Y' OR UPDATETABMAXKEY = 'Y')
ORDER BY Priority

OPEN TmpCrs1

FETCH NEXT FROM TmpCrs1 INTO @TableName
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @DropQuery = 'DROP TABLE ' + @TableName

	IF exists (select * from dbo.sysobjects where id = object_id(@TableName) and OBJECTPROPERTY(id, N'IsUserTable') = 1)
	BEGIN
		EXECUTE (@DropQuery)
		SET @err = @@ERROR
		IF @@ERROR <> 0 OR @err <> 0
		BEGIN
			RAISERROR('Problem occurred while execution of Import Tables Drop Procedure, Table Name = %s', 16, 1, @TableName)
			CLOSE TmpCrs1
			DEALLOCATE TmpCrs1
			RETURN -1
		END 

	END
		
	FETCH NEXT FROM TmpCrs1 INTO @TableName
END
CLOSE TmpCrs1
DEALLOCATE TmpCrs1

SET @TableName = 'DBO.Import_GodownDetail'
SET @DropQuery = 'DROP TABLE ' + @TableName

IF exists (select * from dbo.sysobjects where id = object_id(@TableName) and OBJECTPROPERTY(id, N'IsUserTable') = 1)
BEGIN
	EXECUTE (@DropQuery)
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		RAISERROR('Problem occurred while execution of Import Tables Drop Procedure, Table Name = %s', 16, 1, @TableName)
		RETURN -1
	END 

END

RETURN 0
GO

