Set @Query = 'Select SiteCode, Site=(SELECT Site.Name + SPACE(1) + CHAR(45) + SPACE(1) + InstanceID FROM Site WHERE Site.Sitecode = T.SiteCode), T.IntimationCode, T.IntimationTypeCode, T.Date, T.RefNo, T.Remarks1, T.Remarks2 From ' + @Prefix + 'DB_ExpiryIntimation AS T WHERE T.TargetSiteCode = ' + LTRIM(RTRIM(STR(@SiteCode))) + ' AND T.Pulled = ''N'' AND T.IntimationTypeCode = ' + LTRIM(RTRIM(STR(@IntimationTypeCode)))
Execute (@Query)
Return 1
GO

