-- SP_Generate_Svc_For_StudentServiceTemplate (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_Generate_Svc_For_StudentServiceTemplate
	@Code INT, @UserCode SMALLINT
AS 
--Author: Muhammad Azhar Inayat
--@Code stands for StudentServiceTemplateCode to be processed
DECLARE @errcode INT, @ServiceCode INT, @ServiceInvCode INT, @end_invcode INT, @Rows INT, @DetailRows INT, @NewRowID INT, @SinvCode INT, @EInvCode INT

SET @Rows = ISNULL((SELECT COUNT(StudentServiceTemplateCode)
FROM StudentServiceTemplate 
WHERE StudentServiceTemplateCode = @Code AND Posted='Y' AND SvcInvGenerated='N'), 0)
IF @Rows = 0 OR @Rows IS NULL
BEGIN
	RaisError('Template Already Posted OR used, Please select another one.', 16, 1)
	RETURN -1
END

SET @DetailRows = ISNULL((SELECT COUNT(*) FROM StudentServiceTemplateDetail WHERE StudentServiceTemplateCode = @Code), 0)
IF @DetailRows = 0 OR @DetailRows IS NULL
BEGIN
	RaisError('Template Has no rows for students, Please select another one.', 16, 1)
	RETURN -1
END

SET @ServiceCode = (SELECT ServiceCode FROM StudentServiceTemplate WHERE StudentServiceTemplateCode = @Code AND Posted='Y' AND SvcInvGenerated='N')
IF @ServiceCode = 0 OR @ServiceCode IS NULL
BEGIN
	RaisError('Template Has no Service selected, Please select another one.', 16, 1)
	RETURN -1
END

CREATE TABLE #StudTemp (
	StudentCode INT NOT NULL, 
	ServiceCode INT NOT NULL, 
	Qty NUMERIC(10,2) NOT NULL,  
	TransportRouteCode INT NULL,
	VehicleCode INT NULL,
	Charges NUMERIC(12,2) NOT NULL, 
	DiscPerc NUMERIC(5,2) NOT NULL, 
	ServiceFlatDisc NUMERIC(12,2) NOT NULL, 
	NewRowID INT NOT NULL IDENTITY(1,1),
	RowID INT NOT NULL,
	Remarks VARCHAR(100) NULL,
	ServiceInvCode INT NULL)

INSERT INTO #StudTemp (StudentCode, ServiceCode, Qty, TransportRouteCode, VehicleCode, Charges, DiscPerc, ServiceFlatDisc, Remarks, ServiceInvCode, RowID)
SELECT StudentCode, @ServiceCode, Qty, TransportRouteCode, VehicleCode, Charges, DiscPerc, ServiceFlatDisc, Remarks, ServiceInvCode=NULL, RowID
FROM StudentServiceTemplateDetail 
WHERE StudentServiceTemplateCode = @Code
ORDER BY RowID

SET @DetailRows = ISNULL((SELECT COUNT(*) FROM #StudTemp), 0)
IF @ServiceCode <> 0 AND @DetailRows > 0
BEGIN
	SET @errcode = 0
	EXECUTE @errcode = SP_LockTabMaxkey 'ServiceHeader' , @ServiceInvCode OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Fetching ServiceHeader Key Value', 16, 1)
		RETURN -1
	END

	UPDATE #StudTemp SET ServiceInvCode = @ServiceInvCode + NewRowID

	INSERT INTO ServiceHeader (ServiceInvCode, CustCode, SalesManCode, ServiceCatCode,
		Remarks, OriginalDate, ModifiedBy, Date, 
		PostedBy, PostDate, HeaderNo, DiscPerc, 
		FlatDisc, MiscCharges, SaleInvCode, Posted, ReprintingCounter,
		ServiceOCode, CashReceived, CashTendered, CashCharged, CashBack, 
		StudentCode)
	SELECT
		D.ServiceInvCode, CustCode=S.CustCode, SalesManCode=@UserCode, SerivceCatCode=11,
		Remarks=D.Remarks, OriginalDate=GETDATE(), ModifiedBy=Null, Date=GetDate(),
		PostedBy=@UserCode, PostDate=GETDATE(), HeaderNo=1, DiscPerc=0, 
		FlatDisc=0, MiscCharges=0, SaleInvCode=NULL, Posted='Y', ReprintingCounter=0,
		ServiceOCode=Null, CashReceived=0, CashTendered=0, CashCharged=0, CashBack=0,
		StudentCode=S.StudentCode
	FROM	
		#StudTemp D, Student S
	WHERE
		S.StudentCode = D.StudentCode
	
	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceHeader', 16, 1)
		RETURN -1
	END
	
	INSERT INTO ServiceDetail (ServiceInvCode, ServiceCode, SManCode, Qty, Price, ServiceFlatDisc, DiscPerc, Remarks, TransportRouteCode, VehicleCode)
	SELECT ServiceInvCode, @ServiceCode, SManCode=1, Qty, SalePrice=Charges, ServiceFlatDisc, DiscPerc, Remarks, TransportRouteCode, VehicleCode
	FROM #StudTemp
	
	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceDetail', 16, 1)
		RETURN -1
	END
	
	UPDATE StudentServiceTemplateDetail
	SET ServiceInvCode = T.ServiceInvCode
	FROM #StudTemp T, StudentServiceTemplateDetail D
	WHERE T.RowID = D.RowID
	
	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem in Updating Student Service Template Record', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	SET @SinvCode = ISNULL((SELECT MIN(ServiceInvCode) FROM #StudTemp), 0)
	SET @EInvCode = ISNULL((SELECT MAX(ServiceInvCode) FROM #StudTemp), 0)

	SET @errcode = 0
	EXECUTE @errcode = SP_UpdateTabMaxkey 'ServiceHeader' , @EInvCode
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Updating ServiceHeader Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	UPDATE ServiceHeader 
	SET InvTotal = ISNULL(DBO.fn_GetServiceInvTotal(ServiceInvCode), 0)
	WHERE ServiceInvCode BETWEEN @SinvCode AND @EInvCode
	
	UPDATE ServiceHeader 
	SET OutStandingAmt = InvTotal
	WHERE ServiceInvCode BETWEEN @SinvCode AND @EInvCode

	UPDATE StudentServiceTemplate SET SvcInvGenerated='Y' WHERE StudentServiceTemplateCode = @Code
END
IF @@ERROR = 0 
BEGIN
	RETURN 0
END
ELSE
BEGIN
	RETURN -1
END
GO

-- SP_Generate_Svc_From_AdmPatientRecSvc (last defined by script catalog)
CREATE   PROCEDURE DBO.SP_Generate_Svc_From_AdmPatientRecSvc AS 

DECLARE @tot_admitted_patients INT, @start_invcode INT, @end_invcode INT, @errcode INT
DECLARE @service_table TABLE 
	(AdmissionCode INT NOT NULL, ServiceInvCode INT NULL, Rowid INT IDENTITY(1, 1))

BEGIN TRANSACTION

SET @tot_admitted_patients = 
	ISNULL((SELECT COUNT(PA.AdmissionCode)
			FROM PatientAdmission PA WITH (HOLDLOCK, ROWLOCK), AdmittedPatientRecurringServices APR
			WHERE PA.Discharged1  ='N' AND PA.Discharged  ='N' AND 
				PA.AdmissionCode = APR.AdmissionCode AND
				GETDATE() >= ISNULL(APR.StartDate, '12-12-9999 00:00:00') AND
				GETDATE() >= ISNULL(APR.NextRunOn, '12-12-1900 00:00:00')), 0)

IF @tot_admitted_patients <> 0
BEGIN
	INSERT INTO @service_table (AdmissionCode, ServiceInvCode)
	SELECT PA.AdmissionCode, NULL
	FROM PatientAdmission PA
	WHERE 	PA.Discharged1='N' AND PA.Discharged='N' AND 
		PA.AdmissionCode IN 
			(SELECT DISTINCT AdmittedPatientRecurringServices.AdmissionCode 
			FROM AdmittedPatientRecurringServices
			WHERE GETDATE() >= ISNULL(AdmittedPatientRecurringServices.StartDate, '12-12-9999 00:00:00') AND
				GETDATE() >= ISNULL(AdmittedPatientRecurringServices.NextRunOn, '12-12-1900 00:00:00'))
	ORDER BY PA.AdmissionCode
	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Fetching Admitted Patient Recurring Services', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	SET @errcode = 0
	EXECUTE @errcode = SP_LockTabMaxkey 'ServiceHeader' , @start_invcode OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Fetching ServiceHeader Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	UPDATE @service_table
	SET ServiceInvCode = @start_invcode + RowID
	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in Temporary Table', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	INSERT INTO ServiceHeader (ServiceInvCode, CustCode, SalesManCode, ServiceCatCode,
		Remarks, OriginalDate, ModifiedBy, Date, PostedBy, PostDate, HeaderNo, 
		DiscPerc, FlatDisc, MiscCharges, SaleInvCode, Posted, DoctCode, ReprintingCounter,
		ServiceOCode, CashReceived, PatientCode, AdmissionCode)
	SELECT
		T.ServiceInvCode, CustCode=P.CustCode, SalesManCode=1, SerivceCatCode=11,
		Remarks='Recurring Services', OriginalDate=GETDATE(), ModifiedBy=Null, Date=GetDate(),
		PostedBy=1, PostDate=GETDATE(), HeaderNo=1, DiscPerc=0, FlatDisc=0, MiscCharges=0,
		SaleInvCode=NULL, Posted='Y', DoctCode=PA.DoctorCode, ReprintingCounter=0,
		ServiceOCode=Null, CashReceived=0, PatientCode=Null, PA.AdmissionCode
	FROM	
		PatientAdmission PA, Patient P, (SELECT ServiceInvCode, AdmissionCode FROM @service_table) T
	WHERE
		PA.AdmissionCode = T.AdmissionCode AND PA.PatientCode = P.PatientCode
	ORDER BY T.AdmissionCode

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceHeader', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	INSERT INTO ServiceDetail (ServiceInvCode, ServiceCode, SManCode, Qty, Price, DiscPerc)
	SELECT T.ServiceInvCode, APR.ServiceCode, APR.SManCode, APR.Qty, APR.SalePrice, APR.DiscPerc
	FROM (SELECT ServiceInvCode, AdmissionCode FROM @service_table) T, AdmittedPatientRecurringServices APR
	WHERE T.AdmissionCode = APR.AdmissionCode AND
		GETDATE() >= ISNULL(APR.StartDate, '12-12-9999 00:00:00') AND
		GETDATE() >= ISNULL(APR.NextRunOn, '12-12-1900 00:00:00')
	ORDER BY APR.AdmissionCode, APR.RowID	

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceDetail', 16, 1)
		Rollback Transaction	
		RETURN -1
	END

	UPDATE PatientAdmission 
	SET PatientAdmission.RecurringServicesChargedOn = GETDATE(), 
		PatientAdmission.ServiceInvCode = T.ServiceInvCode
	FROM PatientAdmission, (SELECT ServiceInvCode, AdmissionCode FROM @service_table) T
	WHERE PatientAdmission.AdmissionCode = T.admissioncode			

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem in Updating Patient Admission Record', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	UPDATE AdmittedPatientRecurringServices
	SET NextRunOn = DATEADD(hh, AdmittedPatientRecurringServices.FrequencyHrs, ISNULL(AdmittedPatientRecurringServices.NextRunOn, GETDATE()))
	FROM 
		PatientAdmission PA,
		AdmittedPatientRecurringServices
	WHERE 	PA.Discharged1='N' AND PA.Discharged='N' AND 
		PA.AdmissionCode = AdmittedPatientRecurringServices.AdmissionCode AND
		GETDATE() >= ISNULL(AdmittedPatientRecurringServices.StartDate, '12-12-9999 00:00:00') AND
		GETDATE() >= ISNULL(AdmittedPatientRecurringServices.NextRunOn, '12-12-1900 00:00:00')

	SET @end_invcode = ISNULL((SELECT MAX(ServiceInvCode) FROM @service_table), 0)
	IF @@ERROR <> 0
	BEGIN
		RaisError('Problem in Updating Service Header Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	UPDATE ServiceHeader
	SET InvTotal = ISNULL(DBO.fn_GetServiceInvTotal(ServiceHeader.ServiceInvCode), 0)
	WHERE ServiceHeader.ServiceInvCode IN (SELECT DISTINCT ServiceInvCode FROM @service_table)

	SET @errcode = 0
	EXECUTE @errcode = SP_UpdateTabMaxkey 'ServiceHeader' , @end_invcode
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Updating ServiceHeader Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

END
IF @@ERROR = 0 
BEGIN
	Commit Transaction
	RETURN 0
END
ELSE
BEGIN
	Rollback Transaction
	RETURN -1
END
GO

-- SP_Generate_Svc_From_CheckedInGuest (last defined by script catalog)
CREATE PROCEDURE DBO.SP_Generate_Svc_From_CheckedInGuest 
AS 

DECLARE @tot_checkedin INT, @start_invcode INT, @end_invcode INT, @errcode INT
DECLARE @service_table TABLE 
	(GuestCheckInCode INT NOT NULL, ServiceInvCode INT NULL, Rowid INT IDENTITY(1, 1))

BEGIN TRANSACTION

SET @tot_checkedin = 
	ISNULL((SELECT COUNT(GC.GuestCheckInCode)
			FROM GuestCheckIn GC WITH (HOLDLOCK, ROWLOCK), GuestCheckInService GCS
			WHERE GC.CheckOut ='N' AND 
				GC.GuestCheckInCode = GCS.GuestCheckInCode AND
				DATEDIFF(dd, ISNULL(GC.RecurringServiceChargedOn, 0), GETDATE()) >= 1), 0)

IF @tot_checkedin <> 0
BEGIN
	INSERT INTO @service_table (GuestCheckInCode, ServiceInvCode)
	SELECT GC.GuestCheckInCode, NULL
	FROM GuestCheckIn GC
	WHERE 	GC.CheckOut='N' AND 
			DATEDIFF(dd, ISNULL(GC.RecurringServiceChargedOn, 0), GETDATE()) >= 1 AND
			GC.GuestCheckInCode IN (SELECT DISTINCT GuestCheckInCode FROM GuestCheckInService)
	ORDER BY GC.GuestCheckInCode
	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Fetching Checked-In Guest Recurring Services', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	SET @errcode = 0
	EXECUTE @errcode = SP_LockTabMaxkey 'ServiceHeader' , @start_invcode OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Fetching ServiceHeader Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	UPDATE @service_table
	SET ServiceInvCode = @start_invcode + RowID
	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in Temporary Table', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	INSERT INTO ServiceHeader (ServiceInvCode, CustCode, SalesManCode, ServiceCatCode,
		Remarks, OriginalDate, ModifiedBy, Date, PostedBy, PostDate, HeaderNo, 
		DiscPerc, FlatDisc, MiscCharges, SaleInvCode, Posted, DoctCode, ReprintingCounter,
		ServiceOCode, CashReceived, GuestCode, GuestCheckInCode)
	SELECT
		T.ServiceInvCode, CustCode=G.CustCode, SalesManCode=1, SerivceCatCode=11,
		Remarks='Recurring Services', OriginalDate=GETDATE(), ModifiedBy=Null, Date=GetDate(),
		PostedBy=1, PostDate=GETDATE(), HeaderNo=1, DiscPerc=0, FlatDisc=0, MiscCharges=0,
		SaleInvCode=NULL, Posted='Y', DoctCode=NULL, ReprintingCounter=0,
		ServiceOCode=Null, CashReceived=0, GuestCode=GC.GuestCode, GC.GuestCheckInCode
	FROM	
		GuestCheckIn GC, Guest G, (SELECT ServiceInvCode, GuestCheckInCode FROM @service_table) T
	WHERE
		GC.GuestCheckInCode = T.GuestCheckInCode AND GC.GuestCode = G.GuestCode
	ORDER BY T.GuestCheckInCode

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceHeader', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	INSERT INTO ServiceDetail (ServiceInvCode, ServiceCode, SManCode, Qty, Price, DiscPerc)
	SELECT T.ServiceInvCode, GCS.ServiceCode, GCS.SManCode, GCS.Qty, GCS.SalePrice, GCS.DiscPerc
	FROM (SELECT ServiceInvCode, GuestCheckInCode FROM @service_table) T, GuestCheckInService GCS
	WHERE T.GuestCheckInCode = GCS.GuestCheckInCode
	ORDER BY GCS.GuestCheckInCode, GCS.RowID

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceDetail', 16, 1)
		Rollback Transaction	
		RETURN -1
	END

	UPDATE GuestCheckIn 
	SET GuestCheckIn.RecurringServiceChargedOn = GETDATE(), GuestCheckIn.ServiceInvCode = T.ServiceInvCode
	FROM GuestCheckIn, (SELECT ServiceInvCode, GuestCheckInCode FROM @service_table) T
	WHERE GuestCheckIn.GuestCheckInCode = T.GuestCheckInCode			

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem in Updating Guest Checked-In Record', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	SET @end_invcode = ISNULL((SELECT MAX(ServiceInvCode) FROM @service_table), 0)
	IF @@ERROR <> 0
	BEGIN
		RaisError('Problem in Updating Service Header Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END


	UPDATE ServiceHeader SET InvTotal = dbo.fn_GetServiceInvTotal(T.ServiceInvCode)
	FROM (SELECT ServiceInvCode FROM @service_table) T, ServiceHeader
	WHERE ServiceHeader.ServiceInvCode = T.ServiceInvCode
	IF @@ERROR <> 0
	BEGIN
		RaisError('Problem in Updating Service Invoice Totals', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	SET @errcode = 0
	EXECUTE @errcode = SP_UpdateTabMaxkey 'ServiceHeader' , @end_invcode
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Updating ServiceHeader Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

END
IF @@ERROR = 0 
BEGIN
	Commit Transaction
	RETURN 0
END
ELSE
BEGIN
	Rollback Transaction
	RETURN -1
END
GO

-- SP_Generate_Svc_From_PatientRecSvc (last defined by script catalog)
CREATE PROCEDURE DBO.SP_Generate_Svc_From_PatientRecSvc AS 

DECLARE @tot_patients INT, @start_invcode INT, @end_invcode INT, @errcode INT
DECLARE @service_table TABLE 
	(PatientCode INT NOT NULL, ServiceInvCode INT NULL, Rowid INT IDENTITY(1, 1))

BEGIN TRANSACTION

SET @tot_patients = 
	ISNULL((SELECT COUNT(P.PatientCode)
			FROM Patient P WITH (HOLDLOCK, ROWLOCK), PatientRecServices PR
			WHERE P.AutoGenRecurringServiceInv ='Y' AND 
				P.PatientCode = PR.PatientCode),0)

IF @tot_patients <> 0
BEGIN
	INSERT INTO @service_table (PatientCode, ServiceInvCode)
	SELECT PA.PatientCode, NULL
	FROM Patient PA, PatientRecServices PR
	WHERE 	PA.AutoGenRecurringServiceInv='Y' AND 
			PA.PatientCode = PR.PatientCode
	ORDER BY PA.PatientCode
	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Fetching Patient Recurring Services', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	SET @errcode = 0
	EXECUTE @errcode = SP_LockTabMaxkey 'ServiceHeader' , @start_invcode OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Fetching ServiceHeader Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	UPDATE @service_table
	SET ServiceInvCode = @start_invcode + RowID
	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in Temporary Table', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	INSERT INTO ServiceHeader (ServiceInvCode, CustCode, SalesManCode, ServiceCatCode,
		Remarks, OriginalDate, ModifiedBy, Date, PostedBy, PostDate, HeaderNo, 
		DiscPerc, FlatDisc, MiscCharges, SaleInvCode, Posted, DoctCode, ReprintingCounter,
		ServiceOCode, CashReceived, PatientCode, AdmissionCode)
	SELECT
		T.ServiceInvCode, CustCode=P.CustCode, SalesManCode=1, SerivceCatCode=11,
		Remarks='Recurring Services', OriginalDate=GETDATE(), ModifiedBy=Null, Date=GetDate(),
		PostedBy=1, PostDate=GETDATE(), HeaderNo=1, DiscPerc=0, FlatDisc=0, MiscCharges=0,
		SaleInvCode=NULL, Posted='Y', DoctCode=P.DoctCode, ReprintingCounter=0,
		ServiceOCode=Null, CashReceived=0, PatientCode=P.PatientCode, NULL
	FROM	
		Patient P, (SELECT ServiceInvCode, PatientCode FROM @service_table) T
	WHERE
		P.PatientCode = T.PatientCode
	ORDER BY P.PatientCode

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceHeader', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	INSERT INTO ServiceDetail (ServiceInvCode, ServiceCode, SManCode, Qty, Price, DiscPerc)
	SELECT T.ServiceInvCode, APR.ServiceCode, APR.SManCode, APR.Qty, APR.SalePrice, APR.DiscPerc
	FROM (SELECT ServiceInvCode, PatientCode FROM @service_table) T, PatientRecServices APR
	WHERE T.PatientCode = APR.PatientCode
	ORDER BY APR.PatientCode, APR.RowID	

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceDetail', 16, 1)
		Rollback Transaction	
		RETURN -1
	END

	UPDATE Patient
	SET Patient.RecurringServicesChargedOn = GETDATE(), 
		Patient.ServiceInvCode = T.ServiceInvCode
	FROM Patient, (SELECT ServiceInvCode, PatientCode FROM @service_table) T
	WHERE Patient.PatientCode = T.PatientCode

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem in Updating Patient Record', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	SET @end_invcode = ISNULL((SELECT MAX(ServiceInvCode) FROM @service_table), 0)
	IF @@ERROR <> 0
	BEGIN
		RaisError('Problem in Updating Service Header Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	SET @errcode = 0
	EXECUTE @errcode = SP_UpdateTabMaxkey 'ServiceHeader' , @end_invcode
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Updating ServiceHeader Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

END
IF @@ERROR = 0 
BEGIN
	Commit Transaction
	RETURN 0
END
ELSE
BEGIN
	Rollback Transaction
	RETURN -1
END
GO

-- sp_GenerateAutoSale (last defined by script catalog)
CREATE  Procedure sp_GenerateAutoSale 
	@machinename VarChar(20), 
	@saletemplatecode Int, 
	@usercode Int, 
	@gcode Int, 
	@headerno Int, 
	@startdate DateTime, 
	@enddate DateTime, 
	@max_lineitems Int,  
	@max_lineitems_coushin Int, 
	@max_itemqty Int, 
	@sinvno Int OUTPUT, 
	@einvno Int OUTPUT
AS

Declare @module Int, @custcode Int, @saletypecode SmallInt, @salecatcode Int, @headerinvno Int, @continue Int, @rt_code Int, @Err Int, @totalrows Int, @rowcount Int, @invcounter Int, @counter Int
Declare @SaleInvCode Int, @rand_itemqty Int, @rand_lineitems Int, @rand_item Int, @satisfiableqty Int, @satisfiedqty Int, @item_in_inv_exist Int
Declare @saleprice Numeric(12,2), @rate Numeric(12,2), @discperc Numeric(5,2), @itemflatdisc Numeric(12,2), @unitsalestax Numeric(12,2), @gstperc1 Numeric(6,2), @gstperc2 Numeric(6,2), @hold_avgprice Numeric(15,5)
Declare @icode Int, @anyitem_exist Int, @packunits Int
Declare @totalqty NUMERIC(15, 4), @givenqty NUMERIC(15, 4), @reqqty NUMERIC(15, 4), @batchqty NUMERIC(15, 4), @delqty NUMERIC(15, 4), @currqty NUMERIC(15, 4), @newqty NUMERIC(15, 4), @total_availablestock NUMERIC(15, 4)
Declare @batch VarChar(100), @itemname VarChar(60), @expiry DateTime, @serverdate DateTime
Declare @saleutn BigInt, @firsttime Bit
Declare @saletemplate_rowcount Int, @invdetail_exist Int, @rowgroup Int, @lineitems_rowcount Int, @innercounter Int
Set @firsttime = 0
Set @custcode = 19
Set @salecatcode = 3 
Set @saletypecode = 2
Set @module = ( Select module from module where name = 'Sales' )
Set @serverdate = @enddate

Create Table  #randomitemlist ( lineid Int Not Null, randomvalue Int Not Null )
Create Table #saletemp ( id int not null identity(1,1), icode Int , satisfiableqty Int, satisfiedqty Int, SalePrice  Numeric(12,2), DiscPerc Numeric(8,2), ItemFlatDisc Numeric(12,2), UnitSalesTax Numeric(12,2), GstPerc Numeric(6,2) )
Insert Into #saletemp ( icode, satisfiableqty, satisfiedqty , saleprice, discperc, itemflatdisc, unitsalestax, gstperc )
Select icode, looseqty, 0, saleprice, discperc, itemflatdisc, unitsalestax, gstperc
From SaleTemplateDetail
Where SaleTemplateCode = @saletemplatecode
Order By rowid

Set @saletemplate_rowcount = (Select count(*) from saletemplatedetail where saletemplatecode = @saletemplatecode) + 1
Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp )
Set @continue = 0
Set @invcounter = 1
Set @invdetail_exist = 1
Set @rowgroup = 0

	While @anyitem_exist > 0 And @continue >= 0
	Begin
		IF @invdetail_exist >  0 
			Execute @rt_code = sp_GetTabMaxkey 'Saleledger' , @SaleInvCode Output
		IF ( @firsttime = 0  )
		Begin
			Set @sinvno = @saleinvcode	
			Set @firsttime = 1
		End
		Set @rowgroup = 0
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		Else
		Begin
			IF @invdetail_exist >  0 
				Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno , @module,  @headerinvno Output 
			IF @@Error <> 0 OR @rt_code <>  0
			Begin
				Set @continue  = -1
			End
			Else
			Begin
				Set @Err = 0 
				Set @RowCount = 1
				IF @invdetail_exist >  0 
				Begin
					Insert Into SaleLedger (SaleInvCode, SaleCatCode, CustCode, SPrice, SalesManCode, Date, Discperc, Flatdisc, MiscCharges, SalesTax, Posted, PostDate,  HeaderNo, HeaderInvNo, OriginalDate, InvTotal, MachineName, ModifyCounter, BillingDate, SaleTypeCode)
					Values (@SaleInvCode, @salecatcode, @custcode, 1, @usercode, @serverdate, 0, 0, 0, 0, 'N', @serverdate, @headerno, @headerinvno, @serverdate, 0 , @machinename, 0, @serverdate, @saletypecode)
					Select @Err = @@Error, @RowCount = @@RowCount
				End
				IF @Err <> 0 OR @RowCount = 0 
				Begin 
					RaisError( 'Error occured in inserting record into Sale Ledger : %d' ,16,1,  @SaleInvCode  )
					Set @continue  = -1
				End 
				Else
				Begin
					Set @rand_lineitems = Rand() * @max_lineitems
					IF @rand_lineitems = 0 
						Set @rand_lineitems = 1
					Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp )
					Set @lineitems_rowcount =  @max_lineitems /* + @max_lineitems_coushin */
					Truncate Table #randomitemlist
					Insert Into #randomitemlist
					exec sp_getRandomValueTable @lineitems_rowcount, @saletemplate_rowcount
					Set @innercounter = 1
					While ( @rand_lineitems > 0 )  AND ( @anyitem_exist > 0 ) AND ( @innercounter <= @lineitems_rowcount ) AND ( @continue >= 0 )
					Begin
						Set @rand_item = ( Select randomvalue from #randomitemlist where lineid = @innercounter )
						Select @icode = icode , @satisfiableqty = satisfiableqty, @satisfiedqty = satisfiedqty, @saleprice = saleprice, @discperc = discperc,  @itemflatdisc = itemflatdisc, @unitsalestax = unitsalestax, @gstperc1 = gstperc
						From #saletemp
					        Where id = @rand_item
						Select @RowCount = @@RowCount
						Set @item_in_inv_exist = ( Select count(*) From SaleDetail Where SaleInvCode = @SaleInvCode AND icode = @icode  ) 
						IF  ( @item_in_inv_exist = 0 ) AND ( @RowCount = 1 ) AND  ( (@satisfiableqty - @satisfiedqty) > 0 )
						Begin
								Set @rand_itemqty = Rand() * @max_itemqty
								IF @rand_itemqty = 0 
									Set @rand_itemqty = 1
								IF ( @rand_itemqty + @satisfiedqty ) <=  @satisfiableqty 
									Set @givenqty = @rand_itemqty
								Else
									Set @givenqty = @satisfiableqty - @satisfiedqty
								IF @givenqty <= 0 
									Set @givenqty = 1
								Else
									Update #saletemp Set satisfiedqty = @satisfiedqty + @givenqty Where icode = @icode
								Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
								IF @@Error <> 0 OR @rt_code <> 0
								Begin
									Set @continue  = -1
								End
								Else
								Begin
									set @total_availablestock = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.icode = @icode)
									IF @total_availablestock < 0 OR @total_availablestock IS NULL
										SET @total_availablestock=0
									Set @totalqty = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.gcode = @gcode and godowndetail.icode = @icode  )
									IF @totalqty >= @givenqty 
									Begin 
										Set @rowgroup = @rowgroup + 1
										Select @rate = saleprice, @packunits = packunits
										From ITEM
										Where icode = @icode
										IF @packunits = 0 OR @packunits Is Null 
											Set @packunits = 1
										Set @reqqty = @givenqty
										Declare ItemBatch_Cursor Cursor Static Forward_Only
										For 	Select  batch, expiry, Currqty 
										From    godowndetail 
										Where  godowndetail.gcode = @gcode and
											    godowndetail.icode = @icode 
										Order by priority, expiry, Currqty
		
										Open ItemBatch_Cursor
										Set @totalrows = @@Cursor_Rows
										Fetch Next From ItemBatch_Cursor
										Into 	@batch, @expiry, @currqty
										Set @counter = 1	
										While @@Fetch_Status = 0 And @counter <= @totalrows AND @reqqty > 0
										Begin
											Set @batchqty = @currqty
											IF @batchqty >= @ReqQty 
												Set @delqty = @reqqty
											Else
												Set @delqty = @batchqty
											Set @reqqty = @reqqty - @delqty
	
											Execute @rt_code = sp_maxutn 1, @saleutn Output
											IF @@Error <> 0 OR @rt_code <> 0
											Begin
												Set @continue  = -1															
											End 									
											SET @total_availablestock = @total_availablestock - @delqty
	
											Insert Into SaleDetail (SaleInvCode, icode, gcode, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup)
											Values (@saleinvcode, @icode, @gcode, @batch, @expiry, 0, @delqty, @packunits, @saleprice, @hold_avgprice, @rate / @packunits, @discperc, 0, @itemflatdisc, @rate, @unitsalestax, @gstperc1, @saleutn, @total_availablestock, @rowgroup)
											Select @Err = @@Error, @RowCount = @@RowCount
											IF @Err <> 0 OR @RowCount = 0 
											Begin 
												RaisError( 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %d' ,16,1, @SaleInvCode  )
												Set @continue  = -1
											End 							
											Else
											Begin
												Set @newqty = @currqty - @delqty
												IF @newqty > 0
													Execute @rt_code = sp_SaleUpdateItemStockBatch @gcode, @icode, @batch, @expiry, @newqty , @currqty
												Else
													Execute @rt_code = sp_DeleteItemStockBatch @gcode, @icode, @batch, @expiry, @delqty
												IF @@Error <> 0 OR @rt_code <> 0 
												Begin
													Set @continue  = -1								
												End
											End
											Set @counter = @counter + 1
											Fetch Next From ItemBatch_Cursor
											Into 	@batch, @expiry, @currqty
										End
									Close ItemBatch_Cursor
									Deallocate ItemBatch_Cursor
									End
									Else
									Begin
										Set @itemname = (Select name from item where icode = @icode )	
										RaisError( 'Not enough stock for item (%s) to decrease for Sale Inv. No : %d' , 16 , 1, @itemname, @SaleInvCode  )
										Set @continue  = -1								
									End
								End
						End	
/*
						Else
						Begin 
							Set @rand_lineitems = @rand_lineitems + 1
						End 
*/
						Set @innercounter = @innercounter + 1
						Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp )
						Set @rand_lineitems = @rand_lineitems - 1
					End
					Set @invdetail_exist = ( Select count(*) from saledetail where saleinvcode = @saleinvcode )
				End
			End	
		End
	Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp )
	End

Drop Table #saletemp
Drop Table #randomitemlist

IF ( @continue >= 0 )
Begin
	Set @einvno = @SaleInvCode
	Update Saleledger 
	Set InvTotal = dbo.fn_getSaleInvTotal (Saleledger.saleinvcode)
	Where saleinvcode between @sinvno and @einvno

	Select @Err = @@Error, @Rowcount = @@RowCount
	IF  @Err <> 0 OR @RowCount = 0
	Begin
		RaisError( 'Unable to update SaleInvoices for Sale Inv. total' , 16 , 1 )
		Set @continue  = -1									
	End
	Else
	Begin
		Exec @rt_code = sp_setDateForAutoSaleGen @startdate, @enddate, @sinvno, @einvno
		Select @Err = @@Error
		IF @Err <> 0 OR @rt_code <> 0
		Begin
			RaisError( 'Unable to update SaleInvoices for Date adjustment' , 16 , 1 )
			Set @continue  = -1									
		End
		Else
		Begin
			Insert Into AutoSaleLog (SaleTemplateCode, SSaleInvCode, ESaleInvCode, SDate, EDate )
			Values (@saletemplatecode, @sinvno, @einvno, @startdate, @enddate )
			Select @Err = @@Error, @RowCount = @@RowCount
			IF @Err <> 0 OR @RowCount = 0
			Begin
				RaisError( 'Database error in inserting record in AutoSaleLog' , 16 , 1 )
				Set @continue  = -1									
			End
		End
	End
End

Return @continue
GO

-- sp_GenerateIssue (last defined by script catalog)
CREATE  Procedure [dbo].[sp_GenerateIssue] 
	@ProdCode Int, 
	@UserCode Int, 
	@HeaderNo Int, 
	@serverdate DateTime, 
	@IssueInvCode Int Output 
As

Declare @Code Int, @deptcode Int, @module SmallInt, @utn Int, @HeaderInvNo Int, @category smallint, @IssueCode INT
Declare @IssueType SmallInt, @PriceType SmallInt, @IssueGodownStrategy SMALLINT, @dracccode smallint
Declare @ICode Int, @GCode Int, @packunits Int, @AreaCode Int, @ProdRowID INT, @RowID INT, @GroupCode INT
Declare @GivenQty NUMERIC(15, 4), @TotalQty NUMERIC(15, 4), @CurrQty NUMERIC(15, 4), @DelQty NUMERIC(15, 4), @BatchQty NUMERIC(15, 4), @ReqQty NUMERIC(15, 4), @NewQty NUMERIC(15, 4)
Declare @Price Numeric(12,2), @PurPrice Numeric(12,2), @SalePrice Numeric(12,2), @Hold_AvgPrice Numeric(15,5), @RecentPurPrice Numeric(12,2), @total_availablestock NUMERIC(15, 4)
DECLARE @ItemFlatDisc Numeric(10,2), @DiscPerc Numeric(5,2), @ProcessCharge Numeric(10,2), @ProcessChargePerc Numeric(5,2)
Declare @batch VarChar(100), @ItemName VarChar(100), @AutoPost CHAR(1), @AccountFor CHAR(1)
Declare @Items_Rows Int, @Counter Int, @RowCount Int, @TotalRows Int, @continue Int, @Err Int, @rt_code Int 
Declare @expiry DateTime

/*
Author: M.Usman
Purpose:This Stored Procedure takes an argument of Production Code (@ProdCode)
	and against that Production Code it generates Issue Invoice Auto Posted.
*/
Set @continue = 0
Set @DeptCode = ISNULL((SELECT IssueDeptCode FROM ProdHeader WHERE ProdCode = @ProdCode), 1)
Set @AreaCode = 1 /* Default Selection */
Set @module = ( Select Module From Module Where Lower(Name) = 'issue' ) 
Set @pricetype = DBO.Fn_Get_INT_Preference('IssuePriceTypeCode')
SET @GroupCode = ISNULL((SELECT MIN(GroupCode) FROM UserGroups WHERE UserCode=@UserCode), 1)
SET @Category = 2 -- Production
SET @AccountFor = ISNULL((SELECT AccountFor FROM IssueCategory WHERE IssueCategoryCode=@Category), 'N')
IF @AccountFor = 'Y'
	SET @dracccode = ISNULL((SELECT Code FROM Global WHERE Name='GT_WIPAcc'), 33) -- cr wor in process a/c
ELSE
	SET @dracccode = NULL

SET @AutoPost = DBO.Fn_GetPreference('AutoPostIssueOnProdPost')
IF @AutoPost IS NULL
	SET @AutoPost = 'Y'

IF @GroupCode > 0 
	SET @IssueGodownStrategy = ISNULL((SELECT IssueGodownStrategy FROM Groups WHERE GroupCode=@GroupCode), 1)
ELSE
	SET @IssueGodownStrategy = 1

IF @IssueGodownStrategy = 1
	Set @GCode = ( Select IssueGCode From ProdHeader Where ProdCode = @ProdCode )

	Declare Cursor_Items Cursor Forward_Only Static
	For	Select			
			RD.ICode, 
			Sum(RD.Qty) As Qty, 
			Max(I.PackUnits) As PackUnits ,
			Round(Max(I.PurPrice)/Max(I.PackUnits) , 2) As PurPrice ,
			Round(Max(I.SalePrice)/Max(I.PackUnits) , 2) As SalePrice ,
			Round(Max(I.RecentPurPrice)/Max(I.PackUnits) , 2) As RecentPurPrice ,
			/*CASE @PriceType 
				WHEN 1 THEN Round(Max(I.SalePrice)/Max(I.PackUnits) , 2) 
				WHEN 2 THEN Round(Max(I.SalePrice2)/Max(I.PackUnits) , 2) 
				WHEN 3 THEN Round(Max(I.SalePrice3)/Max(I.PackUnits) , 2) 
				WHEN 4 THEN Round(Max(I.PurPrice)/Max(I.PackUnits) , 2) 
				WHEN 5 THEN Round(Max(I.RecentPurPrice)/Max(I.PackUnits) , 2) 
				WHEN 6 THEN Round(Max(I.AvgPrice), 2) 
				WHEN 7 THEN Round(Max(I.SalePrice4)/Max(I.PackUnits) , 2) 
				WHEN 8 THEN Round(Max(I.SalePrice5)/Max(I.PackUnits) , 2) END*/ RD.Price As Price,
			RD.ItemFlatDisc, RD.DiscPerc, RD.ProcessCharge, RD.ProcessChargePerc, RD.ProdRowID, RD.RowID
		From  	
			(
			Select ICode, Qty, RowID
			From   ProdDetail
			Where  ProdDetail.ProdCode = @ProdCode
			) PD,
			(SELECT R1.*
			FROM Recipe R1
			WHERE STR(R1.ResultedItem, 7) + STR(R1.Priority, 7) IN
				(SELECT DISTINCT STR(RR.ResultedItem,7) + STR(MIN(RR.Priority), 7)
				FROM Recipe RR 
				WHERE RR.ResultedItem IN 
					(SELECT DISTINCT D.ICode 
					FROM ProdHeader P, ProdDetail D
					WHERE P.ProdCode = @ProdCode AND 
						P.ProdCode = D.ProdCode)
				GROUP BY RR.ResultedItem)) R,
			ProdBuffer RD,
			Item I
		Where   PD.ICode = R.ResultedItem AND
			RD.ProdCode = @ProdCode AND
			PD.RowID = RD.ProdRowID AND
			RD.ICode = I.ICode			
		Group By RD.ProdRowID, RD.ICode, RD.Price, RD.RowID, RD.ItemFlatDisc, RD.DiscPerc, RD.ProcessCharge, RD.ProcessChargePerc
		Order By RD.RowID

	Open Cursor_Items
	Set @Items_Rows = @@Cursor_Rows
	IF @Items_Rows > 0 
	Begin
		Execute @rt_code = sp_GetTabMaxkey 'IssueHeader' , @Code Output
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		Else
		Begin
			Set @IssueInvCode = @Code
			Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno , @module,  @headerinvno Output 
			IF @@Error <> 0 OR @rt_code <>  0
			Begin
				Set @continue  = -1
			End
			Else
			Begin
				Set @IssueCode = NULL
				Execute @rt_code = sp_GetIssueCategoryCounter @Category , @IssueCode Output 
				IF @@Error <> 0 OR @rt_code <>  0
				Begin
					Set @continue  = -1
				End
				Else
				Begin
					Insert Into IssueHeader (IssueInvCode, DeptCode, Date, OriginalDate, SalesManCode, Posted, PostDate, PostedBy, AreaCode, HeaderNo, HeaderInvNo, PriceTypeCode, Remarks, IssueCategoryCode, AccountFor, DrAccCode, IssueCode)
					Values (@Code, @deptcode, @serverdate, @serverdate, @usercode, @AutoPost, @serverdate, @usercode, @AreaCode, @headerno, @headerinvno, @pricetype, 'SYSTEM GENERATED ISSUE', @Category, @AccountFor, @DrAccCode, @IssueCode)
					Select @Err = @@Error, @RowCount = @@RowCount
					IF @Err <> 0 OR @RowCount = 0 
					Begin 
						RaisError( 'Error occured in inserting record into Issue Header : %d' ,16,1,  @Code  )
						Set @continue  = -1
					End 
					Else
					Begin
						Fetch Next From Cursor_Items
						Into @icode, @givenqty, @packunits, @purprice, @saleprice, @recentpurprice, @price, @ItemFlatDisc, @DiscPerc, @ProcessCharge, @ProcessChargePerc, @ProdRowID, @RowID
						While @@Fetch_Status = 0 AND @continue >= 0
						Begin
							IF @IssueGodownStrategy = 2
								SET @Gcode = ISNULL((SELECT GCode FROM Item WHERE ICode=@icode), 1)
	
							SET @Price = ((@Price - @ItemFlatDisc) * (1 - @DiscPerc * 0.01)) + @ProcessCharge + ((@Price - @ItemFlatDisc) * (1 - @DiscPerc * 0.01) * @ProcessChargePerc * 0.01)
							Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
							IF @@Error <> 0 OR @rt_code <> 0
							Begin
								Set @continue  = -1
							End
							Else
							Begin
								Set @packunits = Case When @packunits Is Null Then 1 When @packunits = 0 Then 1 Else @packunits End
								Set @totalqty = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.gcode = @gcode and godowndetail.icode = @icode  )
								IF @totalqty >= @givenqty 
								Begin 
									set @total_availablestock = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.icode = @icode)
									IF @total_availablestock < 0 OR @total_availablestock IS NULL
										SET @total_availablestock=0

									Set @reqqty = @givenqty
									Declare ItemBatch_Cursor Cursor Static Forward_Only
									For 	Select  batch, expiry, Currqty 
										From    godowndetail 
										Where  	godowndetail.gcode = @gcode and
											godowndetail.icode = @icode 
										Order by priority, expiry, Currqty
		
									Open ItemBatch_Cursor
									Set @totalrows = @@Cursor_Rows
									Fetch Next From ItemBatch_Cursor
									Into 	@batch, @expiry, @currqty
									Set @counter = 1	
									While @@Fetch_Status = 0 And @counter <= @totalrows AND @reqqty > 0
									Begin
										Set @batchqty = @currqty
										IF @batchqty >= @ReqQty 
											Set @delqty = @reqqty
										Else
											Set @delqty = @batchqty
										Set @reqqty = @reqqty - @delqty
	
										Execute @rt_code = sp_maxutn 1, @utn Output
										IF @@Error <> 0 OR @rt_code <> 0
										Begin
											Set @continue  = -1															
										End 									
										SET @total_availablestock = @total_availablestock - @delqty
										
										Insert Into IssueDetail (IssueInvCode, GCode, ICode, Batch, Expiry, Qty, SalePrice, PurchasePrice, AvgPrice, PackUnits, MRPP, IssueUtn, Price , BalanceStock)
										Values(@Code, @GCode, @ICode, @batch, @expiry, @delqty, @saleprice, @purprice, @hold_avgprice, @packunits, @recentpurprice, @utn, @price , @total_availablestock)
										Select @Err = @@Error, @RowCount = @@RowCount
										IF @Err <> 0 OR @RowCount = 0 
										Begin 
											RaisError( 'Error occured in inserting record into Issue Detail for Production : %d' ,16,1, @Code  )
											Set @continue  = -1
										End 							
										Else
										Begin
											Set @newqty = @currqty - @delqty
											IF @newqty > 0
												Execute @rt_code = sp_SaleUpdateItemStockBatch @gcode, @icode, @batch, @expiry, @newqty , @currqty
											Else
												Execute @rt_code = sp_DeleteItemStockBatch @gcode, @icode, @batch, @expiry, @delqty
											IF @@Error <> 0 OR @rt_code <> 0 
											Begin
												Set @continue  = -1								
											End
										End
										Set @counter = @counter + 1
										Fetch Next From ItemBatch_Cursor
										Into 	@batch, @expiry, @currqty
									End
									Close ItemBatch_Cursor
									Deallocate ItemBatch_Cursor
								End
								Else
								Begin
									Set @itemname = (Select name from item where icode = @icode )	
									RaisError( 'Not enough stock for item (%s) to decrease for Issue No. : %d' , 16 , 1, @itemname, @Code  )
									Set @continue  = -1								
								End
							End
							Fetch Next From Cursor_Items
							Into @icode, @givenqty , @packunits, @purprice, @saleprice, @recentpurprice, @price, @ItemFlatDisc, @DiscPerc, @ProcessCharge, @ProcessChargePerc, @ProdRowID, @RowID
						End
					End
				End
			End
		End	
	End

Close Cursor_Items
Deallocate Cursor_Items

IF @continue <> 0 
Begin
	Return -1
End
Else
Begin 
	Return 0
End
GO

-- sp_GenerateIssue_On_ProdunctionNote (last defined by script catalog)
CREATE    PROCEDURE sp_GenerateIssue_On_ProdunctionNote
	@ProdNoteCode Int, 
	@UserCode Int, 
	@IssueInvCode Int Output 
As

Declare @Code Int, @deptcode Int, @module SmallInt, @utn Int, @HeaderInvNo Int, @category smallint, @IssueCode INT, @dracccode smallint, @AccountFor CHAR(1)
Declare @IssueType SmallInt, @PriceType SmallInt, @HeaderNo SmallInt
Declare @ICode Int, @GCode Int, @packunits Int, @AreaCode Int, @ProdRowID INT, @RowID INT, @TotalPieces INT, @PiecesInHand INT
Declare @GivenQty NUMERIC(15, 4), @TotalQty NUMERIC(15, 4), @CurrQty NUMERIC(15, 4), @DelQty NUMERIC(15, 4), @BatchQty NUMERIC(15, 4), @ReqQty NUMERIC(15, 4), @NewQty NUMERIC(15, 4), @total_availablestock NUMERIC(15, 4)
Declare @Price Numeric(12,2), @PurPrice Numeric(12,2), @SalePrice Numeric(12,2), @Hold_AvgPrice Numeric(15,5), @RecentPurPrice Numeric(12,2)
DECLARE @ItemFlatDisc Numeric(10,2), @DiscPerc Numeric(5,2), @ProcessCharge Numeric(10,2), @ProcessChargePerc Numeric(5,2)
Declare @batch VarChar(100), @ItemName VarChar(100), @errtext VARCHAR(4000)
Declare @Items_Rows Int, @Counter Int, @RowCount Int, @TotalRows Int, @continue Int, @Err Int, @rt_code Int 
Declare @expiry DateTime, @serverdate DateTime

/*
Author: M. Azhar Inayat
Purpose:This Stored Procedure takes an argument of Production Note Code (@ProdNoteCode)
and against that Production Note, it generates Issue Invoice Auto Posted.
*/
Set @continue = 0
Set @DeptCode = ISNULL((SELECT IssueDeptCode FROM ProdNote WHERE ProdNoteCode=@ProdNoteCode), 1)
Set @HeaderNo = 1
Set @AreaCode = 1 /* Default Selection */
Set @module = ( Select Module From Module Where Lower(Name) = 'issue' ) 
Set @pricetype = DBO.Fn_Get_INT_Preference('IssuePriceTypeCode')
Set @serverdate = GETDATE()
SET @Category = 2 -- Production
SET @AccountFor = ISNULL((SELECT AccountFor FROM IssueCategory WHERE IssueCategoryCode=@Category), 'N')
IF @AccountFor = 'Y'
	SET @dracccode = ISNULL((SELECT Code FROM Global WHERE Name='GT_WIPAcc'), 33) -- cr wor in process a/c
ELSE
	SET @dracccode = NULL

Declare Cursor_Items Cursor Forward_Only Static
For	Select			
		PNI.ICode, 
		PNI.GCode, 
		Sum(PNI.Qty) As Qty, 
		SUM(PNI.TotalPieces) AS TotalPieces,
		PNI.PackUnits,
		Round(Max(I.PurPrice)/Max(I.PackUnits) , 2) As PurPrice ,
		Round(Max(I.SalePrice)/Max(I.PackUnits) , 2) As SalePrice ,
		Round(Max(I.RecentPurPrice)/Max(I.PackUnits) , 2) As RecentPurPrice ,
		CASE @PriceType 
			WHEN 1 THEN Round(Max(I.SalePrice)/Max(I.PackUnits) , 2) 
			WHEN 2 THEN Round(Max(I.SalePrice2)/Max(I.PackUnits) , 2) 
			WHEN 3 THEN Round(Max(I.SalePrice3)/Max(I.PackUnits) , 2) 
			WHEN 4 THEN Round(Max(I.PurPrice)/Max(I.PackUnits) , 2) 
			WHEN 5 THEN Round(Max(I.RecentPurPrice)/Max(I.PackUnits) , 2) 
			WHEN 6 THEN Round(Max(I.AvgPrice), 2) 
			WHEN 7 THEN Round(Max(I.SalePrice4)/Max(I.PackUnits) , 2) 
			WHEN 8 THEN Round(Max(I.SalePrice5)/Max(I.PackUnits) , 2) END As Price,
		PNI.RowID
	From  	
		ProdNoteIssue PNI,
		Item I
	Where   PNI.ProdNoteCode = @ProdNoteCode AND
		PNI.ICode = I.ICode			
	Group By PNI.RowID, PNI.ICode, PNI.GCode, PNI.PackUnits
	Order By PNI.RowID

Open Cursor_Items
Set @Items_Rows = @@Cursor_Rows
IF @Items_Rows > 0 
Begin
	Execute @rt_code = sp_GetTabMaxkey 'IssueHeader' , @Code Output
	IF @@Error <> 0 OR @rt_code <>  0
	Begin
		Set @continue  = -1
	End
	Else
	Begin
		Set @IssueInvCode = @Code
		Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno , @module,  @headerinvno Output 
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		Else
		Begin
			Set @IssueCode = NULL
			Execute @rt_code = sp_GetIssueCategoryCounter @Category , @IssueCode Output 
			IF @@Error <> 0 OR @rt_code <>  0
			Begin
				Set @continue  = -1
			End
			Else
			Begin
				Insert Into IssueHeader (IssueInvCode, DeptCode, Date, OriginalDate, SalesManCode, Posted, PostDate, PostedBy, AreaCode, HeaderNo, HeaderInvNo, PriceTypeCode, Remarks, RecipientCode, IssueCategoryCode, AccountFor, DrAccCode, IssueCode)
				Values (@Code, @deptcode, @serverdate, @serverdate, @usercode, 'Y', @serverdate, @usercode, @AreaCode, @headerno, @headerinvno, @pricetype, 'PRODUCTION NOTE BASED ISSUE', 1, @Category, @AccountFor, @DrAccCode, @IssueCode)
				Select @Err = @@Error, @RowCount = @@RowCount
				IF @Err <> 0 OR @RowCount = 0 
				Begin 
					RaisError( 'Error occured in inserting record into Issue Header : %d' ,16,1,  @Code  )
					Set @continue  = -1
				End 
				Else
				Begin
					Fetch Next From Cursor_Items
					Into @icode, @gcode, @givenqty, @totalpieces, @packunits, @purprice, @saleprice, @recentpurprice, @price, @RowID
					While @@Fetch_Status = 0 AND @continue >= 0
					Begin
						Set @itemname = (Select name from item where icode = @icode )
	--					SET @Price = ((@Price - @ItemFlatDisc) * (1 - @DiscPerc * 0.01)) + @ProcessCharge + ((@Price - @ItemFlatDisc) * (1 - @DiscPerc * 0.01) * @ProcessChargePerc * 0.01)
						Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
						IF @@Error <> 0 OR @rt_code <> 0
						Begin
							SET @errtext = 'Unable to aquire item lock for item = ' + @itemname
							Set @continue  = -1								
						End
	 					ELSE
	 					BEGIN
	 						Execute @rt_code = SP_GetItemTotalPiecesInHand @icode, @piecesinhand OutPut
	 						IF @@Error <> 0 OR @rt_code <> 0
	 						Begin
	 							SET @errtext = 'Unable to fetch total pieces in hand for item = ' + @itemname
	 							Set @continue  = -1
	 						End
	 						Else
	 						BEGIN
	 							IF @totalpieces > @piecesinhand
	 							BEGIN
	 								SET @errtext = 'Total Pieces asked to issue are more than total pieces in hand for item = ' + @itemname
	 								Set @continue  = -1
	 							END
	 							ELSE
	 							BEGIN
	 								Execute @rt_code = SP_UpdateItemTotalPiecesInHand @icode, -1, @totalpieces
	 								IF @@Error <> 0 OR @rt_code <> 0
	 								Begin
	 									SET @errtext = 'Error Updating pieces in hand for item = ' + @itemname
	 									Set @continue  = -1
	 								End
	 							END
	 						END
	 					END
	 					IF @continue >= 0
	 					BEGIN
							set @total_availablestock = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.icode = @icode)
							IF @total_availablestock < 0 OR @total_availablestock IS NULL
								SET @total_availablestock=0

							Set @packunits = Case When @packunits Is Null Then 1 When @packunits = 0 Then 1 Else @packunits End
							Set @totalqty = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.gcode = @gcode and godowndetail.icode = @icode  )
							IF @totalqty >= @givenqty 
							Begin 
								Set @reqqty = @givenqty
								Declare ItemBatch_Cursor Cursor Static Forward_Only
								For 	Select  batch, expiry, Currqty 
									From    godowndetail 
									Where  	godowndetail.gcode = @gcode and
										godowndetail.icode = @icode 
									Order by priority, expiry, Currqty
	
								Open ItemBatch_Cursor
								Set @totalrows = @@Cursor_Rows
								Fetch Next From ItemBatch_Cursor
								Into 	@batch, @expiry, @currqty
								Set @counter = 1	
								While @@Fetch_Status = 0 And @counter <= @totalrows AND @reqqty > 0
								Begin
									Set @batchqty = @currqty
									IF @batchqty >= @ReqQty 
										Set @delqty = @reqqty
									Else
										Set @delqty = @batchqty
									Set @reqqty = @reqqty - @delqty
	
									Execute @rt_code = sp_maxutn 1, @utn Output
									IF @@Error <> 0 OR @rt_code <> 0
									Begin
										Set @continue  = -1															
									End 									
									SET @total_availablestock = @total_availablestock - @delqty
									
									Insert Into IssueDetail (IssueInvCode, GCode, ICode, Batch, Expiry, Qty, SalePrice, PurchasePrice, AvgPrice, PackUnits, MRPP, IssueUtn, Price, TotalPieces, PiecesInHand , BalanceStock)
									Values(@Code, @GCode, @ICode, @batch, @expiry, @delqty, @saleprice, @purprice, @hold_avgprice, @packunits, @recentpurprice, @utn, @price , @TotalPieces, @PiecesInHand  , @total_availablestock)
									Select @Err = @@Error, @RowCount = @@RowCount
									IF @Err <> 0 OR @RowCount = 0 
									Begin 
										RaisError( 'Error occured in inserting record into Issue Detail for Production : %d' ,16,1, @Code  )
										Set @continue  = -1
									End 							
									Else
									Begin
										Set @newqty = @currqty - @delqty
										IF @newqty > 0
											Execute @rt_code = sp_SaleUpdateItemStockBatch @gcode, @icode, @batch, @expiry, @newqty , @currqty
										Else
											Execute @rt_code = sp_DeleteItemStockBatch @gcode, @icode, @batch, @expiry, @delqty
										IF @@Error <> 0 OR @rt_code <> 0 
										Begin
											Set @continue  = -1								
										End
									End
									Set @counter = @counter + 1
									Fetch Next From ItemBatch_Cursor
									Into 	@batch, @expiry, @currqty
								End
								Close ItemBatch_Cursor
								Deallocate ItemBatch_Cursor
							End
							Else
							Begin
								Set @itemname = (Select name from item where icode = @icode )	
								RaisError( 'Not enough stock for item (%s) to decrease for Issue No. : %d' , 16 , 1, @itemname, @Code  )
								Set @continue  = -1								
							End
						End
						ELSE
						BEGIN
							RaisError(@errtext, 16 , 1)
							Set @continue  = -1								
						END
						Fetch Next From Cursor_Items
						Into @icode, @gcode, @givenqty, @totalpieces, @packunits, @purprice, @saleprice, @recentpurprice, @price, @RowID
					End
				End
			End
		End
	End	
End

Close Cursor_Items
Deallocate Cursor_Items

IF @continue <> 0 
Begin
	Return -1
End
Else
Begin 
	Return 0
End
GO

-- sp_GenerateItemLog_DataCarryDB (last defined by script catalog)
Create  Procedure sp_GenerateItemLog_DataCarryDB @SRV VARCHAR(50), @DB VARCHAR(50), @OWNER VARCHAR(20) AS
/*
Author: Muhammad Usman
Version:1.0
*/
SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON
Declare @query VarChar(2000)
Set @query = 'Insert Into ItemLog '
Set @query = @query + ' Select 	GetDate(), i.saleprice, (SELECT isnull(sum(g.currqty),0) FROM godowndetail g WHERE g.icode=item.icode), item.* '
Set @query = @query + ' from   	item , ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'item i '
Set @query = @query + ' where  	item.icode = i.icode AND item.saleprice <> i.saleprice '
Execute(@query)
IF @@Error <> 0
Begin
	RaisError('Some Problem occur in generating ItemLog',16,1)
	Return -1
End
Return 1
GO

-- sp_GenerateMarkedSaleFromTemplate (last defined by script catalog)
CREATE     Procedure sp_GenerateMarkedSaleFromTemplate
	@saletemplatecode Int, 
	@usercode Int, 
	@MachineName VARCHAR(100),
	@sinvno Int OUTPUT, 
	@einvno Int OUTPUT
AS
SET NOCOUNT ON

Declare @module Int, @custcode Int, @saletypecode SmallInt, @headerno SmallInt, @headerinvno Int, @continue Int, @rt_code Int, @Err Int, @totalrows Int, @rowcount Int, @invcounter Int, @counter Int, @OutofStock INT, @RowID INT, @gcode smallint, @SaleCatCode TINYINT
Declare @InvCode INT, @SaleInvCode Int, @OldInvCode INT, @satisfiableqty Int, @satisfiedqty Int, @item_in_inv_exist Int
Declare @saleprice Numeric(12,2), @rate Numeric(12,2), @discperc Numeric(5,2), @itemflatdisc Numeric(12,2), @unitsalestax Numeric(12,2), @gstperc1 Numeric(6,2), @gstperc2 Numeric(6,2), @hold_avgprice Numeric(15,5)
Declare @icode Int, @anyitem_exist Int, @packunits Int
Declare @Quantity NUMERIC(15, 4), @BonusQty NUMERIC(15, 4), @totalqty NUMERIC(15, 4), @givenqty NUMERIC(15, 4), @reqqty NUMERIC(15, 4), @batchqty NUMERIC(15, 4), @delqty NUMERIC(15, 4), @currqty NUMERIC(15, 4), @newqty NUMERIC(15, 4), @total_availablestock NUMERIC(15, 4)
Declare @batch VarChar(100), @itemname VarChar(60), @expiry DateTime, @serverdate DateTime, @Remarks VARCHAR(100)
Declare @saleutn BigInt, @firsttime Bit
Declare @saletemplate_rowcount Int, @invdetail_exist Int, @rowgroup Int, @lineitems_rowcount Int, @innercounter Int

SET @OutofStock = 
	ISNULL((SELECT COUNT(T.ICode)
	FROM
		(SELECT ICode, Qty=SUM(ISNULL(LooseQty,0) + ISNULL(BonusQty,0)), Stock = ISNULL((SELECT SUM(GD.CurrQty) FROM GodownDetail GD WHERE GD.ICode = SaleTemplateDetail.ICode), 0)
		FROM SaleTemplateDetail 
		WHERE SaleTemplateCode = @saletemplatecode AND Marked='Y' AND (LooseQty + BonusQty) > 0
		GROUP BY ICode) T
	WHERE
		T.Qty > T.Stock), 0)

IF @OutofStock > 0
BEGIN
	RaisError( 'Not Enough Stock exists for some items of sale template no. %d' ,16,1, @saletemplatecode)
	RETURN -1
END

CREATE TABLE #SaleTemp 
(SaleInvCode INT, SaleCatCode TINYINT, OldInvCode INT, SaleDate DATETIME, CustCode SMALLINT, ICode INT, LooseQty NUMERIC(15,4), BonusQty NUMERIC(15,4), SalePrice NUMERIC(15,2), DiscPerc NUMERIC(5,2), ItemFlatDisc NUMERIC(10,2), 
UnitSalesTax NUMERIC(15,2), GSTPerc NUMERIC(5,2), PackUnits INT, Remarks VARCHAR(100), 
SatisfiableQty NUMERIC(15,4), SatisfiedQty NUMERIC(15,4), RowID INT IDENTITY(1,1))

INSERT INTO #SaleTemp (SaleInvCode, SaleCatCode, OldInvCode, SaleDate, CustCode, ICode, LooseQty, BonusQty, SalePrice, DiscPerc, ItemFlatDisc, UnitSalesTax, GSTPerc, PackUnits, Remarks, SatisfiableQty, SatisfiedQty)
SELECT SaleInvCode=-1, ISNULL(SaleCatCode, 3), OldInvCode=SaleInvCode, SaleDate, CustCode, ICode, LooseQty, BonusQty, SalePrice, DiscPerc, ItemFlatDisc, UnitSalesTax, GSTPerc, PackUnits, Remarks, SatisfiableQty = LooseQty + BonusQty, SatisfiedQty=0
FROM SaleTemplateDetail 
WHERE SaleTemplateCode = @saletemplatecode AND Marked='Y' AND (LooseQty + BonusQty) > 0
ORDER BY SaleInvCode, RowID

Set @saletypecode = 1
Set @module = ( Select module from module where name = 'Sales' )
SET @Headerno=1
Set @saletemplate_rowcount = ISNULL((SELECT COUNT(*) FROM #SaleTemp), 0)
Set @anyitem_exist  = ISNULL(( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp ), 0)
Set @continue = 0
Set @invcounter = 1
Set @rowgroup = 0
SET @RowID=1

While @anyitem_exist > 0 And @continue >= 0
Begin
	SET @CustCode = ISNULL((SELECT CustCode FROM #SaleTemp WHERE RowID = @RowID), 19)
	SET @ServerDate = ISNULL((SELECT SaleDate FROM #SaleTemp WHERE RowID = @RowID), GETDATE())
	SET @OldInvCode = (SELECT OldInvCode FROM #SaleTemp WHERE RowID = @RowID)
	SET @InvCode = (SELECT SaleInvCode FROM #SaleTemp WHERE RowID = @RowID)
	SET @SaleInvCode = ISNULL((SELECT MAX(SaleInvCode) FROM #SaleTemp WHERE OldInvCode = @OldInvCode), -1)
	SET @SaleCatCode = ISNULL((SELECT SaleCatCode FROM #SaleTemp WHERE RowID = @RowID), 3)
	SET @Remarks = ISNULL((SELECT Remarks FROM #SaleTemp WHERE RowID = @RowID), '')
	Set @rowgroup = 0
	IF @InvCode = -1 AND @SaleInvCode = -1
	BEGIN
		Execute @rt_code = sp_GetTabMaxkey 'Saleledger' , @SaleInvCode Output
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		IF @continue >= 0
		BEGIN
			Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno , @module,  @headerinvno Output 
			IF @@Error <> 0 OR @rt_code <>  0
			Begin
				Set @continue  = -1
			End
		END
		IF @continue >= 0
		BEGIN
			Insert Into SaleLedger (SaleInvCode, SaleCatCode, CustCode, SPrice, SalesManCode, Date, Discperc, Flatdisc, MiscCharges, SalesTax, Posted, PostDate,  HeaderNo, HeaderInvNo, OriginalDate, InvTotal, MachineName, ModifyCounter, BillingDate, SaleTypeCode, Remarks, CustRefNo)
			Values (@SaleInvCode, @SaleCatCode, @custcode, 1, @usercode, @serverdate, 0, 0, 0, 0, 'N', @serverdate, @headerno, @headerinvno, @serverdate, 0 , @MachineName, 0, @serverdate, @saletypecode, @Remarks, @OldInvCode)
			Select @Err = @@Error, @RowCount = @@RowCount
			IF @Err <> 0 OR @RowCount = 0 
			Begin 
				RaisError( 'Error occured in inserting record into Sale Ledger : %d' ,16,1,  @SaleInvCode)
				Set @continue  = -1
			End 
		END
	END
	
	IF @continue >= 0
	Begin
		Set @anyitem_exist  = ISNULL(( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp ), 0)
		IF @OldInvCode > 0
			Set @lineitems_rowcount = ISNULL((SELECT COUNT(*) from #saletemp WHERE OldInvCode = @OldInvCode AND SatisfiableQty - SatisfiedQty > 0), 1)
		ELSE
			Set @lineitems_rowcount = ISNULL((SELECT COUNT(*) from #saletemp WHERE OldInvCode IS NULL AND SatisfiableQty - SatisfiedQty > 0), 1)
		Set @innercounter = 1
		While ( @anyitem_exist > 0 ) AND ( @innercounter <= @lineitems_rowcount ) AND ( @continue >= 0 )
		Begin
			Select @icode = icode , @Quantity=LooseQty, @BonusQty=BonusQty, @satisfiableqty = satisfiableqty, @satisfiedqty = satisfiedqty, @saleprice = saleprice, @discperc = discperc,  @itemflatdisc = itemflatdisc, @unitsalestax = unitsalestax, @gstperc1 = gstperc
			From #saletemp
		        Where RowID = @RowID
			Select @RowCount = @@RowCount
			IF (@RowCount > 0) AND ( (@satisfiableqty - @satisfiedqty) > 0 )
			Begin
				IF ( @Quantity + @BonusQty + @satisfiedqty ) <= @satisfiableqty 
					Set @givenqty = @Quantity + @BonusQty
				Else
					Set @givenqty = @satisfiableqty - @satisfiedqty

				IF @givenqty <= 0 
					Set @givenqty = 1
				Else
					Update #saletemp Set satisfiedqty = @satisfiedqty + @givenqty Where icode = @icode AND RowID=@RowID

				Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
				IF @@Error <> 0 OR @rt_code <> 0
				Begin
					Set @continue  = -1
				End
				Else
				Begin
					set @total_availablestock = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.icode = @icode)
					IF @total_availablestock < 0 OR @total_availablestock IS NULL
						SET @total_availablestock=0
					Set @totalqty = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.icode = @icode)
					IF @totalqty >= @givenqty 
					Begin 
						Set @rowgroup = @rowgroup + 1
						Select @rate = saleprice, @packunits = packunits
						From ITEM
						Where icode = @icode
						IF @packunits = 0 OR @packunits Is Null 
							Set @packunits = 1
						Set @reqqty = @givenqty
						Declare ItemBatch_Cursor Cursor Static Forward_Only
						For 	Select  gcode, batch, expiry, Currqty 
						From    godowndetail 
						Where   godowndetail.icode = @icode 
						Order by gcode, priority, expiry, Currqty

						Open ItemBatch_Cursor
						Set @totalrows = @@Cursor_Rows
						Fetch Next From ItemBatch_Cursor
						Into 	@gcode, @batch, @expiry, @currqty
						Set @counter = 1	
						While @@Fetch_Status = 0 And @counter <= @totalrows AND @reqqty > 0
						Begin
							Set @batchqty = @currqty
							IF @batchqty >= @ReqQty 
								Set @delqty = @reqqty
							Else
								Set @delqty = @batchqty
							Set @reqqty = @reqqty - @delqty
							IF @delqty >= @Quantity
							BEGIN
								SET @Quantity = @Quantity
								SET @BonusQty = @delqty - @Quantity
								IF @BonusQty < 0
									SET @BonusQty = 0
							END
							ELSE
							BEGIN
								SET @Quantity = @Quantity - @delqty
								IF @Quantity < 0
									SET @Quantity = 0
								SET @BonusQty = 0
							END

							Execute @rt_code = sp_maxutn 1, @saleutn Output
							IF @@Error <> 0 OR @rt_code <> 0
							Begin
								Set @continue  = -1															
							End 									
							SET @total_availablestock = @total_availablestock - @Quantity - @BonusQty

							Insert Into SaleDetail (SaleInvCode, icode, gcode, batch, expiry, packqty, looseqty, bonusqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup)
							Values (@saleinvcode, @icode, @gcode, @batch, @expiry, 0, @Quantity, @BonusQty, @packunits, @saleprice, @hold_avgprice, @rate / @packunits, @discperc, 0, @itemflatdisc, @rate, @unitsalestax, @gstperc1, @saleutn, @total_availablestock, @rowgroup)
							Select @Err = @@Error, @RowCount = @@RowCount
							IF @Err <> 0 OR @RowCount = 0 
							Begin
								RaisError( 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %d' ,16,1, @SaleInvCode  )
								Set @continue  = -1
							End 							
							Else
							Begin
								Set @newqty = @currqty - @delqty
								IF @newqty > 0
									Execute @rt_code = sp_SaleUpdateItemStockBatch @gcode, @icode, @batch, @expiry, @newqty , @currqty
								Else
									Execute @rt_code = sp_DeleteItemStockBatch @gcode, @icode, @batch, @expiry, @delqty
								IF @@Error <> 0 OR @rt_code <> 0 
								Begin
									Set @continue  = -1								
								End
							End
							Set @counter = @counter + 1
							Fetch Next From ItemBatch_Cursor
							Into 	@gcode, @batch, @expiry, @currqty
						End
						Close ItemBatch_Cursor
						Deallocate ItemBatch_Cursor
					End
					Else
					Begin
						Set @itemname = (Select name from item where icode = @icode )	
						RaisError( 'Not enough stock for item (%s) to decrease for Sale Inv. No : %d' , 16 , 1, @itemname, @SaleInvCode  )
						Set @continue  = -1								
					End
				End
			End	
			Set @innercounter = @innercounter + 1
			Set @anyitem_exist  = ISNULL(( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp ), 0)
		End
	End
	IF @OldInvCode > 0
		UPDATE #SaleTemp SET SaleInvCode = @SaleInvCode WHERE OldInvCode = @OldInvCode AND RowID=@RowID
	ELSE
		UPDATE #SaleTemp SET SaleInvCode = @SaleInvCode WHERE RowID=@RowID

	Set @RowID = @RowID + 1
	Set @anyitem_exist  = ISNULL(( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp ), 0)
End

IF ( @continue >= 0 )
Begin
	Set @sinvno = (SELECT MIN(SaleInvCode) FROM #SaleTemp)
	Set @einvno = (SELECT MAX(SaleInvCode) FROM #SaleTemp)

	Update Saleledger 
	Set InvTotal = dbo.fn_getSaleInvTotal (Saleledger.saleinvcode)
	Where saleinvcode between @sinvno and @einvno

	Select @Err = @@Error, @Rowcount = @@RowCount
	IF  @Err <> 0 OR @RowCount = 0
	Begin
		RaisError( 'Unable to update SaleInvoices for Sale Inv. total' , 16 , 1 )
		Set @continue  = -1									
	End
End

Return @continue
GO

-- sp_GeneratePayroll (last defined by script 7940)
CREATE Procedure dbo.sp_GeneratePayroll @Type INT, @EmpCategory VARCHAR(8000), @EmpDept VARCHAR(8000), @StartDate DATETIME, @EndDate DATETIME, @UserCode Int, @PaySlipsGenerated Int Output 
As
/*
Author: M. Azhar Inayat
Purpose:This Stored Procedure generates payroll for employees selected using employee category and department
*/
Declare @StartCode Int, @EndCode Int, @RowID INT, @PayslipRows INT
Declare @RowCount Int, @TotalRows Int, @continue Int, @Err Int, @rt_code Int 

DECLARE @Tab_EmpCategory TABLE (CODE INT NOT NULL)
DECLARE @Tab_EmpDept TABLE (CODE INT NOT NULL)

CREATE TABLE #TempPay (
PayrollCode INT,
EmpCode INT, WorkDays NUMERIC(6,2), Presents NUMERIC(6,2), Absents NUMERIC(6,2), Leaves NUMERIC(6,2),
PerHourRate NUMERIC(12,2), BasicPay NUMERIC(12,2), OverTimeHours NUMERIC(12,2), OverTimeRate NUMERIC(12,2), 
OverTime NUMERIC(12,2), BonusPay NUMERIC(12,2), SpecialPay NUMERIC(12,2), AdditionalPay NUMERIC(12,2), 
OtherPay NUMERIC(12,2), Fine NUMERIC(12,2), Penalty NUMERIC(12,2), OtherCharge NUMERIC(12,2), Advance NUMERIC(12,2), 
NetPayable NUMERIC(12,2), Sundays NUMERIC(6,2), Holidays NUMERIC(6,2), 
AdvAccCode INT, PayType INT, HoursWorked NUMERIC(10,4), ROWID INT IDENTITY(1,1)
)

INSERT INTO @Tab_EmpCategory SELECT Code FROM dbo.udf_StringToTabl(@EmpCategory, ',')
INSERT INTO @Tab_EmpDept SELECT Code FROM dbo.udf_StringToTabl(@EmpDept, ',')
SET @StartCode = 0
Execute @rt_code = SP_LockTabMaxkey 'EMP_Payroll' , @StartCode Output
IF @@Error <> 0 OR @rt_code <>  0
Begin
	RaisError('Error occured in aquiring latest payslip code' ,16, 1)
	RETURN -1
End

--Payroll Header
IF @Type=1
BEGIN
	INSERT INTO #TempPay 
		(PayrollCode, EmpCode, WorkDays, Presents, Absents, Leaves,
		PerHourRate, BasicPay, OverTimeHours, 
		OverTimeRate, OverTime, 
		BonusPay, SpecialPay, AdditionalPay, 
		OtherPay, Fine, Penalty, OtherCharge, Advance, 
		NetPayable, Sundays, Holidays, 
		AdvAccCode, PayType, HoursWorked)
	SELECT PayrollCode=@StartCode, E.EmpCode, WorkDays=0, Presents=ISNULL(T.Presents,0), Absents=ISNULL(T.Absents, 0), 
		Leaves=ISNULL(T.Leaves,0), PerHourRate=P.PerHourRate, BasicPay=ISNULL(CASE WHEN P.OverTime='Y' THEN CASE WHEN T.HoursWorked > (P.WorkingHours * P.PayFrequencyFactor) THEN (P.WorkingHours * P.PayFrequencyFactor) ELSE T.HoursWorked END ELSE T.HoursWorked END * P.PerHourRate,0), 
		OverTimeHours=ISNULL(T.OverTimeHrs,0), 
		OverTimeRate=P.OverTimeRate, OverTime=ISNULL(CASE WHEN P.OverTime='Y' THEN T.OverTimeHrs * P.OverTimeRate ELSE 0 END,0), 
		BonusPay=0, SpecialPay=0, AdditionalPay=0, 
		OtherPay=0, Fine=0, Penalty=0, OtherCharge=0,
		Advance= ISNULL((SELECT 
				Advance=CASE 
					WHEN T.Adv_Acc_Balance <> T.Balance THEN 
						CASE WHEN T.Adv_Acc_Balance >= T.Installment THEN T.Installment 
						ELSE T.Adv_Acc_Balance END 
					ELSE 
						CASE WHEN T.Balance >= T.Installment THEN T.Installment 
						ELSE T.Adv_Acc_Balance END
					END
			FROM
				(SELECT 
					EA.EmpAdvAccCode,
					Amount=SUM(EA.Amount), 
					ReturnedAmt=SUM(EA.ReturnedAmt), 
					Balance=SUM(EA.Amount) - SUM(EA.ReturnedAmt), 
					Installment=SUM(EA.Installment),
					Adv_Acc_Balance = ISNULL((SELECT Balance=SUM(V.Debit - V.Credit) FROM VirtualGL V WHERE AccCode=EA.EmpAdvAccCode), 0)
				FROM EMP_Advance EA
				WHERE EA.Amount - EA.ReturnedAmt > 0
				GROUP BY EA.EmpAdvAccCode) T
			WHERE T.EmpAdvAccCode = E.AdvAccCode), 0), 
		NetPayable=0, Sundays=ISNULL(T.Sundays ,0), Holidays=ISNULL(T.Holidays,0), 
		E.AdvAccCode, P.PayType, HoursWorked=ISNULL(T.HoursWorked,0)
	FROM EMP_Employee E, EMP_Pay P, EMP_Category C, EMP_Department D,
		(SELECT 
			EA.EmpCode, 
			Presents = SUM(CASE WHEN EA.AttendanceStatusCode = 1 THEN 1 WHEN EA.AttendanceStatusCode = 4 OR EA.AttendanceStatusCode = 5 OR EA.AttendanceStatusCode = 6 OR EA.AttendanceStatusCode = 10 THEN 0.5 ELSE 0 END),
			Absents = SUM(CASE WHEN EA.AttendanceStatusCode = 2 OR EA.AttendanceStatusCode = 12 THEN 1 ELSE 0 END),
			Leaves = SUM(CASE WHEN EA.AttendanceStatusCode = 11 OR EA.AttendanceStatusCode = 3 THEN 1 WHEN EA.AttendanceStatusCode = 5 OR EA.AttendanceStatusCode = 6 OR EA.AttendanceStatusCode = 7 OR EA.AttendanceStatusCode = 8 THEN 0.5 ELSE 0 END),
			Sundays = CASE WHEN E.SundaysPaid ='Y' THEN ISNULL(DBO.udf_Count_DayOfWeek(@StartDate, @EndDate, 'Sunday'), 0) ELSE 0 END,
			Holidays = CASE WHEN E.HolidaysPaid ='Y' THEN ISNULL((SELECT COUNT(EH.Date) FROM EMP_Holiday EH WHERE EH.Date BETWEEN @StartDate AND @EndDate), 0) ELSE 0 END,
			OverTimeHrs = 
				CASE 
				WHEN E.Overtime='N' THEN 0 
				ELSE 
					CASE 
						WHEN (SUM(DATEDIFF(n, EA.TimeIn, ISNULL(EA.TimeOut, GETDATE()))) / 60.0000) > (E.WorkingHours * E.PayFrequencyFactor) THEN 
							(SUM(DATEDIFF(n, EA.TimeIn, ISNULL(EA.TimeOut, GETDATE()))) / 60.0000) - (E.WorkingHours * E.PayFrequencyFactor) 
						ELSE 0 
					END
				END,
			HoursWorked = CAST(SUM(DATEDIFF(n, EA.TimeIn, ISNULL(EA.TimeOut, GETDATE()))) / 60.0000 AS NUMERIC(12,4)),
			MinWorked = CAST((SUM(DATEDIFF(n, EA.TimeIn, ISNULL(EA.TimeOut, GETDATE()))) / 60) % 60 AS INT)
		FROM EMP_Attendance EA, 
				(SELECT EE.EmpCode, EE.DeptCode, EE.EmpCatCode, EP.Overtime, EP.WorkingHours, EP.WorkingWeekDays, EP.PerHourRate, EP.SundaysPaid, EP.HolidaysPaid, EP.PayFrequencyFactor
				FROM EMP_Employee EE LEFT OUTER JOIN EMP_Pay EP ON (EE.EmpCode = EP.EmpCode)) AS E
		WHERE 
			E.EmpCode = EA.EmpCode AND
			EA.TimeIn IS NOT NULL AND 
			EA.TimeOut IS NOT NULL AND 
			EA.TimeIn >= @StartDate AND EA.TimeOut <= @EndDate AND
			EA.Payed = 'N'
		GROUP BY 
			EA.EmpCode,
			E.Overtime,
			E.WorkingHours,
			E.WorkingWeekDays,
			E.SundaysPaid,	
			E.HolidaysPaid,
			E.PayFrequencyFactor) T
	WHERE C.EmpCatCode IN (SELECT Code FROM @Tab_EmpCategory) AND
		D.DeptCode IN (SELECT Code FROM @Tab_EmpDept) AND 
		E.Active = 'Y' AND
		E.EmpCatCode = C.EmpCatCode AND
		E.DeptCode = D.DeptCode AND
		E.EmpCode = P.EmpCode AND 
		E.EmpCode = T.EmpCode
	UNION
	SELECT PayrollCode=@StartCode, E.EmpCode, WorkDays=0, Presents=0, Absents=0, 
		Leaves=0, PerHourRate=P.PerHourRate, BasicPay=ISNULL(P.BasicPay,0), OverTimeHours=0, 
		OverTimeRate=P.OverTimeRate, OverTime=0, 
		BonusPay=0, SpecialPay=0, AdditionalPay=0, 
		OtherPay=0, Fine=0, Penalty=0, OtherCharge=0,
		Advance= ISNULL((SELECT 
				Advance=CASE 
					WHEN T.Adv_Acc_Balance <> T.Balance THEN 
						CASE WHEN T.Adv_Acc_Balance >= T.Installment THEN T.Installment 
						ELSE T.Adv_Acc_Balance END 
					ELSE 
						CASE WHEN T.Balance >= T.Installment THEN T.Installment 
						ELSE T.Adv_Acc_Balance END
					END
			FROM
				(SELECT 
					EA.EmpAdvAccCode,
					Amount=SUM(EA.Amount), 
					ReturnedAmt=SUM(EA.ReturnedAmt), 
					Balance=SUM(EA.Amount) - SUM(EA.ReturnedAmt), 
					Installment=SUM(EA.Installment),
					Adv_Acc_Balance = ISNULL((SELECT Balance=SUM(V.Debit - V.Credit) FROM VirtualGL V WHERE AccCode=EA.EmpAdvAccCode), 0)
				FROM EMP_Advance EA
				WHERE 	EA.Amount - EA.ReturnedAmt > 0
				GROUP BY EA.EmpAdvAccCode) T
			WHERE T.EmpAdvAccCode = E.AdvAccCode), 0), 
		NetPayable=0, Sundays=0, Holidays=0, 
		E.AdvAccCode, P.PayType, HoursWorked=0
	FROM EMP_Employee E, EMP_Pay P, EMP_Category C, EMP_Department D
	WHERE C.EmpCatCode IN (SELECT Code FROM @Tab_EmpCategory) AND
		D.DeptCode IN (SELECT Code FROM @Tab_EmpDept) AND 
		E.Active = 'Y' AND
		E.EmpCatCode = C.EmpCatCode AND
		E.DeptCode = D.DeptCode AND
		E.EmpCode = P.EmpCode AND 
		E.EmpCode NOT IN 
			(SELECT EA.EmpCode 
			FROM EMP_Attendance EA 
			WHERE EA.TimeIn IS NOT NULL AND EA.TimeOut IS NOT NULL AND 
			EA.TimeIn >= @StartDate AND EA.TimeOut <= @EndDate AND
			EA.Payed = 'N')
END
ELSE
BEGIN
	INSERT INTO #TempPay 
		(PayrollCode, EmpCode, WorkDays, Presents, Absents, Leaves,
		PerHourRate, BasicPay, OverTimeHours, 
		OverTimeRate, OverTime, 
		BonusPay, SpecialPay, AdditionalPay, 
		OtherPay, Fine, Penalty, OtherCharge, Advance, 
		NetPayable, Sundays, Holidays, 
		AdvAccCode, PayType, HoursWorked)
	SELECT PayrollCode=@StartCode, E.EmpCode, WorkDays=0, Presents=0, Absents=0, Leaves=0,
		PerHourRate=P.PerHourRate, BasicPay=ISNULL(P.BasicPay,0), OverTimeHours=0, 
		OverTimeRate=P.OverTimeRate, OverTime=0, 
		BonusPay=0, SpecialPay=0, AdditionalPay=0, 
		OtherPay=0, Fine=0, Penalty=0, OtherCharge=0,
		Advance= ISNULL((SELECT 
				Advance=CASE 
					WHEN T.Adv_Acc_Balance <> T.Balance THEN 
						CASE WHEN T.Adv_Acc_Balance >= T.Installment THEN T.Installment 
						ELSE T.Adv_Acc_Balance END 
					ELSE 
						CASE WHEN T.Balance >= T.Installment THEN T.Installment 
						ELSE T.Adv_Acc_Balance END
					END
			FROM
				(SELECT 
					EA.EmpAdvAccCode,
					Amount=SUM(EA.Amount), 
					ReturnedAmt=SUM(EA.ReturnedAmt), 
					Balance=SUM(EA.Amount) - SUM(EA.ReturnedAmt), 
					Installment=SUM(EA.Installment),
					Adv_Acc_Balance = ISNULL((SELECT Balance=SUM(V.Debit - V.Credit) FROM VirtualGL V WHERE AccCode=EA.EmpAdvAccCode), 0)
				FROM EMP_Advance EA
				WHERE 	EA.Amount - EA.ReturnedAmt > 0
				GROUP BY EA.EmpAdvAccCode) T
			WHERE T.EmpAdvAccCode = E.AdvAccCode), 0), 
		NetPayable=0, Sundays=0, Holidays=0, 
		E.AdvAccCode, P.PayType, HoursWorked=0
	FROM EMP_Employee E, EMP_Pay P, EMP_Category C, EMP_Department D
	WHERE C.EmpCatCode IN (SELECT Code FROM @Tab_EmpCategory) AND
		D.DeptCode IN (SELECT Code FROM @Tab_EmpDept) AND 
		E.Active = 'Y' AND
		E.EmpCatCode = C.EmpCatCode AND
		E.DeptCode = D.DeptCode AND
		E.EmpCode = P.EmpCode
END

UPDATE #TempPay SET PayrollCode = PayrollCode + RowID

SET @PayslipRows = ISNULL((SELECT COUNT(*) FROM #TempPay), 0)
IF @PayslipRows = 0
	RETURN 0

SET @EndCode = ISNULL((SELECT MAX(PayrollCode) FROM #TempPay), @StartCode)

-- Insert Payroll Header Rows
INSERT INTO EMP_Payroll (PayrollCode,Date,UserCode,Posted,PostDate,PostedBy,LastSaved,
	FromDate,ToDate,EmpCode,WorkDays,Presents,Absents,Leaves,PerHourRate,BasicPay,
	OverTimeHours,OverTimeRate,OverTime,BonusPay,SpecialPay,AdditionalPay,OtherPay,Fine,Penalty,
	OtherCharge,Advance,NetPayable,Remarks,Paid,PaidVia,PaymentDate,PaymentRefNo,
	PaymentRemarks,PaidBy,Sundays,Holidays,HoursWorked)
SELECT PayrollCode,Date=GETDATE(),UserCode=@UserCode,Posted='N',PostDate=NULL,PostedBy=NULL,LastSaved=GETDATE(),
	FromDate=@StartDate,ToDate=@EndDate,EmpCode,WorkDays,Presents,Absents,Leaves,PerHourRate,BasicPay,
	OverTimeHours,OverTimeRate,OverTime,BonusPay,SpecialPay,AdditionalPay,OtherPay,Fine,Penalty,
	OtherCharge,Advance,NetPayable,Remarks='Auto Generated',Paid='N',PaidVia=2,PaymentDate=GETDATE(),PaymentRefNo='CASH',
	PaymentRemarks='',PaidBy=@UserCode,Sundays,Holidays,HoursWorked
FROM #TempPay
--Insert Allowances

INSERT INTO EMP_PayrollAllowances
SELECT 
	PayrollCode = (SELECT T.PayrollCode FROM #TempPay T WHERE T.EmpCode=PA.EmpCode),
	PA.AllowanceCode,
	PA.AttendanceWise,
	PA.Percentage,
	PA.FlatAmount
FROM EMP_Employee E, EMP_Category C, EMP_Department D, EMP_PayAllowance PA
WHERE C.EmpCatCode IN (SELECT Code FROM @Tab_EmpCategory) AND
	D.DeptCode IN (SELECT Code FROM @Tab_EmpDept) AND 
	E.Active = 'Y' AND
	E.EmpCatCode = C.EmpCatCode AND
	E.DeptCode = D.DeptCode AND
	E.EmpCode = PA.EmpCode

--Insert Deductions

INSERT INTO EMP_PayrollDeductions
SELECT 
	PayrollCode = (SELECT T.PayrollCode FROM #TempPay T WHERE T.EmpCode=PD.EmpCode),
	PD.DeductionCode,   
	PD.Percentage,   
	PD.FlatAmount  
FROM EMP_Employee E, EMP_Category C, EMP_Department D, EMP_PayDeduction PD
WHERE C.EmpCatCode IN (SELECT Code FROM @Tab_EmpCategory) AND
	D.DeptCode IN (SELECT Code FROM @Tab_EmpDept) AND 
	E.Active = 'Y' AND
	E.EmpCatCode = C.EmpCatCode AND
	E.DeptCode = D.DeptCode AND
	E.EmpCode = PD.EmpCode

SET @PaySlipsGenerated = ISNULL((SELECT COUNT(*) FROM #TempPay), 0)

UPDATE EMP_Payroll
SET NetPayable = ISNULL(BasicPay,0) + ISNULL(OverTime,0) + ISNULL(BonusPay,0) + ISNULL(AdditionalPay,0) + ISNULL(OtherPay,0) - ISNULL(Fine,0) - ISNULL(Penalty,0) - ISNULL(OtherCharge,0) - ISNULL(Advance,0) +
	ISNULL((SELECT Allowances=SUM(EA.FlatAmount + ROUND((E.BasicPay * EA.Percentage * 0.01), 2))
		FROM EMP_PayrollAllowances EA, Emp_Payroll E
		WHERE EA.PayrollCode=E.PayrollCode AND E.PayrollCode = EMP_Payroll.PayrollCode
		GROUP BY E.PayrollCode, E.BasicPay), 0) -
	ISNULL((SELECT Deductions=SUM(ED.FlatAmount + ROUND((E.BasicPay * ED.Percentage * 0.01), 2))
		FROM EMP_PayrollDeductions ED, Emp_Payroll E
		WHERE ED.PayrollCode=E.PayrollCode AND E.PayrollCode = EMP_Payroll.PayrollCode
		GROUP BY E.PayrollCode, E.BasicPay), 0)
WHERE PayrollCode BETWEEN @StartCode AND @EndCode

EXECUTE @rt_code = SP_UpdateTabMaxkey 'EMP_Payroll' , @EndCode
IF @@ERROR <> 0 OR @rt_code <> 0
BEGIN
	RaisError('Problem while Updating EMP_Payroll Key Value', 16, 1)
	RETURN -1
END

RETURN 0
GO

-- sp_GenerateReceipt (last defined by script catalog)
CREATE Procedure dbo.sp_GenerateReceipt 
	@ProdCode Int, 
	@UserCode Int, 
	@HeaderNo Int, 
	@serverdate DateTime, 
	@IssueInvCode INT,
	@ReceiptInvCode Int OutPut 
As
Declare @Code Int, @deptcode Int, @category smallint, @module SmallInt, @utn Int, @HeaderInvNo Int, @ReceiptCode INT
Declare @IssueType SmallInt, @PriceType SmallInt, @priority SmallInt, @GodownStrategy SMALLINT, @GroupCode INT, @cracccode smallint
Declare @ICode Int, @GCode Int, @packunits Int, @AreaCode Int
Declare @GivenQty NUMERIC(15, 4), @TotalQty NUMERIC(15, 4), @CurrQty NUMERIC(15, 4), @DelQty NUMERIC(15, 4), @BatchQty NUMERIC(15, 4), @ReqQty NUMERIC(15, 4), @NewQty NUMERIC(15, 4), @TotStock NUMERIC(15, 4)
Declare @Price Numeric(12,2), @PurPrice Numeric(12,2), @SalePrice Numeric(12,2), @Hold_AvgPrice Numeric(15,5), @RecentPurPrice Numeric(12,2), @NewAvgPrice NUMERIC(15,5)
Declare @batch VarChar(100), @ItemName VarChar(100), @UpdateAvgPrice CHAR(1)
Declare @Items_Rows Int, @Counter Int, @RowCount Int, @TotalRows Int, @continue Int, @Err Int, @rt_code Int 
Declare @expiry DateTime, @RecomputeCost CHAR(1), @AutoPost CHAR(1), @AccountFor CHAR(1)

/*
Author: M.Usman, Azhar
Purpose:This Stored Procedure takes an argument of Production Code (@ProdCode)
	and against that Production Code it generates Receipt Invoice Auto Posted.
*/
Set @continue = 0
Set @DeptCode = ISNULL((SELECT ReceiptDeptCode FROM ProdHeader WHERE ProdCode = @ProdCode), 1)
Set @AreaCode = 1 /* Default Selection */
Set @module = ( Select Module From Module Where Lower(Name) = 'receipt' ) 
Set @pricetype = DBO.Fn_Get_INT_Preference('ReceiptPriceTypeCode')
SET @GroupCode = ISNULL((SELECT MIN(GroupCode) FROM UserGroups WHERE UserCode=@UserCode), 1)
SET @Category = 2 -- Production
SET @AccountFor = ISNULL((SELECT AccountFor FROM ReceiptCategory WHERE ReceiptCategoryCode=@Category), 'N')
IF @AccountFor = 'Y'
	SET @cracccode = ISNULL((SELECT Code FROM Global WHERE Name='GT_WIPAcc'), 33) -- cr wor in process a/c
ELSE
	SET @cracccode = NULL

IF @GroupCode > 0 
	SET @GodownStrategy = ISNULL((SELECT ReceiptGodownStrategy FROM Groups WHERE GroupCode=@GroupCode), 1)
ELSE
	SET @GodownStrategy = 1

IF @GodownStrategy = 1
	Set @GCode = ( Select ReceiptGCode From ProdHeader Where ProdCode = @ProdCode )

Set @batch = DBO.Fn_GetPreference('defaultbatch')
Set @expiry = DBO.Fn_Get_DateTime_Preference('defaultexpiry')
SET @UpdateAvgPrice = DBO.Fn_GetPreference('UpdAvgPriceInReceipt')
Set @priority = 10
Set @RecomputeCost = DBO.Fn_GetPreference('ReComputeCostInProduction')
SET @AutoPost = DBO.Fn_GetPreference('AutoPostReceiptOnProdPost')
IF @AutoPost IS NULL
	SET @AutoPost = 'Y'

Declare Cursor_Items Cursor Forward_Only Static
FOR	Select			
	PD.ICode As ICode, 
	PD.Batch, PD.Expiry,
	Sum(PD.Qty) As Qty , 
	Max(I.PackUnits) As PackUnits ,
	Round(Max(I.PurPrice)/Max(I.PackUnits) , 2) As PurPrice ,
	Round(Max(I.SalePrice)/Max(I.PackUnits) , 2) As SalePrice ,
	Round(Max(I.RecentPurPrice)/Max(I.PackUnits) , 2) As RecentPurPrice ,
	CASE WHEN @IssueInvCode > 0 THEN 
		CASE @RecomputeCost
			WHEN 'Y' THEN 
				ROUND((SELECT SUM(ISD.Qty * ISD.Price) FROM IssueDetail ISD, RecipeDetail RD WHERE ISD.IssueInvCode = @IssueInvCode AND R.RecipeCode = RD.RecipeCode AND RD.ICode = ISD.ICode) / CASE WHEN Sum(PD.Qty) = 0 THEN 1 ELSE Sum(PD.Qty) END , 2)
			ELSE 
				CASE @pricetype WHEN 1 THEN Round(Max(I.SalePrice)/Max(I.PackUnits) , 2) WHEN 2 THEN Round(Max(I.SalePrice2)/Max(I.PackUnits) , 2) WHEN 3 THEN Round(Max(I.SalePrice3)/Max(I.PackUnits) , 2) WHEN 4 THEN Round(Max(I.PurPrice)/Max(I.PackUnits) , 2) WHEN 5 THEN Round(Max(I.RecentPurPrice)/Max(I.PackUnits) , 2) WHEN 6 THEN Round(Max(I.AvgPrice), 2) WHEN 7 THEN Round(Max(I.SalePrice4)/Max(I.PackUnits) , 2) WHEN 8 THEN Round(Max(I.SalePrice5)/Max(I.PackUnits) , 2) END 
		END
	ELSE
		CASE @pricetype WHEN 1 THEN Round(Max(I.SalePrice)/Max(I.PackUnits) , 2) WHEN 2 THEN Round(Max(I.SalePrice2)/Max(I.PackUnits) , 2) WHEN 3 THEN Round(Max(I.SalePrice3)/Max(I.PackUnits) , 2) WHEN 4 THEN Round(Max(I.PurPrice)/Max(I.PackUnits) , 2) WHEN 5 THEN Round(Max(I.RecentPurPrice)/Max(I.PackUnits) , 2) WHEN 6 THEN Round(Max(I.AvgPrice), 2) WHEN 7 THEN Round(Max(I.SalePrice4)/Max(I.PackUnits) , 2) WHEN 8 THEN Round(Max(I.SalePrice5)/Max(I.PackUnits) , 2) END 
	END As Price
From  	Recipe R, 
	(
	Select ICode, Qty, Batch, Expiry
	From   ProdDetail
	Where  ProdDetail.ProdCode = @ProdCode
	) PD, Item I
Where   R.ResultedItem = PD.ICode AND
	PD.ICode = I.ICode AND
	R.Priority = ( Select Min(Priority) From Recipe Where ResultedItem = PD.ICode )
Group By PD.ICode, PD.Batch, PD.Expiry, R.RecipeCode

Open Cursor_Items
Set @Items_Rows = @@Cursor_Rows
IF @Items_Rows > 0 
Begin
	Execute @rt_code = sp_GetTabMaxkey 'ReceiptHeader' , @Code Output
	IF @@Error <> 0 OR @rt_code <>  0
	Begin
		Set @continue  = -1
	End
	Else
	Begin
		Set @ReceiptInvCode = @Code
		Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno , @module,  @headerinvno Output 
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		Else
		Begin
			Set @ReceiptCode = NULL
			Execute @rt_code = sp_GetReceiptCategoryCounter @Category , @ReceiptCode  Output 
			IF @@Error <> 0 OR @rt_code <>  0
			Begin
				Set @continue  = -1
			End
			Else
			Begin
				Insert Into ReceiptHeader (ReceiptInvCode, DeptCode, Date, OriginalDate, SalesManCode, Posted, PostDate, PostedBy, AreaCode, HeaderNo, HeaderInvNo, PriceTypeCode, Remarks, ReceiptCategoryCode, AccountFor, CrAccCode, ReceiptCode)
				Values (@Code, @deptcode, @serverdate, @serverdate, @usercode, @AutoPost, @serverdate, @usercode, @AreaCode, @headerno, @headerinvno, @pricetype, 'SYSTEM GENERATED RECEIPT', @Category, @AccountFor, @CrAccCode, @ReceiptCode)
				Select @Err = @@Error, @RowCount = @@RowCount
				IF @Err <> 0 OR @RowCount = 0 
				Begin 
					RaisError( 'Error occured in inserting record into Receipt Header : %d' ,16,1,  @Code  )
					Set @continue  = -1
				End 
				Else
				Begin
					Fetch Next From Cursor_Items
					Into @icode, @Batch, @Expiry, @givenqty, @packunits, @purprice, @saleprice, @recentpurprice, @price
					While @@Fetch_Status = 0 AND @continue >= 0
					Begin
						IF @GodownStrategy = 2
							SET @Gcode = ISNULL((SELECT GCode FROM Item WHERE ICode=@icode), 1)
	
						Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
						IF @@Error <> 0 OR @rt_code <> 0
						Begin
							Set @continue  = -1
						End
						Else
						Begin
							Execute @rt_code = sp_maxutn 1, @utn OutPut
							IF @@Error <> 0 OR @rt_code <>  0
							Begin
								Set @continue  = -1															
							End 									
							Set @packunits = Case When @packunits Is Null Then 1 When @packunits = 0 Then 1 Else @packunits End
	
							Execute @rt_code = sp_GetItemStockAll @ICode, @TotStock OutPut
							IF @@Error <> 0 OR @rt_code <>  0
							Begin
								Set @continue  = -1															
							End
	
							IF @UpdateAvgPrice = 'Y'
							BEGIN
								SET	@NewAvgPrice = ISNULL((SELECT ROUND(((@TotStock * @hold_avgprice) + (@givenqty * @price)) / (@givenqty + @TotStock), 5) ), 0)
								IF @AutoPost='Y'
								BEGIN
									Execute @rt_code = sp_UpdateItemAvgPrice @ICode, @NewAvgPrice
									IF @@Error <> 0 OR @rt_code <>  0
									Begin
										Set @continue  = -1															
									End
								END
							END
							ELSE
							BEGIN
								SET @NewAvgPrice = @hold_avgprice
							END
	
							IF @continue <> -1
							BEGIN
								Insert Into ReceiptDetail (ReceiptInvCode, GCode, ICode, Batch, Expiry, Qty, Priority, SalePrice, PurchasePrice, AvgPrice, PackUnits, MRPP, ReceiptUtn, Price, UpdateAvgPrice, NewAvgPrice, CurrStock )
								Values(@Code, @GCode, @ICode, @batch, @expiry, @givenqty, @priority, @saleprice, @purprice, @hold_avgprice, @packunits, @recentpurprice, @utn, @price, @UpdateAvgPrice, @NewAvgPrice, @TotStock )
								Select @Err = @@Error, @RowCount = @@RowCount
								IF @Err <> 0 OR @RowCount = 0 
								Begin 
									RaisError( 'Error occured in inserting record into Receipt Detail for Production : %d' ,16,1,  @ProdCode  )
									Set @continue  = -1
								End 							
								Else
								Begin
									IF @AutoPost = 'Y'
									BEGIN
										Execute @rt_code = sp_GetItemStockBatch @gcode, @icode, @batch, @expiry, @currqty Output
										IF @@Error <> 0 OR @rt_code <> 0 
										Begin
											Set @continue  = -1																	
										End 
										Else
										Begin
											Set @newqty = @currqty + @givenqty	
											Execute @rt_code = sp_UpdateItemStockBatch @gcode, @icode, @batch, @expiry, @newqty
											IF @@Error <> 0 OR @rt_code <> 0 
											Begin
												Set @continue  = -1								
											End
										End
									END
								End
							END
						End
						Fetch Next From Cursor_Items
						Into @icode, @Batch, @Expiry, @givenqty , @packunits, @purprice, @saleprice, @recentpurprice, @price
	
					End
				End
			End
		End
	End	
End

Close Cursor_Items
Deallocate Cursor_Items

IF @continue <> 0 
Begin
	Return -1
End
Else
Begin 
	Return 0
End
GO

-- sp_GenerateReceipt_On_ProdunctionNote (last defined by script catalog)
CREATE    Procedure sp_GenerateReceipt_On_ProdunctionNote
	@ProdNoteCode Int, 
	@UserCode Int, 
	@ReceiptInvCode Int OutPut 
As
Declare @Code Int, @RowID INT, @deptcode Int, @module SmallInt, @category SmallInt, @utn Int, @HeaderInvNo Int
Declare @IssueType SmallInt, @PriceType SmallInt, @priority SmallInt, @HeaderNo Int, @ReceiptCode INT, @cracccode smallint
Declare @ICode Int, @GCode Int, @packunits Int, @AreaCode Int, @TotalPieces INT, @PiecesInHand INT
Declare @GivenQty NUMERIC(15, 4), @TotalQty NUMERIC(15, 4), @CurrQty NUMERIC(15, 4), @DelQty NUMERIC(15, 4), @BatchQty NUMERIC(15, 4), @ReqQty NUMERIC(15, 4), @NewQty NUMERIC(15, 4), @TotStock NUMERIC(15, 4)
Declare @Price Numeric(12,2), @PurPrice Numeric(12,2), @SalePrice Numeric(12,2), @Hold_AvgPrice Numeric(15,5), @RecentPurPrice Numeric(12,2), @NewAvgPrice NUMERIC(15,5), @NetRate NUMERIC(15,5)
Declare @batch VarChar(100), @ItemName VarChar(100), @UpdateAvgPrice CHAR(1), @errtext VARCHAR(4000)
Declare @Items_Rows Int, @Counter Int, @RowCount Int, @TotalRows Int, @continue Int, @Err Int, @rt_code Int 
Declare @expiry DateTime, @serverdate DateTime, @RecomputeCost CHAR(1), @AccountFor CHAR(1)

/*
Author: M.Azhar Inayat
Purpose:This Stored Procedure takes an argument of Production Note Code (@ProdNoteCode)
and against that Production Note it generates Receipt Invoice Auto Posted.
*/
Set @continue = 0
Set @DeptCode = ISNULL((SELECT ReceiptDeptCode FROM ProdNote WHERE ProdNoteCode=@ProdNoteCode), 1)
Set @HeaderNo = 1
Set @AreaCode = 1 /* Default Selection */
Set @module = ( Select Module From Module Where Lower(Name) = 'receipt' ) 
Set @pricetype = DBO.Fn_Get_INT_Preference('ReceiptPriceTypeCode')
Set @batch = DBO.Fn_GetPreference('defaultbatch')
Set @expiry = DBO.Fn_Get_DateTime_Preference('defaultexpiry')
SET @UpdateAvgPrice = DBO.Fn_GetPreference('UpdAvgPriceInReceipt')
Set @priority = 10
Set @RecomputeCost = DBO.Fn_GetPreference('ReComputeCostInProduction')
SET @serverdate = GETDATE()
SET @Category = 2 -- Production
SET @AccountFor = ISNULL((SELECT AccountFor FROM ReceiptCategory WHERE ReceiptCategoryCode=@Category), 'N')
IF @AccountFor = 'Y'
	SET @cracccode = ISNULL((SELECT Code FROM Global WHERE Name='GT_WIPAcc'), 33) -- cr wor in process a/c
ELSE
	SET @cracccode = NULL

Declare Cursor_Items Cursor Forward_Only Static
FOR	Select			
		PNR.ICode, PNR.GCode, PNR.Batch, PNR.Expiry,
		SUM(PNR.TotalPieces) AS TotalPieces,
		Sum(PNR.Qty) As Qty, PNR.PackUnits,
		Round(Max(I.PurPrice)/Max(I.PackUnits) , 2) As PurPrice ,
		Round(Max(I.SalePrice)/Max(I.PackUnits) , 2) As SalePrice ,
		Round(Max(I.RecentPurPrice)/Max(I.PackUnits) , 2) As RecentPurPrice ,
		CASE @pricetype WHEN 1 THEN Round(Max(I.SalePrice)/Max(I.PackUnits) , 2) WHEN 2 THEN Round(Max(I.SalePrice2)/Max(I.PackUnits) , 2) WHEN 3 THEN Round(Max(I.SalePrice3)/Max(I.PackUnits) , 2) WHEN 4 THEN Round(Max(I.PurPrice)/Max(I.PackUnits) , 2) WHEN 5 THEN Round(Max(I.RecentPurPrice)/Max(I.PackUnits) , 2) WHEN 6 THEN Round(Max(I.AvgPrice), 2) WHEN 7 THEN Round(Max(I.SalePrice4)/Max(I.PackUnits) , 2) WHEN 8 THEN Round(Max(I.SalePrice5)/Max(I.PackUnits) , 2) END As Price,
		PNR.RowID
	From  	ProdNoteReceipt PNR, Item I
	Where   PNR.ProdNoteCode = @ProdNoteCode AND
		PNR.ICode = I.ICode
	Group By PNR.ICode, PNR.GCode, PNR.Batch, PNR.Expiry, PNR.PackUnits, PNR.RowID

Open Cursor_Items
Set @Items_Rows = @@Cursor_Rows
IF @Items_Rows > 0 
Begin
	Execute @rt_code = sp_GetTabMaxkey 'ReceiptHeader' , @Code Output
	IF @@Error <> 0 OR @rt_code <>  0
	Begin
		Set @continue  = -1
	End
	Else
	Begin
		Set @ReceiptInvCode = @Code
		Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno , @module,  @headerinvno Output 
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		Else
		Begin
			Set @ReceiptCode = NULL
			Execute @rt_code = sp_GetReceiptCategoryCounter @Category , @ReceiptCode  Output 
			IF @@Error <> 0 OR @rt_code <>  0
			Begin
				Set @continue  = -1
			End
			Else
			Begin
				Insert Into ReceiptHeader (ReceiptInvCode, DeptCode, Date, OriginalDate, SalesManCode, Posted, PostDate, PostedBy, AreaCode, HeaderNo, HeaderInvNo, PriceTypeCode, Remarks, RecipientCode, ReceiptCategoryCode, AccountFor, CrAccCode, ReceiptCode, QE1_AccCode, QE2_AccCode, QE3_AccCode, QE4_AccCode, QE5_AccCode, WE1_AccCode, WE2_AccCode, WE3_AccCode, WE4_AccCode, WE5_AccCode, QExp1_CrAccCode, QExp2_CrAccCode, QExp3_CrAccCode, QExp4_CrAccCode, QExp5_CrAccCode, WExp1_CrAccCode, WExp2_CrAccCode, WExp3_CrAccCode, WExp4_CrAccCode, WExp5_CrAccCode)
				SELECT @Code, @deptcode, @serverdate, @serverdate, @usercode, 'Y', @serverdate, @usercode, @AreaCode, @headerno, @headerinvno, @pricetype, 'PRODUCTION NOTE BASED RECEIPT', 1, @Category, @AccountFor, @CrAccCode, @ReceiptCode, QE1_AccCode, QE2_AccCode, QE3_AccCode, QE4_AccCode, QE5_AccCode, WE1_AccCode, WE2_AccCode, WE3_AccCode, WE4_AccCode, WE5_AccCode, QExp1_CrAccCode, QExp2_CrAccCode, QExp3_CrAccCode, QExp4_CrAccCode, QExp5_CrAccCode, WExp1_CrAccCode, WExp2_CrAccCode, WExp3_CrAccCode, WExp4_CrAccCode, WExp5_CrAccCode
				FROM ProdNote
				WHERE ProdNoteCode = @ProdNoteCode
				Select @Err = @@Error, @RowCount = @@RowCount
				IF @Err <> 0 OR @RowCount = 0 
				Begin 
					RaisError( 'Error occured in inserting record into Receipt Header : %d' ,16,1,  @Code  )
					Set @continue  = -1
				End 
				Else
				Begin
					Fetch Next From Cursor_Items
					Into @icode, @gcode, @Batch, @Expiry, @TotalPieces, @givenqty, @packunits, @purprice, @saleprice, @recentpurprice, @price, @RowID
					While @@Fetch_Status = 0 AND @continue >= 0
					Begin
						Set @itemname = (Select name from item where icode = @icode )
						Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
						IF @@Error <> 0 OR @rt_code <> 0
						Begin
							SET @errtext = 'Unable to aquire item lock for item = ' + @itemname
							Set @continue  = -1
						End
	 					ELSE
	 					BEGIN
	 						Execute @rt_code = SP_GetItemTotalPiecesInHand @icode, @piecesinhand OutPut
	 						IF @@Error <> 0 OR @rt_code <> 0
	 						Begin
	 							SET @errtext = 'Unable to fetch total pieces in hand for item = ' + @itemname
	 							Set @continue  = -1
	 						End
	 						Else
	 						BEGIN
								Execute @rt_code = SP_UpdateItemTotalPiecesInHand @icode, 1, @totalpieces
								IF @@Error <> 0 OR @rt_code <> 0
								Begin
									SET @errtext = 'Error Updating pieces in hand for item = ' + @itemname
									Set @continue  = -1
								End
	 						END
	 					END
	 					IF @continue >= 0
						Begin
							Execute @rt_code = sp_maxutn 1, @utn OutPut
							IF @@Error <> 0 OR @rt_code <>  0
							Begin
								Set @continue  = -1															
							End 									
							Set @packunits = Case When @packunits Is Null Then 1 When @packunits = 0 Then 1 Else @packunits End
	
							Execute @rt_code = sp_GetItemStockAll @ICode, @TotStock OutPut
							IF @@Error <> 0 OR @rt_code <>  0
							Begin
								Set @continue  = -1															
							End
	
							IF @UpdateAvgPrice = 'Y'
							BEGIN
								SET @NetRate = ISNULL((SELECT ROUND((((Qty * Price) + (Qty * (QE1 + QE2 + QE3 + QE4 + QE5)) + (Qty * UnitWeight * (WE1 + WE2 + WE3 + WE4 + WE5))) / CASE WHEN Qty = 0 THEN 1 ELSE Qty END), 5) FROM ProdNoteReceipt WHERE ProdNoteCode = @ProdNoteCode AND RowID = @RowID), 0)
								SET @NewAvgPrice = ISNULL((SELECT ROUND(((@TotStock * @hold_avgprice) + (@givenqty * @NetRate)) / (@givenqty + @TotStock), 5) ), 0)
								Execute @rt_code = sp_UpdateItemAvgPrice @ICode, @NewAvgPrice
								IF @@Error <> 0 OR @rt_code <>  0
								Begin
									Set @continue  = -1															
								End
							END
							ELSE
							BEGIN
								SET @NewAvgPrice = @hold_avgprice
							END
	
							IF @continue <> -1
							BEGIN
								Insert Into ReceiptDetail (ReceiptInvCode, GCode, ICode, Batch, Expiry, Qty, Priority, SalePrice, PurchasePrice, AvgPrice, PackUnits, MRPP, ReceiptUtn, Price, UpdateAvgPrice, NewAvgPrice, CurrStock, TotalPieces, PiecesInHand, UnitWeight, QE1, QE2, QE3, QE4, QE5, WE1, WE2, WE3, WE4, WE5)
								SELECT @Code, @GCode, @ICode, @batch, @expiry, @givenqty, @priority, @saleprice, @purprice, @hold_avgprice, @packunits, @recentpurprice, @utn, @price, @UpdateAvgPrice, @NewAvgPrice, @TotStock , @TotalPieces, @PiecesInHand, UnitWeight, QE1, QE2, QE3, QE4, QE5, WE1, WE2, WE3, WE4, WE5
								FROM ProdNoteReceipt
								WHERE ProdNoteCode = @ProdNoteCode AND RowID = @RowID
								Select @Err = @@Error, @RowCount = @@RowCount
								IF @Err <> 0 OR @RowCount = 0 
								Begin 
									RaisError( 'Error occured in inserting record into Receipt Detail for Production : %d', 16, 1, @ProdNoteCode)
									Set @continue  = -1
								End 							
								Else
								Begin
									Execute @rt_code = sp_GetItemStockBatch @gcode, @icode, @batch, @expiry, @currqty Output
									IF @@Error <> 0 OR @rt_code <> 0 
									Begin
										Set @continue  = -1																	
									End 
									Else
									Begin
										Set @newqty = @currqty + @givenqty	
										Execute @rt_code = sp_UpdateItemStockBatch @gcode, @icode, @batch, @expiry, @newqty
										IF @@Error <> 0 OR @rt_code <> 0 
										Begin
											Set @continue  = -1								
										End
									End
								End
							END
						End
						ELSE
						BEGIN
							RaisError(@errtext, 16 , 1)
							Set @continue  = -1								
						END
						Fetch Next From Cursor_Items
						Into @icode, @GCode, @Batch, @Expiry, @totalpieces, @givenqty , @packunits, @purprice, @saleprice, @recentpurprice, @price, @RowID
	
					End
				End
			End
		End
	End	
End

Close Cursor_Items
Deallocate Cursor_Items

IF @continue <> 0 
Begin
	Return -1
End
Else
Begin 
	Return 0
End
GO

-- sp_GenerateSale_From_PreSales (last defined by script catalog)
CREATE PROCEDURE sp_GenerateSale_From_PreSales
	@PreSaleInvCode INT,
	@UserCode SMALLINT,
	@NewSaleInvCode INT OUTPUT
AS

Declare @module Int, @headerinvno Int, @continue Int, @rt_code Int, @Err Int, @totalrows Int, @rowcount Int, @counter Int
Declare @SaleInvCode Int, @HeaderInvCode INT
Declare @saleprice Numeric(12,2), @rate Numeric(12,2), @discperc Numeric(5,2), @itemflatdisc Numeric(15,2), @unitsalestax Numeric(12,2), @gstperc1 Numeric(6,2), @gstperc2 Numeric(6,2), @hold_avgprice Numeric(15,5)
Declare @icode Int, @gcode int, @packunits Int
Declare @totalstock NUMERIC(15, 4), @totalqty NUMERIC(15, 4), @looseQty NUMERIC(15, 4), @BonusQty NUMERIC(15, 4), @totalbatchqty NUMERIC(15, 4), @delqty NUMERIC(15, 4), @currqty NUMERIC(15, 4), @newqty NUMERIC(15, 4), @balancestock NUMERIC(15, 4)
Declare @batch VarChar(100), @itemname VarChar(60), @expiry DateTime, @serverdate DateTime
Declare @saleutn BigInt, @custcode SMALLINT, @itemdescription VARCHAR(100)
DECLARE @Headerno INT, @MachineName VARCHAR(100)
Declare @rowgroup Int, @innercounter Int

Set @custcode = ISNULL((SELECT Custcode FROM PreSaleHeader WHERE PreSaleInvCode=@presaleinvcode), 19)
SET @Headerno = 1
Set @module = ( Select module from module where name = 'Sales' )
Set @serverdate = GETDATE()
SET @MachineName = LEFT(@@ServerName, 15)

Create Table #saletemp ( id int not null identity(1,1), icode Int , gcode smallint, batch varchar(100), expiry datetime, looseqty Int, bonusqty Int, SalePrice  Numeric(12,2), DiscPerc Numeric(8,2), ItemFlatDisc Numeric(12,2), UnitSalesTax Numeric(12,2), GstPerc Numeric(6,2), itemdescription varchar(100) )
Insert Into #saletemp ( icode, gcode, batch, expiry, looseqty, bonusqty , saleprice, discperc, itemflatdisc, unitsalestax, gstperc , itemdescription )
Select icode, gcode, batch, expiry, qty, 0, saleprice, discperc, itemflatdisc=0, unitsalestax=0, gstperc=0, itemdescription
From PreSaleDetail
Where PreSaleInvCode = @PreSaleInvCode AND (Qty + BonusQty) > 0
Order By rowid

Set @totalrows = ISNULL((Select count(*) from #SaleTemp), 0)
Set @continue = 0
Set @rowgroup = 0

IF @totalrows > 0 And @continue >= 0
Begin
	Execute @rt_code = sp_GetTabMaxkey 'Saleledger' , @SaleInvCode Output
	Set @rowgroup = 0
	IF @@Error <> 0 OR @rt_code <>  0
	Begin
		Set @continue  = -1
	End

	SET @NewSaleInvCode = @SaleInvCode
	IF @continue >= 0
	Begin
		Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno , @module,  @headerinvno Output 
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
	END

	IF @continue >= 0
	Begin
		Set @Err = 0 
		Set @RowCount = 1

		Insert Into SaleLedger (SaleInvCode, SaleCatCode, CustCode, SalesmanCode, Date, DiscPerc, FlatDisc, MiscCharges, SalesTax, Posted, PostDate, 
			Remarks, CustRefNo, Headerno, headerinvno, OriginalDate, ModifiedBy, PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, 
			RePrintingCounter, CashReceived, InvGSTPerc1, PrintWaranty, PrintBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3,
			CustRefno4, GSTNO, InvTotal, MachineName, ModifyCounter, ItemDiscPercNo, RelationCode, DiseaseCode, WardCode, AdmissionCode, 
			ReturnCounter, Paid, BillingDate, UnReceivedBalance, TotalOfSaleReturns, ListOfSrInvoices, printbalance, AccountFor, PaymentMode, 
			PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked, Transferable, Transfered, TransferedOn, TransferedBy, 
			Imported, ImportedBy, deliveredby, SaleTypeCode, Balance, PptCustCode, DELETED, PresCode, ImpactInventory, SaleOrderCode, 
			SaleComments1, SaleComments2, AlterSaleInvCode, RecurringInvoice, RecurringPeriod, LastRecurringInvCode, RecurringAgainst, ConsiderInPO, VisitCode, DueDate, SRBufferInvCode, CustRefNo5, 
			SuppInvCode, GRN, GCCode, Vehicle, ShipTo)
		SELECT @SaleInvCode, SaleCatCode=2, @CustCode, @UserCode, Date=GETDATE(), DiscPerc=0, FlatDisc=0, MiscCharges=0, SalesTax=0, Posted='Y', PostDate=GETDATE(), 
			Remarks, CustRefNo, @HeaderNo, @HeaderInvCode, Date=GETDATE(), ModifiedBy=NULL, PostedBy=@UserCode, Sprice=1,  QuotationCode=NULL, DoctCode=NULL, PatientCode=NULL, 
			RePrintingCounter=0, CashReceived=0, InvGSTPerc1=0, Printwaranty='N', PrintBatch='N', MessageCode=1, SManCode=NULL, InvoiceSize='F', CustRefno2, CustRefno3, 
			CustRefno4, GSTNO=1, InvTotal=0, @MachineName, ModifyCounter=NULL, ItemDiscPercNo=1, RelationCode=NULL, DiseaseCode=NULL, WardCode=NULL, AdmissionCode=NULL,
			ReturnCounter=0, Paid='N', BillingDate=OrderDate, UnreceivedBalance=0, TotalOfSaleReturns=0, '', 'Y', 'Y', PaymentMode='C', 
			PaymentAccCode=2, Amt=0, AmtBY=NULL, AmtDate=GETDATE(), AmtReference=NULL, OutStandingAmt = 0, Marked='N', Transferable='N', Transfered='N', TransferedOn=NULL, TransferedBy=NULL, 
			Imported='N', ImportedBy=NULL, DeliveredBy=NULL, SaleTypeode=1, Balance=0, PptCustCode=NULL, Deleted='N', PresCode=NULL, ImpactInventory='Y', SaleOrderCode=NULL, 
			SaleComments1=(SELECT a=DBO.Fn_GetPreference('SaleComments1')), SaleComments2=(SELECT a=DBO.Fn_GetPreference('SaleComments2')), 
			AlterSaleInvCode=NULL, RecurringInvoice='N', RecurringPeriod=0, 
			LastRecurringInvCode=NULL, RecurringAgainst=NULL, ConsiderInPO='Y', VisitCode=NULL, DueDate=GETDATE(), SRBufferInvCode=NULL, CustRefNo5=NULL, 
			SuppInvCode=NULL, GRN=NULL, GCCode=NULL, Vehicle=NULL, ShipTo=NULL
		FROM PreSaleHeader
		WHERE PreSaleInvCode = @PreSaleInvCode

		Select @Err = @@Error, @RowCount = @@RowCount

		IF @Err <> 0 OR @RowCount = 0 
		Begin 
			RaisError( 'Error occured in inserting record into Sale Ledger : %d' ,16,1,  @SaleInvCode )
			Set @continue  = -1
		End 
		ELSE
		Begin
			Set @innercounter = 1
			While ( @innercounter <= @totalrows ) AND ( @continue >= 0 )
			Begin
				Select @icode = icode , @Gcode = Gcode, @Batch=Batch, @Expiry=Expiry, @looseqty = looseqty, @bonusqty = bonusqty, @saleprice = saleprice, @discperc = discperc,  @itemflatdisc = itemflatdisc, @unitsalestax = unitsalestax, @gstperc1 = gstperc, @itemdescription=itemdescription
				From #saletemp
		        Where id = @innercounter

				Select @Err = @@Error, @RowCount = @@RowCount
				SET @totalqty = @looseqty + @bonusqty
				IF @totalqty > 0 AND @RowCount > 0 AND @Err = 0
				Begin
					Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
					IF @@Error <> 0 OR @rt_code <> 0
					Begin
						Set @continue = -1
					End
					ELSE
					Begin
						Set @totalstock = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.gcode = @gcode and godowndetail.icode = @icode  )
						Set @totalbatchqty = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.gcode = @gcode and godowndetail.icode = @icode and godowndetail.Batch = @batch and godowndetail.Expiry = @expiry)
						IF @totalbatchqty >= @totalqty
						Begin 
							Set @newqty = @totalbatchqty - @totalqty
							IF @newqty > 0
								Execute @rt_code = sp_SaleUpdateItemStockBatch @gcode, @icode, @batch, @expiry, @newqty , @totalbatchqty
							Else
								Execute @rt_code = sp_DeleteItemStockBatch @gcode, @icode, @batch, @expiry, @totalqty
	
							IF @@Error <> 0 OR @rt_code <> 0 
							Begin
								Set @continue  = -1								
							End
							ELSE
							BEGIN
								Set @rowgroup = @rowgroup + 1
								Select @rate = saleprice, @packunits = packunits
								From ITEM
								Where icode = @icode
			
								IF @packunits = 0 OR @packunits Is Null 
									Set @packunits = 1
		
								Execute @rt_code = sp_maxutn 1, @saleutn Output
								IF @@Error <> 0 OR @rt_code <> 0
								Begin
									Set @continue  = -1															
								End
								ELSE
								BEGIN
									Insert Into SaleDetail (SaleInvCode, icode, gcode, batch, expiry, packqty, looseqty, bonusqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, saleitemdescription)
									Values (@saleinvcode, @icode, @gcode, @batch, @expiry, 0, @looseqty, @bonusqty, @packunits, @saleprice, @hold_avgprice, @rate / @packunits, @discperc, 0, @itemflatdisc, @rate, @unitsalestax, @gstperc1, @saleutn, 0, @rowgroup, @itemdescription)
									Select @Err = @@Error, @RowCount = @@RowCount
									IF @Err <> 0 OR @RowCount = 0 
									Begin 
										RaisError( 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %d' ,16,1, @SaleInvCode  )
										Set @continue  = -1
									End
								END
							END						END
						ELSE
						Begin
							Set @itemname = (Select name from item where icode = @icode )	
							RaisError( 'Not enough stock for item (%s) to decrease for Sale Inv. No : %d' , 16 , 1, @itemname, @SaleInvCode  )
							Set @continue  = -1								
						End
					END
				End
				Set @innercounter = @innercounter + 1
			End

			IF ( @continue >= 0 ) and @innercounter > @totalrows
			Begin
				Update Saleledger 
				Set InvTotal = ISNULL(dbo.fn_getSaleInvTotal (Saleledger.saleinvcode), 0), OutStandingAmt=ISNULL(dbo.fn_getSaleInvTotal (Saleledger.saleinvcode), 0)
				Where saleinvcode = @saleinvcode
			
				Select @Err = @@Error, @Rowcount = @@RowCount
				IF  @Err <> 0 OR @RowCount = 0
				Begin
					RaisError( 'Unable to update Sale Inv. total for Sale Invoice %d' , @saleinvcode, 16 , 1 )
					Set @continue  = -1									
				End
			
				IF ( @continue >= 0 )
				BEGIN
					Update PreSaleHeader 
					SET Posted = 'Y', POSTDATE=GETDATE(), PostedBy = @UserCode, SaleInvCode=@SaleInvCode
					WHERE PreSaleInvCode = @PreSaleInvCode
			
					Select @Err = @@Error, @Rowcount = @@RowCount
					IF  @Err <> 0 OR @RowCount = 0
					BEGIN 
						RaisError( 'Unable to update Sale Order Status (Inv. No. %d)' , @PreSaleInvCode, 16 , 1 )
						Set @continue  = -1									
					END
				END
			
			End
		End
	End
End

Drop Table #saletemp

Return @continue
GO

-- sp_GenerateSale_From_SaleOrder (last defined by script 7965)
CREATE Procedure sp_GenerateSale_From_SaleOrder
	@SaleOrderCode INT,
	@UserCode SMALLINT,
	@NewSaleInvCode INT OUTPUT
AS

Declare @module Int, @custcode Int, @saletypecode SmallInt, @salecatcode Int, @headerinvno Int, @continue Int, @rt_code Int, @Err Int, @totalrows Int, @rowcount Int, @invcounter Int, @counter Int
Declare @SaleInvCode Int, @looseqty NUMERIC(15, 4), @satisfiableqty NUMERIC(15, 4), @satisfiedqty NUMERIC(15, 4), @ItemAdvanceTaxPerc NUMERIC(5, 2)
Declare @saleprice Numeric(12,2), @rate Numeric(12,2), @discperc Numeric(5,2), @Claimable CHAR(1), @claimableDiscPerc Numeric(6,2), @itemflatdisc Numeric(12,2), @unitsalestax Numeric(12,2), @gstperc1 Numeric(6,2), @gstperc2 Numeric(6,2), @hold_avgprice Numeric(15,5)
Declare @icode Int, @anyitem_exist Int, @packunits Int, @finalized CHAR(1), @posted CHAR(1)
Declare @totalqty NUMERIC(15, 4), @givenqty NUMERIC(15, 4), @reqqty NUMERIC(15, 4), @batchqty NUMERIC(15, 4), @delqty NUMERIC(15, 4), @currqty NUMERIC(15, 4), @newqty NUMERIC(15, 4), @total_availablestock NUMERIC(15, 4)
Declare @batch VarChar(100), @itemname VarChar(60), @expiry DateTime, @serverdate DateTime, @machinename varchar(15)
Declare @saleutn BigInt, @firsttime Bit, @Headerno Smallint, @gcode SMALLINT, @SOCatCode SMALLINT
Declare @saleorder_rowcount Int, @invdetail_exist Int, @rowgroup Int, @lineitems_rowcount Int, @innercounter Int, @saleitemdescription varchar(100)

/*
SET @finalized = ISNULL((SELECT Finalized FROM SaleOrderHeader WHERE SaleOrderCode=@SaleOrderCode), 'N')
IF @finalized <> 'Y'
BEGIN
	RaisError( 'Sale Order is Not Finalized, Please Finalize first' ,16,1)
	RETURN -1
END
*/

SET @posted = ISNULL((SELECT Posted FROM SaleOrderHeader WHERE SaleOrderCode=@SaleOrderCode), 'N')
IF @posted = 'Y'
BEGIN
	RaisError( 'Sale Order is Already Posted, Can not post again.' ,16,1)
	RETURN -1
END

Set @firsttime = 0
Set @custcode = 19
Set @salecatcode = 3 
Set @saletypecode = 2
Set @module = ( Select module from module where name = 'Sales' )
Set @serverdate = GETDATE()
SET @SOCatCode = ISNULL((SELECT SOCatCode FROM SaleOrderHeader WHERE SaleOrderCode=@SaleOrderCode), 1)

Create Table #saletemp ( id int not null identity(1,1), icode Int , gcode smallint, looseqty NUMERIC(15, 4), satisfiableqty NUMERIC(15, 4), satisfiedqty NUMERIC(15, 4), SalePrice  Numeric(12,2), DiscPerc Numeric(8,2), Claimable CHAR(1), ClaimableDiscPerc Numeric(8,2), ItemFlatDisc Numeric(12,2), UnitSalesTax Numeric(12,2), GstPerc Numeric(6,2) , saleitemdescription varchar(100), ItemAdvanceTaxPerc NUMERIC(5,2), rowid int)

Insert Into #saletemp ( icode, gcode, looseqty, satisfiableqty, satisfiedqty , saleprice, discperc, claimable, claimablediscperc, itemflatdisc, unitsalestax, gstperc , saleitemdescription, ItemAdvanceTaxPerc, rowid)
Select icode, gcode, sum(looseqty), sum(looseqty), 0, max(saleprice), max(discperc), max(claimable), max(claimablediscperc), max(itemflatdisc), max(unitsalestax), max(gstperc), saleitemdescription, max(ItemAdvanceTaxPerc), rowid=MAX(rowId)
From SaleOrderDetail
Where SaleOrderCode = @SaleOrderCode
group by icode, gcode, saleitemdescription 
Order By rowid

Set @saleorder_rowcount = (Select count(icode) from SaleOrderDetail where saleordercode = @saleordercode) + 1
Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp )
Set @continue = 0
Set @invcounter = 1
Set @invdetail_exist = 1
Set @rowgroup = 0
SET @Headerno = ( Select HeaderNo from SaleOrderHeader WHERE SaleOrderCode = @SaleOrderCode)
While @anyitem_exist > 0 And @continue >= 0
Begin
	IF @invdetail_exist >  0 
		Execute @rt_code = sp_GetTabMaxkey 'Saleledger' , @SaleInvCode Output
	IF ( @firsttime = 0  )
	Begin
		Set @firsttime = 1
	End
	Set @rowgroup = 0
	IF @@Error <> 0 OR @rt_code <>  0
	Begin
		Set @continue  = -1
	End
	Else
	Begin
		IF @invdetail_exist >  0 
			Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno , @module,  @headerinvno Output 
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		Else
		Begin
			Set @Err = 0 
			Set @RowCount = 1
			IF @invdetail_exist >  0 
			Begin
				Insert Into SaleLedger (SaleInvCode, SaleCatCode, CustCode, SalesmanCode, Date, DiscPerc, FlatDisc, MiscCharges, SalesTax, Posted, PostDate, 					Remarks, CustRefNo, Headerno, headerinvno, OriginalDate, ModifiedBy, PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, 
					RePrintingCounter, CashReceived, InvGSTPerc1, PrintWaranty, PrintBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3,
					CustRefno4, GSTNO, InvTotal, MachineName, ModifyCounter, ItemDiscPercNo, RelationCode, DiseaseCode, WardCode, AdmissionCode, 
					ReturnCounter, Paid, BillingDate, UnReceivedBalance, TotalOfSaleReturns, ListOfSrInvoices, printbalance, AccountFor, PaymentMode, 
					PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked, Transferable, Transfered, TransferedOn, TransferedBy, 
					Imported, ImportedBy, deliveredby, SaleTypeCode, Balance, PptCustCode, DELETED, PresCode, ImpactInventory, SaleOrderCode, 
					SaleComments1, SaleComments2, AlterSaleInvCode, RecurringInvoice, RecurringPeriod, LastRecurringInvCode, RecurringAgainst, ConsiderInPO, VisitCode, DueDate, SRBufferInvCode, CustRefNo5, 
					SuppInvCode, GRN, GCCode, Vehicle, ShipTo, AdvanceTax, AdvanceTaxAmt, MiscCharges1, MiscCharges2, MiscCharges3, MiscCharges4, MiscCharges5, FBRPOSFee)
				SELECT @SaleInvCode, SaleCatCode=2, CustCode, UserCode, Date=GETDATE(), DiscPerc, FlatDisc, MiscCharges, SalesTax=0, Posted='N', PostDate=GETDATE(), 
					Remarks, CustRefNo, @HeaderNo, @headerinvno, Date=GETDATE(), ModifiedBy, PostedBy, Sprice=1,  QuotationCode, DoctCode, PatientCode, 
					RePrintingCounter, CashReceived=0, InvGSTPerc1, Printwaranty='N', PrintBatch='N', MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3, 
					CustRefno4, GSTNO, InvTotal, MachineName, ModifyCounter, ItemDiscPercNo, RelationCode, DiseaseCode, WardCode, AdmissionCode=NULL,
					ReturnCounter=0, Paid='N', BillingDate, UnreceivedBalance=InvTotal, TotalOfSaleReturns=0, '', 'Y', 'Y', PaymentMode='C', 
					PaymentAccCode=2, Amt=0, AmtBY=NULL, AmtDate=GETDATE(), AmtReference=NULL, OutStandingAmt = InvTotal, Marked='N', Transferable='N', Transfered='N', TransferedOn=NULL, TransferedBy=NULL, 
					Imported='N', ImportedBy=NULL, DeliveredBy=NULL, SaleTypeode=1, Balance=0, PptCustCode, Deleted='N', PresCode, ImpactInventory='Y', SaleOrderCode, 
					SaleComments1=(SELECT a=DBO.Fn_GetPreference('SaleComments1')), SaleComments2=(SELECT a=DBO.Fn_GetPreference('SaleComments2')), 
					AlterSaleInvCode=NULL, RecurringInvoice='N', RecurringPeriod=0, 
					LastRecurringInvCode=NULL, RecurringAgainst=NULL, ConsiderInPO='Y', VisitCode=NULL, DueDate=GETDATE(), SRBufferInvCode=NULL, CustRefNo5=NULL, 
					SuppInvCode, GRN, GCCode, Vehicle, ShipTo, AdvanceTax, AdvanceTaxAmt, MiscCharges1, MiscCharges2, MiscCharges3, MiscCharges4, MiscCharges5, FBRPOSFee
				FROM SaleOrderHeader
				WHERE SaleOrderCode = @SaleOrderCode

				Select @Err = @@Error, @RowCount = @@RowCount
			End
			IF @Err <> 0 OR @RowCount = 0 
			Begin 
				RaisError( 'Error occured in inserting record into Sale Ledger : %d' ,16,1,  @SaleInvCode  )
				Set @continue  = -1
			End 
			Else
			Begin
				Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp )
				SET @lineitems_rowcount = ( Select COUNT(*) from #saletemp )
				Set @innercounter = 1
				While ( @anyitem_exist > 0 ) AND ( @innercounter <= @lineitems_rowcount ) AND ( @continue >= 0 )
				Begin
					Select @icode = icode , @gcode = gcode , @looseqty = looseqty , @satisfiableqty = satisfiableqty, @satisfiedqty = satisfiedqty, @saleprice = saleprice, @discperc = discperc, @itemflatdisc = itemflatdisc, @unitsalestax = unitsalestax, @gstperc1 = gstperc, @saleitemdescription = saleitemdescription, @Claimable=Claimable, @claimableDiscPerc=claimableDiscPerc, @ItemAdvanceTaxPerc=ItemAdvanceTaxPerc
					From #saletemp
				        Where id = @innercounter
					Select @RowCount = @@RowCount
					IF ( @RowCount = 1 ) AND  ( (@satisfiableqty - @satisfiedqty) > 0 )
					Begin
							IF ( @looseqty + @satisfiedqty ) <=  @satisfiableqty 
								Set @givenqty = @looseqty
							Else
								Set @givenqty = @satisfiableqty - @satisfiedqty
							IF @givenqty <= 0 
								Set @givenqty = 1
							Else
								Update #saletemp Set satisfiedqty = @satisfiedqty + @givenqty Where icode = @icode

							Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
							IF @@Error <> 0 OR @rt_code <> 0
							Begin
								Set @continue  = -1
							End
							Else
							Begin
								Execute @rt_code = sp_GetItemStockAll @ICode, @total_availablestock OutPut
								Set @totalqty = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.gcode = @gcode and godowndetail.icode = @icode  )
								IF @totalqty >= @givenqty 
								Begin 
									Set @rowgroup = @rowgroup + 1
									Select @rate = saleprice, @packunits = packunits
									From ITEM
									Where icode = @icode
									IF @packunits = 0 OR @packunits Is Null 
										Set @packunits = 1
									Set @reqqty = @givenqty
									Declare ItemBatch_Cursor Cursor Static Forward_Only
									For 	Select  batch, expiry, Currqty 
									From    godowndetail 
									Where  godowndetail.gcode = @gcode and
										    godowndetail.icode = @icode 
									Order by priority, expiry, Currqty
	
									Open ItemBatch_Cursor
									Set @totalrows = @@Cursor_Rows
									Fetch Next From ItemBatch_Cursor
									Into 	@batch, @expiry, @currqty
									Set @counter = 1	
									While @@Fetch_Status = 0 And @counter <= @totalrows AND @reqqty > 0
									Begin
										Set @batchqty = @currqty
										IF @batchqty >= @ReqQty 
											Set @delqty = @reqqty
										Else
											Set @delqty = @batchqty
										Set @reqqty = @reqqty - @delqty

										Execute @rt_code = sp_maxutn 1, @saleutn Output
										IF @@Error <> 0 OR @rt_code <> 0
										Begin
											Set @continue  = -1															
										End 									
										SET @total_availablestock = @total_availablestock - @delqty

										Insert Into SaleDetail (SaleInvCode, icode, gcode, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, saleitemdescription, Claimable, ClaimableDiscPerc, ItemAdvanceTaxPerc)
										Values (@saleinvcode, @icode, @gcode, @batch, @expiry, 0, @delqty, @packunits, @saleprice, @hold_avgprice, @rate / @packunits, @discperc, 0, @itemflatdisc, @rate, @unitsalestax, @gstperc1, @saleutn, @total_availablestock, @rowgroup, @saleitemdescription, @Claimable, @ClaimableDiscPerc, @ItemAdvanceTaxPerc)
										Select @Err = @@Error, @RowCount = @@RowCount
										IF @Err <> 0 OR @RowCount = 0 
										Begin 
											RaisError( 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %d' ,16,1, @SaleInvCode  )
											Set @continue  = -1
										End 							
										Else
										Begin
											Set @newqty = @currqty - @delqty
											IF @newqty > 0
												Execute @rt_code = sp_SaleUpdateItemStockBatch @gcode, @icode, @batch, @expiry, @newqty , @currqty
											Else
												Execute @rt_code = sp_DeleteItemStockBatch @gcode, @icode, @batch, @expiry, @delqty
											IF @@Error <> 0 OR @rt_code <> 0 
											Begin
												Set @continue  = -1								
											End
										End
										Set @counter = @counter + 1
										Fetch Next From ItemBatch_Cursor
										Into 	@batch, @expiry, @currqty
									End
								Close ItemBatch_Cursor
								Deallocate ItemBatch_Cursor
								End
								Else
								Begin
									Set @itemname = (Select name from item where icode = @icode )	
									RaisError( 'Not enough stock for item (%s) to decrease for Sale Inv. No : %d' , 16 , 1, @itemname, @SaleInvCode  )
									Set @continue  = -1								
								End
							End
					End	
					Set @innercounter = @innercounter + 1
					Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp )
				End
				Set @invdetail_exist = ( Select count(*) from saledetail where saleinvcode = @saleinvcode )
			End
		End	
	End
Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #saletemp )
End

Drop Table #saletemp

IF ( @continue >= 0 )
Begin
	Update Saleledger 
	Set InvTotal = dbo.fn_getSaleInvTotal (Saleledger.saleinvcode)
	Where saleinvcode = @SaleInvCode

	Select @Err = @@Error, @Rowcount = @@RowCount
	IF  @Err <> 0 OR @RowCount = 0
	Begin
		RaisError( 'Unable to update Sale Invoice for Sale Inv. %d' , 16 , 1 , @SaleInvCode)
		Set @continue  = -1									
	End

	IF ( @continue >= 0 )
	BEGIN
		UPDATE SaleOrderHeader SET Finalized='Y' WHERE SaleOrderCode = @SaleOrderCode

		Execute @rt_code = sp_PostSaleOrder @SOCatCode, @SaleOrderCode, @SaleOrderCode, @UserCode, NULL, 1
		IF @@Error <> 0 OR @rt_code <> 0
		BEGIN 
			RaisError( 'Unable to update Sale Order Posting Status (Sale Order No. %d)' , @SaleOrderCode, 16 , 1 )
			Set @continue  = -1									
		END
	END
End

IF ( @continue >= 0 )
	SET @NewSaleInvCode = @SaleInvCode

Return @continue
GO

-- SP_GenerateServiceTicket (last defined by script catalog)
CREATE PROCEDURE DBO.SP_GenerateServiceTicket @ServiceInvCode INT, @UserCode SMALLINT
AS

IF (SELECT DBO.Fn_GetPreference('genserviceticketonposting')) = 'N'
	RETURN 0

DECLARE @tot_services INT, @tot_tickets INT, @start_ticket INT, @end_ticket INT, @errcode INT, @RowId INT, @In_RowID INT, @In_Qty INT, @TicketCode INT, @ServiceCode INT, @Interval INT, @ExpiryDays INT
DECLARE @Posted CHAR(1), @Date DATETIME, @Expiry DateTime, @Price NUMERIC(12,2), @DiscPerc NUMERIC(5,2), @method CHAR(1)
DECLARE @service_table TABLE 
	(ServiceCode INT, Date DATETIME, Qty INT, Expiry DateTime, Price NUMERIC(12,2), DiscPerc NUMERIC(5,2), Rowid INT IDENTITY(1, 1), Interval INT, ExpiryDays INT)

IF @ServiceInvCode IS NULL
	RETURN 0

IF @UserCode IS NULL
	SET @UserCode = 1

SET @Posted = ISNULL((SELECT Posted FROM ServiceHeader WHERE ServiceInvCode=@ServiceInvCode), 'N')
IF @Posted = 'N' OR @Posted IS NULL
	RETURN 0

SET @method = ISNULL((SELECT DBO.Fn_GetPreference('serviceticketgenerationmethod')), 'Q')
IF @method IS NULL
	SET @method = 'Q'

SET @tot_tickets = ISNULL(
	(SELECT SUM(CASE WHEN @method = 'S' THEN S.TicketsToGenerate ELSE D.Qty END)
	FROM ServiceDetail D WITH (HOLDLOCK, ROWLOCK), Service S
	WHERE D.ServiceInvCode = @ServiceInvCode AND
		D.ServiceCode = S.ServiceCode AND
		S.TicketRequired = 'Y'), 0)

IF @tot_tickets = 0
	RETURN 0

INSERT INTO @service_table (ServiceCode, Date, Qty, Expiry, Price, DiscPerc, Interval, ExpiryDays)
SELECT D.ServiceCode, Date=GETDATE(), Qty = CASE WHEN @method = 'S' THEN S.TicketsToGenerate ELSE CAST(D.Qty AS INT) END, D.DeliveryDate, D.Price, D.DiscPerc, CASE WHEN @method = 'S' THEN S.TicketIntervalInDays ELSE 0 END, CASE WHEN @method = 'S' THEN TicketExpiryInDays ELSE 0 END
FROM ServiceDetail D, Service S
WHERE D.ServiceInvCode = @ServiceInvCode AND 
	D.ServiceCode = S.ServiceCode AND
	S.TicketRequired = 'Y'
ORDER BY D.SrvRowID

IF @@ERROR <> 0 OR @@ROWCOUNT = 0
BEGIN
	RaisError('Problem while Fetching Ticketing Services', 16, 1)
	RETURN -1
END

SET @tot_services = ISNULL((SELECT count(*) from @service_table), 0)

IF @tot_services = 0 
BEGIN
	RETURN 0
END 

SET @errcode = 0
EXECUTE @errcode = SP_LockTabMaxkey 'ServiceTicket' , @start_ticket OUTPUT
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem while Fetching Service Ticket Key Value', 16, 1)
	RETURN -1
END

SET @rowid = 1
WHILE @RowId <= @tot_services 
BEGIN
	SET @In_RowID = 1
	SET @In_Qty = (SELECT Qty FROM @service_table WHERE RowID = @RowID)
	SET @ServiceCode = (SELECT ServiceCode FROM @service_table WHERE RowID = @RowID)
	SET @Interval  = (SELECT Interval FROM @service_table WHERE RowID = @RowID)
	SET @ExpiryDays  = (SELECT ExpiryDays FROM @service_table WHERE RowID = @RowID)
	SET @Date = (SELECT Date FROM @service_table WHERE RowID = @RowID)
	SET @Expiry = (SELECT CASE WHEN @method = 'S' THEN @Date + @ExpiryDays ELSE Expiry END FROM @service_table WHERE RowID = @RowID)
	SET @Price  = ISNULL((SELECT Price FROM @service_table WHERE RowID = @RowID), 0)
	SET @DiscPerc  = ISNULL((SELECT DiscPerc FROM @service_table WHERE RowID = @RowID), 0)
	WHILE @In_RowId <= @In_Qty
	BEGIN
		Set @TicketCode = @start_ticket + @In_RowId
		IF @In_RowID > 1
		BEGIN
			SET @Date = @Date + @Interval
			SET @Expiry = (SELECT CASE WHEN @method = 'S' THEN @Date + @ExpiryDays ELSE Expiry END FROM @service_table WHERE RowID = @RowID)
		END
		INSERT INTO ServiceTicket (ServiceTicketCode, Date, ServiceInvCode, ServiceCode, Price, DiscPerc, ExpiresOn, TicketUsed, TicketUsedOn, UserCode)
		VALUES (@TicketCode , @Date, @ServiceInvCode, @ServiceCode, @Price, @DiscPerc, @Expiry, 'N', GETDATE(), @UserCode)
		IF @@ERROR <> 0 OR @@ROWCOUNT = 0
		BEGIN
			RaisError('Problem while Inserting Record in ServiceHeader', 16, 1)
			RETURN -1
		END
		Set @In_RowID = @In_RowID + 1
	END
	Set @start_ticket = @TicketCode
	Set @RowID = @RowID + 1
END
Set @end_ticket = @TicketCode
SET @errcode = 0
EXECUTE @errcode = SP_UpdateTabMaxkey 'ServiceTicket' , @end_ticket
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem while Updating Service Ticket Key Value', 16, 1)
	RETURN -1
END
GO

