-- SP_GetAliasName_WithQty (last defined by script catalog)
CREATE  PROCEDURE SP_GetAliasName_WithQty
	@UserCode INT,
	@AliasName VARCHAR(75),
	@ICode INT OUTPUT,
	@ItemName VARCHAR(60) OUTPUT,
	@RetType INT OUTPUT,
	@Qty NUMERIC(15,4) OUTPUT
AS
DECLARE @GroupCode INT, @TempICode INT, @RetCode INT
DECLARE @err INT, @rowcount INT
DECLARE @aliaslen INT, @itemcodelen INT, @weightlen INT, @WeighingScaleCode SMALLINT
DECLARE @scaleid VARCHAR(10), @NewAliasName VARCHAR(75), @WeightStr VARCHAR(75)
DECLARE @Weight NUMERIC(15,4)

SET @GroupCode = (SELECT MIN(GroupCode) FROM UserGroups WHERE UserCode = @UserCode)
Select @err = @@Error , @rowcount = @@RowCount
IF @err = 0 AND @rowcount = 1
BEGIN
