	BEGIN
		SELECT   @ICode = item.icode, @ItemName = item.name, @Qty=1
		FROM     item
		WHERE    item.customicode  = @AliasName AND 
			(item.Restricted='N' OR (Item.Restricted='Y' AND Exists (select * from grouprights where rightcode = 515 and groupcode = @GroupCode) ) ) AND
			item.Active=1 AND 
			Item.ICatCode IN 
				(SELECT ICatCode 
				FROM ItemCategory 
				WHERE ICatCode IN 
					(SELECT ItemsCategoryCode FROM ItemsGroupCategory WHERE GroupCode IN
						 (SELECT GroupCode FROM UserGroups WHERE UserCode = @UserCode)))
		Select @err = @@Error , @rowcount = @@RowCount
		IF @err <> 0
		BEGIN
			RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
			SET @RetCode = -1
			SET @RetType = 0
			RETURN @RetCode
		END
		IF @rowcount = 0
		BEGIN
			SELECT   @ICode = item.icode, @ItemName = item.name, @Qty=ISNULL((SELECT MAX(AI.Qty) FROM AlternateItemAlias AI WHERE AI.CustomICode = @AliasName), 1)
			FROM     item
			WHERE    item.icode in (SELECT MAX(AI.ICode) FROM AlternateItemAlias AI WHERE AI.CustomICode = @AliasName) AND 
				(item.Restricted='N' OR (Item.Restricted='Y' AND Exists (select * from grouprights where rightcode = 515 and groupcode = @GroupCode) ) ) AND
				item.Active=1 AND 
				Item.ICatCode IN 
					(SELECT ICatCode 
					FROM ItemCategory 
					WHERE ICatCode IN 
						(SELECT ItemsCategoryCode FROM ItemsGroupCategory WHERE GroupCode IN
							 (SELECT GroupCode FROM UserGroups WHERE UserCode = @UserCode)))
			Select @err = @@Error , @rowcount = @@RowCount
			IF @err <> 0
			BEGIN
				RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
				SET @RetCode = -1
				SET @RetType = 0
				RETURN @RetCode
			END
			IF @rowcount = 0
			BEGIN
				SET @ICode = NULL
				SET @ItemName = NULL
			END
		END
	END
	ELSE
	BEGIN
		SELECT  @ICode = item.icode, @ItemName=item.name, @Qty = 1
		FROM    item
		WHERE   item.customicode  = @AliasName AND
				  item.Active = 1 AND 
				  (item.Restricted='N' OR (Item.Restricted='Y' AND Exists (select * from grouprights where rightcode = 515 and groupcode = @GroupCode) ) )
		Select @err = @@Error , @rowcount = @@RowCount
		IF @err <> 0
		BEGIN
			RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
			SET @RetCode = -1
			SET @RetType = 0
			RETURN @RetCode
		END
		IF @rowcount = 0
		BEGIN
			SELECT  @ICode = item.icode, @ItemName=item.name, @Qty = ISNULL((SELECT MAX(AI.Qty) FROM AlternateItemAlias AI WHERE AI.CustomICode = @AliasName), 1)
			FROM    item
			WHERE   item.icode in (SELECT MAX(AI.ICode) FROM AlternateItemAlias AI WHERE AI.CustomICode = @AliasName) AND
