					END
					IF @rowcount = 0
					BEGIN
						SET @ICode = NULL
						SET @ItemName = NULL
					END
				END
		
				IF @ICode IS NULL
				BEGIN
					RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
					SET @RetCode = -1
					SET @RetType = 0
					RETURN @RetCode
				END
				ELSE 
				BEGIN
					SET @RetCode = 0
					SET @RetType = 1
				END
			END
			ELSE
			BEGIN
				RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
				SET @RetCode = -1
				SET @RetType = 0
				RETURN @RetCode
			END
