		--	RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
			SET @RetCode = -1
			SET @RetType = 0
		--	RETURN @RetCode
		END
	END
	ELSE
	BEGIN
		SET @RetCode = 0
		SET @RetType = 0
	END

	IF @ICode IS NULL
	BEGIN
		SELECT @WeighingScaleCode = MAX(WS.WeighingScaleCode)
		FROM WeighingScale WS
		WHERE LEN(@AliasName) = WS.BarCodeLen AND
			SUBSTRING(@AliasName, WS.ScaleIDPos, LEN(WS.ScaleID)) = WS.ScaleID AND
			LEN(SUBSTRING(@AliasName, WS.ItemStartPos, (WS.ItemEndPos - WS.ItemStartPos + 1))) <= (WS.ItemEndPos - WS.ItemStartPos + 1) AND
			LEN(SUBSTRING(@AliasName, WS.WeightStartPos, (WS.WeightEndPos - WS.WeightStartPos + 1))) <= (WS.WeightEndPos - WS.WeightStartPos + 1)
		IF @@Error <> 0 OR @@RowCount = 0
		BEGIN
			RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
			SET @RetCode = -1
			SET @RetType = 0
			RETURN @RetCode
		END

		IF @WeighingScaleCode > 0 
		BEGIN
			SELECT @NewAliasName = CAST(CAST(SUBSTRING(@AliasName, WS.ItemStartPos, (WS.ItemEndPos - WS.ItemStartPos + 1)) AS INT) AS VARCHAR(75)),
				@WeightStr = SUBSTRING(@AliasName, WS.WeightStartPos, (WS.WeightEndPos - WS.WeightStartPos + 1))
			FROM WeighingScale WS
			WHERE WS.WeighingScaleCode = @WeighingScaleCode 
			IF @@Error <> 0 OR @@RowCount = 0
			BEGIN
				RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
				SET @RetCode = -1
				SET @RetType = 0
				RETURN @RetCode
			END
			EXECUTE @RetCode = SP_GetAliasName_WithQty @UserCode, @NewAliasName, @ICode OUTPUT, @ItemName OUTPUT, @RetType OUTPUT, @Qty OUTPUT
			IF @@Error <> 0 OR @RetCode < 0
			BEGIN
				RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
				SET @RetCode = -1
				SET @RetType = 0
				RETURN @RetCode
			END
			IF @Icode > 0 AND @RetCode=0
			BEGIN
				SET @Qty = CAST(@WeightStr AS NUMERIC(15,4)) / 1000
				SET @RetCode = 0
				SET @RetType = 0
			END
		END 
	END
END
ELSE
BEGIN
	RaisError('Unable to fetch group code for user code = %d' , 16, 1, @usercode)
	Return -1
END
 
Return @RetCode
