-- sp_GetAllowedGroupSupplierCategory (last defined by script catalog)
CREATE Procedure sp_GetAllowedGroupSupplierCategory 
@groupcode Int , @catstring VarChar(500) OUTPUT 
AS    
Declare @suppcategory Int  
Declare @holdsuppcatstring VarChar(500)    
Declare Cursor_suppcat Cursor  
For  
Select suppcatcode 
From   GroupSupplierCategory  
Where GroupCode = @groupcode    

Open Cursor_suppcat    
Fetch Next From Cursor_suppcat 
Into @suppcategory  
Set @holdsuppcatstring = ''    
While @@Fetch_Status = 0   
Begin   
	IF @holdsuppcatstring = ''     
