-- sp_GetCustWiseLatestItemSale (last defined by script catalog)
CREATE  Procedure sp_GetCustWiseLatestItemSale 
	@custcode Int, 
	@icode Int, 
	@saleprice Numeric(8,2) OUTPUT,  
	@looseqty NUMERIC(15, 4) OUTPUT, 
	@bonusqty NUMERIC(15, 4) OUTPUT, 
	@discperc Numeric(5,2) OUTPUT, 
	@itemflatdisc Numeric(12,2) OUTPUT, 
	@rows SmallInt OUTPUT As

Select @rows = count(*) , @saleprice = Max(saledetail.saleprice) , @looseqty = Sum(saledetail.looseqty) , @bonusqty = Sum(saledetail.bonusqty) , @discperc = Max(saledetail.discperc) , @itemflatdisc = Max(saledetail.itemflatdisc)
From saleledger , saledetail , 
(
Select date = max(sl.date) 
from saleledger sl, saledetail sd
where sl.custcode = @custcode And
      sl.saleinvcode = sd.saleinvcode And
      sd.icode = @icode
) A

Where   saleledger.custcode = @custcode And 
	saleledger.date = A.date And 
	saleledger.saleinvcode = saledetail.saleinvcode And
	saledetail.icode = @icode

Group By saledetail.icode,
	 saledetail.saleprice,
	 saledetail.discperc,
	 saledetail.itemflatdisc
GO

-- SP_GetDiscountPolicyBased_ItemDiscount (last defined by script catalog)
CREATE PROCEDURE SP_GetDiscountPolicyBased_ItemDiscount
	@ICode INT,
	@QtySold NUMERIC(15,4),
	@DiscPerc NUMERIC(5, 2) OUTPUT,
	@ItemFlatDisc NUMERIC(12, 2) OUTPUT
AS
/*
Author: Muhammad Azhar Inayat
Description:
This stored procedure returns the item discount (in percenatage) 
according to the policy slab that is applicable to the qty sold 
passed as an input to this procedure
Input:
	@ICode		= Item Code
	@QtySold	= Qty Sold (units sold)
	@DiscPerc	= Item Disccount Percentage Determined via the discount policy slab applicable
*/
IF @ICode IS NULL OR @ICode < 0 
BEGIN 
	SET @DiscPerc = NULL
	SET @ItemFlatDisc = NULL
	RaisError('Problem occured while fetching Discount (%), Item is null' ,16,1)
	RETURN -1
END

DECLARE @DiscountPolicyCode SMALLINT
SET @DiscountPolicyCode = (SELECT DiscountPolicyCode FROM Item WHERE ICode = @ICode)

IF @DiscountPolicyCode IS NULL
BEGIN
	SET @DiscPerc = NULL
	SET @ItemFlatDisc = NULL
	RETURN 0
END
ELSE
BEGIN
	SET @DiscPerc = 
		(SELECT D.DiscPerc
		FROM DiscountPolicyDetail D,
			(SELECT QtyLimit=MIN(QtyLimit) 
			FROM DiscountPolicyDetail 
			WHERE ExpiryDate >= CAST(CONVERT(VARCHAR(20), GETDATE(), 101) AS DATETIME) AND 
				DiscountPolicyCode=@DiscountPolicyCode AND 
				QtyLimit >= @QtySold
			UNION
			SELECT QtyLimit=MAX(QtyLimit) 
			FROM DiscountPolicyDetail 
			WHERE ExpiryDate >= CAST(CONVERT(VARCHAR(20), GETDATE(), 101) AS DATETIME) AND 
				DiscountPolicyCode=@DiscountPolicyCode AND 
				QtyLimit <= @QtySold) T
		WHERE 
			ExpiryDate >= CAST(CONVERT(VARCHAR(20), GETDATE(), 101) AS DATETIME) AND 
			DiscountPolicyCode=@DiscountPolicyCode AND
			D.QtyLimit = T.QtyLimit AND
			T.QtyLimit <= @QtySold)

	SET @ItemFlatDisc = 
		(SELECT D.ItemFlatDisc
		FROM DiscountPolicyDetail D,
			(SELECT QtyLimit=MIN(QtyLimit) 
			FROM DiscountPolicyDetail 
			WHERE ExpiryDate >= CAST(CONVERT(VARCHAR(20), GETDATE(), 101) AS DATETIME) AND 
				DiscountPolicyCode=@DiscountPolicyCode AND 
				QtyLimit >= @QtySold
			UNION
			SELECT QtyLimit=MAX(QtyLimit) 
			FROM DiscountPolicyDetail 
			WHERE ExpiryDate >= CAST(CONVERT(VARCHAR(20), GETDATE(), 101) AS DATETIME) AND 
				DiscountPolicyCode=@DiscountPolicyCode AND 
				QtyLimit <= @QtySold) T
		WHERE 
			ExpiryDate >= CAST(CONVERT(VARCHAR(20), GETDATE(), 101) AS DATETIME) AND 
			DiscountPolicyCode=@DiscountPolicyCode AND
			D.QtyLimit = T.QtyLimit AND
			T.QtyLimit <= @QtySold)
END

RETURN 0
GO

