-- SP_GetGodownConsumption (last defined by script catalog)
CREATE PROCEDURE DBO.SP_GetGodownConsumption @GCode SMALLINT, @Type SMALLINT, @StartDate DATETIME, @EndDate DATETIME
AS
DELETE REPORTDATA

INSERT INTO REPORTDATA (Code1, Value1)
SELECT 
	ICode = T.ICode,
	Qty = SUM(T.Qty)
FROM
 	(SELECT D.ICode, Qty = SUM(D.LooseQty)
 	FROM SaleLedger H, SaleDetail D
 	WHERE 
 		(@Type = 1 OR @Type = 4) AND
 		H.Date BETWEEN @StartDate AND @EndDate AND
 		H.SaleInvCode = D.SaleInvCode AND
 		D.GCode = @GCode
 	GROUP BY
 		D.ICode
	UNION ALL
	SELECT D.ICode, Qty = -SUM(D.LooseQty)
	FROM SRLedger H, SRDetail D
	WHERE 
 		(@Type = 1 OR @Type = 4) AND
		H.Date BETWEEN @StartDate AND @EndDate AND
		H.SRInvCode = D.SRInvCode AND
		D.GCode = @GCode
	GROUP BY
		D.ICode
	UNION ALL
	SELECT D.ICode, Qty = SUM(D.Qty)
	FROM IssueHeader H, IssueDetail D
	WHERE 
		(@Type = 2 OR @Type = 4) AND
		H.Date BETWEEN @StartDate AND @EndDate AND
		H.IssueInvCode = D.IssueInvCode AND
		D.GCode = @GCode
	GROUP BY
		D.ICode
	UNION ALL
	SELECT D.ICode, Qty = -SUM(D.Qty)
	FROM ReceiptHeader H, ReceiptDetail D
	WHERE 
		(@Type = 2 OR @Type = 4) AND
		H.Date BETWEEN @StartDate AND @EndDate AND
		H.ReceiptInvCode = D.ReceiptInvCode AND
		D.GCode = @GCode
	GROUP BY
		D.ICode
	UNION ALL
	SELECT D.ICode, Qty = SUM(D.Qty)
	FROM THeader H, TDetail D
	WHERE 
		(@Type = 3 OR @Type = 4) AND
		H.Date BETWEEN @StartDate AND @EndDate AND
		H.SGCode = @GCode AND
		H.TransCode = D.TransCode
	GROUP BY
		D.ICode
	UNION ALL
	SELECT D.ICode, Qty = -SUM(D.Qty)
	FROM THeader H, TDetail D
	WHERE 
		(@Type = 3 OR @Type = 4) AND
		H.Date BETWEEN @StartDate AND @EndDate AND
		H.DGCode = @GCode AND
		H.TransCode = D.TransCode
	GROUP BY
		D.ICode
	UNION ALL
	SELECT D.ICode, Qty = SUM(CASE WHEN H.AdjCatCode = 1 THEN -1 ELSE 1 END * D.LooseQty)
	FROM AdjHeader H, AdjDetail D
	WHERE 
		@Type = 4 AND
		H.Date BETWEEN @StartDate AND @EndDate AND
		H.AdjCode = D.AdjCode AND 
		D.GCode = @GCode
	GROUP BY
		D.ICode
	UNION ALL
	SELECT D.ICode, Qty = - SUM(CASE WHEN H.PurCatCode > 2 THEN (D.LooseQty + D.BonusQty) ELSE  (D.LooseQty + D.BonusQty) * D.PackUnits END)
	FROM PurLedger H, PurDetail D
	WHERE 
		@Type = 4 AND
		H.Date BETWEEN @StartDate AND @EndDate AND
		H.PurInvCode = D.PurInvCode AND 
		D.GCode = @GCode
	GROUP BY
		D.ICode
	UNION ALL
	SELECT D.ICode, Qty = SUM(D.LooseQty)
	FROM PRLedger H, PRDetail D
	WHERE 
		@Type = 4 AND
		H.Date BETWEEN @StartDate AND @EndDate AND
		H.PRInvCode = D.PRInvCode AND 
		D.GCode = @GCode
	GROUP BY
		D.ICode) T
GROUP BY 
	ICode
HAVING 
	SUM(T.Qty) > 0
GO

-- sp_GetHeaderTabMaxKey (last defined by script catalog)
CREATE  Procedure dbo.sp_GetHeaderTabMaxKey @headercode As SmallInt, @modulecode As SmallInt, @key As Int Output
As

Declare @modulename As VarChar(60)
Declare @Err As Int , @RowCount As Int
Set NoCount On
SELECT 	@key = TABMAXKEY
FROM	_HEADERTABMAXKEY WITH (UPDLOCK HOLDLOCK)
WHERE	_HEADERTABMAXKEY.HeaderCode = @HeaderCode AND
		_HEADERTABMAXKEY.Module = @Modulecode
Select @Err = @@Error , @RowCount = @@RowCount
IF @Err = 0 AND @rowcount > 0 
Begin
	Set @key = @key + 1
	UPDATE dbo._HEADERTABMAXKEY
	SET 	 TABMAXKEY = @key
	WHERE	_HEADERTABMAXKEY.HeaderCode = @HeaderCode AND
			_HEADERTABMAXKEY.Module = @Modulecode
	Select @err = @@Error , @rowcount = @@RowCount	
	IF @Err <> 0 OR @rowcount = 0 	
	Begin
		Select @modulename = name from module where module = @modulecode
		Set NoCount OFF
		RaisError('Exception occured in updating max key for module %s' ,16, 1, @modulename)
		Return -1		
	End 
End
ELSE
Begin
	Select @modulename = name from module where module = @modulecode
	Set NoCount OFF
	RaisError('Exception occured in getting max key for module %s' ,16, 1, @modulename)
	Return -1		
End 
Set NoCount OFF

Return 0
GO

-- sp_GetIssueCategoryCounter (last defined by script catalog)
CREATE PROCEDURE dbo.sp_GetIssueCategoryCounter @Category As SmallInt, @Counter As Int Output
As
--Author : Azhar
Declare @Err As Int , @RowCount As Int
Set NoCount On

SELECT @Counter = Counter
FROM	dbo.IssueCategory WITH (UPDLOCK HOLDLOCK)
WHERE	IssueCategoryCode = @Category

Select @Err = @@Error , @RowCount = @@RowCount
IF @Err = 0 AND @rowcount > 0 
Begin
	Set @Counter = @Counter + 1
	UPDATE dbo.IssueCategory 
	SET 	Counter = @Counter
	WHERE	IssueCategoryCode = @Category

	Select @err = @@Error , @rowcount = @@RowCount	
	IF @Err <> 0 OR @rowcount = 0 	
	Begin
		Set NoCount OFF
		RaisError('Exception occured in updating Issue category counter' ,16, 1)
		Return -1		
	End 
End
ELSE
Begin
	Set NoCount OFF
	RaisError('Exception occured in fetching Issue category counter' ,16, 1)
	Return -1		
End 
Set NoCount OFF

Return 0
GO

-- SP_GetItemAliasName (last defined by script catalog)
CREATE PROCEDURE SP_GetItemAliasName
	@AliasName VARCHAR(75),
	@ICode INT OUTPUT,
	@ItemName VARCHAR(60) OUTPUT
AS
SET NOCOUNT ON
DECLARE @TempICode INT, @RetCode INT
DECLARE @err INT, @rowcount INT

SELECT  @ICode = item.icode, @ItemName=item.name
FROM    item
WHERE   item.customicode  = @AliasName AND item.Active = 1 AND item.Restricted='N'
Select @err = @@Error , @rowcount = @@RowCount
IF @err <> 0
BEGIN
	RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
	SET @RetCode = -1
	RETURN @RetCode
END

IF @rowcount = 0
BEGIN
	SELECT  @ICode = item.icode, @ItemName=item.name
	FROM    item
	WHERE   item.Active = 1 AND item.Restricted='N' AND
		item.icode in (SELECT MAX(AI.ICode) FROM AlternateItemAlias AI WHERE AI.CustomICode = @AliasName)
			  
	Select @err = @@Error , @rowcount = @@RowCount
	IF @err <> 0
	BEGIN
		RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
		SET @RetCode = -1
		RETURN @RetCode
	END
	IF @rowcount = 0
	BEGIN
		SET @ICode = NULL
		SET @ItemName = NULL
	END
END

IF @ICode IS NULL
BEGIN
	IF DBO.Fn_GetPreference('SearchItemCodeIfAliasNameNotFound') = 'Y'
	BEGIN
		SET @TempICode = ISNULL((SELECT CAST(@AliasName AS INT)),0)
		Select @err = @@Error , @rowcount = @@RowCount
		IF @err <> 0
		BEGIN
			RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
			SET @RetCode = -1
			RETURN @RetCode
		END
		IF @TempICode > 0
		BEGIN
			SELECT @ICode=item.icode, @ItemName=item.name
			FROM   item
			WHERE item.icode  = @TempICode AND item.Active = 1 AND item.Restricted='N'

			Select @err = @@Error , @rowcount = @@RowCount
			IF @err <> 0
			BEGIN
				RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
				SET @RetCode = -1
				RETURN @RetCode
			END
			IF @rowcount = 0
			BEGIN
				SET @ICode = NULL
				SET @ItemName = NULL
			END
	
			IF @ICode IS NULL
			BEGIN
				RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
				SET @RetCode = -1
				RETURN @RetCode
			END
			ELSE 
			BEGIN
				SET @RetCode = 0
			END
		END
		ELSE
		BEGIN
			RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
			SET @RetCode = -1
			RETURN @RetCode
		END
	END
	ELSE
	BEGIN
		RaisError('Unable to fetch Item Alias Name = %s' , 16, 1, @AliasName)
		SET @RetCode = -1
		RETURN @RetCode
	END
END
	 
Return @RetCode
GO

-- sp_GetItemAvgPrice (last defined by script catalog)
CREATE   PROCEDURE SP_GetItemAvgPrice 
	@ICode integer, 
	@AvgPrice NUMERIC(15,5) OUTPUT AS

Declare @err  Int, @rowcount  Int
Declare @itemname VarChar(100)
Declare @price Numeric(15, 5)

Set @Price = (Select Item.AvgPrice  From   Item WITH (UPDLOCK HOLDLOCK)  Where  ICode = @ICode)
Select @err = @@Error , @rowcount = @@RowCount
IF @err = 0 AND @rowcount = 1
Begin
	IF @Price IS NULL
	    Set @AvgPrice = 0
	ELSE
	    Set @AvgPrice = Convert(NUMERIC(15, 5), @price)
End
Else
Begin
	Set @itemname = (Select name from item Where icode = @icode )
	RaisError('Unable to fetch AvgPrice for Item = %s' , 16, 1, @itemname)
	Return -1
End

Return 0
GO

