-- sp_GetItemStockBatch (last defined by script catalog)
CREATE PROCEDURE SP_GetItemStockBatch 
	@GCode integer, 
	@ICode integer, 
	@Batch varchar (100), 
	@Expiry datetime, 
	@QTY NUMERIC(15, 4) OUTPUT AS

Declare @itemname As VarChar(100)
Declare @str_expiry As VarChar(10)

Set @qty = 0

Select 	@qty = IsNull(GodownDetail.currqty, 0)
From	GodownDetail 
Where    GodownDetail.GCode  = @GCode and
		GodownDetail.ICode  = @ICode and 
		GodownDetail.Batch  = @Batch and
		GodownDetail.Expiry = @Expiry

IF @@Error <> 0 
Begin 
	Set @itemname = (Select name from item where icode = @icode )
	Set @str_expiry = Convert(VarChar(10), @expiry, 103)
	RaisError ('Unable to fetch item batch wise stock for Item = (%s) , with batch = (%s) and expiry = (%s)' , 16 , 1 , @itemname, @batch, @str_expiry)
	Set @qty = 0 
	Return -1
End 

IF @Qty IS NULL 
Begin
	Set @Qty = 0
End

Return 0
GO

-- sp_GetItemStockInAllowedGodown (last defined by script catalog)
CREATE PROCEDURE SP_GetItemStockInAllowedGodown 
	@ICode integer, 
	@GroupCode integer, 
	@Strategy integer, 
	@Module integer, 
	@QTY NUMERIC(15, 4) OUTPUT AS  

Set @qty = 0

Select @qty = (Select IsNULL(Sum(Gd.currqty), 0)   
From GodownDetail Gd 
Where
	Gd.ICode  = @ICode AND 
	Gd.GCode IN
		(CASE @Strategy 
		WHEN 2 THEN 
		    (SELECT DISTINCT G.GCode
			From Godown G
			WHERE G.Gcode = Gd.GCode)
		ELSE 
			(SELECT DISTINCT GAG.GCode
			From GroupAllowedGodown GAG
			WHERE GAG.GroupCode = @GroupCode AND
			GAG.Module = @Module AND
			GAG.GCode = Gd.GCode) END))

IF @qty Is Null
	Set @qty = 0
GO

