-- SP_GetLoyaltyCardBalance (last defined by script catalog)
CREATE PROCEDURE DBO.SP_GetLoyaltyCardBalance
	@LoyaltyCardCode INT, 
	@BalanceDate DATETIME,
	@LayaltyPointsBalance INT OUTPUT,
	@LayaltyPointsValue NUMERIC(12,2) OUTPUT
AS
/*
Author: Muhammad Azhar Inayat
Description:
This stored procedure is used to get a loyalty card points balance and points balance value
*/
SET NOCOUNT ON
DECLARE @LoyaltyPolicyCode INT, @PointsValue NUMERIC(12,2), @LayaltyPointsSlab INT

IF @LoyaltyCardCode IS NULL OR @LoyaltyCardCode < 0 
BEGIN 
	RaisError('Problem occured while fetching loyalty card balance Information' ,16, 1)
	RETURN -1
END

SET @LayaltyPointsBalance = ISNULL((SELECT PointsBalance=ISNULL(SUM(PointsDebit - PointsCredit), 0) FROM LoyaltyCardLedger WHERE LoyaltyCardCode=@LoyaltyCardCode AND Date < @BalanceDate), 0)
SET @LayaltyPointsValue = ISNULL((SELECT Balance=ISNULL(SUM(Debit - Credit), 0) FROM LoyaltyCardLedger WHERE LoyaltyCardCode=@LoyaltyCardCode AND Date < @BalanceDate), 0)

RETURN 0
GO

