-- SP_GetSaleInvBalance (last defined by script catalog)
CREATE  PROCEDURE SP_GetSaleInvBalance 
	@ai_SaleInvCode int, 
	@an_Balance NUMERIC(15, 2) OUTPUT 
AS

SELECT @an_Balance = SaleLedger.OutstandingAmt  
FROM SaleLedger  
WHERE SaleLedger.SaleInvCode = @ai_SaleInvCode AND   
	SaleLedger.Marked = 'N' AND   
