GO

-- SP_GetSaleInvoice_JSON (last defined by script catalog)
CREATE   PROCEDURE DBO.SP_GetSaleInvoice_JSON @SaleInvCode INT, @JSON VARCHAR(8000) OUTPUT
AS
SET NOCOUNT ON

DECLARE @Qry VARCHAR(8000), @Q VARCHAR(8000), @PosID VARCHAR(100)

SET @PosID = ISNULL(DBO.Fn_GetPreference('FBRPOSID'),'')
SET @Qry = ''

--910247

DECLARE C1 CURSOR FOR 
SELECT A
FROM 
(SELECT A='{"InvoiceNumber":"","POSID":"' + @PosID + '","USIN":"' + LTRIM(RTRIM(STR(S.SaleInvCode))) + 
'","DateTime":"' + CONVERT(VARCHAR(100), S.DATE, 121) + 
'","BuyerNTN":"' + ISNULL(C.NTNNo,'') + '","BuyerCNIC":"' + ISNULL(C.NIC,'') + '","BuyerName":"' + ISNULL(A.Name,'') + '","BuyerPhoneNumber":"' + ISNULL(C.Phone,'') + '","TotalBillAmount":"' + LTRIM(RTRIM(STR(S.InvTotal,12, 2))) + 
'","TotalQuantity":"' + LTRIM(RTRIM(STR(ISNULL((SELECT SUM(D.LooseQty + D.BonusQty) FROM SaleDetail D WHERE D.SaleInvCode = @SaleInvCode),0)))) + '","TotalSaleValue":"' + LTRIM(RTRIM(STR(ISNULL(S.InvTotal,0) - ISNULL(DBO.fn_getTaxOnSaleInv(S.SaleInvCode),0),12, 2))) + 
'","TotalTaxCharged":"' + LTRIM(RTRIM(STR(DBO.fn_getTaxOnSaleInv(S.SaleInvCode), 12,2))) + 
'","Discount":"'+ LTRIM(RTRIM(STR(ISNULL((SELECT SUM(ROUND((D.LooseQty * D.ItemFlatDisc) + (D.LooseQty * (D.SalePrice - D.ItemFlatDisc) * (D.DiscPerc * 0.01)), 2)) FROM SaleDetail D WHERE D.SaleInvCode = @SaleInvCode),0),12,2)))  + '","FurtherTax":"0.0","PaymentMode":"1","RefUSIN":"null","InvoiceType":"1","Items":['
FROM SaleLedger S, Customer C, Accounts A
WHERE S.SaleInvCode=@SaleInvCode AND S.CustCode=C.CustCode AND S.CustCode=A.AccCode
UNION ALL
SELECT A='{"ItemCode":"' + I.customICode + '","ItemName":"' + I.Name + '","Quantity":"' + LTRIM(RTRIM(STR(D.LooseQty + D.BonusQty, 10,4))) +
'","PCTCode":"' + P.Description + '","TaxRate":"' + LTRIM(RTRIM(STR(STS.TaxPerc, 6, 2))) + '","SaleValue":"' + LTRIM(RTRIM(STR(D.LooseQty * D.SalePrice, 12, 2))) + '","TotalAmount":"' + LTRIM(RTRIM(STR(D.LooseQty * D.SalePrice,12, 2))) + '","TaxCharged":"' + LTRIM(RTRIM(STR((D.LooseQty + D.BonusQty) * D.UnitSalesTax,12,2))) + '","Discount":"' + LTRIM(RTRIM(STR(ROUND((D.LooseQty * D.ItemFlatDisc) + 
(D.LooseQty * (D.SalePrice - D.ItemFlatDisc) * (D.DiscPerc * 0.01)), 2),12,2))) + '","FurtherTax":"0.0","InvoiceType":"1","RefUSIN":"null"},'
FROM SaleDetail D, Item I, PCT P, SalesTaxSchedule STS
WHERE D.SaleInvCode=@SaleInvCode AND D.ICode=I.ICode AND I.PCTCode = P.PCTCode AND I.SalesTaxScheduleCode=STS.SalesTaxScheduleCode) T 

OPEN C1

FETCH NEXT FROM C1
INTO @Q

WHILE @@FETCH_STATUS = 0
BEGIN
	SET @Qry = @Qry + @Q
	FETCH NEXT FROM C1
	INTO @Q
END
SET @JSON = ''

IF Right(@Qry, 1) = ',' 
	SET @Qry = LEFT(@Qry, LEN(@Qry) - 1)

SET @JSON = @Qry + ']}'

Print @JSon

CLOSE C1
DEALLOCATE C1
RETURN 0
GO

-- sp_GetSatisfiedQty_For_Prescription (last defined by script catalog)
CREATE Procedure SP_GetSatisfiedQty_For_Prescription 
	@prescode Int, 
	@icode Int, 
	@satisfiedqty NUMERIC(15, 4) Output
AS
Set @satisfiedQty = 0
Set @satisfiedQty = ( Select IsNull(Sum(looseqty), 0)
		      From   saleledger sl inner join saledetail sd on sl.saleinvcode = sd.saleinvcode
     			     And sl.prescode = @prescode And sd.icode = @icode  )
IF (@satisfiedqty Is Null)
	Set @satisfiedQty = 0
GO

-- SP_GetService_AliasName (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_GetService_AliasName
	@UserCode INT,
	@AliasName VARCHAR(75),
	@ServiceCode INT OUTPUT,
	@ServiceName VARCHAR(60) OUTPUT
AS
DECLARE @GroupCode INT, @TempCode INT, @RetCode INT
DECLARE @err INT, @rowcount INT

SET @RetCode=0
SET @GroupCode = (SELECT MIN(GroupCode) FROM UserGroups WHERE UserCode = @UserCode)
Select @err = @@Error , @rowcount = @@RowCount
IF @err = 0 AND @rowcount = 1
BEGIN
	IF DBO.Fn_GetPreference('EnableServiceCatRights') = 'Y'
	BEGIN
		SELECT   @ServiceCode = Service.ServiceCode, @ServiceName = Service.name
		FROM     Service
		WHERE   Service.Active = 'Y' AND 
			Service.AliasName = @AliasName AND 
			Service.ServiceCatCode IN 
				(SELECT ServiceCatCode 
				FROM GroupAllowedServiceCategory
				WHERE GroupCode = @GroupCode)
		Select @err = @@Error , @rowcount = @@RowCount
		IF @err <> 0
		BEGIN
			RaisError('Unable to fetch Service Alias Name = %s' , 16, 1, @AliasName)
			SET @RetCode = -1
			RETURN @RetCode
		END
	END
	ELSE
	BEGIN
		SELECT   @ServiceCode = Service.ServiceCode, @ServiceName = Service.name
		FROM     Service
		WHERE    Service.Active = 'Y' AND Service.AliasName = @AliasName

		Select @err = @@Error , @rowcount = @@RowCount
		IF @err <> 0
		BEGIN
			RaisError('Unable to fetch Service Alias Name = %s' , 16, 1, @AliasName)
			SET @RetCode = -1
			RETURN @RetCode
		END
	END
END
ELSE
BEGIN
	RaisError('Unable to fetch group code for user code = %d' , 16, 1, @usercode)
	Return -1
END

IF @ServiceCode IS NULL
BEGIN
	RaisError('Unable to fetch Service Alias Name = %s' , 16, 1, @AliasName)
	SET @RetCode = -1
	RETURN @RetCode
END
 
Return @RetCode
GO

-- SP_GetServiceInfo (last defined by script catalog)
CREATE PROCEDURE DBO.SP_GetServiceInfo
	@ServiceInvCode INT,
	@ServiceDate DATETIME OUTPUT,
	@PatientCode INT OUTPUT,
	@RegNo VARCHAR(100) OUTPUT,
	@PatientName VARCHAR(100) OUTPUT,
	@FName VARCHAR(100) OUTPUT,
	@DOB DATETIME OUTPUT,
	@Gender CHAR(1) OUTPUT,
	@CustCode INT OUTPUT,
	@Address1 VARCHAR(100) OUTPUT,	
	@Address2 VARCHAR(100) OUTPUT,	
	@Phone VARCHAR(100) OUTPUT,	
	@AgeYears INT OUTPUT,
	@AgeMonths INT OUTPUT,
	@AgeDays INT OUTPUT,
	@AdmissionCode INT OUTPUT,
	@PatientLocation INT OUTPUT
AS

Set NoCount ON

SELECT 
	@ServiceDate=SH.Date,
	@PatientCode = 	
		(SELECT P.PatientCode FROM Patient P
		WHERE P.PatientCode IN 
			(SELECT PatientCode=SH.PatientCode 
			UNION ALL
			SELECT PA.PatientCode 
			FROM PatientAdmission PA
			WHERE PA.AdmissionCode = SH.AdmissionCode)),
	@AdmissionCode = SH.AdmissionCode
FROM
	ServiceHeader SH
WHERE
	SH.ServiceInvCode = @ServiceInvCode

IF @ServiceInvCode > 0
BEGIN
	IF @PatientCode > 0
	BEGIN
		EXECUTE DBO.SP_GetPatientInfo @PatientCode, @RegNo OUT, @PatientName OUT, @FName OUT, @DOB OUT, @Gender OUT, @CustCode OUT, @Address1 OUT, @Address2 OUT, @Phone OUT, @AgeYears OUT, @AgeMonths OUT, @AgeDays OUT
	END

	IF @AdmissionCode > 0
	BEGIN
		SELECT 
			@PatientLocation = PA.LocationCode
		FROM
			PatientAdmission PA
		WHERE 
			PA.AdmissionCode = @AdmissionCode

	END
END

RETURN 0
GO

