-- SP_GetSRInvoice_JSON (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_GetSRInvoice_JSON @SRInvCode INT, @JSON VARCHAR(8000) OUTPUT
AS
SET NOCOUNT ON

DECLARE @Qry VARCHAR(8000), @Q VARCHAR(8000), @PosID VARCHAR(100)

SET @PosID = ISNULL(DBO.Fn_GetPreference('FBRPOSID'),'')
SET @Qry = ''

--910247
DECLARE C1 CURSOR FOR 
SELECT A
FROM 
(SELECT A='{"InvoiceNumber":"","POSID":"' + @PosID + '","USIN":"' + LTRIM(RTRIM(STR(SRInvCode))) + 
'","DateTime":"' + CONVERT(VARCHAR(100), DATE, 121) + 
'","BuyerNTN":"","BuyerCNIC":"","BuyerName":"","BuyerPhoneNumber":"","TotalBillAmount":"' + LTRIM(RTRIM(STR(InvTotal,12, 2))) + 
'","TotalQuantity":"' + LTRIM(RTRIM(STR(ISNULL((SELECT SUM(D.LooseQty + D.BonusQty) FROM SRDetail D WHERE D.SRInvCode = @SRInvCode),0)))) + '","TotalSaleValue":"' + LTRIM(RTRIM(STR(ISNULL(InvTotal, 0) - ISNULL(DBO.fn_getTaxOnSRInv(SRInvCode),0),12, 2))) + 
'","TotalTaxCharged":"' + LTRIM(RTRIM(STR(DBO.fn_getTaxOnSRInv(SRInvCode), 12,2))) + 
'","Discount":"' + LTRIM(RTRIM(STR(ISNULL((SELECT SUM(ROUND((D.LooseQty * D.SRPrice * (D.DiscPerc * 0.01)), 2)) FROM SRDetail D WHERE D.SRInvCode = @SRInvCode),0),12,2))) + '","FurtherTax":"0.0","PaymentMode":"1","RefUSIN":"' + LTRIM(RTRIM(ISNULL(STR(SaleInvCode),'null'))) + '","InvoiceType":"3","Items":['
FROM SRLedger 
WHERE SRInvCode=@SRInvCode
UNION ALL
SELECT A='{"ItemCode":"' + I.customICode + '","ItemName":"' + I.Name + '","Quantity":"' + LTRIM(RTRIM(STR(D.LooseQty + D.BonusQty, 10,4))) +
'","PCTCode":"' + P.Description + '","TaxRate":"' + LTRIM(RTRIM(STR(STS.TaxPerc, 6, 2))) + '","SaleValue":"' + LTRIM(RTRIM(STR(D.LooseQty * D.SRPrice, 12, 2))) + '","TotalAmount":"' + LTRIM(RTRIM(STR(D.LooseQty * D.SRPrice,12, 2))) + '","TaxCharged":"' + LTRIM(RTRIM(STR((D.LooseQty + D.BonusQty) * D.UnitSalesTax,12,2))) + '","Discount":"' + LTRIM(RTRIM(STR(ROUND((D.LooseQty * D.SRPrice * (D.DiscPerc * 0.01)), 2),12,2))) + '","FurtherTax":"0.0","InvoiceType":"3","RefUSIN":"'+ LTRIM(RTRIM(ISNULL(STR(S.SaleInvCode),'null'))) + '"},'
FROM SRLedger S, SRDetail D, Item I, PCT P, SalesTaxSchedule STS
WHERE S.SRInvCode=@SRInvCode AND D.SRInvCode=@SRInvCode AND S.SRInvCode=D.SRInvCode AND D.ICode=I.ICode AND I.PCTCode = P.PCTCode AND I.SalesTaxScheduleCode=STS.SalesTaxScheduleCode) T 

OPEN C1

FETCH NEXT FROM C1
INTO @Q

WHILE @@FETCH_STATUS = 0
BEGIN
	SET @Qry = @Qry + @Q
	FETCH NEXT FROM C1
	INTO @Q
END
SET @JSON = ''

IF Right(@Qry, 1) = ',' 
	SET @Qry = LEFT(@Qry, LEN(@Qry) - 1)

SET @JSON = @Qry + ']}'

Print @JSon

CLOSE C1
DEALLOCATE C1
RETURN 0
GO

-- sp_GetTabMaxKey (last defined by script catalog)
CREATE    Procedure dbo.sp_GetTabMaxKey @tabname As VarChar(32) , @key As Int Output As

Declare @Err As Int , @RowCount As Int
Set NoCount On
SELECT 	@key = TABMAXKEY
FROM	_TABMAXKEY WITH (UPDLOCK HOLDLOCK)
WHERE	_TABMAXKEY.TABName = @tabname
Select @err = @@Error , @rowcount = @@RowCount
IF @Err = 0 AND @rowcount > 0 
Begin
	Set @key = @key + 1
	UPDATE _tabmaxkey  
	SET 	 TABMAXKEY = @key
	WHERE  _TABMAXKEY.TABName = @tabname
	Select @err = @@Error , @rowcount = @@RowCount	
	IF @Err <> 0 OR @rowcount = 0 	
	Begin
		Set NoCount OFF
		RaisError('Exception occured in updating key for table %s' ,16, 1, @tabname)
		Return -1		
	End 
End
ELSE
Begin
	Set NoCount OFF
	RaisError('Exception occured in fetching key for table %s' ,16, 1, @tabname)
	Return -1
End 

Set NoCount OFF
Return 0
GO

-- SP_GetTransactionAmount (last defined by script catalog)
CREATE PROCEDURE DBO.SP_GetTransactionAmount @DocumentCode INT, @Amount NUMERIC(15,2) OUTPUT
AS
SET @Amount = ISNULL(
	(SELECT Amt=SUM(X.Amt)
	FROM
		(SELECT Amt=ISNULL(T.CashCharged, 0)
		FROM TransactionHeader T
		WHERE T.DocumentCode=@DocumentCode
		UNION ALL
		SELECT Amt=ISNULL(SUM(T.Amount), 0)
		FROM TransactionDetail T
		WHERE T.DocumentCode=@DocumentCode) X), 0)
GO

-- sp_GetTransactionCode (last defined by script catalog)
CREATE  Procedure dbo.sp_GetTransactionCode @TransactionTypeCode AS INT, @key As Int Output As

Declare @Err As Int , @RowCount As Int
Set NoCount On
SELECT 	@key = Counter
FROM	TransactionType WITH (UPDLOCK HOLDLOCK)
WHERE	TransactionTypeCode = @TransactionTypeCode
Select @err = @@Error , @rowcount = @@RowCount
IF @Err = 0 AND @rowcount > 0 
Begin
	Set @key = @key + 1
	UPDATE TransactionType
	SET 	 Counter = @key
	WHERE  TransactionTypeCode = @TransactionTypeCode
	Select @err = @@Error , @rowcount = @@RowCount	
	IF @Err <> 0 OR @rowcount = 0 	
	Begin
		Set NoCount OFF
		RaisError('Exception occured in updating counter for transaction type code %d' ,16, 1, @TransactionTypeCode)
		Return -1		
	End 
End
ELSE
Begin
	Set NoCount OFF
	RaisError('Exception occured in fetching counter for transaction type code %d' ,16, 1, @TransactionTypeCode)
	Return -1
End 

Set NoCount OFF
Return 0
GO

-- SP_GetVersionInfo (last defined by script catalog)
CREATE   PROCEDURE SP_GetVersionInfo
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20),
	@SequenceID INT OUTPUT,
	@AppVersion INT OUTPUT,
	@DBStatus INT OUTPUT
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DELETE REPORTDATA
DECLARE @qry VARCHAR(1000) 
SET @qry = 'INSERT INTO REPORTDATA (code1, code2, code3) SELECT * FROM ' + @SRV + '.' + @DB + '.' + @OWNER + '.Sequence'
EXECUTE (@qry)
SET @SequenceID = (SELECT Code1 FROM REPORTDATA)
SET @AppVersion = (SELECT Code2 FROM REPORTDATA)
SET @DBStatus = (SELECT Code3 FROM REPORTDATA)
GO

-- SP_GetVoucherCode (last defined by script catalog)
CREATE  PROCEDURE SP_GetVoucherCode @ai_VochCatCode int, @ai_Vouchercode int OUTPUT AS

Declare @Err As Int , @RowCount As Int
DECLARE @catname VARCHAR(100)
SET @catname = (select name from vochercategory where VochCatCode = @ai_VochCatCode)
IF @catname IS NULL
Begin
	Set NoCount OFF
	RaisError('Voucher category does not exists, wrong voucher category code passed' ,16, 1)
	Return -1		
End 

Set NoCount On

SELECT 	@ai_Vouchercode = Counter
FROM	dbo.VocherCategory WITH (UPDLOCK HOLDLOCK)
WHERE	VochCatCode = @ai_vochcatcode

Select @err = @@Error , @rowcount = @@RowCount
IF @Err = 0 AND @rowcount > 0 
Begin
	Set @ai_Vouchercode = @ai_Vouchercode + 1
	UPDATE dbo.VocherCategory  
	SET 	 Counter = @ai_Vouchercode
	WHERE  dbo.VocherCategory.VochCatCode = @ai_vochcatcode

	Select @err = @@Error , @rowcount = @@RowCount	

	IF @Err <> 0 OR @rowcount = 0 	
	Begin
		Set NoCount OFF
		RaisError('Exception occured in updating counter for voucher category %s' ,16, 1, @catname)
		Return -1		
	End 
End
ELSE
Begin
	Set NoCount OFF
	RaisError('Exception occured in fetching voucher code for voucher category %s' ,16, 1, @catname)
	Return -1
End 

Set NoCount OFF
Return 0
GO

