Set @query = @query + ' Select OldInvCode=QuotationCode,QuotationCode=-1,CustCode,SalesmanCode,date,DiscPerc,FlatDisc,MiscCharges,SalesTax,SPrice,ValidateUpTo,PostDate,Remarks,CustRefNo,headerno,OriginalDate,ModifiedBy,PostedBy,Posted,InvGSTPerc1,Remarks2,Remarks3,Remarks4,Remarks5,Remarks6,Remarks7,Remarks8,Remarks9,Pagesize,MessageCode,SManCode,LoosePack,ConsolidatedSaleOrder '
Set @query = @query + ' From ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'QuotationHeader '
Set @query = @query + ' Where QuotationCode Between ' + Cast(@sinvcode As VarChar(10)) + ' And ' + Cast(@linvcode As VarChar(10)) /*+ ' AND LTRIM(RTRIM(CAST(QuotationCode AS VARCHAR(10)))) NOT IN (SELECT LTRIM(RTRIM(SuppInvCode)) FROM QuotationHeader WHERE SuppInvCode IS NOT NULL) '*/
IF @CustCode > 0
BEGIN
	Set @query = @query + ' AND CustCode = ' + Cast(@CustCode As VarChar(10))
END
Set @query = @query + ' ORDER BY OldInvCode '
Execute(@query)
IF @@Error = 0 AND @@RowCount > 0 
Begin
	Set @query = 'Insert Into #Detail (OldInvCode,QuotationCode,ICode,Qty,PackUnits,SalePrice,DiscPerc,SalesTax,itemflatdisc,BonusQty,GSTPerc,UnitSalesTax,ItemDescription,gcode,RemoteNetSaleQty,RemoteStock,PORate,PODiscPerc,SpecialRate,RefNo) '
	Set @query = @query + 'Select OldInvCode=QuotationCode,QuotationCode=-1,ICode,Qty,PackUnits,SalePrice,DiscPerc,SalesTax,itemflatdisc,BonusQty,GSTPerc,UnitSalesTax,ItemDescription,gcode,RemoteNetSaleQty,RemoteStock,PORate,PODiscPerc,SpecialRate,RefNo '
	Set @query = @query + 'From ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'QuotationDetail '
	Set @query = @query + 'Where QuotationCode Between ' + Cast(@sinvcode As VarChar(10)) + ' And ' + Cast(@linvcode As VarChar(10))  /*+ ' AND LTRIM(RTRIM(CAST(QuotationCode AS VARCHAR(10)))) NOT IN (SELECT LTRIM(RTRIM(SuppInvCode)) FROM QuotationHeader WHERE SuppInvCode IS NOT NULL) '*/
	IF @CustCode > 0
	BEGIN
		Set @query = @query + ' AND QuotationCode IN (SELECT QuotationCode FROM QuotationHeader WHERE CustCode = ' + Cast(@CustCode As VarChar(10)) + ') '
	END
	Set @query = @query + ' ORDER BY OldInvCode, RowID '
	Execute(@query)
	IF @@Error <> 0 OR @@RowCount = 0 	
	Begin
		RaisError('Problem in inserting detail records From Remote DataBase',16,1)
		Return -1
	End
End
Else
Begin
	IF @@RowCount = 0 AND @@Error=0
	BEGIN
		Return 1
	END
	ELSE
	BEGIN
		RaisError('Problem in inserting header records From Remote DataBase',16,1)
		Return -1
	END
End

SET @RowCount = (SELECT COUNT(*) FROM #Header)
IF @linvcode >= @sinvcode AND @RowCount > 0
BEGIN
	SET @errcode = 0
	EXECUTE @errcode = SP_LockTabMaxkey 'Quotation' , @QuotationCode OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Fetching QuotationHeader Key Value', 16, 1)
		RETURN -1
	END
	UPDATE #Header SET QuotationCode = @QuotationCode + RowID
	UPDATE #Detail SET QuotationCode = H.QuotationCode FROM #Detail D, #Header H WHERE H.OldInvCode = D.OldInvCode

	INSERT INTO QuotationHeader (QuotationCode,CustCode,SalesmanCode,date,DiscPerc,FlatDisc,MiscCharges,SalesTax,SPrice,ValidateUpTo,PostDate,Remarks,CustRefNo,headerno,OriginalDate,ModifiedBy,PostedBy,Posted,InvGSTPerc1,Remarks2,Remarks3,Remarks4,Remarks5,Remarks6,Remarks7,Remarks8,Remarks9,Pagesize,MessageCode,SManCode,LoosePack,ConsolidatedSaleOrder)
	SELECT QuotationCode,CustCode,SalesmanCode,date,DiscPerc,FlatDisc,MiscCharges,SalesTax,SPrice,ValidateUpTo,PostDate,Remarks,CustRefNo,headerno,OriginalDate,ModifiedBy=NULL,PostedBy=NULL,Posted='N',InvGSTPerc1,Remarks2,Remarks3,Remarks4,Remarks5,Remarks6,Remarks7,Remarks8,Remarks9,Pagesize,MessageCode,SManCode,LoosePack,ConsolidatedSaleOrder
	FROM #Header
	ORDER BY OldInvCode

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in QuotationHeader', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	INSERT INTO QuotationDetail (QuotationCode,ICode,Qty,PackUnits,SalePrice,DiscPerc,SalesTax,itemflatdisc,BonusQty,GSTPerc,UnitSalesTax,ItemDescription,gcode,RemoteNetSaleQty,RemoteStock,PORate,PODiscPerc,SpecialRate,RefNo)
	SELECT QuotationCode,ICode,Qty,PackUnits,SalePrice,DiscPerc,SalesTax,itemflatdisc,BonusQty,GSTPerc,UnitSalesTax,ItemDescription,gcode,RemoteNetSaleQty,RemoteStock,PORate,PODiscPerc,SpecialRate,RefNo
	FROM #Detail

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in Quotation Detail', 16, 1)
		Rollback Transaction	
		RETURN -1
	END
	SET @end_invcode = ISNULL((SELECT Max(QuotationCode) FROM #Header),1)
	SET @errcode = 0
	EXECUTE @errcode = SP_UpdateTabMaxkey 'Quotation' , @end_invcode
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Updating QuotationHeader Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END
END
IF @@ERROR = 0 
BEGIN
	RETURN 0
END
ELSE
BEGIN
	RETURN -1
END
GO

-- sp_Import_ServiceSales_From_DataCarryDB (last defined by script catalog)
CREATE PROCEDURE sp_Import_ServiceSales_From_DataCarryDB 
	@SRV VARCHAR(50), @DB VARCHAR(50), @OWNER VARCHAR(20), @sinvcode INT, @linvcode INT, @CustCode SMALLINT, @UserCode SMALLINT
AS 
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON
DECLARE @query VARCHAR(2500), @Temp VARCHAR(100)
DECLARE @errcode INT, @ServiceInvCode INT, @end_invcode INT, @RowCount INT

SELECT OldInvCode=ServiceInvCode,ServiceInvcode=-1,CustCode,SalesmanCode,ServiceCatCode,Remarks,OriginalDate,ModifiedBy,Date,PostedBy,PostDate,HeaderNo,DiscPerc,FlatDisc,MiscCharges,SaleInvCode,Posted,DoctCode,RePrintingCounter,ServiceOCode,CashReceived,PatientCode,AdmissionCode,DueDate,FullPatientName,PatientAge,PatientSex,PatientRefBy,Ref1,Ref2,CashAccCode,CashTendered,CashCharged,CashBack,InvTotal,OutStandingAmt,TokenNo,GuestCode,GuestCheckInCode,StudentCode,Marked,ServiceInvTypeCode,MessageCode,ServiceInvGSTPerc
INTO #SHeader
FROM ServiceHeader
WHERE ServiceInvCode<0

SELECT OldInvCode=ServiceInvCode,ServiceInvcode=-1,ServiceCode,Price,DiscPerc,SmanCode,Qty,Commission,DeliveryDate,SampleTaken,ReportMade,CostPrice,Remarks,ServiceFlatDisc,ServiceGSTPerc,ServiceFlatTax,TransportRouteCode,VehicleCode
INTO #SDetail
FROM ServiceDetail
WHERE ServiceInvCode<0

SET @query = 'ALTER TABLE #SHeader ADD RowID INT NOT NULL IDENTITY(1,1)'
EXECUTE (@query)
IF @@Error <> 0
Begin
	RaisError('Problem in adding identity column in temporary table',16,1)
	Return -1
End

Set @query = 'Insert Into #SHeader (OldInvCode,ServiceInvCode,CustCode,SalesmanCode,ServiceCatCode,Remarks,OriginalDate,ModifiedBy,Date,PostedBy,PostDate,HeaderNo,DiscPerc,FlatDisc,MiscCharges,SaleInvCode,Posted,DoctCode,RePrintingCounter,ServiceOCode,CashReceived,PatientCode,AdmissionCode,DueDate,FullPatientName,PatientAge,PatientSex,PatientRefBy,Ref1,Ref2,CashAccCode,CashTendered,CashCharged,CashBack,InvTotal,OutStandingAmt,TokenNo,GuestCode,GuestCheckInCode,StudentCode,Marked,ServiceInvTypeCode,MessageCode,ServiceInvGSTPerc ) '
Set @query = @query + ' Select OldInvCode=ServiceInvCode,ServiceInvCode=-1,CustCode,SalesmanCode,ServiceCatCode,Remarks,OriginalDate,ModifiedBy,Date,PostedBy,PostDate,HeaderNo,DiscPerc,FlatDisc,MiscCharges,SaleInvCode,Posted,DoctCode,RePrintingCounter,ServiceOCode,CashReceived,PatientCode,AdmissionCode,DueDate,FullPatientName,PatientAge,PatientSex,PatientRefBy,Ref1,Ref2,CashAccCode,CashTendered,CashCharged,CashBack,InvTotal,OutStandingAmt,TokenNo,GuestCode,GuestCheckInCode,StudentCode,Marked,ServiceInvTypeCode,MessageCode,ServiceInvGSTPerc '
Set @query = @query + ' From ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'ServiceHeader '
Set @query = @query + ' Where ServiceInvCode Between ' + Cast(@sinvcode As VarChar(10)) + ' And ' + Cast(@linvcode As VarChar(10)) + ' AND LTRIM(RTRIM(CAST(ServiceInvCode AS VARCHAR(10)))) NOT IN (SELECT LTRIM(RTRIM(Ref2)) FROM ServiceHeader WHERE Ref2 IS NOT NULL) '
IF @custcode > 0
BEGIN
	Set @query = @query + ' AND CustCode = ' + Cast(@CustCode As VarChar(10))
END
Set @query = @query + ' ORDER BY OldInvCode '
Execute(@query)
IF @@Error = 0 AND @@RowCount > 0 
Begin
	Set @query = 'Insert Into #SDetail (OldInvCode,ServiceInvCode,ServiceCode,Price,DiscPerc,SmanCode,Qty,Commission,DeliveryDate,SampleTaken,ReportMade,CostPrice,Remarks,ServiceFlatDisc,ServiceGSTPerc,ServiceFlatTax,TransportRouteCode,VehicleCode) '
	Set @query = @query + 'Select OldInvCode=ServiceInvCode,ServiceInvCode=-1,ServiceCode,Price,DiscPerc,SmanCode,Qty,Commission,DeliveryDate,SampleTaken,ReportMade,CostPrice,Remarks,ServiceFlatDisc,ServiceGSTPerc,ServiceFlatTax,TransportRouteCode,VehicleCode '
	Set @query = @query + 'From ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'ServiceDetail '
	Set @query = @query + 'Where ServiceInvCode Between ' + Cast(@sinvcode As VarChar(10)) + ' And ' + Cast(@linvcode As VarChar(10)) + ' AND LTRIM(RTRIM(CAST(ServiceInvCode AS VARCHAR(10)))) NOT IN (SELECT LTRIM(RTRIM(Ref2)) FROM ServiceHeader WHERE Ref2 IS NOT NULL) '
	IF @custcode > 0
	BEGIN
		Set @query = @query + ' AND ServiceInvCode IN (SELECT ServiceInvCode FROM ServiceHeader WHERE CustCode = ' + Cast(@CustCode As VarChar(10)) + ') '
	END
	Set @query = @query + ' ORDER BY OldInvCode, SrvRowId '
	Execute(@query)
	IF @@Error <> 0 OR @@RowCount = 0 	
	Begin
		RaisError('Problem in inserting detail records From Remote DataBase',16,1)
		Return -1
	End
End
Else
Begin
	IF @@RowCount = 0 AND @@Error=0
	BEGIN
		Return 1
	END
	ELSE
	BEGIN
		RaisError('Problem in inserting header records From Remote DataBase',16,1)
		Return -1
	END
End

SET @RowCount = (SELECT COUNT(*) FROM #SHeader)
IF @linvcode >= @sinvcode AND @RowCount > 0
BEGIN
	SET @errcode = 0
	EXECUTE @errcode = SP_LockTabMaxkey 'ServiceHeader' , @ServiceInvCode OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Fetching ServiceHeader Key Value', 16, 1)
		RETURN -1
	END
	UPDATE #SHeader SET ServiceInvCode = @ServiceInvCode + RowID
	UPDATE #SDetail SET ServiceInvCode = H.ServiceInvcode FROM #SDetail D, #SHeader H WHERE H.OldInvCode = D.OldInvCode

	INSERT INTO ServiceHeader (ServiceInvCode,CustCode,SalesmanCode,ServiceCatCode,Remarks,OriginalDate,ModifiedBy,Date,PostedBy,PostDate,HeaderNo,DiscPerc,FlatDisc,MiscCharges,SaleInvCode,Posted,DoctCode,RePrintingCounter,ServiceOCode,CashReceived,PatientCode,AdmissionCode,DueDate,FullPatientName,PatientAge,PatientSex,PatientRefBy,Ref1,Ref2,CashAccCode,CashTendered,CashCharged,CashBack,InvTotal,OutStandingAmt,TokenNo,GuestCode,GuestCheckInCode,StudentCode,Marked,ServiceInvTypeCode,MessageCode,ServiceInvGSTPerc)
	SELECT ServiceInvCode,CustCode,SalesmanCode,ServiceCatCode,Remarks,OriginalDate,ModifiedBy,Date,PostedBy,PostDate,HeaderNo,DiscPerc,FlatDisc,MiscCharges,SaleInvCode=NULL,Posted,DoctCode,RePrintingCounter,ServiceOCode=NULL,CashReceived,PatientCode,AdmissionCode=NULL,DueDate,FullPatientName,PatientAge,PatientSex,PatientRefBy,Ref1,Ref2=OldInvCode,CashAccCode,CashTendered,CashCharged,CashBack,InvTotal,OutStandingAmt,TokenNo,GuestCode,GuestCheckInCode,StudentCode,Marked,ServiceInvTypeCode,MessageCode,ServiceInvGSTPerc
	FROM #SHeader
	ORDER BY OldInvCode

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceHeader', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	INSERT INTO ServiceDetail (ServiceInvCode,ServiceCode,Price,DiscPerc,SmanCode,Qty,Commission,DeliveryDate,SampleTaken,ReportMade,CostPrice,Remarks,ServiceFlatDisc,ServiceGSTPerc,ServiceFlatTax,TransportRouteCode,VehicleCode)
	SELECT ServiceInvCode,ServiceCode,Price,DiscPerc,SmanCode,Qty,Commission,DeliveryDate,SampleTaken,ReportMade,CostPrice,Remarks,ServiceFlatDisc,ServiceGSTPerc,ServiceFlatTax,TransportRouteCode,VehicleCode
	FROM #SDetail

	IF @@ERROR <> 0 OR @@ROWCOUNT = 0
	BEGIN
		RaisError('Problem while Inserting Record in ServiceDetail', 16, 1)
		Rollback Transaction	
		RETURN -1
	END
	SET @end_invcode = ISNULL((SELECT Max(ServiceInvCode) FROM #SHeader),1)
	SET @errcode = 0
	EXECUTE @errcode = SP_UpdateTabMaxkey 'ServiceHeader' , @end_invcode
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Updating ServiceHeader Key Value', 16, 1)
		Rollback Transaction
		RETURN -1
	END

	UPDATE ServiceHeader 
	SET InvTotal = ISNULL(DBO.fn_GetServiceInvTotal(ServiceInvCode), 0)
	WHERE ServiceInvCode IN (SELECT ServiceInvCode FROM #SHeader)

	UPDATE ServiceHeader SET OutStandingAmt = CASE WHEN CashCharged > InvTotal THEN 0 ELSE InvTotal - CashCharged END
	WHERE ServiceCatCode <> 10 AND ServiceInvCode IN (SELECT ServiceInvCode FROM #SHeader)
END
IF @@ERROR = 0 
BEGIN
	RETURN 0
END
ELSE
BEGIN
	RETURN -1
END
GO

-- SP_ImportData (last defined by script catalog)
CREATE PROCEDURE SP_ImportData 
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20) 
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

/* Variables to be used in import process */
DECLARE @TableName NVARCHAR(255), @Imp_TableName NVARCHAR(255), @full_table_name NVARCHAR(255)
DECLARE @SQL NVARCHAR(50), @Query VARCHAR(4000), @FROM VARCHAR(1000), @LastDate DATETIME
DECLARE @table_id INT, @err INT, @rt_code INT
DECLARE @dt DATETIME

SET @SQL = N'SELECT * INTO '
SET @FROM = N' FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.'

DECLARE TmpCrs1 CURSOR FOR
SELECT TABLENAME=LTRIM(RTRIM(TABLENAME)), IMP_TABLENAME = 'DBO.Import_' + LTRIM(RTRIM(TABLENAME))
FROM TransferableData 
WHERE Enable='Y' AND (AUTOINSERT = 'Y' OR AUTOUPDATE = 'Y' OR AUTODELETE = 'Y' OR UPDATETABMAXKEY = 'Y')
ORDER BY Priority

OPEN TmpCrs1

FETCH NEXT FROM TmpCrs1 INTO @TableName, @Imp_TableName
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @full_table_name = LTRIM(RTRIM(@owner)) + '.' + @TableName
	SET @table_id = OBJECT_ID(@full_table_name)
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0 OR @table_id IS NULL
	BEGIN
		RAISERROR('Import Basic Data Problem: Invalid Object Refered: Name = %s', 16, 1, @full_table_name)
		CLOSE TmpCrs1
		DEALLOCATE TmpCrs1
		RETURN -1
	END 

	IF LOWER(@TableName) = 'item'
	BEGIN
		SET @LastDate = ISNULL((SELECT MAX(LastUpdate) FROM Item), '01-01-1900 00:00:00')
		SET @Query = @SQL + @Imp_TableName + ' ' + @FROM + @TableName + ' AS T WHERE T.LastUpdate NOT IN (SELECT DISTINCT I.LASTUPDATE FROM Item I)'
	END
	ELSE
		SET @Query = @SQL + @Imp_TableName + ' ' + @FROM + @TableName
	EXECUTE (@Query)
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		RAISERROR('Import Basic Data Problem: Error Transfering Data From %s into %s ', 16, 1, @TableName, @Imp_TableName)
		CLOSE TmpCrs1
		DEALLOCATE TmpCrs1
		RETURN -1
	END 
	FETCH NEXT FROM TmpCrs1 INTO @TableName, @Imp_TableName
END
CLOSE TmpCrs1
DEALLOCATE TmpCrs1

SET @full_table_name = LTRIM(RTRIM(@owner)) + '.GodownDetail'
SET @table_id = OBJECT_ID(@full_table_name)
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0 OR @table_id IS NULL
BEGIN
	RAISERROR('Import Stock Data Problem: Invalid Object Refered: Name = %s', 16, 1, @full_table_name)
	RETURN -1
END 

SET @Imp_TableName = LTRIM(RTRIM(@owner)) + '.Import_GodownDetail'
SET @Query = @SQL + @Imp_TableName + ' ' + @FROM + 'GodownDetail'
EXECUTE (@Query)
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RAISERROR('Import Stock Data Problem: Error Transfering Data From %s into %s ', 16, 1, @TableName, @Imp_TableName)
	RETURN -1
END 

SET @dt = GETDATE()
Execute @rt_code = SP_Set_DateTime_Preference 'LastDataImport', @dt
IF @@Error <> 0 OR @rt_code <> 0 
Begin
	RaisError( 'Unable to Record Last Sale Import Information in Software Preferences' , 16 , 1)
	RETURN -1								
End

INSERT INTO DataImportLog (LogDate, ImportedBy, ImportType, Remarks)
VALUES (GetDate(), 1, 'Complete Data Import', 'Complete Data Import')

RETURN 0
GO

-- sp_ImportData_From_ParentServer (last defined by script catalog)
CREATE  PROCEDURE DBO.sp_ImportData_From_ParentServer
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20) 
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DECLARE @rt_code Int, @Err Int, @continue Int

BEGIN TRANSACTION T1

DECLARE @RC int
DECLARE @SequenceID int, @mySeq int
DECLARE @AppVersion int, @myVer int
DECLARE @DBStatus int, @dbstat int
SET @mySeq = ISNULL((SELECT SequenceID From Sequence), 0)
SET @myVer = ISNULL((SELECT Appversion From Sequence), 0)
SET @dbstat = ISNULL((SELECT DBStatus From Sequence), 0)

EXEC @RC = DBO.SP_GetVersionInfo @SRV, @DB, @OWNER, @SequenceID OUTPUT , @AppVersion OUTPUT , @DBStatus OUTPUT 
IF @@Error <> 0 OR @rt_code <>  0
BEGIN
	ROLLBACK TRANSACTION T1
END
ELSE
BEGIN
	IF @SequenceID <> @mySeq OR @AppVersion <> @myVer OR @DBStatus <> @dbstat
	BEGIN
		ROLLBACK TRANSACTION T1
	END
	ELSE
	BEGIN
		EXECUTE @rt_code = DBO.SP_DropImportTables
		IF @@Error <> 0 OR @rt_code <>  0
		BEGIN
			ROLLBACK TRANSACTION T1
		END
		ELSE
		BEGIN
			COMMIT TRANSACTION T1
		
			BEGIN TRANSACTION T2
			EXECUTE @rt_code = DBO.SP_ImportData @SRV, @DB, @OWNER
			IF @@Error <> 0 OR @rt_code <>  0
			BEGIN
				ROLLBACK TRANSACTION T2
			END
			ELSE
			BEGIN
				COMMIT TRANSACTION T2
			END
		END
	END
END
RETURN 0
GO

-- sp_ImportSales (last defined by script catalog)
CREATE   PROCEDURE DBO.sp_ImportSales
	@SRV VARCHAR(255), 
	@DB VARCHAR(255), 
	@OWNER VARCHAR(255), 
	@StartDate DateTime, 
	@EndDate DateTime, 
	@TemplateCode Int Output 
As

/*SET environment*/
SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON
SET XACT_ABORT ON

/*Declare Variables*/
DECLARE @TableQualifier NVARCHAR(4000), @SQLDETAIL NVARCHAR(4000)
DECLARE @HeaderCode INT, @errcode INT
/*
Prepare TableQualifier Variable from passed parameters
*/
SET @TableQualifier = LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner))

/*
Get Primary Key value for fresh datatransfer log instance
*/
EXECUTE @errcode = SP_GetTabMaxkey 'SaleTemplateHeader' , @TemplateCode Output
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in generating sale template', 16, 1)
	RETURN -1
END

INSERT INTO SaleTemplateHeader (SaleTemplateCode, Date, Modified, Name, HeaderNo)
SELECT @TemplateCode, Date=GetDate(), Modified=GETDATE(), Name = 'FROM ' + LTRIM(RTRIM(CAST(@StartDate AS VARCHAR(100)))) + ' TO ' + LTRIM(RTRIM(CAST(@EndDate AS VARCHAR(100)))) + ' (' + LTRIM(RTRIM(STR(@TemplateCode))) +  ')', HeaderNo=1
IF @@ERROR <> 0
BEGIN
	RaisError('Problem in generating sale template header', 16, 1)
	RETURN -1
END

SET @errcode = 0

SET @SQLDETAIL = 'INSERT INTO DBO.SaleTemplateDetail (SaleTemplateCode, Icode, LooseQty, PackQty, SalePrice, DiscPerc, ItemFlatDisc, UnitSalesTax, GSTPerc, PackUnits, Remarks, BonusQty, SaleInvCode, SaleDate, CustCode, SaleCatCode, Marked) SELECT Template=' + LTRIM(RTRIM(STR(@TemplateCode))) + ' , D.ICode, LooseQty=SUM(D.LooseQty), PackQty=0, D.SalePrice, D.DiscPerc, D.ItemFlatDisc, D.UnitSalesTax, D.GstPerc, D.PackUnits, Remarks=S.Remarks, BonusQty = SUM(D.BonusQty), SaleInvCode=S.SaleInvCode, SaleDate=S.Date, CustCode=S.CustCode, S.SaleCatCode, Marked=''Y'' FROM ' + @TableQualifier + '.SaleLedger S, ' + @TableQualifier + '.SaleDetail D, ' + @TableQualifier + '.Item I WHERE S.SaleInvCode = D.SaleInvCode AND S.Date BETWEEN ''' + LTRIM(RTRIM(CAST(@StartDate AS VARCHAR(100)))) + ''' AND ''' + LTRIM(RTRIM(CAST(@EndDate AS VARCHAR(100)))) + ''' AND D.ICode = I.ICode GROUP BY I.Name, S.SaleInvCode, S.Date, S.CustCode, S.SaleCatCode, S.Remarks, D.ICode, D.SalePrice, D.DiscPerc, D.ItemFlatDisc, D.UnitSalesTax, D.GstPerc, D.PackUnits ORDER BY S.SaleInvCode, D.ICode'
EXECUTE(@SQLDETAIL)
IF @@ERROR = 0 AND @errcode = 0
	RETURN 0
ELSE
	RaisError('Unable To successfully generate sale template detail', 16, 1)
	RETURN -1
GO

-- sp_ImportStock_From_ParentServer (last defined by script catalog)
CREATE PROCEDURE DBO.sp_ImportStock_From_ParentServer
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20),
	@UserCode SMALLINT
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DECLARE @Query VARCHAR(4000), @FROM VARCHAR(1000)
DECLARE @rt_code Int, @Err Int, @continue Int
DECLARE @RC int
DECLARE @SequenceID int, @mySeq int
DECLARE @AppVersion int, @myVer int
DECLARE @DBStatus int, @dbstat int
SET @mySeq = ISNULL((SELECT SequenceID From Sequence), 0)
SET @myVer = ISNULL((SELECT Appversion From Sequence), 0)
SET @dbstat = ISNULL((SELECT DBStatus From Sequence), 0)

BEGIN TRANSACTION T1

EXEC @RC = DBO.SP_GetVersionInfo @SRV, @DB, @OWNER, @SequenceID OUTPUT , @AppVersion OUTPUT , @DBStatus OUTPUT 
IF @@Error <> 0 OR @rt_code <>  0
BEGIN
	ROLLBACK TRANSACTION T1
	RAISERROR('Import Stock Problem: Failure in Version Fetching', 16, 1)
	RETURN -1
END
ELSE
BEGIN
	IF @SequenceID <> @mySeq OR @AppVersion <> @myVer OR @DBStatus <> @dbstat
	BEGIN
		ROLLBACK TRANSACTION T1
		RAISERROR('Import Stock Problem: Version Conflict Exist between the two databases', 16, 1)
		RETURN -1
	END
	ELSE
	BEGIN

		SET @Query = N'TRUNCATE TABLE GodownDetail'
		EXECUTE (@Query)
		IF @@Error <> 0 
		BEGIN
			ROLLBACK TRANSACTION T1
			RAISERROR('Stock Truncation Problem', 16, 1)
			RETURN -1
		END
		SET @Query = N'INSERT INTO GodownDetail SELECT T.* FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.GodownDetail T WHERE T.ICode IN (SELECT ICode FROM Item)'
		EXECUTE (@Query)
		IF @@Error <> 0 
		BEGIN
			ROLLBACK TRANSACTION T1
			RAISERROR('Stock Import Error', 16, 1)
			RETURN -1
		END
		ELSE
		BEGIN
			INSERT INTO DataImportLog (LogDate, ImportedBy, ImportType, Remarks)
			VALUES (GetDate(), @UserCode, 'Stock Position Only', 'Stock Position Updated via Job')
		END
	END
END
COMMIT TRANSACTION T1
RETURN 0
GO

-- sp_IncomeStatement (last defined by script catalog)
CREATE   PROCEDURE sp_IncomeStatement @ad_SDate DateTime, @ad_EDate DateTime, @ac_level Char(1) AS
SET NOCOUNT ON
DECLARE @ln_purchaseacc NUMERIC(5, 0), @ln_cashacc NUMERIC(5, 0), @ln_equityacc NUMERIC(5, 0),
	@ln_salesacc NUMERIC(5, 0), @ln_salesretacc NUMERIC(5, 0), @ln_purchaseretacc NUMERIC(5, 0),
	@ln_revfromservice NUMERIC(5, 0), @ln_temp NUMERIC(20, 5), @ln_RevenueFromSalesCat NUMERIC(5, 0),
	@ln_DirectExpensesCat NUMERIC(5, 0), @ln_OperatingExpensesCat NUMERIC(5, 0), @ln_OtherExpensesCat NUMERIC(5, 0),
	@ln_OtherRevenuesCat NUMERIC(5, 0), @ln_invacc NUMERIC(5, 0), @ln_cgs NUMERIC(5, 0)
DECLARE @InvSys CHAR(1)

SET @InvSys = ISNULL((SELECT a=DBO.Fn_GetPreference( 'InventorySystemUsed')), 'P')
SET @ln_invacc = (SELECT code FROM global WHERE name = 'GT_InventoryAcc')
SET @ln_cgs = (SELECT code FROM global WHERE name = 'GT_CostOfGoodsSoldAcc')
SET @ln_purchaseacc = (SELECT code FROM global WHERE name = 'GT_PurchaseAccount')
SET @ln_cashacc = (SELECT code FROM global WHERE name = 'GT_CashACC')
SET @ln_equityacc = (SELECT code FROM global WHERE name = 'GT_EquityACC')
SET @ln_salesacc = (SELECT code FROM global WHERE name = 'GT_SalesACC')
SET @ln_salesretacc = (SELECT code FROM global WHERE name = 'GT_SalesReturnACC')
SET @ln_purchaseretacc = (SELECT code FROM global WHERE name = 'GT_PurchaseReturnsAccount')
SET @ln_revfromservice  = (SELECT code FROM global WHERE name = 'GT_RevenueFromServices')
SET @ln_OtherRevenuesCat= (SELECT code FROM global WHERE name = 'GT_OtherRevenuesCat')
SET @ln_RevenueFromSalesCat=(SELECT code FROM global WHERE name = 'GT_RevenueFromSalesCat')
SET @ln_DirectExpensesCat= (SELECT code FROM global WHERE name = 'GT_DirectExpensesCat')
SET @ln_OperatingExpensesCat=(SELECT code FROM global WHERE name = 'GT_OperatingExpensesCat')
SET @ln_OtherExpensesCat=(SELECT code FROM global WHERE name = 'GT_OtherExpensesCat')
SET @ln_OtherRevenuesCat=(SELECT code FROM global WHERE name = 'GT_OtherRevenuesCat')

DELETE reportdata

BEGIN TRANSACTION

insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=1,
	code3=0,
	name1= (SELECT name 
		from categoryaccounts 
		where catacccode = @ln_RevenueFromSalesCat),
	name2='',
	value1= isnull(sum(isnull(v.debit, 0) - isnull(v.credit, 0)), 0),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level
from virtualgl v
where   v.acccode in (select acccode from accounts where subcode in 
		(SELECT subacccode 
		from subaccounts 
		where catacccode = @ln_RevenueFromSalesCat)) and
	v.date >= @ad_SDate and v.date <= @ad_EDate

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=1)

insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=2,
	code3=0,
	name1= 'COST OF SALES',
	name2='',
	value1=(select isnull(sum(isnull(v.debit, 0) - isnull(v.credit,0)), 0) from virtualgl v
		where  	v.acccode in (select acccode from accounts where subcode in 
					(SELECT subacccode 
					from subaccounts 
					where catacccode = @ln_DirectExpensesCat)) and
			v.date >= @ad_SDate and v.date <= @ad_EDate) + 
		(select Round(isnull(sum(isnull(newavgprice*newstock, 0)), 0),0)
		from stockledger
		where 	date < @ad_SDate AND
			convert(varchar(10), icode) + ' ' + convert(varchar(20), utn) IN
			(select convert(varchar(10), icode) + ' ' + convert(varchar(20), max(utn))
		from stockledger
		where @InvSys = 'P' AND date < @ad_SDate
		group by icode)) - 
		(select Round(isnull(sum(isnull(newavgprice*newstock, 0)), 0),0)
		from stockledger
		where 	date <= @ad_EDate AND
			convert(varchar(10), icode) + ' ' + convert(varchar(20), utn) IN
			(select convert(varchar(10), icode) + ' ' + convert(varchar(20), max(utn))
		from stockledger
		where @InvSys = 'P' AND date <= @ad_EDate
		group by icode)), 
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=2)

insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=3,
	code3=0,
	name1= 'GROSS PROFIT/LOSS',
	name2='',
	value1=(select isnull(sum(isnull(value1, 0)), 0) from reportdata),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=3)

insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=4,
	code3=0,
	name1= (SELECT name 
		from categoryaccounts 
		where catacccode = @ln_OperatingExpensesCat),
	name2='',
	value1=isnull(sum(v.debit - v.credit), 0),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level
from virtualgl v
where   v.acccode in (select acccode from accounts where subcode in 
		(SELECT subacccode 
		from subaccounts 
		where catacccode = @ln_OperatingExpensesCat)) and
	v.date >= @ad_SDate and v.date <= @ad_EDate

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=4)

IF @ln_temp <> 0
BEGIN
insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=5,
	code3=0,
	name1= 'OPERATING PROFIT/LOSS',
	name2='',
	value1= (select sum(isnull(value1, 0)) from reportdata where code2 in (3,4)),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level
END

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=5)

insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=6,
	code3=0,
	name1= (SELECT name 
		from categoryaccounts 
		where catacccode = @ln_OtherExpensesCat),
	name2='',
	value1=isnull(sum(v.debit - v.credit), 0),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level
from virtualgl v
where   v.acccode in (select acccode from accounts where subcode in 
		(SELECT subacccode 
		from subaccounts 
		where catacccode = @ln_OtherExpensesCat)) and
	v.date >= @ad_SDate and v.date <= @ad_EDate

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=6)

IF @ln_temp <> 0
BEGIN
insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=7,
	code3=0,
	name1= 'PROFIT/LOSS AFTER ' + (SELECT RTRIM(LTRIM(NAME)) FROM categoryaccounts 
					where catacccode = @ln_OtherExpensesCat),
	name2='',
	value1= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2 in ((select max(code2) from reportdata where code2 in (3, 5)),6)),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level
END

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=7)

insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=8,
	code3=0,
	name1= (SELECT name 
		from categoryaccounts 
		where catacccode = @ln_OtherRevenuesCat),
	name2='',
	value1= isnull(sum(v.debit - v.credit), 0),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level
from virtualgl v
where   v.acccode in (select acccode from accounts where subcode in 
		(SELECT subacccode 
		from subaccounts 
		where catacccode = @ln_OtherRevenuesCat)) and
	v.date >= @ad_SDate and v.date <= @ad_EDate

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=8)

IF @ln_temp <> 0
BEGIN
insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=9,
	code3=0,
	name1= 'NET INCOME/LOSS',
	name2='',
	value1= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2 in ((select max(code2) from reportdata where code2 in (3, 5, 7)),8)),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level
END

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=9)

insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=10,
	code3=0,
	name1= (SELECT name 
		from categoryaccounts 
		where catacccode = c.catacccode),
	name2='',
	value1=isnull(sum(v.debit - v.credit), 0),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level
from virtualgl v, categoryaccounts c, subaccounts s, accounts a
where   v.acccode in (select acccode from accounts where subcode in 
		(SELECT subacccode 
		from subaccounts 
		where catacccode in 
			(SELECT catacccode 
			from categoryaccounts 
			where mainacccode in (4, 5) and catacccode not in 
				(@ln_RevenueFromSalesCat, @ln_DirectExpensesCat, 
				 @ln_OperatingExpensesCat, @ln_OtherExpensesCat, 
				 @ln_OtherRevenuesCat)))) and
	v.date >= @ad_SDate and v.date <= @ad_EDate and
	v.acccode = a.acccode and a.subcode=s.subacccode and s.catacccode = c.catacccode
GROUP BY c.catacccode

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=10)

IF @ln_temp <> 0
BEGIN
insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
select	code1=-1,
	code2=11,
	code3=0,
	name1= 'NET INCOME/LOSS FOR THE PERIOD',
	name2='',
	value1= (select isnull(sum(isnull(value1, 0)), 0) 
		from reportdata 
		where code2 in ((select max(code2) from reportdata where code2 in (3, 5, 7, 9)), 10)),
	value2=0,
	value3=0,
	value4=0,
	date1 =@ad_SDate,
	date2 =@ad_EDate,
	value5=@ac_level
END

IF @@ROWCOUNT <> 0
	set @ln_temp= (select isnull(sum(isnull(value1, 0)), 0) from reportdata where code2=11)

UPDATE REPORTDATA SET Value1 = 0 WHERE VALUE1 is NULL

IF @ac_level <> '0'
BEGIN
	set @ln_temp= (select isnull(code2, 0) from reportdata where code2=1)
	IF @ln_temp <> 0
	BEGIN
		insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
		select	code1=1,
			code2=(select max(code2)+1 from reportdata),
			code3=ac.acccode,
			name1= ac.name,
			name2=(select distinct name1 from reportdata where code2=1),
			value1=a.balance,
			value2=0,
			value3=0,
			value4=1,
			date1 =@ad_SDate,
			date2 =@ad_EDate,
			value5=@ac_level
		from 
		(select acccode, isnull(sum(debit-credit), 0) as balance
		from virtualgl where acccode in 
			(select acccode from accounts where subcode in 
				(SELECT subacccode 
				from subaccounts 
				where catacccode = @ln_RevenueFromSalesCat)) and
			date >= @ad_SDate and date <= @ad_EDate
		group by acccode) a, accounts ac
		where a.acccode=ac.acccode
	END

	set @ln_temp= (select isnull(code2, 0) from reportdata where code2=2)
	IF @ln_temp <> 0
	BEGIN
		IF @InvSys = 'P'
		BEGIN
			insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
			select	code1=2,
				code2=(select max(code2)+1 from reportdata),
				code3=-2,
				name1= 'OPENING STOCK/INVENTORY ',
				name2=(select distinct name1 from reportdata where code2=2),
				value1=	(select Round(isnull(sum(isnull(newavgprice*newstock, 0)),0),0)
					from stockledger
					where 	date < @ad_SDate AND
						convert(varchar(10), icode) + ' ' + convert(varchar(20), utn) IN
						(select convert(varchar(10), icode) + ' ' + convert(varchar(20), max(utn))
						from stockledger
						where date < @ad_SDate
						group by icode)),
				value2=0,
				value3=0,
				value4=1,
				date1 =@ad_SDate,
				date2 =@ad_EDate,
				value5=@ac_level
		END

		insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
		select	code1=2,
			code2=(select max(code2)+1 from reportdata),
			code3=ac.acccode,
			name1= ac.name,
			name2=(select distinct name1 from reportdata where code2=2),
			value1=isnull(a.balance, 0),
			value2=0,
			value3=0,
			value4=1,
			date1 =@ad_SDate,
			date2 =@ad_EDate,
			value5=@ac_level
		from 
		(select acccode, sum(isnull(debit, 0)-isnull(credit, 0)) as balance
		from virtualgl where acccode in 
			(select acccode from accounts where subcode in 
				(SELECT subacccode 
				from subaccounts 
				where catacccode = @ln_DirectExpensesCat)) and
			date >= @ad_SDate and date <= @ad_EDate
		group by acccode) a, accounts ac
		where a.acccode=ac.acccode
	
		IF @InvSys = 'P'
		BEGIN
			insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
			select	code1=2,
				code2=(select max(code2)+1 from reportdata),
				code3=-1,
				name1= 'CLOSING STOCK/INVENTORY ',
				name2=(select distinct name1 from reportdata where code2=2),
				value1=	(select Round(isnull(sum(-isnull(newavgprice*newstock, 0)), 0), 0)
					from stockledger
					where 	date <= @ad_EDate AND
						convert(varchar(10), icode) + ' ' + convert(varchar(20), utn) IN
					(select convert(varchar(10), icode) + ' ' + convert(varchar(20), max(utn))
						from stockledger
						where date <= @ad_EDate
						group by icode)),
				value2=0,
				value3=0,
				value4=1,
				date1 =@ad_SDate,
				date2 =@ad_EDate,
				value5=@ac_level
		END
	END

	set @ln_temp= (select isnull(code2, 0) from reportdata where code2=4)
	IF @ln_temp <> 0
	BEGIN
		insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
		select	code1=4,
			code2=(select max(code2)+1 from reportdata),
			code3=acccode,
			name1= name,
			name2=(select distinct name1 from reportdata where code2=4),
			value1=isnull(balance, 0),
			value2=0,
			value3=0,
			value4=1,
			date1 =@ad_SDate,
			date2 =@ad_EDate,
			value5=@ac_level
		from
		(select a.acccode, a.name, sum(isnull(v.debit, 0)-isnull(v.credit, 0)) as balance
		from virtualgl v, accounts a
		where v.acccode in 
			(select acccode from accounts where subcode in 
				(select subacccode from subaccounts where catacccode in 
					(SELECT catacccode 
					from categoryaccounts 
					where catacccode = @ln_OperatingExpensesCat))) and
			v.acccode = a.acccode and 
			v.date >= @ad_SDate and v.date <= @ad_EDate
		group by a.acccode, a.name) a
	END

	set @ln_temp= (select isnull(code2, 0) from reportdata where code2=6)
	IF @ln_temp <> 0
	BEGIN
		insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
		select	code1=6,
			code2=(select max(code2)+1 from reportdata),
			code3=acccode,
			name1= name,
			name2=(select distinct name1 from reportdata where code2=6),
			value1=isnull(balance, 0),
			value2=0,
			value3=0,
			value4=1,
			date1 =@ad_SDate,
			date2 =@ad_EDate,
			value5=@ac_level
		from
		(select a.acccode, a.name, sum(isnull(v.debit, 0)-isnull(v.credit, 0)) as balance
		from virtualgl v, accounts a
		where v.acccode in 
			(select acccode from accounts where subcode in 
				(select subacccode from subaccounts where catacccode in 
					(SELECT catacccode 
					from categoryaccounts 
					where catacccode = @ln_OtherExpensesCat))) and
			v.acccode = a.acccode and 
			v.date >= @ad_SDate and v.date <= @ad_EDate
		group by a.acccode, a.name) a
	END

	set @ln_temp= (select isnull(code2, 0) from reportdata where code2=8)
	IF @ln_temp <> 0
	BEGIN
		insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
		select	code1=8,
			code2=(select max(code2)+1 from reportdata),
			code3=acccode,
			name1= name,
			name2=(select distinct name1 from reportdata where code2=8),
			value1=isnull(balance, 0),
			value2=0,
			value3=0,
			value4=1,
			date1 =@ad_SDate,
			date2 =@ad_EDate,
			value5=@ac_level
		from
		(select a.acccode, a.name, sum(isnull(v.debit, 0)-isnull(v.credit, 0)) as balance
		from virtualgl v, accounts a
		where v.acccode in 
			(select acccode from accounts where subcode in 
				(select subacccode from subaccounts where catacccode in 
					(SELECT catacccode
					from categoryaccounts 
					where catacccode = @ln_OtherRevenuesCat))) and
			v.acccode = a.acccode and 
			v.date >= @ad_SDate and v.date <= @ad_EDate
		group by a.acccode, a.name) a
	END

	insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
	select	code1=10+catacccode,
		code2=catacccode,
		code3=acccode,
		name1= name,
		name2= catname,
		value1=isnull(balance, 0),
		value2=0,
		value3=0,
		value4=1,
		date1 =@ad_SDate,
		date2 =@ad_EDate,
		value5=@ac_level
	from
	(select a.acccode, a.name, c.catacccode, catname=c.name, sum(isnull(v.debit, 0)-isnull(v.credit, 0)) as balance
	from virtualgl v, accounts a, subaccounts s, categoryaccounts c
	where v.acccode in 
		(select acccode from accounts where subcode in 
			(select subacccode from subaccounts where catacccode in 
				(SELECT catacccode 
				from categoryaccounts 
				where mainacccode in (4, 5) and catacccode not in 
					(@ln_RevenueFromSalesCat, @ln_DirectExpensesCat, 
					 @ln_OperatingExpensesCat, @ln_OtherExpensesCat, 
					 @ln_OtherRevenuesCat)))) and
		v.acccode = a.acccode and 
		v.date >= @ad_SDate and v.date <= @ad_EDate and
		a.subcode = s.subacccode and
		s.catacccode = c.catacccode
	group by a.acccode, a.name, c.name, c.catacccode) a
END

UPDATE REPORTDATA SET Value1 = 0 WHERE VALUE1 is NULL

IF @ac_level = '2' OR @ac_level = '3'
BEGIN
	insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
	select	code1=(select max(code1)+1 from reportdata),
		code2=catcode,
		code3=acccode,
		name1=(select name from salecategory where salecatcode = s.catcode),
		name2=(select distinct name1 from reportdata where code3=@ln_salesacc),
		value1= isnull(balance, 0),
		value2=0,
		value3=0,
		value4=2,
		date1 =@ad_SDate,
		date2 =@ad_EDate,
		value5=@ac_level
	from 
	(select	acccode, 
		catcode,
		sum(debit - credit) as balance
	from virtualgl v
	where   acccode in (@ln_salesacc) and
		date >= @ad_SDate and date <= @ad_EDate
	group by v.acccode,v.catcode) S

	insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
	select	code1=(select max(code1)+1 from reportdata),
		code2=catcode,
		code3=acccode,
		name1=(select name from salecategory where salecatcode = sr.catcode),
		name2=(select distinct name1 from reportdata where code3=@ln_salesretacc),
		value1= isnull(balance, 0),
		value2=0,
		value3=0,
		value4=2,
		date1 =@ad_SDate,
		date2 =@ad_EDate,
		value5=@ac_level
	from 
	(select	acccode, 
		catcode,
		sum(debit - credit) as balance
	from virtualgl v
	where   acccode in (@ln_salesretacc) and
		date >= @ad_SDate and date <= @ad_EDate
	group by v.acccode,v.catcode) SR

	insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
	select	code1=(select max(code1)+1 from reportdata),
		code2=catcode,
		code3=acccode,
		name1=(select name from purcategory where purcatcode = p.catcode),
		name2=(select distinct name1 from reportdata where code3=@ln_purchaseacc),
		value1= isnull(balance, 0),
		value2=0,
		value3=0,
		value4=2,
		date1 =@ad_SDate,
		date2 =@ad_EDate,
		value5=@ac_level
	from 
	(select	acccode, 
		catcode,
		sum(debit - credit) as balance
	from virtualgl v
	where   acccode in (@ln_purchaseacc) and
		date >= @ad_SDate and date <= @ad_EDate
	group by v.acccode,v.catcode) P

	insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
	select	code1=(select max(code1)+1 from reportdata),
		code2=catcode,
		code3=acccode,
		name1=(select name from purcategory where purcatcode = p.catcode),
		name2=(select distinct name1 from reportdata where code3=@ln_purchaseretacc),
		value1= isnull(balance, 0),
		value2=0,
		value3=0,
		value4=2,
		date1 =@ad_SDate,
		date2 =@ad_EDate,
		value5=@ac_level
	from 
	(select	acccode, 
		catcode,
		sum(debit - credit) as balance
	from virtualgl v
	where   acccode in (@ln_purchaseretacc) and
		date >= @ad_SDate and date <= @ad_EDate
	group by v.acccode,v.catcode) P

	insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
	select	code1=(select max(code1)+1 from reportdata),
		code2=catcode,
		code3=a.acccode,
		name1=(select name from salecategory where salecatcode = s.catcode),
		name2=(select distinct name1 from reportdata where code3=@ln_revfromservice),
		value1= isnull(balance, 0),
		value2=0,
		value3=0,
		value4=2,
		date1 =@ad_SDate,
		date2 =@ad_EDate,
		value5=@ac_level
	from 
	(select	acccode, 
		catcode,
		sum(debit - credit) as balance
	from virtualgl v
	where   acccode in (@ln_revfromservice) and
		date >= @ad_SDate and date <= @ad_EDate
	group by v.acccode,v.catcode) S, Accounts a
	where S.acccode = a.acccode
END

IF @ac_level = '3'
BEGIN
	set @ln_temp= (select isnull(code2, 0) from reportdata where code3=-2)
	IF @ln_temp <> 0 AND @InvSys = 'P'
	BEGIN
		insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
		select	code1=(select max(code1)+1 from reportdata),
			code2=0,
			code3=item.icode,
			name1= item.name,
			name2=(select distinct name1 from reportdata where code3=-2),
			value1=	stockval,
			value2= newstock,
			value3= newavgprice,
			value4=3,
			date1 =@ad_SDate,
			date2 =@ad_EDate,
			value5=@ac_level
		FROM
		(select icode, newstock, newavgprice, -isnull(newavgprice*newstock, 0) stockval
			from stockledger
			where 	date < @ad_SDate AND
				convert(varchar(10), icode) + ' ' + convert(varchar(20), utn) IN
				(select convert(varchar(10), icode) + ' ' + convert(varchar(20), max(utn))
				from stockledger
				where date < @ad_SDate
				group by icode) and newstock > 0) OS, item
		where OS.icode = item.icode
		order by item.name
	END

	set @ln_temp= (select isnull(code2, 0) from reportdata where code3=-1)
	IF @ln_temp <> 0 AND @InvSys = 'P'
	BEGIN
		insert into reportdata (code1, code2, code3, name1, name2, value1, value2, value3, value4, date1, date2, value5)
		select	code1=(select max(code1)+1 from reportdata),
			code2=0,
			code3=item.icode,
			name1= item.name,
			name2=(select distinct name1 from reportdata where code3=-1),
			value1=	stockval,
			value2= newstock,
			value3= newavgprice,
			value4=3,
			date1 =@ad_SDate,
			date2 =@ad_EDate,
			value5=@ac_level
		FROM
			(select icode, newstock, newavgprice, -isnull(newavgprice*newstock, 0) stockval
			from stockledger
			where 	date <= @ad_EDate AND
				convert(varchar(10), icode) + ' ' + convert(varchar(20), utn) IN
				(select convert(varchar(10), icode) + ' ' + convert(varchar(20), max(utn))
				from stockledger
				where date <= @ad_EDate
				group by icode) and newstock > 0) CS, item
		where CS.icode = item.icode
		order by item.name
	END
END

UPDATE REPORTDATA SET Value1 = 0 WHERE VALUE1 is NULL

UPDATE REPORTDATA SET Value2 = 0 WHERE VALUE2 is NULL

COMMIT
GO

-- sp_IncomeStatment (last defined by script catalog)

/****** Object:  Stored Procedure dbo.sp_IncomeStatment    Script Date: 4/23/02 4:29:59 PM ******/
/****** Object:  Stored Procedure dbo.sp_IncomeStatment    Script Date: 4/8/02 6:26:06 PM ******/
/****** Object:  Stored Procedure dbo.sp_IncomeStatment    Script Date: 3/6/02 3:39:37 PM ******/
/****** Object:  Stored Procedure dbo.sp_IncomeStatment    Script Date: 7/20/01 6:52:01 PM ******/
CREATE PROCEDURE sp_IncomeStatment @ad_SDate DateTime, @ad_EDate DateTime AS

/* Declaration of local Variables to be used in the script later */

declare @ln_cashacc numeric(5, 0)
declare @ln_equityacc numeric(5, 0)
declare @ln_freightacc numeric(5, 0)
declare @ln_octroiacc numeric(5, 0)
declare @ln_salestaxacc numeric(5, 0)
declare @ln_inventoryacc numeric(5, 0)
declare @ln_favourableacc numeric(5, 0)
declare @ln_unfavourableacc numeric(5, 0)
declare @ln_avgpurcostacc numeric(5, 0)
declare @ln_salesacc numeric(5, 0)
declare @ln_salesfixdiscacc numeric(5, 0)
declare @ln_miscchargesacc numeric(5, 0)
declare @ln_salesretacc numeric(5, 0)
declare @ln_purchaseacc numeric(5, 0)
declare @ln_revfromservices numeric(5, 0)

select @ln_cashacc      = (Select code from global where name = 'GT_CashACC')
select @ln_equityacc	= (Select code from global where name = 'GT_EquityACC')
select @ln_freightacc	= (Select code from global where name = 'GT_FreightACC')
select @ln_octroiacc	= (Select code from global where name = 'GT_OctroiACC')
select @ln_salestaxacc	= (Select code from global where name = 'GT_AdvanceSalesTaxACC')
select @ln_inventoryacc	= (Select code from global where name = 'GT_InventoryACC')
select @ln_favourableacc= (Select code from global where name = 'GT_FavourableACC')
select @ln_unfavourableacc = (Select code from global where name = 'GT_UnFavourableACC')
/*select @ln_avgpurcostacc = (Select code from global where name = 'GT_AvgPurCostACC'*/
select @ln_salesacc        = (Select code from global where name = 'GT_SalesACC')
select @ln_salesfixdiscacc = (Select code from global where name = 'GT_SalesFixDiscountACC')
select @ln_miscchargesacc  = (Select code from global where name = 'GT_MiscChargesACC')
select @ln_salesretacc     = (Select code from global where name = 'GT_SalesReturnACC')
select @ln_purchaseacc     = (Select code from global where name = 'GT_PurchaseACC')
select @ln_revfromservices = (Select code from global where name = 'GT_RevenueFromServices')

/* Declaration of Temporary Table to be used for records to be returned by this script */

create table #lt_Accounts
(
	acccode      numeric (5,  0) NOT NULL,
	type	     numeric (2,  0) NOT NULL,
	currbalance  numeric (25, 5) NOT NULL
)

Insert #lt_Accounts
Select a.acccode, 0, 0
from   accounts a
where acccode not in (@ln_revfromservices, @ln_salesretacc, @ln_salesacc)

/**********************************************************************/
/******************* Purchase Module's effects ************************/
/**********************************************************************/

create table #lt_PurchaseSummary
(
	acccode      numeric (5,  0) NOT NULL,
	NetAmt       numeric (25, 2) NOT NULL,    /*Net Cost including flat discounts, misc charges*/
	flatdisc     numeric (11, 2) NOT NULL,
	misccharges  numeric (11, 2) NOT NULL,
	salestax     numeric (11, 2) NOT NULL
)

insert  #lt_PurchaseSummary
select  Case purledger.PurCatCode
		when 1 THEN @ln_cashacc     /* Purchase Purchase Cash */
		when 3 THEN @ln_equityacc   /* Opening Purchase  */
		when 7 THEN @ln_cashacc     /* Cash Purchase Loose */	
		else   purledger.suppcode   /* Credit Purhase Pack (2) or Loose (8)  */
	end,
	IsNull( Round(sum(( (purdetail.looseqty + purdetail.packqty * purdetail.packunits) * purdetail.purprice) * (1 - (.01 * purdetail.discperc))) * (1- (.01 * purledger.discperc)) + purledger.misccharges + purledger.salestax - purledger.flatdisc, 0), 0),
	purledger.flatdisc,
	purledger.misccharges,
	purledger.salestax 

from     purledger,	 
	 purdetail 

where    purledger.date >= @ad_SDate and purledger.date <= @ad_EDate and
	 purledger.posted = 'Y' and
	 purledger.purinvcode = purdetail.purinvcode 

group by purledger.purinvcode,
	 purledger.purcatcode,
	 purledger.date,
	 purledger.discperc,
	 purledger.misccharges,
	 purledger.salestax,
	 purledger.flatdisc,	
	 purledger.suppcode 


/********************** Credit flatdiscount (Income A/c) ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(flatdisc), 0) from #lt_PurchaseSummary)
where  #lt_accounts.acccode = @ln_freightacc

/********************** Debit misc charges (Income A/c) ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(misccharges), 0) from #lt_PurchaseSummary)
where  #lt_accounts.acccode = @ln_octroiacc

/********************** Debit salestax (Current Asset A/c) ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(salestax), 0) from #lt_PurchaseSummary)
where  #lt_accounts.acccode = @ln_salestaxacc

/******************Credit supplier/cash/equity account********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(#lt_PurchaseSummary.NetAmt), 0) from #lt_PurchaseSummary where #lt_PurchaseSummary.acccode = #lt_accounts.acccode)
from   #lt_accounts, #lt_PurchaseSummary
where  #lt_accounts.acccode = #lt_PurchaseSummary.acccode 

Drop table #lt_PurchaseSummary

/**********************************************************************/
/**************** Purchase Return Module's Effects*********************/
/**********************************************************************/

create table #lt_PurRetSummary
(
	acccode      numeric (5,  0) NOT NULL,
	NetAmt       numeric (15, 2) NOT NULL,    /*Net Cost including flat discounts, misc charges*/
	flatdisc     numeric (11, 2) NOT NULL,
	misccharges  numeric (11, 2) NOT NULL,
	salestax     numeric (11, 2) NOT NULL
)

insert  #lt_PurRetSummary
select  Case prledger.PRCatCode
		when 4 THEN @ln_cashacc     /* Cash Purchase Return */
		when 6 THEN @ln_equityacc   /* Opening Purchase Return */
		else   prledger.suppcode    /* Credit Purhase Return */
	end,

	IsNull(Round(sum((( prdetail.looseqty + prdetail.packqty * prdetail.packunits) * prdetail.prprice) * (1 - (.01 * prdetail.discperc))) * (1- (.01 * prledger.discperc)) + prledger.misccharges + prledger.salestax - prledger.flatdisc, 0), 0),
	prledger.flatdisc,
	prledger.misccharges,
	prledger.salestax

from     prledger,	 
	 prdetail		

where    prledger.date >= @ad_SDate and prledger.date <= @ad_EDate and
	 prledger.posted = 'Y' and
	 prledger.prinvcode = prdetail.prinvcode

group by prledger.prinvcode,
	 prledger.suppcode, 
	 prledger.prcatcode,
	 prledger.date,
	 prledger.discperc,
	 prledger.misccharges,
	 prledger.salestax,
	 prledger.flatdisc		

/**********************Debit flatdiscount ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(flatdisc), 0) from #lt_PurRetSummary)
where  #lt_accounts.acccode = @ln_freightacc

/**********************Credit misc charges ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(misccharges), 0) from #lt_PurRetSummary)
where  #lt_accounts.acccode = @ln_octroiacc

/**********************Credit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(salestax), 0) from #lt_PurRetSummary)
where  #lt_accounts.acccode = @ln_salestaxacc

/******************Debit supplier/cash/equity account********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(#lt_PurRetSummary.netAmt), 0) from #lt_PurRetSummary where #lt_PurRetSummary.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_PurRetSummary
where  #lt_accounts.acccode = #lt_PurRetSummary.acccode 

Drop table #lt_PurRetSummary

/**********************************************************************/
/**************************** Sale ***********************************/
/**********************************************************************/

create table #lt_SaleSummary
(
	acccode      numeric (5,  0) NOT NULL,
	InventoryAmt numeric (15, 5) NOT NULL,    /*Average cost of goods*/
	NetAmt       numeric (15, 5) NOT NULL,    /*Net sale price including flat discounts, misc charges etc*/
	salecatcode  numeric (1,  0) NOT NULL,
	flatdisc     numeric (11, 2) NOT NULL,
	misccharges  numeric (11, 2) NOT NULL,
	salestax     numeric (11, 2) NOT NULL
)

insert  #lt_SaleSummary
select  Case saleledger.saleCatCode
		when 1 THEN @ln_cashacc     /* Cash Sale */
		when 3 THEN @ln_cashacc     /* Cash Sale */
		else   saleledger.custcode     /* Credit Sale */
	end,
	IsNull(sum( (saledetail.looseqty + saledetail.packqty * saledetail.packunits) * saledetail.avgprice), 0),
	IsNull(Round(sum(( (saledetail.looseqty + saledetail.packqty * saledetail.packunits) * (saledetail.saleprice - saledetail.itemflatdisc)) * (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0), 0),
	saleledger.salecatcode,
	saleledger.flatdisc,
	saleledger.misccharges,
	saleledger.salestax

from     saleledger,	 
	 saledetail		

where    saleledger.date >= @ad_SDate and saleledger.date <= @ad_EDate and
	 saleledger.posted = 'Y' and
	 saleledger.saleinvcode = saledetail.saleinvcode 

group by saleledger.saleinvcode,
	 saleledger.custcode, 
	 saleledger.salecatcode,
	 saleledger.date,
	 saleledger.discperc,
	 saleledger.misccharges,
	 saleledger.salestax,
	 saleledger.flatdisc		

/**********************Debit Average Purchase Cost***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(InventoryAmt), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_purchaseacc

/**********************Debit flatdiscount ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(flatdisc), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_salesfixdiscacc

/**********************Credit misc charges ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(misccharges), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_miscchargesacc

/**********************Credit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(salestax), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_salestaxacc

/**********************Credit Sales***********************/
Insert #lt_accounts
Select distinct @ln_salesacc, salecatcode, 0
from #lt_SaleSummary

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(NetAmt), 0) from #lt_SaleSummary where #lt_SaleSummary.salecatcode = #lt_accounts.type)
from   #lt_accounts
where  #lt_accounts.acccode = @ln_salesacc

/******************Debit customer/cash/equity account********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(#lt_SaleSummary.NetAmt), 0) from #lt_SaleSummary where #lt_SaleSummary.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_SaleSummary
where  #lt_accounts.acccode = #lt_SaleSummary.acccode 

Drop table #lt_SaleSummary

/**********************************************************************/
/**************************** Sale Return ********************************/
/**********************************************************************/

create table #lt_SaleRetSummary
(
	acccode      numeric (5,  0) NOT NULL,
	InventoryAmt numeric (15, 5) NOT NULL,    /*Average cost of goods*/
	NetAmt       numeric (15, 5) NOT NULL,    /*Sale price of items and disc on total item sale price*/
	srcatcode    numeric (1,  0) NOT NULL,
	flatdisc     numeric (11, 2) NOT NULL,
	misccharges  numeric (11, 2) NOT NULL,
	salestax     numeric (11, 2) NOT NULL
)

insert  #lt_SaleRetSummary
select  Case srledger.srCatCode
		when 6 THEN @ln_cashacc     /* Cash Sale Return*/
		when 8 THEN @ln_cashacc     /* Cash Sale Return*/
		else   srledger.custcode     /* Credit Sale Return*/
	end,
	IsNull( sum(((srdetail.looseqty + srdetail.packqty * srdetail.packunits) * srdetail.srprice) * (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)), 0),
	IsNull(Round(sum(((srdetail.looseqty + srdetail.packqty * srdetail.packunits) * srdetail.srprice) * (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) + srledger.misccharges + srledger.salestax - srledger.flatdisc, 0), 0),
	srledger.srcatcode,
	srledger.flatdisc,
	srledger.misccharges,
	srledger.salestax

from     srledger,	 
	 srdetail		

where    srledger.date >= @ad_SDate and srledger.date <= @ad_EDate and
	 srledger.posted = 'Y' and
	 srledger.srinvcode = srdetail.srinvcode 

group by srledger.srinvcode,
	 srledger.custcode, 
	 srledger.srcatcode,
	 srledger.date,
	 srledger.discperc,
	 srledger.misccharges,
	 srledger.salestax,
	 srledger.flatdisc		

/**********************Credit Purchase ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(InventoryAmt), 0) from #lt_SaleRetSummary)
where  #lt_accounts.acccode = @ln_purchaseacc

/**********************Credit flatdiscount ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(flatdisc), 0) from #lt_SaleRetSummary)
where  #lt_accounts.acccode = @ln_salesfixdiscacc

/**********************Debit misc charges ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(misccharges), 0) from #lt_SaleRetSummary)
where  #lt_accounts.acccode = @ln_miscchargesacc

/**********************Debit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(salestax), 0) from #lt_SaleRetSummary)
where  #lt_accounts.acccode = @ln_salestaxacc

/**********************Debit Sales Return ***********************/
Insert #lt_accounts
Select distinct @ln_salesretacc, srcatcode, 0
from #lt_SaleRetSummary

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(NetAmt), 0) from #lt_SaleRetSummary where #lt_SaleRetSummary.srcatcode = #lt_accounts.type)
from   #lt_accounts
where  #lt_accounts.acccode = @ln_salesretacc

/******************credit customer/cash/equity account********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(NetAmt), 0) from #lt_SaleRetSummary where #lt_SaleRetSummary.acccode = #lt_accounts.acccode)
from   #lt_accounts, #lt_SaleRetSummary
where  #lt_accounts.acccode = #lt_SaleRetSummary.acccode 

Drop table #lt_SaleRetSummary

/**********************************************************************/
/**************************** Accounting Vouchers ************************/
/**********************************************************************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(gldetail.debit - gldetail.credit), 0) from glheader, gldetail where glheader.date >= @ad_SDate and glheader.date <= @ad_EDate and glheader.posted = 'Y' and glheader.glvochcode =  gldetail.glvochcode and gldetail.acccode = #lt_accounts.acccode ) 
from   #lt_accounts
where  #lt_accounts.acccode IN (Select distinct acccode from gldetail) 


/**********************************************************************/
/********************* Bills Receivables/Payables **********************/
/**********************************************************************/

/* Credit the Customer A/c for B/R and Debit the Supplier A/c for B/P */
/* that is decrease the balance for Customer or Supplier */

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
	(Select IsNull(sum(Case NoteCatCode When 1 Then Amount * -1 Else Notes.Amount      End), 0)
		from Notes 
		where Notes.postdate >= @ad_SDate and Notes.postdate <= @ad_EDate and Notes.posted = 'Y' and 
		Notes.acccode = #lt_accounts.acccode )
from   #lt_accounts
where  #lt_accounts.acccode IN (Select distinct acccode from Notes ) 

/* Credit the Bank A/c for B/P and Debit the Bank A/c for B/R */
/* that is Increase the balance for Customer and Decrease for Supplier */

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
	(Select IsNull(sum(Case NoteCatCode When 1 Then Amount    Else Notes.Amount * -1   End), 0)
		from Notes 
		where Notes.postdate >= @ad_SDate and Notes.postdate <= @ad_EDate and Notes.posted = 'Y' and 
		Notes.bankacccode = #lt_accounts.acccode ) 
from   #lt_accounts
where  #lt_accounts.acccode IN (Select distinct bankacccode from Notes ) 

/**********************************************************************/
/********************* Stock Adjustment Decrease **********************/
/**********************************************************************/

create table #lt_Stockadj
(
	AccCode      numeric (5,  0) NOT NULL,
	NetAmt       numeric (15, 5) NOT NULL,    /*Net Cost including flat discounts, misc charges*/
)

/* Accounting impact of Stock Adjustments for Decrease */

insert  #lt_Stockadj

Select 	h.AccCode,
	round(sum((d.looseqty + d.bonusqty) * d.price), 0) as NetAmt

From AdjHeader h, AdjDetail d

where   h.Date >= @ad_SDate and h.Date <= @ad_EDate and
	h.Posted = 'Y' and
	h.AdjCatCode = 2 and
	h.AdjCode = d.AdjCode

group by h.AdjCode,
	 h.AccCode

/**********************Debit Relevant Expense Account ******************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
	(Select IsNull(sum(NetAmt), 0) from #lt_Stockadj)
from   #lt_accounts, #lt_Stockadj
where  #lt_accounts.acccode = #lt_Stockadj.acccode

Drop table #lt_Stockadj

/**********************************************************************/
/********************* Stock Adjustment Increase **********************/
/**********************************************************************/

create table #lt_Stockadj2
(
	AccCode      numeric (5,  0) NOT NULL,
	NetAmt       numeric (15, 5) NOT NULL,    /*Net Cost including flat discounts, misc charges*/
)

insert  #lt_Stockadj2

Select 	h.AccCode,
	round(sum((d.looseqty + d.bonusqty) * d.price), 0) as NetAmt

From AdjHeader h, AdjDetail d

where   h.PostedDate >= @ad_SDate and h.PostedDate <= @ad_EDate and
	h.Posted = 'Y' and
	h.AdjCatCode = 1 and
	h.AdjCode = d.AdjCode

group by h.AdjCode,
	 h.AccCode

/**********************Credit Relevant Income Account ******************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance -
	(Select IsNull(sum(NetAmt), 0) from #lt_Stockadj2)
from   #lt_accounts, #lt_Stockadj2
where  #lt_accounts.acccode = #lt_Stockadj2.acccode

Drop table #lt_Stockadj2

/**********************************************************************/
/************************** Sale of Services **************************/
/**********************************************************************/

create table #lt_Services
(
	acccode      	numeric (5,  0) NOT NULL,
	NetAmt       	numeric (15, 5) NOT NULL,    /*Net sale price including flat discounts, misc charges etc*/
	servicecatcode	numeric (2,  0) NOT NULL,
	flatdisc     	numeric (11, 2) NOT NULL,
	misccharges  	numeric (11, 2) NOT NULL
)

insert #lt_Services
Select  Case h.serviceCatCode
	    When 10 THEN @ln_cashacc   /* Cash Service Sale (Retail Cash) */
	    When 12 THEN @ln_cashacc   /* Cash Service Sale (Immediate Cash) */
	    Else   	 h.custcode    /* Credit Service Sale */
	End,
	IsNull(Round(sum( (isnull(d.price, 0) * 
		(1 - (.01 * isnull(d.discperc, 0)))) * 
		(1- (.01 * h.discperc)) + isnull(h.misccharges,0) - 
		isnull(h.flatdisc, 0)), 0), 0),
	h.servicecatcode,
	isnull(h.flatdisc, 0) as flatdisc, 
	isnull(h.misccharges, 0) as misccharges

from     serviceheader h,	 
	 servicedetail d
where    h.date >= @ad_SDate and h.date <= @ad_EDate and
	 h.posted = 'Y' and
	 h.serviceinvcode = d.serviceinvcode 

group by h.serviceinvcode,
	 h.custcode, 
	 h.servicecatcode,
	 h.date,
	 h.discperc,
	 h.misccharges,
	 h.flatdisc

/*******************Credit Revenue From Services A/c ********************/
insert #lt_accounts
select distinct @ln_revfromservices, servicecatcode, 0
from #lt_Services

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(NetAmt), 0) from #lt_Services where #lt_Services.servicecatcode = #lt_accounts.type)
from   #lt_accounts
where  #lt_accounts.acccode = @ln_revfromservices

/******************Debit customer/cash account********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + 
	(Select IsNull(sum(#lt_Services.NetAmt), 0) from #lt_Services where #lt_Services.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_Services
where  #lt_accounts.acccode = #lt_Services.acccode 

/**********************Debit flatdiscount ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(flatdisc), 0) from #lt_Services)
where  #lt_accounts.acccode = @ln_salesfixdiscacc

/**********************Credit misc charges ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(misccharges), 0) from #lt_Services)
where  #lt_accounts.acccode = @ln_miscchargesacc

Drop table #lt_Services

/**********************************************************************/
/********************** Sale Returns of Services **********************/
/**********************************************************************/

create table #lt_ServicesRet
(
	acccode      	numeric (5,  0) NOT NULL,
	NetAmt       	numeric (15, 5) NOT NULL,    /*Net sale price including flat discounts, misc charges etc*/
	servicecatcode	numeric (2,  0) NOT NULL,
	flatdisc     	numeric (11, 2) NOT NULL,
	misccharges  	numeric (11, 2) NOT NULL
)

insert #lt_ServicesRet
Select  Case h.serviceRCatCode
	    When 13 THEN @ln_cashacc   /* Cash Service Sale Return (Retail Cash) */
	    When 15 THEN @ln_cashacc   /* Cash Service Sale Return (Immediate Cash) */
	    Else   	 h.custcode    /* Credit Service Sale Return */
	End,
	IsNull(Round(sum( (isnull(d.Serviceprice, 0) * 
		(1 - (.01 * isnull(d.discperc, 0)))) * 
		(1- (.01 * h.discperc)) + isnull(h.misccharges,0) - 
		isnull(h.flatdisc, 0)), 0), 0),
	h.serviceRcatcode,
	isnull(h.flatdisc, 0) as flatdisc, 
	isnull(h.misccharges, 0) as misccharges

from     serviceRheader h,	 
	 serviceRdetail d
where    h.date >= @ad_SDate and h.date <= @ad_EDate and
	 h.posted = 'Y' and
	 h.serviceRinvcode = d.serviceRinvcode 

group by h.serviceRinvcode,
	 h.custcode, 
	 h.serviceRcatcode,
	 h.date,
	 h.discperc,
	 h.misccharges,
	 h.flatdisc

/******************* Debit Revenue From Services A/c ********************/
insert #lt_accounts
select distinct @ln_revfromservices, servicecatcode, 0
from #lt_ServicesRet

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(NetAmt), 0) from #lt_ServicesRet where #lt_ServicesRet.servicecatcode = #lt_accounts.type)
from   #lt_accounts
where  #lt_accounts.acccode = @ln_revfromservices

/******************** Credit customer/cash account **********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - 
	(Select IsNull(sum(#lt_ServicesRet.NetAmt), 0) from #lt_ServicesRet where #lt_ServicesRet.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_ServicesRet
where  #lt_accounts.acccode = #lt_ServicesRet.acccode 

/********************** Credit flatdiscount ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(flatdisc), 0) from #lt_ServicesRet)
where  #lt_accounts.acccode = @ln_salesfixdiscacc

/********************** Debit misc charges ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(misccharges), 0) from #lt_ServicesRet)
where  #lt_accounts.acccode = @ln_miscchargesacc

Drop table #lt_ServicesRet

/**************************Final Housing Keeping *********************/

create table #lt_Amt
(
	AccCode int NOT NULL ,
	SubAccCode smallint NOT NULL ,
	CatAccCode smallint NOT NULL ,
	MainAccCode smallint NOT NULL ,
	AcName varchar (60) NOT NULL ,
	SubAcName varchar (60) NOT NULL ,
	CatAcName varchar (60) NOT NULL ,
	MainAcName varchar (60) NOT NULL ,
	Value1 numeric(25, 5) NULL,
	Type numeric(2, 0) NOT NULL
)

Insert #lt_Amt (acccode, subacccode, catacccode, mainacccode, acname, 
	subacname, catacname, mainacname, value1, type)

Select a.acccode, s.subacccode, c.catacccode, m.mainacccode, a.name, s.name, c.name, m.name, 
	#lt_Accounts.currbalance, #lt_Accounts.type

from   #lt_Accounts, accounts a, subaccounts s, categoryaccounts c, mainaccounts m
where #lt_Accounts.acccode = a.acccode and a.subcode = s.subacccode and 
	s.catacccode = c.catacccode and c.mainacccode = m.mainacccode and
	m.mainacccode in (4, 5) and #lt_Accounts.currbalance <> 0

