-- SP_InsertBasicData (last defined by script catalog)
CREATE   PROCEDURE SP_InsertBasicData 
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20) 
AS    

SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DECLARE @INS NVARCHAR(1000), @SQL NVARCHAR(4000), @QRY NVARCHAR(4000), @TableName NVARCHAR(100), @LIST NVARCHAR(4000), @FROM NVARCHAR(1000)
DECLARE @ENDD NVARCHAR(50), @CON NVARCHAR(1000), @NOTIN NVARCHAR(1000), @PKCOND NVARCHAR(2000), @WHRTBM NVARCHAR(1000)
DECLARE @full_table_name NVARCHAR(255), @ColName NVARCHAR(255), @MAXCOL NVARCHAR(255), @TABMAXSQL NVARCHAR(3000)
DECLARE @Priority SMALLINT, @KeySeq SMALLINT
DECLARE @table_id INT, @err INT
DECLARE @UPDMAXKEY CHAR(1)

SET @INS = N'INSERT INTO '
SET @SQL = N'SELECT '
set @FROM = N' FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.'
SET @ENDD = N' AS T WHERE '
SET @CON = N'CONVERT(VarChar(10),'
SET @NOTIN = N' NOT IN (SELECT '

DECLARE Ins1 CURSOR FOR  
SELECT TABLENAME=LTRIM(RTRIM(TABLENAME)), PRIORITY, UPDATETABMAXKEY
FROM TransferableData
WHERE Enable='Y' AND AutoInsert = 'Y'
ORDER BY Priority

OPEN Ins1
FETCH NEXT FROM Ins1 INTO @TableName, @Priority, @UPDMaxKey
WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @PKCOND = '', @MAXCOL = ''
	SET @full_table_name = LTRIM(RTRIM(@owner)) + '.' + @TableName
	SET @table_id = OBJECT_ID(@full_table_name)
	SET @err = @@ERROR
	IF @err <> 0 OR @table_id IS NULL
	BEGIN
		RAISERROR('Data Insertion: Invalid Object Refered: Name = %s', 16, 1, @full_table_name)
		CLOSE Ins1
		DEALLOCATE Ins1
		RETURN -1
	END

	DECLARE Ins2 CURSOR FOR
	SELECT 
		COLNAME = CONVERT(sysname,c.name),
		KEYSEQ = 
			CASE 
			when c.name = index_col(@full_table_name, i.indid,  1)
				then convert (smallint,1)
			when c.name = index_col(@full_table_name, i.indid,  2)
				then convert (smallint,2)
			when c.name = index_col(@full_table_name, i.indid,  3) 
				then convert (smallint,3)
			when c.name = index_col(@full_table_name, i.indid,  4)
				then convert (smallint,4)
			when c.name = index_col(@full_table_name, i.indid,  5)
				then convert (smallint,5)
			when c.name = index_col(@full_table_name, i.indid,  6)
				then convert (smallint,6)
			when c.name = index_col(@full_table_name, i.indid,  7)
				then convert (smallint,7)
			when c.name = index_col(@full_table_name, i.indid,  8)
				then convert (smallint,8)
			when c.name = index_col(@full_table_name, i.indid,  9)
				then convert (smallint,9)
			when c.name = index_col(@full_table_name, i.indid, 10)
				then convert (smallint,10)
			when c.name = index_col(@full_table_name, i.indid, 11)
				then convert (smallint,11)
			when c.name = index_col(@full_table_name, i.indid, 12)
				then convert (smallint,12)
			when c.name = index_col(@full_table_name, i.indid, 13)
				then convert (smallint,13)
			when c.name = index_col(@full_table_name, i.indid, 14)
				then convert (smallint,14)
			when c.name = index_col(@full_table_name, i.indid, 15)
				then convert (smallint,15)
			when c.name = index_col(@full_table_name, i.indid, 16)
				then convert (smallint,16)
			end
		from
			sysindexes i, syscolumns c, sysobjects o
		where
			o.id = @table_id and o.id = c.id 
			and o.id = i.id and (i.status & 0x800) = 0x800 and
			(c.name = index_col (@full_table_name, i.indid,  1) or
			c.name = index_col (@full_table_name, i.indid,  2) or
			c.name = index_col (@full_table_name, i.indid,  3) or
			c.name = index_col (@full_table_name, i.indid,  4) or
			c.name = index_col (@full_table_name, i.indid,  5) or
			c.name = index_col (@full_table_name, i.indid,  6) or
			c.name = index_col (@full_table_name, i.indid,  7) or
			c.name = index_col (@full_table_name, i.indid,  8) or
			c.name = index_col (@full_table_name, i.indid,  9) or
			c.name = index_col (@full_table_name, i.indid, 10) or
			c.name = index_col (@full_table_name, i.indid, 11) or
			c.name = index_col (@full_table_name, i.indid, 12) or
			c.name = index_col (@full_table_name, i.indid, 13) or
			c.name = index_col (@full_table_name, i.indid, 14) or
			c.name = index_col (@full_table_name, i.indid, 15) or
			c.name = index_col (@full_table_name, i.indid, 16))
		order by 2

		OPEN Ins2
		FETCH NEXT FROM Ins2 INTO @ColName, @KeySeq
		WHILE @@FETCH_STATUS = 0
		BEGIN
		IF @PKCOND <> ''
		BEGIN
			SET @PKCOND = @PKCOND + ' + '
		END
		SET @PKCOND = @PKCOND + ' ' + @CON + LTRIM(RTRIM(@ColName)) + ')'
		SET @MAXCOL = 'MAX(' + RTRIM(LTRIM(@ColName)) + ')'
		FETCH NEXT FROM Ins2 INTO @ColName, @KeySeq
	END
	CLOSE Ins2
	DEALLOCATE Ins2
	SET @SQL = N' SELECT '
	SET @LIST=''
	EXECUTE @err = SP_COLUMNLIST @OWNER, @TableName, @LIST OUTPUT
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		CLOSE Ins1
		DEALLOCATE Ins1
		RETURN -1
	END
	SET @QRY = @INS + @TableName + ' (' + @List + ' )  ' + @SQL + @List + @FROM + @TableName + @ENDD + @PKCOND + @NOTIN + @PKCOND + ' FROM ' + @TableName + ')'
	EXECUTE (@QRY)
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		RAISERROR('Data Insertion: Error Transfering %s Data', 16, 1, @full_table_name)
		CLOSE Ins1
		DEALLOCATE Ins1
		RETURN -1
	END
	IF @UPDMaxKey = 'Y'
	BEGIN
		SET @TABMAXSQL = ''
		SET @TABMAXSQL = 'UPDATE _tabmaxkey SET TABMAXKEY = ' + ' ISNULL((SELECT ' + @MAXCOL + ' FROM  ' + RTRIM(LTRIM(@TableName)) + '), 0) ' + 'WHERE TABNAME = ''' + RTRIM(LTRIM(@TableName)) + ''''
		EXECUTE (@TABMAXSQL)
		SET @err = @@ERROR
		IF @@ERROR <> 0 OR @err <> 0
		BEGIN
			RAISERROR('Data Insertion: Error While Updating the TABMAXKEY of %s ', 16, 1, @full_table_name)
			CLOSE Ins1
			DEALLOCATE Ins1
			RETURN -1
		END
	END
	FETCH NEXT FROM Ins1 INTO @TableName, @Priority, @UPDMaxKey
END
CLOSE Ins1
DEALLOCATE Ins1
RETURN 0
GO

-- SP_InsertBasicData_Form_DataCarry (last defined by script catalog)
CREATE PROCEDURE SP_InsertBasicData_Form_DataCarry
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20) 
AS

SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DECLARE @INS NVARCHAR(1000), @SQL NVARCHAR(4000), @QRY NVARCHAR(4000), @TableName NVARCHAR(100), @LIST NVARCHAR(4000), @FROM NVARCHAR(1000)
DECLARE @ENDD NVARCHAR(50), @CON NVARCHAR(1000), @NOTIN NVARCHAR(1000), @PKCOND NVARCHAR(2000), @WHRTBM NVARCHAR(1000)
DECLARE @full_table_name NVARCHAR(255), @ColName NVARCHAR(255), @MAXCOL NVARCHAR(255), @TABMAXSQL NVARCHAR(3000)
DECLARE @Priority SMALLINT, @KeySeq SMALLINT
DECLARE @table_id INT, @err INT
DECLARE @UPDMAXKEY CHAR(1)

SET @INS = N'INSERT INTO '
SET @SQL = N'SELECT '
set @FROM = N' FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.'
SET @ENDD = N' AS T WHERE '
SET @CON = N'CONVERT(VarChar(10),'
SET @NOTIN = N' NOT IN (SELECT '

DECLARE Ins1 CURSOR FOR  
SELECT TABLENAME=LTRIM(RTRIM(TABLENAME)), PRIORITY, UPDATETABMAXKEY
FROM TransferableData
WHERE Enable='Y' AND AutoInsert = 'Y'
ORDER BY Priority

OPEN Ins1
FETCH NEXT FROM Ins1 INTO @TableName, @Priority, @UPDMaxKey
WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @PKCOND = '', @MAXCOL = ''
	SET @full_table_name = LTRIM(RTRIM(@owner)) + '.' + @TableName
	SET @table_id = OBJECT_ID(@full_table_name)
	SET @err = @@ERROR
	IF @err <> 0 OR @table_id IS NULL
	BEGIN
		RAISERROR('Data Insertion: Invalid Object Refered: Name = %s', 16, 1, @full_table_name)
		CLOSE Ins1
		DEALLOCATE Ins1
		RETURN -1
	END

	DECLARE Ins2 CURSOR FOR
	SELECT 
		COLNAME = CONVERT(sysname,c.name),
		KEYSEQ = 
			CASE 
			when c.name = index_col(@full_table_name, i.indid,  1)
				then convert (smallint,1)
			when c.name = index_col(@full_table_name, i.indid,  2)
				then convert (smallint,2)
			when c.name = index_col(@full_table_name, i.indid,  3) 
				then convert (smallint,3)
			when c.name = index_col(@full_table_name, i.indid,  4)
				then convert (smallint,4)
			when c.name = index_col(@full_table_name, i.indid,  5)
				then convert (smallint,5)
			when c.name = index_col(@full_table_name, i.indid,  6)
				then convert (smallint,6)
			when c.name = index_col(@full_table_name, i.indid,  7)
				then convert (smallint,7)
			when c.name = index_col(@full_table_name, i.indid,  8)
				then convert (smallint,8)
			when c.name = index_col(@full_table_name, i.indid,  9)
				then convert (smallint,9)
			when c.name = index_col(@full_table_name, i.indid, 10)
				then convert (smallint,10)
			when c.name = index_col(@full_table_name, i.indid, 11)
				then convert (smallint,11)
			when c.name = index_col(@full_table_name, i.indid, 12)
				then convert (smallint,12)
			when c.name = index_col(@full_table_name, i.indid, 13)
				then convert (smallint,13)
			when c.name = index_col(@full_table_name, i.indid, 14)
				then convert (smallint,14)
			when c.name = index_col(@full_table_name, i.indid, 15)
				then convert (smallint,15)
			when c.name = index_col(@full_table_name, i.indid, 16)
				then convert (smallint,16)
			end
		from
			sysindexes i, syscolumns c, sysobjects o
		where
			o.id = @table_id and o.id = c.id 
			and o.id = i.id and (i.status & 0x800) = 0x800 and
			(c.name = index_col (@full_table_name, i.indid,  1) or
			c.name = index_col (@full_table_name, i.indid,  2) or
			c.name = index_col (@full_table_name, i.indid,  3) or
			c.name = index_col (@full_table_name, i.indid,  4) or
			c.name = index_col (@full_table_name, i.indid,  5) or
			c.name = index_col (@full_table_name, i.indid,  6) or
			c.name = index_col (@full_table_name, i.indid,  7) or
			c.name = index_col (@full_table_name, i.indid,  8) or
			c.name = index_col (@full_table_name, i.indid,  9) or
			c.name = index_col (@full_table_name, i.indid, 10) or
			c.name = index_col (@full_table_name, i.indid, 11) or
			c.name = index_col (@full_table_name, i.indid, 12) or
			c.name = index_col (@full_table_name, i.indid, 13) or
			c.name = index_col (@full_table_name, i.indid, 14) or
			c.name = index_col (@full_table_name, i.indid, 15) or
			c.name = index_col (@full_table_name, i.indid, 16))
		order by 2

		OPEN Ins2
		FETCH NEXT FROM Ins2 INTO @ColName, @KeySeq
		WHILE @@FETCH_STATUS = 0
		BEGIN
		IF @PKCOND <> ''
		BEGIN
			SET @PKCOND = @PKCOND + ' + '
		END
		SET @PKCOND = @PKCOND + ' ' + @CON + LTRIM(RTRIM(@ColName)) + ')'
		SET @MAXCOL = 'MAX(' + RTRIM(LTRIM(@ColName)) + ')'
		FETCH NEXT FROM Ins2 INTO @ColName, @KeySeq
	END
	CLOSE Ins2
	DEALLOCATE Ins2
	SET @SQL = N' SELECT '
	SET @LIST=''
	EXECUTE @err = SP_COLUMNLIST @OWNER, @TableName, @LIST OUTPUT
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		CLOSE Ins1
		DEALLOCATE Ins1
		RETURN -1
	END
	IF @TableName <> 'GroupRights'
		SET @QRY = @INS + @TableName + ' (' + @List + ' )  ' + @SQL + @List + @FROM + @TableName + @ENDD + @PKCOND + @NOTIN + @PKCOND + ' FROM ' + @TableName + ')'
	ELSE
		SET @QRY = @INS + @TableName + ' (' + @List + ' )  ' + @SQL + @List + @FROM + @TableName + @ENDD + @PKCOND + @NOTIN + @PKCOND + ' FROM ' + @TableName + ') AND T.RightCode IN (SELECT DISTINCT R.RightCode FROM Rights R)'

	EXECUTE (@QRY)
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		RAISERROR('Data Insertion: Error Transfering %s Data', 16, 1, @full_table_name)
		CLOSE Ins1
		DEALLOCATE Ins1
		RETURN -1
	END
	IF @UPDMaxKey = 'Y'
	BEGIN
		SET @TABMAXSQL = ''
		SET @TABMAXSQL = 'UPDATE _tabmaxkey SET TABMAXKEY = ' + ' ISNULL((SELECT ' + @MAXCOL + ' FROM  ' + RTRIM(LTRIM(@TableName)) + '), 0) ' + 'WHERE TABNAME = ''' + RTRIM(LTRIM(@TableName)) + ''''
		EXECUTE (@TABMAXSQL)
		SET @err = @@ERROR
		IF @@ERROR <> 0 OR @err <> 0
		BEGIN
			RAISERROR('Data Insertion: Error While Updating the TABMAXKEY of %s ', 16, 1, @full_table_name)
			CLOSE Ins1
			DEALLOCATE Ins1
			RETURN -1
		END
	END
	FETCH NEXT FROM Ins1 INTO @TableName, @Priority, @UPDMaxKey
END
CLOSE Ins1
DEALLOCATE Ins1
RETURN 0
GO

-- SP_InsertBasicData_To_DataCarryDB (last defined by script catalog)
CREATE PROCEDURE SP_InsertBasicData_To_DataCarryDB @SRV VARCHAR(50), @DB VARCHAR(50), @OWNER VARCHAR(20), @CustCode SMALLINT, @exportitemchangessince DATETIME AS
SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DECLARE @INS VARCHAR(1000), @SQL VARCHAR(8000), @QRY VARCHAR(8000), @IQRY VARCHAR(8000), @TableName VARCHAR(100), @LIST VARCHAR(8000), @SOURCELIST VARCHAR(8000), @FROM VARCHAR(1000)
DECLARE @ENDD VARCHAR(50), @CON VARCHAR(1000), @NOTIN VARCHAR(1000), @PKCOND VARCHAR(2000), @WHRTBM VARCHAR(1000)
DECLARE @full_table_name VARCHAR(255), @ColName VARCHAR(255), @MAXCOL VARCHAR(255), @TABMAXSQL VARCHAR(3000)
DECLARE @Priority SMALLINT, @KeySeq SMALLINT, @Position SMALLINT
DECLARE @table_id INT, @err INT, @srow INT, @lrow INT
DECLARE @UPDMAXKEY CHAR(1), @ItemTimeStamp VARCHAR(100), @ICodeStr VARCHAR(1000)
SET @ItemTimeStamp = ISNULL((SELECT CONVERT(VARCHAR(100), @exportitemchangessince, 121)), '1990-01-01 00:00:00')

SET @INS = 'INSERT INTO ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.'
SET @SQL = 'SELECT '
set @FROM = ' FROM ' 
SET @ENDD = ' AS T '
SET @CON = 'CONVERT(VarChar(10),'
SET @NOTIN = ' NOT IN (SELECT '

DECLARE Ins1 CURSOR FOR
SELECT TABLENAME=LTRIM(RTRIM(TABLENAME)), PRIORITY, UPDATETABMAXKEY
FROM TransferableData 
WHERE Enable='Y' AND AutoInsert = 'Y'
ORDER BY Priority

OPEN Ins1

FETCH NEXT FROM Ins1 INTO @TableName, @Priority, @UPDMaxKey
WHILE @@FETCH_STATUS = 0
BEGIN
	SELECT @PKCOND = '', @MAXCOL = ''
	SET @full_table_name = @TableName
	SET @table_id = OBJECT_ID(@full_table_name)
	SET @err = @@ERROR

	IF @err <> 0 OR @table_id IS NULL
	BEGIN
		RAISERROR('Data Insertion: Invalid Object Refered: Name = %s', 16, 1, @full_table_name)
		CLOSE Ins1
		DEALLOCATE Ins1
		RETURN -1
	END 

	DECLARE Ins2 CURSOR FOR
	SELECT 	COLNAME = CONVERT(sysname,c.name),
		KEYSEQ =
			CASE
				when c.name = index_col(@full_table_name, i.indid,  1) then convert (smallint,1)
				when c.name = index_col(@full_table_name, i.indid,  2) then convert (smallint,2)
				when c.name = index_col(@full_table_name, i.indid,  3) then convert (smallint,3)
				when c.name = index_col(@full_table_name, i.indid,  4) then convert (smallint,4)
				when c.name = index_col(@full_table_name, i.indid,  5) then convert (smallint,5)
				when c.name = index_col(@full_table_name, i.indid,  6) then convert (smallint,6)
				when c.name = index_col(@full_table_name, i.indid,  7) then convert (smallint,7)
				when c.name = index_col(@full_table_name, i.indid,  8) then convert (smallint,8)
				when c.name = index_col(@full_table_name, i.indid,  9) then convert (smallint,9)
				when c.name = index_col(@full_table_name, i.indid, 10) then convert (smallint,10)
				when c.name = index_col(@full_table_name, i.indid, 11) then convert (smallint,11)
				when c.name = index_col(@full_table_name, i.indid, 12) then convert (smallint,12)
				when c.name = index_col(@full_table_name, i.indid, 13) then convert (smallint,13)
				when c.name = index_col(@full_table_name, i.indid, 14) then convert (smallint,14)
				when c.name = index_col(@full_table_name, i.indid, 15) then convert (smallint,15)
				when c.name = index_col(@full_table_name, i.indid, 16) then convert (smallint,16)
			end
	from
		sysindexes i, syscolumns c, sysobjects o
	where
		o.id = @table_id
		and o.id = c.id
		and o.id = i.id
		and (i.status & 0x800) = 0x800
		and (c.name = index_col (@full_table_name, i.indid,  1) or
		     c.name = index_col (@full_table_name, i.indid,  2) or
		     c.name = index_col (@full_table_name, i.indid,  3) or
		     c.name = index_col (@full_table_name, i.indid,  4) or
		     c.name = index_col (@full_table_name, i.indid,  5) or
		     c.name = index_col (@full_table_name, i.indid,  6) or
		     c.name = index_col (@full_table_name, i.indid,  7) or
		     c.name = index_col (@full_table_name, i.indid,  8) or
		     c.name = index_col (@full_table_name, i.indid,  9) or
		     c.name = index_col (@full_table_name, i.indid, 10) or
		     c.name = index_col (@full_table_name, i.indid, 11) or
		     c.name = index_col (@full_table_name, i.indid, 12) or
		     c.name = index_col (@full_table_name, i.indid, 13) or
		     c.name = index_col (@full_table_name, i.indid, 14) or
		     c.name = index_col (@full_table_name, i.indid, 15) or
		     c.name = index_col (@full_table_name, i.indid, 16)
		    )
	order by 2

	OPEN Ins2
	
	FETCH NEXT FROM Ins2 INTO @ColName, @KeySeq
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF @PKCOND <> ''
		BEGIN
			SET @PKCOND = @PKCOND + ' + '
		END
		SET @PKCOND = @PKCOND + ' ' + @CON + LTRIM(RTRIM(@ColName)) + ')'
		SET @MAXCOL = 'MAX(' + RTRIM(LTRIM(@ColName)) + ')'	
		FETCH NEXT FROM Ins2 INTO @ColName, @KeySeq
	END
	CLOSE Ins2
	DEALLOCATE Ins2

	SET @SQL = ' SELECT '
	SET @LIST=''
	EXECUTE @err = SP_COLUMNLIST 'dbo', @TableName, @LIST OUTPUT
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		CLOSE Ins1
		DEALLOCATE Ins1
		RETURN -1
	END

	SET @SOURCELIST = @LIST

	IF lower(@TableName) = 'service'
		SET @SOURCELIST = REPLACE(@SOURCELIST,'Description,',@ColName+'Description=LEFT(Description,255),')

	IF lower(@TableName) = 'servicecomponent'
		SET @SOURCELIST = REPLACE(@SOURCELIST,'RefDescription,',@ColName+'RefDescription=LEFT(RefDescription,255),')

	IF lower(@TableName) = 'customer'
		SET @SOURCELIST = REPLACE(@SOURCELIST,'SpecialInstructions,',@ColName+'SpecialInstructions=LEFT(SpecialInstructions,255),')

	IF lower(@TableName) = 'supplier'
		SET @SOURCELIST = REPLACE(@SOURCELIST,'SpecialInstructions,',@ColName+'SpecialInstructions=LEFT(SpecialInstructions,255),')
		

	DECLARE Ins3 CURSOR FOR
	SELECT
		COLUMNNAME = convert(sysname,c.name),
		POSITION = convert(int,
				   (
					select count(*)
					from syscolumns sc
					where sc.id     =  c.id
					  AND sc.number =  c.number
					  AND sc.colid  <= c.colid
				    ))
	FROM
		sysobjects o,
		syscolumns c
	WHERE
		o.id = @table_id AND c.id = o.id
	ORDER BY 2

	OPEN Ins3

	FETCH NEXT FROM Ins3 INTO @ColName, @Position
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF ColumnProperty (@table_id, @ColName, 'IsIdentity') <> 1
		BEGIN
			IF @ColName = (SELECT columnname FROM TransferableData_ExportRestrictedColumns WHERE columnname = @ColName and tablename = @TableName)
			BEGIN
				SET @SOURCELIST = REPLACE(@SOURCELIST,@ColName+',',@ColName+'=0,')
			END
		END
		FETCH NEXT FROM Ins3 INTO @ColName, @Position
	END
	CLOSE Ins3
	DEALLOCATE Ins3

	IF RIGHT(@SOURCELIST,1) = ','
		SET @SOURCELIST = LEFT(@SOURCELIST, LEN(@SOURCELIST)-1)

	IF lower(@TableName) = 'item'
		SET @QRY = @INS + @TableName + ' (' + @List + ' )  ' + @SQL + @SOURCELIST + @FROM + @TableName + @ENDD + ' WHERE T.LASTUPDATE >= ''' + @ItemTimeStamp + ''''
	ELSE
		SET @QRY = @INS + @TableName + ' (' + @List + ' )  ' + @SQL + @SOURCELIST + @FROM + @TableName + @ENDD 

	IF lower(@TableName) = 'item' AND @CustCode > 0
		SET @QRY = @QRY + ' AND T.ICatCode IN (SELECT DISTINCT CI.ICatCode FROM DBO.CustWiseItemCategory CI WHERE CI.CustCode = ' + LTRIM(RTRIM(STR(@CustCode, 7))) + ') '

	IF lower(@TableName) = 'itemsuppliers' AND @CustCode > 0
		SET @QRY = @QRY + ' WHERE T.ICode IN (SELECT DISTINCT I.ICode FROM DBO.CustWiseItemCategory CI, Item I WHERE CI.CustCode = ' + LTRIM(RTRIM(STR(@CustCode, 7))) + ' AND CI.ICatCode = I.ICatCode) '

	IF lower(@TableName) = 'item' OR lower(@TableName) = 'itemsuppliers'
	BEGIN
		SET @srow = 0
		SET @lrow = 50000
		WHILE @srow <= 2000000
		BEGIN
			IF @CustCode > 0
				SET @ICodeStr = ' AND T.ICode BETWEEN ' + LTRIM(RTRIM(STR(@srow))) + ' AND ' + LTRIM(RTRIM(STR(@lrow)))
			ELSE
			BEGIN
				IF lower(@TableName) = 'itemsuppliers' 
					SET @ICodeStr = ' WHERE T.ICode BETWEEN ' + LTRIM(RTRIM(STR(@srow))) + ' AND ' + LTRIM(RTRIM(STR(@lrow)))
				ELSE
					SET @ICodeStr = ' AND T.ICode BETWEEN ' + LTRIM(RTRIM(STR(@srow))) + ' AND ' + LTRIM(RTRIM(STR(@lrow)))
			END
			
			SET @IQRY = @QRY + @ICodeStr
--			PRINT @IQRY 
			EXECUTE (@IQRY)
			SET @err = @@ERROR
			IF @@ERROR <> 0 OR @err <> 0
			BEGIN
				RAISERROR('Data Insertion: Error Transfering %s Data', 16, 1, @full_table_name)
				CLOSE Ins1
				DEALLOCATE Ins1
				RETURN -1
			END
			IF lower(@TableName) = 'item'
			BEGIN
				SET @IQRY = 'Update ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' +  'Item Set UserCode=1 , ISizeCode=1, IStyleCode=1, IColourCode=1, ISleeveCode=1, IYarnCode=1, IFabricCode=1, IBrandCode=1, IPartCode=1 WHERE ICode BETWEEN ' + LTRIM(RTRIM(STR(@srow))) + ' AND ' + LTRIM(RTRIM(STR(@lrow)))
				Execute(@IQRY)
				IF @@Error <> 0 
				Begin
					RAISERROR('Updation Problem of Default Values In DataCarryDB', 16, 1)
					RETURN -1	
				End
			END

			SET @srow = @lrow + 1
			SET @lrow = @lrow + 50000
		END
	END
	ELSE
	BEGIN
		EXECUTE (@QRY)
		SET @err = @@ERROR
		IF @@ERROR <> 0 OR @err <> 0
		BEGIN
			RAISERROR('Data Insertion: Error Transfering %s Data', 16, 1, @full_table_name)
			CLOSE Ins1
			DEALLOCATE Ins1
			RETURN -1
		END 
	END
	FETCH NEXT FROM Ins1 INTO @TableName, @Priority, @UPDMaxKey
END
CLOSE Ins1
DEALLOCATE Ins1

SET @QRY = 'Delete From ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'DataImportlog '
Execute(@QRY)
IF @@Error <> 0 
Begin
	RAISERROR('Problem Initializing Data Import Log in DataCarryDB', 16, 1)
	RETURN -1	
End

RETURN 0
GO

-- SP_InsertExpIntimation_To_DataCarryDB (last defined by script catalog)
CREATE Procedure SP_InsertExpIntimation_To_DataCarryDB @SRV VARCHAR(50), @DB VARCHAR(50), @OWNER VARCHAR(20), @scode INT, @lcode INT, @Type SMALLINT AS
/*
Author: Muhammad Azhar Inayat
Version:1.0
date : 2017-11-27
*/
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON
Declare @query VarChar(2500)
Set @query = 'Insert 	Into '+ LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'ExpiryIntimation (IntimationCode, IntimationTypeCode, IntimationSerialNo, AccCode, Date, RefNo, Remarks1, Remarks2, UserCode, Posted, PostedBy, PostDate, CustCode) '
Set @query = @query + ' Select 	IntimationCode, IntimationTypeCode, IntimationSerialNo, AccCode, Date, RefNo, Remarks1, Remarks2, UserCode, Posted, PostedBy, PostDate, CustCode '
Set @query = @query + ' From 	ExpiryIntimation '
Set @query = @query + ' Where   IntimationTypeCode = ' + Cast(@Type As VarChar(10)) +  ' AND IntimationCode Between ' + Cast(@scode As VarChar(10)) + ' And ' + Cast(@lcode As VarChar(10)) 
Execute(@query)
IF @@Error = 0 
Begin
	Set @query = 'Insert 	Into ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'ExpiryIntimationDetail (IntimationCode, ICode, Batch, Expiry, Qty, Packunits, PackPrice, Price, InvoiceCode, InvoiceDate, RefNo, RefDate, RowID) '
	Set @query = @query + 'Select  IntimationCode, ICode, Batch, Expiry, Qty, Packunits, PackPrice, Price, InvoiceCode, InvoiceDate, RefNo, RefDate, RowID '
	Set @query = @query + ' From 	ExpiryIntimationDetail '
	Set @query = @query + ' Where   IntimationCode Between ' + Cast(@scode As VarChar(10)) + ' And ' + Cast(@lcode As VarChar(10)) + ' AND IntimationCode IN (SELECT IntimationCode FROM ExpiryIntimation WHERE IntimationTypeCode = ' + Cast(@Type As VarChar(10)) +  ' AND IntimationCode Between ' + Cast(@scode As VarChar(10)) + ' And ' + Cast(@lcode As VarChar(10)) + ') '
	Set @query = @query + ' ORDER BY RowID '
	Execute(@query)
	IF @@Error <> 0 
	Begin
		RaisError('Problem in inserting detail records of Expiry Intimation to Remote DataBase',16,1)
		Return -1
	End
End
Else
Begin
	RaisError('Problem in inserting header records of Expiry Intimation to Remote DataBase',16,1)
	Return -1
End

Return 1
GO

-- sp_InsertIssueData_To_DataCarryDB (last defined by script catalog)
CREATE   Procedure sp_InsertIssueData_To_DataCarryDB @SRV VARCHAR(50), @DB VARCHAR(50), @OWNER VARCHAR(20), @sinvcode INT, @linvcode INT , @CustCode SMALLINT AS
/*
Author: Muhammad Azhar Inayat
Version:1.0
Comments:This stored procedure is build using iterative prototyping sofware process model so at this stage
	 only necessary columns of SaleLedger and SaleDetail table are used  for carrying data.
	 sp_Empty_DataCarryDB must be execute before executing the following stored procedures.
	 1-SP_InsertBasicData_To_DataCarryDB	
	 2-sp_InsertSaleData_To_DataCarryDB
Version:1.1 (Muhammad Azhar Inayat)
	Procedure Modified in order to implement customer based datacarry
	The idea is to send only required items to a customer/branch
*/
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON
Declare @query VarChar(2500)
Set @query = 'Insert 	Into '+ LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'SaleLedger (SaleInvCode, SaleCatCode, CustCode, SalesmanCode, date, DiscPerc, FlatDisc, MiscCharges, SalesTax,  Posted, PostDate, Remarks, CustRefNo, headerno, headerinvno, OriginalDate, ModifiedBy,PostedBy, InvGSTPerc1, InvTotal) '
Set @query = @query + ' Select 	SaleInvCode=IssueInvCode, SaleCatCode=1, CustCode=ISNULL(AccCode, 19), SalesmanCode, date, DiscPerc=0, FlatDisc=0, MiscCharges=0, SalesTax=0,  Posted, PostDate, Remarks, CustRefNo=LEFT(ReferenceNo, 30), headerno, headerinvno, OriginalDate, ModifiedBy,PostedBy, InvGSTPerc1=0, InvTotal=(SELECT ROUND(SUM(d.qty * d.price), 0) FROM IssueDetail D where d.issueinvcode=issueheader.issueinvcode) '
Set @query = @query + ' From 	IssueHeader '
Set @query = @query + ' Where   IssueInvCode Between ' + Cast(@sinvcode As VarChar(10)) + ' And ' + Cast(@linvcode As VarChar(10))
IF @custcode > 0
BEGIN
	Set @query = @query + ' AND AccCode = ' + Cast(@CustCode As VarChar(10))
END

Execute(@query)
IF @@Error = 0 AND @@RowCount > 0 
Begin
	Set @query = 'Insert 	Into ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' + 'SaleDetail (SaleInvcode, ICode, GCode, Batch, Expiry, PackQty, LooseQty, PackUnits, SalePrice, AvgPrice, Rate, DiscPerc, SalesTax, RowID, itemflatdisc, SaleItemDescription, PackPrice, UnitSalesTax, GSTPerc, SaleUtn, bonusqty, RowGroup) '
	Set @query = @query + 'Select 	SaleInvcode=IssueInvCode, ICode, GCode, Batch, Expiry, PackQty=0, LooseQty=Qty, PackUnits, SalePrice=Price, AvgPrice, Rate=Price, DiscPerc=0, SalesTax=0, RowID=IssRowID, itemflatdisc=0, SaleItemDescription=ItemDescription, PackPrice=SalePrice, UnitSalesTax=0, GSTPerc=0, SaleUtn=IssueUtn, bonusqty=0, RowGroup '
	Set @query = @query + 'From  	IssueDetail '
	Set @query = @query + 'Where   IssueInvCode Between ' + Cast(@sinvcode As VarChar(10)) + ' And ' + Cast(@linvcode As VarChar(10))
	IF @custcode > 0
	BEGIN
		Set @query = @query + ' AND IssueInvCode IN (SELECT IssueInvCode FROM IssueHeader WHERE AccCode = ' + Cast(@CustCode As VarChar(10)) + ') '
	END
	Execute(@query)
	IF @@Error <> 0 OR @@RowCount = 0 	
	Begin
		RaisError('Problem in inserting detail records to Remote DataBase',16,1)
