CREATE PROCEDURE sp_itemingodowns AS

Delete stockinallgodown


insert into stockinallgodown

select  item.customicode, 
	item.name, 
	item.saleprice,
	item.purprice,
	item.avgprice,
	item.packunits,
	item.iccode,
	item.icatcode,
	item.packcode,
	item.manfcode,
	godown = (select name from godown where godown.gcode = i.gcode), 
