Set @Query = 'Select POCode, Date, Remarks, PurOrderCatCode From  ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.' +  'PurOrderHeader'
