		SELECT ServiceInvCode
		FROM ServiceHeader
		Where
			ServiceHeader.ServiceInvCode Between @ai_sInvCode AND @ai_lInvCode AND
			ServiceHeader.ServiceCatCode NOT IN (10) AND
			ServiceHeader.CustCode = @ai_custcode AND
