AS
DECLARE @RowID INT, @TotRows INT, @rt_code INT, @ServiceInvCode INT, @ServiceResultCode INT
CREATE TABLE #lt_invoicelist (Code INT NOT NULL, ROWID INT NOT NULL IDENTITY(1,1))

INSERT INTO #lt_invoicelist 
SELECT ServiceInvCode
FROM ServiceHeader
WHERE
	ServiceHeader.Posted = 'N' AND
	ServiceHeader.ServiceInvCode Between @ai_sInvCode AND @ai_lInvCode AND
	ServiceHeader.ServiceCatCode IN ( @ai_ServiceCatCode) AND
	ServiceHeader.AdmissionCode IS NULL

UPDATE ServiceHeader 
SET ServiceHeader.posted   = 'Y', ServiceHeader.postdate = GetDate(), ServiceHeader.postedby = @ai_SalesmanCode	
WHERE ServiceHeader.Posted = 'N' AND ServiceHeader.ServiceInvCode Between @ai_sInvCode AND @ai_lInvCode AND
	ServiceHeader.ServiceCatCode IN ( @ai_ServiceCatCode) AND ServiceHeader.AdmissionCode IS NULL

SET @RowID = 1
SET @TotRows = ISNULL((SELECT COUNT(*) FROM #lt_invoicelist), 0)

WHILE @RowID <= @TotRows
BEGIN
	SET @ServiceInvCode = (SELECT Code FROM #lt_invoicelist WHERE RowID = @RowID)

	EXECUTE @rt_code = DBO.SP_AutoGenerateServiceResult @ServiceInvCode, @ai_SalesmanCode, @ServiceResultCode OUTPUT
	IF @@ERROR <> 0 OR @rt_code <>  0
	BEGIN
		RaisError('Unable to Generate Service Result for Service Invoice Code = %d' , 16 , 1, @ServiceInvCode)
		RETURN -1
	END

	EXECUTE @rt_code = DBO.SP_AutoGenerateServiceInvPurTemplate @ServiceInvCode, @ai_SalesmanCode
	IF @@ERROR <> 0 OR @rt_code <>  0
	BEGIN
		RaisError('Unable to Generate Service Purchase Template for Service Invoice Code = %d' , 16 , 1, @ServiceInvCode)
		RETURN -1
	END

	EXECUTE @rt_code = DBO.SP_AutoGenerateIssueReqForConsumableItem @ServiceInvCode, @ai_SalesmanCode
	IF @@ERROR <> 0 OR @rt_code <>  0
	BEGIN
		RaisError('Unable to Generate Service Issue Request for Service Invoice Code = %d' , 16 , 1, @ServiceInvCode)
		RETURN -1
	END

	SET @RowID = @RowID + 1
END
RETURN 0
GO

