-- sp_PostServiceIssueRequest (last defined by script catalog)
CREATE PROCEDURE DBO.sp_PostServiceIssueRequest @ai_sInvCode integer, @ai_lInvCode integer, @UserCode integer 
AS
DECLARE @RowID INT, @TotRows INT, @rt_code INT, @IssueInvCode INT, @errcode INT, @Code INT
CREATE TABLE #lt_invoicelist (Code INT NOT NULL, ROWID INT NOT NULL IDENTITY(1,1))

INSERT INTO #lt_invoicelist 
SELECT ServiceIssueRequestCode
FROM ServiceIssueRequest
WHERE ServiceIssueRequestCode Between @ai_sInvCode AND @ai_lInvCode AND Posted = 'N'

Update  ServiceIssueRequest
Set posted   = 'Y', postdate = GetDate(), postedby = @UserCode
Where ServiceIssueRequestCode Between @ai_sInvCode AND @ai_lInvCode AND Posted = 'N'

SET @RowID = 1
SET @TotRows = ISNULL((SELECT COUNT(*) FROM #lt_invoicelist), 0)

WHILE @RowID <= @TotRows
BEGIN
	SET @Code = (SELECT Code FROM #lt_invoicelist WHERE RowID = @RowID)
	EXECUTE @errcode = sp_AutoIssueConsumableItem @Code, @UserCode, @IssueInvCode OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem while Generation of Issue against Service Consumable Items.', 16, 1)
		RETURN -1
	END
	SET @RowID = @RowID + 1
END
RETURN 0
GO

