-- sp_PostTransferHeader (last defined by script catalog)
CREATE PROCEDURE sp_PostTransferHeader @ai_sInvCode integer, @ai_lInvCode integer, @ai_strategy integer, @ai_groupcode integer AS Update  Theader Set Theader.posted   = 'Y', Theader.postdate = GetDate() Where   Theader.TransCode Between @ai_sInvCode AND @ai_lInvCode AND Theader.Posted = 'N' AND SGCode IN (SELECT Godown.GCode FROM	Godown WHERE GCode IN (CASE @ai_strategy WHEN 2 THEN (SELECT G.GCode From Godown G WHERE G.GCode = Godown.GCode) ELSE (SELECT G.GCode From GroupAllowedGodown G WHERE G.GroupCode = @ai_groupcode AND G.Module = 8 AND Godown.GCode = G.GCode) END))
GO

-- SP_PostVisit (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_PostVisit
	@ai_sVisitCode INTEGER, 
	@ai_lVisitCode INTEGER, 
	@ai_UserCode INTEGER, 
	@ai_DoctCode SMALLINT
AS

IF @ai_DoctCode=0 OR @ai_DoctCode IS NULL
BEGIN
	UPDATE VisitAppointment
	SET AppointmentStatusCode = 5, Posted='Y'
	WHERE AppointmentCode IN 
		(SELECT DISTINCT AppointmentCode
		FROM Visit
		WHERE VisitCode Between @ai_sVisitCode AND @ai_lVisitCode AND
			Posted = 'N' AND
			DoctCode IN 
				(SELECT UAD.DoctCode FROM UserAllowedDoctor UAD 
				WHERE UAD.UserCode = @ai_UserCode))

	UPDATE Visit
	SET Posted   = 'Y'
	WHERE VisitCode Between @ai_sVisitCode AND @ai_lVisitCode AND
		Posted = 'N' AND
		DoctCode IN 
			(SELECT UAD.DoctCode FROM UserAllowedDoctor UAD 
			WHERE UAD.UserCode = @ai_UserCode)
END
ELSE
BEGIN
	UPDATE VisitAppointment
	SET AppointmentStatusCode = 5, Posted='Y'
	WHERE AppointmentCode IN 
		(SELECT DISTINCT AppointmentCode
		FROM Visit
		WHERE VisitCode Between @ai_sVisitCode AND @ai_lVisitCode AND
			DoctCode = @ai_DoctCode AND Posted = 'N' AND
			DoctCode IN 
				(SELECT UAD.DoctCode FROM UserAllowedDoctor UAD 
				WHERE UAD.UserCode = @ai_UserCode))

	UPDATE Visit
	SET Posted   = 'Y'
	WHERE VisitCode Between @ai_sVisitCode AND @ai_lVisitCode AND
		DoctCode = @ai_DoctCode AND Posted = 'N' AND
		DoctCode IN 
			(SELECT UAD.DoctCode FROM UserAllowedDoctor UAD 
			WHERE UAD.UserCode = @ai_UserCode)
END
GO

