-- SP_ReadDataMigrationPacket (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_ReadDataMigrationPacket @PacketFile VARCHAR(4000), @ServerName VARCHAR(100), @TempDBName VARCHAR(100)
AS
SET NOCOUNT ON
DECLARE @Qry VARCHAR(4000), @LogicalDatFl VARCHAR(4000), @LogicalLogFl VARCHAR(4000)
DECLARE @rtCode INT, @err INT, @RC INT
DECLARE @VersionInfo varchar(4000), @DBVersion VARCHAR(100)

EXEC @RC = SP_DBMS_Version @VersionInfo OUTPUT 
IF CHARINDEX('Microsoft SQL Server 2012', @VersionInfo, 1) > 0 
	SET @DBVersion = '2012'
ELSE
	SET @DBVersion = '2000'

IF @DBVersion = '2012'
	SET @Qry = 'RESTORE FILELISTONLY FROM DISK = ''' + @PacketFile + ''''
ELSE
	SET @Qry = 'RESTORE FILELISTONLY FROM DISK = ''' + @PacketFile + ''' WITH MEDIAPASSWORD = ''alcia' + LOWER(@ServerName) + ''', PASSWORD = ''alfia' + LOWER(@ServerName) + ''''

CREATE TABLE #backupinfo (LogicalFile VARCHAR(500), PhysicalFile VARCHAR(1000), Type CHAR(1), FG VARCHAR(100), Sz BIGINT, MaxSz BIGINT)

INSERT INTO #backupinfo 
EXECUTE (@Qry)
SET @err = @@Error
IF @err <> 0 OR @rtCode <> 0 
BEGIN
	RAISERROR('Failure to Read Logical File Names From Data Migration Packet, Error Code = %d', 16, 1, @err)
	RETURN -1
END

SET @LogicalDatFl = ISNULL((SELECT LogicalFile FROM #backupinfo WHERE Type = 'D'), 'MehmoodDatabase_Data')
SET @LogicalLogFl = ISNULL((SELECT LogicalFile FROM #backupinfo WHERE Type = 'L'), 'MehmoodDatabase_Log')

IF @DBVersion = '2012'
	SET @Qry = 'RESTORE DATABASE ' + @TempDBName + ' FROM DISK = ''' + @PacketFile + ''' WITH RECOVERY, REPLACE, MOVE ''' + @LogicalDatFl + ''' TO ''C:\' + @TempDBName + '_DM.MDF'', MOVE ''' + @LogicalLogFl + ''' TO ''C:\' + @TempDBName + '_DM_Log.LDF'''
ELSE
	SET @Qry = 'RESTORE DATABASE ' + @TempDBName + ' FROM DISK = ''' + @PacketFile + ''' WITH RECOVERY, REPLACE, MEDIAPASSWORD = ''alcia' + LOWER(@ServerName) + ''', PASSWORD = ''alfia' + LOWER(@ServerName) + ''', MOVE ''' + @LogicalDatFl + ''' TO ''C:\' + @TempDBName + '_DM.MDF'', MOVE ''' + @LogicalLogFl + ''' TO ''C:\' + @TempDBName + '_DM_Log.LDF'''

EXECUTE (@Qry)
SET @err = @@Error
IF @err <> 0 OR @rtCode <> 0 
BEGIN
	RAISERROR('Failure to Read Data Migration Packet, Error Code = %d', 16, 1, @err)
	RETURN -1
END

RETURN 0
GO

-- SP_ReGenerateServiceResult (last defined by script catalog)
CREATE PROCEDURE DBO.SP_ReGenerateServiceResult @ServiceInvCode INT, @UserCode SMALLINT
AS
SET NOCOUNT ON
DECLARE @tot_services INT, @ServiceResultCode INT, @ServiceCode INT, @PatientCode INT, @GestationCode SMALLINT
DECLARE @Posted CHAR(1), @Expiry DateTime, @Price NUMERIC(12,2)

SET @ServiceResultCode = (SELECT MAX(ServiceResultCode) FROM ServiceResultHeader WHERE ServiceInvCode=@ServiceInvCode)

DECLARE @start_ticket INT, @end_ticket INT, @errcode INT, @RowId INT, @In_RowID INT, @In_Qty INT, @TicketCode INT

DECLARE @service_table TABLE 
	(ServiceCode INT, Qty INT, Expiry DateTime, Price NUMERIC(12,2), Rowid INT IDENTITY(1, 1))

IF @ServiceInvCode IS NULL
	RETURN 0

IF @UserCode IS NULL
	SET @UserCode = 1

SET @Posted = ISNULL((SELECT Posted FROM ServiceHeader WHERE ServiceInvCode=@ServiceInvCode), 'N')
IF @Posted = 'N' OR @Posted IS NULL
	RETURN 0

SET @tot_services = (SELECT servicecount=(SELECT COUNT(SD.ServiceCode) FROM ServiceDetail SD, Service SV WHERE SD.ServiceInvCode=@ServiceInvCode AND SD.ServiceCode = SV.ServiceCode AND SV.ResultRequired='Y')
	FROM DBO.ServiceHeader
	WHERE ServiceInvCode = @ServiceInvCode AND Posted='Y')

IF @tot_services <= 0 OR @tot_services IS NULL
	RETURN 0

SELECT @PatientCode = P.PatientCode , @GestationCode = P.GestationCode
FROM Patient P
WHERE P.PatientCode IN 
	(SELECT PatientCode=SH.PatientCode 
	FROM ServiceHeader SH WHERE SH.ServiceInvCode=@ServiceInvCode
	UNION ALL
	SELECT PA.PatientCode 
	FROM PatientAdmission PA, ServiceHeader SH 
	WHERE SH.ServiceInvCode=@ServiceInvCode AND SH.AdmissionCode=PA.AdmissionCode)

DELETE ServiceResultDetail WHERE ServiceResultCode = @ServiceResultCode

INSERT INTO ServiceResultDetail (ServiceResultCode, ServiceRowID, RowID, ServiceHead,
	ServiceComponentCode, ServiceComponentUnitCode, TestMachineCode, CostPrice, SalePrice,
	Componentvalue, LowerReferenceValue, UpperReferenceValue, Comments, Remarks, Componentvalue2,
	DeliveryDate, PrintOnReport)
SELECT 
	ServiceResultCode=@ServiceResultCode,
	SrvRowID=D.SrvRowID,
	RowID=SB.ROWID,   
	ServiceHead=SB.ServiceHead,   
	ServiceComponentCode=SB.ServiceComponentCode,   
	ServiceComponentUnitCode= (SELECT S.ServiceComponentUnitCode FROM ServiceComponent S WHERE S.ServiceComponentCode = SB.ServiceComponentCode),
	TestMachineCode=1,
	CostPrice=SB.CostPrice,   
	SalePrice=SB.SalePrice,
	Componentvalue=CASE WHEN S.ServiceResultTemplate IS NULL THEN NULL ELSE (SELECT MAX(SRD.ComponentValue) FROM ServiceResultDetail SRD WHERE SRD.ServiceResultCode=S.ServiceResultTemplate AND SRD.ServiceComponentCode=SB.ServiceComponentCode) END,
	LowerReferenceValue=CASE WHEN S.ServiceResultTemplate IS NULL THEN NULL ELSE (SELECT MAX(SRD.LowerReferenceValue) FROM ServiceResultDetail SRD WHERE SRD.ServiceResultCode=S.ServiceResultTemplate AND SRD.ServiceComponentCode=SB.ServiceComponentCode) END,
	UpperReferenceValue=CASE WHEN S.ServiceResultTemplate IS NULL THEN NULL ELSE (SELECT MAX(SRD.UpperReferenceValue) FROM ServiceResultDetail SRD WHERE SRD.ServiceResultCode=S.ServiceResultTemplate AND SRD.ServiceComponentCode=SB.ServiceComponentCode) END,
	Comments=CASE WHEN S.ServiceResultTemplate IS NULL THEN NULL ELSE (SELECT MAX(SRD.Comments) FROM ServiceResultDetail SRD WHERE SRD.ServiceResultCode=S.ServiceResultTemplate AND SRD.ServiceComponentCode=SB.ServiceComponentCode) END,
	Remarks=CASE WHEN S.ServiceResultTemplate IS NULL THEN NULL ELSE (SELECT MAX(SRD.Remarks) FROM ServiceResultDetail SRD WHERE SRD.ServiceResultCode=S.ServiceResultTemplate AND SRD.ServiceComponentCode=SB.ServiceComponentCode) END,
	Componentvalue2=CASE WHEN S.ServiceResultTemplate IS NULL THEN NULL ELSE (SELECT MAX(SRD.ComponentValue2) FROM ServiceResultDetail SRD WHERE SRD.ServiceResultCode=S.ServiceResultTemplate AND SRD.ServiceComponentCode=SB.ServiceComponentCode) END,
	DeliveryDate=D.DeliveryDate,
	PrintOnReport=SB.PrintOnReport
FROM
	ServiceHeader H,
	ServiceDetail D,
	Service S,
	ServiceBreakUp SB   
WHERE
	H.ServiceInvCode = @ServiceInvCode AND
	H.ServiceInvCode = D.ServiceInvCode AND
	D.ServiceCode = S.ServiceCode AND
	S.ResultRequired='Y' AND
	S.ServiceCode=SB.ServiceCode
ORDER BY 
	D.SrvRowID,
	SB.ServiceHead,
	RowID

IF @@ERROR <> 0 OR @@ROWCOUNT <= 0
BEGIN
	RaisError('Problem while Inserting Service Result Detail Rows', 16, 1)
	RETURN -1
END

UPDATE ServiceResultHeader SET Posted='N' WHERE ServiceResultCode=@ServiceResultCode

RETURN 0
GO

-- SP_REGIONAREASALES (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_REGIONAREASALES 
	@ar_regcode INT, 
	@ar_startdate datetime, 
	@ar_enddate datetime, 
	@ReportGrouping CHAR(1), 
	@GroupList Varchar(8000),
	@pricetype INT,
	@includebonus INT AS
/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'reportdata' table to be used for cross tabulation of
	areas of a region and items selected depending upon the grouping criteria selected.

PARAMETER DESCRIPTION :
	@ar_startdate, @ar_enddate = Determine the period of report
	@ReportGrouping = The criteria for grouping the items in report
	@GroupList = A comma separated list of values to be filtered while grouping the record set
	@PriceType = (1 = Actual Price, 2 = Sale price, 3 = Purchase Price, 4 = Avg. Price)
	@includebonus = (1 = Include bonusqty into sales else ignore it
*/
DELETE ReportData    
DECLARE @Tab_GroupList TABLE (CODE INT NOT NULL)
DECLARE @Tab_ItemList TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_GroupList SELECT CODE FROM udf_StringToTabl(@GroupList, ',')
INSERT INTO @Tab_ItemList SELECT CODE FROM udf_selectitems(@ReportGrouping, @GroupList)

DELETE ReportData    
INSERT INTO ReportData (code1, code2, code3, code4, name1, name2, name3, name4, name5, name6, name7, name8, value1, value2)  
SELECT  Code1=S.ICODE,   
	Code2=S.AREACODE,    
	Code3=S.REGIONCODE,    
	Code4=CASE @ReportGrouping 
		WHEN 'M' THEN I.MANFCODE
		WHEN 'C' THEN I.ICatCode
		WHEN 'L' THEN I.ICCode
		ELSE I.PACKCODE END,   
	Name1=I.NAME,   
	Name2=(SELECT AREA.SHORTNAME FROM AREA WHERE AREACODE = S.AREACODE),   
	Name3=(SELECT NAME FROM REGION WHERE REGIONCODE = S.REGIONCODE),   
	Name4=CASE @ReportGrouping 
		WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE  = I.ManfCode)
		WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE  = I.ICatCode)
		WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE  = I.ICCode)
		ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE  = I.PACKCODE) END,   
	Name5=I.CUSTOMICODE,   
	Name6=I.PackingDesc,
	Name7=(SELECT AREA.SHORTNAME FROM AREA WHERE AREACODE = S.AREACODE),
	Name8=RTRIM(LTRIM(STR(S.ICODE))), 
	Value1= SUM(QTY),   
	Value2 = ROUND(SUM(
				CASE @pricetype 
				WHEN 1 THEN NETAMT
				WHEN 2 THEN Qty * ROUND(I.SalePrice / CASE I.PackUnits WHEN 0 THEN 1 ELSE I.PackUnits END, 2)
				WHEN 3 THEN Qty * ROUND(I.PurPrice / CASE I.PackUnits WHEN 0 THEN 1 ELSE I.PackUnits END, 2)
				WHEN 4 THEN Qty * I.AvgPrice 
				END), 0)
FROM    
	(SELECT INVNO=-1,
		ICODE=I.ICODE,
		CUSTCODE=-1,
		QTY = 0,
		NETAMT=0,
		A.AREACODE,
		R.REGIONCODE
	FROM
		AREA A,
		REGION R,
		(SELECT ICODE=MIN(code) FROM @Tab_ItemList) I
	WHERE
		R.REGIONCODE = @ar_regcode AND
		R.REGIONCODE = A.REGIONCODE
	UNION ALL
	SELECT INVNO=-1,
		ICODE=I.ICODE,
		CUSTCODE=-1,
		QTY = 0,
		NETAMT=0,
		A.AREACODE,
		A.REGIONCODE
	FROM
		(SELECT AREACODE=MIN(AREACODE), REGIONCODE FROM AREA WHERE REGIONCODE = @ar_regcode GROUP BY REGIONCODE) A,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	UNION ALL
	SELECT INVNO=SL.SALEINVCODE,
		SD.ICODE,
		CUSTCODE=SL.CUSTCODE,
		QTY = ISNULL(Sum(SD.looseqty + CASE WHEN @includebonus = 1 THEN SD.bonusqty ELSE 0 END), 0),
		NETAMT=Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
				(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2),
		C.AREACODE,
		R.REGIONCODE
	FROM
		SALELEDGER SL,
		SALEDETAIL SD,
		CUSTOMER C,
		AREA A,
		REGION R, 
		@Tab_ItemList I
	WHERE
		R.REGIONCODE = @ar_regcode AND
		R.REGIONCODE = A.REGIONCODE AND
		A.AREACODE = C.AREACODE AND
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate AND
		SD.ICODE = I.CODE
	GROUP BY
		SL.SaleInvCode,
		SD.ICODE,
		SL.CustCode,
		R.REGIONCODE,
		C.AREACODE,
		SL.DiscPerc
	UNION ALL
	SELECT INVNO=SL.SRINVCODE,
		SD.ICODE,
		CUSTCODE=SL.CUSTCODE,
		QTY = - ISNULL(Sum(SD.looseqty + CASE WHEN @includebonus = 1 THEN SD.bonusqty ELSE 0 END), 0),
		NETAMT= - Round(ISNULL(SUM((SD.looseqty * SD.SRPrice) *
				(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2),
		C.AREACODE,
		R.REGIONCODE
	FROM
		SRLEDGER SL,
		SRDETAIL SD,
		CUSTOMER C,
		AREA A,
		REGION R, 
		@Tab_ItemList I
	WHERE
		R.REGIONCODE = @ar_regcode AND
		R.REGIONCODE = A.REGIONCODE AND
		A.AREACODE = C.AREACODE AND
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SRINVCODE = SD.SRINVCODE AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate AND
		SD.ICODE = I.CODE
	GROUP BY
		SL.SRInvCode,
		SD.ICODE,
		SL.CustCode,
		R.REGIONCODE,
		C.AREACODE,
		SL.DiscPerc) S,
	ITEM I,
	ITEMCATEGORY IC  
WHERE
	S.ICode = I.ICode AND I.ICatCode = IC.ICatCode AND I.ICODE IN (SELECT CODE FROM @Tab_ItemList)
GROUP BY
	S.ICODE,
	S.REGIONCODE,
	S.AREACODE,
	I.Name,
	I.CustomICode,
	I.PackingDesc,
	I.ICatCode,
	I.ICCode,
	I.ManfCode,
	I.PackCode
GO

-- SP_REGIONWISESALES (last defined by script catalog)
CREATE PROCEDURE DBO.SP_REGIONWISESALES @ar_startdate datetime, @ar_enddate datetime, @ReportGrouping CHAR(1), @GroupList Varchar(8000), @RegionList Varchar(8000) AS 

/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'reportdata' table to be used for cross tabulation of
	region and items selected depending upon the grouping criteria selected.

PARAMETER DESCRIPTION :
	@ar_startdate, @ar_enddate = Determine the period of report
	@ReportGrouping = The criteria for grouping the items in report
	@GroupList = A comma separated list of values to be filtered while grouping the record set
	@RegionList = A comma separated list of values of regioncode
*/
DELETE ReportData    
DECLARE @Tab_GroupList TABLE (CODE INT NOT NULL)
DECLARE @Tab_ItemList TABLE (CODE INT NOT NULL)
DECLARE @Tab_RegionList TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_GroupList SELECT CODE FROM udf_StringToTabl(@GroupList, ',')
INSERT INTO @Tab_RegionList SELECT CODE FROM udf_StringToTabl(@RegionList, ',')
INSERT INTO @Tab_ItemList SELECT CODE FROM udf_selectitems(@ReportGrouping, @GroupList)

INSERT INTO ReportData (code1, code2, code3, name1, name2, name3, name4, name5, name6, value1, value2)  
SELECT  Code1=S.ICODE,   
	Code2=S.REGIONCODE,    
	Code3=CASE @ReportGrouping 
		WHEN 'M' THEN I.MANFCODE
		WHEN 'C' THEN I.ICatCode
		WHEN 'L' THEN I.ICCode
		ELSE I.PACKCODE END,   
	Name1=I.NAME,   
	Name2=(SELECT NAME FROM REGION WHERE REGIONCODE = S.REGIONCODE),   
	Name3=CASE @ReportGrouping 
		WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE  = I.ManfCode)
		WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE  = I.ICatCode)
		WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE  = I.ICCode)
		ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE  = I.PACKCODE) END,   
	Name4=I.CUSTOMICODE,   
	Name5=I.PackingDesc,
	Name6=RTRIM(LTRIM(STR(S.ICODE))), 
	Value1= SUM(QTY),   
	Value2 = ROUND(SUM(NETAMT), 0)
FROM    
	(SELECT INVNO=-1,
		ICODE=I.ICODE,
		CUSTCODE=-1,
		QTY = 0,
		NETAMT=0,
		R.REGIONCODE
	FROM
		(SELECT RegionCode=CODE FROM @Tab_RegionList) R,
		(SELECT ICODE=MIN(code) FROM @Tab_ItemList) I
	UNION ALL
	SELECT INVNO=-1,
		ICODE=I.ICODE,
		CUSTCODE=-1,
		QTY = 0,
		NETAMT=0,
		R.REGIONCODE
	FROM
		(SELECT RegionCode=MIN(CODE) FROM @Tab_RegionList) R,
		(SELECT ICODE=Code FROM @Tab_ItemList) I
	UNION ALL
	SELECT INVNO=SL.SALEINVCODE,
		SD.ICODE,
		CUSTCODE=SL.CUSTCODE,
		QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		NETAMT=Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
				(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2),
		R.REGIONCODE
	FROM
		SALELEDGER SL,
		SALEDETAIL SD,
		CUSTOMER C,
		AREA A,
		(SELECT RegionCode=CODE FROM @Tab_RegionList) R,
		@Tab_ItemList I
	WHERE
		R.REGIONCODE = A.REGIONCODE AND
		A.AREACODE = C.AREACODE AND
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate AND
		SD.ICODE = I.CODE
	GROUP BY
		SL.SaleInvCode,
		SD.ICODE,
		SL.CustCode,
		R.REGIONCODE,
		SL.DiscPerc
	UNION ALL
	SELECT INVNO=SL.SRINVCODE,
		SD.ICODE,
		CUSTCODE=SL.CUSTCODE,
		QTY = - ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		NETAMT= - Round(ISNULL(SUM((SD.looseqty * SD.SRPrice) *
				(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2),
		R.REGIONCODE
	FROM
		SRLEDGER SL,
		SRDETAIL SD,
		CUSTOMER C,
		AREA A,
		(SELECT RegionCode=CODE FROM @Tab_RegionList) R,
		@Tab_ItemList I
	WHERE
		R.REGIONCODE = A.REGIONCODE AND
		A.AREACODE = C.AREACODE AND
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SRINVCODE = SD.SRINVCODE AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate AND
		SD.ICODE = I.CODE
	GROUP BY
		SL.SRInvCode,
		SD.ICODE,
		SL.CustCode,
		R.REGIONCODE,
		SL.DiscPerc) S,
	ITEM I,
	ITEMCATEGORY IC  
WHERE
	S.ICode = I.ICode AND I.ICatCode = IC.ICatCode AND I.ICODE IN (SELECT CODE FROM @Tab_ItemList)
GROUP BY
	S.ICODE,
	S.REGIONCODE,
	I.Name,
	I.CustomICode,
	I.PackingDesc,
	I.ICatCode,
	I.ICCode,
	I.ManfCode,
	I.PackCode
GO

-- sp_RejectInstallment (last defined by script catalog)
CREATE PROCEDURE DBO.sp_RejectInstallment
	@StartCode INT,
	@EndCode Int, 
	@UserCode SMALLInt
AS

DECLARE @totalrows INT
UPDATE InstallmentHeader
SET Rejected='Y', RejectedBy = @UserCode, RejectedOn=GetDate()
WHERE InstallmentCode BETWEEN @StartCode AND @EndCode AND Posted='N' AND Approved='N'

Set @totalrows = @@RowCount
IF @totalrows=0
BEGIN
	RaisError( 'No Installment Estimate available for Rejection' ,16,1)
	RETURN -1
END

Return 0
GO

-- SP_Repair_NetRate_RPP (last defined by script catalog)
CREATE   PROCEDURE SP_Repair_NetRate_RPP
	@upd_NetRate_IN_Pur tinyint, @upd_RPP_IN_Pur tinyint, @upd_RPP_IN_Item tinyint
AS 
/*
Author : M. Azhar Inayat
Procedure Description:
	As the name signifies, this procedure will be used to Update 
	'NetRate', 'RecentPurPrice' in purchase invoice each line item
	Moreover it also updates the 'RecentPurPrice' column in 'Item' Table

Parameter Description:
	@upd_NetRate_IN_Pur (1 Stands for Update 'NetRate' column in 'PurDetail' Table)
	@upd_RPP_IN_Pur (1 Stands for Update 'RecentPurPrice' in 'PurDetail' Table)
	@upd_RPP_IN_Item (1 Stands for Update 'RecentPurPrice' in 'Item' Table)
*/

IF @upd_NetRate_IN_Pur = 1
BEGIN
/*
	Fetch NetRate Computations and Update Respective Rows for effective NetRate
	then use the same NetRate and assign it to NetRate column in purdetail 
*/
	UPDATE PurDetail
	SET PurDetail.NetRate = T.NetRate
	FROM
		PurDetail, 
		(SELECT
			PD.PurInvCode, PD.ICode, PD.PurRowID,
			NetRate= ROUND(((PD.ItemValue + ((PD.ItemValue / Pur.GrossValue) * Pur.InvLevelCharges)) / PD.TotQty), 5)
		FROM
			(SELECT
				P.PurInvCode,
				D.ICode,
				D.PurRowID,
				TotQty=(D.PackQty + D.LooseQty + D.BonusQty),
				ItemValue= 
					ROUND(
						((D.LooseQty + D.PackQty) * D.PurPrice * (1 - D.DiscPerc * .01)) + 
						ROUND(D.UnitSalesTax * (D.PackQty + D.LooseQty + D.BonusQty), 2) +
						ROUND((D.LooseQty + D.PackQty) * D.PurPrice * (1 - D.DiscPerc * .01) * D.GSTPERC * 0.01, 2), 2)
			FROM
				PurLedger P, PurDetail D
			WHERE
				P.PurInvCode = D.PurInvCode) PD,
			(SELECT
				PU.PurInvCode,
				InvLevelCharges=PU.MiscCharges + PU.InvGSTValue - PU.FlatDisc - PU.DiscPercValue,
				PU.GrossValue
			FROM
				(SELECT
					P.PurInvCode, 
					GrossValue= 
						SUM(ROUND(
								((D.LooseQty + D.PackQty) * D.PurPrice * (1 - D.DiscPerc * .01)) + 
								ROUND(D.UnitSalesTax * (D.PackQty + D.LooseQty + D.BonusQty), 2) +
								ROUND((D.LooseQty + D.PackQty) * D.PurPrice * (1 - D.DiscPerc * .01) * D.GSTPERC * 0.01, 2), 2)),
					DiscPercValue= 
						SUM( 
							((D.LooseQty + D.PackQty) * D.PurPrice * (1 - D.DiscPerc * .01)) * P.DiscPerc * .01),
					InvGSTValue= 
						ROUND(((Round(
							SUM((D.LooseQty + D.PackQty) * D.PurPrice * (1 - D.DiscPerc * .01)) * 
								(1 - P.DiscPerc * 0.01), 2)) - P.FlatDisc) * P.InvGSTPERC1 * 0.01, 2),
					P.MiscCharges,
					P.FlatDisc
				FROM
					PurLedger P, PurDetail D
				WHERE
					P.PurInvCode = D.PurInvCode
				GROUP BY
					P.PurInvCode,
					P.DiscPerc,
					P.FlatDisc,
					P.MiscCharges,
					P.FlatDisc,
					P.InvGSTPerc1) PU) PUR
		WHERE
			PD.PurInvCode = Pur.PurInvCode) T
	WHERE
		T.PurInvCode = PurDetail.PurInvCode AND PurDetail.PurRowID = T.PurRowID
END

IF @upd_RPP_IN_Pur = 1
BEGIN
/* 
	Fetch Latest Row of Pack Purchase for each item before the current purrowid 
	then use the same max of purrowid for each item to get NetRate and
	assign it to RecentPurPrice column in purdetail 
*/
	UPDATE PurDetail
	SET RecentPurPrice = 
		ISNULL(
			CASE WHEN PREV.PREVID IS NULL THEN 0 
			ELSE (SELECT ROUND(PD.NETRATE, 2) FROM PURDETAIL PD WHERE PD.PURROWID = PREV.PREVID) 
			END
		, 0)
	FROM 
		PURDETAIL PDD
		LEFT OUTER JOIN
		(SELECT D.ICode, D.PURRowID,
			PREVID = (SELECT
				PID=MAX(DD.PurRowID)
			FROM
				PurLedger P, PurDetail DD
			WHERE
				DD.ICODE = D.ICODE AND
				DD.PurRowID < D.PurRowID AND
				P.PurInvCode = DD.PurInvCode AND 
				P.PURCATCODE IN (1, 2)
			GROUP BY 
				DD.ICode)
 
		FROM PurDetail D) PREV ON (PDD.PURROWID = PREV.PURROWID)
END

IF @upd_RPP_IN_Item = 1
BEGIN
/* 
	Fetch Latest Row of Pack Purchase for each item in item table
	then use the same max of purrowid for each item to get NetRate and
	assign it to RecentPurPrice column in Item
*/
	UPDATE Item
	SET RecentPurPrice = ISNULL(ROUND(RPP.NetRate, 2), RecentPurPrice)
	FROM 
		Item I,
		(SELECT DD.ICode, DD.NetRate 
		FROM 
			PurDetail DD,
			(SELECT
				D.ICode,
				PID=MAX(D.PurRowID)
			FROM
				PurLedger P, PurDetail D
			WHERE
				P.PurInvCode = D.PurInvCode AND 
				P.PURCATCODE IN (1, 2)
			GROUP BY 
				D.ICode) P
		WHERE DD.PurRowID = P.PID) RPP
	
	WHERE
		I.ICode = RPP.ICode
END
GO

-- SP_RepairBatchWiseCorruptedStock (last defined by script catalog)
CREATE PROCEDURE SP_RepairBatchWiseCorruptedStock 
AS

DECLARE @Godown TABLE (Code INT, ID INT IDENTITY(1,1))
DECLARE @GCode INT, @RowID INT, @TotRows INT

INSERT INTO @Godown
SELECT GCode FROM Godown

DELETE ReportData

SET @TotRows = ISNULL((SELECT Count(GCode) FROM Godown), 0)

SET @RowID=1

WHILE @RowID <= @TotRows
BEGIN
	SET @GCode = (SELECT Code FROM @Godown WHERE ID = @RowID)

	DELETE ReportData

	INSERT INTO ReportData(Code1, Value1)
	SELECT 
		T.ICode, 
		SUM(CASE WHEN T.Type <> 'ST' THEN T.Net  ELSE 0 END) AS Net 
	FROM
		(SELECT
			ICode, SUM( PackQty * PackUnits + BonusQty * PackUnits ) AS Net, 'PU' AS Type 
		FROM 
			PurDetail, PurLedger
		WHERE 
			PurLedger.PurCatCode IN (1,2) AND 
			PurLedger.PurInvCode = PurDetail.PurInvCode AND 
			Posted = UPPER('Y') AND GCode = @GCode
		GROUP BY 
			ICode
		UNION ALL
		SELECT 
			ICode, SUM(LooseQty +  BonusQty  ) AS Net, 'PU' AS Type
		FROM 
			PurDetail, PurLedger
		WHERE 
			PurLedger.PurCatCode IN (3,7,8) AND 
			PurLedger.PurInvCode = PurDetail.PurInvCode AND 
			Posted = UPPER('Y') AND GCode = @GCode
		GROUP BY 
			ICode
		UNION ALL
		SELECT 
			ICode, -SUM(LooseQty +  BonusQty) AS Net, 'PR' AS Type
		FROM PRDetail
		WHERE GCode = @GCode
		GROUP BY ICode
		UNION ALL
		SELECT 
			ICode, -SUM(LooseQty + BonusQty ) AS Net, 'SL' AS Type
		FROM SaleDetail
		WHERE 
			Due IS NULL AND GCode = @GCode
		GROUP BY 
			ICode
		UNION ALL
		SELECT 
			ICode, SUM(LooseQty + BonusQty) AS Net, 'SR' AS Type
		FROM 
			SRDetail
		WHERE 
			GCode = @GCode
		GROUP BY 
			ICode
		UNION ALL
		SELECT 
			ICode, -SUM(Qty) AS Net, 'IS' AS Type
		FROM 
			IssueDetail, IssueHeader
		WHERE 
			IssueHeader.IssueInvCode = IssueDetail.IssueInvCode AND 
			GCode = @GCode
		GROUP BY 
			ICode
		UNION ALL
		SELECT 
			ICode, -SUM(DueSatisfyQty) AS Net, 'DS' AS Type
		FROM 
			DueSatisfyDetail
		WHERE 
			GCode = @GCode
		GROUP BY 
			ICode
		UNION ALL
		SELECT 
			ICode, SUM(Qty) AS Net, 'DS' AS Type
		FROM 
			ReceipTHeader, ReceipTDetail
		WHERE 
			ReceipTHeader.Posted='Y' AND
			ReceipTHeader.ReceiptInvCode = ReceipTDetail.ReceiptInvCode AND 
			GCode = @GCode
		GROUP BY 
			ICode
		UNION ALL
		SELECT 
			ICode, SUM(LooseQty) AS Net, 'AI' AS Type
		FROM 
			AdjHeader,AdjDetail
		WHERE 
			AdjHeader.Posted='Y' AND
			AdjHeader.AdjCatCode=1 AND
			AdjHeader.AdjCode=AdjDetail.AdjCode AND 
			AdjDetail.GCode = @GCode
		GROUP BY 
			ICode
		UNION ALL
		SELECT 
			ICode, -SUM(LooseQty) AS Net, 'AD' AS Type
		FROM 
			AdjHeader, AdjDetail
		WHERE 
			AdjHeader.Posted='Y' AND
			AdjHeader.AdjCatCode=2 AND
			AdjHeader.AdjCode=AdjDetail.AdjCode AND 
			AdjDetail.GCode = @GCode
		GROUP BY 
			ICode
		UNION ALL
		/* TRANSFER SOURCE GODOWN*/
		SELECT ICode, -SUM(Qty) AS Net, 'TM' AS Type
		FROM 
			THeader, TDetail
		WHERE 
			THeader.Posted='Y' AND
			THeader.SGCode = @GCode AND
			THeader.TransCode=TDetail.TransCode 
		GROUP BY 
			ICode
		/*END*/
		UNION ALL
		/* TRANSFER TARGET GODOWN*/
		SELECT 
			ICode, SUM(Qty) AS Net, 'TN' AS Type
		FROM 
			THeader, TDetail
		WHERE 
			THeader.Posted='Y' AND
			THeader.DGCode = @GCode AND
			THeader.TransCode=TDetail.TransCode 
		GROUP BY 
			ICode
		/*END*/
		UNION ALL
		SELECT 
			ICode, SUM(CurrQty) AS Net, 'ST' AS Type
		FROM 
			GodownDetail
		WHERE
			GCode = @GCode
		GROUP BY 
			ICode) T, Item
	WHERE 
		T.ICode = Item.ICode
	GROUP BY 
		T.ICode, 
		Item.name
	HAVING 	SUM(CASE WHEN T.Type = 'ST' THEN T.Net ELSE 0 END) <> 
		SUM(CASE WHEN T.Type <> 'ST' THEN T.Net ELSE 0 END)
	ORDER BY T.ICode

	UPDATE ReportData
	SET ReportData.Date1=
		ISNULL( 
			(SELECT MIN(D.expiry) FROM GodownDetail D
			WHERE ReportData.Code1=D.ICode AND D.GCode = @GCode), 
		ISNULL((SELECT MIN(Expiry) FROM PurDetail 
		WHERE PurUtn IN 
			(SELECT MAX(purutn) FROM PurDetail P 
			WHERE P.ICode= ReportData.Code1) ), '12/12/2010 00:00:00') )

	DELETE FROM GodownDetail 
	WHERE ICode IN (SELECT Code1 FROM ReportData) AND GCode = @GCode

	UPDATE ReportData SET Code2 = @GCode
	
	INSERT INTO GodownDetail (GCode, ICode, CurrQty, Batch, Expiry, Priority, ManfDate)
	SELECT Code2, Code1, Value1, 
		ISNULL((SELECT Batch FROM PurDetail 
		WHERE PurUtn IN 
			(SELECT MAX(PurUtn) FROM PurDetail P 
			WHERE P.ICode= ReportData.Code1) ), '.'), 
		Date1, 10, Null
	FROM ReportData
	WHERE Value1 > 0

	SET @RowID = @RowID + 1
END
GO

-- SP_RepairDB (last defined by script catalog)
CREATE PROC DBO.SP_RepairDB @DB VARCHAR(255), @Option INT
AS
SET NOCOUNT ON
DECLARE @Qry VARCHAR(1000)

IF @DB IS NULL
	RETURN 0

IF @Option IS NULL
	RETURN 0

SET @Qry = 'dbcc CheckDB(''' + @DB + ''''
IF @Option = 0
	SET @Qry = @Qry + ''
IF @Option = 1
	SET @Qry = @Qry + ', REPAIR_FAST'
IF @Option = 2
	SET @Qry = @Qry + ', REPAIR_REBUILD'
IF @Option = 3
	SET @Qry = @Qry + ', REPAIR_ALLOW_DATA_LOSS'

SET @Qry = @Qry + ') with tableresults, ALL_ERRORMSGS'

TRUNCATE TABLE DBCC_History

INSERT INTO DBCC_History(
ErrorID, LevelID, StateID, MessageText, RepairLevel, StatusID,
DbId, ObjectId, IndId, FileID, PageID, SlotID, RefFileID, 
RefPageID, RefSlotID, AllocationID)
EXEC (@Qry)
IF @@Error <> 0
BEGIN
	RETURN @@Error
END

INSERT INTO DBO.DBRepairLog (Date, RepairLevel, ObjectName)
SELECT Date=GETDATE(), 
	RepairLevel=CASE @Option WHEN 1 THEN 'REPAIR_FAST' WHEN 2 THEN 'REPAIR_REBUILD' WHEN 3 THEN 'REPAIR_ALLOW_DATA_LOSS' ELSE '' END, 
	ObjectName=@DB

RETURN 0
GO

-- SP_RePrioritizeStockBatches (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_RePrioritizeStockBatches @Method INT
AS

DECLARE @batch VARCHAR(100), @ItemName Varchar(100)
DECLARE @ICode INT, @OldICode INT, @errcode INT, @Priority INT
DECLARE @Expiry DATETIME, @InDate DATETIME

/*
Author : Muhammad Azhar Inayat
Date : May 03, 2011
Purpose : Implement the selected/prefered Stock Allocation Method
*/

IF @Method = 1	/* Shortest Expiry First Method */
BEGIN
	UPDATE GodownDetail SET Priority=10
END


IF @Method = 2	/* FIFO Method*/
BEGIN
	/*
	Step - 1 :- Set Default Priority To Each Batch in Stock
	*/
	UPDATE GodownDetail SET Priority=9
	
	SET @OldICode = NULL
	SET @Priority = 0
	/*
	Step - 2 :- Find Min InDate for each Batch in Stock
	*/
	
	DECLARE cursor1 CURSOR FOR
	SELECT T.ICode, T.Batch, T.Expiry, InDate=MIN(T.InDate)
	FROM
		(SELECT GD.ICode, GD.Batch, GD.Expiry, InDate=MIN(H.PostDate)
		FROM PurDetail D, PurLedger H, GodownDetail GD
		WHERE H.Posted = 'Y' AND 
			H.PurInvCode = D.PurInvCode AND 
			D.ICode = GD.ICode AND
			D.Batch = GD.Batch AND
			D.Expiry = GD.Expiry
		GROUP BY
			GD.ICode,
			GD.Batch, 
			GD.Expiry
		UNION ALL
		SELECT GD.ICode, GD.Batch, GD.Expiry, InDate=MIN(H.PostDate)
		FROM SRDetail D, SRLedger H, GodownDetail GD
		WHERE H.Posted = 'Y' AND 
			H.SRInvCode = D.SRInvCode AND 
			D.ICode = GD.ICode AND
			D.Batch = GD.Batch AND
			D.Expiry = GD.Expiry
		GROUP BY
			GD.ICode,
			GD.Batch, 
			GD.Expiry
		UNION ALL
		SELECT GD.ICode, GD.Batch, GD.Expiry, InDate=MIN(H.PostDate)
		FROM ReceiptDetail D, ReceiptHeader H, GodownDetail GD
		WHERE H.Posted = 'Y' AND 
			H.ReceiptInvCode = D.ReceiptInvCode AND 
			D.ICode = GD.ICode AND
			D.Batch = GD.Batch AND
			D.Expiry = GD.Expiry
		GROUP BY
			GD.ICode,
			GD.Batch, 
			GD.Expiry
		UNION ALL
		SELECT GD.ICode, GD.Batch, GD.Expiry, InDate=MIN(H.Date)
		FROM AdjDetail D, AdjHeader H, GodownDetail GD
		WHERE H.Posted = 'Y' AND 
			AdjCatCode=1 AND
			H.AdjCode = D.AdjCode AND 
			D.ICode = GD.ICode AND
			D.Batch = GD.Batch AND
			D.Expiry = GD.Expiry
		GROUP BY
			GD.ICode,
			GD.Batch, 
			GD.Expiry) T
	GROUP BY
		T.ICode,
		T.Batch, 
		T.Expiry
	ORDER BY
		ICode,
		InDate,
		Expiry,
		Batch
	
	OPEN cursor1

	/* Step 3 Update Priority as it suits */	
	FETCH NEXT FROM cursor1
	INTO @ICode, @Batch, @Expiry, @InDate
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF @ICode = @OldICode
			SET @Priority = @Priority + 1
		ELSE
			SET @Priority = 1
	
		IF @Priority > 8
			SET @Priority = 8
	
		UPDATE GodownDetail SET Priority = @Priority WHERE ICode=@ICode AND Batch = @Batch AND Expiry = @Expiry
	
		SET @OldICode = @ICode
	
		FETCH NEXT FROM cursor1 INTO @ICode, @Batch, @Expiry, @InDate
	END
	CLOSE cursor1
	DEALLOCATE cursor1
END

IF @Method = 3	/* LIFO Method*/
BEGIN
	/*
	Step - 1 :- Set Default Priority To Each Batch in Stock
	*/
	UPDATE GodownDetail SET Priority=30
	
	SET @OldICode = NULL
	SET @Priority = 10
	/*
	Step - 2 :- Find Lastest InDate for each Batch in Stock
	*/
	
	DECLARE cursor2 CURSOR FOR
	SELECT T.ICode, T.Batch, T.Expiry, InDate=MAX(T.InDate)
	FROM
		(SELECT GD.ICode, GD.Batch, GD.Expiry, InDate=MAX(H.PostDate)
		FROM PurDetail D, PurLedger H, GodownDetail GD
		WHERE H.Posted = 'Y' AND 
			H.PurInvCode = D.PurInvCode AND 
			D.ICode = GD.ICode AND
			D.Batch = GD.Batch AND
			D.Expiry = GD.Expiry
		GROUP BY
			GD.ICode,
			GD.Batch, 
			GD.Expiry
		UNION ALL
		SELECT GD.ICode, GD.Batch, GD.Expiry, InDate=MAX(H.PostDate)
		FROM SRDetail D, SRLedger H, GodownDetail GD
		WHERE H.Posted = 'Y' AND 
			H.SRInvCode = D.SRInvCode AND 
			D.ICode = GD.ICode AND
			D.Batch = GD.Batch AND
			D.Expiry = GD.Expiry
		GROUP BY
			GD.ICode,
			GD.Batch, 
			GD.Expiry
		UNION ALL
		SELECT GD.ICode, GD.Batch, GD.Expiry, InDate=MAX(H.PostDate)
		FROM ReceiptDetail D, ReceiptHeader H, GodownDetail GD
		WHERE H.Posted = 'Y' AND 
			H.ReceiptInvCode = D.ReceiptInvCode AND 
			D.ICode = GD.ICode AND
			D.Batch = GD.Batch AND
			D.Expiry = GD.Expiry
		GROUP BY
			GD.ICode,
			GD.Batch, 
			GD.Expiry
		UNION ALL
		SELECT GD.ICode, GD.Batch, GD.Expiry, InDate=MAX(H.Date)
		FROM AdjDetail D, AdjHeader H, GodownDetail GD
		WHERE H.Posted = 'Y' AND 
			AdjCatCode=1 AND
			H.AdjCode = D.AdjCode AND 
			D.ICode = GD.ICode AND
			D.Batch = GD.Batch AND
			D.Expiry = GD.Expiry
		GROUP BY
			GD.ICode,
			GD.Batch, 
			GD.Expiry) T
	GROUP BY
		T.ICode,
		T.Batch, 
		T.Expiry
	ORDER BY
		ICode,
		InDate DESC,
		Expiry,
		Batch
	
	OPEN cursor2
	
	/* Step 3 Update Priority as it suits */	
	FETCH NEXT FROM cursor2
	INTO @ICode, @Batch, @Expiry, @InDate
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF @ICode = @OldICode
			SET @Priority = @Priority + 1
		ELSE
			SET @Priority = 11
	
		IF @Priority > 29
			SET @Priority = 29
	
		UPDATE GodownDetail SET Priority = @Priority WHERE ICode=@ICode AND Batch = @Batch AND Expiry = @Expiry
	
		SET @OldICode = @ICode
	
		FETCH NEXT FROM cursor2 INTO @ICode, @Batch, @Expiry, @InDate
	END
	CLOSE cursor2
	DEALLOCATE cursor2
END
GO

-- SP_RequestHttpWebService (last defined by script catalog)
CREATE PROCEDURE [dbo].[SP_RequestHttpWebService]
	@Url varchar(1024),
	@HttpMethod varchar(10),
	@ParamsValues varchar(8000),    -- param1=value&param2=value
	@SoapAction varchar(1024) = null
AS
BEGIN
SET NOCOUNT ON;

if @HttpMethod in ('get','GET') and len(@ParamsValues) > 0
begin
	set @Url = @Url + '?' + @ParamsValues
end

declare @obj int, @response varchar(8000),@status varchar(50),@statusText varchar(1024),@method varchar(10)

SET @method = (case when @HttpMethod in ('soap','SOAP') then 'POST' else @HttpMethod end)

exec sp_OACreate 'MSXML2.ServerXMLHttp', @obj out
exec sp_OAMethod @obj, 'Open', null, @method, @Url, false

if @HttpMethod in ('get','GET')
begin
	exec sp_OAMethod @obj, 'send'
end
else if @HttpMethod in ('post','POST')
begin
	exec sp_OAMethod @obj, 'setRequestHeader', null, 'Content-Type', 'application/json' --'application/x-www-form-urlencoded'
	exec sp_OAMethod @obj, 'send', null, @ParamsValues
end
else if @HttpMethod in ('soap','SOAP')
begin
	if @SoapAction is null
		raiserror('@SoapAction is null', 10, 1)

	declare @host varchar(1024)
	SET @host  = @Url
	if @host like 'http://%'
		set @host = right(@host, len(@host) - 7)
	else if @host like 'https://%'
		set @host = right(@host, len(@host) - 8)

	if charindex(':', @host) > 0 and charindex(':', @host) < charindex('/', @host)
		set @host = left(@host, charindex(':', @host) - 1)
	else 
		set @host = left(@host, charindex('/', @host) - 1)

	declare @envelope varchar(8000) 
	SET @envelope = '<?xml version="1.0" encoding="utf-8"?><soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><{action} xmlns="http://tempuri.org/">{params}</{action}></soap:Body></soap:Envelope>'
	declare @params varchar(8000) 
	SET @params = '' 

	WHILE LEN(@ParamsValues) > 0
	BEGIN
		declare @param varchar(256), @value varchar(256)
		IF charindex('&', @ParamsValues) > 0
		BEGIN
			SET @param = left(@ParamsValues, charindex('&', @ParamsValues) - 1)
			set @value = RIGHT(@param, len(@param) - charindex('=', @param))
			set @param = left(@param, charindex('=', @param) - 1)
			set @params = @params + '<' + @param + '>' + @value + '</'+ @param + '>'
			SET @ParamsValues = right(@ParamsValues, LEN(@ParamsValues) - LEN(@param + '=' + @value + '&'))
		END
		ELSE
		BEGIN
			set @value = RIGHT(@ParamsValues, len(@ParamsValues) - charindex('=', @ParamsValues))
			set @param = left(@ParamsValues, charindex('=', @ParamsValues) - 1)
			
			set @params = @params + '<' + @param + '>' + @value + '</'+ @param + '>'
			SET @ParamsValues = NULL
		END
	END

	set @envelope = replace(@envelope, '{action}', @SoapAction)
	set @envelope = replace(@envelope, '{params}', @params)

	set @SoapAction = 'http://tempuri.org/' + @SoapAction

	print @host
	print @SoapAction
	print @envelope

	exec sp_OAMethod @obj, 'setRequestHeader', null, 'Content-Type', 'text/xml; charset=utf-8'
	exec sp_OAMethod @obj, 'setRequestHeader', null, 'Host', @host
	exec sp_OAMethod @obj, 'setRequestHeader', null, 'SOAPAction', @SoapAction
	exec sp_OAMethod @obj, 'send', null, @envelope
end

exec sp_OAGetProperty @obj, 'responseText', @response out
exec sp_OADestroy @obj

select @status as [status], @statusText as [statusText], @response as [response]

END
GO

-- SP_RestrictSelectedClassItems (last defined by script catalog)
CREATE PROCEDURE DBO.SP_RestrictSelectedClassItems
AS
/* Restrict Items of Class 2 IF time is over 7 am and below than 11 pm*/
UPDATE Item SET Restricted = 'Y' WHERE ICCode = 2 AND (DatePart(hh, GETDATE()) > 7 AND DatePart(hh, GETDATE()) < 23)

/* Un-Restrict Items of Class 2 IF time is over 7 am or below 11 pm*/
UPDATE Item SET Restricted = 'N' WHERE ICCode = 2 AND NOT (DatePart(hh, GETDATE()) > 7 AND DatePart(hh, GETDATE()) < 23)

/* Un-Restrict Items of Class 3 IF time is over 7 am and below than 11 pm*/
UPDATE Item SET Restricted = 'N' WHERE ICCode = 3 AND (DatePart(hh, GETDATE()) > 7 AND DatePart(hh, GETDATE()) < 23)

/* Restrict Items of Class 3 IF time is over 7 am or below 11 pm*/
UPDATE Item SET Restricted = 'Y' WHERE ICCode = 3 AND NOT (DatePart(hh, GETDATE()) > 7 AND DatePart(hh, GETDATE()) < 23)
GO

