-- sp_SaleAndReturnCatClassWise (last defined by script catalog)
CREATE PROCEDURE sp_SaleAndReturnCatClassWise  @ad_date datetime ,@ad_ldate datetime AS    

delete from reportdata  
insert into reportdata(name1,code1,name2,value1,value2,value4,value5) 

select  
	CategoryName=(select itemcategory.name from itemcategory where itemcategory.icatcode=A.icatcode),  
	A.iccode,   
	classname=(select name from itemclass where iccode=A.iccode),  
	salevalue=  (select IsNull( sum(round(((SD.looseqty + SD.packqty * SD.packunits) * (SD.saleprice - SD.itemflatdisc)) * (1 - (.01 *  SD.discperc)),2))  ,0)         
		     FROM saledetail SD,
		          saleledger SL,
	  	          item I         
		    WHERE    SL.date between @ad_date and @ad_ldate and 
           		     SL.saleinvcode=SD.saleinvcode and
			     SD.icode=I.icode AND
			     I.iccode=A.iccode AND
			     I.icatcode=A.icatcode ),   
	srvalue = (select IsNull( sum(round(((SRD.looseqty + SRD.packqty * SRD.packunits) * SRD.srprice ) * (1 - (.01 *  SRD.discperc)),2))  ,0)         
		  FROM 	srdetail SRD,
		       	srledger SRL,
		        item I
	          WHERE   SRL.date between @ad_date and @ad_ldate and
		          SRL.srinvcode=SRD.srinvcode and
			  SRD.icode=I.icode AND
			  I.iccode=A.iccode   AND
			  I.icatcode=A.icatcode  ),
	saleqty=  (select IsNull( sum(SD.looseqty+SD.packqty* SD.packunits)  ,0)         
		     FROM saledetail SD,
		          saleledger SL,
	  	          item I         
		    WHERE    SL.date between @ad_date and @ad_ldate and 
           		     SL.saleinvcode=SD.saleinvcode and
			     SD.icode=I.icode AND
			     I.iccode=A.iccode AND
			     I.icatcode=A.icatcode ), 
	srqty = (select IsNull( sum(SRD.looseqty + SRD.packqty * SRD.packunits)  ,0)         
		  FROM 	srdetail SRD,
		       	srledger SRL,
		        item I
	          WHERE   SRL.date between @ad_date and @ad_ldate and
		          SRL.srinvcode=SRD.srinvcode and
			  SRD.icode=I.icode AND
			  I.iccode=A.iccode  AND
			  I.icatcode=A.icatcode )          

from (select distinct item.iccode as iccode , item.icatcode as icatcode
	from 	saledetail,
		saleledger,
		item         
	where saleledger.date between @ad_date and @ad_ldate and
	      saleledger.saleinvcode=saledetail.saleinvcode and
	      saledetail.icode=item.icode      
	union      
       	select distinct item.iccode as iccode , item.icatcode as icatcode
	from 	srdetail,
		srledger,
		item           
	where srledger.date between @ad_date and @ad_ldate and
	      srledger.srinvcode=srdetail.srinvcode and
	      srdetail.icode=item.icode) as A        

update reportdata  set value3 = value1 - value2
GO

-- sp_SaleAndReturnCategoryWise (last defined by script catalog)
CREATE   PROCEDURE sp_SaleAndReturnCategoryWise  
	@ad_date datetime ,@ad_ldate datetime 
AS

delete from reportdata

insert into reportdata(code1,name1,value1,value2,value4,value5)

select  A.icatcode,
	catname=(select name from itemcategory where icatcode=A.icatcode),
	salevalue=  (select IsNull( sum(SD.looseqty * (SD.saleprice - SD.itemflatdisc) * (1 - (.01 *  SD.discperc))),0)
		     FROM saledetail SD,
     			  saleledger SL,
     			  item I
		     WHERE 
       
		 	SL.date between @ad_date and @ad_ldate and
       			SL.saleinvcode=SD.saleinvcode and
		 	SD.icode=I.icode AND
		 	I.icatcode=A.icatcode),
	srvalue = (select IsNull( sum(SRD.looseqty * SRD.srprice * (1 - (.01 *  SRD.discperc))), 0)
		     FROM srdetail SRD,
     			  srledger SRL,
     			  item I
		     WHERE 
       
		 	SRL.date between @ad_date and @ad_ldate and
       			SRL.srinvcode=SRD.srinvcode and
		 	SRD.icode=I.icode AND
		 	I.icatcode=A.icatcode 

		    /* GROUP BY I.icatcode,
         			IC.name*/
	
			),

	saletax=  (select IsNull( sum(SD.looseqty * SD.UnitSalesTax) + SUM(ROUND(SD.looseqty * (SD.saleprice - SD.itemflatdisc) * (1 - (.01 *  SD.discperc)) * SD.GSTPerc * 0.01,2)),0)
		     FROM saledetail SD,
     			  saleledger SL,
     			  item I
		     WHERE 
       
		 	SL.date between @ad_date and @ad_ldate and
       			SL.saleinvcode=SD.saleinvcode and
		 	SD.icode=I.icode AND
		 	I.icatcode=A.icatcode),
	returntax=  (select IsNull( sum(SD.looseqty * SD.UnitSalesTax) + SUM(ROUND(SD.looseqty * SD.srprice * (1 - (.01 *  SD.discperc)) * SD.GSTPerc * 0.01,2)),0)
		     FROM srdetail SD,
     			  srledger SL,
     			  item I
		     WHERE 
       
		 	SL.date between @ad_date and @ad_ldate and
       			SL.srinvcode=SD.srinvcode and
		 	SD.icode=I.icode AND
		 	I.icatcode=A.icatcode)

from (select distinct(item.icatcode) as icatcode from saledetail,saleledger,item 
      where saleledger.date between @ad_date and @ad_ldate and
	    saleledger.saleinvcode=saledetail.saleinvcode and
	    saledetail.icode=item.icode   
	union
	
	select distinct(item.icatcode) as icatcode from srdetail,srledger,item 
        where srledger.date between @ad_date and @ad_ldate and
	    srledger.srinvcode=srdetail.srinvcode and
	    srdetail.icode=item.icode) as A


update reportdata
set value3 = value1 - value2

commit
GO

-- sp_SaleAndReturnCategoryWise_wrt_SaleCat (last defined by script catalog)
Create PROCEDURE sp_SaleAndReturnCategoryWise_wrt_SaleCat  @ad_date datetime, @ad_ldate datetime, @salecategory Char(1) = 'R' AS
Declare @salecatcode SmallInt,@srcatcode SmallInt

IF Upper(@salecategory) = 'W' 
Begin
	Set @salecatcode = 2
	Set @srcatcode = 7
End
ELSE 
Begin
	Set @salecatcode = 3
	Set @srcatcode = 8
End

Truncate Table ReportData
Insert into reportdata(code1,name1,value1,value2)
Select  A.icatcode,
	catname=(select name from itemcategory where icatcode=A.icatcode),
	salevalue=  (select IsNull( sum(round(((SD.looseqty + SD.packqty * SD.packunits) * (SD.saleprice - SD.itemflatdisc)) * (1 - (.01 *  SD.discperc)),2))  ,0)
		     FROM saledetail SD,
     			  saleledger SL,
     			  item I
		     WHERE 
       
		 	SL.date between @ad_date and @ad_ldate and
       			SL.saleinvcode = SD.saleinvcode and
			SL.SaleCatCode = @salecatcode AND
		 	SD.icode=I.icode AND
		 	I.icatcode=A.icatcode 
		     ),
	srvalue = (select IsNull( sum(round(((SRD.looseqty + SRD.packqty * SRD.packunits) * SRD.srprice ) * (1 - (.01 *  SRD.discperc)),2))  ,0)
		     FROM srdetail SRD,
     			  srledger SRL,
     			  item I
		     WHERE 
       
		 	SRL.date between @ad_date and @ad_ldate and
			SRL.srinvcode = SRD.srinvcode and
			SRL.SRCatCode = @srcatcode AND
		 	SRD.icode = I.icode AND
		 	I.icatcode = A.icatcode 
		  )

From (	Select distinct(item.icatcode) as icatcode 
	From saledetail,saleledger,item 
      	Where 	saleledger.date between @ad_date and @ad_ldate and
	    	saleledger.saleinvcode=saledetail.saleinvcode and
	    	saleledger.salecatcode = @salecatcode and
	    	saledetail.icode=item.icode   
	Union
	Select distinct(item.icatcode) as icatcode 
	From srdetail,srledger,item 
        Where 	srledger.date between @ad_date and @ad_ldate and
	    	srledger.srinvcode=srdetail.srinvcode and
	    	srledger.srinvcode = @srcatcode and	
	    	srdetail.icode=item.icode ) as A

Update ReportData Set value3 = value1 - value2
GO

