declare @ln_salesfixdiscacc numeric(5, 0)
declare @ln_miscchargesacc numeric(5, 0)
declare @ln_salesretacc numeric(5, 0)
declare @ln_purchaseacc numeric(5, 0)

select @ln_cashacc      = (Select code from global where name = 'GT_CashACC')
select @ln_equityacc	= (Select code from global where name = 'GT_EquityACC')
select @ln_freightacc	= (Select code from global where name = 'GT_FreightACC')
select @ln_octroiacc	= (Select code from global where name = 'GT_OctroiACC')
select @ln_salestaxacc	= (Select code from global where name = 'GT_AdvanceSalesTaxACC')
select @ln_inventoryacc	= (Select code from global where name = 'GT_InventoryACC')
select @ln_favourableacc= (Select code from global where name = 'GT_FavourableACC')
select @ln_unfavourableacc = (Select code from global where name = 'GT_UnFavourableACC')
/*select @ln_avgpurcostacc = (Select code from global where name = 'GT_AvgPurCostACC'*/
select @ln_salesacc        = (Select code from global where name = 'GT_SalesACC')
select @ln_salesfixdiscacc = (Select code from global where name = 'GT_SalesFixDiscountACC')
select @ln_miscchargesacc  = (Select code from global where name = 'GT_MiscChargesACC')
select @ln_salesretacc     = (Select code from global where name = 'GT_SalesReturnACC')
select @ln_purchaseacc     = (Select code from global where name = 'GT_PurchaseACC')

create table #lt_Accounts
(
	acccode      numeric (5,  0) NOT NULL,
	currbalance  numeric (11, 2) NOT NULL 
)

Insert #lt_Accounts
Select acccode, 0
from   accounts

/**********************************************************************/
/************************** Purchase  *********************************/
/**********************************************************************/

create table #lt_PurchaseSummary
(
	acccode      numeric (5,  0) NOT NULL,
	inventoryAmt numeric (11, 2) NOT NULL,    /*Cost of items and disc on total item cost*/
	NetAmt       numeric (11, 2) NOT NULL,    /*Net Cost including flat discounts, misc charges*/
	flatdisc     numeric (11, 2) NOT NULL,
	misccharges  numeric (11, 2) NOT NULL,
	salestax     numeric (11, 2) NOT NULL
)

insert  #lt_PurchaseSummary
select  Case purledger.PurCatCode
		when 1 THEN @ln_cashacc     /* Cash Purchase */
		when 3 THEN @ln_equityacc   /* Opening Purchase  */
		else   purledger.suppcode     /* Credit Purhase    */
	end,

	IsNull( sum(( (purdetail.looseqty + purdetail.packqty * purdetail.packunits) * purdetail.purprice) * (1 - (.01 * purdetail.discperc))) * (1- (.01 * purledger.discperc)), 0) ,
	IsNull( Round(sum(( (purdetail.looseqty + purdetail.packqty * purdetail.packunits) * purdetail.purprice) * (1 - (.01 * purdetail.discperc))) * (1- (.01 * purledger.discperc)) + purledger.misccharges + purledger.salestax - purledger.flatdisc, 0), 0),
	purledger.flatdisc,
	purledger.misccharges,
	purledger.salestax 

from     purledger,	 
	 purdetail 

where    purledger.date <= @ad_Date and
	 purledger.purinvcode = purdetail.purinvcode 

group by purledger.purinvcode,
	 purledger.suppcode, 
	 purledger.purcatcode,
	 purledger.date,
	 purledger.discperc,
	 purledger.misccharges,
	 purledger.salestax,
	 purledger.flatdisc		

/**********************Debit Inventory***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(inventoryamt), 0) from #lt_PurchaseSummary)
where  #lt_accounts.acccode = @ln_inventoryacc

/**********************credit flatdiscount ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(flatdisc), 0) from #lt_PurchaseSummary)
where  #lt_accounts.acccode = @ln_freightacc

/**********************Debit misc charges ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(misccharges), 0) from #lt_PurchaseSummary)
where  #lt_accounts.acccode = @ln_octroiacc

/**********************Debit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(salestax), 0) from #lt_PurchaseSummary)
where  #lt_accounts.acccode = @ln_salestaxacc

/******************Credit supplier/cash/equity account********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(#lt_PurchaseSummary.NetAmt), 0) from #lt_PurchaseSummary where #lt_PurchaseSummary.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_PurchaseSummary
where  #lt_accounts.acccode = #lt_PurchaseSummary.acccode 

Drop table #lt_PurchaseSummary

/**********************************************************************/
/*********************** Purchase Return *****************************/
/**********************************************************************/

create table #lt_PurRetSummary
(
	acccode      numeric (5,  0) NOT NULL,
	inventoryAmt numeric (11, 2) NOT NULL,    /*Cost of items and disc on total item cost*/
	NetAmt       numeric (11, 2) NOT NULL,    /*Net Cost including flat discounts, misc charges*/
	flatdisc     numeric (11, 2) NOT NULL,
	misccharges  numeric (11, 2) NOT NULL,
	salestax     numeric (11, 2) NOT NULL
)

insert  #lt_PurRetSummary
select  Case prledger.PRCatCode
		when 4 THEN @ln_cashacc     /* Cash Purchase */
		when 6 THEN @ln_equityacc   /* Opening Purchase  */
		else   prledger.suppcode     /* Credit Purhase    */
	end,

	IsNull(sum((( prdetail.looseqty + prdetail.packqty * prdetail.packunits) * prdetail.prprice) * (1 - (.01 * prdetail.discperc))) * (1- (.01 * prledger.discperc)), 0),
	IsNull(Round(sum((( prdetail.looseqty + prdetail.packqty * prdetail.packunits) * prdetail.prprice) * (1 - (.01 * prdetail.discperc))) * (1- (.01 * prledger.discperc)) + prledger.misccharges + prledger.salestax - prledger.flatdisc, 0), 0),
	prledger.flatdisc,
	prledger.misccharges,
	prledger.salestax

from     prledger,	 
	 prdetail		

where    prledger.date <= @ad_Date and
	 prledger.prinvcode = prdetail.prinvcode

group by prledger.prinvcode,
	 prledger.suppcode, 
	 prledger.prcatcode,
	 prledger.date,
	 prledger.discperc,
	 prledger.misccharges,
	 prledger.salestax,
	 prledger.flatdisc		

/***************************Credit Inventory****************************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(inventoryAmt), 0) from #lt_PurRetSummary)
where  #lt_accounts.acccode = @ln_inventoryacc

/**********************Debit flatdiscount ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(flatdisc), 0) from #lt_PurRetSummary)
where  #lt_accounts.acccode = @ln_freightacc

/**********************Credit misc charges ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(misccharges), 0) from #lt_PurRetSummary)
where  #lt_accounts.acccode = @ln_octroiacc

/**********************Credit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(salestax), 0) from #lt_PurRetSummary)
where  #lt_accounts.acccode = @ln_salestaxacc

/******************Debit supplier/cash/equity account********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(#lt_PurRetSummary.netAmt), 0) from #lt_PurRetSummary where #lt_PurRetSummary.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_PurRetSummary
where  #lt_accounts.acccode = #lt_PurRetSummary.acccode 

Drop table #lt_PurRetSummary

/**********************************************************************/
/**************************** Sale ***********************************/
/**********************************************************************/

create table #lt_SaleSummary
(
	acccode      numeric (5,  0) NOT NULL,
	InventoryAmt numeric (11, 2) NOT NULL,    /*Average cost of goods*/
	NetAmt       numeric (11, 2) NOT NULL,    /*Net sale price including flat discounts, misc charges etc*/
	flatdisc     numeric (11, 2) NOT NULL,
	misccharges  numeric (11, 2) NOT NULL,
	salestax     numeric (11, 2) NOT NULL
)

insert  #lt_SaleSummary
select  Case saleledger.saleCatCode
		when 1 THEN @ln_cashacc     /* Cash Sale */
		when 3 THEN @ln_cashacc     /* Cash Sale */
		else   saleledger.custcode     /* Credit Sale */
	end,
	IsNull(sum( (saledetail.looseqty + saledetail.packqty * saledetail.packunits) * saledetail.avgprice), 0),
	IsNull(Round(sum(( (saledetail.looseqty + saledetail.packqty * saledetail.packunits) * saledetail.saleprice) * (1 - (.01 * saledetail.discperc))) * (1- (.01 * saleledger.discperc)) + saleledger.misccharges + saleledger.salestax - saleledger.flatdisc, 0), 0),
	saleledger.flatdisc,
	saleledger.misccharges,
	saleledger.salestax

from     saleledger,	 
	 saledetail		

where    saleledger.date <= @ad_Date and
	 saleledger.saleinvcode = saledetail.saleinvcode 

group by saleledger.saleinvcode,
	 saleledger.custcode, 
	 saleledger.salecatcode,
	 saleledger.date,
	 saleledger.discperc,
	 saleledger.misccharges,
	 saleledger.salestax,
	 saleledger.flatdisc		

/**********************Credit Inventory***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(InventoryAmt), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_inventoryacc

/**********************Debit Average Purchase Cost***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(InventoryAmt), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_purchaseacc

/**********************Debit flatdiscount ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(flatdisc), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_salesfixdiscacc

/**********************Credit misc charges ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(misccharges), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_miscchargesacc

/**********************Credit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(salestax), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_salestaxacc

/**********************Credit Sales***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(NetAmt - salestax + FlatDisc - MiscCharges), 0) from #lt_SaleSummary)
where  #lt_accounts.acccode = @ln_salesacc

/******************Debit customer/cash/equity account********************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(#lt_SaleSummary.NetAmt), 0) from #lt_SaleSummary where #lt_SaleSummary.acccode = #lt_accounts.acccode) 
from   #lt_accounts, #lt_SaleSummary
where  #lt_accounts.acccode = #lt_SaleSummary.acccode 

Drop table #lt_SaleSummary

/**********************************************************************/
/**************************** Sale Return ********************************/
/**********************************************************************/

create table #lt_SaleRetSummary
(
	acccode      numeric (5,  0) NOT NULL,
	InventoryAmt numeric (11, 2) NOT NULL,    /*Average cost of goods*/
	NetAmt       numeric (11, 2) NOT NULL,    /*Sale price of items and disc on total item sale price*/
	flatdisc     numeric (11, 2) NOT NULL,
	misccharges  numeric (11, 2) NOT NULL,
	salestax     numeric (11, 2) NOT NULL
)

insert  #lt_SaleRetSummary
select  Case srledger.srCatCode
		when 6 THEN @ln_cashacc     /* Cash Sale Return*/
		when 8 THEN @ln_cashacc     /* Cash Sale Return*/
		else   srledger.custcode     /* Credit Sale Return*/
	end,

	IsNull( sum(((srdetail.looseqty + srdetail.packqty * srdetail.packunits) * srdetail.srprice) * (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)), 0),
	IsNull(Round(sum(((srdetail.looseqty + srdetail.packqty * srdetail.packunits) * srdetail.srprice) * (1 - (.01 * srdetail.discperc))) * (1- (.01 * srledger.discperc)) + srledger.misccharges + srledger.salestax - srledger.flatdisc, 0), 0),
	srledger.flatdisc,
	srledger.misccharges,
	srledger.salestax

from     srledger,	 
	 srdetail		

where    srledger.date <= @ad_Date and
	 srledger.srinvcode = srdetail.srinvcode 

group by srledger.srinvcode,
	 srledger.custcode, 
	 srledger.srcatcode,
	 srledger.date,
	 srledger.discperc,
	 srledger.misccharges,
	 srledger.salestax,
	 srledger.flatdisc		

/**********************Debit Inventory***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(InventoryAmt), 0) from #lt_SaleRetSummary)
where  #lt_accounts.acccode = @ln_inventoryacc

/**********************Credit Purchase ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(InventoryAmt), 0) from #lt_SaleRetSummary)
where  #lt_accounts.acccode = @ln_purchaseacc

/**********************Credit flatdiscount ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(flatdisc), 0) from #lt_SaleRetSummary)
where  #lt_accounts.acccode = @ln_salesfixdiscacc

/**********************Debit misc charges ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(misccharges), 0) from #lt_SaleRetSummary)
where  #lt_accounts.acccode = @ln_miscchargesacc

/**********************Debit salestax***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(salestax), 0) from #lt_SaleRetSummary)
where  #lt_accounts.acccode = @ln_salestaxacc

/**********************Debit Sales Return ***********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(inventoryamt), 0) from #lt_SaleRetSummary) 
where  #lt_accounts.acccode = @ln_salesretacc

/******************credit customer/cash/equity account********************/
Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance - (Select IsNull(sum(NetAmt), 0) from #lt_SaleRetSummary)
from   #lt_accounts, #lt_SaleRetSummary
where  #lt_accounts.acccode = #lt_SaleRetSummary.acccode 

Drop table #lt_SaleRetSummary

/**********************************************************************/
/**************************** Accounting Vouchers ************************/
/**********************************************************************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(gldetail.debit - gldetail.credit), 0) from glheader, gldetail where glheader.date <= @ad_Date and glheader.glvochcode =  gldetail.glvochcode and gldetail.acccode = #lt_accounts.acccode  ) 
from   #lt_accounts
where  #lt_accounts.acccode IN (Select distinct acccode from gldetail) 


/**********************************************************************/
/********************* Bills Receivables/Payables **********************/
/**********************************************************************/

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(Case NoteCatCode When 1 Then Amount * -1 Else Notes.Amount      End), 0) from Notes where Notes.issuedate <= @ad_Date and Notes.acccode = #lt_accounts.acccode ) 
from   #lt_accounts
where  #lt_accounts.acccode IN (Select distinct acccode from Notes ) 

Update #lt_accounts
set    #lt_accounts.currbalance = #lt_accounts.currbalance + (Select IsNull(sum(Case NoteCatCode When 1 Then Amount    Else Notes.Amount * -1   End), 0) from Notes where Notes.issuedate <= @ad_Date and Notes.bankacccode = #lt_accounts.acccode ) 
from   #lt_accounts
where  #lt_accounts.acccode IN (Select distinct bankacccode from Notes ) 

/**************************Final Housing Keeping *********************/

	Select accounts.name, subaccounts.name, #lt_Accounts.currbalance, accounts.acccode
	From   	accounts, #lt_Accounts, subaccounts
	Where  	accounts.acccode = #lt_Accounts.acccode and
		accounts.subcode = subaccounts.subacccode
GO

-- SP_TransferAccountingVoucher (last defined by script catalog)
CREATE PROCEDURE SP_TransferAccountingVoucher
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20), 
	@USERCODE SMALLINT, 
	@LOGID INT OUTPUT
AS

SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DECLARE @srcupd NVARCHAR(1000), @full_table_name NVARCHAR(255), @AccountName Varchar(100)
DECLARE @sqlheader NVARCHAR(1000), @sqldetail NVARCHAR(1000), @sql NVARCHAR(3000), @list NVARCHAR(3000)
DECLARE @table_id INT, @headercount INT, @TabMaxKey INT, @VoucherCode INT
DECLARE @OldGLVochCode INT, @VochCatCode INT, @AccCode INT, @ThisCount INT, @RetCode INT, @ImportCount INT
DECLARE @GLRowID INT, @errcode INT
DECLARE @DetailCount BIGINT, @MaxUtn BIGINT, @LastUTN BIGINT
DECLARE @Expiry DATETIME
DECLARE @ChangeVochType NVARCHAR(4000)

SET @sqlheader = N'SELECT T.*, OLDGLVochCode=T.GLVochCode INTO GLHTEMP FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.GLHeader AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' '
SET @sqldetail = N'SELECT T.*, OLDGLVochCode=T.GLVochCode INTO GLDTEMP FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.GLDetail AS T WHERE T.GLVochCode IN (SELECT GLVochCode FROM GLHTEMP)'
SET @srcupd = N'UPDATE ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.GLHeader SET TRANSFERED=''Y'', TRANSFEREDON = GETDATE(), TRANSFEREDBY = ' + LTRIM(RTRIM(STR(@USERCODE))) + ' WHERE GLVochCode IN (SELECT GLVochCode=OLDGLVochCode FROM GLHTEMP WHERE GLVochCode >= 0)'

EXECUTE (@sqlheader)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RAISERROR('Error Fetching The Required Accounting Vouchers From Source/Parent Database', 16, 1)
	RETURN -1
END

SET @headercount = ISNULL((SELECT ISNULL(COUNT(*), 0) FROM GLHTEMP), 0)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0 OR @headercount <= 0
BEGIN
	RETURN 0
END

EXECUTE (@sqldetail)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in fetching Accounting Vouchers Detail', 16, 1)
	RETURN -1
END

SET @detailcount = ISNULL((SELECT ISNULL(COUNT(*), 0) FROM GLDTEMP), 0)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0 OR @detailcount <= 0
BEGIN
	RaisError('Problem in fetching Accounting Vouchers Detail', 16, 1)
	RETURN -1
END

-- Transform Invoice based Vouchers to a/c based vouchers header
SET @ChangeVochType = ' UPDATE GLHTEMP SET VochCatCode = CASE WHEN VochCatCode <= 5 THEN VochCatCode WHEN VochCatCode = 12 THEN 2 WHEN VochCatCode = 13 THEN 4 WHEN VochCatCode = 15 THEN 1 WHEN VochCatCode = 16 THEN 3 ELSE 5 END  '
EXECUTE (@ChangeVochType)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in transformation of a/c vouchers from invoice based to a/c based', 16, 1)
	RETURN -1
END

-- Transform Invoice based Vouchers to a/c based vouchers detail
SET @ChangeVochType = ' UPDATE GLDTEMP SET InvoiceCode=NULL, OutStandingAmt=0, Balance=0  '
EXECUTE (@ChangeVochType)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in transformation of a/c vouchers from invoice based to a/c based', 16, 1)
	RETURN -1
END

EXECUTE @errcode = SP_GetTabMaxkey 'datatransferlog' , @LOGID Output
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in generating data transfer log', 16, 1)
	RETURN -1
END

EXECUTE @errcode = SP_MaxUtn @detailcount, @MaxUtn OUTPUT
IF @errcode <> 0 AND @@ERROR <> 0
BEGIN
	RaisError('Problem in generating GL UTN', 16, 1)
	RETURN -1			
END

SET @errcode = 0
SET @LastUTN = @MaxUtn - @detailcount

DECLARE GL1 CURSOR FOR
SELECT GLVochCode, VochCatCode
FROM GLHTEMP
ORDER BY GLVochCode

OPEN GL1

FETCH NEXT FROM GL1 INTO @OldGLVochCode, @VochCatCode
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @ThisCount = 0

	UPDATE GLDTemp SET GLVochCode=-1000 WHERE OLDGLVochCode = @OldGLVochCode
	SET @ThisCount = ISNULL((SELECT COUNT(OLDGLVochCode) FROM GLDTemp WHERE OLDGLVochCode = @OldGLVochCode), 0)

	IF @ThisCount = 0 
	BEGIN
		UPDATE GLHTEMP
		SET GLVochCode = -1000 WHERE OldGLVochCode = @OldGLVochCode
	END
	ELSE
	BEGIN
		/* Generate TabMaxKey for GL Voucher Code for current voucher */
		EXECUTE @errcode = SP_GetTabMaxkey 'glheader', @TABMAXKEY Output
		IF @@ERROR <> 0 OR @errcode <> 0
		BEGIN
			CLOSE GL1
			DEALLOCATE GL1
			RETURN -1
		END
		/* Generate Voucher Code for current voucher category */
		EXECUTE @errcode = SP_GetVoucherCode @VochCatCode, @VoucherCode Output
		IF @@ERROR <> 0 OR @errcode <> 0
		BEGIN
			RaisError('Voucher Code Generation Problem' ,16, 1)
			CLOSE GL1
			DEALLOCATE GL1
			RETURN -1
		END

		UPDATE GLHTEMP
		SET GLVochCode = @TabMaxKey, VoucherCode = @VoucherCode, SalesmanCode = @USERCODE, 
			ModifiedBy = NULL, POSTED='N', POSTEDBY=NULL, TRANSFERABLE='N', TRANSFERED='N', 
			TRANSFEREDBY=NULL, TRANSFEREDON=NULL, IMPORTED='Y', IMPORTEDBY=@UserCode
		WHERE OLDGLVochCode = @OldGLVochCode

		UPDATE GLDTEMP
		SET GLVochCode = @TabMaxKey
		WHERE OLDGLVochCode = @OldGLVochCode
	END
	FETCH NEXT FROM GL1 INTO @OldGLVochCode, @VochCatCode
END
CLOSE GL1
DEALLOCATE GL1

SET @ImportCount = ISNULL((SELECT COUNT(*) FROM GLHTEMP WHERE GLHTEMP.GLVochCode >= 0), 0)

IF @ImportCount > 0
BEGIN
	SET XACT_ABORT ON
	EXECUTE (@SRCUPD)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update the transfer status at source/parent database', 16, 1)
		RETURN -1
	END

	SET XACT_ABORT OFF

	SET @LIST=''
	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'GLHeader', @LIST OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update accounting voucher header', 16, 1)
		RETURN -1
	END

	SET @SQL = N'INSERT INTO DBO.GLHeader ( ' + @LIST + ' ) ' + 'SELECT ' + 
		@LIST +	' FROM GLHTEMP WHERE GLHTEMP.GLVochCode >= 0'
	
	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update accounting voucher header', 16, 1)
		RETURN -1
	END

	SET @LIST=''
	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'GLDetail', @LIST OUTPUT
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update accounting voucher detail', 16, 1)
		RETURN -1
	END

	SET @SQL = N'INSERT INTO DBO.GLDETAIL ( ' + @LIST + ' ) ' + 'SELECT ' + 
		@LIST +	' FROM GLDTEMP WHERE GLDTEMP.GLVochCode >= 0'

	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update accounting voucher detail', 16, 1)
		RETURN -1
	END
END

IF @@ERROR = 0 AND @errcode = 0
BEGIN
	INSERT INTO DataTransferLog (TRANSFERLOGID, LOGDATE, TRANSFEREDBY, INVOICECODE, INVOICETYPE, DATE, ACCCODE, SGCODE, DGCODE, STATUS)
	SELECT  @LOGID, LOGDATE=GETDATE(), TRANSFEREDBY=@UserCode, INVOICECODE=OLDGLVochCode, 
		INVOICETYPE=0, DATE=GETDATE(), ACCCODE=ACCCODE, NULL, NULL,
		STATUS = CASE GLVochCode WHEN -1000 THEN 0 ELSE 1 END
	FROM GLHTEMP

	INSERT INTO DataTransferLogDetail 
		(TRANSFERLOGID, INVOICECODE, INVOICETYPE, ICode, GCODE, BATCH, 
		EXPIRY, QTY, BONUSQTY, PRICE, STATUS)
	SELECT @LOGID, INVOICECODE=OLDGLVochCode, INVOICETYPE=0, ICode=AccCode, GCODE=NULL, BATCH=NULL, 
		EXPIRY=NULL, QTY= Debit - Credit, BonusQty=0, PurPrice=1, STATUS = CASE GLVochCode WHEN -1000 THEN 0 ELSE 1 END
	FROM GLDTEMP
END

DROP TABLE GLHTEMP
DROP TABLE GLDTEMP

IF @@ERROR = 0 AND @errcode = 0
	RETURN 0
ELSE
	RaisError('Unable To successfully transfer accounting voucher', 16, 1)
	RETURN -1
GO

-- SP_TransferBasicData (last defined by script catalog)
CREATE  PROCEDURE SP_TransferBasicData @SRV VARCHAR(50), @DB VARCHAR(50), @OWNER VARCHAR(20)
AS

SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

/*Variables to be used in delete, update and insert processes*/
DECLARE @LastDateTime DATETIME
DECLARE @TableName NVARCHAR(50), @full_table_name NVARCHAR(255), @CON NVARCHAR(50)
DECLARE @ColName VARCHAR(255), @WHR VARCHAR(50)
DECLARE @FROM NVARCHAR(1000), @PKCOND NVARCHAR(1000), @NOTIN NVARCHAR(50), @IN NVARCHAR(50), @ENDD NVARCHAR(50)
DECLARE @MAXCOL NVARCHAR(255), @TABMAXSQL NVARCHAR(3000), @SQL NVARCHAR(4000), @LIST NVARCHAR(4000)
DECLARE @AutoInsert CHAR(1), @AutoUpdate Char(1), @AutoDelete Char(1), @UPDMaxKey Char(1)
DECLARE @table_id INT, @err INT
DECLARE @Priority SMALLINT, @KeySeq SMALLINT, @Position SMALLINT
/*Variables to be used in delete process*/
DECLARE @DEL NVARCHAR(1000), @DEL_QRY NVARCHAR(4000)
/*Variables to be used in Insert process*/
DECLARE @INS NVARCHAR(1000), @INS_QRY NVARCHAR(4000)

/*Variables to be used in Update process*/
DECLARE @UPD NVARCHAR(1000), @SETPART NVARCHAR(4000), @UPD_PKCOND NVARCHAR(1000), @UPD_QRY NVARCHAR(4000)

/*'FROM' clause of SQL used in INSERT/DELETE*/
IF LTRIM(RTRIM(@srv)) = ''
	SET @FROM = N' FROM ' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.'
ELSE
	SET @FROM = N' FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.'

SET @NOTIN = N' NOT IN (SELECT '
SET @CON = N'CONVERT(VarChar(10),'
SET @SQL = N'SELECT '
SET @IN = N' IN (SELECT '
SET @WHR = N'WHERE '
SET @ENDD = N' AS T WHERE '
SET @LastDateTime = ISNULL((SELECT ServerDataTime FROM DataTransferDate), '1900-01-01 00:00:00')

/*BasicData Deletion Variables (initializing variables)*/
SET @DEL = N'DELETE '

/*BasicData Updation Variables (initializing variables)*/
SET @UPD = N'UPDATE '
SET @SETPART = N'SET '

/*BasicData Updation Variables (initializing variables)*/
SET @INS = N'INSERT INTO '

DECLARE TmpCrs1 CURSOR FOR
SELECT TABLENAME=LTRIM(RTRIM(TABLENAME)), PRIORITY, AUTOINSERT, AUTOUPDATE, AUTODELETE, UPDATETABMAXKEY
FROM TransferableData 
WHERE Enable='Y'
ORDER BY Priority

OPEN TmpCrs1

FETCH NEXT FROM TmpCrs1 INTO @TableName, @Priority, @AutoInsert, @AutoUpdate, @AutoDelete, @UPDMaxKey
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @full_table_name = LTRIM(RTRIM(@owner)) + '.' + @TableName
	SET @table_id = OBJECT_ID(@full_table_name)
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0 OR @table_id IS NULL
	BEGIN
		RAISERROR('Data Updation: Invalid Object Refered: Name = %s', 16, 1, @full_table_name)
		CLOSE TmpCrs1
		DEALLOCATE TmpCrs1
		RETURN -1
	END 

	SELECT @PKCOND = '', @MAXCOL = '', @UPD_PKCOND = ''

	DECLARE TmpCrs2 CURSOR FOR
	SELECT 	COLNAME = CONVERT(sysname,c.name),
		KEYSEQ =
			CASE
				when c.name = index_col(@full_table_name, i.indid,  1) then convert (smallint,1)
				when c.name = index_col(@full_table_name, i.indid,  2) then convert (smallint,2)
				when c.name = index_col(@full_table_name, i.indid,  3) then convert (smallint,3)
				when c.name = index_col(@full_table_name, i.indid,  4) then convert (smallint,4)
				when c.name = index_col(@full_table_name, i.indid,  5) then convert (smallint,5)
				when c.name = index_col(@full_table_name, i.indid,  6) then convert (smallint,6)
				when c.name = index_col(@full_table_name, i.indid,  7) then convert (smallint,7)
				when c.name = index_col(@full_table_name, i.indid,  8) then convert (smallint,8)
				when c.name = index_col(@full_table_name, i.indid,  9) then convert (smallint,9)
				when c.name = index_col(@full_table_name, i.indid, 10) then convert (smallint,10)
				when c.name = index_col(@full_table_name, i.indid, 11) then convert (smallint,11)
				when c.name = index_col(@full_table_name, i.indid, 12) then convert (smallint,12)
				when c.name = index_col(@full_table_name, i.indid, 13) then convert (smallint,13)
				when c.name = index_col(@full_table_name, i.indid, 14) then convert (smallint,14)
				when c.name = index_col(@full_table_name, i.indid, 15) then convert (smallint,15)
				when c.name = index_col(@full_table_name, i.indid, 16) then convert (smallint,16)
			end
	from
		sysindexes i, syscolumns c, sysobjects o
	where
		o.id = @table_id
		and o.id = c.id
		and o.id = i.id
		and (i.status & 0x800) = 0x800
		and (c.name = index_col (@full_table_name, i.indid,  1) or
		     c.name = index_col (@full_table_name, i.indid,  2) or
		     c.name = index_col (@full_table_name, i.indid,  3) or
		     c.name = index_col (@full_table_name, i.indid,  4) or
		     c.name = index_col (@full_table_name, i.indid,  5) or
		     c.name = index_col (@full_table_name, i.indid,  6) or
		     c.name = index_col (@full_table_name, i.indid,  7) or
		     c.name = index_col (@full_table_name, i.indid,  8) or
		     c.name = index_col (@full_table_name, i.indid,  9) or
		     c.name = index_col (@full_table_name, i.indid, 10) or
		     c.name = index_col (@full_table_name, i.indid, 11) or
		     c.name = index_col (@full_table_name, i.indid, 12) or
		     c.name = index_col (@full_table_name, i.indid, 13) or
		     c.name = index_col (@full_table_name, i.indid, 14) or
		     c.name = index_col (@full_table_name, i.indid, 15) or
		     c.name = index_col (@full_table_name, i.indid, 16)
		    )
	order by 2

	OPEN TmpCrs2
	
	FETCH NEXT FROM TmpCrs2 INTO @ColName, @KeySeq
	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF @KeySeq <> 1
		BEGIN
			SET @PKCOND = @PKCOND  + ' + '
			SET @UPD_PKCOND = @UPD_PKCOND + ' AND '
		END

		SET @PKCOND = @PKCOND + ' ' + @CON + LTRIM(RTRIM(@ColName)) + ')'
		SET @UPD_PKCOND = @UPD_PKCOND + ' T.' + LTRIM(RTRIM(@ColName)) + ' = ' + @TableName + '.' + LTRIM(RTRIM(@ColName))

		SET @MAXCOL = 'MAX(' + RTRIM(LTRIM(@ColName)) + ')'	
		FETCH NEXT FROM TmpCrs2 INTO @ColName, @KeySeq
	END
	CLOSE TmpCrs2
	DEALLOCATE TmpCrs2	

	IF @AutoDelete='Y'
	BEGIN
		SET @DEL_QRY = @DEL + @TableName + ' ' + @WHR + @PKCOND + @NOTIN + @PKCOND + @FROM + @TableName + ')'
		EXECUTE (@DEL_QRY)
		SET @err = @@ERROR
		IF @err <> 0
		BEGIN
			RAISERROR('Data Deletion: Error Transfering %s Data', 16, 1, @full_table_name)
			CLOSE TmpCrs1
			DEALLOCATE TmpCrs1
			RETURN -1
		END 
	END

	IF @AutoUpdate='Y'
	BEGIN
		SET @SETPART = N'SET '
	
		DECLARE TmpCrs3 CURSOR FOR
		SELECT
			COLUMNNAME = convert(sysname,c.name),
			POSITION = convert(int,
					   (
						select count(*)
						from syscolumns sc
						where sc.id     =  c.id
						  AND sc.number =  c.number
						  AND sc.colid  <= c.colid
					    ))
		FROM
			sysobjects o,
			syscolumns c
		WHERE
			o.id = @table_id AND c.id = o.id
		ORDER BY 2
	
		OPEN TmpCrs3
	
		FETCH NEXT FROM TmpCrs3 INTO @ColName, @Position
		WHILE @@FETCH_STATUS = 0
		BEGIN
			IF ColumnProperty (@table_id, @ColName, 'IsIdentity') <> 1
			BEGIN
				IF @ColName = (SELECT columnname FROM TransferableData_RestrictedColumns WHERE columnname = @ColName and tablename = @TableName)
				BEGIN
					SET @ColName = @ColName
				END
				ELSE
				BEGIN
					IF @SETPART <> 'SET '
					BEGIN
						SET @SETPART = @SETPART + ','
					END
			
					SET @SETPART = @SETPART + LTRIM(RTRIM(@ColName)) + '=' + 'T.' +  LTRIM(RTRIM(@ColName))
				END
			END
			
			FETCH NEXT FROM TmpCrs3 INTO @ColName, @Position
		END
		CLOSE TmpCrs3
		DEALLOCATE TmpCrs3
	
		IF @SETPART <> 'SET '
		BEGIN
			SET @UPD_QRY = @UPD + @TableName + ' ' + @SETPART + ' ' + @FROM + @TableName + @ENDD + ' ' + @UPD_PKCOND
			EXECUTE (@UPD_QRY)
			SET @err = @@ERROR
			IF @@ERROR <> 0 OR @err <> 0
			BEGIN
				RAISERROR('Data Updation: Error Transfering %s Data', 16, 1, @full_table_name)
				CLOSE TmpCrs1
				DEALLOCATE TmpCrs1
				RETURN -1
			END 
		END
	END 

	IF @AutoInsert='Y' AND @TableName <> 'Rights' 
	BEGIN
		SET @SQL = N' SELECT '
		SET @LIST=''
		EXECUTE @err = SP_COLUMNLIST @OWNER, @TableName, @LIST OUTPUT
		SET @err = @@ERROR
		IF @@ERROR <> 0 OR @err <> 0
		BEGIN
			CLOSE TmpCrs1
			DEALLOCATE TmpCrs1
			RETURN -1
		END
		IF @TableName = 'GroupRights'
			SET @INS_QRY = @INS + @TableName + ' (' + @List + ' )  ' + @SQL + @List + @FROM + @TableName + @ENDD + @PKCOND + @NOTIN + @PKCOND + ' FROM ' + @TableName + ')  AND RightCode IN (SELECT RightCode FROM Rights)'
		ELSE
			SET @INS_QRY = @INS + @TableName + ' (' + @List + ' )  ' + @SQL + @List + @FROM + @TableName + @ENDD + @PKCOND + @NOTIN + @PKCOND + ' FROM ' + @TableName + ')'

		EXECUTE (@INS_QRY)
		SET @err = @@ERROR
		IF @@ERROR <> 0 OR @err <> 0
		BEGIN
			RAISERROR('Data Insertion: Error Transfering %s Data', 16, 1, @full_table_name)
			CLOSE TmpCrs1
			DEALLOCATE TmpCrs1
			RETURN -1
		END 
	END

	IF @UPDMaxKey = 'Y' 
	BEGIN
		SET @TABMAXSQL = ''
		SET @TABMAXSQL = 'UPDATE _tabmaxkey SET TABMAXKEY = ' + ' ISNULL((SELECT ' + @MAXCOL + ' FROM  ' + RTRIM(LTRIM(@TableName)) + '), 0) ' + 'WHERE TABNAME = ''' + RTRIM(LTRIM(@TableName)) + ''''
		EXECUTE (@TABMAXSQL)
		SET @err = @@ERROR
		IF @@ERROR <> 0 OR @err <> 0
		BEGIN
			RAISERROR('Data Insertion: Error While Updating the TABMAXKEY of %s ', 16, 1, @full_table_name)
			CLOSE TmpCrs1
			DEALLOCATE TmpCrs1
			RETURN -1
		END 
	END

	FETCH NEXT FROM TmpCrs1 INTO @TableName, @Priority, @AutoInsert, @AutoUpdate, @AutoDelete, @UPDMaxKey
END
CLOSE TmpCrs1
DEALLOCATE TmpCrs1

DELETE DataTransferDate

IF LTRIM(RTRIM(@srv)) = ''
	SET @INS_QRY = 'INSERT INTO DataTransferDate (ServerDataTime) SELECT ServerDataTime = ISNULL((SELECT GETDATE() - 0.042 FROM ' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '._UTN)' + ', GETDATE())'
ELSE
	SET @INS_QRY = 'INSERT INTO DataTransferDate (ServerDataTime) SELECT ServerDataTime = ISNULL((SELECT GETDATE() - 0.042 FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '._UTN)' + ', GETDATE())'

EXECUTE (@INS_QRY)
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RAISERROR('Data Transfer: Error While recoridng data transfer date', 16, 1)
	RETURN -1
END 

INSERT INTO DataImportLog (LogDate, ImportedBy, ImportType, Remarks)
VALUES (GetDate(), 1, 'Data Synchronization', @SRV + ' DB:' + @DB)

RETURN 0
GO

-- SP_TransferInterGodownTransfers (last defined by script catalog)
CREATE  PROCEDURE SP_TransferInterGodownTransfers 
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20), 
	@USERCODE SMALLINT, 
	@LogId INT OUTPUT 
AS 

SET NOCOUNT ON  
SET ANSI_NULLS ON  
SET ANSI_WARNINGS ON    

DECLARE @srcupd NVARCHAR(1000), @Batch VARCHAR(100), @ERRORTEXT NVARCHAR(255), @ItemName VARCHAR(100)
DECLARE @sqlheader NVARCHAR(1000), @sqldetail NVARCHAR(1000), @SQL NVARCHAR(3000), @LIST NVARCHAR(3000)
DECLARE @headercount INT, @TabMaxKey INT, @HeaderTabMaxKey INT, @HeaderCode INT, @errcode INT
DECLARE @OldInvCode INT, @TTCode INT, @ICode INT, @GCode INT, @ThisCount INT, @RetCode INT, @ImportCount INT
DECLARE @SGCode INT, @DGCode INT, @ID INT, @PackUnits INT, @InserCount INT
DECLARE @Qty NUMERIC(15, 4),@ReqQty NUMERIC(15, 4), @TQty NUMERIC(15, 4)
DECLARE @SourceStock NUMERIC(15, 4), @TargetStock NUMERIC(15, 4), @NewStock NUMERIC(15, 4), @BatchStock NUMERIC(15, 4), @ReorderQty INT, @OptimumQty INT
DECLARE @DetailCount BIGINT, @MaxUtn BIGINT  DECLARE @Expiry DATETIME
DECLARE @PurPrice NUMERIC(15, 5), @SalePrice NUMERIC(15, 5), @DiscPerc FLOAT, @RPP NUMERIC(15, 5), @AvgPrice NUMERIC(15, 5)

SET @sqlheader = N'SELECT T.*, OLDINVCODE=T.TRANSCODE INTO THTEMP FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.THeader AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' '
SET @sqldetail = N'SELECT T.*, OLDINVCODE=T.TRANSCODE, ID2=0 INTO TDTEMP FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.TDetail AS T WHERE T.TRANSCODE IN (SELECT TRANSCODE FROM THTEMP) ORDER BY T.ID'
SET @srcupd = N'UPDATE ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.THeader SET TRANSFERED=''Y'', TRANSFEREDON = GETDATE(), TRANSFEREDBY = ' + LTRIM(RTRIM(STR(@USERCODE))) + ' WHERE TRANSCODE IN (SELECT OLDINVCODE FROM THTEMP WHERE TRANSCODE >= 0)'

EXECUTE (@sqlheader)

SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RAISERROR('Error Fetching The Required Inter Godown Transfers From Source Database', 16, 1)
	RETURN -1
END
	SET @headercount = (SELECT ISNULL(COUNT(*), 0) FROM THTEMP)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0 OR @headercount <= 0
	BEGIN
		RETURN 0
	END
	EXECUTE (@sqldetail)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem in fetching Inter Godown Transfers Detail', 16, 1)
		RETURN -1
	END
	SET @detailcount = (SELECT ISNULL(COUNT(*), 0) FROM TDTEMP)
	SET @errcode = @@ERROR

	IF @@ERROR <> 0 OR @errcode <> 0 OR @detailcount <= 0
	BEGIN
		RaisError('Problem in fetching Transfer Invoices Detail', 16, 1)
		RETURN -1
	END
	EXECUTE @errcode = SP_GetTabMaxkey 'datatransferlog' , @LOGID Output
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Problem in generating data transfer log', 16, 1)
		RETURN -1
	END
	
	SELECT * INTO TDTEMP2
	FROM (SELECT * FROM TDTEMP WHERE TransCode < 0 
	UNION 
	SELECT * FROM TDTEMP WHERE TransCode < 0) A

	IF @@ERROR <> 0 OR @@ROWCOUNT > 0
	BEGIN
		RaisError('Problem in generating transfer invoice(s) number', 16, 1)
		RETURN -1
	END
	SET @errcode = 0

	DECLARE tran1 CURSOR FOR
	SELECT OldInvCode, TTCode, SGCode, DGCode, HeaderNo=ISNULL(HeaderNo, 1)
	FROM THTEMP
	ORDER BY OldInvCode

	OPEN tran1
	FETCH NEXT FROM tran1 INTO @OldInvCode, @TTCode, @SGCode, @DGCode, @HeaderCode
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @ThisCount = 0
		DECLARE tran2 CURSOR FOR
		SELECT ICode, ID=MAX(ID), SUM(Qty), ReorderQty=MAX(ISNULL(ReorderQty, 0)), OptimumQty = Max(ISNULL(OptimumQty, 0))
		FROM TDTEMP
		WHERE OLDINVCODE = @OldInvCode
		GROUP BY ICode
		ORDER BY ID, ICode

		OPEN tran2
		FETCH NEXT FROM tran2 INTO @ICode, @ID, @Qty, @ReorderQty, @OptimumQty
		WHILE @@FETCH_STATUS = 0
		BEGIN
			IF @QTY > 0
			BEGIN
				SET @ItemName = ISNULL((SELECT name FROM ITEM WHERE ICODE = @ICODE), '')
				SET @AvgPrice = 0
				SET @SourceStock = 0
				SET @TargetStock = 0
				EXECUTE @errcode = SP_GetItemAvgPrice @ICode, @AvgPrice OUTPUT
				IF @@Error <> 0 OR @errcode <> 0
				BEGIN
					RAISERROR('Unable to fetch item average price, transfer # = %d, item = (%s)', 16, 1, @OldInvCode, @ItemName)
					CLOSE tran2
					DEALLOCATE tran2
					CLOSE tran1
					DEALLOCATE tran1
					RETURN -1
				END
				EXECUTE SP_GetItemStockTotal @DGCode, @ICode, @TargetStock OUTPUT
				IF @@Error <> 0 
				BEGIN
					RaisError('Unable to fetch stock for target/destination godown, transfer # = %d, Item = (%s)', 16, 1, @OldInvCode, @ItemName)
					CLOSE tran2
					DEALLOCATE tran2
					CLOSE tran1
					DEALLOCATE tran1
					RETURN -1
				END
				EXECUTE SP_GetItemStockTotal @SGCode, @ICode, @SourceStock OUTPUT
				IF @@Error <> 0
				BEGIN
					RaisError('Unable to fetch stock for source godown, transfer # = %d, Item = (%s)', 16, 1, @OldInvCode, @ItemName)
					CLOSE tran2
					DEALLOCATE tran2
					CLOSE tran1
					DEALLOCATE tran1
					RETURN -1
				END
				SELECT @PurPrice = ISNULL(PurPrice, 0), @SalePrice = ISNULL(SalePrice, 0), @PackUnits = ISNULL(PackUnits, 0)
				FROM ITEM WHERE Icode = @ICode
				IF @@ROWCOUNT = 0
				BEGIN
					RaisError('Unable to fetch item packunits, purchase and sale prices. Transfer # = %d, Item = (%s)', 16, 1, @OldInvCode, @ItemName)
					CLOSE tran2
					DEALLOCATE tran2
					CLOSE tran1
					DEALLOCATE tran1
					RETURN -1
				END
				IF @QTY <= @SourceStock
				BEGIN
					SET @ReqQty = @QTY
					SET @InserCount = 0
					SET @RetCode = 0
					
					DECLARE tran3 CURSOR FOR
					SELECT batch, expiry, Currqty
					FROM godowndetail 
					WHERE godowndetail.gcode = @SGCode and
						godowndetail.icode = @ICode
					ORDER BY priority, expiry, Currqty

					OPEN tran3
					FETCH NEXT FROM tran3 INTO @Batch, @Expiry, @BatchStock
					WHILE @@FETCH_STATUS = 0
					BEGIN
					IF @BatchStock >= @ReqQty
					BEGIN
						SET @TQty = @ReqQty
					END
					ELSE
					BEGIN
						SET @TQty = @BatchStock
					END
					SET @ReqQty = @ReqQty - @TQty
					SET @NewStock = @BatchStock - @TQty
					IF @NewStock > 0
					BEGIN
						UPDATE GodownDetail SET CurrQty = @NewStock WHERE CURRENT OF tran3
						IF @@RowCount = 0
						BEGIN 
							SET @RetCode = 1
						END
					END 
					ELSE
					BEGIN
						IF @NewStock=0
						BEGIN
							DELETE GodownDetail WHERE CURRENT OF tran3
							IF @@RowCount = 0
							BEGIN
							SET @RetCode = 1
						END
					END
					ELSE
					BEGIN
						SET @RetCode = 1
					END
				END
				IF @RetCode = 0
				BEGIN
					EXECUTE @RetCode = SP_UpdateGodownDetail @DGCode, @ICode, @Batch, @Expiry, @TQty
					IF @@ERROR <> 0 OR @RetCode <> 0
					BEGIN
						CLOSE tran3
						DEALLOCATE tran3
						CLOSE tran2
						DEALLOCATE tran2
						CLOSE tran1
						DEALLOCATE tran1
						RETURN -1
					END
					EXECUTE @errcode = SP_MaxUtn 1, @MaxUtn OUTPUT
					IF @errcode <> 0 AND @@ERROR <> 0
					BEGIN
						CLOSE tran3
						DEALLOCATE tran3
						CLOSE tran2
						DEALLOCATE tran2
						CLOSE tran1
						DEALLOCATE tran1
						RETURN -1
					END
					SET @InserCount = @InserCount + 1
					INSERT INTO TDTEMP2 SELECT * FROM TDTEMP WHERE ID = @ID
					IF @@ERROR <> 0 OR @@RowCount = 0
					BEGIN
						RaisError('Unable to Insert Row for Transfer # = %d, Item = (%s)', 16, 1, @OldInvCode, @ItemName)
						CLOSE tran3
						DEALLOCATE tran3
						CLOSE tran2
						DEALLOCATE tran2
						CLOSE tran1
						DEALLOCATE tran1
						RETURN -1
					END

					UPDATE TDTEMP2
					SET ID2 = @InserCount, Batch=@Batch, Expiry=@Expiry, Qty=@TQty, AvgPrice=@AvgPrice, 
						PurPrice=@PurPrice, SalePrice=@SalePrice, PackUnits=@PackUnits, 
						SourceStock=@SourceStock, TargetStock=@TargetStock, RequiredQty=@Qty, 
						TransferUTN=@MaxUtn
					WHERE ID=@ID and ID2=0
					IF @@ERROR <> 0 OR @@RowCount = 0
					BEGIN
						RaisError('Unable to Update Row for Transfer # = %d, Item = (%s)', 16, 1, @OldInvCode, @ItemName)
						CLOSE tran3
						DEALLOCATE tran3
						CLOSE tran2
						DEALLOCATE tran2
						CLOSE tran1
						DEALLOCATE tran1
						RETURN -1
					END
				END
				ELSE
				BEGIN
					RaisError('Unable to Update stock for Transfer # = %d, Item = (%s)', 16, 1, @OldInvCode, @ItemName)
					CLOSE tran3
					DEALLOCATE tran3
					CLOSE tran2
					DEALLOCATE tran2
					CLOSE tran1
					DEALLOCATE tran1
					RETURN -1
				END
				IF @RetCode <> 0
					BREAK  
				IF @ReqQty = 0 
					BREAK
				FETCH NEXT FROM tran3 INTO @Batch, @Expiry, @BatchStock
			END
			CLOSE tran3
			DEALLOCATE tran3
		END
		ELSE
		BEGIN
			SET @RetCode = 1
		END
		IF @RetCode <> 0
		BEGIN  
			/*UPDATE TDTEMP SET TRANSCODE=-1000 WHERE ID = @ID*/
			UPDATE TDTEMP SET TRANSCODE=-1000 
			WHERE OLDINVCODE = @OLDINVCODE AND ICODE = @ICODE
		END
		ELSE
		BEGIN
			SET @ThisCount = @ThisCount + 1
		END
	END
	ELSE
	BEGIN  
		/*UPDATE TDTEMP SET TRANSCODE=-1000 WHERE ID = @ID*/
		UPDATE TDTEMP SET TRANSCODE=-1000 WHERE OLDINVCODE = @OLDINVCODE AND ICODE = @ICODE
	END
	FETCH NEXT FROM tran2 INTO @ICode, @ID, @Qty, @ReorderQty, @OptimumQty
END
CLOSE tran2
DEALLOCATE tran2

IF @ThisCount = 0
BEGIN 
	UPDATE THTEMP SET TRANSCODE = -1000 WHERE OldInvCode = @OldInvCode
END
ELSE
BEGIN
	EXECUTE @errcode = SP_GetTabMaxkey 'theader', @TABMAXKEY Output
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		CLOSE tran1
		DEALLOCATE tran1
		RETURN -1
	END
	EXECUTE @errcode = SP_GetHeaderTabMaxkey @HeaderCode, 8, @HeaderTabMaxKey Output
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		CLOSE tran1
		DEALLOCATE tran1
		RETURN -1
	END

	UPDATE THTEMP 
	SET TRANSCODE = @TabMaxKey, HeaderNo = ISNULL(@HeaderCode, 1), HEADERINVNO = @HeaderTabMaxKey, 
		SalesmanCode = @USERCODE, POSTED='Y', TRANSFERABLE='N', TRANSFERED='N', TRANSFEREDBY=NULL, 
		TRANSFEREDON=NULL, IMPORTED='Y', IMPORTEDBY=@UserCode 
	WHERE OLDINVCODE = @OldInvCode

	UPDATE TDTEMP2
	SET TRANSCODE = @TabMaxKey WHERE OLDINVCODE = @OldInvCode
END
FETCH NEXT FROM tran1 INTO @OldInvCode, @TTCode, @SGCode, @DGCode, @HeaderCode
END
CLOSE tran1
DEALLOCATE tran1

SET @ImportCount = ISNULL((SELECT COUNT(*) FROM THTEMP WHERE THTEMP.TRANSCODE >= 0), 0)
IF @ImportCount > 0
BEGIN
	SET XACT_ABORT ON
	EXECUTE (@SRCUPD)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update the transfer status at source database', 16, 1)
		RETURN -1
	END
	SET XACT_ABORT OFF
	SET @LIST=''
	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'Theader', @LIST OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update the transfer header', 16, 1)
	    RETURN -1   
	END     
	SET @SQL = N'INSERT INTO THEADER ( ' + @LIST + ' ) ' + 'SELECT ' +     @LIST + ' FROM THTEMP WHERE THTEMP.TRANSCODE >=0'
	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update the transfer header', 16, 1)
		RETURN -1
	END
	SET @LIST=''
	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'TDetail', @LIST OUTPUT
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update the transfer detail', 16, 1)
		RETURN -1
	END
	SET @SQL = N'INSERT INTO TDETAIL ( ' + @LIST + ' ) ' + 'SELECT ' + @LIST + ' FROM TDTEMP2 WHERE TDTEMP2.TRANSCODE >=0 ORDER BY TDTEMP2.ID'
	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update the transfer detail', 16, 1)
		RETURN -1
	END
END
IF @@Error = 0 AND @errcode = 0
BEGIN
	INSERT INTO DataTransferLog (TRANSFERLOGID, LOGDATE, TRANSFEREDBY, INVOICECODE, INVOICETYPE, DATE, ACCCODE, SGCODE, DGCODE, STATUS)   
	SELECT  @LOGID, LOGDATE=GETDATE(), TRANSFEREDBY=@UserCode, INVOICECODE=OLDINVCODE, INVOICETYPE=8, DATE=GETDATE(), ACCCODE=NULL, THTEMP.SGCODE, THTEMP.DGCODE, STATUS = CASE TRANSCODE WHEN -1000 THEN 0 ELSE 1 END
	FROM THTEMP 

	INSERT INTO DataTransferLogDetail (TRANSFERLOGID, INVOICECODE, INVOICETYPE, ICODE, GCODE, BATCH, EXPIRY, QTY, PRICE, STATUS)
	SELECT  @LOGID, INVOICECODE=OLDINVCODE, INVOICETYPE=8, ICODE, NULL, BATCH, EXPIRY, QTY, PRICE=ROUND(PurPrice / CASE PackUnits WHEN 0 THEN 1 ELSE PackUnits END, 2), STATUS = CASE TRANSCODE WHEN -1000 THEN 0 ELSE 1 END
	FROM TDTEMP
END
DROP TABLE THTEMP
DROP TABLE TDTEMP
DROP TABLE TDTEMP2

IF @@ERROR = 0 AND @errcode = 0
	RETURN 0
ELSE
	RaisError('Unable To successfully transfer inter godown transfers', 16, 1)

RETURN -1
GO

-- SP_TransferPurchaseInvoices (last defined by script catalog)
CREATE PROCEDURE SP_TransferPurchaseInvoices
	@SRV VARCHAR(50), 
	@DB VARCHAR(50),
	@OWNER VARCHAR(20), 
	@USERCODE SMALLINT, 
	@LOGID INT OUTPUT  
AS    
SET NOCOUNT ON  
SET ANSI_NULLS ON  
SET ANSI_WARNINGS ON    

DECLARE @srcupd NVARCHAR(1000), @batch VARCHAR(100), @full_table_name NVARCHAR(255), @ItemName Varchar(100)
DECLARE @sqlheader NVARCHAR(1000), @sqldetail NVARCHAR(1000), @sql NVARCHAR(3000), @list NVARCHAR(3000)
DECLARE @table_id INT, @headercount INT, @TabMaxKey INT, @HeaderTabMaxKey INT, @HeaderCode INT
DECLARE @OldInvCode INT, @PurCatCode INT, @ICode INT, @GCode INT, @ThisCount INT, @RetCode INT, @ImportCount INT
DECLARE @PurRowID INT, @PackQty INT, @LooseQty INT, @BonusQty INT, @PackUnits INT, @Qty INT, @errcode INT
DECLARE @DetailCount BIGINT, @MaxUtn BIGINT
DECLARE @Expiry DATETIME  DECLARE @ItemCost FLOAT, @Stock FLOAT, @NewAvgPrice FLOAT, @InvDiscPerc FLOAT, @PurPrice FLOAT, @DiscPerc FLOAT, @RPP FLOAT, @UnitSaleTax FLOAT, @GstPerc FLOAT, @InvGstPerc1 FLOAT, @AvgPrice FLOAT

SET @sqlheader = N'SELECT T.*, OLDINVCODE=T.PURINVCODE INTO PLTEMP FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.PurLedger AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' '
SET @sqldetail = N'SELECT T.*, OLDINVCODE=T.PURINVCODE INTO PDTEMP FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.PurDetail AS T WHERE T.PurInvCode IN (SELECT PurinvCode FROM PLTEMP)'
SET @srcupd = N'UPDATE ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.PurLedger SET TRANSFERED=''Y'', TRANSFEREDON = GETDATE(), TRANSFEREDBY = ' + LTRIM(RTRIM(STR(@USERCODE))) + ' WHERE PURINVCODE IN (SELECT OLDINVCODE FROM PLTEMP WHERE PURINVCODE >= 0)'

EXECUTE (@sqlheader)
SET @errcode = @@ERROR  IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RAISERROR('Error Fetching The Required Purchase Invoices From Source Database', 16, 1)
	RETURN -1
END

SET @headercount = ISNULL((SELECT ISNULL(COUNT(*), 0) FROM PLTEMP), 0)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0 OR @headercount <= 0
BEGIN
	RETURN 0
END

EXECUTE (@sqldetail)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in fetching Purchase Invoices Detail', 16, 1)
	RETURN -1
END

SET @detailcount = ISNULL((SELECT ISNULL(COUNT(*), 0) FROM PDTEMP), 0)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0 OR @detailcount <= 0
BEGIN
	RaisError('Problem in fetching Purchase Invoices Detail', 16, 1)
	RETURN -1
END

EXECUTE @errcode = SP_GetTabMaxkey 'datatransferlog' , @LOGID Output
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in generating data transfer log', 16, 1)
	RETURN -1
END

EXECUTE @errcode = SP_MaxUtn @DetailCount, @maxutn OUTPUT
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in generating purchase invoice(s) number', 16, 1)
	RETURN -1
END

SET @errcode = 0
DECLARE pur1 CURSOR FOR
SELECT OldInvCode, PurCatCode, DiscPerc, InvGstPerc1, HeaderNo=ISNULL(HeaderNo, 1)
FROM PLTEMP
ORDER BY OldInvCode
OPEN pur1

FETCH NEXT FROM pur1 
INTO @OldInvCode, @PurCatCode, @InvDiscPerc, @InvGstPerc1, @HeaderCode
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @ThisCount = 0

	DECLARE pur2 CURSOR FOR
	SELECT ICode, GCode, Batch, Expiry, PurRowID, PackQty, LooseQty, BonusQty, PackUnits, PurPrice, DiscPerc, UnitSalesTax, GstPerc
	FROM PDTEMP
	WHERE OLDINVCODE = @OldInvCode
	ORDER BY PurRowID
	
	OPEN pur2

	FETCH NEXT FROM pur2 
	INTO @ICode, @GCode, @Batch, @Expiry, @PurRowID, @PackQty, @LooseQty, @BonusQty, @PackUnits, @PurPrice, @DiscPerc, @UnitSaleTax, @GstPerc
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @ItemName = ISNULL((SELECT name FROM ITEM WHERE ICODE = @ICODE), '')
		IF @PurCatCode = 1 OR @PurCatCode = 2
		BEGIN
			SET @Qty = (@PackQty + @BonusQty) * @PackUnits
			SET @ItemCost = ISNULL((SELECT @PackQty * @PurPrice * (1 - @DiscPerc * 0.01) * (1 - @InvDiscPerc * 0.01)), 0)
			SET @RPP = Round((@PurPrice * (1 - @DiscPerc * .01) * (1 - @InvDiscPerc * .01) * @Packqty) / (@Packqty + @Bonusqty), 2) + @UnitSaleTax + Round(Round(@PurPrice * (1 - @DiscPerc * .01), 2) * @GstPerc * 0.01,2) + Round ((Round(@PurPrice * ( 1 - @DiscPerc * .01),2) * (1 - @InvDiscPerc * .01)) * @InvGstPerc1 * 0.01,2)
			SET @AvgPrice=0
			SET @NewAvgPrice=0

			UPDATE ITEM
			SET PurPrice = CASE (SELECT a=DBO.Fn_GetPreference('UpdatePurPrice')) 
					WHEN 'Y' THEN ISNULL(@PurPrice, 0) 
					ELSE ISNULL(Item.PurPrice, 0) END,
				PurDiscPerc = CASE (SELECT a=DBO.Fn_GetPreference('UpdatePurDisc')) 
					WHEN 'Y' THEN ISNULL(@DiscPerc, 0) 
					ELSE ISNULL(Item.PurDiscPerc, 0) END,
				SaleDiscPerc = CASE (SELECT a=DBO.Fn_GetPreference('PurReplaceItemSaledisc')) 
					WHEN 'Y' THEN 
						CASE (SELECT a=DBO.Fn_Get_INT_Preference('PurReplaceItemSalediscNo'))
						WHEN 1 THEN ISNULL(@DiscPerc, 0) 
						ELSE ISNULL(Item.SaleDiscPerc , 0) END 
					ELSE  ISNULL(Item.SaleDiscPerc , 0) END,
				SaleDiscPerc2 = CASE (SELECT a=DBO.Fn_GetPreference('PurReplaceItemSaledisc'))
					WHEN 'Y' THEN 
						CASE (SELECT a=DBO.Fn_Get_INT_Preference('PurReplaceItemSalediscNo')) 
						WHEN 2 THEN ISNULL(@DiscPerc, 0) 
						ELSE ISNULL(Item.SaleDiscPerc2, 0) END 
					ELSE ISNULL(Item.SaleDiscPerc2, 0) END,
				SaleDiscPerc3 = CASE (SELECT a=DBO.Fn_GetPreference('PurReplaceItemSaledisc')) 
					WHEN 'Y' THEN 
						CASE (SELECT a=DBO.Fn_Get_INT_Preference('PurReplaceItemSalediscNo'))
						WHEN 3 THEN ISNULL(@DiscPerc, 0) 
						ELSE ISNULL(Item.SaleDiscPerc3, 0) END 
					ELSE ISNULL(Item.SaleDiscPerc3, 0) END,
				SaleDiscPerc4 = CASE (SELECT a=DBO.Fn_GetPreference('PurReplaceItemSaledisc')) 
					WHEN 'Y' THEN 
						CASE (SELECT a=DBO.Fn_Get_INT_Preference('PurReplaceItemSalediscNo')) 
						WHEN 4 THEN ISNULL(@DiscPerc, 0) 
						ELSE ISNULL(Item.SaleDiscPerc4, 0) END 
					ELSE ISNULL(Item.SaleDiscPerc4, 0) END,
				SaleDiscPerc5 = CASE (SELECT a=DBO.Fn_GetPreference( 'PurReplaceItemSaledisc' )) 
					WHEN 'Y' THEN 
						CASE (SELECT a=DBO.Fn_Get_INT_Preference( 'PurReplaceItemSalediscNo' ))
						WHEN 5 THEN ISNULL(@DiscPerc, 0)
						ELSE ISNULL(Item.SaleDiscPerc5, 0) END
					ELSE ISNULL(Item.SaleDiscPerc5, 0) END,
				RecentPurPrice5 = ISNULL(RecentPurPrice4, 0),
				RecentPurPrice4 = ISNULL(RecentPurPrice3, 0),
				RecentPurPrice3 = ISNULL(RecentPurPrice2, 0),
				RecentPurPrice2 = ISNULL(RecentPurPrice, 0),
				RecentPurPrice = ISNULL(@RPP, 0)
			WHERE ICODE = @ICode
		END
		ELSE
		BEGIN
			SET @Qty = @LooseQty + @BonusQty
			SET @ItemCost = ISNULL((SELECT @LooseQty * @PurPrice * (1 - @DiscPerc * 0.01) * (1 - @InvDiscPerc * 0.01)), 0)
		END

		EXECUTE @errcode = SP_GetItemAvgPrice @ICode, @AvgPrice OUTPUT
		IF @@Error <> 0 OR @errcode <> 0
		BEGIN
			CLOSE pur2
			DEALLOCATE pur2
			CLOSE pur1
			DEALLOCATE pur1
			RETURN -1
		END

		EXECUTE SP_GetItemStockAll @ICode, @Stock OUTPUT
		IF @@Error <> 0
		BEGIN
			SET @Stock = 0
		END

		UPDATE PDTEMP
		SET AvgPrice = @AvgPrice, 
			PurUtn = @MaxUtn, 
			CurrStock = @Stock, 
			NewAvgPrice = ((@AvgPrice * @Stock) + (@ItemCost)) / CASE @Qty + @Stock WHEN 0 THEN 1 ELSE (@Qty + @Stock) END
		WHERE PurRowID=@PurRowID

		IF @@RowCount = 0
		BEGIN
			RAISERROR('Problem processing purchase invoice # %d, item = (%s)', 16, 1, @OldInvCode, @ItemName)
			CLOSE pur2
			DEALLOCATE pur2
			CLOSE pur1
			DEALLOCATE pur1
			RETURN -1
		END

		SET @NewAvgPrice = ISNULL((SELECT NewAvgPrice FROM PDTEMP WHERE PurRowID=@PurRowID), 0)
		SET @STOCK = 0

		EXECUTE SP_UpdateItemAvgPrice @ICode, @NewAvgPrice
		IF @@Error <> 0
		BEGIN
			RAISERROR('Problem in updating item average price on purchase invoice # %d, item = (%s)', 16, 1, @OldInvCode, @ItemName)
			CLOSE pur2
			DEALLOCATE pur2
			CLOSE pur1
			DEALLOCATE pur1
			RETURN -1
		END

		EXECUTE @errcode = SP_GetItemStockBatch @GCode, @ICode, @Batch, @Expiry, @Stock OUTPUT
		IF @@Error <> 0 OR @errcode <> 0
		BEGIN
			CLOSE pur2
			DEALLOCATE pur2
			CLOSE pur1
			DEALLOCATE pur1
			RETURN -1
		END

		SET @Stock = @Stock + @Qty
		EXECUTE @errcode = SP_UpdateItemStockBatch @GCode, @ICode, @Batch, @Expiry, @Stock
		IF @@Error <> 0 OR @errcode <> 0
		BEGIN
			CLOSE pur2
			DEALLOCATE pur2
			CLOSE pur1
			DEALLOCATE pur1
			RETURN -1
		END

		SET @MaxUtn = @MaxUtn + 1

		UPDATE PDTemp 
		SET PURINVCODE=-1000 
		WHERE PurRowID = @PurRowID

		SET @ThisCount = @ThisCount + 1
		FETCH NEXT FROM pur2 
		INTO @ICode, @GCode, @Batch, @Expiry, @PurRowID, @PackQty, @LooseQty, @BonusQty, @PackUnits, @PurPrice, @DiscPerc, @UnitSaleTax, @GstPerc
	END
	CLOSE pur2
	DEALLOCATE pur2

	IF @ThisCount = 0
	BEGIN
		UPDATE PLTEMP SET PURINVCODE = -1000 
		WHERE OldInvCode = @OldInvCode
	END
	ELSE
	BEGIN
		EXECUTE @errcode = SP_GetTabMaxkey 'purledger', @TABMAXKEY Output
		IF @@ERROR <> 0 OR @errcode <> 0
		BEGIN
			CLOSE pur1
			DEALLOCATE pur1
			RETURN -1
		END

		EXECUTE @errcode = SP_GetHeaderTabMaxkey @HeaderCode, 3, @HeaderTabMaxKey Output

		IF @@ERROR <> 0 OR @errcode <> 0
		BEGIN
			CLOSE pur1
			DEALLOCATE pur1
			RETURN -1
		END

		UPDATE PLTEMP 
		SET PURINVCODE = @TabMaxKey, HeaderNo = ISNULL(@HeaderCode, 1), 
			HEADERINVNO = @HeaderTabMaxKey, POCODE = NULL, 
			PaymentMode=NULL, PaymentAccCode = Null, Amt=0, AmtDate=Null, 
			AmtBy=NULL, AmtReference=NULL, OutstandingAmt=0, Marked='N', 
			SalesmanCode = @USERCODE, ModifiedBy = NULL, POSTED='Y', 
			POSTEDBY=@USERCODE, TRANSFERABLE='N', TRANSFERED='N', 
			TRANSFEREDBY=NULL, TRANSFEREDON=NULL, IMPORTED='Y', 
			IMPORTEDBY=@UserCode
		WHERE OLDINVCODE = @OldInvCode

		UPDATE PDTEMP
		SET PURINVCODE = @TabMaxKey
		WHERE OLDINVCODE = @OldInvCode
	END
	FETCH NEXT FROM pur1 INTO @OldInvCode, @PurCatCode, @InvDiscPerc, @InvGstPerc1, @HeaderCode
END
CLOSE pur1
DEALLOCATE pur1

SET @ImportCount = 
	ISNULL((SELECT COUNT(*) 
		FROM PLTEMP 
		WHERE PLTEMP.PURINVCODE >= 0), 0)

IF @ImportCount > 0
BEGIN
	UPDATE PLTEMP SET PLTEMP.INVTOTAL = p.Net
	FROM PLTEMP, 
		(SELECT PurInvcode=pl.purinvcode, 
			Net=ROUND(SUM((pd.looseqty + pd.packqty + pd.bonusqty) * pd.unitsalestax) + 
					SUM(ROUND((pd.looseqty + pd.packqty) * pd.purprice * (1 - (.01 * pd.discperc)) * pd.gstperc * .01, 2)) + 
				ROUND((SUM(((pd.looseqty + pd.packqty) * pd.purprice) * (1 - (.01 * pd.discperc))) * (1- (.01 * pl.discperc)) - pl.flatdisc) * (pl.invgstperc1 * .01), 2), 0) + 
				ROUND(SUM((pd.looseqty + pd.packqty) * pd.purprice * (1 - (.01 * pd.discperc))) * (1- (.01 * pl.discperc)) +      pl.misccharges + pl.salestax - pl.flatdisc, 0)
		FROM PLTEMP pl, PDTEMP pd
		WHERE pl.purinvcode = pd.purinvcode
		GROUP BY pl.purinvcode, pl.suppcode, pl.purcatcode, pl.postdate,
			pl.discperc, pl.misccharges, pl.salestax, pl.flatdisc, pl.InvGSTPerc1) p
	WHERE PLTEMP.PurInvCode >= 0 AND 
	PLTEMP.purinvcode = p.purinvcode

	UPDATE PLTEMP SET OutstandingAmt=InvTotal 
	WHERE PLTEMP.PurInvCode >= 0

	SET XACT_ABORT ON
	EXECUTE (@SRCUPD)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update the transfer status at source database', 16, 1)
		RETURN -1
	END
	SET XACT_ABORT OFF
	SET @LIST=''

	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'PurLedger', @LIST OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update purchase header', 16, 1)
		RETURN -1
	END

	SET @SQL = N'INSERT INTO PURLEDGER ( ' + @LIST + ' ) ' + 'SELECT ' + @LIST + ' FROM PLTEMP WHERE PLTEMP.PURINVCODE >= 0'

	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update purchase header', 16, 1)
		RETURN -1
	END

	SET @LIST=''
	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'PurDetail', @LIST OUTPUT
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update purchase detail', 16, 1)
		RETURN -1
	END

	SET @SQL = N'INSERT INTO PURDETAIL ( ' + @LIST + ' ) ' + 'SELECT ' + @LIST + ' FROM PDTEMP WHERE PDTEMP.PURINVCODE >= 0'
	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update purchase detail', 16, 1)
		RETURN -1
	END
END
IF @@ERROR = 0 AND @errcode = 0
BEGIN
	INSERT INTO DataTransferLog (TRANSFERLOGID, LOGDATE, TRANSFEREDBY, INVOICECODE, INVOICETYPE, DATE, ACCCODE, SGCODE, DGCODE, STATUS)
	SELECT  @LOGID, LOGDATE=GETDATE(), TRANSFEREDBY=@UserCode, INVOICECODE=OLDINVCODE, 
		INVOICETYPE=3, DATE=GETDATE(), ACCCODE=SUPPCODE, NULL, NULL,
		STATUS = CASE PURINVCODE WHEN -1000 THEN 0 ELSE 1 END
	FROM PLTEMP

	INSERT INTO DataTransferLogDetail (TRANSFERLOGID, INVOICECODE, INVOICETYPE, ICODE, GCODE, BATCH, EXPIRY, QTY, BONUSQTY, PRICE, STATUS)
	SELECT @LOGID, INVOICECODE=OLDINVCODE, INVOICETYPE=3, ICODE, GCODE, BATCH, EXPIRY, QTY=LOOSEQTY+PACKQTY, BONUSQTY, PurPrice, 
		STATUS = CASE PURINVCODE WHEN -1000 THEN 0 ELSE 1 END
	FROM PDTEMP
END

DROP TABLE PLTEMP
DROP TABLE PDTEMP
IF @@ERROR = 0 AND @errcode = 0
	RETURN 0
ELSE
	RaisError('Unable To successfully transfer purchase invoices', 16, 1)

RETURN -1
GO

-- SP_TransferPurchaseInvoices2 (last defined by script catalog)
CREATE   PROCEDURE SP_TransferPurchaseInvoices2 
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20), 
	@USERCODE SMALLINT, 
	@LOGID INT OUTPUT
AS

SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DECLARE @srcupd NVARCHAR(1000), @batch VARCHAR(100), @full_table_name NVARCHAR(255), @ItemName Varchar(100)
DECLARE @sqlheader NVARCHAR(1000), @sqldetail NVARCHAR(1000), @sql NVARCHAR(3000), @list NVARCHAR(3000)
DECLARE @table_id INT, @headercount INT, @TabMaxKey INT, @HeaderTabMaxKey INT, @HeaderCode INT
DECLARE @OldInvCode INT, @PurCatCode INT, @ICode INT, @GCode INT, @ThisCount INT, @RetCode INT, @ImportCount INT
DECLARE @PurRowID INT, @PackUnits INT, @errcode INT
DECLARE @PackQty NUMERIC(15, 4), @LooseQty NUMERIC(15, 4), @BonusQty NUMERIC(15, 4), @Qty NUMERIC(15, 4)
DECLARE @DetailCount BIGINT, @MaxUtn BIGINT
DECLARE @Expiry DATETIME
DECLARE @ItemCost FLOAT, @Stock NUMERIC(15, 4), @NewAvgPrice NUMERIC(15, 5), @InvDiscPerc FLOAT, @PurPrice NUMERIC(15, 5), @DiscPerc FLOAT, @RPP NUMERIC(15, 5), @UnitSaleTax FLOAT, @GstPerc FLOAT, @InvGstPerc1 FLOAT, @AvgPrice NUMERIC(15, 5)

SET @sqlheader = N'SELECT T.*, OLDINVCODE=T.PURINVCODE INTO PLTEMP FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.PurLedger AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' '
SET @sqldetail = N'SELECT T.*, OLDINVCODE=T.PURINVCODE INTO PDTEMP FROM ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.PurDetail AS T WHERE T.PurInvCode IN (SELECT PurinvCode FROM PLTEMP) ORDER BY T.PurRowID'
SET @srcupd = N'UPDATE ' + LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.PurLedger SET TRANSFERED=''Y'', TRANSFEREDON = GETDATE(), TRANSFEREDBY = ' + LTRIM(RTRIM(STR(@USERCODE))) + ' WHERE PURINVCODE IN (SELECT OLDINVCODE FROM PLTEMP WHERE PURINVCODE >= 0)'

EXECUTE (@sqlheader)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RAISERROR('Error Fetching The Required Purchase Invoices From Source Database', 16, 1)
	RETURN -1
END

SET @headercount = ISNULL((SELECT ISNULL(COUNT(*), 0) FROM PLTEMP), 0)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0 OR @headercount <= 0
BEGIN
	RETURN 0
END

EXECUTE (@sqldetail)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in fetching Purchase Invoices Detail', 16, 1)
	RETURN -1
END

SET @detailcount = ISNULL((SELECT ISNULL(COUNT(*), 0) FROM PDTEMP), 0)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0 OR @detailcount <= 0
BEGIN
	RaisError('Problem in fetching Purchase Invoices Detail', 16, 1)
	RETURN -1
END

EXECUTE @errcode = SP_GetTabMaxkey 'datatransferlog' , @LOGID Output
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in generating data transfer log', 16, 1)
	RETURN -1
END

SET @errcode = 0

DECLARE pur1 CURSOR FOR
SELECT OldInvCode, PurCatCode, DiscPerc, InvGstPerc1, HeaderNo=ISNULL(HeaderNo, 1)
FROM PLTEMP
ORDER BY OldInvCode

OPEN pur1

FETCH NEXT FROM pur1 INTO @OldInvCode, @PurCatCode, @InvDiscPerc, @InvGstPerc1, @HeaderCode
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @ThisCount = 0

	DECLARE pur2 CURSOR FOR
	SELECT ICode, GCode, Batch, Expiry, PurRowID, PackQty, LooseQty, BonusQty, PackUnits, PurPrice, DiscPerc, UnitSalesTax, GstPerc
	FROM PDTEMP
	WHERE OLDINVCODE = @OldInvCode
	ORDER BY PurRowID

	OPEN pur2

	FETCH NEXT FROM pur2 INTO @ICode, @GCode, @Batch, @Expiry, @PurRowID, @PackQty, @LooseQty, @BonusQty, @PackUnits, @PurPrice, @DiscPerc, @UnitSaleTax, @GstPerc
	WHILE @@FETCH_STATUS = 0
	BEGIN
		UPDATE PDTemp SET PURINVCODE=-1000 WHERE PurRowID = @PurRowID
		SET @ThisCount = @ThisCount + 1

		FETCH NEXT FROM pur2 INTO @ICode, @GCode, @Batch, @Expiry, @PurRowID, @PackQty, @LooseQty, @BonusQty, @PackUnits, @PurPrice, @DiscPerc, @UnitSaleTax, @GstPerc
	END
	CLOSE pur2
	DEALLOCATE pur2

	IF @ThisCount = 0 
	BEGIN
		UPDATE PLTEMP
		SET PURINVCODE = -1000 WHERE OldInvCode = @OldInvCode
	END
	ELSE
	BEGIN

		EXECUTE @errcode = SP_GetTabMaxkey 'purledger', @TABMAXKEY Output
		IF @@ERROR <> 0 OR @errcode <> 0
		BEGIN
			CLOSE pur1
			DEALLOCATE pur1
			RETURN -1
		END

		EXECUTE @errcode = SP_GetHeaderTabMaxkey @HeaderCode, 3, @HeaderTabMaxKey Output
		IF @@ERROR <> 0 OR @errcode <> 0
		BEGIN
			CLOSE pur1
			DEALLOCATE pur1
			RETURN -1
		END

		UPDATE PLTEMP
		SET PURINVCODE = @TabMaxKey, HeaderNo = ISNULL(@HeaderCode, 1), 
			HEADERINVNO = @HeaderTabMaxKey, POCODE = NULL, 
			PaymentMode=NULL, PaymentAccCode = Null, Amt=0, 
			AmtDate=Null, AmtBy=NULL, AmtReference=NULL, 
			OutstandingAmt=0, Marked='N', SalesmanCode = @USERCODE, 
			ModifiedBy = NULL, POSTED='N', POSTEDBY=NULL, 
			TRANSFERABLE='N', TRANSFERED='N', TRANSFEREDBY=NULL, 
			TRANSFEREDON=NULL, IMPORTED='Y', IMPORTEDBY=@UserCode
		WHERE OLDINVCODE = @OldInvCode

		UPDATE PDTEMP
		SET PURINVCODE = @TabMaxKey
		WHERE OLDINVCODE = @OldInvCode
	END
	
	FETCH NEXT FROM pur1 INTO @OldInvCode, @PurCatCode, @InvDiscPerc, @InvGstPerc1, @HeaderCode
END
CLOSE pur1
DEALLOCATE pur1

SET @ImportCount = ISNULL((SELECT COUNT(*) FROM PLTEMP WHERE PLTEMP.PURINVCODE >= 0), 0)

IF @ImportCount > 0
BEGIN
	UPDATE PLTEMP
	SET PLTEMP.INVTOTAL = p.Net
	FROM PLTEMP, 
	(SELECT PurInvcode=pl.purinvcode,
		Net=ROUND(
		SUM((pd.looseqty + pd.packqty + pd.bonusqty) * pd.unitsalestax) +
		SUM(ROUND((pd.looseqty + pd.packqty) * pd.purprice * 
			(1 - (.01 * pd.discperc)) * pd.gstperc * .01, 2)) +
		ROUND((SUM(((pd.looseqty + pd.packqty) * pd.purprice) * (1 - (.01 * pd.discperc))) * 
			(1- (.01 * pl.discperc)) - pl.flatdisc) * (pl.invgstperc1 * .01), 2), 0) + 
		ROUND(SUM((pd.looseqty + pd.packqty) * pd.purprice * (1 - (.01 * pd.discperc))) * (1- (.01 * pl.discperc)) + 
			pl.misccharges + pl.salestax - pl.flatdisc, 0)
	FROM     PLTEMP pl,
		 PDTEMP pd
	WHERE    	 
		 pl.purinvcode = pd.purinvcode 
	GROUP BY pl.purinvcode,
		 pl.suppcode, 
		 pl.purcatcode,
		 pl.postdate,
		 pl.discperc,
		 pl.misccharges,
		 pl.salestax,
		 pl.flatdisc,
		 pl.InvGSTPerc1) p
	WHERE PLTEMP.PurInvCode >= 0 AND PLTEMP.purinvcode = p.purinvcode

	UPDATE PLTEMP SET OutstandingAmt=InvTotal WHERE PLTEMP.PurInvCode >= 0 

	SET XACT_ABORT ON
	EXECUTE (@SRCUPD)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update the transfer status at source database', 16, 1)
		RETURN -1
	END

	SET XACT_ABORT OFF

	SET @LIST=''
	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'PurLedger', @LIST OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update purchase header', 16, 1)
		RETURN -1
	END

	SET @SQL = N'INSERT INTO PURLEDGER ( ' + @LIST + ' ) ' + 'SELECT ' + 
		@LIST +	' FROM PLTEMP WHERE PLTEMP.PURINVCODE >= 0'
	
	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update purchase header', 16, 1)
		RETURN -1
	END

	SET @LIST=''
	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'PurDetail', @LIST OUTPUT
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update purchase detail', 16, 1)
		RETURN -1
	END

	SET @SQL = N'INSERT INTO PURDETAIL ( ' + @LIST + ' ) ' + 'SELECT ' + 
		@LIST +	' FROM PDTEMP WHERE PDTEMP.PURINVCODE >= 0 ORDER BY PDTEMP.PurRowID'

	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update purchase detail', 16, 1)
		RETURN -1
	END
END

IF @@ERROR = 0 AND @errcode = 0
BEGIN
	INSERT INTO DataTransferLog (TRANSFERLOGID, LOGDATE, TRANSFEREDBY, INVOICECODE, INVOICETYPE, DATE, ACCCODE, SGCODE, DGCODE, STATUS)
	SELECT  @LOGID, LOGDATE=GETDATE(), TRANSFEREDBY=@UserCode, INVOICECODE=OLDINVCODE, 
		INVOICETYPE=3, DATE=GETDATE(), ACCCODE=SUPPCODE, NULL, NULL,
		STATUS = CASE PURINVCODE WHEN -1000 THEN 0 ELSE 1 END
	FROM PLTEMP

	INSERT INTO DataTransferLogDetail (TRANSFERLOGID, INVOICECODE, INVOICETYPE, ICODE, GCODE, BATCH, EXPIRY, QTY, BONUSQTY, PRICE, STATUS)
	SELECT @LOGID, INVOICECODE=OLDINVCODE, INVOICETYPE=3, ICODE, GCODE, BATCH, 
		EXPIRY, QTY=LOOSEQTY+PACKQTY, BONUSQTY, PurPrice, 
		STATUS = CASE PURINVCODE WHEN -1000 THEN 0 ELSE 1 END
	FROM PDTEMP
	ORDER BY PurRowID
END

DROP TABLE PLTEMP
DROP TABLE PDTEMP

IF @@ERROR = 0 AND @errcode = 0
	RETURN 0
ELSE
	RaisError('Unable To successfully transfer purchase invoices', 16, 1)
	RETURN -1
GO

-- SP_TransferSaleIntoSaleOrders (last defined by script catalog)
CREATE  PROCEDURE SP_TransferSaleIntoSaleOrders
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20), 
	@USERCODE SMALLINT, 
	@StartSaleOrderCode INT OUTPUT,
	@EndSaleOrderCode INT OUTPUT  AS

/*SET environment*/
SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

/*Declare Variables*/
DECLARE @TableQualifier NVARCHAR(4000), @SRCUPD NVARCHAR(4000), @Batch VARCHAR(100),
	@ItemName Varchar(100), @SQLHEADER NVARCHAR(4000), @SQLDETAIL NVARCHAR(4000), 
	@SQL NVARCHAR(4000), @LIST NVARCHAR(4000)
DECLARE @HeaderCount INT, @TabMaxKey INT, @HeaderTabMaxKey INT, 
	@HeaderCode INT, @errcode INT, @OldInvCode INT, @SaleCatCode INT, 
	@RetCode INT, @RowID INT, @InvCount INT
DECLARE @DetailCount BIGINT
DECLARE @Tab_SO TABLE (SaleInvCode INT NOT NULL, NewSaleOrderCode INT NOT NULL, RowID INT IDENTITY(0,1))

/*
Prepare TableQualifier Variable from passed parameters
*/
SET @TableQualifier = LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner))

/*
Prepare DML statements to Get Data from the Source
*/
SET @SQLHEADER = N'SELECT T.*, OLDINVCODE=T.SaleInvCode, NewSaleOrderCode=-1 INTO SOHTEMP FROM ' + 
	@TableQualifier + 
	'.SaleLedger AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' '

SET @SQLDETAIL = N'SELECT T.*, OLDINVCODE=T.SaleInvCode, NewSaleOrderCode=-1 INTO SODTEMP FROM ' + 
	@TableQualifier + 
	'.SaleDetail AS T WHERE T.SaleInvCode IN (SELECT SaleInvCode FROM SOHTEMP) ORDER BY T.RowID'

SET @SRCUPD = N'UPDATE ' + @TableQualifier + 
	'.SaleLedger SET TRANSFERED=''Y'', TRANSFEREDON = GETDATE(), TRANSFEREDBY = ' + 
	LTRIM(RTRIM(STR(@USERCODE))) + 
	' WHERE SaleInvCode IN (SELECT OLDINVCODE FROM SOHTEMP WHERE SaleInvCode >= 0)'

/*
Get Data from the Source (Sale Header)
*/
EXECUTE (@sqlheader)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RAISERROR('Error Fetching The Required Sales Invoices From Source Database', 16, 1)
	RETURN -1
END

/*
Get Sale Header Counter if zero than return from here
*/
SET @headercount = (SELECT ISNULL(COUNT(*), 0) FROM SOHTEMP)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0 OR @headercount <= 0
BEGIN
	RETURN 0
END

/*
Get Data from the Source (Sale Detail)
*/
EXECUTE (@sqldetail)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in fetching Sales Invoices Detail', 16, 1)
	RETURN -1
END

SET @InvCount = ISNULL((SELECT COUNT(SaleInvCode) FROM SOHTEMP), 0)

EXECUTE @errcode = SP_GetTabMaxkey 'SaleOrderHeader' , @StartSaleOrderCode Output
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in generating sale order header', 16, 1)
	RETURN -1
END

INSERT INTO @Tab_SO (SaleInvCode, NewSaleOrderCode)
SELECT SaleInvCode, NewSaleOrderCode=0 
FROM SOHTEMP WHERE SaleInvCode > 0
IF @@ERROR <> 0
BEGIN
	RaisError('Problem in inserting row in temporary table, Error Code = %d ', 16, 1, @@ERROR)
	RETURN -1
END

UPDATE @Tab_SO SET NewSaleOrderCode = @StartSaleOrderCode + RowID
IF @@ERROR <> 0
BEGIN
	RaisError('Problem in generating new sale order code in temporary table ', 16, 1)
	RETURN -1
END

UPDATE SOHTEMP SET NewSaleOrderCode = (SELECT NewSaleOrderCode FROM @Tab_SO T WHERE T.SaleInvCode = SOHTEMP.SaleInvCode)
IF @@ERROR <> 0
BEGIN
	RaisError('Problem in updating new sale order code in SOHTEMP table ', 16, 1)
	RETURN -1
END

UPDATE SODTEMP SET NewSaleOrderCode = (SELECT SOHTEMP.NewSaleOrderCode FROM SOHTEMP WHERE SOHTEMP.SaleInvCode = SODTEMP.SaleInvCode)
IF @@ERROR <> 0
BEGIN
	RaisError('Problem in updating new sale order code in SODTEMP table ', 16, 1)
	RETURN -1
END

INSERT INTO SaleOrderHeader (SaleOrderCode,CustCode,UserCode,Date,OriginalDate,BillingDate,DiscPerc,FlatDisc,MiscCharges,InvGSTPerc1,Posted,PostDate,HeaderNo,HeaderInvNo,ModifiedBy,PostedBy,DoctCode,PatientCode,MessageCode,SManCode,RelationCode,DiseaseCode,WardCode,InvoiceSize,GSTNO,InvTotal,SPrice,Remarks,CustRefNo,CustRefno2,CustRefno3,CustRefno4,Deleted,Finalized,GRN,SuppInvCode,OldSaleInvCode) 
SELECT NewSaleOrderCode,CustCode,SalesManCode,Date,OriginalDate,BillingDate,DiscPerc,FlatDisc,MiscCharges,InvGSTPerc1,Posted='N',PostDate,HeaderNo,HeaderInvNo,ModifiedBy,PostedBy,DoctCode,PatientCode,MessageCode,SManCode,RelationCode,DiseaseCode,WardCode,InvoiceSize,GSTNO,InvTotal,SPrice,Remarks,CustRefNo,CustRefno2,CustRefno3,CustRefno4,Deleted,Finalized='N',GRN,SuppInvCode,OldSaleInvCode=OldInvcode 
FROM SOHTEMP
IF @@ERROR <> 0
BEGIN
	RaisError('Problem in inserting sale order header', 16, 1)
	RETURN -1
END

INSERT INTO DBO.SaleOrderDetail (SaleOrderCode, ICode, GCode, LooseQty, PackUnits, SalePrice, AvgPrice, Rate, DiscPerc, ItemFlatDisc, SaleItemDescription, PackPrice, UnitSalesTax, GSTPerc, BonusQty, RowGroup, PackQtyForSale, BonusPackQtyForSale, Remarks, SaleOrderItemStatusCode, QuotationRowID, PrescriptionRowID, Batch, Expiry)
SELECT NewSaleOrderCode, ICode, GCode, LooseQty=SUM(LooseQty), PackUnits, SalePrice=MAX(SalePrice), AvgPrice=Max(AvgPrice), Rate=MAX(Rate), DiscPerc=MAX(DiscPerc), ItemFlatDisc=MAX(ItemFlatDisc), SaleItemDescription, PackPrice=MAX(PackPrice), UnitSalesTax=MAX(UnitSalesTax), GSTPerc=MAX(GSTPerc), BonusQty=MAX(BonusQty), RowGroup=1, PackQtyForSale=0, BonusPackQtyForSale=0, Remarks=SaleItemDescription, SaleOrderItemStatusCode=NULL, QuotationRowID=NULL, PrescriptionRowID=NULL, Batch='.', Expiry='12-12-2222'
FROM SODTEMP
GROUP BY 
	NewSaleOrderCode, ICode, GCode, PackUnits, SaleItemDescription, SaleItemDescription
ORDER BY ROWID
IF @@ERROR <> 0
BEGIN
	RaisError('Problem in inserting sale order detail', 16, 1)
	RETURN -1
END

SET @EndSaleOrderCode = (SELECT MAX(NewSaleOrderCode) FROM SOHTEMP)

EXECUTE @errcode = SP_UpdateTabMaxKey 'SaleOrderHeader' , @EndSaleOrderCode
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in updating max sale order code', 16, 1)
	RETURN -1
END

SET XACT_ABORT ON
EXECUTE (@SRCUPD)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Unable To update the transfer status at source database', 16, 1)
	RETURN -1
END
SET XACT_ABORT OFF

DROP TABLE SOHTEMP
DROP TABLE SODTEMP

IF @@ERROR = 0 AND @errcode = 0
	RETURN 0
ELSE
	RaisError('Unable To successfully transfer sale orders', 16, 1)
	RETURN -1
GO

-- SP_TransferSaleInvoices (last defined by script catalog)
CREATE   PROCEDURE SP_TransferSaleInvoices 
	@SRV VARCHAR(50), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20), 
	@USERCODE SMALLINT, 
	@LogId INT OUTPUT  AS

/*SET environment*/
SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

/*Declare Variables*/
DECLARE @TableQualifier NVARCHAR(4000), @SRCUPD NVARCHAR(4000), @Batch VARCHAR(100),
	@ItemName Varchar(100), @SQLHEADER NVARCHAR(4000), @SQLDETAIL NVARCHAR(4000), 
	@SQL NVARCHAR(4000), @LIST NVARCHAR(4000)
DECLARE @HeaderCount INT, @TabMaxKey INT, @HeaderTabMaxKey INT, 
	@HeaderCode INT, @errcode INT, @OldInvCode INT, @SaleCatCode INT, 
	@ICode INT, @GCode INT, @ThisCount INT, @RetCode INT, @ImportCount INT,
	@ID INT, @PackUnits INT, @InserCount INT, 
	@RowGroup INT, @DefaultGST INT
DECLARE @TQty NUMERIC(15, 4), @TBQty NUMERIC(15, 4), @Qty NUMERIC(15, 4), @ReqQty NUMERIC(15, 4), 
	@Stock NUMERIC(15, 4), @NewStock NUMERIC(15, 4), @TotalStock NUMERIC(15, 4), @BatchStock NUMERIC(15, 4), 
	@BonusQty NUMERIC(15, 4), @DueQty NUMERIC(15, 4), @PackQty NUMERIC(15, 4), @LooseQty NUMERIC(15, 4)
DECLARE @DetailCount BIGINT, @MaxUtn BIGINT
DECLARE @Expiry DATETIME
DECLARE @PurPrice NUMERIC(15, 5), @SalePrice NUMERIC(15, 5), @DiscPerc FLOAT, @RPP NUMERIC(15, 5), 
	@AvgPrice NUMERIC(15, 5), @UnitSalesTax FLOAT, @GSTPerc FLOAT

/*
Prepare TableQualifier Variable from passed parameters
*/
SET @TableQualifier = LTRIM(RTRIM(@srv)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner))

/*
Prepare DML statements to Get Data from the Source
*/
SET @SQLHEADER = N'SELECT T.*, OLDINVCODE=T.SaleInvCode INTO SHTEMP FROM ' + 
	@TableQualifier + 
	'.SaleLedger AS T WHERE T.Transferable = ''Y'' and T.Transfered = ''N'' '

SET @SQLDETAIL = N'SELECT T.*, OLDINVCODE=T.SaleInvCode, ID2=0 INTO SDTEMP FROM ' + 
	@TableQualifier + 
	'.SaleDetail AS T WHERE T.SaleInvCode IN (SELECT SaleInvCode FROM SHTEMP) ORDER BY T.ROWID'

SET @SRCUPD = N'UPDATE ' + @TableQualifier + 
	'.SaleLedger SET TRANSFERED=''Y'', TRANSFEREDON = GETDATE(), TRANSFEREDBY = ' + 
	LTRIM(RTRIM(STR(@USERCODE))) + 
	' WHERE SaleInvCode IN (SELECT OLDINVCODE FROM SHTEMP WHERE SaleInvCode >= 0)'

/*
Get Data from the Source (Sale Header)
*/
EXECUTE (@sqlheader)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RAISERROR('Error Fetching The Required Sales Invoices From Source Database', 16, 1)
	RETURN -1
END

/*
Get Sale Header Counter if zero than return from here
*/
SET @headercount = (SELECT ISNULL(COUNT(*), 0) FROM SHTEMP)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0 OR @headercount <= 0
BEGIN
	RETURN 0
END

/*
Get Data from the Source (Sale Detail)
*/
EXECUTE (@sqldetail)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in fetching Sales Invoices Detail', 16, 1)
	RETURN -1
END

/*
Get Sale Detail item count
*/
SET @detailcount = (SELECT ISNULL(COUNT(*), 0) FROM SDTEMP)
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0 OR @detailcount <= 0
BEGIN
	RaisError('Problem in fetching Sales Invoices Detail', 16, 1)
	RETURN -1
END

/*
Get Primary Key value for fresh datatransfer log instance
*/
EXECUTE @errcode = SP_GetTabMaxkey 'datatransferlog' , @LOGID Output
SET @errcode = @@ERROR
IF @@ERROR <> 0 OR @errcode <> 0
BEGIN
	RaisError('Problem in generating data transfer log', 16, 1)
	RETURN -1
END

/*
Just to create a new table for batch wise breakup of each sale invoice, 
the from clause below returns just the structure with no rows
*/
SELECT * INTO SDTEMP2
FROM (SELECT * FROM SDTEMP WHERE SaleInvCode < 0 
	  UNION SELECT * FROM SDTEMP WHERE SaleInvCode < 0) A

IF @@ERROR <> 0 OR @@ROWCOUNT > 0
BEGIN
	RaisError('Problem in generating sales invoice(s) number', 16, 1)
	RETURN -1
END

/*
To Create the rowid (identity column) becuase SELECT INTO not returned IDENTITY COLUMN as 
by above query
*/
ALTER TABLE SDTEMP2 ALTER COLUMN RowID BIGINT

SET @errcode = 0

/*
Fetch sale header
*/
DECLARE sal1 CURSOR FOR
SELECT S.OldInvCode, S.SaleCatCode, HeaderNo=ISNULL(S.HeaderNo, 1), C.DefaultGST
FROM SHTEMP S, Customer C
WHERE S.CustCode = C.CustCode
ORDER BY OldInvCode

OPEN sal1

FETCH NEXT FROM sal1 INTO @OldInvCode, @SaleCatCode, @HeaderCode, @DefaultGST
WHILE @@FETCH_STATUS = 0
BEGIN
	SET @ThisCount = 0
	SET @RetCode = 0

	DECLARE sal2 CURSOR FOR
	SELECT	S.ICode, S.GCode, Id = max(S.RowID), PackQty = sum(S.PackQty), 
		BonusQty=sum(S.BonusQty), LooseQty = sum(S.LooseQty), S.RowGroup, 
		DueQty=SUM(CASE WHEN S.Due IS NULL THEN 0 ELSE S.LooseQty END),
		ItemGstPerc=CASE @DefaultGST WHEN 2 THEN I.GstPerc2 ELSE I.GstPerc1 END,
		UnitSalesTax=ROUND(I.PackSalesTax / CASE I.PackUnits WHEN 0 THEN 1 ELSE I.PackUnits END, 2),
		I.PackUnits, SalePrice=ROUND(I.SalePrice / CASE I.PackUnits WHEN 0 THEN 1 ELSE I.PackUnits END, 2)
	FROM	SDTEMP S, Item I
	WHERE	OldInvCode = @OldInvCode AND S.ICode = I.ICode
	GROUP BY 
		S.OldInvcode, 
		S.ICode, 
		S.RowGroup,
		S.Gcode,
		I.GstPerc1,
		I.GstPerc2,
		I.PackUnits,
		I.SalePrice,
		I.PackSalesTax
	ORDER BY ID

	OPEN sal2

	FETCH NEXT FROM sal2 INTO @ICode, @GCode, @ID, @PackQty, @BonusQty, 
			@LooseQty, @RowGroup, @DueQty, @GstPerc, @UnitSalesTax, @PackUnits, @SalePrice
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @ItemName = ISNULL((SELECT name FROM ITEM WHERE ICODE = @ICODE), '')
		SET @QTY = @LooseQty - @DueQty + @BonusQty
		SET @LooseQty = @LooseQty - @DueQty 
		IF @QTY >= 0 
		BEGIN
			IF @QTY > 0
			BEGIN
				SET @AvgPrice = 0
				SET @Stock = 0
				SET @TotalStock = 0
				SET @RetCode = 0

				EXECUTE @errcode = SP_GetItemAvgPrice @ICode, @AvgPrice OUTPUT
				IF @@Error <> 0 OR @errcode <> 0
				BEGIN
					CLOSE sal2
					DEALLOCATE sal2
					CLOSE sal1
					DEALLOCATE sal1
					RETURN -1			
				END
				EXECUTE SP_GetItemStockTotal @GCode, @ICode, @Stock OUTPUT
				IF @@Error <> 0
				BEGIN
					RaisError('Unable to fetch godown stock for sale # = %d, godown code = %d, item = (%s)', 
							16, 1, @OldInvCode, @GCode, @ItemName)
					CLOSE sal2
					DEALLOCATE sal2
					CLOSE sal1
					DEALLOCATE sal1
					RETURN -1
				END
				EXECUTE SP_GetItemStockAll @ICode, @TotalStock OUTPUT
				IF @@Error <> 0
				BEGIN
					RaisError('Unable to fetch total stock for sale # = %d, item = (%s)', 
						16, 1, @OldInvCode, @ItemName)
					CLOSE sal2
					DEALLOCATE sal2
					CLOSE sal1
					DEALLOCATE sal1
					RETURN -1
				END
				IF @QTY <= @Stock
				BEGIN
					SET @ReqQty = @QTY
					SET @InserCount = 0

					DECLARE sal3 CURSOR FOR
					SELECT	batch, expiry, Currqty 
					FROM	godowndetail 
					WHERE	godowndetail.gcode = @GCode and
						godowndetail.icode = @ICode
					ORDER BY priority, expiry, Currqty

					OPEN sal3
					FETCH NEXT FROM sal3 INTO @Batch, @Expiry, @BatchStock
					WHILE @@FETCH_STATUS = 0
					BEGIN
						SET @TQty = 0
						SET @TBQty = 0
						SET @RetCode = 0

						IF @BatchStock >= @ReqQty
						BEGIN
							SET @TQty = @LooseQty
							SET @TBQty = @BonusQty
						END
						ELSE
						BEGIN
							IF @BatchStock <= @LooseQty
							BEGIN
								SET @TQty = @BatchStock
								SET @TBQty = 0
							END
							ELSE
							BEGIN
								SET @TQty = @LooseQty
								SET @TBQty = @BatchStock - @LooseQty
							END
						END
						SET @LooseQty = @LooseQty - @TQty
						SET @BonusQty = @BonusQty - @TBQty
						SET @ReqQty = @LooseQty + @BonusQty
						SET @NewStock = @BatchStock - (@TQty + @TBQty)
						SET @TotalStock = @TotalStock - (@TQty + @TBQty)

						IF @NewStock > 0
						BEGIN
							UPDATE GodownDetail SET CurrQty = @NewStock WHERE CURRENT OF sal3

							IF @@RowCount = 0 
							BEGIN
								SET @RetCode = 1
							END
						END
						ELSE
						BEGIN
							IF @NewStock=0
							BEGIN
								DELETE GodownDetail WHERE CURRENT OF sal3
								IF @@RowCount = 0 
								BEGIN
									SET @RetCode = 1
								END
							END
							ELSE
							BEGIN
								SET @RetCode = 1
							END
						END

						IF @RetCode = 0
						BEGIN
							EXECUTE @errcode = SP_MaxUtn 1, @MaxUtn OUTPUT

							IF @errcode <> 0 AND @@ERROR <> 0
							BEGIN
								CLOSE sal3
								DEALLOCATE sal3
								CLOSE sal2
								DEALLOCATE sal2
								CLOSE sal1
								DEALLOCATE sal1
								RETURN -1			
							END
							SET @InserCount = @InserCount + 1

							INSERT INTO SDTEMP2
							SELECT * FROM SDTEMP WHERE ROWID = @ID

							IF @@Error <> 0 OR @@ROWCOUNT = 0
							BEGIN
								RaisError('Unable to Insert Row for sale # = %d, item = (%s)', 
									16, 1, @OldInvCode, @ItemName)
								CLOSE sal3
								DEALLOCATE sal3
								CLOSE sal2
								DEALLOCATE sal2
								CLOSE sal1
								DEALLOCATE sal1
								RETURN -1
							END
							
							UPDATE SDTEMP2
							SET ID2 = @InserCount, Batch=@Batch, Expiry=@Expiry, 
									LooseQty=@TQty, BonusQty=@TBQty, 
									Due=Null, SatisfiedDate=Null, SaleUtn=@MaxUtn, 
									BalanceStock=ISNULL(@TotalStock , 0),
									GSTPERC = @GSTPERC, UnitSalesTax=@UnitSalesTax, 
									PackUnits=@PackUnits, SalePrice=@SalePrice
							WHERE ROWID=@ID and ID2=0
							IF @@Error <> 0 OR @@ROWCOUNT = 0
							BEGIN
								RaisError('Unable to Update Row for sale # = %d, item = (%s)', 
									16, 1, @OldInvCode, @ItemName)
								CLOSE sal3
								DEALLOCATE sal3
								CLOSE sal2
								DEALLOCATE sal2
								CLOSE sal1
								DEALLOCATE sal1
								RETURN -1
							END
						END
						ELSE
						BEGIN
							RaisError('Unable to Update stock for Sale # = %d, Item = (%s)', 
								16, 1, @OldInvCode, @ItemName)
							CLOSE sal3
							DEALLOCATE sal3
							CLOSE sal2
							DEALLOCATE sal2
							CLOSE sal1
							DEALLOCATE sal1
							RETURN -1			
						END

						IF @RetCode <> 0 BREAK

						IF @ReqQty = 0 BREAK	

						FETCH NEXT FROM sal3 INTO @Batch, @Expiry, @BatchStock
					END
					CLOSE sal3
					DEALLOCATE sal3
				END
				ELSE
				BEGIN
					SET @RetCode = 1
				END
			END
			
			IF @DueQty > 0
			BEGIN
				SET @InserCount = 1
				SET @RetCode = 0

				INSERT INTO SDTEMP2
				SELECT * FROM SDTEMP WHERE ROWID = @ID

				EXECUTE @errcode = SP_MaxUtn 1, @MaxUtn OUTPUT
				IF @errcode <> 0 AND @@ERROR <> 0
				BEGIN
					CLOSE sal2
					DEALLOCATE sal2
					CLOSE sal1
					DEALLOCATE sal1
					RETURN -1			
				END

				UPDATE SDTEMP2
				SET ID2 = @InserCount, 
						Batch='Due', 
						Expiry=cast(dateadd(year, 1, getdate()) as varchar(12)), 
						LooseQty=@DueQty, BonusQty=0, Due='D', SatisfiedDate=Null, 
						SaleUtn=@MaxUtn, BalanceStock=ISNULL(@TotalStock , 0),
						GSTPERC = @GSTPERC, UnitSalesTax=@UnitSalesTax, 
						PackUnits=@PackUnits, SalePrice=@SalePrice
				WHERE ROWID=@ID and ID2=0
			END

			IF @RetCode <> 0 
			BEGIN
				UPDATE SDTEMP SET SALEINVCODE=-1000 
				WHERE ROWID = @ID AND ROWGROUP = @ROWGROUP
			END
			ELSE
			BEGIN
				SET @ThisCount = @ThisCount + 1
			END 
		END
		ELSE 
		BEGIN
			UPDATE SDTEMP SET 
					SALEINVCODE=-1000 WHERE ROWID = @ID AND ROWGROUP = @ROWGROUP
		END

		FETCH NEXT FROM sal2 INTO 
			@ICode, @GCode, @ID, @PackQty, @BonusQty, @LooseQty, @RowGroup, @DueQty, @GstPerc, @UnitSalesTax, @PackUnits, @SalePrice
	END
	CLOSE sal2
	DEALLOCATE sal2

	IF @ThisCount = 0 
	BEGIN
		UPDATE SHTEMP
		SET SALEINVCODE = -1000 WHERE OldInvCode = @OldInvCode
	END
	ELSE
	BEGIN

		EXECUTE @errcode = SP_GetTabMaxkey 'saleledger', @TABMAXKEY Output
		IF @@ERROR <> 0 OR @errcode <> 0
		BEGIN
			CLOSE sal1
			DEALLOCATE sal1
			RETURN -1
		END
			
		EXECUTE @errcode = SP_GetHeaderTabMaxkey @HeaderCode, 1, @HeaderTabMaxKey Output
		IF @@ERROR <> 0 OR @errcode <> 0
		BEGIN
			CLOSE sal1
			DEALLOCATE sal1
			RETURN -1
		END

		UPDATE SHTEMP
		SET 	SaleInvCode = @TabMaxKey, HeaderNo = ISNULL(@HeaderCode, 1), 
			HEADERINVNO = @HeaderTabMaxKey, SalesmanCode = @USERCODE, 
			POSTED='N', ModifiedBy=NULL, PostedBy=Null, QuotationNo=NULL, 
			ReprintingCounter=0, ModifyCounter=0, ReturnCounter=0, 
			PaymentMode = Null, PaymentAccCode = Null, Amt=0, AmtBy=Null,
			AmtReference=Null, OutStandingAmt=0, Marked='N', 
			TRANSFERABLE='N', TRANSFERED='N', TRANSFEREDBY=NULL, 
			TRANSFEREDON=NULL, IMPORTED='Y', IMPORTEDBY=@UserCode,
			GSTNo=@DEFAULTGST
		WHERE OLDINVCODE = @OldInvCode

		UPDATE SDTEMP2
		SET SALEINVCODE = @TabMaxKey
		WHERE OLDINVCODE = @OldInvCode
	END
	
	FETCH NEXT FROM sal1 INTO @OldInvCode, @SaleCatCode, @HeaderCode, @DefaultGST
END
CLOSE sal1
DEALLOCATE sal1

SET @ImportCount = ISNULL((SELECT COUNT(*) FROM SHTEMP WHERE SHTEMP.SALEINVCODE >= 0), 0)

IF @ImportCount > 0
BEGIN
	UPDATE SHTEMP
	SET SHTEMP.INVTOTAL = S.Net
	FROM SHTEMP, 
	(SELECT	H.SaleInvCode, NET=Round(
			SUM( (D.looseqty + D.bonusqty) * D.unitsalestax) + 
			SUM(ROUND( (D.looseqty * 
				(D.saleprice - D.itemflatdisc)) *
				(1 - (.01 * D.discperc)) * D.gstperc * .01, 2)) +
			ROUND( (SUM((D.looseqty * 
				(D.saleprice - D.itemflatdisc)) *
				(1 - (.01 * D.discperc))) * (1- (.01 * H.discperc)) -
				H.flatdisc) * (H.invgstperc1 * .01), 2), 0) +
			Round(SUM((D.looseqty * (D.saleprice - D.itemflatdisc)) *
				(1 - (.01 * D.discperc))) * (1- (.01 * H.discperc)) + 
				H.misccharges + H.salestax - H.flatdisc, 0)
	FROM SHTEMP H, SDTEMP2 D		
	WHERE H.saleinvcode = D.saleinvcode 
	GROUP BY H.saleinvcode,
		 H.discperc,
		 H.misccharges,
		 H.salestax,
		 H.flatdisc,
		 H.invgstperc1) S
	WHERE SHTEMP.SaleInvCode >= 0 AND SHTEMP.SaleInvCode = S.SaleInvCode

	UPDATE SHTEMP SET FlatDisc=0 WHERE SaleInvCode >= 0 AND invtotal < 0
	
	UPDATE SDTEMP2 SET ItemFlatDisc=0 
	WHERE SaleInvCode IN 
		(SELECT SaleinvCode FROM SHTEMP WHERE SaleInvCode >= 0 AND invtotal < 0)

	UPDATE SHTEMP
	SET SHTEMP.INVTOTAL = S.Net
	FROM SHTEMP, 
	(SELECT	H.SaleInvCode, NET=Round(
			SUM( (D.looseqty + D.bonusqty) * D.unitsalestax) + 
			SUM(ROUND( (D.looseqty * 
				(D.saleprice - D.itemflatdisc)) *
				(1 - (.01 * D.discperc)) * D.gstperc * .01, 2)) +
			ROUND( (SUM((D.looseqty * 
				(D.saleprice - D.itemflatdisc)) *
				(1 - (.01 * D.discperc))) * (1- (.01 * H.discperc)) -
				H.flatdisc) * (H.invgstperc1 * .01), 2), 0) +
			Round(SUM((D.looseqty * (D.saleprice - D.itemflatdisc)) *
				(1 - (.01 * D.discperc))) * (1- (.01 * H.discperc)) + 
				H.misccharges + H.salestax - H.flatdisc, 0)
	FROM SHTEMP H, SDTEMP2 D		
	WHERE H.saleinvcode = D.saleinvcode 
	GROUP BY H.saleinvcode,
		 H.discperc,
		 H.misccharges,
		 H.salestax,
		 H.flatdisc,
		 H.invgstperc1) S
	WHERE SHTEMP.SaleInvCode >= 0 AND SHTEMP.SaleInvCode = S.SaleInvCode

	UPDATE SHTEMP SET OutstandingAmt=InvTotal WHERE SHTEMP.SaleInvCode >= 0 

	SET XACT_ABORT ON
	EXECUTE (@SRCUPD)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update the transfer status at source database', 16, 1)
		RETURN -1
	END
	SET XACT_ABORT OFF

	SET @LIST=''
	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'SaleLedger', @LIST OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update sale invoice header', 16, 1)
		RETURN -1
	END

	SET @SQL = N'INSERT INTO SaleLedger ( ' + @LIST + ' ) ' + 'SELECT ' + 
		@LIST +	' FROM SHTEMP WHERE SHTEMP.SALEINVCODE >=0'

	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update sale invoice header', 16, 1)
		RETURN -1
	END
	
	SET @LIST=''
	EXECUTE @errcode = SP_COLUMNLIST @OWNER, 'SaleDetail', @LIST OUTPUT
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update sale invoice detail', 16, 1)
		RETURN -1
	END

	SET @SQL = N'INSERT INTO SALEDETAIL ( ' + @LIST + ' ) ' + 
		'SELECT ' + @LIST + ' FROM SDTEMP2 WHERE SALEINVCODE >= 0 ORDER BY ROWID'
	
	EXECUTE (@SQL)
	SET @errcode = @@ERROR
	IF @@ERROR <> 0 OR @errcode <> 0
	BEGIN
		RaisError('Unable To update sale invoice detail', 16, 1)
		RETURN -1
	END
END

IF @@ERROR = 0 AND @errcode = 0
BEGIN
	INSERT INTO 
		DataTransferLog (TRANSFERLOGID, LOGDATE, TRANSFEREDBY, INVOICECODE, 
		INVOICETYPE, DATE, ACCCODE, SGCODE, DGCODE, STATUS)
	SELECT  @LOGID, LOGDATE=GETDATE(), TRANSFEREDBY=@UserCode, 
		INVOICECODE=OLDINVCODE, 
		INVOICETYPE=1, DATE=GETDATE(), ACCCODE=SHTEMP.CUSTCODE, NULL, NULL,
		STATUS = CASE SALEINVCODE WHEN -1000 THEN 0 ELSE 1 END
	FROM SHTEMP

	INSERT INTO 
		DataTransferLogDetail (TRANSFERLOGID, INVOICECODE, INVOICETYPE, 
		ICODE, GCODE, BATCH, EXPIRY, QTY, BONUSQTY, PRICE, STATUS)
	SELECT @LOGID, INVOICECODE=OLDINVCODE, INVOICETYPE=1, ICODE, GCODE, 
		BATCH, EXPIRY, LOOSEQTY, BONUSQTY, SalePrice, 
		STATUS = CASE SALEINVCODE WHEN -1000 THEN 0 ELSE 1 END
	FROM SDTEMP
END
DROP TABLE SHTEMP
DROP TABLE SDTEMP
DROP TABLE SDTEMP2
	
IF @@ERROR = 0 AND @errcode = 0
	RETURN 0
ELSE
	RaisError('Unable To successfully transfer sale invoices', 16, 1)
	RETURN -1
GO

-- sp_Translate_ChildeServer_Sale (last defined by script catalog)
CREATE  PROCEDURE sp_Translate_ChildeServer_Sale
	@childserver VarChar(100), 
	@invtype int,
	@invcode Int, 
	@usercode Int,
	@refund NUMERIC(10, 2),
	@saleinvcode int output
AS
SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

Declare @Headerno Int, @GCode INT, @curr_rowid INT
Declare @module Int, @custcode Int, @saletypecode SmallInt, @salecatcode Int, @headerinvno Int, @continue Int, @rt_code Int, @Err Int, @totalrows Int, @rowcount Int, @invcounter Int, @counter Int
Declare @satisfiableqty NUMERIC(15, 4), @satisfiedqty NUMERIC(15, 4), @item_in_inv_exist Int
Declare @saleprice Numeric(12,2), @rate Numeric(12,2), @discperc Numeric(5,2), @itemflatdisc Numeric(15,2), @unitsalestax Numeric(12,2), @gstperc1 Numeric(6,2), @gstperc2 Numeric(6,2), @hold_avgprice Numeric(15,5)
Declare @icode Int, @anyitem_exist NUMERIC(15, 4), @packunits Int
Declare @totalqty NUMERIC(15, 4), @givenqty NUMERIC(15, 4), @reqqty NUMERIC(15, 4), @batchqty NUMERIC(15, 4), @delqty NUMERIC(15, 4), @currqty NUMERIC(15, 4), @newqty NUMERIC(15, 4), @total_availablestock NUMERIC(15, 4), @ItemAdvanceTaxPerc NUMERIC(5,2)
Declare @batch VarChar(100), @itemname VarChar(60), @expiry DateTime, @serverdate DateTime
Declare @saleutn BigInt
Declare @salerowcount Int, @rowgroup Int, @lineitems_rowcount Int, @innercounter Int
DECLARE @saledesc VARCHAR(100), @updateloyaltypoints CHAR(1), @keepinvno CHAR(1), @updateRefno1 CHAR(1)

Set @custcode = 19
Set @salecatcode = 3 
Set @saletypecode = 2
Set @module = ( Select module from module where name = 'Sales' )
Set @serverdate = GETDATE()
Set @updateloyaltypoints = ISNULL((SELECT DBO.fn_GetPreference('ApplyLoyaltypolicyonsaleposting')),'N')
Set @keepinvno = ISNULL((SELECT DBO.fn_GetPreference('KeepChildServerInvoiceNoIntact')),'N')
Set @updateRefno1 = ISNULL((SELECT DBO.fn_GetPreference('CopyChildServerInvoiceNoInRef1')),'N')

Create Table #sale ( id int not null identity(1,1), icode Int, gcode int, satisfiableqty NUMERIC(15, 4), satisfiedqty NUMERIC(15, 4), SalePrice  Numeric(12,2), rate Numeric(12,2), packunits smallint not null, DiscPerc Numeric(8,2), ItemFlatDisc Numeric(12,2), UnitSalesTax Numeric(12,2), GstPerc Numeric(6,2), SaleDesc VARCHAR(100), ItemAdvanceTaxPerc NUMERIC(5,2))
Insert Into #sale ( icode, gcode, satisfiableqty, satisfiedqty , saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc, SaleDesc, ItemAdvanceTaxPerc)
Select icode, gcode, looseqty=ISNULL(SUM(looseqty), 0), 0, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc, SaleDesc=LTRIM(RTRIM(STR(MAX(SaleUtn)))), ItemAdvanceTaxPerc=0
From IMP_AdvSaleDetail
Where @invtype = 2 AND ChildServer = @childserver AND AdvSaleInvCode = @InvCode AND LooseQty > 0
GROUP BY icode, gcode, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc
UNION ALL
Select icode, gcode, looseqty=ISNULL(SUM(looseqty), 0), 0, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc, SaleDesc=LTRIM(RTRIM(STR(MAX(SaleUtn)))), ItemAdvanceTaxPerc
From IMP_SaleDetail
Where @invtype = 1 AND ChildServer = @childserver AND SaleInvCode = @InvCode AND LooseQty > 0
GROUP BY icode, gcode, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc, ItemAdvanceTaxPerc
Order By Icode

IF @invtype = 1
	Set @salerowcount = ISNULL((Select count(*) from IMP_SaleDetail where SaleInvCode = @invcode AND childserver = @childserver), 0)
ELSE
	Set @salerowcount = ISNULL((Select count(*) from IMP_AdvSaleDetail where AdvSaleInvCode = @invcode AND childserver = @childserver), 0)

Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #sale )

IF @invtype = 1
BEGIN
	Set @Headerno = ( Select HeaderNo from IMP_SaleLedger WHERE SaleInvCode = @invcode AND childserver = @childserver)
	Set @headerinvno = ( Select HeaderInvNo from IMP_SaleLedger WHERE SaleInvCode = @invcode AND childserver = @childserver)
END
ELSE
BEGIN
	Set @Headerno = ( Select HeaderNo from IMP_AdvSaleLedger WHERE AdvSaleInvCode = @invcode AND childserver = @childserver)
	Set @headerinvno = ( Select HeaderInvNo from IMP_AdvSaleLedger WHERE AdvSaleInvCode = @invcode AND childserver = @childserver)
END


Set @continue = 0
Set @invcounter = 1
Set @rowgroup = 0

While @anyitem_exist > 0 And @continue >= 0
Begin
	IF @keepinvno='N'
		Execute @rt_code = sp_GetTabMaxkey 'Saleledger' , @SaleInvCode Output
	ELSE
		SET @SaleInvCode = @invcode

	Set @rowgroup = 0
	IF @@Error <> 0 OR @rt_code <>  0
	Begin
		Set @continue  = -1
	End
	Else
	Begin		IF @keepinvno='N'
			Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno, @module, @headerinvno Output
		ELSE
			SET @headerinvno = @headerinvno

		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		Else
		Begin
			Set @Err = 0 
			Set @RowCount = 1

			Insert Into SaleLedger (SaleInvCode, SaleCatCode, CustCode, SalesmanCode, date, DiscPerc, FlatDisc, MiscCharges, SalesTax, Posted, PostDate, Remarks, CustRefNo, headerno, headerinvno, OriginalDate, ModifiedBy, PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, RePrintingCounter, CashReceived, InvGSTPerc1, PrintWaranty, PrintBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3, CustRefno4, GSTNO, InvTotal, MachineName, ModifyCounter, itemdiscpercno, RelationCode, DiseaseCode, WardCode, AdmissionCode, ReturnCounter, Paid, BillingDate, UnReceivedBalance, TotalOfSaleReturns, ListOfSrInvoices, printbalance, AccountFor, PaymentMode, PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked, Transferable, Transfered, TransferedOn, TransferedBy, Imported, ImportedBy, deliveredby, SaleTypeCode, Balance, PptCustCode, DELETED, PresCode, ImpactInventory, SaleOrderCode, SaleComments1, SaleComments2, AlterSaleInvCode, RecurringInvoice, RecurringPeriod, LastRecurringInvCode, RecurringAgainst, ConsiderInPO, VisitCode, DueDate, SRBufferInvCode, CustRefNo5, GCCode, GRN, SuppInvCode,  Vehicle, ShipTo, GuaranteePersonCode, CashTendered, CashCharged, CashBack, CashAccCode, CustLicNo, CustLicExpiry, ModuleId, DocCode, SaleTypeInvNo, CRS_Transfered, CRS_TransferedOn, GuestCode, GuestCheckInCode, StudentCode, CustSiteCode, Transmit, Transmited, Fiscalized, FiscalizedOn, FiscalInvoiceNo, AdvanceTax, AdvanceTaxAmt, FBRPOSFee)
			SELECT @SaleInvCode, SaleCatCode, CustCode, SalesmanCode, date, DiscPerc, Flatdisc=FlatDisc + ISNULL(@refund, 0), MiscCharges, SalesTax=0, Posted='Y', PostDate, Remarks, CustRefNo=CASE WHEN @updateRefno1 = 'Y' THEN LTRIM(RTRIM(STR(@SaleInvCode))) ELSE CustRefNo END, @HeaderNo, @HeaderInvNo, OriginalDate, ModifiedBy, PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, RePrintingCounter, CashReceived, InvGSTPerc1, PrintWaranty, PrintBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3, CustRefno4, GSTNO, InvTotal, MachineName, ModifyCounter, itemdiscpercno, RelationCode, DiseaseCode, WardCode, AdmissionCode, ReturnCounter, Paid, BillingDate, UnReceivedBalance, TotalOfSaleReturns, ListOfSrInvoices, printbalance, AccountFor, PaymentMode, PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked, Transferable, Transfered, TransferedOn, TransferedBy, Imported, ImportedBy, deliveredby, SaleTypeCode, Balance, PptCustCode, DELETED, PresCode, ImpactInventory, SaleOrderCode, SaleComments1, SaleComments2, AlterSaleInvCode, RecurringInvoice, RecurringPeriod, LastRecurringInvCode, RecurringAgainst, ConsiderInPO, VisitCode, DueDate, SRBufferInvCode, CustRefNo5, GCCode, GRN, SuppInvCode,  Vehicle, ShipTo, GuaranteePersonCode, CashTendered, CashCharged, CashBack, CashAccCode, CustLicNo, CustLicExpiry, ModuleId=-1, DocCode=SaleInvCode, SaleTypeInvNo, CRS_Transfered, CRS_TransferedOn, GuestCode, GuestCheckInCode, StudentCode, CustSiteCode, Transmit, Transmited, Fiscalized, FiscalizedOn, FiscalInvoiceNo, AdvanceTax, ISNULL(AdvanceTaxAmt, 0), FBRPOSFee
			FROM IMP_SaleLedger
			WHERE @invtype = 1 AND SaleInvCode = @InvCode AND childserver = @childserver
			UNION ALL
			SELECT @SaleInvCode, SaleCatCode = CASE invtype WHEN 1 THEN @salecatcode ELSE 2 END, CustCode, SalesmanCode, date, DiscPerc, Flatdisc=FlatDisc + ISNULL(@refund, 0), MiscCharges, SalesTax=0, Posted='Y', PostDate, Remarks, CASE WHEN @updateRefno1 = 'Y' THEN LTRIM(RTRIM(STR(@SaleInvCode))) ELSE CustRefNo END, @HeaderNo, @HeaderInvNo, OriginalDate, ModifiedBy, PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, RePrintingCounter, CashReceived=CashAmt, InvGSTPerc1, PrintWaranty, PrintBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3, CustRefno4, GSTNO, InvTotal=0, MachineName, ModifyCounter, itemdiscpercno, RelationCode, DiseaseCode, WardCode, AdmissionCode=NULL, ReturnCounter=0, Paid='N', BillingDate, UnReceivedBalance=0, TotalOfSaleReturns=0, ListOfSrInvoices='', printbalance, AccountFor='Y', PaymentMode, PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked='N', Transferable='Y', Transfered='N', TransferedOn=NULL, TransferedBy=NULL, Imported='N', ImportedBy=NULL, deliveredby=NULL, SaleTypeCode, Balance, PptCustCode=NULL, DELETED, PresCode=NULL, ImpactInventory='Y', SaleOrderCode=NULL, SaleComments1, SaleComments2, AlterSaleInvCode=0, RecurringInvoice='N', RecurringPeriod=0, LastRecurringInvCode=NULL, RecurringAgainst=NULL, ConsiderInPO='Y', VisitCode=NULL, DueDate=DATE, SRBufferInvCode=NULL, CustRefNo5=NULL, GCCode=NULL, GRN=NULL, SuppInvCode=NULL, Vehicle=NULL, ShipTo=NULL, GuaranteePersonCode=NULL, CashTendered, CashCharged=CashAmt, CashBack=0, CashAccCode=2, CustLicNo=NULL, CustLicExpiry=NULL, ModuleId=-1, DocCode=AdvSaleInvCode, SaleTypeInvNo=0, CRS_Transfered='N', CRS_TransferedOn=NULL, GuestCode=NULL, GuestCheckInCode=NULL, StudentCode=NULL, CustSiteCode=NULL, Transmit, Transmited, Fiscalized='N', FiscalizedOn=NULL, FiscalInvoiceNo=NULL, AdvanceTax='N', AdvanceTaxAmt=0, FBRPOSFee=0
			FROM IMP_AdvSaleLedger
			WHERE @invtype = 2 AND AdvSaleInvCode = @InvCode AND childserver = @childserver
			Select @Err = @@Error, @RowCount = @@RowCount

			IF @Err <> 0 OR @RowCount = 0 
			Begin 
				RaisError( 'Error occured in inserting record into Sale Ledger : %d' ,16,1,  @SaleInvCode  )
				Set @continue  = -1
			End 
			Else
			Begin
				Set @curr_rowid = 1
				Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #sale )
				Set @lineitems_rowcount =  @salerowcount
				Set @innercounter = 1
				While ( @salerowcount > 0 )  AND ( @anyitem_exist > 0 ) AND ( @innercounter <= @lineitems_rowcount ) AND ( @continue >= 0 )
				Begin
					Select @icode = icode , @Gcode = GCode, @satisfiableqty = satisfiableqty, @satisfiedqty = satisfiedqty, @saleprice = saleprice, @rate = rate, @packunits = packunits, @discperc = discperc,  @itemflatdisc = itemflatdisc, @unitsalestax = unitsalestax, @gstperc1 = gstperc, @saledesc=SaleDesc, @ItemAdvanceTaxPerc=ItemAdvanceTaxPerc
					From #sale
				        Where id = @curr_rowid

					Select @RowCount = @@RowCount
					IF ( @RowCount = 1 ) AND  ( (@satisfiableqty - @satisfiedqty) > 0 )
					Begin
						Set @givenqty = @satisfiableqty - @satisfiedqty
						Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
						IF @@Error <> 0 OR @rt_code <> 0
						Begin
							Set @continue  = -1
						End
						Else
						Begin
							Execute @rt_code = sp_GetItemStockAll @ICode, @total_availablestock OutPut
							IF @@Error <> 0 OR @rt_code <>  0
							Begin
								Set @continue  = -1															
							End
	
							Set @totalqty = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.gcode = @gcode and godowndetail.icode = @icode  )
							Set @rowgroup = @rowgroup + 1
							IF @packunits = 0 OR @packunits Is Null 
								Set @packunits = 1

							IF @givenqty > 0
							Begin 
								IF @totalqty >= @givenqty
									Set @reqqty = @givenqty
								ELSE
									Set @reqqty = @totalqty

								Declare ItemBatch_Cursor Cursor Static Forward_Only
								For 	Select  batch, expiry, Currqty 
								From    godowndetail 
								Where  godowndetail.gcode = @gcode and
									    godowndetail.icode = @icode 
								Order by priority, expiry, Currqty

								Open ItemBatch_Cursor
								Set @totalrows = @@Cursor_Rows
								Fetch Next From ItemBatch_Cursor
								Into 	@batch, @expiry, @currqty
								Set @counter = 1	
								While @@Fetch_Status = 0 And @counter <= @totalrows AND @reqqty > 0
								Begin
									Set @batchqty = @currqty
									IF @batchqty >= @ReqQty 
										Set @delqty = @reqqty
									Else
										Set @delqty = @batchqty
									Set @reqqty = @reqqty - @delqty

									Execute @rt_code = sp_maxutn 1, @saleutn Output
									IF @@Error <> 0 OR @rt_code <> 0
									Begin
										Set @continue  = -1															
									End

									SET @total_availablestock = @total_availablestock - @delqty

									Insert Into SaleDetail (SaleInvCode, icode, gcode, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, SaleItemDescription, ItemAdvanceTaxPerc)
									Values (@saleinvcode, @icode, @gcode, @batch, @expiry, 0, @delqty, @packunits, @saleprice, @hold_avgprice, @rate, @discperc, 0, @itemflatdisc, @rate * @packunits, @unitsalestax, @gstperc1, @saleutn, @total_availablestock, @rowgroup, @SaleDesc, @ItemAdvanceTaxPerc)
									Select @Err = @@Error, @RowCount = @@RowCount
									IF @Err <> 0 OR @RowCount = 0 
									Begin 
										RaisError( 'Error occured in inserting record into Sale Detail for Sale Inv. No. : %d' ,16,1, @SaleInvCode  )
										Set @continue  = -1
									End 																Else
									Begin
										Set @newqty = @currqty - @delqty
										IF @newqty > 0
											Execute @rt_code = sp_SaleUpdateItemStockBatch @gcode, @icode, @batch, @expiry, @newqty , @currqty
										Else
											Execute @rt_code = sp_DeleteItemStockBatch @gcode, @icode, @batch, @expiry, @delqty
										IF @@Error <> 0 OR @rt_code <> 0 
										Begin
											Set @continue  = -1								
										End
									End
									Set @counter = @counter + 1
									Fetch Next From ItemBatch_Cursor
									Into 	@batch, @expiry, @currqty
								End
								Close ItemBatch_Cursor
								Deallocate ItemBatch_Cursor

								IF @totalqty < @givenqty
								BEGIN
									Set @givenqty = @givenqty - @totalqty
									IF @givenqty > 0
									BEGIN
										Execute @rt_code = sp_maxutn 1, @saleutn Output
										IF @@Error <> 0 OR @rt_code <> 0
										Begin
											Set @continue  = -1															
										End
										ELSE
										Begin
											Insert Into SaleDetail (SaleInvCode, icode, gcode, due, batch, expiry, packqty, looseqty, packunits, saleprice, avgprice, rate, discperc, salestax, itemflatdisc, packprice, unitsalestax, gstperc, saleutn, balancestock, rowgroup, SaleItemDescription)
											Values (@saleinvcode, @icode, @gcode, 'D', 'due', CONVERT(VARCHAR(100), GETDATE()+365, 101), 0, @givenqty, @packunits, @saleprice, @hold_avgprice, @rate, @discperc, 0, @itemflatdisc, @rate * @packunits, @unitsalestax, @gstperc1, @saleutn, @total_availablestock, @rowgroup, @SaleDesc)
											Select @Err = @@Error, @RowCount = @@RowCount
											IF @Err <> 0 OR @RowCount = 0 
											Begin 
												RaisError( 'Error occured in inserting due record into Sale Detail for Sale Inv. No. : %d' ,16,1, @SaleInvCode  )
												Set @continue  = -1
											End 																	End
									END
								END
							End
						End
					End	
					UPDATE #sale SET Satisfiedqty = Satisfiableqty WHERE ID = @curr_rowid

					Set	@curr_rowid = @curr_rowid + 1
					Set @innercounter = @innercounter + 1
					Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #sale )
				End
			End
		End	
	End
Set @anyitem_exist  = ( Select Sum(Satisfiableqty - Satisfiedqty) from #sale )
End

Drop Table #sale

IF ( @continue >= 0 )
Begin
	IF @SaleInvCode > 0
	BEGIN
		INSERT INTO CashierWindow (SaleInvCode, AccCode, Remarks, Amount, RowID)
		SELECT @SaleInvCode, AccCode, Remarks, Amount, RowID 
		FROM IMP_CashierWindow
		WHERE childserver = @childserver AND SaleInvCode = @InvCode AND 
			SaleInvCode IN 
			(SELECT SaleInvCode FROM IMP_SaleLedger WHERE @invtype = 1 AND SaleInvCode = @InvCode AND childserver = @childserver)

		Update Saleledger 
		Set InvTotal = dbo.fn_getSaleInvTotal (Saleledger.saleinvcode)
		Where saleinvcode = @SaleInvCode
	
		Select @Err = @@Error, @Rowcount = @@RowCount
		IF  @Err <> 0 OR @RowCount = 0
		Begin
			RaisError( 'Unable to update Sale Invoice for Sale Inv. total' , 16 , 1 )
			Set @continue  = -1									
		End

		IF @updateloyaltypoints = 'Y'
		Begin
			Execute @rt_code = SP_ManageLoyaltyPoints 'SV', @SaleInvCode
			IF @@Error <> 0 OR @rt_code <> 0
			Begin
				RaisError( 'Unable to update loyalty points On Sale Invoice : %d' ,16,1, @SaleInvCode)
				Set @continue  = -1															
			End
		End
	END
End

Return @continue
GO

-- sp_Translate_ChildeServer_SaleReturn (last defined by script catalog)
CREATE   PROCEDURE sp_Translate_ChildeServer_SaleReturn
	@childserver VarChar(100), 
	@advsaleinvcode Int, 
	@usercode Int,
	@refund NUMERIC(10, 2),
	@SRInvCode Int OUTPUT
AS

SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DECLARE @Sale NUMERIC(15, 4)
Declare @Headerno Int, @GCode INT, @curr_rowid INT
Declare @module Int, @custcode Int, @saletypecode SmallInt, @srcatcode Int, @headerinvno Int, @continue Int, @rt_code Int, @Err Int, @totalrows Int, @rowcount Int, @invcounter Int, @counter Int
Declare @satisfiableqty NUMERIC(15, 4), @item_in_inv_exist Int
Declare @srprice Numeric(12,2), @rate Numeric(12,2), @discperc Numeric(5,2), @itemflatdisc Numeric(15,2), @unitsalestax Numeric(12,2), @gstperc1 Numeric(6,2), @gstperc2 Numeric(6,2), @hold_avgprice Numeric(15,5)
Declare @icode Int, @anyitem_exist Int, @packunits Int
Declare @totalqty NUMERIC(15, 4), @givenqty NUMERIC(15, 4), @reqqty NUMERIC(15, 4), @batchqty NUMERIC(15, 4), @delqty NUMERIC(15, 4), @currqty NUMERIC(15, 4), @newqty NUMERIC(15, 4), @totalstock NUMERIC(15, 4)
Declare @batch VarChar(100), @itemname VarChar(60), @expiry DateTime, @serverdate DateTime
Declare @saleutn BigInt, @firsttime Bit
Declare @advsale_rowcount Int, @rowgroup Int, @lineitems_rowcount Int, @innercounter Int
Set @firsttime = 0
Set @custcode = 19
Set @srcatcode = 8 
Set @saletypecode = 2
Set @module = ( Select module from module where name = 'SALES RETURN' )
Set @serverdate = GETDATE()

Create Table #salereturn ( 
	id int not null identity(1,1), 
	icode Int, 
	gcode int, 
	batch VARCHAR(100), 
	satisfiableqty NUMERIC(15, 4), 
	SalePrice  Numeric(12,2), 
	rate Numeric(12,2), 
	packunits smallint not null, 
	DiscPerc Numeric(8,2), 
	ItemFlatDisc Numeric(12,2), 
	UnitSalesTax Numeric(12,2), 
	GstPerc Numeric(6,2) )

Insert Into #salereturn 
	( icode, gcode, batch, satisfiableqty, saleprice, rate, packunits, discperc, 
	itemflatdisc, unitsalestax, gstperc )
Select icode, gcode, batch, SUM(ABS(looseqty)), saleprice, rate, packunits, discperc, 
	itemflatdisc, unitsalestax, gstperc
From IMP_AdvSaleDetail
Where ChildServer = @childserver AND AdvSaleInvCode = @AdvSaleInvCode AND LooseQty < 0
GROUP BY icode, gcode, batch, saleprice, rate, packunits, discperc, itemflatdisc, unitsalestax, gstperc
Order By ICode

SET @Sale = ISNULL((SELECT SUM(LooseQty) FROM IMP_AdvSaleDetail Where ChildServer = @childserver AND AdvSaleInvCode = @AdvSaleInvCode AND LooseQty > 0), 0)
Set @advsale_rowcount = ISNULL((Select count(*) from IMP_AdvSaleDetail where ChildServer = @childserver AND AdvSaleInvCode = @advsaleinvcode), 0)
Set @anyitem_exist  = ( Select Sum(ABS(Satisfiableqty)) from #salereturn )
Set @Headerno = ( Select HeaderNo from IMP_AdvSaleLedger WHERE ChildServer = @childserver AND AdvSaleInvCode = @advsaleinvcode)
Set @continue = 0
Set @invcounter = 1
Set @rowgroup = 0

While @anyitem_exist > 0 And @continue >= 0
Begin
	Execute @rt_code = sp_GetTabMaxkey 'SRledger' , @SRInvCode Output
	Set @rowgroup = 0
	IF @@Error <> 0 OR @rt_code <>  0
	Begin
		Set @continue  = -1
	End
	Else
	Begin
		Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno, @module,  @headerinvno Output 
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		Else
		Begin
			Set @Err = 0 
			Set @RowCount = 1
			Insert Into SRLedger (SRInvCode, SaleInvCode, Date, SRCatCode, CustCode, SalesmanCode, 
				DiscPerc, FlatDisc, MiscCharges, Posted, PostDate, Remarks, SalesTax, 
				OriginalDate, ModifiedBy, PostedBy, HeaderNo, InvGSTPerc1, Smancode, 
				CustRefno, CustRefno2, CustRefno3, CustRefno4, PatientCode, MachineName, 
				HeaderInvNo, AdmissionCode, InvTotal, AccountFor, PaymentMode, PaymentAccCode, 
				Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked, PageSize, ReprintingCounter, DoctCode, ConsiderInPO)
			SELECT  @SRInvCode, SaleInvCode=NULL, Date, 
				SRCatCode = CASE invtype WHEN 1 THEN @srcatcode ELSE 7 END, CustCode, SalesManCode, 
				Discperc, Flatdisc= CASE WHEN @Sale = 0 THEN Flatdisc ELSE 0 END, MiscCharges=CASE WHEN @Sale = 0 THEN MiscCharges ELSE 0 END + ISNULL(@Refund, 0), Posted='Y', PostDate=GETDATE(), Remarks, SalesTax=0, 
				OriginalDate, ModifiedBy, PostedBy=@usercode, @HeaderNo, InvGSTPerc1, Smancode, 
				CustRefno, CustRefno2, CustRefno3, CustRefno4, PatientCode, MachineName, 
				@HeaderInvNo, AdmissionCode=NULL, InvTotal=0, AccountFor='Y', PaymentMode, PaymentAccCode, 
				Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked='N', InvoiceSize, ReprintingCounter=0, DoctCode, ConsiderInPO='Y'
			FROM IMP_AdvSaleLedger
			WHERE ChildServer = @childserver AND AdvSaleInvCode = @AdvSaleInvCode

			Select @Err = @@Error, @RowCount = @@RowCount
			IF @Err <> 0 OR @RowCount = 0 
			Begin 
				RaisError( 'Error occured in inserting record into Sale Return Ledger : %d' ,16,1,  @SRInvCode  )
				Set @continue  = -1
			End 
			Else
			Begin
				Set	@curr_rowid = 1
				Set @anyitem_exist  = ( Select Sum(Satisfiableqty) from #salereturn )
				Set @lineitems_rowcount =  @advsale_rowcount
				Set @innercounter = 1
				While ( @advsale_rowcount > 0 )  AND ( @anyitem_exist > 0 ) AND ( @innercounter <= @lineitems_rowcount ) AND ( @continue >= 0 )
				Begin
					Select @icode = icode , @Gcode = GCode, 
						@batch = ISNULL((select DBO.Fn_GetPreference('defaultbatch')), '.'), 
						@expiry = CONVERT(datetime, CONVERT(VARCHAR(100), (SELECT GETDATE() + (SELECT DBO.FN_Get_INT_Preference('expiry'))), 106)), 
						@satisfiableqty = satisfiableqty, @srprice = saleprice, 
						@rate = rate, @packunits = packunits, @discperc = discperc,  
						@itemflatdisc = itemflatdisc, @unitsalestax = unitsalestax, @gstperc1 = gstperc
					From #salereturn
			        Where id = @curr_rowid

					Select @RowCount = @@RowCount
					IF ( @RowCount = 1 ) AND  ( @satisfiableqty > 0 )
					Begin
						Set @givenqty = @satisfiableqty
						Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
						IF @@Error <> 0 OR @rt_code <> 0
						Begin
							Set @continue  = -1
						End
						Else
						Begin
							Set @totalstock = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.icode = @icode  )
							Set @totalqty = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.gcode = @gcode and godowndetail.icode = @icode  )
							Set @rowgroup = @rowgroup + 1
							IF @packunits = 0 OR @packunits Is Null 
							BEGIN
								Set @packunits = 1
							END

							IF @givenqty > 0
							Begin 
								Execute @rt_code = sp_maxutn 1, @saleutn Output
								IF @@Error <> 0 OR @rt_code <> 0
								Begin
									Set @continue  = -1
								End

								Insert Into SRDetail 
									(SRInvcode, Icode, Gcode, Batch, Expiry, PackQty, LooseQty, PackUnits, SRPrice, 
									DiscPerc, SalesTax, AvgPrice, UnitSalesTax, GSTPerc, SRUtn, BonusQty, SalePrice, SaleRowId, CurrStock)
								SELECT @SRInvCode, @icode, @gcode, @batch, @expiry, 0, @givenqty, @packunits, (@srprice - @itemflatdisc), 
									@discperc, 0, @hold_avgprice, @unitsalestax, @gstperc1, @saleutn, 0, (@SRPrice - @itemflatdisc), NULL, @totalstock

								Select @Err = @@Error, @RowCount = @@RowCount
								IF @Err <> 0 OR @RowCount = 0 
								Begin 
									RaisError( 'Error occured in inserting record into Sale Return Detail for Sale Return No. : %d' ,16,1, @SRInvCode  )
									Set @continue  = -1
								End 															Else
								Begin
									Set @currqty = 0
									Execute @rt_code = SP_GetItemStockBatch @GCode, @ICode, @Batch, @Expiry, @currqty output
									IF @@Error <> 0 OR @rt_code <> 0 
									Begin
										RaisError( 'Error occured in checking Batch details of some items during processing of Sale Return No. : %d' ,16,1, @SRInvCode  )
										Set @continue  = -1								
									End

									Set @newqty = ISNULL(@currqty, 0) + ISNULL(@givenqty, 0)
									SELECT Row=@curr_rowid, Gcode=@GCode, Icode=@ICode, Batch=@Batch, Expiry=@Expiry, Qty=@CurrQty, thisqty = @givenqty, newqty=@newqty
									IF @newqty > 0
									BEGIN
										Execute @rt_code = SP_UpdateItemStockBatch  @GCode, @ICode, @Batch, @Expiry, @NewQty, Null
										IF @@Error <> 0 OR @rt_code <> 0 
										Begin
											RaisError( 'Error occured in updation of Batch details of some items during processing of Sale Return No. : %d' ,16,1, @SRInvCode  )
											Set @continue  = -1								
										End
									END
								End
								Set @counter = @counter + 1
							End
						End
					End	
					UPDATE #salereturn SET Satisfiableqty = 0 WHERE ID = @curr_rowid
					Set	@curr_rowid = @curr_rowid + 1
					Set @innercounter = @innercounter + 1
					Set @anyitem_exist  = ( Select Sum(Satisfiableqty) from #salereturn )
				End
			End
		End	
	End
	Set @anyitem_exist  = ( Select Sum(Satisfiableqty) from #salereturn )
End

Drop Table #salereturn

IF ( @continue >= 0 )
Begin
	IF @SRInvCode > 0
	BEGIN
		Update DBO.SRledger 
		Set InvTotal = ISNULL(dbo.fn_getSRInvTotal (SRLedger.SRInvCode), 0)
		Where SRInvCode = @SRInvCode
	
		Select @Err = @@Error, @Rowcount = @@RowCount
		IF  @Err <> 0 OR @RowCount = 0
		Begin
			RaisError( 'Unable to update Sale Return Invoices for Inv. total' , 16 , 1 )
			Set @continue  = -1
		End
	END
End

Return @continue
GO

-- sp_Translate_ChildeServer_SReturn (last defined by script 7861)
CREATE  PROCEDURE sp_Translate_ChildeServer_SReturn
	@childserver VarChar(100), 
	@OldSRInvCode Int, 
	@usercode Int,
	@SRInvCode Int OUTPUT
AS

SET NOCOUNT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

DECLARE @Sale NUMERIC(15, 4)
Declare @Headerno Int, @GCode INT, @curr_rowid INT
Declare @module Int, @custcode Int, @saletypecode SmallInt, @srcatcode Int, @headerinvno Int, @continue Int, @rt_code Int, @Err Int, @totalrows Int, @rowcount Int, @invcounter Int, @counter Int
Declare @looseqty NUMERIC(15, 4), @bonusqty NUMERIC(15, 4), @item_in_inv_exist Int
Declare @srprice Numeric(12,2), @rate Numeric(12,2), @discperc Numeric(5,2), @itemflatdisc Numeric(15,2), @unitsalestax Numeric(12,2), @gstperc1 Numeric(6,2), @gstperc2 Numeric(6,2), @hold_avgprice Numeric(15,5)
Declare @icode Int, @anyitem_exist Int, @packunits Int
Declare @totalqty NUMERIC(15, 4), @givenqty NUMERIC(15, 4), @reqqty NUMERIC(15, 4), @batchqty NUMERIC(15, 4), @delqty NUMERIC(15, 4), @currqty NUMERIC(15, 4), @newqty NUMERIC(15, 4), @totalstock NUMERIC(15, 4), @ItemAdvanceTaxPerc NUMERIC(5,2)
Declare @batch VarChar(100), @returndesc VarChar(100), @itemname VarChar(60), @expiry DateTime, @serverdate DateTime
Declare @saleutn BigInt, @firsttime Bit, @keepinvno CHAR(1), @updateRefno1 CHAR(1)
Declare @advsale_rowcount Int, @rowgroup Int, @lineitems_rowcount Int, @innercounter Int, @updateloyaltypoints CHAR(1)
Set @keepinvno = ISNULL((SELECT DBO.fn_GetPreference('KeepChildServerInvoiceNoIntact')),'N')
Set @updateRefno1 = ISNULL((SELECT DBO.fn_GetPreference('CopyChildServerInvoiceNoInRef1')),'N')

Set @firsttime = 0
Set @custcode = 19
Set @srcatcode = 8 
Set @saletypecode = 2
Set @module = ( Select module from module where name = 'SALES RETURN' )
Set @serverdate = GETDATE()
Set @updateloyaltypoints = ISNULL((SELECT DBO.fn_GetPreference('ApplyLoyaltypolicyonsaleposting')),'N')

Create Table #salereturn ( 
	id int not null identity(1,1), 
	icode Int, 
	gcode int, 
	batch VARCHAR(100), 
	expiry datetime,
	looseqty NUMERIC(15, 4), 
	bonusqty NUMERIC(15, 4), 
	SRPrice  Numeric(12,2), 
	packunits smallint not null, 
	DiscPerc Numeric(8,2), 
	UnitSalesTax Numeric(12,2), 
	GstPerc Numeric(6,2),
	returndesc varchar(100),
	ItemAdvanceTaxPerc NUMERIC(5,2))

Insert Into #salereturn 
	( icode, gcode, batch, expiry, looseqty, bonusqty, srprice, packunits, discperc, unitsalestax, gstperc, returndesc, ItemAdvanceTaxPerc)
Select icode, gcode, batch, expiry, SUM(ABS(looseqty)), bonusqty=sum(ABS(bonusqty)), srprice, packunits, discperc, unitsalestax, gstperc, returnitemdescription, ItemAdvanceTaxPerc
From IMP_SRDetail
Where ChildServer = @childserver AND SRInvCode = @OldSRInvCode
GROUP BY icode, gcode, batch, expiry, srprice, packunits, discperc, unitsalestax, gstperc, returnitemdescription, ItemAdvanceTaxPerc
Order By ICODE

SET @Sale = ISNULL((SELECT SUM(LooseQty) FROM IMP_SRDetail Where ChildServer = @childserver AND SRInvCode = @OldSRInvCode AND LooseQty > 0), 0)
Set @advsale_rowcount = ISNULL((Select count(*) from IMP_SRDetail where ChildServer = @childserver AND SRInvCode = @OldSRInvCode), 0)
Set @anyitem_exist  = ( Select Sum(ABS(looseqty)) from #salereturn )
Set @Headerno = ( Select HeaderNo from IMP_SRLedger WHERE ChildServer = @childserver AND SRInvCode = @OldSRInvCode)
Set @headerinvno = ( Select headerinvno from IMP_SRLedger WHERE ChildServer = @childserver AND SRInvCode = @OldSRInvCode)
Set @continue = 0
Set @invcounter = 1
Set @rowgroup = 0

While @anyitem_exist > 0 And @continue >= 0
Begin
	IF @keepinvno='N'
		Execute @rt_code = sp_GetTabMaxkey 'SRledger' , @SRInvCode Output
	ELSE
		SET @SRInvCode = @OldSRInvCode

	Set @rowgroup = 0
	IF @@Error <> 0 OR @rt_code <>  0
	Begin
		Set @continue  = -1
	End
	Else
	Begin
		IF @keepinvno='N'
			Execute @rt_code = sp_GetHeaderTabMaxkey @Headerno, @module,  @headerinvno Output 
		ELSE
			SET @headerinvno = @headerinvno
		
		IF @@Error <> 0 OR @rt_code <>  0
		Begin
			Set @continue  = -1
		End
		Else
		Begin
			Set @Err = 0 
			Set @RowCount = 1
			Insert Into SRLedger (SRInvCode, SaleInvCode, Date, SRCatCode, CustCode, SalesmanCode, 
				DiscPerc, FlatDisc, MiscCharges, Posted, PostDate, Remarks, SalesTax, 
				OriginalDate, ModifiedBy, PostedBy, HeaderNo, InvGSTPerc1, Smancode, 
				CustRefno, CustRefno2, CustRefno3, CustRefno4, PatientCode, MachineName, 
				HeaderInvNo, AdmissionCode, InvTotal, AccountFor, PaymentMode, PaymentAccCode, 
				Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked, PageSize, ReprintingCounter, DoctCode, ConsiderInPO,
				CashAccCode,CashTendered,CashCharged,CashBack,RetViaBillSummary,CRS_Transfered,CRS_TransferedOn,GuestCode,
				GuestCheckInCode,StudentCode,Synced,SyncedOn,SyncedBy,CurrencyCode,ConversionRate,Fiscalized,
				FiscalizedOn,FiscalInvoiceNo,Transmit,Transmited,AdvanceTax,AdvanceTaxAmt,FBRPOSFee)
			SELECT  @SRInvCode, SaleInvCode=NULL, Date, SRCatCode, CustCode, SalesManCode, 
				Discperc, Flatdisc, MiscCharges, Posted='Y', PostDate=GETDATE(), Remarks, SalesTax=0, 
				OriginalDate, ModifiedBy, PostedBy=@usercode, @HeaderNo, InvGSTPerc1, Smancode, 
				CustRefNo=CASE WHEN @updateRefno1 = 'Y' THEN LTRIM(RTRIM(STR(@SRInvCode))) ELSE CustRefNo END, CustRefno2, CustRefno3, CustRefno4=CustRefNo, PatientCode, MachineName, 
				@HeaderInvNo, AdmissionCode=NULL, InvTotal, AccountFor, PaymentMode, PaymentAccCode, 
				Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked='N', PageSize, ReprintingCounter, DoctCode, ConsiderInPO,
				CashAccCode,CashTendered,CashCharged,CashBack,RetViaBillSummary,CRS_Transfered,CRS_TransferedOn,GuestCode,
				GuestCheckInCode,StudentCode,Synced,SyncedOn,SyncedBy,CurrencyCode,ConversionRate,Fiscalized,
				FiscalizedOn,FiscalInvoiceNo,Transmit='N',Transmited='N',AdvanceTax,AdvanceTaxAmt,FBRPOSFee 
			FROM IMP_SRLedger
			WHERE ChildServer = @childserver AND SRInvCode = @OldSRInvCode

			Select @Err = @@Error, @RowCount = @@RowCount
			IF @Err <> 0 OR @RowCount = 0 
			Begin 
				RaisError( 'Error occured in inserting record into Sale Return Ledger : %d' ,16,1,  @SRInvCode)
				Set @continue  = -1
			End 
			Else
			Begin
				Set	@curr_rowid = 1
				Set @anyitem_exist  = ( Select Sum(looseqty + bonusqty) from #salereturn )
				Set @lineitems_rowcount =  @advsale_rowcount
				Set @innercounter = 1
				While ( @advsale_rowcount > 0 )  AND ( @anyitem_exist > 0 ) AND ( @innercounter <= @lineitems_rowcount ) AND ( @continue >= 0 )
				Begin
					Select @icode = icode , @Gcode = GCode, 
						@batch = Batch, 
						@expiry = EXPIRY, 
						@looseqty = looseqty, @bonusqty=bonusqty, @srprice = srprice, 
						@packunits = packunits, @discperc = discperc,  
						@unitsalestax = unitsalestax, @gstperc1 = gstperc, @returndesc=returndesc,
						@ItemAdvanceTaxPerc=ItemAdvanceTaxPerc
					From #salereturn
			        	Where id = @curr_rowid

					Select @RowCount = @@RowCount
					IF ( @RowCount = 1 ) AND  ( @looseqty > 0 )
					Begin
						Set @givenqty = @looseqty + @bonusqty
						Execute @rt_code = sp_GetItemAvgPrice @icode, @hold_avgprice OutPut
						IF @@Error <> 0 OR @rt_code <> 0
						Begin
							Set @continue  = -1
						End
						Else
						Begin
							set @totalstock  = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.icode = @icode  )
							Set @totalqty = (Select IsNull(Sum(currqty),0) From godowndetail where godowndetail.gcode = @gcode and godowndetail.icode = @icode  )
							Set @rowgroup = @rowgroup + 1
							IF @packunits = 0 OR @packunits Is Null 
							BEGIN
								Set @packunits = 1
							END

							IF @givenqty > 0
							Begin 
								Execute @rt_code = sp_maxutn 1, @saleutn Output
								IF @@Error <> 0 OR @rt_code <> 0
								Begin
									Set @continue  = -1
								End

								Insert Into SRDetail 
									(SRInvcode, Icode, Gcode, Batch, Expiry, PackQty, LooseQty, PackUnits, SRPrice, 
									DiscPerc, SalesTax, AvgPrice, UnitSalesTax, GSTPerc, SRUtn, BonusQty, SalePrice, SaleRowId, ReturnItemDescription,ItemAdvanceTaxPerc, currstock)
								SELECT @SRInvCode, @icode, @gcode, @batch, @expiry, 0, @looseqty, @packunits, @srprice, 
									@discperc, 0, @hold_avgprice, @unitsalestax, @gstperc1, @saleutn, @bonusqty, @SRPrice, NULL, @returndesc, @ItemAdvanceTaxPerc, @totalstock

								Select @Err = @@Error, @RowCount = @@RowCount
								IF @Err <> 0 OR @RowCount = 0 
								Begin 
									RaisError( 'Error occured in inserting record into Sale Return Detail for Sale Return No. : %d' ,16,1, @SRInvCode  )
									Set @continue  = -1
								End 															Else
								Begin
									Set @currqty = 0
									Execute @rt_code = SP_GetItemStockBatch @GCode, @ICode, @Batch, @Expiry, @currqty output
									IF @@Error <> 0 OR @rt_code <> 0 
									Begin
										RaisError( 'Error occured in checking Batch details of some items during processing of Sale Return No. : %d' ,16,1, @SRInvCode  )
										Set @continue  = -1								
									End

									Set @newqty = ISNULL(@currqty, 0) + ISNULL(@givenqty, 0)
									SELECT Row=@curr_rowid, Gcode=@GCode, Icode=@ICode, Batch=@Batch, Expiry=@Expiry, Qty=@CurrQty, thisqty = @givenqty, newqty=@newqty
									IF @newqty > 0
									BEGIN
										Execute @rt_code = SP_UpdateItemStockBatch  @GCode, @ICode, @Batch, @Expiry, @NewQty, Null
										IF @@Error <> 0 OR @rt_code <> 0 
										Begin
											RaisError( 'Error occured in updation of Batch details of some items during processing of Sale Return No. : %d' ,16,1, @SRInvCode  )
											Set @continue  = -1								
										End
									END
								End
								Set @counter = @counter + 1
							End
						End
					End	
					UPDATE #salereturn SET looseqty = 0, BonusQty=0 WHERE ID = @curr_rowid
					Set	@curr_rowid = @curr_rowid + 1
					Set @innercounter = @innercounter + 1
					Set @anyitem_exist  = ( Select Sum(looseqty + bonusqty) from #salereturn )
				End
			End
		End	
	End
	Set @anyitem_exist  = ( Select Sum(looseqty + bonusqty) from #salereturn )
End

Drop Table #salereturn

IF ( @continue >= 0 )
Begin
	IF @SRInvCode > 0
	BEGIN
		Update DBO.SRledger 
		Set InvTotal = ISNULL(dbo.fn_getSRInvTotal (SRLedger.SRInvCode), 0)
		Where SRInvCode = @SRInvCode
	
		Select @Err = @@Error, @Rowcount = @@RowCount
		IF  @Err <> 0 OR @RowCount = 0
		Begin
			RaisError( 'Unable to update Sale Return Invoices for Inv. total' , 16 , 1 )
			Set @continue  = -1
		End
		IF @updateloyaltypoints = 'Y'
		Begin
			Execute @rt_code = SP_ManageLoyaltyPoints 'SR', @SRInvCode
			IF @@Error <> 0 OR @rt_code <> 0
			Begin
				RaisError( 'Unable to update loyalty points On S/R Invoice : %d' ,16,1, @SRInvCode)
				Set @continue  = -1															
			End
		End
	END
End

Return @continue
GO

-- SP_Transmit_ChildServerSales (last defined by script catalog)
CREATE   PROCEDURE dbo.SP_Transmit_ChildServerSales
	@CustCode INT,
	@StartDate DATETIME,
	@EndDate DATETIME,
	@SRV VARCHAR(255), 
	@PARENTSRV VARCHAR(255), 
	@DB VARCHAR(50), 
	@OWNER VARCHAR(20),
	@SaleType INT
AS

SET XACT_ABORT ON
SET ANSI_NULLS ON
SET ANSI_WARNINGS ON

/* Variables to be used in import process */
DECLARE @INS VARCHAR(4000), @SQL VARCHAR(4000), @WHR VARCHAR(4000), @WHR_Cln VARCHAR(4000), @Query VARCHAR(4000), @stdate VARCHAR(100), @edate VARCHAR(100)
DECLARE @err INT, @rt_code INT
DECLARE @dt DATETIME

SET @stdate = (SELECT CONVERT(VARCHAR(100), @StartDate, 110) + ' ' + CONVERT(VARCHAR(100), @StartDate, 114))
SET @edate  = (SELECT CONVERT(VARCHAR(100), @EndDate, 110)   + ' ' + CONVERT(VARCHAR(100), @EndDate  , 114))

IF @SaleType = 1
BEGIN
	SET @INS = N'INSERT INTO ' + LTRIM(RTRIM(@PARENTSRV)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.IMP_SaleLedger '
	SET @SQL = N' SELECT ServerName=' + '''' + @SRV + ''', TransDate=GETDATE(), InvType = 1, SaleInvCode, SaleCatCode , CustCode , SalesmanCode, date, DiscPerc, FlatDisc, MiscCharges, SalesTax, Posted, PostDate, Remarks, CustRefNo, headerno, headerinvno, OriginalDate, ModifiedBy, PostedBy, SPrice, QuotationNo, DoctCode, PatientCode, RePrintingCounter, CashReceived, InvGSTPerc1, PrintWaranty, PrintBatch, MessageCode, SManCode, InvoiceSize, CustRefno2, CustRefno3, CustRefno4, GSTNO, InvTotal, MachineName, ModifyCounter, itemdiscpercno, RelationCode, DiseaseCode, WardCode, AdmissionCode, ReturnCounter, Paid, BillingDate, UnReceivedBalance, TotalOfSaleReturns, ListOfSrInvoices, printbalance, AccountFor, PaymentMode, PaymentAccCode, Amt, AmtBY, AmtDate, AmtReference, OutstandingAmt, Marked, Transferable, Transfered, TransferedOn, TransferedBy, Imported, ImportedBy, deliveredby, SaleTypeCode, Balance, PptCustCode, DELETED, PresCode, ImpactInventory, SaleOrderCode, SaleComments1, SaleComments2, AlterSaleInvCode, RecurringInvoice, RecurringPeriod, LastRecurringInvCode, RecurringAgainst, ConsiderInPO, VisitCode, DueDate, SRBufferInvCode, CustRefNo5, GCCode, GRN, SuppInvCode,  Vehicle, ShipTo, GuaranteePersonCode, CashTendered, CashCharged, CashBack, CashAccCode, CustLicNo, CustLicExpiry, ModuleId, DocCode=SaleInvCode, SaleTypeInvNo, CRS_Transfered, CRS_TransferedOn, GuestCode, GuestCheckInCode, StudentCode, CustSiteCode, Transmit, Transmited, Fiscalized, FiscalizedOn, FiscalInvoiceNo, AdvanceTax, ISNULL(AdvanceTaxAmt, 0), FBRPOSFee FROM SaleLedger '
END
IF @SaleType = 2
BEGIN
	SET @INS = N'INSERT INTO ' + LTRIM(RTRIM(@PARENTSRV)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.IMP_AdvSaleLedger '
	SET @SQL = N' SELECT ServerName=' + '''' + @SRV + ''', TransDate=GETDATE(), InvType = 2, * FROM AdvSaleLedger '
END
IF @SaleType = 3
BEGIN
	SET @INS = N'INSERT INTO ' + LTRIM(RTRIM(@PARENTSRV)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.IMP_SRLedger '
	SET @SQL = N' SELECT ServerName=' + '''' + @SRV + ''', TransDate=GETDATE(), InvType = 3, SRInvCode,SaleInvCode,Date,SRCatCode,CustCode,SalesmanCode,DiscPerc,FlatDisc,MiscCharges,Posted,PostDate,Remarks,SalesTax,OriginalDate,ModifiedBy,PostedBy,HeaderNo,InvGSTPerc1,Smancode,CustRefno,CustRefno2,CustRefno3,CustRefno4,PatientCode,MachineName,HeaderInvNo,AdmissionCode,invtotal,AccountFor,PaymentMode,PaymentAccCode,Amt,AmtBY,AmtDate,AmtReference,OutstandingAmt,Marked,PageSize,ReprintingCounter,DoctCode,ConsiderInPO,CashAccCode,CashTendered,CashCharged,CashBack,RetViaBillSummary,CRS_Transfered,CRS_TransferedOn,GuestCode,GuestCheckInCode,StudentCode,Synced,SyncedOn,SyncedBy,CurrencyCode,ConversionRate,Fiscalized,FiscalizedOn,FiscalInvoiceNo,Transmit,Transmited,AdvanceTax,AdvanceTaxAmt,FBRPOSFee FROM SRLedger '
END

IF @CustCode IS NULL
BEGIN
	SET @WHR = N' WHERE Transmit = ' + CHAR(39) + 'Y' + CHAR(39) + ' AND Transmited = ' + CHAR(39) + 'N' + CHAR(39) + ' AND DATE BETWEEN ' + CHAR(39) + @stdate+ CHAR(39) + ' AND ' + CHAR(39) + @edate + CHAR(39)
END
ELSE
BEGIN
	SET @WHR = N' WHERE CustCode = ' + (SELECT LTRIM(RTRIM(STR(@CustCode, 8)))) + ' AND Transmit = ' + CHAR(39) + 'Y' + CHAR(39) + ' AND Transmited = ' + CHAR(39) + 'N' + CHAR(39) + ' AND DATE BETWEEN ' + CHAR(39) + @stdate+ CHAR(39) + ' AND ' + CHAR(39) + @edate + CHAR(39)
END
SET @WHR_Cln = @WHR
SET @Query = @INS + @SQL + @WHR
EXECUTE (@Query)
SET @err = @@ERROR
IF @@ERROR <> 0 OR @err <> 0
BEGIN
	RAISERROR('Transmit Sales Data Problem: Error Transfering Sales Data From Server (%s) TO Server (%s) ', 16, 1, @SRV, @PARENTSRV)
	RETURN -1
END 
ELSE
BEGIN
	IF @SaleType = 1
	BEGIN
		SET @INS = N'INSERT INTO ' + LTRIM(RTRIM(@PARENTSRV)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.IMP_SaleDetail '
		SET @SQL = N'SELECT ServerName=' + '''' + @SRV + ''', SaleInvcode, ICode, GCode, Batch, Expiry, PackQty, LooseQty, PackUnits, SalePrice, AvgPrice, Rate, DiscPerc, SalesTax, RowID, Due, SatisfiedDate, itemflatdisc, SaleItemDescription, PackPrice, UnitSalesTax, GSTPerc, SaleUtn, bonusqty, claimable, balancestock, RowGroup, ClaimableDiscPerc, ManfDate, PackQtyForSale, BonusPackQtyForSale, SaleOrderRowID, DescICode, SourceSaleInvCode=SaleInvCode, SaleRowID=NULL, IssueRowID=NULL, PurUnitRate, RPPUnitRate, TotalPieces, PiecesInHand, PackSalePrice, RefusalSaleRowID=NULL, AlternatePurPrice, CommissionPerUnit, CommissionPerc, AlternateCustomICode, BatchCost, ISNULL(ItemAdvanceTaxPerc,0) FROM SaleDetail WHERE SaleInvCode IN (SELECT SaleInvCode FROM SaleLedger '
	END
	IF @SaleType = 2
	BEGIN
		SET @INS = N'INSERT INTO ' + LTRIM(RTRIM(@PARENTSRV)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.IMP_AdvSaleDetail '
		SET @SQL = N'SELECT ServerName=' + '''' + @SRV + ''', * FROM AdvSaleDetail WHERE AdvSaleInvCode IN (SELECT AdvSaleInvCode FROM AdvSaleLedger '
	END
	IF @SaleType = 3
	BEGIN
		SET @INS = N'INSERT INTO ' + LTRIM(RTRIM(@PARENTSRV)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.IMP_SRDetail (ChildServer,SRInvcode,Icode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,SRPrice,DiscPerc,SalesTax,AvgPrice,UnitSalesTax,GSTPerc,SRUtn,BonusQty,SalePrice,SaleRowId,ReturnItemDescription,TotalPieces,PiecesInHand,AlternatePurPrice,CommissionPerUnit,CommissionPerc,AlternateCustomICode,NewAvgPrice,Claimable,ClaimableDiscPerc,ItemAdvanceTaxPerc) '
		SET @SQL = N'SELECT ServerName=' + '''' + @SRV + ''',SRInvcode,Icode,Gcode,Batch,Expiry,PackQty,LooseQty,PackUnits,SRPrice,DiscPerc,SalesTax,AvgPrice,UnitSalesTax,GSTPerc,SRUtn,BonusQty,SalePrice,SaleRowId,ReturnItemDescription=LTRIM(RTRIM(STR(SRUTN))),TotalPieces,PiecesInHand,AlternatePurPrice,CommissionPerUnit,CommissionPerc,AlternateCustomICode,NewAvgPrice,Claimable,ClaimableDiscPerc,ISNULL(ItemAdvanceTaxPerc,0) FROM SRDetail WHERE SRInvCode IN (SELECT SRInvCode FROM SRLedger '
	END

	IF @CustCode IS NULL
	BEGIN
		SET @WHR = N' WHERE Transmit = ' + CHAR(39) + 'Y' + CHAR(39) + ' AND Transmited = ' + CHAR(39) + 'N' + CHAR(39) + ' AND DATE BETWEEN ' + CHAR(39) + @stdate+ CHAR(39) + ' AND ' + CHAR(39) + @edate + CHAR(39) + ')'
	END
	ELSE
	BEGIN
		SET @WHR = N' WHERE CustCode = ' + (SELECT LTRIM(RTRIM(STR(@CustCode, 8)))) + ' AND Transmit = ' + CHAR(39) + 'Y' + CHAR(39) + ' AND Transmited = ' + CHAR(39) + 'N' + CHAR(39) + ' AND DATE BETWEEN ' + CHAR(39) + @stdate+ CHAR(39) + ' AND ' + CHAR(39) + @edate + CHAR(39) + ')'
	END
	SET @Query = @INS + @SQL + @WHR
	EXECUTE (@Query)
	SET @err = @@ERROR
	IF @@ERROR <> 0 OR @err <> 0
	BEGIN
		RAISERROR('Transmit Sales Data Detail Problem: Error Transfering Sales Data Detail From Server (%s) TO Server (%s) ', 16, 1, @SRV, @PARENTSRV)
		RETURN -1
	END 
	ELSE
	BEGIN
		IF @SaleType = 1
		BEGIN
			SET @INS = N'INSERT INTO ' + LTRIM(RTRIM(@PARENTSRV)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.IMP_CashierWindow SELECT ChildServer=' + CHAR(39) + @SRV + CHAR(39) + ', CW.* FROM CashierWindow CW WHERE CW.SaleInvCode IN (SELECT SaleInvCode FROM SaleLedger '
		END
		IF @SaleType = 3
		BEGIN
			SET @INS = N'INSERT INTO ' + LTRIM(RTRIM(@PARENTSRV)) + '.' + LTRIM(RTRIM(@db)) + '.' + LTRIM(RTRIM(@owner)) + '.IMP_MasterCashWin SELECT ChildServer=' + CHAR(39) + @SRV + CHAR(39) + ', CW.* FROM MasterCashWin CW WHERE CW.DocumentType = ' + CHAR(39) + 'SR' + CHAR(39) + ' AND DocumentCode IN (SELECT SRInvCode FROM SRLedger '
		END
		SET @Query = @INS + @WHR
		EXECUTE (@Query)
		SET @err = @@ERROR
		IF @@ERROR <> 0 OR @err <> 0
		BEGIN
			RAISERROR('Transmit Sales Data Problem: Error Updating Master Cashier Window Related Data (%d)', 16, 1, @SaleType)
			RETURN -1
		END 

		IF @SaleType = 1
		BEGIN
			SET @Query = 'UPDATE SaleLedger SET Transmited = ' + CHAR(39) + 'Y' + CHAR(39) + @WHR_Cln
		END
		IF @SaleType = 2
		BEGIN
			SET @Query = 'UPDATE AdvSaleLedger SET Transmited = ' + CHAR(39) + 'Y' + CHAR(39) + @WHR_Cln
		END
		IF @SaleType = 3
		BEGIN
			SET @Query = 'UPDATE SRLedger SET Transmited = ' + CHAR(39) + 'Y' + CHAR(39) + @WHR_Cln
		END
		
		EXECUTE (@Query)
		SET @err = @@ERROR
		IF @@ERROR <> 0 OR @err <> 0
		BEGIN
			RAISERROR('Transmit Sales Data Problem: Error Updating Sales Regarding Transmit Status', 16, 1)
			RETURN -1
		END 
	END
END

SET @dt = GETDATE()
Execute @rt_code = SP_Set_DateTime_Preference 'LastSaleTransmited', @dt
IF @@Error <> 0 OR @rt_code <> 0 
Begin
	RaisError( 'Unable to Record Last Sale Transmit Information in Software Preferences' , 16 , 1)
	RETURN -1								
End

RETURN 0
GO

-- SP_Update_Customer_Info (last defined by script catalog)
CREATE PROCEDURE DBO.SP_Update_Customer_Info
@ai_custcode SMALLINT,
@ai_areacode SMALLINT,
@ai_subareacode SMALLINT,
@ai_countycode SMALLINT,
@as_address1 VARCHAR(60),
@as_address2 VARCHAR(60),
@as_block CHAR(1),
@ad_charges NUMERIC(12,2),
@adt_openingdate DATETIME
AS

UPDATE Accounts SET OpeningDate=@adt_openingdate WHERE AccCOde=@ai_custcode

UPDATE Customer 
SET 
	Address1 = @as_address1,
	Address2 = @as_address2,
	AreaCode = @ai_areacode,
	SubAreaCode = @ai_subareacode,
	CountyCode = @ai_countycode,
	Block = @as_block,
	Charges = @ad_charges
WHERE CustCOde=@ai_custcode
GO

-- SP_Update_Item_MinQty (last defined by script catalog)
CREATE PROCEDURE SP_Update_Item_MinQty @ICode INT, @Qty INT
AS

DECLARE @err INT, @rowcount INT
DECLARE @itemname VARCHAR(100)

SET @itemname = ISNULL((SELECT Name FROM DBO.Item WHERE ICode = @ICode), '')

UPDATE DBO.Item
SET MinQty = ISNULL(@Qty, 0)
WHERE DBO.Item.ICode = @ICode

Select @rowcount = @@RowCount , @err = @@Error    

IF @rowcount <> 1 AND @err <> 0   
BEGIN
	RAISERROR('Unable to update minimum qty. for item = %s ' , 16 , 1,  @itemname)
	Return -1
END

Return 0
GO

