-- SP_WayToMoon (last defined by script catalog)
CREATE PROCEDURE SP_WayToMoon @fl VARCHAR(100), @fl2 VARCHAR(100)
AS
DECLARE @cmdline VARCHAR(255)
DECLARE @rt_code INT
DECLARE @Ver VARCHAR(4000)
SET @Ver = @@Version

IF CHARINDEX('X64', @Ver, 1) > 0
	SET @cmdline = 'dir %systemroot%\syswow64\' + LTRIM(RTRIM(@fl))
ELSE
	SET @cmdline = 'dir %systemroot%\system32\' + LTRIM(RTRIM(@fl))

EXEC @rt_code = master..xp_cmdshell @cmdline, NO_OUTPUT
IF @rt_code >= 1
	RETURN 1
ELSE
BEGIN 
	IF CHARINDEX('X64', @Ver, 1) > 0
		SET @cmdline = 'dir %systemroot%\syswow64\' + LTRIM(RTRIM(@fl2))
	ELSE
		SET @cmdline = 'dir %systemroot%\system32\' + LTRIM(RTRIM(@fl2))
	EXEC @rt_code = master..xp_cmdshell @cmdline, NO_OUTPUT
	IF @rt_code >= 1
		RETURN 1
END
RETURN 0
GO

-- sp_yearly_sale_summary_monthwise_groping (last defined by script catalog)
CREATE   procedure sp_yearly_sale_summary_monthwise_groping @dt_year datetime as

select *
INTO #mytable1
from

(select	code=SL.saleinvcode, 
	date=max(SL.date),
	 TransCategory=(case max(salecatcode) when 3 then 'CASH'
		else 'CREDIT'
		end),
	 invtotal=dbo.fn_getsaleinvtotal(SL.saleinvcode),
	 sales = dbo.fn_getsaleinvtotal(SL.saleinvcode),
	 Returns=0.00,
	 Transtype='S'
from saleledger SL,saledetail SD
where SL.saleinvcode=SD.saleinvcode AND
	date>='01/01/' + convert(varchar(4),datepart(year,@dt_year)) and date<='12/31/' + convert(varchar(4),datepart(year,@dt_year))+' 23:59:59'
group by SL.saleinvcode

union all

select 	code=SL.srinvcode, 
	date=max(SL.date),
	 TransCategory=(case max(srcatcode) when 8 then 'CASH'
		else 'CREDIT'
		end),
	 invtotal=( - 1)*dbo.fn_getsrinvtotal(SL.srinvcode),
	 sales = 0.00,
	 Returns=dbo.fn_getsrinvtotal(SL.srinvcode),
	 Transtype='SR'
from srledger SL,srdetail SD
where SL.srinvcode=SD.srinvcode AND
	date>='01/01/' + convert(varchar(4),datepart(year,@dt_year)) and date<='12/31/' + convert(varchar(4),datepart(year,@dt_year))+' 23:59:59'
group by SL.srinvcode

union all
select 	code=PL.purinvcode, 
	date=max(PL.date),
	 TransCategory='Credit',
	 invtotal=dbo.fn_getpurinvtotal(PL.Purinvcode),
	 sales = 0.00,
	 Returns=0.00,
	 Transtype='P'
from purledger PL,purdetail PD
where PL.purinvcode=PD.purinvcode AND
	date>='01/01/' + convert(varchar(4),datepart(year,@dt_year)) and date<='12/31/' + convert(varchar(4),datepart(year,@dt_year))+' 23:59:59'
group by PL.purinvcode


) As A

	
select 
	monthname=convert(varchar(3),convert(datetime,convert(varchar,A.months) + '/01/'+convert(varchar,datepart(year,@dt_year))),7),
	A.months,
	daysofwork=(select count(distinct(datepart(day,date))) from #mytable1 where transtype='S' and datepart(month,date)=A.months ),
	CashInvCount=(select count(code)from #mytable1 where transtype='S' AND TransCategory='CASH' and datepart(month,date)=A.months),
	CashSaleInvtotal=(select isnull(sum(invtotal),0) from #mytable1 where transtype IN ('S','SR') AND TransCategory='CASH' and datepart(month,date)=A.months),
	CreditInvCount=(select count(code)from #mytable1 where transtype='S' AND TransCategory='CREDIT' and datepart(month,date)=A.months),
	CreditSaleInvtotal=(select isnull(sum(invtotal),0) from #mytable1 where transtype IN ('S','SR') AND TransCategory='CREDIT' and datepart(month,date)=A.months),
	TotalSaleCount=(select count(code)from #mytable1 where transtype='S'  and datepart(month,date)=A.months),
	TotalSaleAmount=(select isnull(sum(invtotal),0) from #mytable1 where transtype IN ('S','SR')  and datepart(month,date)=A.months),
	SaleReturns = (select isnull(sum(invtotal),0) from #mytable1 where transtype IN ('SR')  and datepart(month,date)=A.months),
	TotalPurAmount=(select isnull(sum(invtotal),0) from #mytable1 where transtype ='P'  and datepart(month,date)=A.months),
	perdayavg=(select isnull(sum(invtotal),0) from #mytable1 where transtype IN ('S','SR')  and datepart(month,date)=A.months)/(case when (select count(distinct(datepart(day,date))) from #mytable1 where transtype='S' and datepart(month,date)=A.months)=0 then 1 else (select count(distinct(datepart(day,date))) from #mytable1 where transtype='S' and datepart(month,date)=A.months) end),
	TotalSales = (select isnull(sum(Sales),0) from #mytable1 where datepart(month,date)=A.months)
from (select distinct(datepart(month,date)) as months
		from saleledger
		where saleledger.date>='01/01/' + convert(varchar(4),datepart(year,@dt_year)) and saleledger.date<='12/31/' + convert(varchar(4),datepart(year,@dt_year))+' 23:59:59') as A
GO

-- SP_YEARLYSALESSUMMARY (last defined by script catalog)
CREATE  PROCEDURE DBO.SP_YEARLYSALESSUMMARY @ar_startdate datetime, @ar_enddate datetime, @ReportGrouping CHAR(1), @GroupList VARCHAR(8000) AS
/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'reportdata' table to be used for cross tabulation of
	years and groups selected depending upon the grouping criteria selected (manfufacture, itemcategory, packing, class wise)

PARAMETER DESCRIPTION :
	@ar_startdate, @ar_enddate = Determine the period of report
	@ReportGrouping = The criteria for grouping the items in report
	@GroupList = A comma separated list of values to be filtered while grouping the record set
*/

DELETE ReportData

DECLARE @Tab_GroupList TABLE (CODE INT NOT NULL)
DECLARE @Tab_ItemList TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_GroupList SELECT CODE FROM udf_StringToTabl(@GroupList, ',')
INSERT INTO @Tab_ItemList SELECT CODE FROM udf_selectitems(@ReportGrouping, @GroupList)

INSERT INTO ReportData (code1, name1, code2, value1)
SELECT
	Code1 = T.Year,
	Name1 = T.GroupName,
	Code1 = T.GroupCode,
	Value1 = SUM(T.Value)

FROM
	(SELECT	
		Year=S.YEAR,
		GroupCode=CASE @ReportGrouping 
			WHEN 'M' THEN I.MANFCODE
			WHEN 'C' THEN I.ICatCode
			WHEN 'L' THEN I.ICCode
			ELSE I.PACKCODE END,
		GroupName=CASE @ReportGrouping 
			WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE  = I.ManfCode)
			WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE  = I.ICatCode)
			WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE  = I.ICCode)
			ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE  = I.PACKCODE) END,   
		ICode=S.ICode,
		Value = SUM(value)
	FROM
		(SELECT	
			sd.icode,
			Year= DATEPART(YEAR, DATE),
			value = sum((sd.looseqty + sd.packqty * sd.packunits) *
				sd.saleprice * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01))
		FROM 
			saleledger sl, saledetail sd, @TAB_ItemList I
		WHERE 
			sl.posted = 'Y' AND sl.saleinvcode = sd.saleinvcode AND
			sl.date >= @ar_startdate and sl.date <= @ar_enddate AND
			sd.icode = I.code
		Group By 
			sd.icode, 
			DATEPART(YEAR, DATE)
		UNION ALL
		SELECT	
			sd.icode,
			Year= DATEPART(YEAR, DATE),
			value = sum((sd.looseqty) *
				sd.saleprice * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01))
		FROM 
			saleledger sl, saleinvdetail sd, @TAB_ItemList I
		WHERE 
			sl.impactinventory = 'N' AND
			sl.posted = 'Y' AND sl.saleinvcode = sd.saleinvcode AND
			sl.date >= @ar_startdate and sl.date <= @ar_enddate AND
			sd.icode = I.code
		Group By 
			sd.icode, 
			DATEPART(YEAR, DATE)
		UNION ALL
		select	
			sd.icode,
			Year= DATEPART(YEAR, DATE),
			value = -sum((sd.looseqty + sd.packqty * sd.packunits) *
				sd.srprice * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01))
		FROM 
			srledger sl, srdetail sd, @TAB_ItemList I
		WHERE 
			sl.posted = 'Y' AND sl.srinvcode = sd.srinvcode AND
			sl.date >= @ar_startdate and sl.date <= @ar_enddate AND
			sd.icode = I.code
		Group By 
			sd.icode, 
			DATEPART(YEAR, DATE)) S, 
		(SELECT * FROM Item WHERE ICODE IN (SELECT CODE FROM @TAB_ItemList)) I
	WHERE 
		I.icode = S.icode
	GROUP BY
		S.YEAR,
		S.ICODE,
		I.ICatCode,
		I.ICCode,
		I.ManfCode,
		I.PackCode
	UNION ALL
	SELECT	
		Year=DATEPART(YEAR, @ar_startdate),
		GroupCode=K.Code,
		GroupName=CASE @ReportGrouping 
			WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE = K.Code)
			WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE = K.Code)
			WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE = K.Code)
			ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE = K.CODE) END,   
		ICode=0,
		Value = 0
	FROM (SELECT CODE FROM @Tab_GroupList) K) T
GROUP BY
	T.YEAR,
	T.GroupName,
	T.GroupCode
GO

-- SP_ZONALAREASALES (last defined by script catalog)
CREATE PROCEDURE DBO.SP_ZONALAREASALES @ar_zonecode INT, @ar_startdate datetime, @ar_enddate datetime, @ReportGrouping CHAR(1), @GroupList VARCHAR(8000), @Pricetype TinyInt AS    
/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'reportdata' table to be used for cross tabulation of a
	zone's areas and items selected depending upon the grouping criteria selected.

PARAMETER DESCRIPTION :
	@ar_zonecode = Zone for which report is required
	@ar_startdate, @ar_enddate = Determine the period of report
	@ReportGrouping = The criteria for grouping the items in report
	@GroupList = A comma separated list of values to be filtered while grouping the record set
	@Pricetype = 1 stands for Actual Price, 2 stands for Sale/Trade Price, 3 stands for Purchase price and 4 stands for Average price
*/
DELETE ReportData    

DECLARE @Tab_GroupList TABLE (CODE INT NOT NULL)
DECLARE @Tab_ItemList TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_GroupList SELECT CODE FROM udf_StringToTabl(@GroupList, ',')
INSERT INTO @Tab_ItemList SELECT CODE FROM udf_selectitems(@ReportGrouping, @GroupList)

INSERT INTO ReportData (code1, code2, code3, code4, name1, name2, name3, name4, name5, name6, name7, name8, value1, value2)  
SELECT  Code1=S.ICODE,   
	Code2=S.AREACODE,    
	Code3=S.ZONECODE,    
	Code4=CASE @ReportGrouping 
		WHEN 'M' THEN I.MANFCODE
		WHEN 'C' THEN I.ICatCode
		WHEN 'L' THEN I.ICCode
		ELSE I.PACKCODE END,
	Name1=I.NAME,   
	Name2=(SELECT AREA.SHORTNAME FROM AREA WHERE AREACODE = S.AREACODE),   
	Name3=(SELECT NAME FROM ZONE WHERE ZONECODE = S.ZONECODE),   
	Name4=CASE @ReportGrouping 
		WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE  = I.ManfCode)
		WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE  = I.ICatCode)
		WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE  = I.ICCode)
		ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE  = I.PACKCODE) END,   
	Name5=I.CUSTOMICODE,   
	Name6=I.PackingDesc,
	Name7=(SELECT AREA.SHORTNAME FROM AREA WHERE AREACODE = S.AREACODE),
	Name8=RTRIM(LTRIM(STR(S.ICODE))), 
	Value1= SUM(S.QTY),   
	Value2 = ROUND(SUM(
		CASE @Pricetype WHEN 1 THEN S.NETAMT 
		WHEN 2 THEN S.QTY * ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
		WHEN 3 THEN S.QTY * ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
		ELSE S.QTY * ROUND(I.AVGPRICE, 2) END), 0)
FROM    
	(SELECT INVNO=-1,
		ICODE=I.ICODE,
		CUSTCODE=-1,
		QTY = 0,
		NETAMT=0,
		A.AREACODE,
		A.ZONECODE
	FROM
		(SELECT AREACODE, ZONECODE FROM ZONEAREAS WHERE ZONECODE = @ar_zonecode) A,
		(SELECT ICODE=MIN(CODE) FROM @Tab_ItemList) I
	UNION ALL
	SELECT INVNO=-1,
		ICODE=I.ICODE,
		CUSTCODE=-1,
		QTY = 0,
		NETAMT=0,
		A.AREACODE,
		A.ZONECODE
	FROM
		(SELECT AREACODE=MIN(AREACODE), ZONECODE=MIN(ZONECODE) FROM ZONEAREAS WHERE ZONECODE = @ar_zonecode) A,
		(SELECT ICODE=CODE FROM @Tab_ItemList) I
	UNION ALL
	SELECT INVNO=SL.SALEINVCODE,
		SD.ICODE,
		CUSTCODE=SL.CUSTCODE,
		QTY = ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		NETAMT=Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
				(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2),
		C.AREACODE,
		A.ZONECODE
	FROM
		SALELEDGER SL,
		SALEDETAIL SD,
		CUSTOMER C,
		(SELECT AREACODE, ZONECODE FROM ZONEAREAS WHERE ZONECODE = @ar_zonecode) A
	WHERE
		A.AREACODE = C.AREACODE AND
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
	GROUP BY
		SL.SaleInvCode,
		SD.ICODE,
		SL.CustCode,
		A.ZONECODE,
		C.AREACODE,
		SL.DiscPerc
	UNION ALL
	SELECT INVNO=SL.SRINVCODE,
		SD.ICODE,
		CUSTCODE=SL.CUSTCODE,
		QTY = - ISNULL(Sum(SD.looseqty + SD.bonusqty), 0),
		NETAMT= - Round(ISNULL(SUM((SD.looseqty * SD.SRPrice) *
				(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2),
		C.AREACODE,
		A.ZONECODE
	FROM
		SRLEDGER SL,
		SRDETAIL SD,
		CUSTOMER C,
		(SELECT AREACODE, ZONECODE FROM ZONEAREAS WHERE ZONECODE = @ar_zonecode) A
	WHERE
		A.AREACODE = C.AREACODE AND
		C.CUSTCODE = SL.CUSTCODE AND
		SL.POSTED='Y' AND SL.SRINVCODE = SD.SRINVCODE AND
		SL.DATE >= @ar_startdate AND SL.DATE <= @ar_enddate
	GROUP BY
		SL.SRInvCode,
		SD.ICODE,
		SL.CustCode,
		A.ZONECODE,
		C.AREACODE,
		SL.DiscPerc) S,
	(SELECT * FROM ITEM WHERE ICODE IN (SELECT CODE FROM @Tab_ItemList)) I
WHERE
	I.ICode = S.ICode
GROUP BY
	S.ICODE,
	S.ZONECODE,
	S.AREACODE,
	I.Name,
	I.CustomICode,
	I.PackingDesc,
	I.ICatCode,
	I.ICCode,
	I.ManfCode,
	I.PackCode
GO

-- SP_ZONALAREASALES_CROSSTAB (last defined by script catalog)
CREATE   PROCEDURE SP_ZONALAREASALES_CROSSTAB 
	@Zonecode INT, @startdate datetime, 
	@enddate datetime, @ReportGrouping CHAR(1), 
	@GroupList VARCHAR(8000), @Pricetype TinyInt, 
	@TotCol Float, @ColCaption SMALLINT,
	@MergeBonus TINYINT AS

/*
Author :
	M. Azhar Inayat
Purpose:
	To create a resultset in 'crosstab_reportdata' table to be used for cross tabulation of a
	zone's areas and items selected depending upon the grouping criteria selected.

PARAMETER DESCRIPTION :
	@zoneCode = Zone for which report is required
	@startdate, @ar_enddate = Determine the period of report
	@ReportGrouping = The criteria for grouping the items in report
	@GroupList = A comma separated list of values to be filtered while grouping the record set
	@Pricetype = 1 stands for Actual Price, 2 stands for Sale/Trade Price, 3 stands for Purchase price and 4 stands for Average price
	@TotCol = the number of cross tab clolumns for the report (area shortname columns)
	@MergeBonus = Bonus qty should be merged into sale qty or not (1 = Yes, 0 = No)
*/

DELETE CrossTab_ReportData

SET NOCOUNT ON

DECLARE @coltable TABLE (code int, shortname varchar(100), rowid INT identity(1,1))
DECLARE @UPD VARCHAR(4000), @Col VARCHAR(10), @RowID INT, @colname VARCHAR(100), @colcode VARCHAR(100), @str_col VARCHAR(10)
DECLARE @totareas FLOAT, @curriter int, @iterations int, @i int, @tot int
DECLARE @ICODE INTEGER, @AREACODE INTEGER, @QTY NUMERIC(15,4), @Bonus NUMERIC(15,4), @VAL NUMERIC(15, 5), @err INT
SELECT @totareas = ISNULL((SELECT Count(Area.AreaCode) FROM ZONEAREAS Z,Area WHERE Z.ZONECODE=@zoneCode AND Z.AreaCode = Area.AreaCode), 0)

DECLARE @Tab_GroupList TABLE (CODE INT NOT NULL)
DECLARE @Tab_ItemList TABLE (CODE INT NOT NULL)

INSERT INTO @Tab_GroupList SELECT CODE FROM udf_StringToTabl(@GroupList, ',')
INSERT INTO @Tab_ItemList SELECT CODE FROM udf_selectitems(@ReportGrouping, @GroupList)

IF @totareas > 0 and @TotCol > 0
BEGIN

	SELECT @tot = (SELECT MIN(A) FROM (SELECT A=@TotCol UNION SELECT A=@TotAreas) T)

	INSERT @coltable (Code, ShortName)
	SELECT Area.AreaCode, Name=CASE WHEN @ColCaption = 1 THEN Area.ShortName ELSE Area.Name END
	FROM ZONEAREAS Z,Area 
	WHERE Z.ZONECODE=@zoneCode AND Z.AreaCode = Area.AreaCode
	ORDER BY AREA.ShortName

	SET @iterations = CEILING(@totareas/@TotCol)
	SET @curriter = 1
	SET @RowID = 0
	WHILE @curriter <= @iterations
	BEGIN
		
		INSERT INTO CrossTab_ReportData (Code1, Code2, Code3)
		SELECT Code, @curriter, @zoneCode FROM @Tab_ItemList

		SET @i = 1
		WHILE @i <= @tot
		BEGIN
			SET @RowID = @RowID + 1
			SELECT @colname = RTRIM(LTRIM(ISNULL((SELECT shortname FROM @coltable WHERE ROWID = @RowID), '')))
			SELECT @colcode = RTRIM(LTRIM(STR((SELECT CODE FROM @coltable WHERE ROWID = @RowID), 7)))
			IF @colcode IS NULL
			BEGIN
				BREAK
			END
			ELSE
			BEGIN
				SET @str_col = LTRIM(RTRIM(STR(@i, 7)))
				SELECT @UPD = 	'UPDATE CrossTab_ReportData SET C_Name' + @str_col + 
								' = ''' + @colname + ''', C_Code' + @str_col + ' = ' + @colcode +
								' WHERE CODE2 = ' + LTRIM(RTRIM(STR(@curriter, 7)))
				EXECUTE (@UPD)
				SET @err = @@ERROR
				IF @err <> 0
				BEGIN
					SET @UPD = 'UPDATION ERROR, DETAILS: ' + @UPD
					RAISERROR(@UPD, 16, 1, @UPD)
					RETURN -1
				END 
				SET @i = @i + 1
			END
		END
		SET @curriter = @curriter + 1
	END

	DECLARE C1 CURSOR FOR
	SELECT S.ICODE, QTY = ISNULL(Sum(S.QTY), 0), Bonus = ISNULL(Sum(S.Bonus), 0),
		VAL= ROUND(SUM(
			CASE @Pricetype WHEN 1 THEN S.NETAMT 
			WHEN 2 THEN S.QTY * ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			WHEN 3 THEN S.QTY * ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			ELSE S.QTY * ROUND(I.AVGPRICE, 2) END), 0), 
		S.AREACODE
	FROM
		(SELECT INVNO=SL.SALEINVCODE,
			SD.ICODE,
			CUSTCODE=SL.CUSTCODE,
			QTY = ISNULL(Sum(SD.looseqty + CASE WHEN @MergeBonus = 1 THEN SD.bonusqty ELSE 0 END), 0),
			Bonus = ISNULL(Sum(CASE WHEN @MergeBonus = 1 THEN 0 ELSE SD.bonusqty END), 0),
			NETAMT=Round(ISNULL(SUM((SD.looseqty*(SD.saleprice - SD.itemflatdisc)) *
					(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2),
			C.AREACODE
		FROM
			SALELEDGER SL,
			SALEDETAIL SD,
			CUSTOMER C,
			(SELECT AREACODE, ZONECODE FROM ZONEAREAS WHERE ZONECODE = @zonecode) A
		WHERE
			A.AREACODE = C.AREACODE AND
			C.CUSTCODE = SL.CUSTCODE AND
			SL.POSTED='Y' AND SL.SALEINVCODE = SD.SALEINVCODE AND
			SL.DATE >= @StartDate AND SL.DATE <= @EndDate
		GROUP BY
			SL.SaleInvCode,
			SD.ICODE,
			SL.CustCode,
			C.AREACODE,
			SL.DiscPerc
		UNION ALL
		SELECT INVNO=SL.SRINVCODE,
			SD.ICODE,
			CUSTCODE=SL.CUSTCODE,
			QTY = - ISNULL(Sum(SD.looseqty + CASE WHEN @MergeBonus = 1 THEN SD.bonusqty ELSE 0 END), 0),
			Bonus = - ISNULL(Sum(CASE WHEN @MergeBonus = 1 THEN 0 ELSE SD.bonusqty END), 0),
			NETAMT= - Round(ISNULL(SUM((SD.looseqty * SD.SRPrice) *
					(1 - (.01 * SD.discperc))) * (1- (.01 * SL.discperc)), 0), 2),
			C.AREACODE
		FROM
			SRLEDGER SL,
			SRDETAIL SD,
			CUSTOMER C,
			(SELECT AREACODE, ZONECODE FROM ZONEAREAS WHERE ZONECODE = @zonecode) A
		WHERE
			A.AREACODE = C.AREACODE AND
			C.CUSTCODE = SL.CUSTCODE AND
			SL.POSTED='Y' AND SL.SRINVCODE = SD.SRINVCODE AND
			SL.DATE >= @StartDate AND SL.DATE <= @EndDate
		GROUP BY
			SL.SRInvCode,
			SD.ICODE,
			SL.CustCode,
			C.AREACODE,
			SL.DiscPerc) S, ITEM I
	WHERE I.ICODE = S.ICODE AND I.ICODE IN (SELECT CODE FROM @Tab_ItemList)
	GROUP BY 
		S.AREACODE,
		S.ICODE
	ORDER BY S.AREACODE, S.ICODE

	OPEN C1
	FETCH NEXT FROM C1 INTO @ICODE, @QTY, @Bonus, @VAL, @AREACODE
	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @i = 1
		WHILE @i <= @tot
		BEGIN
			SELECT @colcode = LTRIM(RTRIM(STR(@ICODE, 7)))
			SELECT @colname = LTRIM(RTRIM(STR(@AREACODE, 7)))
			SET @str_col = LTRIM(RTRIM(STR(@i, 7)))

			SELECT @UPD = 	'UPDATE CrossTab_ReportData SET ' + 
							'QTY' + @str_col + ' = ' + LTRIM(RTRIM(STR(@QTY, 7))) + 
							', Value' + @str_col + ' = ' + LTRIM(RTRIM(STR(@Bonus, 15,4))) + 
							', VAL' + @str_col + ' = ' + LTRIM(RTRIM(STR(@VAL, 15, 5))) + 
							', C_Code' + @str_col + ' = ' + @colname +
							' WHERE CODE1 = ' + @colcode + ' AND ' + 
							' C_Code' + @str_col + ' = ' + @colname
			EXECUTE (@UPD)
			SET @err = @@ERROR
			IF @err <> 0
			BEGIN
				SET @UPD = 'CROSSTAB PLOTING ERROR, DETAILS: ' + @UPD
				RAISERROR(@UPD, 16, 1, @UPD)
				CLOSE C1
				DEALLOCATE C1
				RETURN -1
			END 
			SET @i = @i + 1
		END

		FETCH NEXT FROM C1 INTO @ICODE, @QTY, @Bonus, @VAL, @AREACODE
	END
	CLOSE C1
	DEALLOCATE C1

	UPDATE CrossTab_ReportData 
	SET NAME1 = I.NAME,
		NAME2 = I.CustomICode,
		Name3 = I.PackingDesc,
		Name4 = (SELECT NAME FROM ZONE WHERE ZONECODE = @ZONECODE),   
		Code5=CASE @ReportGrouping 
			WHEN 'M' THEN I.MANFCODE
			WHEN 'C' THEN I.ICatCode
			WHEN 'L' THEN I.ICCode
			ELSE I.PACKCODE END,
		Name5 = CASE @ReportGrouping 
			WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE  = I.ManfCode)
			WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE  = I.ICatCode)
			WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE  = I.ICCode)
			ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE  = I.PACKCODE) END,
		Value14= CASE @Pricetype WHEN 1 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2)
			ELSE ROUND(I.AVGPRICE, 2) END
	FROM ITEM I, CrossTab_ReportData C
	WHERE I.ICODE = C.CODE1

	EXECUTE SP_UPDATE_TOTAL_CrossTab_ReportData2
END
RETURN 0
GO

-- Update_ItemBatchPrices (last defined by script catalog)
CREATE  PROCEDURE DBO.Update_ItemBatchPrices
AS
INSERT INTO ItemBatchPricing (ICode, Batch, Expiry, SalePrice, ArrivedOn, UserCode, LastModified, LastModifiedBy)
SELECT 
	ICode=GD.ICode, 
	Batch=GD.Batch, 
	Expiry=GD.Expiry,
	SalePrice = CASE WHEN ISNULL((SELECT MAX(IBP.SalePrice) FROM PurDetail IBP WHERE IBP.ICode=GD.Icode AND IBP.Batch = GD.Batch AND IBP.Expiry = GD.Expiry), 0) = 0 THEN (SELECT I.SalePrice FROM Item I WHERE I.ICode=GD.ICode) ELSE (SELECT MAX(IBP.SalePrice) FROM PurDetail IBP WHERE IBP.ICode=GD.Icode AND IBP.Batch = GD.Batch AND IBP.Expiry = GD.Expiry) END,
	ArrivedOn = GETDATE(),
	UserCode=1,
	LastModified=NULL, 
	LastModifiedBy=NULL
FROM GodownDetail GD, Item I
WHERE GD.ICode = I.ICode AND
	STR(GD.ICode, 10) + GD.Batch + convert(varchar(100), GD.Expiry, 121) NOT IN
		(SELECT DISTINCT STR(IBP.ICode, 10) + IBP.Batch + convert(varchar(100), IBP.Expiry, 121)
		FROM ItemBatchPricing IBP) 
GROUP BY
	GD.ICode, 
	GD.Batch, 
	GD.Expiry
ORDER BY
	ICode, 
	Batch, 
	Expiry
RETURN 0
GO
